int n, l, t;

void solve() {
    ll c = 0;
    for (int i=0; i<n; ++i) {
        int dir = d[i] == 2 ? -1 : 1;
        ll pos = (ll)x[i] + dir * t;
        c += (pos > 0 ? pos/l : (pos-l+1)/l);
        ex[i] = (pos%l+l) % l;
    }
    c = (c%n+n) % n;
    sort(sx, sx+n);
    sort(ex, ex+n);
    for (int i=0; i<n; ++i) {
        ans[sx[i].second] = ex[(i+c)%n];
    }
    for (int i=0; i<n; ++i) {
        printf("%d\n", ans[i]);
    }
}

