			else
				delta = (2 * t - len + l - 1) / l;

			if (dir[i] == 1)
				ind += delta;
			else
				ind -= delta;

			ind = (ind % n + n) % n;
		}

		ll val = arr[i];

		if (dir[i] == 1)
			val += t;
		else
			val -= t;
		val = (val % l + l) % l;
		//cout << val << ' ' << ind << '\n';
		must_know.push_back({ind, val});
	}

	for (int i = 0; i < n; i++)
	{
		ll val = arr[i];
		if (dir[i] == 1)
			val += t;
		else
			val -= t;
		val = (val % l + l) % l;
		res.push_back(val);
	}

	sort(res.begin(), res.end());
	res.resize(2 * n);

	for (int i = 0; i < n; i++)
		res[n + i] = res[i];

	for (int i = 0; i < n; i++)
	{
		bool ok = true;
		for (auto it : must_know)
		{
			ok &= res[i + it.first] == it.second;
		}

		if (ok)
		{
			for (int j = 0; j < n; j++)
			{
				cout << res[i + j] << '\n';
			}
			return 0;
		}
	}

	assert(false);

	return 0;
}

