  for (int i = 0; i < n; i++)
    cin >> x[i] >> w[i];

  for (int i = 0; i < n; i++){
    if (w[i] == 1){
      m[i] = (x[i] + t) % l;
    }else{
      m[i] = (x[i] - t) % l;
      if (m[i] < 0)
        m[i] += l;
    }
  }

  // for(auto a: m) cout << a << endl;

  int ms = t / l, md = t % l;
  map<int, int> p;

  for (int cur = 0; cur <= 1; cur++){
    int num = cur, point = m[cur];
    for (int i = 0; i < n; i++){
      if (w[cur] == w[i])
        continue;
      int d;
      if (w[cur] == 1){
        if(x[i] > x[cur]){
          d = (x[i] - x[cur]);
        }else{
          d = l - (x[cur] - x[i]);
        }
        num += ms + (2*md >= d?1:0);
      }else{
        if(x[i] > x[cur]){
          d = l - (x[i] - x[cur]);
        }else{
          d = x[cur] - x[i];
        }
        num -= ms + (2*md >= d?1:0);
      }
