		sum[0][i]=sum[0][max((i-1),0)];
		sum[1][i]=sum[1][max((i-1),0)];
		W[i]--;
		sum[W[i]][i]++;
	}
	for(int i=N;i<2*N;i++)
	{
		pos[i]=X[i%N]+L;
		sum[0][i]=sum[0][i-1];
		sum[1][i]=sum[1][i-1];
		sum[W[i%N]][i]++;
	}
	int cnt[2]={};
	T*=2;
	cnt[0]=T/L*sum[0][N-1];
	cnt[1]=T/L*sum[1][N-1];
	T%=L;
	for(int i=0;i<N;i++)
	{
		if(W[i]==1)
			continue;
		int p=upper_bound(pos,pos+2*N,pos[i]+T)-pos;
		p--;
		int cntn=cnt[1]+sum[1][p]-sum[1][i];
		ans[(i+cntn)%N]=(pos[i]+T1)%L;
	}
	for(int i=N;i<2*N;i++)
	{
		if(W[i%N]==0)
			continue;
		int p=lower_bound(pos,pos+2*N,pos[i]-T)-pos;
