		else
			cntn=cnt[0]+sum[0][i-1];
		ans[(i-cntn)%N]=((pos[i]-T1)%L+L)%L;
	}
	for(int i=0;i<N;i++)
		printf("%d\n",ans[i]);
	return 0;
}

