#include <iostream>
#include <algorithm>

int len;
int pos[100000];
bool dir[100000];
int next_pos[100000];
bool next_dir[100000];
int work_d;

void move(int id){
    if(dir[id]) next_pos[id] = (pos[id] + 1) % len;
    else if (pos[id] > 0) next_pos[id] = pos[id] - 1;
    else next_pos[id] = len - 1;
    next_dir[id] = dir[id];
}
void multiple_move(int m, int id){
    if(dir[id]) pos[id] = (pos[id] + (m -1)) % len;
    else if (pos[id] > 0) pos[id] = pos[id] - (m - 1);
    else pos[id] = len - (m - 1);
    move(id);
}
void invert (int id){
    if(dir[id]) dir[id] = false;
    else dir[id] = true;
}
void invert_stay (int id){
    if(dir[id]) next_dir[id] = false;
    else next_dir[id] = true;
    next_pos[id] = pos[id];
}
int dist (int p, int id){
    int ret = pos[id] - p;
    if(ret < 0) ret = len + ret;
    return ret;
}
bool collide (bool d, int p, int id){
    work_d = dist(p, id);
    if(work_d != 1 && work_d != len - 1) return false;
    if ((d == true && dir[id] == false && dist(p, id) == 1) || (d == false && dir[id] == true && dist(p, id) == len - 1)) return true;
    else return false;
}
void update(int id){
    pos[id] = next_pos[id];
    dir[id] = next_dir[id];
}

int main(int argc, const char * argv[]) {
    int N, L, T, iiid, interval, min_interval;
    std::cin >> N >> L >> T;
    len = L;

    min_interval = 0;
    for(int id = 0; id < N; id++){
        int this_pos, dir_id;
        bool this_dir = true;
        std::cin >> this_pos >> dir_id;
        if(dir_id == 2) this_dir = false;
        pos[id] = this_pos;
        dir[id] = this_dir;
    }
    // clock tick loop
    for(int clock = 0; clock < T; clock++){

        if(min_interval / 2 - 1 > 1){
            clock += (min_interval / 2 - 1);
            for(int id = 0; id < N; id++){
                multiple_move(min_interval / 2 - 1, id);
            }
            continue;
        }

        for(int id = 0; id < N; id++){
            bool collide_flag = false;
            for(int iid = id-1; iid <= id+1; iid++){
                iiid = iid;
                if(iid < 0) iiid = N + iid;
                else if (iid >= N) iiid = iid % N;
                if(id == iiid) continue;
                if(pos[iiid] == pos[id]) {
                    invert(id);
                }
                if(collide(dir[iiid], pos[iiid], id)){
                    collide_flag = true;
                    invert_stay(id);
                }
            }
            if(!collide_flag) {
                move(id);
            }
        }
        update(0);
        interval = dist(pos[N-1],0);
        min_interval = interval;
        for(int id = 1; id < N; id++){
            update(id);
            interval = dist(pos[id - 1], id);
            if (min_interval > interval) min_interval = interval;
        }
    }
    for(int id = 0; id < N; id++){
        std::cout << pos[id] << std::endl;
    }
    return 0;
}

