bool intersects(ll a, ll b, ll c, ll d) {
	if (b > l) {
		a -= l;
		b -= l;
	}
	if (d > l) {
		c -= l;
		d -= l;
	}

	bool res = false;
	res |= (max(a, c) <= min(b, d));

	if (a < 0 && c > 0) {
		c -= l;
		d -= l;
	}
	else if (a > 0 && c < 0) {
		a -= l;
		b -= l;
	}
	res |= (max(a, c) <= min(b, d));
	return res;
}

void calcPos() {
	if (w[0] == 1) {
		for (int i = 1; i < n; i++) {
