    cin >> n >> l >> t;

    int x[n], w[n];
    for (int i = 0; i < n; i++) {
        cin >> x[i] >> w[i];
    }

    int pos;
    if (w[0] == 1) {
        pos = (x[0] + t) % l;
    } else {
        pos = (x[0] - t % l + l) % l;
    }

    int idx = 0;
    for (int i = 1; i < n; i++) {
        if (w[0] == 1 && w[i] == 2) {
            int cnt = t / l * 2;
            if (t%l > (x[i] - x[0]) / 2) cnt++;
            if (t%l > x[i] + (l + x[0] - x[i]) / 2) cnt++;
            idx = (idx + cnt) % n;
        } else if (w[0] == 2 && w[i] == 1) {
            int cnt = t / l * 2;
            if (t%l > x[i] + (x[i] - x[0]) / 2) cnt++;
            if (t%l > (l + x[0] - x[i]) / 2) cnt++;
            idx = (idx - cnt % n + n) % n;
        }
    }

    vector <int> vec(n);
    for (int i = 0; i < n; i++) {
        if (w[i] == 1) {
            vec[i] = (x[i] + t) % l;
        } else {
            vec[i] = (x[i] - t % l + l) % l;
        }
    }

    sort(vec.begin(), vec.end());

    int start = 0;
    if (w[0] == 1) {
        for (int i = 0; i < n; i++) {
            if (vec[i] == pos) {
                start = (i - idx + n) % n;
                break;
            }
        }
    } else {
        for (int i = n-1; i >= 0; i--) {
            if (vec[i] == pos) {
                start = (i - idx + n) % n;
                break;
            }
        }
    }

    for (int i = 0; i < n; i++) {
        cout << vec[(start + i) % n] << '\n';
    }

    return 0;
}

