    cin >> n >> l >> t;
    rep(i, n) {
        cin >> x[i] >> w[i];
    }

    //一番目のありが最後は何番目のありになっているか算出
    int count = 0, last = 0;
    if (w[0] == 1) {
        for (int i = 1; i < n; ++i) {
            if (w[i] == 2) {
                count += 1 + (2 * t + x[0] - x[i]) / l;
            }
        }
        last = count % n;
    } else {
        for (int i = 1; i < n; ++i) {
            if (w[i] == 1) {
                count += (2 * t + x[i] - x[0]) / l;
            }
        }
        if (count % n == 0) {
            last = 0;
        } else {
            last = n - count % n;
        }
    }


    //ありの最後の位置を区別しないで求める
    rep(i, n) {
        if (w[i] == 1) {
            x[i] = (x[i] + t) % l;
        } else {
            if (t-x[i] > 0) x[i] = l - (t - x[i]) % l;
            else x[i] = x[i] - t;
        }
    }

    int last0 = x[0];

    sort(x, x + n);

    int pos;
    for (pos = 0; pos < n; ++pos) {
        if (x[pos] == last0) break;
    }


    //答えを出力
    if (pos > last) {
        reps(i, pos-last, n) {
            cout << x[i] << endl;
        }
        reps(i, 0, pos-last) {
