const int N = 200 * 1000 + 228;
const int INF = 1e13 + 228;

int n, l, t;
int x[N], w[N], fx[N], meet[N], pref[N][3], ans[N];

int dist(int i, int j) {
    int crd = x[(j - 1) % n + 1];
    crd += l * ((j - 1) / n);
    return crd - x[i];
}
int summa(int i, int j, int T) {
    if (j <= n) return pref[j][T]-pref[i][T];
    int res = pref[n][T] - pref[i][T];
    res += pref[(j - 1) % n + 1][T];
    res += max(0LL, ((j - 1) / n - 1)) * pref[n][T];
    return res;
}

signed main() {
    ios_base::sync_with_stdio(false);
    cin.tie(0);
    cin >> n >> l >> t;
    int left = 0, right = 0;
    for (int i = 1; i <= n; ++i) {
        cin >> x[i] >> w[i];
        if (w[i] == 1) {
            fx[i] = (x[i] + t) % l;
            ++left;
        } else {
            fx[i] = ((x[i] - t) % l + l) % l;
            ++right;
        }
    }
    for (int i = 1; i <= n; ++i) {
        x[n + i] = x[i] + l;
        w[n + i] = w[i];
    }
    for (int i = 1; i <= 2 * n; ++i) {
        for (int j = 1; j <= 2; ++j) {
            pref[i][j] = pref[i - 1][j] + (w[i] == j);
        }
    }
    for (int i = 1; i <= n; ++i) {
        int l = i, r = INF;
        while (r - l > 1) {
            int m = (l + r) >> 1;
            if (dist(i, m) <= t * 2) l = m;
            else r = m;
        }
        meet[i] = summa(i, l, 3 - w[i]);
        if (w[i] == 1) {
            ans[(i - 1 + meet[i]) % n + 1] = fx[i];
        } else {
            ans[((i - 1 - meet[i]) % n + n) % n + 1] = fx[i];
        }
    }
    for (int i = 1; i <= n; ++i) {
        cout << ans[i] << '\n';
    }
    return 0;
}

