typedef long long LL;

LL N, L, T;
LL p[100005], d[100005], f[100005], r[100005], aux[100005];

LL getIntersections(LL x, LL y)
{
	if(x > y) y += L;
	if(2 * T <= y - x)  return 0;
	LL t = 2 * T - (y - x);
	LL cnt = t / L + 1;
	if(t % L == 0)  cnt--;
	return cnt;
}

int main()
{
    #ifdef FILE_IO
    freopen("1.in", "r", stdin);
    freopen("1.out", "w", stdout);
    #endif

    scanf("%lld%lld%lld", &N, &L, &T);
    for(LL i = 0; i < N; i++)
    {
        scanf("%lld%lld", &p[i], &d[i]);
        if(d[i] == 2)   d[i] = -1;
    }

    LL add = T % L;
    for(LL i = 0; i < N; i++)
    {
        if(d[i] == 1)   f[i] = (p[i] + add) % L;
        else            f[i] = (p[i] - add + L) % L;
    }
    sort(f, f + N);
    LL pos0 = p[0];
    if(d[0] == 1)   pos0 = (p[0] + add) % L;
    else            pos0 = (p[0] - add + L) % L;

    for(LL i = 0; i < N; i++)  aux[i] = f[i];
    for(LL i = 0; i < N; i++)
        if(pos0 == f[i])
        {
            if(f[i] == f[i + 1] && d[0] == -1)   i++;
            for(LL j = 0; j < N; j++)
                f[j] = aux[(j + i) % N];
            break;
        }

    LL id = 0;
    for(LL i = 1; i < N; i++)
        if(d[i] != d[0])
        {
            LL cnt = 0;
            if(d[0] == 1)   cnt = getIntersections(p[0], p[i]);
            else            cnt = getIntersections(p[i], p[0]);
            if(d[0] == 1) (id += cnt) %= N;
            else (id += N - (cnt % N) ) %= N;
        }

    for(LL i = 0; i < N; i++)
        r[(id + i) % N] = f[i];

    for(LL i = 0; i < N; i++)
        printf("%lld\n", r[i]);

    return 0;
}

