int L, T;
int main(void){
	cin >> N >> L >> T;
	int x[114514];
	int w[114514];
	vector<int> pos;
	REP(i, N){
		cin >> x[i];
		cin >> w[i];
		if(w[i] == 1){
			pos.push_back((x[i]+T)%L);
		}else{
			int p = x[i]-T;
			if(p >= 0) pos.push_back(p);
			else pos.push_back(L-(-p%L));
		}
	}
	int cross = 0;
	FOR(i, 1, N){
		if(w[i] != w[0]){
			if(w[0] == 1){
				if(x[i]-x[0] <= 2*T){
					cross++;
					cross += (T-x[i]+x[0])/L*2;
				}
			}else{
				if(x[0]+L-x[i] <= 2*T){
					cross--;
					cross -= max(0, (T-x[0]+L-x[i]))/L*2;
				}
			}
		}
	}
	int cp = pos[0];
	sort(all(pos));
	while(cross < 0) cross += N;
	cross %= N;
	int in = 0;
	while(pos[in] != cp) in++;
	REP(i, cross){
		in = (in-1+N)%N;
	}
	REP(i, N){
		cout << pos[(in+i)%N] << endl;
	}
}

