int f(LL T)
{
	if(ps[0].size()==0||ps[1].size()==0){
		return 0;
	}
	int f=0;
	int a=0;
	int b;
	if(W[0]==0){
		b=0;
	}
	else
	{
		f=1;
		b=ps[0].size()-1;
	}
	LL c=0;
	int sg[2]={1,-1};
	while(c<T){
		LL p=sg[f]*c+X[ps[f][a]];
		LL q=sg[f^1]*c+X[ps[f^1][b]];
		p%=L;
		if(p<0){
			p+=L;
		}
		q%=L;
		if(q<0){
			q+=L;
		}
		if(f==0&&q<=p){
			q+=L;
		}
		else if(f==1&&p<=q){
			p+=L;
		}
		if(abs(p-q)/2+c<T){
			c+=abs(p-q)/2;
			int t=(ps[f].size()+sg[f^1]+a)%ps[f].size();
			a=b;
			b=t;
			f^=1;
		}
		else{
			break;
		}
	}
	return ps[f][a];
}
