struct Solver {
  long n, l, t;
  std::vector<std::array<long, 2>> xs;
  Solver() {
    S002 reader;
    reader >= n >= l >= t >n>= xs;
  }
  void solve() {
    std::vector<long> coords;
    long p = -1;
    for(long i = 0; i < n; ++i) {
      auto x = xs[i];
      long next = -1;
      if( x[1] == 1 ) {
        next = (x[0] + t) % l;
      }
      else if( x[1] == 2 ) {
        next = (x[0] - t + l * 1000000000) % l;
      }
      coords.push_back(next);
      if( i == 0 ) p = next;
    }
    std::sort(coords.begin(), coords.end());
    long roundC = 0;
    for(auto x : xs) {
      if( xs[0][1] != x[1] ) roundC += 1;
    }
    long diff = 2 * t / l * roundC;
    for(long i = 1; i < n; ++i) {
      if( xs[0][1] != xs[i][1] ) {
        if( xs[i][1] == 1 ) {
          if( (xs[0][0] - xs[i][0] + 3 * l) % l <= 2 * t ) diff += 1;
        }
        if( xs[i][1] == 2 ) {
          if( (xs[i][0] - xs[0][0] + 3 * l) % l <= 2 * t ) diff += 1;
        }
      }
    }
    long diff2 = xs[0][1] == 1 ? diff % n : -(diff % n);
    long diff3 = -1;
    for(long i = 0; i < n; ++i) {
      if( coords[i] == p ) {
        diff3 = i;
        break;
      }
    }
    dumpll(diff2, diff3);
    for(long i = 0; i < n; ++i) {
      printf("%ld\n", coords[(i+diff3-diff2+3*l) % n]);
    }
  }    
  ~Solver() { fprintf(stderr, "--end--\n"); }
};


int main() {
  loop std::unique_ptr<Solver>(new Solver())->solve();
  return 0;
}

