	// 負 -> 正: 最初のインデックスが1減る
	// 正 -> 負: 最初のインデックスが1増える
	rep(i, N) {
		if (W[i] == 1) {
			count -= (T - (L - X[i]) + L) / L;
		}
		else {
			count += (T - (X[i] + 1) + L) / L;
		}
	}

	count = (count % N + N) % N;
	vector<int> res(N);
	rep(i, N) {
		res[(i + count) % N] = tmp[i];
	}

	for (int i : res) {
		cout << i << "\n";
	}

	return 0;

}

