int go(int id, int t2)
{
	queue < int > w1, w2;
	for (int i = 0; i < n; i++)
	{
		if (dir[(id + i) % n] == 2)
			w2.push(pos[(id + i) % n]);
	}                  
	for (int i = 0; i < n; i++)
	{
		if (dir[(id - i + n) % n] == 1)
			w1.push(pos[(id - i + n) % n]);	
	}
	int t1 = 0, d = dir[id], x = pos[id];
	while(t1 < t2)
	{
		if (d == 1)
		{
			if (w2.empty())
			{	
				x = (x + t2 - t1) % L;
				break;
			}  
			int y = (w2.front() - t1 + L) % L;
			int t3 = (y - x + 1) / 2;
			if (x > y)
				t3 = (L - x + y + 1) / 2;
			if (t2 - t1 < t3)
			{
				x = (x + t2 - t1) % L;
				break;
			}
			w2.push(w2.front());
			w2.pop();	
			if (t3 > 0)
			{	
				w1.push(w1.front());
				w1.pop();
				x = (y - t3 + L) % L;
				t1 += t3;
			}
			d = 2;
		}
		else
		{
			if (w1.empty())
			{
				x = (x - t2 + t1 + L) % L;
				break;
			}
			int y = (w1.front() + t1) % L;
			int t3 = (x - y + 1) / 2;
			if (y > x)
			{
				t3 = (L - y + x + 1) / 2;
			}
			if (t2 - t1 < t3)
			{
				x = (x - t2 + t1 + L) % L;
				break;
			}
			w1.push(w1.front());
			w1.pop();	
			if (t3 > 0)
			{
				w2.push(w2.front());
				w2.pop();
				x = (y + t3) % L;
				t1 += t3;
			}
			d = 1;
		}	
	}
	return x;
}

