ll collision_count(int a, int b)
{
    ll res = 0, diff = -1;

    if (W[a] == 1 && W[b] == 2) {
        diff = (X[b] - X[a]);
    } else if (W[a] == 2 && W[b] == 1) {
        diff = L - (X[b] - X[a]);
    }

    // DUMP(diff);
    if (diff >= 0) res = T / L + (diff <= (T % L) * 2);
    // cerr << "collision_count(" << a << ", " << b << ") = " << res << endl;
    return res;
}

