#include <bits/stdc++.h>
#define N 100001
using namespace std;
typedef long long ll;
ll n,Len,T;
ll X[N],W[N],ID[N];

typedef pair<ll,ll> P;
typedef pair<P,P> PP;

ll Dis(int a,int b){
  return (X[a]<X[b])?(X[b]-X[a]):Len - (X[a]-X[b]);
}

void sim(){
  vector<int> L,R;
  for(int i=0;i<n;i++)W[i] == 1? R.push_back(i):L.push_back(i);
  for(int i=0;i<n;i++)L.push_back(L[i]+n),R.push_back(R[i]+n);

  priority_queue<PP,vector<PP>,greater<PP> > Q;
  for(int i=0;i<n;i++){
    if(W[i]==2)continue;
    int idx = *lower_bound(L.begin(),L.end(),i);
    idx%=n;
    ll dis=Dis(i,idx);
    if(idx<(int)L.size())Q.push(PP(P(dis,dis/2.0+0.5),P(i,idx)));
  }

  while(!Q.empty()){
    PP t = Q.top();Q.pop();
    ll sum = t.first.second;
    int a= t.second.first;
    int b= t.second.second;
    if(sum>T)continue;

    swap(ID[a],ID[b]);
    b=(b+1)%L.size();
    ll dis=Dis(a,L[b]%n);
    sum += dis/2.0+0.5;

    Q.push(PP(P(dis,sum+dis),P(a,b)));
  }
}

int main(){

  cin>>n>>Len>>T;
  for(int i=0;i<n;i++)cin>>X[i]>>W[i],ID[i] = i;
  sim();
  vector<int> ans(n);
  for(int i=0;i<n;i++){
    if(W[i]==1)ans[ID[i]]=(X[i]+T)%Len;;
    if(W[i]==2)ans[ID[i]]=(X[i]-T+Len)%Len;
  }
  for(int i=0;i<n;i++)cout<<ans[i]<<endl;
  return 0;
}

