			long long pos0 = (X[0][idx[0]] + forward) % L;
			long long pos1 = (X[1][idx[1]] + L - forward) % L;
			if(pos1 <= pos0) pos1 += L;
			long long nextTime = curTime + (pos1 - pos0)/2;
			if(nextTime > T) break;
			curTime = nextTime;
			if(dir == 0){
				idx[0] = (idx[0] + X[0].size() - 1) % X[0].size();
			} else {
				idx[1] = (idx[1] + 1) % X[1].size(); 
			}
			dir = 1 - dir;
		}
		long long endPos = (X[dir][idx[dir]] + (dir==0 ? T%L : L - T%L)) % L;
		vector<pair<long long, long long>> vp;
		for(auto x : X[0]) vp.emplace_back((x+T%L)%L, 0);
		for(auto x : X[1]) vp.emplace_back((x+L-T%L)%L, 1);
		sort(vp.begin(), vp.end());
		int start = -1;
		for(int i=0;i<vp.size();i++){
			if(vp[i].first == endPos && vp[i].second == dir) start = i;
		}
		for(int i=0;i<vp.size();i++){
			cout << vp[(i+start)%vp.size()].first/2 << endl;
		}
	}
}

