int32_t main()
{
    cout << fixed << setprecision(12);
    cerr << fixed << setprecision(4);
    ios_base::sync_with_stdio(false); cin.tie(0);
    cin >> N >> L >> T;
    pii lol;
    FOR(i, 0, N)
    {
        cin >> arr[i].fi >> arr[i].se;
        if (arr[i].se == 2) arr[i].se = -1;
        int ft = arr[i].fi + arr[i].se * T;
        ft %= L;
        if (ft < 0) ft += L;
        ans[i] = {ft, arr[i].se};
        if (i == 0) lol = ans[i];
    }
    int idx = 0;
    if (arr[0].se == 1)
    {
        FOR(j, 1, N)
        {
            if (arr[j].se == 1) continue;
            //count the # these guys intersect.
            int d = arr[j].fi - arr[0].fi;
            int k = max(0, (2 * T - d + L)) / L;
            idx += k;
            idx %= N;
            // cerr << 2 * T - d + L << '/' << L << endl;
            //d/2, (d+L)/2,....(d+(k-1)L)/2
            //(d + (k-1)L) / 2 <= T -> d+(k-1)L <= 2T => (2T - d + L)/L >= k
        }
        // cerr << idx << " intersectons\n";
        sort(ans, ans + N, cmp);
        FOR(i, 0, N) if (ans[i] == lol) idx = i - idx;
        if (idx < 0) idx += N;
        //the ith is ant #idx
        //so i-idx ant #0
        //val[idx1] corresponds to idx
    }
    else
    {
        FOR(j, 1, N)
        {
            if (arr[j].se == -1) continue;
            int d = arr[0].fi + L - arr[j].fi;
            int k = max(0, (2 * T - d + L)) / L;
            idx += k;
            idx %= N;
        }
        sort(ans, ans + N);
        //the ith is ant #-idx
        //so the i+idx is ant #0
        FOR(i, 0, N) if (ans[i] == lol) idx = i + idx;
        if (idx > N) idx -= N;
    }
    rotate(ans, ans + idx, ans + N);
    FOR(i, 0, N)
    {
        cout << ans[i].fi << '\n';
    }
    return 0;
}

