    vector<ll> X(N);
    vector<int> W(N);
    rep(i,N) cin >> X[i] >> W[i];
    vector<ll> tmp(N); ll count = 0;
    // T秒後の座標だけをもとめる
    rep(i,N){
        ll d = (W[i] == 1) ? (X[i] + T) : (X[i] - T)%L + L;
        d %= L; 
        tmp[i] = d;
    }
