            gap = L - gap;
            if(T >= gap/2){
                count -= 1 + (T*2 - gap) / L;
            }
        }
    }
    //cout << "count = " << count << endl;
    count = count % N;
    if(count < 0) count = N + count;
    // 出力
    rep(i,N){
        cout << tmp[(i + count)%N] << endl;
    }

