        if (antW[i] == 1) {
            ants[i].x = antX[i] + T;
        } else {
            ants[i].x = antX[i] - T;
        }
        if (ants[i].x >= L) {
            ants[i].x = ants[i].x % L;
        } else if (ants[i].x < 0) {
            ants[i].x = (L + ants[i].x) % L;
        }
        ants[i].index = i;
//        cout << "ant" << i << ", x" << ants[i].x << endl;
    }
    // 蟻の位置の配列を昇順でソート
