    for (int j = 1; j < N; ++j) {
        if (antW[0] != antW[j]) {
            double firstTime;
            double diff = antX[0] - antX[j];
            if (diff < 0) {
                diff += L;
            }
            firstTime = diff / 2.0;
            if (firstTime > 0) {
                suretigai += 1;
            }
            suretigai += (int) (2 * (T - firstTime)) / L;
        }
    }
