        zekken = suretigai;
    } else {
        zekken = N - suretigai;
        if (zekken == N) {
            zekken = 0;
        }
        if (zekken < 0) {
            zekken = (N + zekken) % N;
        }
    }
    zekken = zekken % N;
//    cout << "zekken : " << zekken << endl;
    // T秒後にどの番号のゼッケンがどの座標にあるかを算出
    int zekkenX[100000];
    int index = 0;
    for (int i = 0; i < N; ++i) {
        if (ants[i].index == 0) {
            index = i;
            break;
        }
    }
    for (int i = 0; i < N; ++i) {
        // ゼッケン番号を計算
        int z = zekken + i;
        if (z >= N) {
            z -= N;
        }
        //
        int ind = index + i;
        if (ind >= N) {
            ind -= N;
        }
//        cout << z << " " << ind << endl;
        zekkenX[z] = ants[ind].x;
    }


    for (int i = 0; i < N; ++i) {
        cout << zekkenX[i] << endl;
    }
    return 0;
}

