int n,l,t;
LL x[maxn],cl[maxn],ans[maxn];
vector<LL> pos,c,rc;
void ini()
{
	memset(ans,0,sizeof(ans));
	pos.clear();
	c.clear();
	rc.clear();
}
void work()
{
	ini();
	go(i,1,n)
	{
		sff(x[i],cl[i]);
		if(cl[i]==1)pos.pb((x[i]+t)%l),c.pb(i);
		else pos.pb((x[i]-t%l+l)%l),rc.pb(i);
	}
	sort(pos.begin(),pos.end());
	LL tp,ps;
	if(cl[1]==1)
	{
		tp=2*(int)rc.size()*(t/l)+1;
		//tp=(tp-1)%n+1;
		LL tm=t%l;
		gov(i,rc)
		{
			if((x[rc[i]]-x[1])<2*tm)tp++;
			if((x[rc[i]]-x[1]+l)<2*tm)tp++;
		}

		tp=(tp-1)%n+1;
		//prt(tp);
		ps=(x[1]+t)%l;
	}
	else
	{
		tp=2*(int)c.size()*(t/l);
		//tp=(tp-1)%n+1;
		LL tm=t%l;
		gov(i,c)
		{
			if((l-x[c[i]]+x[1])<=2*tm)tp++;
			if((l-x[c[i]]+x[1]+l)<=2*tm)tp++;
		}
		tp=(n-tp%n)%n+1;
		//prt(tp);
		ps=(x[1]-t%l+l)%l;
		//prt(ps);
	}
	int tt=lower_bound(pos.begin(),pos.end(),ps)-pos.begin();
	go(i,tt,n-1)
	{
		ans[tp]=pos[i];
		tp++;
		if(tp>n)tp=1;
	}
	go(i,0,tt)
	{
		ans[tp]=pos[i];
		tp++;
		if(tp>n)tp=1;
	}
	go(i,1,n)printf("%I64d\n",ans[i]);
}
int main()
{
	while(~sfff(n,l,t))
	{
		work();
	}
	return 0;
}

