typedef tuple<double, double> res; // time, atlas

int N;
ll L, T;
ll X[100010];
int W[100010];
int ans[100010];

vector<ll> V[2];

int main () {
  cin >> N >> L >> T;
  for (auto i = 0; i < N; ++i) {
    cin >> X[i] >> W[i];
    W[i]--;
    V[W[i]].push_back(X[i]);
  }
  for (auto i = 0; i < N; ++i) {
    if (W[i] == 0) {
      ans[i] = X[i] + T%L;
      ans[i] %= L;
    } else {
      ans[i] = X[i] + L - T%L;
      ans[i] %= L;  
    }
  }
  int branch = 0;
  if (W[0] == 0) {
    int counter = V[1].size();
    branch += (T/L) * counter;
    branch %= N;
    int nokori = T%L;
    for (auto x : V[1]) {
      if (x - X[0] < 2 * nokori) {
        branch++;
      }
    }
    branch %= N;
  } else {
    int counter = V[0].size();
    branch += N - (T/L) * counter;
    branch %= N;
    int nokori = T%L;
    for (auto x : V[0]) {
      if (L - (x - X[0]) < 2 * nokori) {
        branch += (N-1);
      }
    }
    branch %= N;
  }
  cerr << "branch = " << branch << endl;
  int memo = ans[0];
  cerr << "memo = " << memo << endl;
  sort(ans, ans+N);
  int zahyo = 0;
  if (W[0] == 0) {
    for (auto i = 0; i < N; ++i) {
      if (memo == ans[i]) {
        zahyo = (i + N - branch)%N;
        break;
      }
    }    
  } else {
    for (auto i = N-1; i >= 0; --i) {
      if (memo == ans[i]) {
        zahyo = (i + N - branch)%N;
        break;
      }
    }    
  }
  cerr << "zahyo = " << zahyo << endl;
  for (auto i = 0; i < N; ++i) {
    cout << ans[(zahyo + i)%N] << endl;
  }
}

