int n, L, T;

int x[Sz], w[Sz];

void solve (int x[], int w[], int p[]) {      
  static vec<ll> a;
  a.clear();
  for (int i = 1; i <= n; i++) {
    if (w[i])
      a.pb (x[i]);
  }    
  int len = sz(a);
  for (int i = 0; i < len; i++)
    a.pb (a[i] + L);
  for (int i = 1; i <= n; i++) {
    if (!w[i]) {
      ll j = i;
      j += ((2*T/L) * 1ll * sz(a));
      if (sz(a))
        j += upper_bound (a.begin(), a.end(), x[i] + (2ll * T % L)) - upper_bound (a.begin(), a.end(), x[i]);
      j = ((j-1) % n + 1);
      p[i] = j;
    }
  } 
}

int main()
{
  #ifdef Local
    localInput();
  #endif
  Read_rap();      
  cin >> n >> L >> T;
  for (int i = 1; i <= n; i++) {
    cin >> x[i] >> w[i];
    w[i]--;
  }
  int p[2][Sz] = {0};
  int ans[Sz];
  for (int t = 0; t < 2; t++) {
    solve (x, w, p[t]); 
    for (int i = 1; i <= n/2; i++) {
      swap (x[i], x[n - i + 1]);
      swap (w[i], w[n - i + 1]);
    }
    for (int i = 1; i <= n; i++)
      x[i] = (L-x[i]) % L, w[i] ^= 1;
  }
  /*
  for (int i = 0; i < 2; i++) {
    for (int j = 1; j <= n; j++)
      cout << p[i][j] << ' ';
    cout << endl;
  }
  */             

  for (int i = 1; i <= n; i++)
    if (!w[i]) 
      ans[p[0][i]] = (x[i] + T) % L;
    else
      ans[n - p[1][n - i + 1] + 1] = ((x[i] - T) % L + L) % L ;

  for (int i = 1; i <= n; i++)
    cout << ans[i] << endl;

  return 0;
}






