/* functions */
inline ll QueryLeft(ll v) {
    ll w = (v % L + L) % L, k = (v - w) / L;
    return std::upper_bound(lef, lef + l, w) - lef + k * l;
}
inline ll QueryRight(ll v) {
    ll w = (v % L + L) % L, k = (v - w) / L;
    return std::upper_bound(rig, rig + r, w) - rig + k * r;
}
int main(int argc, char *argv[]) {
