        read(pos[i]), read(dir[i]);
        (dir[i] == 1) ? lef[l++] = pos[i] : rig[r++] = pos[i];
    }
    FOR(i, 0, n - 1, 1) {
        nxtp[i] = pos[i];
        if(dir[i] == 1) {
            nxtp[i] = (nxtp[i] + T) % L;
            ser[i] = (i + QueryRight(pos[i] + 2ll * T) - QueryRight(pos[i])) % n;
        } else {
