const int MAX_N = 112345;
ll X[MAX_N];
int W[MAX_N];

vector<int> solve(int N, ll L, ll T) {
  vector<int> res(N);
  if (count(W, W+N, 1) == N) {
    REP(i, N) res[i] = (X[i] + T) % L;
    return res;
  }
  if (count(W, W+N, 2) == N) {
    REP(i, N) res[i] = ((X[i] - T) % L + L) % L;
    return res;
  }

  vector<int> Y(N);
  REP(i, N) {
    if (W[i] == 1) Y[i] = (X[i] + T) % L;
    else Y[i] = ((X[i] - T) % L + L) % L;
  }
  sort(ALL(Y));
  // pv(ALL(Y));

  int o = 0;
  while (W[o] == 2) o++;
  // W[o] == 1

  ll co = 0;
  REP(i, N) if (i != o) {
    if (W[i] == 2) {
      ll t = T;
      if (o < i) {
        if (t >= (X[i]-X[o])/2) {
          co++;
          t -= (X[i]-X[o])/2;
          co += 2*t/L;
        }
      } else {
        if (t >= (L-X[o]+X[i])/2) {
          co++;
          t -= (L-X[o]+X[i])/2;
          co += 2*t/L;
        }
      }
    }
  }
  int y0 = (X[o] + T) % L;
  int p;
  for (p = N - 1; p >= 0; p--) if (y0 == Y[p]) break;
  // cout << "co=" << co << " " << y0 << " " << p <<  endl;
  REP(i, N) res[(co+o+i) % N] = Y[(p+i) % N];
  return res;
}

