void solve() {
    rep (i,n) rad[i] = i;
    sort(rad, rad+n, [](int a, int b) {
        return pos[a] < pos[b];
    });
    int Fir=0;
    rep (i,n) {
        int add= (dir[i]==1) ? (pos[i]+s) /m %n
                          : (pos[i]-s-m+1) /m %n;
        Fir = (Fir+add+n+n) % n;
        pos[i] = (pos[i] +s%m*dir[i] +m +m) %m;
    }
    sort(pos, pos+n);
    rep (i,n) ans[ rad[(i-Fir +n)%n] ] = pos[i];
    rep (i,n) printf("%lld\n",ans[i]);
}

