typedef long long ll;
typedef pair<ll, int> pii;

int n;
ll l, t;
pii x[100005];

ll f(ll a){
  a %= l;
  if (a < 0) return a+l;
  return a;
}

set<pii> Sn, Sp;

ll location(int dir, ll loc, ll tm){

  while (true){
    loc = f(loc);
    int nxt;
    if (dir == 1)
      nxt = Sn.lower_bound({f(loc+tm), 1e9})->y;
    else
      nxt = (--Sp.lower_bound({f(loc-tm), -1}))->y;
    ll loc2 = f(x[nxt].x + tm * x[nxt].y);

    if (dir == 1){
      if (loc2 <= loc) loc2 += l;
      loc2 = (loc+loc2) / 2;
    } else {
      if (loc2 >= loc) loc2 -= l;
      loc2 = (loc+loc2) / 2;
    }

    ll del = abs(loc-loc2);
    if (tm+del > t) break;
    tm += del;
    loc = loc2;
    dir = -dir;

  }

  return f(loc + (t-tm) * dir);

}

ll location(int id){
  return location(x[id].y, x[id].x, 0);
}

