using i64=int64_t;

void solve(){
    int n;
    i64 l,t;
    cin >> n >> l >> t;
    vector<i64> x(n),w(n);
    rep(i,0,n) cin >> x[i] >> w[i];
    int num=0;
    rep(i,1,n){
        if(w[i]==w[0]) continue;
        i64 a=x[0],b=x[i];
        if(w[i]==1) swap(a,b);
        if(a<b) num+=((l+1)/2/t+(l+1)/2%t/((b-a+1)/2))*(w[0]==1?1:-1);
        else num+=((l+1)/2/t+(l+1)/2%t/((a+l-b+1)/2))*(w[0]==1?1:-1);
    }
    num=(num%n+n)%n;

    vector<i64> y(n);
    rep(i,0,n) y[i]=((x[i]+t*(w[i]==1?1:-1))%l+l)%l;
    i64 tmp=y[0];
    sort(y.begin(),y.end());
    vector<i64> ans(n);
    int j;
    rep(i,0,n) if(y[i]==tmp){
        j=i;
        break;
    }
    rep(i,0,n) ans[(num+i)%n]=y[(i+j)%n];
    rep(i,0,n) cout << ans[i] << endl;
}

int main(){
    std::cin.tie(0);
    std::ios::sync_with_stdio(false);
    cout.setf(ios::fixed);
    cout.precision(10);
    solve();
    return 0;
}

