int model1(int p, int t) {
	FOR(i, 0, n) {
		na[i] = a[i] - a[p];
		if (na[i] < 0) {
			na[i] += l;
		}
		if (i == p) {
			continue;
		}
		if (w[i] == 1) {
			ti[1].push_back(na[i]);
		}
		else {
			ti[0].push_back(na[i]);
		}
	}
	sort(ti[0].begin(), ti[0].end());
	sort(ti[1].rbegin(), ti[1].rend());
	int x = 0;
	int y = 0;
	int dir = 1;
	int p0 = 0;
	int p1 = 0;
	while (1) {
		if (dir == 1) {
			if (p0 == ti[0].size()) {
				break;
			}
			if (y + ti[0][p0] > t + t) {
				break;
			}
			x = ti[0][p0++];
			dir = 2;
		}
		else {
			if (p1 == ti[1].size()) {
				break;
			}
			if (x + l - ti[1][p1] > t + t) {
				break;
			}
			y = l - ti[1][p1++];
			dir = 1;
		}
	}
	if (dir == 1) {
		int res = a[p] + t;
		res %= l;
		res -= y;
		if (res < 0) {
			res += l;
		}
		return res;
	}
	else {
		int res = a[p] + x;
		res %= l;
		res -= t;
		if (res < 0) {
			res += l;
		}
		return res;
	}
}

