		if (dir == 2) {
			if (p0 == ti[0].size()) {
				break;
			}
			if (y + l - ti[0][p0] > t + t) {
				break;
			}
			x = l - ti[0][p0++];
			dir = 1;
		}
		else {
			if (p1 == ti[1].size()) {
				break;
			}
			if (x + ti[1][p1] > t + t) {
				break;
			}
			y = ti[1][p1++];
			dir = 2;
		}
	}
	if (dir == 1) {
		int res = a[p] + t;
		res %= l;
		res -= x;
		if (res < 0) {
			res += l;
		}
		return res;
	}
	else {
		int res = a[p] + y;
		res %= l;
		res -= t;
		if (res < 0) {
			res += l;
		}
		return res;
	}
}

