	}
	int X0, X1, P0 = FP[0], P1 = FP[1];
	if (w[0] == 1)X0 = cntcross(0)%N;
	else X0 = (N - cntcross(0) % N) % N;
	if (w[1] == 1)X1 = (cntcross(1) + 1) % N;
	else X1 = (N + 1 - cntcross(1) % N) % N;
	sort(FP, FP + N);
	if (X0 > X1&&X1 != 0) {
	swap(P0, P1); swap(X0, X1);
	}
	rep(i, N) {
		if (FP[i] == P0&&FP[(i + 1) % N] == P1) {
			rep(j, N) {
				FX[(i + j) % N] = (X0 + j) % N;
			}
			goto FN;
		}
	}
	rep(i, N) {
		if (FP[i] == P0&&FP[(i + 1) % N] == P1) {
			rep(j, N) {
				FX[(i + j) % N] = (X0 + j) % N;
			}
			goto FN;
		}
	}

	FN: ;
	vector<P>V;
	rep(i, N) {
		V.push_back(P(FX[i], FP[i]));
	}
	sort(V.begin(), V.end());
	rep(i, N)cout << V[i].second << endl;
}

