int main(){
  std::vector<int> place;
  long int true_place[100001];
  long int pre_true_place[100001];
  long int direction[100001];
  long int n, l, timer;
  long int cnt;

  std::cin >> n >> l >> timer;
  for(int i = 0; i < n; i++){
    std::cin >> true_place[i] >> direction[i];
    pre_true_place[i] = true_place[i];
    place.push_back(true_place[i]);
    if(direction[i] == 1);
    else if(direction[i] == 2) direction[i] = l - 1;
  }

  for(int t = 0; t < timer % l; t++){

    //個体を無視したありの位置
    for(int i = 0; i < n; i++){
      place[i] = true_place[i] + direction[i];
      place[i] %= l;
    }
    std::sort(place.begin(), place.end());

    //一番目のありの位置
    if(direction[0] == 1 && true_place[1] - true_place[0] == 0) true_place[0] += l - direction[0];
    else if(direction[0] == l - 1 && true_place[0] - true_place[n - 1] == 0) true_place[0] += l - direction[0];
    else if(direction[0] == 1 && (true_place[1] - true_place[0] == 1 || true_place[1] - true_place[0] == 1 - l));
    else if(direction[0] == l - 1  && (true_place[0] - true_place[n - 1] == 1 || true_place[0] - true_place[n - 1] == 1 - l));
    else true_place[0] += direction[0];
    true_place[0] %= l;

    //i番目のありの位置
    for(cnt = 0; place[cnt] != true_place[0]; cnt++);
    for(int i = 0; i < n; i++){
      true_place[i] = place[(cnt + i) % n];
    }

    //ありの動く向き
    for(int i = 0; i < n; i++){
      if(true_place[i] - pre_true_place[i] == 1 || true_place[i] - pre_true_place[i] == 1 - l) direction[i] = 1;
      else if(true_place[i] - pre_true_place[i] == 0) direction[i] = l - direction[i];
      else direction[i] = l - 1;
    }
    for(int i = 0; i < n; i++){
      pre_true_place[i] = true_place[i];
    }
  }
  for(int i = 0; i < n; i++){
    std::cout << true_place[i] << std::endl;
  }
  return 0;
}

