double min(double k, double l){
	if(k < l){
		return k;
	}else{
		return l;
	}
}

int main(){
	int n;
	double l, t;

	cin >> n >> l >> t;

	double ant[n][2];

	for(int i = 0; i < n; ++i){
		cin >> ant[i][0] >> ant[i][1];
	}

	double d = l;
	int x1, x2;
	double time = 0;

	while(1){	
		for(int i = 0; i < n - 1; ++i){
			for(int j = i + 1; j < n; ++j){
				if(min(abs(ant[i][0] - ant[j][0]), l - abs(ant[i][0] - ant[j][0])) != 0 && min(abs(ant[i][0] - ant[j][0]), l - abs(ant[i][0] - ant[j][0])) < d && ant[i][1] != ant[j][1]){
					d = min(abs(ant[i][0] - ant[j][0]), l - abs(ant[i][0] - ant[j][0]));
					x1 = i;
					x2 = j;
					break;
				}
			}
		}
		if((t - time) < d / 2){
			for(int i = 0; i < n; ++i){
				if(ant[i][1] == 1){
					ant[i][0] += (t - time);
					if(ant[i][0] >= l){
						ant[i][0] -= l;
					}
				}else{
					ant[i][0] -= (t - time);
					if(ant[i][0] < 0){
						ant[i][0] += l;
					}
				}
			}
			break;
		}

		for(int i = 0; i < n; ++i){
			if(ant[i][1] == 1){
				ant[i][0] += (d / 2);
				if(ant[i][0] >= l){
					ant[i][0] -= l;
				}
			}else{
				ant[i][0] -= (d / 2);
				if(ant[i][0] < 0){
					ant[i][0] += l;
				}	
			}
		}

		if(ant[x1][1] == 1){
			ant[x1][1] = 2;
			ant[x2][1] = 1;
		}else{
			ant[x1][1] = 1;
			ant[x2][1] = 2;
		}
		time += (d / 2);
	}

	for(int i = 0; i < n; ++i){
		cout << ant[i][0] << "\n";
	}

	return 0;
}

