int N;
ll M, T;
int S[303030], NS[303030], ret[303030];
int D[303030];
int O[303030];
int NL, NR;
pair<int, int> P[303030];

void solve() {
	int i, j, k, l, r, x, y; string s;

	cin >> N >> M >> T;
	//R=1;L=2;
	vector<int> VL, VR;
	FOR(i,0, N) {
		cin >> S[i] >> s;
		S[i];
		D[i] = s[0] == '1';
		if (D[i] == 0) {
			NL++;
			VL.push_back(S[i]), VL.push_back(S[i] + M);
			NS[i] = (M + (S[i] - T) % M) % M;
		}
		else {
			NR++;
			VR.push_back(S[i]), VR.push_back(S[i] + M);
			NS[i] = (S[i] + T) % M;
		}

		P[i] = { S[i],i };
	}

	if (NL == 0 || NR == 0) {
		FOR(i,0, N) printf("%d ", NS[i] + 1);
		printf("\n");
		return;
	}

	sort(P, P + N);
	FOR(i,0, N) O[P[i].second] = i;
	sort(ALL(VL));
	sort(ALL(VR));

	FOR(i,0, N) {
		x = P[i].second;
		if (D[x] == 0) {
			ll col = 2 * T / M*NR;
			int left = (int)(2 * T%M);
			auto it1 = lower_bound(ALL(VR), S[x] + M);
			auto it2 = lower_bound(ALL(VR), S[x] + M - left);
			col += it1 - it2;
			y = (N + (i - col) % N) % N;
		}
		else {
			ll col = 2 * T / M*NL;
			int left = (int)(2 * T%M);
			auto it1 = lower_bound(ALL(VL), S[x] + left + 1);
			auto it2 = lower_bound(ALL(VL), S[x]);
			col += it1 - it2;
			y = (i + col) % N;
		}
		ret[P[y].second] = NS[x] ;

	}

	FOR(i,0, N) printf("%d ", ret[i]);
	printf("\n");
}

int main() {
  cin.tie(0);
  ios_base::sync_with_stdio(false);

  solve();

  return 0;
}
