using namespace std;

signed main() {
  int N,L,T;
  cin >> N >> L >> T;
  vector<int> X(N),W(N);
  for(int i=0; i<N; i++) {
    cin >> X[i] >> W[i];
    if(W[i]==2) W[i] = -1;
  }

  priority_queue<tuple<int,int,int>> events;

  for(int i=0; i<N; i++) {
    int j = (i+1) % N;
    if(W[i]==1 && W[j] == -1) {
      int time;
      if(X[i] < X[j]) time = (X[j]-X[i]+1)/2;
      else            time = (X[j]+L-X[i]+1)/2;
      events.push(make_tuple(time,i,j));
    }
  }

  int t = 0;

  while(t < T) {
    auto e = events.top();
    events.pop();
    int etime = get<0>(e);
    int ant1 = get<1>(e);
    int ant2 = get<2>(e);
    if(etime > T) etime = T;

    if (etime != t) {
      for(int i=0; i<N; i++) {
        X[i] += W[i] * (etime - t);
        if(X[i] < 0) X[i] += L;
        X[i] %= L;
      }
    }

    t = etime;
    W[ant1] *= -1;
    W[ant2] *= -1;
    assert(W[ant1]==-1);
    assert(W[ant2]==1);

    int distance = (int)abs(X[ant1]-X[ant2]);
    if(distance == 1 || distance == L-1) swap(X[ant1],X[ant2]);

    int ant1pair = ant1==0 ? N-1 : ant1-1;
    int ant2pair = (ant2 + 1)%N;

    assert((int)abs(ant1-ant1pair) == 1 || (int)abs(ant1-ant1pair) == N-1);
    assert((int)abs(ant2-ant2pair) == 1 || (int)abs(ant2-ant2pair) == N-1);

    if(W[ant1]==-1 && W[ant1pair]==1) {
      int e2time;
      if(X[ant1pair] < X[ant1]) e2time = t + (X[ant1]-X[ant1pair]+1)/2;
      else                      e2time = t + (X[ant1]+L-X[ant1pair]+1)/2;
      events.push(make_tuple(e2time, ant1pair, ant1));
    }

    if(W[ant2]==1 && W[ant2pair]==-1) {
      int e2time;
      if(X[ant2] < X[ant2pair]) e2time = t + (X[ant2pair]-X[ant2]+1)/2;
      else                      e2time = t + (X[ant2pair]+L-X[ant2]+1)/2;
      events.push(make_tuple(e2time, ant2, ant2pair));
    }
  }
  for(int i=0; i<N; i++) cout << X[i] << endl;
  return 0;
}

