typedef long long ll;

int main() {
	int n; ll L, T; cin >> n >> L >> T;
	vector<ll> a, b, c;
	ll pos0; int w0;
	for (int i = 0; i < n; ++i) {
		ll x; int w; cin >> x >> w;
		if (i == 0) pos0 = x, w0 = w;
		if (w == 1) {
			a.push_back((x + T)%L);
			b.push_back(x - L); b.push_back(x - 2*L);
		}
		else {
			a.push_back((x - T%L + L) % L);
			c.push_back(x); c.push_back(x + L);
		}
	}
	ll cnt = 0;
	if (w0 == 1) {
		cnt += T / L  * c.size();
		T %= L;
		sort(c.begin(), c.end());
		auto iter = lower_bound(c.begin(), c.end(), pos0 + 2*T);
		cnt += distance(c.begin(), iter);
		cnt %= n;
	}
	else {
		cnt += T / L * b.size();
		T %= L;
		sort(b.begin(), b.end());
		auto iter = lower_bound(b.begin(), b.end(), pos0 - 2*T);
		cnt += distance(iter, b.end());
		cnt = ((-cnt) % L + L) % n;
	}
	sort(a.begin(), a.end());
	for (int i = 0; i < n; ++i) {
		cout << a[(i + cnt) % n] << endl;
	}
	return 0;
}

