const int N = 100000 + 5;

int n , L , T , A[N] , W[N] , v[N];

int main()
{
    read(n) , read(L) , read(T);
    rep(i , 0 , n-1) read(A[i]) , read(W[i]);
    rep(i , 0 , n-1)
    {
        if(W[i] == 1) v[i] = (A[i] + T) % L;
        if(W[i] == 2) v[i] = (A[i] - T) % L , v[i] = (v[i] + L) % L;
    }
    int x = v[0] , p;
    sort(v , v + n);
    if(W[0] == 1)
    {
        rep(i , 0 , n-1) if(v[i] == x)
        {
            p = i ; break ;
        }
    }
    else
    {
        per(i , n-1 , 0) if(v[i] == x)
        {
            p = i ; break ;
        }
    }
    int R1 = 0 , R2 = 0;
    rep(i , 1 , n-1)
    {
        if(W[i] == W[0]) continue ;
        R1 += 2;
        int dis = A[i] - A[0];
        if(W[0] == 2) dis = L - dis;
        if(dis < T % L * 2) R2++;
        if(dis < T % L * 2 - L) R2++;
    }
    int t = R1 * (T / L) + R2; t %= n;
    if(W[0] == 2) t = (n - t) % n;
    rep(i , 0 , n-1) printf("%d\n" , v[(i + p - t + n) % n]);
