using namespace std;

constexpr static int MAXN = 1e6;

int64_t n, l, t;
int64_t x[MAXN], w[MAXN];
int64_t y[MAXN];
vector <pair<int64_t, int>> x1, x2;

int64_t tprev[MAXN];

int main() {
    cin >> n >> l >> t;
    for (int i = 0; i < n; i++)
        cin >> x[i] >> w[i];

    for (int i = 0; i < n; i++) {
        tprev[i] = -1;
        if (w[i] == 1)
            x1.push_back({x[i], i});
        else
            x2.push_back({x[i], i});
    }

    int pos0 = 0;
    if (x1.size() > 0 && x2.size() > 0) {
        int64_t tcur = 0;
        int idx = 0;
        int i1 = 0, i2 = 0;
        while (tcur < 2 * t) {
            if (w[idx] == 1) {
                int64_t xcur = (x[idx] + tcur % l) % l;
                while (i2 < x2.size() && x2[i2].first <= xcur)
                    i2++;
                int64_t tadd = 0;
                if (i2 == x2.size())
                    i2 = 0, tadd += l;
                tadd += x2[i2].first - xcur;
                if (tcur + tadd <= 2 * t) {
                    tcur += tadd;
                    idx = x2[i2].second;
                }
                else {
                    tcur = 2 * t;
                }
            }
            else {
                int64_t xcur = (x[idx] + l - tcur % l) % l;
                while (i1 >= 0 && x1[i1].first >= xcur)
                    i1--;
                int64_t tadd = 0;
                if (i1 == -1)
                    i1 = x1.size() - 1, tadd += l;
                tadd += xcur - x1[i1].first;
                if (tcur + tadd <= 2 * t) {
                    tcur += tadd;
                    idx = x1[i1].second;
                }
                else {
                    tcur = 2 * t;
                }
            }
            //cout << "> " << tcur << " " << idx << endl;
            if (tprev[idx] != -1) {
                int64_t tadd = tcur - tprev[idx];
                if (tadd > 0 && tcur + tadd <= 2 * t) {
                    int64_t q = (2 * t - tcur) / tadd;
                    tcur += tadd * q;
                }
            }
            tprev[idx] = tcur;
        }
        pos0 = idx;
    }

    for (int j = 0; j < n; j++) {
        int i = (pos0 + j) % n;
        int64_t diff = (w[i] == 1 ? (t % l) : (l - t % l));
        y[i] = (x[i] + diff) % l;
        cout << y[i] << '\n';
    }
    cout.flush();
}

