int count(int x, int y, int T, int L)
{
	x *= 2;
	y *= 2;
	T *= 2;
	L *= 2;
	auto m = (y - x) / 2;
	auto m2 = (m + L / 2) % L;
	auto v = T % L;
	if (v >= m2)
	{
		return 2 * (T / L) + 2;
	}
	else if (v >= m)
	{
		return 2 * (T / L) + 1;
	}
	else
	{
		return 2 * (T / L);
	}

}
int rcount(int x, int y, int T, int L)
{
	return count(x, ((L + x - y) + x) % L, T, L);
}

void Main()
{
