	f = num[0] + (c - a) / 2 + T*L;
	f += L;
	f %= L;
	//cout << f << endl;
	for (int i = 0; i < N; i++) {
		if (ans[i] == f) {
			for (int j = 0; j < N; j++) {
				cout << ans[(i + j) % N] << endl;
			}
			return 0;
		}
	}
	return 0;
}

