struct xw {
	int X;
	int W;
};

xw xw_list[100001];


int main(void) {
	int N, L, T;
	cin >> N >> L >> T;

	int dir[2] = {0};
	int first = 0;

	vector <int> endpos;
	for (int i= 1; i <= N; i++) {
		cin >> xw_list[i].X >> xw_list[i].W;
		if (xw_list[i].W == 1) {
			dir[0]++;
			endpos.push_back((xw_list[i].X+T)%L);

			if (first == 0) first = i;

		} else {
			dir[1]++;
			long long mv = T%L;
			mv = xw_list[i].X + L - mv;
			mv = mv % L;
			endpos.push_back(mv);
		}
	}

	if (first == 0) {
		for (int i = 0; i < N; i++) {
			cout << endpos.at(i) << endl;
		}
		return 0;
	}

	long long crossed = 0;
	for (int i = 1; i <= N; i++) {
		if (xw_list[first].W != xw_list[i].W) {
			int diff = abs(xw_list[first].X-xw_list[i].X);

			int tim = T;
			if (diff > 2*tim) continue;

			crossed++;
			tim -= diff;
			if (tim > 0) {
				crossed += (2*tim)/L;
			}
			crossed %= N;
		}
	}

	int changed_no;
	changed_no = crossed + first-1;
	int val = endpos.at(first-1);
	sort(endpos.begin(), endpos.end());

	int vecpos;
	for (vecpos = N-1; vecpos >= 0; vecpos--) {
		if (endpos.at(vecpos) == val) {
			break;
		}
	}

	for (int i = 0; i < N; i++) {
		cout << endpos.at((vecpos+i-changed_no+N)%N) << endl;
	}

	return 0;
}

