void solve (int x[], int w[], int p[]) {      
  static vec<ll> a;
  a.clear();
  for (int i = 1; i <= n; i++) {
    if (w[i])
      a.pb (x[i]);
  }    
  int len = sz(a);
  for (int i = 0; i < len; i++)
    a.pb (a[i] + L);
  for (int i = 1; i <= n; i++) {
    if (!w[i]) {
      ll j = i;
      j += (2*T/L) * 1ll * sz(a);
      if (sz(a)) {
        j += upper_bound (a.begin(), a.end(), x[i] + (2ll * T % L)) - upper_bound (a.begin(), a.end(), x[i]);
      }
      if (j > n)
        j -= n;
      p[i] = j;
    }
  } 
}

