using namespace std;
typedef long long ll;

const int N=100005;

int n,m,Q;
int a[N],na,b[N],nb;
int w[N],pnext[N],pnow[N];

int chk1(int p){
	int l=0,r=Q,mid=(l+r+1)>>1;
	int x=pnow[p],y=pnext[p];
	if((b[y%nb]-a[x%na]+m)%m>=Q*2)
		return (a[x%na]+Q)%m;
	while(l<r){
		int cx=x-(mid+1)/2,cy=y+mid/2;
		ll dis=0;
		dis+=(ll)m*(cy/nb+(-cx)/na);
		cx%=na,cy%=nb;
		if(cx<0)cx+=na,dis+=m;
		dis+=b[cy]-a[cx];
		if(dis>=Q*2)
			r=mid-1;
		else
			l=mid;
		mid=(l+r+1)>>1;
	}
	if(mid&1)return (a[((x-(mid+1)/2)%na+na)%na]+Q)%m;
	return ((b[(y+mid/2)%nb]-Q)%m+m)%m;
}

int chk2(int p){
	int l=0,r=Q,mid=(l+r+1)>>1;
	int x=pnext[p]-1,y=pnow[p];
	if((b[y%nb]-a[(x%na+na)%na]+m)%m>=Q*2)
		return ((b[y%nb]-Q)%m+m)%m;
	while(l<r){
		int cx=x-mid/2,cy=y+(mid+1)/2;
		ll dis=0;
		dis+=(ll)m*(cy/nb+(-cx)/na);
		cx%=na,cy%=nb;
		if(cx<0)cx+=na,dis+=m;
		dis+=b[cy]-a[cx];
		if(dis>=Q*2)
			r=mid-1;
		else
			l=mid;
		mid=(l+r+1)>>1;
	}
	if(mid&1)return ((b[(y+(mid+1)/2)%nb]-Q)%m+m)%m;
	return (a[((x-mid/2)%na+na)%na]+Q)%m;
}

int main(){
