	for(int i=1,x;i<=n;i++){
		scanf("%d%d",&x,&w[i]);
		if(w[i]==1)
			a[pnow[i]=na++]=x,pnext[i]=nb;
		else
			b[pnow[i]=nb++]=x,pnext[i]=na;
	}
	if(!na||!nb){
		for(int i=1;i<=n;i++)
			if(w[i]==1)
				printf("%d\n",(a[pnow[i]]+Q)%m);
			else
				printf("%d\n",((b[pnow[i]]-Q)%m+m)%m);
	}else{
		for(int i=1;i<=n;i++)
			if(w[i]==1)
				printf("%d\n",chk1(i));
			else
				printf("%d\n",chk2(i));
	}
	return 0;
}

