		if (w[i] == 1) res[i].first = (x[i] + t) % l;
		else res[i].first = mod_minus(x[i] - t, l);
		res[i].second = i;
	}
	ll count = 0;
	repp (i, 1, n) {
		if (w[0] == 1) {
			if (w[i] == 2) {
				// cout << i << ": " << div_minus(2 * t - (x[i] - x[0]), l) + 1 << endl;
