			}
		} else {
			if (w[i] == 1) {
				// cout << i << ": " << div_minus(2 * t - (l + x[0] - x[i]), l) + 1 << endl;
				count -= div_minus(2 * t - (l + x[0] - x[i]), l) + 1;
			}
		}
	}
	sort(all(res));
	ll k;
	for (k = 0; k < n; k++) {
		if (res[k].second == 0) break;
	}
	if (w[0] == 1 && res[(k + 1) % n].first == res[k].first) k++;
	// cout << count << " " << k << endl;
	count = mod_minus(k - count, n);
	rep(i, n) {
		cout << res[(i + count) % n].first << endl;
	}
	return 0;
}

