#include <bits/stdc++.h>
using namespace std;

typedef long long LL; 
typedef long double LD;
const int MAX=1e5+5;
int n,l,t;
int dir[MAX];
int coord[MAX];
pair<int,int> cord[MAX];
int ans[MAX];

int main() 
{	
	scanf("%d %d %d",&n,&l,&t);//number of balls,circumference, total path

	for(int i=0;i<n;i++)
	{
		scanf("%d %d",&coord[i],&dir[i]);//coordinate,direction
	}

	int cyc=(t/l);//number of cycles
	int v=(t%l);//leftover
	int cnt=0;
	if(dir[0]==1)
	{
		for(int i=1;i<n;i++)
		{
			if(coord[i]<=(coord[0]+v))
			{
				//printf("%d %d\n",coord[i],coord[0]+v);
				cnt++;
			}
			else
			{
				break;
			}
		}
	}		
	else
	{
		for(int i=n-1;i>=1;i--)
		{
			if(coord[i]>=((coord[1]-v+l)%l))
			{
				cnt++;
			}
			else
			{
				break;
			}
		}
	}
	//printf("%d\n",cnt);
	cnt=(cnt+((1ll*cyc*1ll*(n-1))%n))%n;//change
	int rep;
	if(dir[0]==1)
	{
		rep=(cnt%n);
	}
	else
	{
		rep=(n-cnt)%n;
	}

	for(int i=0;i<n;i++)
	{
		if(dir[i]==1)
		{
			cord[i].second=i;
			cord[i].first=(coord[i]+v)%l;
		}
		else
		{
			cord[i].second=i;
			cord[i].first=(coord[i]-v+l)%l;
		}
		/*printf("%d %d\n",cord[i].first,cord[i].second);*/
	}
	sort(cord,cord+n);
	int st=0;
	for(int i=0;i<n;i++)
	{
		if(cord[i].second==0)
		{
			st=i;
			break;
		}
	}
	int don=0;
	for(int i=st;;i=(i+1)%n)
	{
		if(don==n)
		{
			break;
		}
		ans[(rep+don)%n]=cord[i].first;
		don++;
	}
	for(int i=0;i<n;i++)
	{
		printf("%d\n",ans[i]);
	}
	return 0;
}

