using namespace std;

typedef long long ll;
typedef pair<ll, int> pii;

int n;
ll l, t;
pii x[100005];

ll f(ll a){
  a %= l;
  if (a < 0) return a+l;
  return a;
}

set<pii> Sn, Sp;

pii location(int dir, ll loc, ll tm){

  while (true){
    loc = f(loc);
    int nxt;
    if (dir == 1)
      nxt = Sn.lower_bound({f(loc+tm), 1e9})->y;
    else
      nxt = (--Sp.lower_bound({f(loc-tm), -1}))->y;
    ll loc2 = f(x[nxt].x + tm * x[nxt].y);

    if (dir == 1){
      if (loc2 <= loc) loc2 += l;
      loc2 = (loc+loc2) / 2;
    } else {
      if (loc2 >= loc) loc2 -= l;
      loc2 = (loc+loc2) / 2;
    }

    ll del = abs(loc-loc2);
    if (tm+del > t) break;
    tm += del;
    loc = loc2;
    dir = -dir;

  }

  return {f(loc + (t-tm) * dir), dir};

}

pii location(pii a, ll tm){
  return location(a.y, a.x, tm);
}

ll location(int id){
  return location(x[id], 0).x;
}

int main(){
  ios_base::sync_with_stdio(false);

  cin >> n >> l >> t;
  REP(i,n) cin >> x[i].x >> x[i].y, x[i].y = x[i].y == 1 ? 1 : -1;

  {
    bool check = true;
    REP(i,n) if (x[i].y != x[0].y) check = false;
    if (check){
      REP(i,n) cout << f(x[i].x + t * x[i].y) << endl;
      return 0;
    }
  }

  l *= 2;
  t *= 2;
  REP(i,n) x[i].x *= 2;

  REP(i,n){
    if (x[i].y == 1)
      Sp.insert({x[i].x, i}),
	Sp.insert({x[i].x+l, i}),
	Sp.insert({x[i].x-l, i});
    else
      Sn.insert({x[i].x, i}),
	Sn.insert({x[i].x+l, i}),
	Sn.insert({x[i].x-l, i});
  }

  ll a = t/l;
  ll b = t%l;

  t = l;
  ll p = location(0);
  ll q = location(1);

  vector<ll> all;
  REP(i,n) all.pb(f(x[i].x + x[i].y * t));
  sort(all.begin(), all.end());

  ll id = -1;
  if (all.back() == p && all.front() == q)
    id = n-1;
  REP(i,n-1) if (all[i] == p && all[i+1] == q) id = i;
  assert(id != -1);

  id = a*id%n;
  t = a*l+b;
  p = location(x[id], a*l).x;
  q = location(x[(id+1)%n], a*l).x;

  all.clear();
  REP(i,n) all.pb(f(x[i].x + x[i].y * t));
  sort(all.begin(), all.end());

  id = -1;
  if (all.back() == p && all.front() == q)
    all.insert(all.begin(), p), all.pop_back();
  REP(i,n-1) if (all[i] == p && all[i+1] == q) id = i;

  assert(id != -1);

  FOR(i,id,n) cout << all[i]/2 << endl;
  FOR(i,0,id) cout << all[i]/2 << endl;

  return 0;
}

