int main () {
  int N;
  long long L, T;
  cin >> N >> L >> T;
  vector<tuple<long long, int, int>>an(N);
  for (int i = 0; i < N; i ++) {
    int w;
    long long x;
    cin >> x >> w;
    an[i] = make_tuple(x, w, i);
  }
  int num = 0;
  for (int i = 1; i < N; i ++) {
    if (get<1>(an[i]) == get<1>(an[0])) continue;
    long long t = get<0>(an[i]) - get<0>(an[0]);
    if (!(get<1>(an[0]) % 2)) {
      t = L - t;
    }
    long long ti = T * 2 - t;
    if (ti < 0) continue;
    ti /= L;
    num += (int)ti + 1;
    num %= N;
  }
  vector<long long>ans(N);
  int kj = num;
  if (get<1>(an[0]) == 2) kj = (N - num) % N;
  long long tim = T % L;
  ans[kj] = (get<0>(an[0]) + tim) % L;
  if (get<1>(an[0]) == 2) ans[kj] = (L - tim + get<0>(an[0])) % L;
  vector<long long>as(N);
  for (int i = 0; i < N; i ++) {
    as[i] = (get<0>(an[i]) + tim) % L;
    if (get<1>(an[i]) == 2) as[i] = (L - tim + get<0>(an[i])) % L;
  }
  sort(as.begin(), as.end());
  int al = 0;
  while (as[al] != ans[kj]) al ++;
  for (int i = 1; i < N; i ++) {
    int j = i + al;
    j %= N;
    int k = i + kj;
    k %= N;
    ans[k] = as[j];
  }
  for (int i = 0; i < N; i ++) {
    cout << ans[i] << endl;
  }
}

