template <typename T>
inline T mod(T a, T m) {
    T res = a % m;
    if (res < 0) res += m;
    return res;
}


class Solver {
    int N, L, T;
    vi x, w;

    vi cw, ccw, xt;
    int CW, CCW;
public:
    Solver() {
        scanf("%d%d%d", &N, &L, &T);
        x.resize(N); w.resize(N);
        rep(i,N) {
            scanf("%d%d", &x[i], &w[i]);
        }

        init();

        if (N == 1) {
            printf("%d\n", xt[0]);
            return;
        }

        int c0 = solve1(0), x0 = xt[0];
        int c1 = solve1(1), x1 = xt[1];

        sort(ALL(xt));
        int ix = lower_bound(ALL(xt), x0) - xt.begin();
        assert(xt[ix] == x0);
        int offset = 0;
        if (ix < N-1 && xt[ix+1] == x0) {
            if (c0 > c1) swap(c0, c1);
            if (x0 == x1) {
                offset = ix - c0;
            } else {
                offset = ix - (c0 - 1);
            }
        } else {
            offset = ix - c0;
        }
        rep(i,N){
            printf("%d\n", xt[mod(i+offset, N)]);
        }
    }
private:
    void init() {
        cw.reserve(N); ccw.reserve(N);
        xt.resize(N);
        rep(i,N){
            if (w[i] == 1) {
                cw.pb(x[i]);
                xt[i] = mod(x[i] + T, L);
            } else {
                ccw.pb(x[i]);
                xt[i] = mod(x[i] - T, L);
            }
        }
        CW = cw.size(); CCW = ccw.size();
    }
    int solve1(int i) {
        ll crossed = i;
        if (w[i] == 1) {
            for (int y: ccw) {
                int d2 = y - x[i];
                if (d2 < 0) d2 += L;
                int q = 1+(T*2 - d2)/L;
                crossed += q;
            }
        } else {
            for (int y: cw) {
                int d2 = x[i] - y;
                if (d2 < 0) d2 += L;
                int q = 1+(T*2 - d2)/L;
                crossed -= q;
            }
        }
        return mod(crossed, (ll)N);
    }
};

int main() {
    Solver *s = new Solver();
    delete s;
    return 0;
}

