typedef struct {
  long loc;
  short dir;
}preset;


template <typename T>
void q_sort_temp(vector<T> *v, int s, int e){
  if (e-s<=1) {
    return;
  }
  T p = (*v)[0] > (*v)[1]?(*v)[0]:(*v)[1];
  int i = s;
  int j = e;
  while (i < j) {
    while ((*v)[i]<p && i<j) {
      i++;
    }
    while ((*v)[j]>=p && i<j) {
      j--;
    }
    if (i<j) {
      T tmp = (*v)[i];
      (*v)[i] = (*v)[j];
      (*v)[j] = tmp;
    }
  }
  if (s<i||i<e) {
    q_sort_temp(v, s, i);
    q_sort_temp(v, i+1, e);
  }     
  return;

}

int main(){
  int n;
  long l, t;
  vector<preset> prs;
  vector<int> rplc;
  vector<long> pos;
  cin >> n >> l >> t;
  for (int i=0;i<n;i++) {
    preset p;
    long x;
    int w;
    cin >> x >> w;
    //    v.push_back(x);
    //    v.push_back(w);
    p.loc = x;
    p.dir = w;
    prs.push_back(p);
  }

  preset s_p = prs[0];
  long total_colision = 0;
  for (int j=0;j<n;j++) {
    long pos_tmp;
    preset e_p = prs[j];
    if (e_p.dir == 1) {
      pos_tmp = (e_p.loc + t) % l;
    } else {
      pos_tmp = (e_p.loc - t) % l;
    }
    if (pos_tmp < 0) {
      pos_tmp += l;
    }
    pos.push_back(pos_tmp);
    if (s_p.dir == e_p.dir) {
      continue;
    }
    long distance;
    if (s_p.dir == 1) {
      distance = e_p.loc - s_p.loc;
    } else {
      distance = s_p.loc - e_p.loc;
    }
    if (distance < 0) {
      distance += l;
    }
    long v = t / l;
    long r = t % l;
    long c = 2*v;
    if (2*r >= distance) {
      c++;
    }
    total_colision += c;
  }
  int z = (total_colision % n);
  if (s_p.dir == 2) {
    z = (n-z)%n;
  }
  cerr << z << endl;
  q_sort_temp(&pos, 0, pos.size()-1);
  /*  for (int i=0;i<n;i++) {
    cout << pos[i] << endl;
    }*/
  for (int i=z;i<z+n;i++) {
    cout << pos[i % n] << endl;
  }

}

