int L;

struct position{
    int pos;
    position operator+(int num){
        position ans;
        ans.pos = pos + num;
        if(ans.pos >= L) ans.pos -= L;
        return ans;
    }
    position operator-(int num){
        position ans;
        ans.pos = pos - num;
        if(ans.pos < 0) ans.pos += L;
        return ans;
    }
    bool operator==(position other){
        bool ans = false;
        if(pos == other.pos) ans = true;
        return ans;
    }
};

