node operator+(node a,node b)
{
	node c;
	c.x=a.x+b.x;
	c.tb=a.tb+b.tb;
	if(c.tb==2)c.x++,c.tb=0;
	return c;
}
node operator-(node a,node b)
{
	node c;
	c.x=a.x-b.x;
	c.tb=a.tb-b.tb;
	if(c.tb==-1)c.x--,c.tb=1;
	return c;
}
node operator/(node a,node b)
{
	ll u,v;
	node c;
	u=2LL*a.x+a.tb;
	v=2LL*b.x+b.tb;
	c.x=u/v;c.tb=0;
	return c;
}
node div(node a)
{
	if(a.x%2)return (node){a.x/2LL,1LL};
