	{
		if(dir[i]==dir[1])continue;
		if(dir[1]==0)
		{
			if(a[i]>a[1])res=a[i]-a[1];
			else res=l-a[1]+a[i];
		}
		else
		{
			if(a[i]>a[1])res=a[1]+l-a[i];
			else res=a[1]-a[i];
		}
		rs.x=res;rs.tb=0;tot=0;
		tp.x=t;tp.tb=0;
		ls.x=l;ls.tb=0;
		rs=div(rs);
		if((tp/rs).x==0)continue;
		tot=1;tp=tp-rs;
		ls=div(ls);
		tot+=(tp/ls).x;
		cnt+=tot;
	}
	if(dir[1]==0)att=1;
	else att=0,cnt=-cnt;
	for(i=1;i<=n;i++)
