typedef long long int64;
static const int MAXN = 1e5 + 4;

int n, l, t;
int x[MAXN], w[MAXN];
int p[MAXN];

int main()
{
    scanf("%d%d%d", &n, &l, &t);
    for (int i = 0; i < n; ++i) {
        scanf("%d%d", &x[i], &w[i]), --w[i];
        p[i] = ((x[i] + (w[i] ? -1 : 1) * t) % l + l) % l;
    }

    int64 id0 = 0;
    int p0 = p[0];
    int cycles = t / l;
    for (int i = 1; i < n; ++i) if (w[i] ^ w[0]) {
        id0 += cycles;
        int dist;
        if (w[0]) { // Counter-clockwise
            dist = (x[0] + l - x[i]) % l;
        } else {    // Clockwise
            dist = (x[i] + l - x[0]) % l;
        }
        if (t % l * 2 > dist) id0++;
    }
    id0 %= n;

    std::sort(p, p + n);
    int id0_pos;
    if (w[0]) { // Counter-clockwise
        id0_pos = std::distance(&p[0], std::upper_bound(p, p + n, p0) - 1);
    } else {
        id0_pos = std::distance(&p[0], std::lower_bound(p, p + n, p0));
    }
    int offset = id0_pos - id0;
    for (int i = 0; i < n; ++i) printf("%d\n", p[((i + offset) % n + n) % n]);

    return 0;
}

