struct Ant {int x, w, z=-1;};

int main() {
  int N, L, T;
  cin >> N >> L >> T;
  vector<Ant> ant(N);
  for(auto& a: ant) cin >> a.x >> a.w;

  ant[0].z = 0;
  for(auto a: ant) if(a.z==-1) if(ant[0].w!=a.w) {
    if(ant[0].w==1) {
      auto d = a.x-ant[0].x;
      if(d <= 2*T) ant[0].z += (2*T - d)%L + 1;
      ant[0].z %= N;
    } else {
      auto d = L-a.x+ant[0].x;
      if(d <= 2*T) ant[0].z -= (2*T - (d%L))%L + 1;
      ant[0].z %= N;
      if(ant[0].z < 0) ant[0].z += N;
    }
  }

  for(auto& a: ant) {
    if(a.w==1) {
      a.x += T%L;
      a.x %= L;
    } else {
      a.x -= T%L;
      a.x %= L;
      if(a.x < 0) a.x += L;
    }
  }

  sort(begin(ant), end(ant), [](auto l, auto r) {return l.x!=r.x ? l.x<r.x : l.w>r.w;});

  auto s=0;
  for(auto i=0; i<N; ++i) if(ant[i].z!=-1) s=i;
  for(auto i=1; i<N; ++i) {
    auto& a = ant[(s+i)%N];
    auto& p = ant[(s+i-1)%N];
    a.z = (p.z+1)%N;
  }

  sort(begin(ant), end(ant), [](auto l, auto r) {return l.z < r.z;});

  for(auto a: ant) cout << a.x << endl;
}

