    int n,l,t;
    in>>n>>l>>t;
    int X,V,x,v,E;
    ll ans{};
    vector<int> e(n);
    in>>X>>V;
    if(V==1) e[0]=(X+t)%l;
    else e[0]=(X-t)%l;
    if(e[0]<0) e[0]+=l;
