const int N = 1e5 + 5;
int n;
long long L, T, ans[N];

struct Ant {
    long long x, d;
    long long ed, tmp;
    bool operator < (const Ant &rhs) const {
        return ed < rhs.ed;
    }
}a[N];

int main() {
    scanf("%d%lld%lld", &n, &L, &T);
    long long cnt = 0;
    for(int i = 0; i < n; i++) {
        scanf("%lld%lld", &a[i].x, &a[i].d);
        if(a[i].d == 1) cnt++;
        a[i].ed = a[i].x + T*(a[i].d == 1 ? 1LL : -1LL);
        a[i].ed = (a[i].ed%L + L)%L;
    }
    long long cross = 0;
    if(a[0].d == 1) {
        cross += T/L*(n-cnt)*2;
    }else {
        cross += T/L*cnt*2;
    }
    for(int i = 1; i < n; i++) {
        if(a[i].d == a[0].d) continue;
        long long dis = abs(a[i].x - a[0].x);
        if(dis <= T%L*2) cross++;
        if(dis+L < T%L*2) cross++;
    }
    cross %= n;
    if(a[0].d == 2) cross = (n-cross)%n;
    for(int i = 1; i < n; i++) {
        if(a[i].ed < a[0].ed) a[i].ed += L;
    }
    sort(a+1, a+n);
    for(int i = 0; i < n; i++) {
        ans[(cross+i)%n] = a[i].ed%L;
    }
    for(int i = 0; i < n; i++) {
        printf("%d\n", (int)ans[i]);
    }
    return 0;
}

