int const INF = 1001001001;

ll n,L,T;
ll mod(ll a, ll b = L) {
    if(a%b < 0) return a%b+b;
    else return a%b;
}

int main()
{
    cin >> n >> L >> T;
    vl x(n),w(n);
    rep(i,n) cin >> x[i] >> w[i];

    vl z(n);
    rep(i,n) {
        if(w[i] == 1) z[i] = mod(x[i] + T);
        if(w[i] == 2) z[i] = mod(x[i] - T);
    }

    vl v;
    if(w[0] == 1) {
        for(int i = 1; i < n; ++i) {
            if(w[i] == 2) v.push_back(x[i]-x[0]);
        }
    }
    if(w[0] == 2) {
        for(int i = n-1; i > 0; --i) {
            if(w[i] == 1) v.push_back(L-x[i]+x[0]);
        }
    }
    ll p = (2*T)/L, q = (2*T)%L;
    ll collide_count = p*SZ(v);
    rep(j,SZ(v)) {
        if(v[j] <= q) collide_count++;
    }
    ll r;
    if(w[0] == 1) r = collide_count % n;
    if(w[0] == 2) r = n - collide_count % n;
    if(r != 0)rotate(z.begin(), z.begin() + (n - r), z.end());
    rep(i,n) cout << z[i] << endl;
    return 0;
}

