pair<int, int> arr[MAXN];

pair<int, int> pt[MAXN];

int col[MAXN];

int ans[MAXN];

int n, m, lim;

void solve() {                   
	scanf("%d %d %d", &n, &m, &lim);

	for (int i = 0; i < n; ++i) {
		scanf("%d %d", &arr[i].fi, &arr[i].se);

		if (arr[i].se == 2) {
			arr[i].se = -1;
		}
	}

	for (int i = 0; i < n; ++i) {
		pt[i] = mp(arr[i].fi + arr[i].se * lim, i);
		pt[i].fi = (pt[i].fi % m + m) % m;
	}

	sort(pt, pt + n);
	int one = 0;

	for (int i = 1; i < n; ++i) {
		if (arr[i].se == arr[0].se) {
			continue;
		}

		if (arr[0].se == 1) {
		    int t = arr[i].fi - arr[0].fi;

		    if (0 <= t && t <= lim * 2) {
				one += ((2 * lim - t) / m + 1);		    	
		    }

		}
		else {
			int t = arr[0].fi - arr[i].fi + m;

			if (0 <= t && t <= lim * 2) {
				one -= ((2 * lim - t) / m + 1);
			}
		}
	}

    one = (one % n + n) % n;
    int p = 0;

    for (int i = 0; i < n; ++i) {
    	if (pt[i].se == 0) {
    		p = i;
    		break;
    	}
    }

    for (int i = 0; i < n; ++i) {
    	col[(p + i) % n] = (one + i) % n;
    }

    for (int i = 0; i < n; ++i) {
    	ans[col[i]] = pt[i].fi;
    }

    for (int i = 0; i < n; ++i) {
    	printf("%d\n", ans[i]);
    }
}

int main() {    
    int tt = 1;

    while (tt--) {
        solve();
    }

    return 0;
}

