		if (curdir == 2){
			// cout<<"Case 2\n";
			if (SZ(rblock) == 0)break;
			// cout<<"Tar "<<rblock[0]<<'\n';
			ll opploc = (rblock[0]+curtime)%L;
			ll meettime = ((curloc+L-opploc)/2);
			ll meetloc = (opploc + meettime);
			meettime += curtime;
			// cout<<"Meet at time "<<meettime<<" location "<<meetloc%L<<'\n';
			if (meettime > K)break;
			ll newstart = meetloc + meettime;
			lblock.pb(newstart);
			// cout<<"inserting "<<newstart<<" llo left \n";
			curtime = meettime;
			curloc = meetloc%L;
			// cout<<"New curloc "<<curloc<<'\n';
			rblock.pop_front();
			// break;
		}else{
			// cout<<"Case 1\n";
			// cout<<"Tar "<<lblock[0]<<'\n';
			if (SZ(lblock) == 0)break;
			ll opploc = lblock[0] - curtime;
			ll meettime = opploc - curloc;

			while (meettime<0)meettime+=L;
			meettime/= 2;
			ll meetloc = (meettime + curloc)%L;
			meettime += curtime;
			// cout<<"Meet at time "<<meettime<<" location "<<meetloc<<'\n';
			if (meettime > K)break;
			ll newstart = meetloc - meettime;
			rblock.pb(newstart);
			// cout<<"inserting "<<newstart<<" llo right \n";
			curtime = meettime;
			curloc = meetloc;
			lblock.pop_front();
		}
		curdir = 3-curdir;
		// cout<<'\n';
		// break;
	}
	// cout<<curdir<<' '<<curloc<<' '<<curtime<<'\n';
	ll timeleft = K-curtime;
	if (curdir == 2)curloc = (curloc + timeleft)%L;
	else curloc = (curloc + L - timeleft)%L;
	// cout<<curloc<<'\n';
	// cout<<offset<<'\n';
	// for (auto i : E)cout<<((i+offset)%L/2)<<' ';
	// return 0;
	while (E[0]!=curloc){
		// cout<<((E[0] + offset)%L/2)<<'\n';
		E.pb(E[0]);
		E.pop_front();
	}
	for (auto i : E)cout<<((i+offset)%L/2)<<'\n';
}

