tree<int, null_type, greater_equal<int>, rb_tree_tag, tree_order_statistics_node_update> gls, gms;
int main() {
	ios::sync_with_stdio(false);
	cin.tie(0);
	cin >> n >> l >> t;
	m = t%l;
	for(int i = 0; i < n; i++) {
		cin >> x[i] >> w[i];
		cnt[--w[i]]++;
	}
	for(int i = 0; i < n; i++) if(!w[i]) gms.insert(x[i]);
	for(int i = 0; i < n; i++) {
		if(w[i]) {
			int fl = gls.order_of_key(x[i]-2*m) + gls.order_of_key(x[i]-2*(m-l));
			int fm = gms.order_of_key(x[i]+l-2*m) + gms.order_of_key(x[i]+l-2*(m-l));
			res[(n+i-(fl+fm)%n)%n] = (x[i]-m+l)%l;
		} else {
			gls.insert(*gms.begin());
			gms.erase(gms.begin());
		}
	}
	for(int i = 0; i < n; i++) if(w[i]) lms.insert(x[i]);
	for(int i = 0; i < n; i++) {
		if(!w[i]) {
			int fl = lls.order_of_key(x[i]-l+2*m) + lls.order_of_key(x[i]-l+2*(m-l));
			int fm = lms.order_of_key(x[i]+2*m) + lms.order_of_key(x[i]+2*(m-l));
			res[(i+fl+fm)%n] = (x[i]+m)%l;
		} else {
			lls.insert(*lms.begin());
			lms.erase(lms.begin());
		}
	}
	for(int i = 0; i < n; i++) cout << res[i] << endl;
}

