ll count(ll p, ll x) {
	pi t = a[p];
	ll cnt = 0;
	for(auto i : a) {
		if(t.second==i.second) continue;
		int z = (t.second==1?i.first-t.first:t.first-i.first)%l;
		if(z<0) z += l;
		cnt += z <= 2*x;
	}
	return cnt;
}
pi calc(int i) { // {pos, val}
	ll np = count(i, l)*(t/l) + count(i, t%l);
	//cout << count(i, t) << ", ";
