void unit(ll a,ll b){
  a=root(a);
  b=root(b);
  if(a==b)return;
  if(len[a]<len[b]){
    par[a]=b;
    ele[b]+=ele[a];
  }
  else{
    par[b]=a;
    ele[a]+=ele[b];
    if(len[a]==len[b])len[a]++;
  }
}
