using namespace std;

struct Ant {
  int pos;
  bool dir;
};

ostream& operator<<(ostream& os, const Ant& a)
{
  os << a.pos << "|" << a.dir;
  return os;
}

int cross(int max, int L, const Ant& a, const Ant& b)
{
  if ((a.dir and b.dir) or (!a.dir and !b.dir) or a.pos == b.pos) return max;
  if (a.dir and !b.dir) return ((L + b.pos - a.pos) % L)/2;
  return ((L + a.pos - b.pos) % L)/2;
}

int main()
{
  int N, L, T;
  cin >> N >> L >> T;
  vector<Ant> as(N);

  for (int i = 0; i < N; ++i) {
    int d;
    cin >> as[i].pos >> d;
    as[i].dir = d == 1;
  }

  int T2 = 2*T;
  int L2 = 2*L;
  for (auto& a: as) a.pos *= 2;

  for (int t = 0; t < T2; ) {
    int left = T2 - t;
    int min_t = left;
    for (int now = 0; now < as.size(); ++now) {
      int next = (now + 1) % N;
      int tt = cross(left, L2, as[now], as[next]);
      // cout << as[now] << " " << as[next] << ": " << tt << endl;
      if (min_t > tt) min_t = tt;
    }
    for (auto& a: as) a.pos = (L2 + a.pos + (a.dir ? min_t : -min_t)) % L2;
    for (int now = 0; now < as.size(); ++now) {
      int next = (now + 1) % N;
      if (as[now].pos == as[next].pos) swap(as[now], as[next]);
    }
    t += min_t;
  }

  for (const auto& a: as) cout << a.pos/2 << endl;
  return 0;
}

