#include<bits/stdc++.h>
using namespace std;
#define MAX_N 200005

typedef long long ll;

ll L,N,T;

ll X[200005];
ll W[200005];
ll t[200005];
ll sum[200005];
ll ans[200005];

ll f(ll x){
  while(x<0)x+=L;
  return x%L;
}

ll calc(int left,int right,int type){
  if(type==1)return sum[right]-sum[left];
  else return (right-left)-(sum[right]-sum[left]);
}

void solve(){
  ll loop=T*2/L;
  ll nt=T*2%L;

  int h=0;

  for(int i=0;i<N;i++){
    if(W[i]==2)continue;
    ll key=i;
    key+=loop*(N-sum[N]);
    while(h<N+N&&(W[h]==1||X[h]-X[i]<=nt))h++;
    key+= calc(i,h,2);
    key%=N;
    ans[key]=t[i];
  }

  h=N+N-1;
  for(int i=N+N-1;i>=N;i--){
    if(W[i]==1)continue;

    ll key=i;
    key+= N-( loop*(sum[N]) )%N;

    while(h>=0&&(W[h]==2||X[i]-X[h]<=nt))h--;
    key+=(N- calc(h+1,i,1))%N;

    key%=N;
    //    cout<<calc(h+1,i,1)<<' '<<key<<endl;
    //    cout<<key<<' '<<t[i]<<endl;

    ans[key]=t[i];
  }
}


