  cin>>N>>L>>T;


  for(int i=0;i<N;i++){
    cin>>X[i]>>W[i];
    if(W[i]==1){
      t[i]=X[i]+T;
    } else{
      t[i]=X[i]-T;
    }
    t[i]=f(t[i]);
  }

  for(int i=0;i<N;i++){
    X[i+N]=X[i]+L;
    W[i+N]=W[i];
    t[i+N]=t[i];
  }

  for(int i=1;i<=N*2;i++){
    sum[i]=sum[i-1];
    if(W[i-1]==1)sum[i]++;
  }


  solve();

  for(int i=0;i<N;i++)
    cout<<ans[i]<<endl;
  return 0;
}

