	cin >> n >> L >> T;
	vector<int> x(n), dir(n);
	vector<int> pos(n);
	for (int i = 0; i < n; ++i) {
		cin >> x[i] >> dir[i];
		dir[i] = (dir[i] == 1) ? 1 : -1;
		pos[i] = (((x[i] + dir[i] * T) % L) + L) % L;
	}

	int clockwise = -1;
	for (int i = 0; i < n; ++i) {
		if (dir[i] == 1) {
			clockwise = i;
			break;
		}
	}
	int obg = 0;
	if (clockwise != -1) {
		for (int i = 0; i < n; ++i) {
			if (dir[i] == 1) {
				continue;
			}
			int diff = ((x[i] - x[clockwise]) + L) % L;
			//cout << diff << " " << i + 1 << endl;
			if (2 * T < diff) continue;
			obg += (2 * T - diff) / L + 1;
		}
	}
	obg %= n;
	//cerr << obg << endl;
	for (int i = n - obg; i < n; ++i) {
		cout << pos[i] << "\n";
	}
	for (int i = 0; i < n - obg; ++i) {
		cout << pos[i] << "\n";
	}

}

