typedef long long ll;

const int MAXN = (int)1e5 + 5;

pair<ll, int> arr[MAXN];

vector<ll> tmp[2];

int ans[MAXN];

int n, m, lim;

ll col[MAXN];

void solve() {                   
	scanf("%d %d %d", &n, &m, &lim);	

    for (int i = 0; i < n; ++i) {
		scanf("%lld %d", &arr[i].fi, &arr[i].se);
        --arr[i].se;
    }

    for (int i = 1; i < n; ++i) {
    	if (arr[i].se == arr[0].se) {
    		continue;
    	}

    	if (arr[0].se == 0) {
    		int t = arr[i].fi - arr[0].fi;

    		if (0 <= t && t <= 2 * lim) {
    			col[0] += ((2 * lim - t) / m + 1);
    		}                            	
    	}
    	else {
    		int t = arr[0].fi - arr[i].fi + m;

    		if (0 <= t && t <= 2 * lim) {
    			col[0] -= ((2 * lim - t) / m + 1);
    		}                        
    	}
    }

    for (int i = 1; i < n; ++i) {
    	col[i] = col[i - 1] + 1;
    }    

    for (int i = 0; i < n; ++i) {
    	col[i] = (col[i] % n + n) % n;
    }                 

    for (int i = 0; i < n; ++i) {
    	ll p = (arr[i].se ? arr[i].fi - lim : arr[i].fi + lim);
    	ans[col[i]] = (p % m + m) % m;
    }

    for (int i = 0; i < n; ++i) {
    	printf("%d\n", ans[i]);
    }
}

