	for (int i = 0; i < N; i++) {
		int a, b;
		scanf("%d%d", &a, &b);
		ori[i] = a;
		d[i] = b;
		if (b == 1) even.push_back((a + T) % L);
		else even.push_back((((a - T) % L) + L) % L);
		if (b == 1) r.push_back(a);
		else l.push_back(a);
		S.insert(d[i]);
	}
	if (S.size() == 1) {
		for (int i = 0; i < N; i++) {
			if (d[i] == 1) printf("%d\n", (ori[i] + T) % L);
			else printf("%d\n", ((((ori[i] - T) % L) + L) % L));
		}
		return 0;
	}
	sort(even.begin(), even.end());
	pair<int, int> res = make_pair(-1, -1);
	T *= 2;
	int oriT = T;
	if (d[0] == 1) {
		if (T <= l[0] - r[0]) {
			res = make_pair(1, 0);
		} else {
			T -= l[0] - r[0];
			long long bot = 0, top = 20000000005ll, mid;
			while (bot + 1 < top) {
				mid = (bot + top) / 2;
				long long val = 0;
				long long ls = mid / 2, rs = mid - ls;
				val += (ls / l.size()) * L;
				for (int i = 0; i < rs % r.size(); i++) {
					val += (((r[(r.size() - i) % r.size()] - r[(r.size() - i - 1)]) + L) % L) * 1;
				}
				val += ((rs / r.size()) * L) * 1;
				for (int i = 0; i < ls % l.size(); i++) {
					//val += (((l[(l.size() - i) % .size()] - r[(r.size() - i - 1)]) + L) % L) * 1;
					val += (((l[(i + 1) % l.size()] - l[i]) + L) % L) * 1;
				}
				if (val > T) top = mid;
				else if (val == T && mid % 2 == 1) top = mid;
				else bot = mid;
			}
			if (bot % 2 == 0) res = make_pair(2, (bot/2) % l.size());
			else res = make_pair(1, (r.size() - (bot/2+1) % r.size()) % r.size());
		}
	} else {
		assert(false);
		if (T <= L - (r[r.size() - 1] - l[0])) {
			res = make_pair(2, 0);
		} else {
			T -= L - (r[r.size() - 1] - l[0]);
			long long bot = 0, top = 20000000005ll, mid;
			while (bot + 1 < top) {
				mid = (bot + top) / 2;
				long long val = 0;
				long long rs = mid / 2, ls = mid - rs;
				val += (ls / l.size()) * L;
				for (int i = 0; i < rs % r.size(); i++) {
					val += (((r[(r.size() - i - 1) % r.size()] - r[(((int)r.size() - i - 2) + r.size()) % r.size()]) + L) % L) * 1;
				}
				val += ((rs / r.size()) * L) * 1;
				for (int i = 0; i < ls % l.size(); i++) {
					val += (((l[(i + 1) % l.size()] - l[i]) + L) % L) * 1;
				}
				if (val > T) top = mid;
				else if (val == T && mid % 2 == 0) top = mid;
				else bot = mid;
			}
			if (bot % 2 == 1) res = make_pair(2, (bot/2) % l.size());
			else res = make_pair(1, (r.size() - (bot/2+1) % r.size()) % r.size());
		}
	}
	int t = -1;
	if (res.first == 1) t = (r[res.second] + oriT/2) % L;
	else t = ((l[res.second] - oriT/2) % L + L) % L;
	int f = -1;
	for (int i = 0; i < even.size(); i++) {
		if (even[i] == t) {
			f = i;
		}
	}
	for (int i = 0; i < N; i++) printf("%d\n", even[(f + i) % even.size()]);
}

