long long N, L, T, f1, f2, X[100000], W[100000], ans[100000];
vector<int> o, t;

int solve(int p){
	int ok, ng;
	if(W[p] == 1){
		ng = -1, ok = t.size();
		while(abs(ok - ng) > 1){
			int mid = (ok + ng)/2;
			if(t[mid] > X[p]) ok = mid;
			else ng = mid;
		}
		int next = ok % (t.size());
		ok = -1, ng = o.size();
		while(abs(ok - ng) > 1){
			int mid = (ok + ng)/2;
			if(o[mid] < X[p]) ok = mid;
			else ng = mid;
		}
		int prev = (ok + o.size()) % o.size();
		int ok = 0, ng = 2000000001;
		while(ng - ok > 1){
			int mid = (ok + ng)/2;
			long long cost;
			if(mid == 1){
				cost = t[next] - X[p];
			}else if(mid == 2){
				cost = t[next] - o[prev];
			}else{
				int d = ((mid+1)/2 - 1) / t.size();
				int e = ((mid+1)/2 - 1) % t.size();
				cost = t[next] - X[p] + d * L;
				if(next + e >= t.size()){
					cost += t[(next+e)%t.size()] + L - t[next];
				}else{
					cost += t[next+e] - t[next];
				}
				if(cost <= 2*T){
					ok = mid;
				}else{
					ng = mid;
				}
			}
		}
		if(ok % 2 == 0){
			int bb = (prev - ((ok/2)%o.size()) + 1) % o.size();
			return (o[bb] + T) % L;
		}else{
			int bb = (next + ((ok/2)%t.size()) - 1) % t.size();
			return (t[bb] - (T/L) + L) % L;
		}
	}else{
		ng = -1, ok = o.size();
		while(abs(ok - ng) > 1){
			int mid = (ok + ng)/2;
			if(o[mid] > X[p]) ok = mid;
			else ng = mid;
		}
		int next = ok % (o.size());
		ok = -1, ng = t.size();
		while(abs(ok - ng) > 1){
			int mid = (ok + ng)/2;
			if(t[mid] < X[p]) ok = mid;
			else ng = mid;
		}
		int prev = (ok + t.size()) % t.size();
		int ok = 0, ng = 2000000001;
		while(ng - ok > 1){
			int mid = (ok + ng)/2;
			long long cost;
			if(mid == 1){
				cost = o[next] - X[p];
			}else if(mid == 2){
				cost = o[next] - t[prev];
			}else{
				int d = ((mid+1)/2 - 1) / o.size();
				int e = ((mid+1)/2 - 1) % o.size();
				cost = o[next] - X[p] + d * L;
				if(next + e >= o.size()){
					cost += o[(next+e)%o.size()] + L - o[next];
				}else{
					cost += o[next+e] - o[next];
				}
				if(cost <= 2*T){
					ok = mid;
				}else{
					ng = mid;
				}
			}
		}
		if(ok % 2 == 0){
			int bb = (prev - ((ok/2)%t.size()) + 1) % t.size();
			return (t[bb] - (T/L) + L) % L;
		}else{
			int bb = (next + ((ok/2)%o.size()) - 1) % o.size();
			return (o[bb] + T) % L;
		}
	}
}

int main(){
	cin >> N >> L >> T;
	for(int i=0; i<N; i++){
		cin >> X[i] >> W[i];
		if(W[i] == 1){
			o.push_back(X[i]);
			ans[i] = (X[i] + T) % L;
			f1 = 1;
		}else{
			t.push_back(X[i]);
			ans[i] = (X[i] - (T/L) + L) % L;
			f2 = 1;
		}
	}
	if(f1 * f2 == 0){
		for(int i=0; i<N; i++) cout << ans[i] << endl;
	}else{
		for(int i=0; i<N; i++){
			int t = solve(i);
			cout << t << endl;
		}
	}
	return 0;
}

