	ll i, j;
	vll X, W;
	for (i = 0; i < N; i++){
		ll x, w;
		cin >> x >> w;
		X.push_back(x);
		W.push_back(w);
	}
	vll Pos(N);
	for (i = 0; i < N; i++){
		if (W[i] == 1){
			Pos[i] = (X[i] + T) % L;
		}
		else{
			Pos[i] = (X[i] + L - (T%L)) % L;
		}
	}
	sort(Pos.begin(), Pos.end());
	ll s = find_index(W, 1);
	if (s == -1){
		for (i = 0; i < N; i++){
			cout << (X[i] + L - T) % L << endl;
		}
	}
	else{
		ll adv = accumulate(W.begin(), W.end(), 0) - N;
		ll c = 0;
		ll am;
		if (L % 2 == 0){
			am = (T % (L / 2)) * 2;
		}
		else{
			am = ((2 * T) % L);
		}
		for (i = 1; i < N; i++){
			ll tmp = X[(s + i) % N] - X[s];
			if (tmp >= am || (tmp<0 && L + tmp > am)){
				break;
			}
			else if (W[i] == 2){
				c++;
			}
		}
		c += adv*ll((T * 2) / L);
		c = c % N;
		ll ind = find_index(Pos, (X[s] + T) % L);
		for (i = 0; i < N; i++){
			cout << Pos[(ind + N + N - s - c + i) % N] << endl;
		}
	}
	return 0;
}

