const int mod = 1000000007;

long long pw(long long a, long long b) {
	long long res = 1;
	while (b) {
		if (b & 1ll) {
			res = res * a % mod;
		}
		b >>= 1;
		a = a * a % mod;
	}
	return res;
}

int main(){
	int n = nxt(), l = nxt(), t = nxt();
	vector<int> a(n);
	vector<int> w(n);
	for (int i = 0; i < n; ++i) {
		a[i] = nxt();
		w[i] = 3 - 2 * nxt();
	}

	int shift = accumulate(all(w), 0);
	if (shift < 0) {
		shift += n;
	}
	rotate(a.begin(), a.begin() + (1ll * (t / l) * shift) % n, a.end());
	t %= l;

	vector<int> new_pos(n);
	for (int i = 0; i < n; ++i) {
		new_pos[i] = a[i] + t * w[i];
		new_pos[i] %= l;
		if (new_pos[i] < 0) {
			new_pos[i] += l;
		}
	}
	sort(all(new_pos));

	if (n == 1) {
		cout << new_pos[0] << "\n";
		return 0;
	}

	long long sum = 1ll * accumulate(all(w), 0) * t;
	long long cur = accumulate(all(new_pos), 0ll) - accumulate(all(a), 0ll);
	// cerr << sum << " " << cur << "\n";

	long long diff = (sum - cur) / l;
	diff %= n;
	if (diff < 0) {
		diff += n;
	}
	rotate(new_pos.begin(), new_pos.begin() + diff, new_pos.end());
	for (int x : new_pos) {
		printf("%d\n", x);
	}

	return 0;
}

