    double T,T_copy;
    cin >> N >> L >> T;
    T_copy = T;
    vector<ll> X(N);
    vector<bool> W(N);//０なら時計回り,１なら反時計回り
    for(int i = 0; i < N; i++){
        cin >> X.at(i);
        int a;
        cin >> a;
        a--;
        W.at(i) = a;
    }

    vector<ll> afterX(N);
    for(int i = 0; i < N; i++){
        if(W.at(i)){//反時計回り
            afterX.at(i) = (((X.at(i) - (ll)T) % L) + L) % L;
        }else{
            afterX.at(i) = (X.at(i) + (ll)T) % L;
        }

    }

    ll through = 0;
    for(int i = 0; i < N; i++){
        if(W.at(0) != W.at(i)){

            ll sa;
            if(!W.at(0)){//時計回り
                if(X.at(0) >= X.at(i)){
                    sa = (L-X.at(0)) + X.at(i);
                }else{
                    sa =  X.at(i) - X.at(0);
                }
            }
            else{//反時計回り
                if(X.at(0) >= X.at(i)){
                    sa = X.at(0) - X.at(i);
                }else{
                    sa =  X.at(0) + (L - X.at(i));
                }
            }

            if(T >= sa / 2.0){
                through++;
                T -= sa / 2.0;
                through += int(T / (L / 2));
            }
        }
        T = T_copy;
    }

    ll position = 0;//蟻０の場所


    if(W.at(0)){//反時計回り
        position += through;
    }else{//時計回り
        position -= through;

    }


    position = ((position % N) + N) % N;
    ll P = afterX.at(position);

    vector<pair<ll,ll>> AfterX(N);
    for(int i = 0; i < N; i++){
        AfterX.at(i).first = afterX.at(i);
        AfterX.at(i).second = i;
    }
    sort(AfterX.begin(), AfterX.end());

    int I1,I2;
    int cnt = 0;
    for(int i = 0; i < N; i++){
        if(AfterX.at(i).first == P){
            if(cnt == 0){
                I1 = i;
                cnt++;
            }else if(cnt == 1){
                I2 = i;
                cnt++;
            }
        }
    }

    int I;
    if(cnt == 1){
        I = I1;
    }

    if(cnt == 2){
        if(W.at(0) + through){
            I = min(I1, I2);
        }else{
            I = max(I1, I2);
        }
    }


    for(int i = 0; i < N; i++){
        cout << AfterX.at(I).first << endl;
        I++;
        I %= N;
    }

}

