        w[i].num = i;
    }
    int s = 0, pv = 0;
    for(i=0;i<n;i++){
        s = (s + Calc(w[0],w[i]))%n;
    }
    for(i=0;i<n;i++){
        if(w[i].ck==1)w[i].x = (w[i].x + T)%L;
        else w[i].x = (w[i].x + L - T%L) % L;
    }
    sort(w,w+n);
    for(i=0;i<n;i++){
        if(!w[i].num)pv = i;
    }
    for(i=0;i<n;i++){
        Res[(i-pv+s+n)%n] = w[i].x;
    }
    for(i=0;i<n;i++)printf("%d\n",Res[i]);
}

