int main() {
    int N, L, T;
    int antX[100000];
    int antW[100000];
    cin >> N >> L >> T;
    for (int i = 0; i < N; ++i) {
        cin >> antX[i] >> antW[i];
    }
//    srand(0);
//    N = 100000;
//    L = rand() % 1000000000 + 1;
