const int N = 1e5 + 10;

int L, t;

int intersect(int x, int y) {
    return (y - x) / 2;
}

void solve(vector<pii> pts, vi & ans) {

    vi ones, zeros;
    int n = SZ(pts);


    fori (i, n) {
        if (pts[i].second)
            ones.push_back(pts[i].first - L);
        else
            zeros.push_back(pts[i].first);
    }

    reverse(ALL(ones));
    fori (i, n) {
        if (pts[i].second) {
            ones.pop_back();
            ones.insert(ones.begin(), pts[i].first);
            int l = -1, r = min(SZ(ones), SZ(zeros));
            while (r - l > 1) {
                int m = r + l >> 1;
                if (intersect(ones[m], zeros[m]) <= t) {
                    l = m;
                } else {
                    r = m;
                }
            }
            if (l == -1) {
                ans[i] = (pts[i].first + t) % L;
            } else {
                if (l + 1 < SZ(ones) && intersect(ones[l + 1], zeros[l]) <= t) {
                    ans[i] = (ones[l + 1] + t) % L;
                } else {
                    ans[i] = (zeros[l] - t + L) % L;
                }
            }
        } else {
            zeros.erase(zeros.begin());
            zeros.push_back(pts[i].first + L);
        }
    }
}

void smain() {

    int n;
    cin >> n >> L >> t;
    L <<= 1;
    t <<= 1;
    vector<pii> pts(n);
    fori (i, n) {
        cin >> pts[i].first >> pts[i].second;
        pts[i].first <<= 1;
        pts[i].second &= 1;
    }


    vi ans(n, -1);

    t %= L;

    solve(pts, ans);
    reverse(ALL(pts));
    reverse(ALL(ans));
    for (auto & item : pts) {
        item.second ^= 1;
        item.first = L - item.first - 2;
    }

    solve(pts, ans);
    reverse(ALL(ans));
    reverse(ALL(pts));
    fori (i, n) {
        if (pts[i].second) {
            ans[i] = L - ans[i] - 2;
        }
        ans[i] = (L + ans[i] % L) % L;
        cout << (ans[i] >> 1) << ' ';
    }



}

