int t, n, l;
struct Ant
{
    int x, w, idx;
    bool operator < (const Ant &ot) const
    {
        return x < ot.x;
    }
} v[maxN];
int ant1;

int ans[maxN];

void printAns()
{
    for (int i = 1; i <= n; ++ i)
        printf("%d\n", ans[i]);
}

int main()
{
    scanf("%d %d %d", &n, &l, &t);
    for (int i = 1; i <= n; ++ i)
    {
        scanf("%d %d", &v[i].x, &v[i].w);
        v[i].idx = i;
        if (v[i].w == 2)
            v[i].w = -1;
    }
    t %= l;
    sort(v + 1, v + n + 1);
    if (v[1].w == 1)
    {
        ant1 = 1;
        for (int i = 2; i <= n; ++ i)
            if ((v[i].x - v[1].x <= 2 * t) && v[i].w != v[1].w)
                ++ ant1;
        int ant = ant1 - 1;
        for (int i = 1; i <= n; ++ i)
        {
            ++ ant;
            if (ant > n)
                ant -= n;
            ans[v[ant].idx] = ((v[i].x + t * v[i].w) % l + l) % l;
        }
    }
    else
    {
        ant1 = 1;
        for (int i = n; i >= 1; -- i)
            if ((v[1].x - v[i].x + l <= 2 * t) && v[i].w != v[1].w)
            {
                -- ant1;
                if (ant1 == 0)
                    ant1 = n;
            }
        int ant = ant1 - 1;
        for (int i = 1; i <= n; ++ i)
        {
            ++ ant;
            if (ant > n)
                ant -= n;
            ans[v[ant].idx] = ((v[i].x + t * v[i].w) % l + l) % l;
        }
    }
    printAns();
    return 0;
}

