signed main(){
  cin.tie(0);
  ios::sync_with_stdio(false);
  ll N,L,T;
  cin>>N>>L>>T;
  L*=2; T*=2;
  vector<ll> X(N),W(N);
  deque<int> rg,lf;
  for(int i=0;i<N;i++){
    cin>>X[i]>>W[i];
    X[i]*=2;
    if(W[i]==1){rg.push_front(i);}
    else{lf.push_back(i);}
  }
  auto point=[&](int i){return (X[i]+T*L+(W[i]==1?1:-1)*T)%L/2;};
  if(rg.empty() || lf.empty()){
    for(int i=0;i<N;i++){
      cout<<point(i)<<endl;
    }
    return 0;
  }
  int rem=T%L;
  int div=T/L;
  int k=(int)rg.size()-(int)lf.size();
  int dif=(k*div%N+N)%N;
  int t=0,idx=0,w=W[0];
  if(w==2){ll tp=lf[0]; lf.pop_front();  lf.push_back(tp);}
  vector<pair<int,int>> tmp;
  while(1){
    tmp.push_back({t,idx});
    if(w==1){
      ll tp=lf[0];
      ll td=(X[tp]+L-X[idx])%L/2;
      while(td<=t){td+=L/2;}
      if(td>rem){break;}
      t=td;
      idx=tp;
      lf.pop_front();
      lf.push_back(tp);
    }
    else{
      ll tp=rg[0];
      ll td=(X[idx]+L-X[tp])%L/2;
      while(td<=t){td+=L/2;}
      if(td>rem){break;}
      t=td;
      idx=tp;
      rg.pop_front();
      rg.push_back(tp);
    }
    w^=3;
  }
  int C=idx;
  vector<pair<int,int>> pts(N);
  for(int i=0;i<N;i++){
    pts[i]={point(i),W[i]};
  }
  sort(pts.begin(),pts.end());
  int base=-1;
  for(int i=0;i<N;i++){
    if(pts[i].F==point(C) && pts[i].S==W[C]){
      base=i;
    }
  }
  assert(base!=-1);
  for(int i=0;i<N;i++){
    assert(pts[(i+base+dif)%N].F>=0 && pts[(i+base+dif)%N].F<L);
    cout<<pts[(i+base+dif)%N].F<<endl;
  }
  assert(unique(pts.begin(),pts.end(),[](pll a,pll b){return a.F==b.F;})==pts.end());
  return 0;
}

