    while (true) {
        // 最短でぶつかるアリを検索
        double minTime = 1000000000.0;
        bool flag = false;
        int minIndex = 0;
        for (int i = 0; i < N; ++i) {
            double time;
            if (i == N - 1) {
                if (antW[0] - antW[i] == 1) {
                    int x = antX[0] - antX[i];
                    if (x < 0) {
                        x += L;
                    }
                    time = x / 2.0;
                    if (minTime > time) {
                        minTime = time;
                        minIndex = i;
                        flag = true;
                    }
                }
            }
            if (antW[i + 1] - antW[i] == 1) {
                int x = antX[i + 1] - antX[i];
                if (x < 0) {
                    x += L;
                }
                time = x / 2.0;
                if (minTime > time) {
                    minTime = time;
                    minIndex = i;
                    flag = true;
                }
            }
        }
//        cout << "mintime : " << minTime << endl;
        // ありを最小単位で更新
        if (flag && totalTime + minTime <= T) {
            for (int i = 0; i < N; ++i) {
                if (antW[i] == 1) {
                    antX[i] = (antX[i] + minTime);
                } else{
                    antX[i] = (antX[i] - minTime);
                }
                while (antX[i] >= L) {
                    antX[i] -= L;
                }
                while (antX[i] < 0) {
                    antX[i] += L;
                }
//                cout << "x : " << antX[i] << endl;
            }
            for (int i = 0; i < N; ++i) {
                int index1 = i;
                int index2 = (i == N - 1) ? 0 : i + 1;
                if (antX[index1] == antX[index2]) {
                    antW[index1] = 2;
                    antW[index2] = 1;
                }
            }
//            if (minIndex == N - 1) {
//                antW[0] = 1;
//                antW[minIndex] = 2;
//            } else {
//                antW[minIndex + 1] = 1;
//                antW[minIndex] = 2;
//            }
            totalTime += minTime;
//            cout << "totalT : " << totalTime << endl;
            if (totalTime >= T) {
                break;
            }
        } else {
            for (int i = 0; i < N; ++i) {
                if (antW[i] == 1) {
                    antX[i] = (antX[i] + T - totalTime);
                } else{
                    antX[i] = (antX[i] - T + totalTime);
                }
                while (antX[i] >= L) {
                    antX[i] -= L;
                }
                while (antX[i] < 0) {
                    antX[i] += L;
                }
            }
            break;
        }
    }
    // 出力
    for (int i = 0; i < N; ++i) {
        cout << antX[i] << endl;
    }
    return 0;
}

