int main() {
	lnt n,l,t;
	std::cin >> n >> l >> t;
	std::vector<lnt> x(n),w(n),y(n);
	rep(i,n) std::cin >> x[i] >> w[i];
	// find how many ants index 0 has collided with
	lnt zdir=w[0];
	lnt rcount=0;
	rep(i,n) if(w[i]!=zdir) rcount++;
	lnt shift=t/l*rcount*2;
	shift%=n;
	t%=l;
	rep(i,n) {
		if(w[i]==1) y[i]=x[i]+t;
		else y[i]=x[i]-t;
		if(w[i]==zdir) continue;
		lnt diff;
		if(zdir==1) diff=x[i]-x[0];
		else diff=x[0]-x[i]+l;
		if(2*t-diff>=l) shift+=2;
		else if(2*t>=diff) shift+=1;
	}
	std::vector<lnt> ans(n);
	rep(i,n) {
		if(zdir==1) ans[(i+shift)%n]=((y[i]%l)+l)%l;
		else ans[((i-shift)%n+n)%n]=((y[i]%l)+l)%l;
	}
	rep(i,n) std::cout << ans[i] << EL;
}

