int main() {
    ll n, l, t;
    cin >> n >> l >> t;
    VL x(n);
    VI w(n);
    REP(i,n) scanf("%lld %d", &x[i], &w[i]);
    ll s = 0, v = 0;
    REP(i,n){
        s += x[i];
        if (w[i] == 1) v++;
        else v--;
    }
    VL y(n);
    REP(i,n){
        if (w[i] == 1) y[i] = (x[i] + t) % l;
        else y[i] = (x[i] + l - t) % l;
    }
    sort(ALL(y));

    ll cm = (s + v*t) % (l*n);

    int ind = -1;
    ll c = 0;
    REP(i,n) c += y[i];

    REP(i,n){
        if (c == cm){
            ind = i;
            break;
        }
        c = (c + l) % (l*n);
    }

    assert(ind != -1);

    REP(i,n){
        printf("%lld\n", y[(ind+i)%n]);
    }

    return 0;
}

