#endif

	DWORD	min_pos, last_min, min_idx;
	DWORD zero_ant_Idx;
	cin >> N >> L >> T;

	min_pos = L;
	last_min = L;

	//アリの位置＝first　向き＝second(1or-1に直す)
	for (int i = 0; i < N; i++) {
		PAIR ant;

		//初期値を挿入
		cin >> ant.first >> ant.second;
		if (ant.second == 2) ant.second = -1;
		vAnts.push_back(ant);

	}

	//[0]のアリが何回衝突するかを求める
	HitCntOfZeroAnt();

	// T秒進める
	for (int i = 0; i < N; i++) {
		vAnts[i].first = RevisePos(vAnts[i].first + (vAnts[i].second * T));
	}

	//衝突回数から0番目のアリのインデックスを求める
	if (vAnts[0].second == 1) {
		zero_ant_Idx = ((N - 1) - ((hit - 1) % N));
	} else if (vAnts[0].second == -1) {
		zero_ant_Idx = (hit + 1) % N;
	}

	DWORD antId = zero_ant_Idx;
	for (int cnt = 0; cnt < N; cnt++) {
		cout << vAnts[antId].first << endl;

		if ((antId + 1) >= N) {
			antId = 0;
		} else { 
			antId++;
		}
	}
	return 0;
}

