    if(w[i]==1){
      x_t[i] = (x[i] + t)%l;
    }else{
      x_t[i] = (x[i] - t + t * l)%l;
    }
  }
  ll zero_pos = x_t[0];
  sort(x_t,x_t+n);
  ll cross_cnt = 0;
  for(ll i = 1; i < n; i++){
    if(w[0]==1&&w[i]==2){
