      cross_cnt -= floor((t-(x[0]-x[i]+l)%l/2.0)/(l/2.0))+1;
    }
  }
  cout << cross_cnt << endl;
  ll zero_ind = cross_cnt>=0 ? cross_cnt%n : n+cross_cnt%n ;
  ll zero_ord = lower_bound(x_t,x_t+n,zero_pos) - x_t;
  vector<pair<ll,ll> > ants;
