				to -= dis/L;
			}
			if(to < 0){
				to += ((-1 * to)/N + 1)*N;
				to %= N;
			}
		}
		//cout << "after " << i << " to = " << to << endl;
	}


	for(long long i = 0; i < N; i++){
		if(W[i] == 1){
			X[i] += T;
			X[i] %= L;
		}else{
			X[i] -= T;
			if(X[i] < 0){
				X[i] += ((-1 * X[i])/L + 1)*L;
				if(X[i] < 0){
					return 1;
