int main(){
    ll first_ant_w = 0;
    ll second_ant_reverse = -1;
    ios::sync_with_stdio(false);
    cin >> N >> L >> T;
    bool recorded = false;
    REP(i, N) {
        cin >> X[i] >> W[i];
        if (i==0) first_ant_w = W[i];
        if (!recorded && first_ant_w!=W[i]) {
            second_ant_reverse = i;
            recorded = W[0]==1;
        }
     }

    // 一つ目のアリの最終的なゼッケン番号を求める
    ll lastf = 0;
    int cnt=0;
    REP(i,N) {

        if(W[0]!= W[i]) {
            double t = T;
            ll fx = X[0];
            ll sx = X[i];
            if (W[0]==2) {
                swap(fx,sx);
            }

            while(fx > sx) {
                sx+=L;
            }
            if(ll((sx-fx-1)/2.0 + 1) <= t) {
                cnt++;
                t-=ll((sx-fx-1)/2.0 + 1);
            }
            cnt += (ll)(t*2 / L);
        }
    }
    if (W[0]==2) {
        lastf = INF * L;
        lastf -= cnt;

    } else {
        lastf += cnt;
    }
    lastf %= L;

    // 反時計の蟻はINF×N周足しておく
    REP(i,N) {
        if (W[i]==2) {
            X[i]+=INF*L;
        }
    }

    // T秒後の座標を求める
    vector<ll> ans;
    REP(i,N) {
        if(W[i]==2) {
            X[i]-=T;
        } else {
            X[i]+=T;
        }
        X[i]%=L;
        ans.pb(X[i]);
        ans.pb(X[i]+L);
        ans.pb(X[i]+L+L);
    }
    sort(ans.begin(), ans.end());
    ll zekken = lastf;
    int cntst = 0;

    for(auto x: ans) {
        if (cntst) {
            ansc[zekken%N] = x%L;
            zekken++;
        } else if(X[0]==x) {
            ansc[zekken%N] = x%L;
            cntst = 1;
            zekken++;
        }
    }

    REP(i, N) {
        cout << ansc[i] << endl;
    }

    return 0;
}

