    }
    sort(b, b + n);
    int rot = lower_bound(b, b + n, ((a[0] + dir[0] * k) % m + m) % m) - b;
    for (int i = 1; i < n; ++i)
        rot += (Collide(0, i) ? -dir[0] : 0);
    rot = (rot % n + n) % n;
    rotate(b, b + rot, b + n);
    for (int i = 0; i < n; ++i)
        printf("%d\n", b[i]);
    return 0;
}

