using namespace std;

int main(){
  const int n = getInt();
  const int l = getInt();
  const int t = getInt();

  vector<int> x(n);
  vector<int> w(n);

  REP(i,n){
    x[i] = getInt();
    w[i] = getInt();
  }

  int k = 0;
  while(k != n && w[k] != 1) k++;

  if(k == n){
    REP(i,n){
      int p = (x[i] - t) % l;
      if(p < 0) p += l;
      printf("%d\n", p);
    }
    return 0;
  }

  int cnt = 0;
  queue<int> q;
  REP(i,n) if(w[(k + i) % n] == 2) q.push(x[i]);

  if(q.size() == 0){
    REP(i,n) printf("%d\n", (x[i] + t) % l);
    return 0;
  }

  int tt = 0;
  int pos = x[k];

  while(true){
    int next = (q.front() - tt) % l; q.pop();
    if(next < 0) next += l;

    if(next < pos) next += l;
    const int diff = next - pos;

    const int d2 = diff / 2 + diff % 2;
    if(tt + d2 <= t){
      tt += d2;
      cnt++;
      pos = (pos + d2) % l;
      // printf("%d: %d\n", tt, pos);

      q.push((pos + l - diff % 2) % l);
    }else{
      break;
    }
  }

  vector<int> ans(n);
  REP(i,n){
    const int idx = (k + i) % n;
    int xx = (x[idx] + (w[idx] == 1 ? t : -t)) % l;
    if(xx < 0) xx += l;
    ans[(k + i + cnt) % n] = xx;
  }
  REP(i,n) printf("%d\n", ans[i]);

  return 0;
}

