    vector<int> x(n), w(n);
    forn (i, n) {
        cin >> x[i] >> w[i];
    }
    int id = -1;
    int idDist = 1e9;
    forn (i, n) {
        if (w[i] == 2)
            continue;
        int i2 = (i+1)%n;
        if (w[i2] != 2)
            continue;
        if (id == -1 || cnorm(x[i2] - x[i]) > idDist) {
            id = i;
            idDist = cnorm(x[i2] - x[i]);
        }
    }

    vector<int> coord(n);
    int idc = -1;
    forn (i, n) {
        coord[i] = cnorm(x[i] + (w[i] == 1 ? 1 : -1) * t);
        //cerr << i << ' ' << coord[i] << '\n';
        if (i == id)
            idc = coord[i];
    }
    sort(coord.begin(), coord.end());
    int idpos = lower_bound(coord.begin(), coord.end(), idc) - coord.begin();
