ll ans[100000];
vector<ll> l,r;

ll solve(ll id){
	ll pos=x[id];
	ll t=T;
	ll cnl,cnr;	
	l.clear();
	r.clear();
	ll pos1=pos;
	ll pos2=pos;
	ll i=id+1;
	while(1){
		i%=N;
		if(i==id) break;
		if(w[i]==1){i++; continue;}
		r.pb( (x[i]-pos1+L)%L );
		pos1=x[i];
		i++;
	}
	i=id-1;
	while(1){//for(ll i=id-1;i!=id;i--){
		i=(i+N)%N;
		if(i==id) break;
		if(w[i]==2) {i--; continue;}
		l.pb( (pos2-x[i]+L)%L );
		pos2=x[i];
		i--;
	}
	if(w[id]==1){
		if(l.size()==0){
			l.pb(L);
		}
		else{
			l.pb( (pos2-x[id]+L)%L );
		}
	}
	else{
		if(r.size()==0){
			r.pb(L);
		}
		else{
			r.pb( (pos1-x[id]+L)%L );
		}
	}

	ll cnt=w[id];
	cnl=0;
	cnr=0;
	/*rep(i,r.size()){
		cout<<r[i]<<" a ";
	}
	cout<<endl;
	rep(i,l.size()){
		cout<<l[i]<<" a ";
	}*/
	while(1){
		if(cnt%2==1){//とけい
			if(r.size()==0){
				return (pos+t)%L;
			}
			cnr%=r.size();
			if(r[cnr]/2>=t){
				return (pos+t)%L;
			}
			pos+=r[cnr]/2;
			t-=r[cnr]/2;
			cnr++;
		}
		else{
			if(l.size()==0){
				return ((pos-t)%L+L)%L;
			}
			cnl%=l.size();
			if(l[cnl]/2>=t){
				return ((pos-t)%L+L)%L;
			}
			pos-=l[cnl]/2;
			t-=l[cnl]/2;
			cnr++;
		}
		cnt++;
	}
}

int main()
{
	cin>>N>>L>>T;
	L*=2;
	T*=2;
	rep(i,N){
		cin>>x[i]>>w[i];
		x[i]*=2;
		if(w[i]==1){
			ans[i]=(x[i]+T)%L;
		}
		else{
			ans[i]=((x[i]-T)%L+L)%L;
		}
	}
	sort(ans,ans+N);
	ll m=solve(0);
	ll n=solve(1);
	ll ori;
	if(m==n){
		ori=lower_bound(ans,ans+N,m)-ans;
	}
	else{
		ori=upper_bound(ans,ans+N,m)-ans-1;
	}
	rep(i,N){
		cout<<ans[(i+ori)%N]/2<<endl;
	}
}

