    vector<long long> num(N);
    for(int i=0; i<N; i++){
        if(XW[i].second == 1)
            num[i] = (i + cross[i]) % N;
        else
            num[i] = (i - cross[i] + 2 * N * T) % N;
    }

    vector<long long> ans(N);
