    while(r<=l){
      cur%=n;
      if(a[cur].second==1){
        if(a[r].second!=2||a[l].first>a[cur].first){
          r++;
          r%=n;
          continue;
        }
        cur=r;
        r++;
        r%=n;
      }
      else{
        if(a[l].second!=1||a[l].first<a[cur].first){
          l--;
          continue;
        }
        cur=l;
        l+=n-1;
        l%=n;
      }
