int main () {
	std::ios::sync_with_stdio (0);
	std::cin >> N >> L >> T;
	for (long long i = 0; i < N; ++i) 
		std::cin >> X[i] >> W[i];
	for (long long i = 0; i < N; ++i)
		fin[i] = ((X[i] + (W[i] == 1 ? 1ll : -1ll) * T) % L + L) % L;

	std::vector <int> rid, st;
	for (long long i = 0; i < N; ++i)
		if (W[i] == 1) 
			rid.push_back (i);
		else
			st.push_back (i);
	if (rid.size () == 0 || st.size () == 0) {
		for (long long i = 0; i < N; ++i)
			std::cout << fin[i] << std::endl;
		return 0;
	}

	std::sort (fin, fin + N);
	long long currid = 0, curst;
	for (curst = 0; curst < st.size (); ++curst)
		if (X[st[curst]] > X[rid[currid]]) break;
	if (curst == st.size ()) curst = 0;
	long long curt = 0, curloc;
	while (true) {
		long long dist = (X[st[curst]] - X[rid[currid]] + L) % L;
		if (curt + dist >= T * 2) {
			curloc = (X[rid[currid]] + T) % L;
			break;
		}
		curt += dist;
		currid = (currid + rid.size () - 1) % rid.size ();
		dist = (X[st[curst]] - X[rid[currid]] + L) % L;
		long long k = (curt - dist + L - 1) / L;
		long long res = k * L + dist;
		if (res >= T * 2) {
			curloc = ((X[st[curst]] - T) % L + L) % L;
			break;
		}
		curst = (curst + 1) % st.size ();
	}
	long long bep;
	for (long long i = 0; i < N; ++i) {
		if (curloc == fin[i]) {
			bep = (i - rid[0] + N) % N;
			break;
		}
	}
	for (long long i = 0; i < N; ++i)
		std::cout << fin[(i + bep) % N] << std::endl;
}

