const int N = 1e5 + 10;

int L, t;

int intersect(int x, int y) {
    return (y - x) / 2;
}

const int DIF = 100;

void solve(vector<pii> pts, vi & ans) {

    vi ones, zeros;
    int n = SZ(pts);


    fori (i, n) {
        if (pts[i].second) {
            for (int dif = -DIF; dif <= DIF; ++dif) {
                ones.push_back(pts[i].first + dif * L);
            }
        } else {
            for (int dif = -DIF; dif <= DIF; ++dif) {
                zeros.push_back(pts[i].first + dif * L);
            }
        }
    }

    sort(ALL(ones));
    sort(ALL(zeros));


    fori (i, n) {
        if (pts[i].second) {
            int mone = lower_bound(ALL(ones), pts[i].first) - ones.begin();
            int mzero = upper_bound(ALL(zeros), pts[i].first) - zeros.begin();

            int l = -1 , r = min(mone, SZ(zeros) - mzero) + 1;
            while (r - l > 1) {
                int m = r + l >> 1;
                if (intersect(ones[mone - m], zeros[mzero + m]) <= t) {
                    l = m;
                } else {
                    r = m;
                }
            }
            if (l == -1) {
                ans[i] = pts[i].first + t;
            } else if (mone - l - 1 >= 0) {
                assert(mone - l - 1 >= 0);
                if (intersect(ones[mone - l - 1], zeros[mzero + l]) <= t) {
                    ans[i] = ones[mone - l - 1] + t;
                } else {
                    ans[i] = zeros[mzero + l] - t;
                }
            }
        } else {
            int mone = lower_bound(ALL(ones), pts[i].first) - ones.begin() - 1;
            int mzero = lower_bound(ALL(zeros), pts[i].first) - zeros.begin();

            int l = -1 , r = min(mone, SZ(zeros) - mzero);
            while (r - l > 1) {
                int m = r + l >> 1;
                if (intersect(ones[mone - m], zeros[mzero + m]) <= t) {
                    l = m;
                } else {
                    r = m;
                }
            }
            if (l == -1) {
                ans[i] = pts[i].first - t;
            } else {
                assert(mone + l - 1 >= 0);
                if (intersect(ones[mone - l], zeros[mzero + l + 1]) <= t) {
                    ans[i] = zeros[mzero + l + 1] - t;
                } else {
                    ans[i] = ones[mone - l] + t;
                }
            }
        }
    }

}

