    cin >> n >> l >> t;
    vi x(n), w(n);
    rep(i, n) cin >> x[i] >> w[i];
    vi y(n);
    rep(i, n) {
        int v = (w[i]==1?1:-1);
        y[i] = (x[i] + v * (t % l)) % l;
        if (y[i] < 0) y[i] = (l+y[i])%l;
    }
    vi rev;
    rep1(i, n-1) if (w[0] != w[i]) {
        rev.pb(x[i]);
    }
    ll cnt = sz(rev) * (t / l) * 2;
    for (int val : rev) {
        int dis = 0;
        if (w[0]==1) dis = val - x[0];
        else dis = x[0]+l-val;
        if (dis/2.0<=t%l) ++cnt;
        if (dis/2.0+l/2.0<=t%l) ++cnt;
    }
    int num = (w[0]==1?cnt%n:(n+(-cnt)%n)%n);
    vi ans(n);
    rep(i, n) ans[(num+i)%n] = y[i];
    rep(i, n) cout << ans[i] << endl;
