#define int long long

int n, l, t;
int x[100011], w[100011], pos[100011];
int ans[100011], p[200011];

int cal() // Numbers of collisions between ant 0 and the others.
{
	int cnt = 0;
	for (int i = 1; i < n; i++)
		if (w[i] != w[0])
		{
			int d = 0;
			if (w[0] == 1 && w[i] == 2)
			{
				if (x[0] < x[i]) d = x[i] - x[0];
				else d = l - x[0] + x[i]; 	
			}
			else 
			{
				if (x[0] > x[i]) d = x[0] - x[i];
				else d = l - x[i] + x[0];
			}
			if (2 * t >= d)
				cnt += (1 + (t * 2 - d)/l);
		}
	return cnt;	
}

int32_t main()
{
	ios::sync_with_stdio(false);
	cin.tie(0);
	cout.tie(0);

	//freopen( (filename + ".inp").c_str(), "r", stdin);
	//freopen( (filename + ".out").c_str(), "w", stdout);

	cin >> n >> l >> t;
	vector<int> final_pos;
	for (int i = 0; i < n; i++)
	{
		cin >> x[i] >> w[i];
		if (w[i] == 1) 
			pos[i] = (x[i] + t)%l;
		else pos[i] = ((x[i] - t)%l + l)%l;
		final_pos.push_back(pos[i]);
	}
	sort(final_pos.begin(), final_pos.end());
	if (final_pos.back() == final_pos[0]) // All ants have the same ending
	{
		for (int i = 0; i < n; i++)
			cout << final_pos[0] << '\n';
		return 0;
	}

	for (int i = 0; i < 2*n; i++)
	{
		if (i < n) p[i] = i;
		else p[i] = i - n;
	}

	int cnt = cal();
	int id = cnt % n;	
	if (w[0] == 2) id = ((n - cnt)%n + n)%n;
	//cerr << '?' << id << ' ' << pos[0] << '\n';
	// id is the index of the ant that its final pos is equal to pos[0]  
	// now find the next nearest ant that its final pos is not equal to pos[0], and val is the final pos of it
	int nxt = id, val = 0;
	if (w[0] == 1)
	{
		for (int i = 1; i < n; i++)
			if (w[i] == 1 && pos[i] != pos[0])
			{
				nxt = p[id + i];
				val = pos[i];
				break;
			}
	}
	else
	{
		for (int i = n; i > 1; i--)
			if (w[i] == 2 && pos[i] != pos[0])
			{
				nxt = p[id + i];
				val = pos[i];
				break;
			}
	}
	//cerr << '?' << nxt << ' ' << val << '\n';
	// since we have the id, the final pos of 1 ant, we create the answer using the previous final_pos array
	for (int i = 0; i < final_pos.size(); i++)
		if (final_pos[i] == val)
		{
			int cur = nxt;
			ans[cur] = val;
			//cerr << '!' << cur << ' ' << val << '\n';
			for (int j = (i + 1) % (int)(final_pos.size()); j != i; j = (j + 1) % (int)(final_pos.size()))
			{
				//cerr << '?' << final_pos[j] << '\n';
				cur++;
				//cerr << '!' << p[cur] << '\n';
				ans[p[cur]] = final_pos[j];
			}
		}
	for (int i = 0; i < n; i++)
		cout << ans[i] << '\n';
}

