        cin >> X[i] >> W[i];
        //cout << X[i] << W[i] << endl;
    }

    vector<int> v;
    for(i=0;i<N;i++){
        if(W[i]==1){
            v.push_back((X[i] + T) % L);
        }
        if(W[i]==2){
            v.push_back((((X[i] - T) % L) + L) % L);
        }
        //cout << v[i] << endl;
    }
    int cross = 0;
    double first;
    if(W[0]==1){
        for(i=1;i<N;i++){
            if(W[i]==2){
                first = (X[i] - X[0])/2.0 + 0.001;
                if(first < T){cross++;}
                cross += (int)((T - first)/L);
            }
        }
    }
    if(W[0]==2){
        for(i=1;i<N;i++){
            if(W[i]==1){
                first = (L - X[i] + X[0])/2.0 + 0.001;
                if(first < T){cross++;}
                cross += (int)((T - first)/L);
                //cout << first << " " << cross << endl;
            }
        }
    }
    cross %= N;
    int tmp = v[0];
    sort(v.begin(), v.end());
    vector<int>::iterator iter = find(v.begin(), v.end(), tmp);
    int index = distance(v.begin(), iter);
    if(W[0]==2 && v[index] == v[(index+1+L)%L]){index++;}
    //cout << index << endl;
    for(i=0;i<N;i++){
        cout << v[(index-cross+i+N)%N] << endl;
    }
    return 0;
}

#include <bits/stdc++.h>
using namespace std;
const int N = 1e5 + 5;
int n;
long long L, T, ans[N];

struct Ant {
    long long x, d;
    long long ed;
    bool operator < (const Ant &rhs) const {
        return ed < rhs.ed;
    }
}a[N];

int main() {
    scanf("%d%lld%lld", &n, &L, &T);
    long long cnt = 0;
    for(int i = 0; i < n; i++) {
        scanf("%lld%lld", &a[i].x, &a[i].d);
        if(a[i].d == 1) cnt++;
        a[i].ed = a[i].x + T*(a[i].d == 1 ? 1LL : -1LL);
        a[i].ed = (a[i].ed%L + L)%L;
    }
    long long cross = 0;
    if(a[0].d == 1) {
        cross += T/L*(n-cnt)*2;
    }else {
        cross += T/L*cnt*2;
    }
    for(int i = 1; i < n; i++) {
        if(a[i].d == a[0].d) continue;
        long long dis;
        if(a[i].d == 2) dis = abs(a[i].x - a[0].x);
        else dis = abs(a[0].x - a[i].x + L);
        if(dis <= T%L*2) cross++;
        if(dis+L <= T%L*2) cross++;
    }
    cross %= n;
    if(a[0].d == 2) cross = (n-cross)%n;
    for(int i = 1; i < n; i++) {
        if(a[0].d == 2 && a[i].ed < a[0].ed) a[i].ed += L;
        if(a[0].d == 1 && a[i].ed <= a[0].ed) a[i].ed += L;
    }
    sort(a+1, a+n);
    for(int i = 0; i < n; i++) {
        ans[(cross+i)%n] = a[i].ed%L;
    }
    for(int i = 0; i < n; i++) {
        printf("%d\n", (int)ans[i]);
    }
    return 0;
}

