		cnt += tr / l - (tr % l == 0);
	}
	ll i_kizyun = (idx + cnt % n) % n;
	ll i_pos = tox[idx];
	sort(ALL(tox));

	ll idx2;
	REP(i, n) {
		if (tox[i] == i_pos) {
			idx2 = i; break;
		}
	}
	REP(i, n) {
		cout << tox[(i - i_kizyun + idx2 + n) % n] << "\n";
	}

	cout << flush;
}

