	for(LL i=1;i<=n;i++) 
	{
		scanf("%lld%lld",&a[i],&w[i]);
		if(w[i]==1) s1++;
		else s2++;
		if(w[i]==1) A[i].d=(a[i]+T)%L;
		else A[i].d=((a[i]-T)%L+L)%L;
	}
	LL t=T/L;T%=L;
	if(w[1]==1) t=t*2*s2%n;
	else t=t*2*s1%n;
	for(LL i=2;i<=n;i++)
	{
		if(w[i]==w[1]) continue;
		LL d;
		if(w[1]==1) d=a[i]-a[1];
		else d=L-a[i]+a[1];
		if(2*T>=d) t++;
		if(2*T>=L+d) t++;
	}
	LL st;
	if(w[1]==1) st=(1+t)%n;
