			break;
		}
	if(p2==0) p=p1;
	else
	{
		if(w[1]==1) {swap(A[p1],A[p2]);p=p2;}
		else p=p1;
	}
	for(LL i=p+1;i<=n;i++) 
	{
		A[i].id=A[i-1].id+1;
		if(A[i].id>n) A[i].id=1;
	}
	for(LL i=p-1;i>=1;i--)
	{
		A[i].id=A[i+1].id-1;
		if(A[i].id==0) A[i].id=n;
	}
	for(LL i=1;i<=n;i++) ans[A[i].id]=A[i].d;
