VI confro;
Vpr last;
int main(){
	LL N,L,T;
	cin >> N >> L >> T;
	REP(i,N){
		cin >> X[i] >> W[i];
		if(W[i]==1) D[i]= (X[i]+T%L)%L;
		else 	 	D[i]= (X[i]-T%L+L)%L;

		last.PB(pr(D[i],W[i]));
	}
	sort(ALL(last));
	LL def=W[0];
	LL hit=0;
	FOR(i,1,N){
		if(def!=W[i]){
			confro.PB(i);
		}
	}
	LL turns=T/L;
	hit+=turns*confro.size();
	T%=L;
	REP(i,confro.size()){
		int next=confro[i];
		LL dist=X[next]-X[0];
		if(def==2) dist=L-dist;
		if(dist<=T*2) hit++;
	}

	hit%=N;
	int st=0;
	REP(i,N){
		if(D[0]==last[i].first && W[0]==last[i].second) st=i;
	}

	REP(i,N){
		if(def==1) cout << last[(st+i-hit+N)%N].first << endl;
		else cout << last[(st+i+N+hit)%N].first << endl;
	}
	return 0;
}

