ll f(ll k)
{
	ll i, ret = 0;

	for(i=0;i<n;i++){
		if(V[i] == k) ret += t;
		else if(V[i] < k) ret += t + (k - V[i] - 1) / l + 1;
		else ret += t - (V[i] - k) / l;
	}

	return ret;
}

