	for(;s<=e;){
		mid = s+e >> 1;

		if(f(mid) <= n*t) s = mid+1;
		else e = mid-1;
	}

	x = (n*t - f(s-1));
	k = ((s-1) % l + l) % l;

	for(i=0;i<n;i++){
		V[i] = (V[i] % l + l) % l;
	}

	sort(V.begin(), V.end());

