    t += d / 2 + 1;
    x = modL(x + d / 2 + 1);
    target = (target + 1) % N;
  }

  DEBUG(x, x1);
  sort(pos.begin(), pos.end());
  REP(i, N) { DEBUG(i, pos[i]); }

