    REP(i, N) {
        if (W[i] != W[0]) {
            int d;
            if (W[0] == 1 && W[1] == 2) {
                d = X[i] - X[0];
            } else if (W[0] == 2 && W[1] == 1) {
                d = L - (X[i] - X[0]);
            }
            if (2 * T >= d) {
                cnt += 1 + (2 * T - d) / L;
            }
        }
    }
    int k;
    if (W[0] == 1) {
        k = mod(cnt, N);
    } else if (W[0] == 2) {
        k = mod(-cnt, N);
    }

    vector<int> Y(N);
