			sumtimes%=N;
		}
	}
	for (ll i=0;i<N;i++) {
		ll dir=W[i]==1?1:-1;
		v.PB(MP(((X[i]+dir*T)%L+L)%L,i));
	}
	sort(v.begin(),v.end());
	ll newZeroIdx=-1;
	for (ll i=0;i<N;i++) {
		if (v[i].snd==0) {newZeroIdx=i; break;}
	}
	if (W[0]==1) {
		if (v[newZeroIdx]==v[(newZeroIdx+N-1)%N]) {
			newZeroIdx=(newZeroIdx+N-1)%N;
		}
	}
	else {
		if (v[newZeroIdx]==v[(newZeroIdx+1)%N]) {
			newZeroIdx=(newZeroIdx+1)%N;
		}
	}
	for (ll i=0;i<N;i++) {
