    else
      Sn.insert({x[i].x, i}),
	Sn.insert({x[i].x+l, i}),
	Sn.insert({x[i].x-l, i});
  }

  ll a = location(0);
  ll b = location(1);

  vector<ll> all;
  REP(i,n) all.pb(f(x[i].x + x[i].y * t));
  sort(all.begin(), all.end());

  if (all.back() == a && all.front() == b)
