long long int A[1][100010], B[1][100010];
int a=0, b=0;
int pmod(long long int x, long long int a){
	if (x%a<0) return x%a+a;
  	else return x%a;
}
int modL(long long int x){
	if(x%L==0) return L;
  	else return pmod(x,L);
}
int locate_0(long long int t){
	if (W[0]==1){
		long long int i=0, d=0;
      	while(d<=2*t){
        	if (i%2==0){
            	if (i==0) {
                  d+=modL(B[1][0]-A[1][0]);
                }
              	else {
                	d+=modL(B[1][pmod(i/2,b)]-B[1][pmod(i/2-1,b)]);
                }
            }
          	else{
            	d+=modL(A[1][pmod((i-1)/2,a)]-A[1][pmod((i+1)/2,a)]);
            }
          i++;
        }
      	if (i%2==1) return pmod(A[1][pmod((i-1)/2,a)]+t,L);
      	else return pmod(B[1][pmod((i-2)/2,b)]-t,L);
    }
  if (W[0]==2){
		long long int i=0, d=0;
      	while(d<=2*t){
        	if (i%2==0){
            	if (i==0) {
                  d+=modL(B[1][0]-A[1][0]);
                }
              	else {
                	d+=modL(A[1][pmod((i-2)/2,a)]-A[1][pmod(i/2,a)]);
                }
            }
          	else{
            	d+=modL(B[1][pmod((i+1)/2,b)]-B[1][pmod((i-1)/2,b)]);
            }
          i++;
        }
      	if (i%2==0) return pmod(A[1][pmod((i-2)/2,a)]+t,L);
      	else return pmod(B[1][pmod((i-1)/2,b)]-t,L);
    }
}
int f(long long int x){
	for (int i=0; i<N; i++){
    	if (x==X[i]) return Z[i];
    }
}
int main() {
  cin >> N >> L >>T;
  for (int i=0; i<N; i++){
  	cin >>X[i] >> W[i];
  }
  for (int i=0; i<N; i++){
    if(W[i]==2){
  		B[0][b]=i;
      	B[1][b]=X[i];
        b++;
    }
  }
  for (int i=N; i>=1; i--){
    	if (W[i%N]==1){
    	A[0][a]=i%N;
      	A[1][a]=X[i%N];
        a++;
        }
    }

  for (int i=0; i<N; i++){
  	if (W[i]==1) Y[i]=(X[i]+L)%L;
    else Y[i]=pmod((X[i]-L),L);
  }
  sort(Y, Y+N);

  int s=0;
  while(Y[s]!=locate_0(L)){
  	s++;
  }
  for (int i=0; i<N;i++){
  	Z[i]=Y[(i+s)%N];
  }

  int c=1, d=X[0];
  long long int U[N];
  U[0]=X[0];
  while(f(d)!=X[0]){
  	d=f(d);
    U[c]=d;
    c++;
  }

  int u=0;
  while (X[u]!=U[(c-(T/L)%c)%c]) u++;

  for (int i=0; i<N; i++){
  	if (W[i]==1) Y[i]=(X[i]+T)%L;
    else Y[i]=pmod((X[i]-T),L);
  }
  sort(Y, Y+N);
  int v=0;
  while(Y[v]!=locate_0(T%L)) v++;

  for (int i=0; i<N; i++){
  	Z[i]=Y[pmod(v-u+i,N)];
    cout << Z[i] <<endl;
  }
}

