LL im(LL a, LL b) { return (a % b + b) % b; }

LL n, l, t, x[100000], w[100000];

LL cw, ccw;
LL CW[100000], CCW[100000];

LL cwc, ccwc;
LL ans_cw, ans_ccw, d;
LL f(LL z) {
	if(z == 0) { return 0; }
	else {
		z--;
		ans_cw = 0;
		ans_ccw = d;
	}

	cwc = (z + 1) / 2;
	ccwc = z / 2;
	ans_cw += (cwc / cw) * l;
	ans_ccw += (ccwc / ccw) * l;
	cwc %= cw;
	ccwc %= ccw;
	inc(i, cwc) { ans_cw += CW[i]; }
	inc(i, ccwc) { ans_ccw += CCW[i]; }

	ans_cw /=2;
	ans_ccw /=2;

	return ans_cw + ans_ccw;
}

int main() {
	cin >> n >> l >> t;
	inc(i, n) { cin >> x[i] >> w[i]; }

	inc(i, n) {
		if(w[i] == 1) { cw++; } else { w[i] = -1; ccw++; }
	}
	if(cw == 0 || ccw == 0) {
		inc(i, n) { cout << im(x[i] + t * w[i], l) << "\n"; }
		return 0;
	}


	t *= 4; l *= 4;
	inc(i, n) { x[i] *= 4; }

	LL p, q;
	inc(i, n) { if(w[i] == 1) { p = i; break; } }
	inc(i, n) {
		LL qq = im(p + i, n);
		if(w[qq] != 1) { q = qq; break; }
	}

	d = im(x[q] - x[p], l);

	ccw = 0;
	LL pre = x[q];
	inc1(i, n) {
		LL qq = im(q + i, n);
		if(w[qq] != 1) {
			CCW[ccw++] = im(x[qq] - pre - 1, l) + 1;
			pre = x[qq];
		}
	}
	cw = 0;
	pre = x[p];
	inc1(i, n) {
		LL pp = im(p - i, n);
		if(w[pp] == 1) {
			CW[cw++] = im(pre - x[pp] - 1, l) + 1;
			pre = x[pp];
		}
	}

	LL L = 0, R = t + 1;
	while(R - L > 1) {
		LL M = (L + R) / 2;
		(f(M) < t ? L : R) = M;
	}

	LL e = (t - 1) - f(L); // f(L) の副作用を利用する
	LL pos = im(x[p] + ans_ccw - ans_cw + (L % 2 == 0 ? 1 : -1) * e, l);

	LL s[100000];
	inc(i, n) { s[i] = im(x[i] + w[i] * (t - 1), l); }
	sort(s, s + n);

	LL ind = -1;
	inc(i, n) { if(s[i] == pos) { ind = i; } }
	assert(ind != -1);

	inc(i, n) {
		int pp = im(ind + i, n);
		cout << im((s[pp] + 1) / 4, l / 4) << "\n";
	}

	return 0;
}

