int mod2L(int n, int L) {
  return (n + L * 2) % (L * 2);
}

int main() {
  int N, L, T;
  cin >> N >> L >> T;

  int tog = 0;
  vector<vector<int> > A(L * 2);
  fill(A[0].begin(), A[0].end(), 0);
  fill(A[1].begin(), A[1].end(), 0);

  int f;

  for (int i = 0; i < N; i++) {
    int X, W;
    cin >> X >> W;
    A[tog][X * 2] = W;

    if (i == 0) {
      f = X;
    }
  }

  for (int i = 0; i < T * 2; i++) {
    int got = 1 - tog;

    bool flg;
    for (int j = f; j < f + L * 2; j++) {
      flg = false;
      int jj = mod2L(j, L);
      if (A[tog][jj] | 1) {
	A[got][mod2L(j + 1, L)] += 1;
	if (!flg) {
	  flg = true;
	  f = mod2L(f - 1, L);
	}
      }
      if (A[tog][jj] | 2) {
	A[got][mod2L(j - 1, L)] += 2;
	if (!flg) {
	  flg = true;
	  f = mod2L(f + 1, L);
	}
      }
    }
    fill(A[tog].begin(), A[tog].end(), 0);
    tog = got;
  }

  for (int i = f; i < f + L * 2; i++) {
    int ii = mod2L(i, L);
    if (A[tog][ii] != 0) {
      cout << A[tog][ii] << endl;
    }
  }

  return 0;
}

