	    else if(dis < 2 * rem) pos += 1;
	    pos %= N;
	}
    }
    if(w[0] == 1) pos %= N;
    else pos = N - pos % N;
    for(int i = 0 ; i < N ; ++i) {
	if(id[i] == 0) {
	    int p = i;
