	int N, L, T, X[100000];
	bool W[100000];
	std::scanf("%d %d %d", &N, &L, &T);
	for (int i = 0; i < N; ++i) {
		int w;
		scanf("%d %d", X + i, &w);
		W[i] = w == 1;
	}
	int diff = W[0] ? 1 : L - 1;
	int pos = (X[0] + T * diff) % L;
	int number = 0;
	int n_diff = W[0] ? 1 : N - 1;
	for (int i = 1; i < N; ++i) {
		if (W[0] == W[i]) {
			continue;
		}
		int dist;
		if (W[0]) {
			if (X[0] <= X[i]) {
				dist = X[i] - X[0];
			} else {
				dist = X[i] + L - X[0];
			}
		} else {
			if (X[0] >= X[i]) {
				dist = X[i] - X[0];
			} else {
				dist = X[0] + L - X[i];
			}
		}
		int count = 0;
		count += 2 * T / L;
		count += (2 * T) % L >= dist ? 1 : 0;
		number += (count * n_diff);
		number %= N;
	}
	for (int i = 0; i < N; ++i) {
		int diff = W[i] ? 1 : L - 1;
		X[i] = (X[i] + diff * T) % L;
