				}
				t-=dist(i,nxt[i]); cb=1; i=nxt[i];
			}
		}
	}
	int bg=lower_bound(c+1,c+1+n,pos)-c;
	for(int i=1;i<=n;i++) PutAns(c[(i+bg-2)%n+1]),putchar('\n');
	return 0;
}

