    if (id == 0) id = n;*/

    aux.clear();
    for (i = id + 1; i <= n; i++) if (tp[i] == 2) aux.push_back(x[i] - x[id]);
    for (i = 1; i < id; i++) if (tp[i] == 2) aux.push_back(L - x[id] + x[i]);
    if (aux.size()) {
        ri.pb(aux[0]);
        for (i = 1; i < aux.size(); i++) ri.pb(aux[i] - aux[i - 1]);
    }

    aux.clear();
    for (i = id - 1; i > 0; i--) if (tp[i] == 1) aux.push_back(x[id] - x[i]);
    for (i = n; i > id; i--) if (tp[i] == 1) aux.push_back(x[id] + L - x[i]);
    if (aux.size()) {
        le.pb(aux[0]);
        for (i = 1; i < aux.size(); i++) le.pb(aux[i] - aux[i - 1]);
    }

    tm = 2 * T;
    act_dir = tp[id];
    while (tm > 0) {
        if (act_dir == 1) {
            dd = min(tm, ri.front());
            delta += dd;
            tm -= dd;
            ri.pop_front();

            if (le.empty())
                le.pb(L);
            else
                le.pb(L - le.back());
        } else {
            dd = min(tm, le.front());
            delta -= dd;
            tm -= dd;
            le.pop_front();

            if (ri.empty())
                ri.pb(L);
            else
                ri.pb(L - ri.back());
        }

        act_dir ^= 3;
    }

    delta /= 2;
    ll ans = (10LL * L + x[id] + delta) % L;
    return ans;
}

