int part[100 * 1000 + 5][4];

int main() {
    //ifstream cin("C.in");
    int n, l, t; cin >> n >> l >> t;

    vector<int> x(n, 0), dir(n, 0);

    for(int i = 0; i < n; ++i) {
        cin >> x[i] >> dir[i];
        for(int j = 1; j <= 2; ++j) {
            if(i >= 1)
                part[i][j] += part[i - 1][j];
            if(dir[i] == j)
                part[i][j]++;
        }
    }

    vector<int> ans(n, 0);

    for(int i = 0; i < n; ++i) {
        int poz = x[i], who = -1;
        int poz2 = x[i];

        if(dir[i] == 1) {
            poz = (poz + t) % l;
            poz2 = (1LL * poz2 + 2 * t) % l;
        } else {
            poz = (poz - t) % l;
            while(poz < 0)
                poz += l;
            poz2 = (poz2 - 2 * t) % l;
            while(poz2 < 0)
                poz2 += l;
        }

        if(dir[i] == 1) {
            int sum = 0;
            auto it = upper_bound(x.begin(), x.end(), min(1LL * x[i] + 2 * t, 1LL * l)) - x.begin();
            --it;
            if(it >= 0 and it >= i)
                sum += part[it][2] - part[i][2];

            if(1LL * x[i] + 2 * t >= l) {
                it = upper_bound(x.begin(), x.end(), poz2) - x.begin();
                --it;
                if(it >= 0)
                    sum += part[it][2];
            }

            sum += ((2 * t) / l) * part[n - 1][2];
            who = (i + sum) % n;

            ans[who] = poz;
        } else {
            int sum = 0;
            auto it = lower_bound(x.begin(), x.end(), x[i] - 2 * t) - x.begin();

            if(it >= 1) {
                sum += part[i][1] - part[it - 1][1];
            } else {
                sum += part[i][1];
            }

            if(x[i] - 2 * t < 0) {
                it = lower_bound(x.begin(), x.end(), poz2) - x.begin();
                sum += part[n - 1][1];
                if(it >= 1)
                    sum -= part[it - 1][1];
            }

            sum += ((2 * t) / l) * part[n - 1][1];

            who = (i - sum) % n;
            while(who < 0)
                who += n;

            ans[who] = poz;
        }
    }

    for(int i = 0; i < n; ++i)
        cout << ans[i] << "\n";
}

#include <bits/stdc++.h>
using namespace std;
template<typename dataT>
struct nodeT{
    dataT val;
    nodeT<dataT> *left, *right;
    nodeT(){
        left = nullptr;
        right = nullptr;
        val = dataT();
    }
    nodeT(dataT v){
        nodeT();
        val = v;
    }
    dataT get_val(){
        return val;
    }
    void set_val(dataT x){
        val = x;
    }
    void add_to_val(dataT x){
        val = val + x;
    }
    void update(){
        val = dataT();
        if(left) val = val + left->get_val();
        if(right) val = val + right->get_val();
    }
};
template<typename dataT, typename boundT = int, boundT leftBound = 0, boundT rightBound = 100100>
struct dynamic_tree{
    using node = nodeT<dataT>;
    virtual node * get_node(node * before){
        if(before) return before;
        node * new_node = new node();
        return new_node;
    }
    node * root;
    void clear(){
        root = nullptr;
    }
    dynamic_tree(){
        clear();
    }
    node * get_root(){
        return root;
    }
    node * set_pos(node * cur, boundT l, boundT r, boundT pos, dataT val){
        cur = get_node(cur);
        if(l == r) cur->set_val(val);
        else{
            boundT mid = (l + r)>>1;
            if(pos <= mid) cur->left = set_pos(cur->left, l, mid, pos, val);
            else cur->right = set_pos(cur->right, mid + 1, r, pos, val);
            cur->update();
        }
        return cur;
    }
    node * set_pos(boundT pos, dataT val){
        root = set_pos(root, leftBound, rightBound, pos, val);
        return root;
    }
    node * set_pos(node * rt, boundT pos, dataT val){
        return set_pos(rt, leftBound, rightBound, pos, val);
    }
    node * add_to_pos(node * cur, boundT l, boundT r, boundT pos, dataT val){
        cur = get_node(cur);
        if(l == r) cur->add_to_val(val);
        else{
            boundT mid = (l + r)>>1;
            if(pos <= mid) cur->left = add_to_pos(cur->left, l, mid, pos, val);
            else cur->right = add_to_pos(cur->right, mid + 1, r, pos, val);
            cur->update();
        }
        return cur;
    }
    node * add_to_pos(boundT pos, dataT val){
        root = add_to_pos(root, leftBound, rightBound, pos, val);
        return root;
    }
    node * add_to_pos(node * rt, boundT pos, dataT val){
        return add_to_pos(rt, leftBound, rightBound, pos, val);
    }
    dataT query(node * cur, boundT l, boundT r, boundT x, boundT y){
        if(cur == nullptr || l > y || r < x) return dataT();
        if(x <= l && r <= y) return cur->get_val();
        boundT mid = (l + r)>>1;
        if(y <= mid) return query(cur->left, l, mid, x, y);
        if(x > mid) return query(cur->right, mid + 1, r, x, y);
        return query(cur->left, l, mid, x, y) + query(cur->right, mid + 1, r, x, y);
    }
    dataT query(boundT x, boundT y){
        return query(root, leftBound, rightBound, x, y);
    }
    dataT query(node * rt, boundT x, boundT y){
        return query(rt, leftBound, rightBound, x, y);
    }
};
