			v1.push_back(X[i] - L);
			v1.push_back(X[i] - L * 2);
			v1.push_back(X[i] - L * 3);
		}else{
			v1.push_back(X[i] - L);
			v2.push_back(X[i]);
			v2.push_back(X[i] + L);
			v2.push_back(X[i] + L * 2);
			v2.push_back(X[i] + L * 3);
		}
	}

	v1.push_back(INF);
	v1.push_back(-INF);
	v2.push_back(INF);
	v2.push_back(-INF);
	sort(v1.begin(), v1.end());
	sort(v2.begin(), v2.end());

	/*
	for(int i = 0; i < v1.size(); i++){
		cout << v1[i] << " ";
	}
	cout << endl;

	for(int i = 0; i < v2.size(); i++){
		cout << v2[i] << " ";
	}
	cout << endl;
	*/

	int id1 = 0;
	int id2 = 0;
	for(int i = 0; i < N; i++){
		if(W[i] == 1){
			while(true){
				if(v2[id1] > X[i]){
					break;
				}
				id1++;
			}
			while(true){
				if(v2[id2] > X[i] + 2 * T){
					break;
				}
				id2++;
			}
			int col = id2 - id1;
			ans[(i + col) % N] = (X[i] + T) % L;
			//cout << i << " " << col << endl;
		}
	}

	id1 = v1.size() - 1;
	id2 = v1.size() - 1;
	for(int i = 0; i < N; i++){
		if(W[i] == 2){
			while(true){
				if(v1[id1] < X[i] - 2 * T){
					break;
				}
				id1--;
			}
			while(true){
				if(v1[id2] < X[i]){
					break;
				}
				id2--;
			}
			int col = id2 - id1;
			ans[(i - col + N * 2) % N] = (X[i] - T + L) % L;
			//cout << i << " " << col << endl;
		}
	}

	for(int i = 0; i < N; i++){
		cout << ans[i] << endl;
	}

	return 0;
}

