void solve()
{
    int left = 2 * T % L;
    int cntall = 0, cntlast = 0;
    for (int i = 1; i < N; ++i) {
        if (D[i] != D[0]) {
            cntall += 1;
            if (D[0] == 1)
                cntlast += (X[i] - X[0] < left);
            else
                cntlast += (X[0] + L - X[i] <= left);
        }
    }
    int d = ((LL)(2 * T / L) * cntall + cntlast) % N;
    int id = D[0] == 1 ? d : (N - d) % N;
    // printf("d=%d, id=%d\n", d, id);

    vector<Pii> pos;

    int T0 = T % L;
    for (int i = 0; i < N; ++i) {
