void solve() {
    int tmp[101010] = {};
    for (int i = 0; i < N; i++) {
        if (W[i] == 1)
            tmp[i] = X[i] + T;
        else
            tmp[i] = X[i] - T;
        tmp[i] %= L;
        tmp[i] += L;
        tmp[i] %= L;
    }
    sort(tmp, tmp + N);

    int cnt = 0;
    for (int i = 0; i < N; i++) {
