  rx.reserve(N);
  lx.reserve(N);
  int target = -1, target_l = -1;
  REP(i, N) {
    cin >> X[i] >> W[i];
    if (W[i] == 1) {
      rx.push_back(X[i]);
      if (target == -1) {
        target = i;
        target_l = lx.size();
      }
    } else {
      assert(W[i] == 2);
      lx.push_back(X[i]);
    }
  }

  auto modL = [&](i64 x) -> i64 {
    if (x >= 0) return x % L;
    i64 k = (-x + L - 1) / L;
    return (x + k * L) % L;
  };

  DEBUG(target);
  vector<int> pos(N);
  REP(i, N) { pos[i] = modL(X[i] + T * (W[i] == 1 ? 1 : -1)); }

