const lli e5 = 1 << 20;
const lli mod = 998244353;
const lli e3 = 1 << 12;

lli n,l,t;
lli x[e5],w[e5];
lli reverse_ants;
lli cross_ants;
lli ans[e5];

int main(){
  cin >> n >> l >> t;
  for(lli i = 0;i < n;i++) cin >> x[i] >> w[i];
  for(lli i = 0;i < n;i++){
    if(w[i] != w[0]){
      reverse_ants++;
      if(w[0] == 1){
        if((x[i]-x[0]+l)%l-t%l < (t%l)) cross_ants++;
      }else{
        if((x[0]-x[i]+l)%l-t%l < (t%l)) cross_ants++;
      }
    }
    cross_ants += reverse_ants*(t/l);
  }
  for(lli i = 0;i < n;i++){
    if(w[i] == 1) x[i] = (x[i]+t)%l;
    else{
      x[i] -= t;
      if(x[i] < 0) x[i] += l*((-x[i])/l);
      x[i] = (x[i]+l)%l;
    }
  }
  lli hoge = x[0];
  for(lli i = 0;i < n;i++){
    x[i] = (x[i]-hoge+l)%l;
    if(x[i] == 0 && w[i] == 2) x[i] += l;
  }
  sort(x,x+n);
  for(lli i = 0;i < n;i++) x[i] = (x[i]+hoge)%l;
  for(lli i = 0;i < n;i++){
    if(w[0] == 1) ans[(i+cross_ants)%n] = x[i];
    else{
      lli idx = i-cross_ants;
      if(idx < 0) idx += n*((-idx)/n);
      idx = (idx+n)%n;
      ans[idx] = x[i];
    }
  }

  for(lli i = 0;i < n;i++){
    cout << ans[i] << endl;
  }

}

#include <iostream>

using namespace std;

int main() {
    int N, L, T;
    double antX[100000];
    double antW[100000];
    cin >> N >> L >> T;
    for (int i = 0; i < N; ++i) {
        cin >> antX[i] >> antW[i];
    }
    double totalTime = 0.0;
    while (true) {
        // 最短でぶつかるアリを検索
        double minTime = 1000000000.0;
        bool flag = false;
        int minIndex = 0;
        for (int i = 0; i < N; ++i) {
            double time;
            if (i == N - 1) {
                if (antW[0] - antW[i] == 1) {
                    int x = antX[0] - antX[i];
                    if (x < 0) {
                        x += L;
                    }
                    time = x / 2.0;
                    if (minTime > time) {
                        minTime = time;
                        minIndex = i;
                        flag = true;
                    }
                }
            }
            if (antW[i + 1] - antW[i] == 1) {
                int x = antX[i + 1] - antX[i];
                if (x < 0) {
                    x += L;
                }
                time = x / 2.0;
                if (minTime > time) {
                    minTime = time;
                    minIndex = i;
                    flag = true;
                }
            }
        }
//        cout << "mintime : " << minTime << endl;
        // ありを最小単位で更新
        if (flag && totalTime + minTime <= T) {
            for (int i = 0; i < N; ++i) {
                if (antW[i] == 1) {
                    antX[i] = (antX[i] + minTime);
                } else{
                    antX[i] = (antX[i] - minTime);
                }
                while (antX[i] >= L) {
                    antX[i] -= L;
                }
                while (antX[i] < 0) {
                    antX[i] += L;
                }
//                cout << "x : " << antX[i] << endl;
            }
            if (minIndex == N - 1) {
                antW[0] = 1;
                antW[minIndex] = 2;
            } else {
                antW[minIndex + 1] = 1;
                antW[minIndex] = 2;
            }
            totalTime += minTime;
//            cout << "totalT : " << totalTime << endl;
            if (totalTime >= L) {
                break;
            }
        } else {
            for (int i = 0; i < N; ++i) {
                if (antW[i] == 1) {
                    antX[i] = (antX[i] + T - totalTime);
                } else{
                    antX[i] = (antX[i] - T + totalTime);
                }
                while (antX[i] >= L) {
                    antX[i] -= L;
                }
                while (antX[i] < 0) {
                    antX[i] += L;
                }
            }
            break;
        }
    }
    // 出力
    for (int i = 0; i < N; ++i) {
        cout << antX[i] << endl;
    }
    return 0;
}

