vector< vector<int> > Gra;
vector< bool> visit;
int must;
vector<int> ans;
bool dfs2(int S,int T){
	visit[S] = true;
	if( S==T ){
		return true;
	}
	int size = Gra[S].size();
	bool res = false;
	for(int i=0;i<size;++i){
		int to = Gra[S][i];
		if( visit[to] ) continue;
		res = dfs2(to,T);
		if( res ){
			ans.push_back(to);
			return res;//true
		}
	}
	visit[S] = false;
	return false;
}

bool dfs(int v){
	visit[v] = true;
	int size = Gra[v].size();
	bool res = false;
	int count = 0;
	for(int i=0;i<size;++i){//いける場所がある場合端点になれない
		int to = Gra[v][i];
		if( visit[to] ){
			++count;
			continue;
		}
		res = dfs(to);
		if( res ){
			ans.push_back(v);
			return res;
		}
	}

	if( count != Gra[v].size() ){
		visit[v] = false;
		return false;
	}

	size = Gra[must].size();
	for(int i=0;i<size;++i){
		if( visit[ Gra[must][i] ] == false ){
			visit[v] = false;
			return false;
		}
	}

	ans.push_back(v);
	return true;
}
