int const N = 1e5 + 41;
ll const INF = 2e9 * 4LL + 41;

vector<pll> a, b;
ll n, l, t;
int posb[N], posa[N];

void solveSpecial(){
	ll sign = (sz(a) ? 1 : -1);
	if(sz(a) == 0) a = b;
	fi(0, sz(a)){
		ll nx = a[i].first + sign * (t % l);
