    for (int i = 0; i < N; ++i) {
        if (antW[i] == 1) {
            ants[i].x = antX[i] + T;
        } else {
            ants[i].x = antX[i] - T;
        }
        if (ants[i].x >= L) {
            ants[i].x = ants[i].x % L;
        } else if (ants[i].x < 0) {
            ants[i].x = (L + ants[i].x) % L;
        }
        for (int j = 0; j < N; ++j) {
            if (i == j) {
                continue;
            }
            if (antW[i] != antW[j]) {
                double firstTime;
                double diff = antX[i] - antX[j];
