                    diff += L;
                }
                firstTime = diff / 2.0;
                if (firstTime > 0) {
                    suretigai[i] += 1;
                }
                suretigai[i] += (int) (2 * (T - firstTime)) / L;
            }
        }
        if (antW[i] == 1) {
