#include <bits/stdc++.h>
using namespace std;
#define ll long long
#define all(V) V.begin(),V.end()

ll L;
ll lmod(ll A) {
	if (A < 0) {
		A = 0 - A;
		A %= L;
		A = L - A;
	}
	else A %= L;
	return A;
}

int main() {
	ll N, T, X, W, X1, W1;
	cin >> N >> L >> T;
	vector<ll> Lant;
	vector<ll> Rant;
	vector<ll> last(N);
	for (int i = 0;i < N;i++) {
		cin >> X >> W;
		if (i == 0)	X1 = X, W1 = W;
		if (W == 1) {
			Rant.push_back(lmod(X1 - X));
			last[i] = lmod(X + T);
		}
		else {
			Lant.push_back(X - X1);
			last[i] = lmod(X - T);
		}
	}

	ll Ras = Rant.size();
	ll Las = Lant.size();
	sort(all(last));
	reverse(all(Rant));

	ll ri = 0, le = 0, r_it = 0, l_it = 0, fmet;

	for (ll tim = 0; tim <= T;) {
		if (W == 1) {
			if (tim == 0 && Rant[r_it] == 0) {
				Rant[r_it] += L;
				r_it++;
				if (r_it == Ras) r_it = 0;
				continue;
			}
			fmet = Lant[l_it] - ri;
			if (tim + (fmet + 1) / 2 > T) {
				X1 += T - tim;
				break;
			}
			X1 += fmet / 2; //ぶつかるまでの距離/2=時間
			tim += (fmet + 1) / 2;
			//途中でぶつかったら位置は切り捨てればよい Lantの要素との距離の差は距離分短くなるだけ
			ri = Lant[l_it];
			Lant[l_it] += L;
			l_it++;
			if (l_it == Las)
				l_it = 0;
			if (fmet % 2)
				le++;
			W = 2;
		}
		else {
			if (tim == 0 && Lant[l_it] == 0) {
				Lant[l_it] += L;
				l_it++;
				if (l_it == Las) l_it = 0;
				continue;
			}
			fmet = Rant[r_it] - le;
			if (tim + (fmet + 1) / 2 > T) {
				X1 = lmod(X1 - (T - tim));
				break;
			}
			X1 = lmod(X1 - fmet / 2);
			tim += (fmet + 1) / 2;
			le = Rant[r_it];
			Rant[r_it] += L;
			r_it++;
			if (r_it == Ras)
				r_it = 0;
			if (fmet % 2)
				ri++;
			W = 1;
		}
	}
	auto it = lower(all(last), X1);
	for (int i = 0;i < N;i++) {
		cout << *it << endl;
		it++;
		if (it == last.end())
			it = last.begin();
	}
}

