const int MAX = 1e5+10;

ll N, L, T;
ll X[MAX], W[MAX];

void add(ll& n, ll m, ll mod) {
    n += m;
    n %= mod;
    if (n < 0) n += mod;
}

ii getPair(int n) {
    ll pos = 0;
    ll w = W[n], x = X[n];
    if (w == 1) add(pos, x+T, L);
    else add(pos, x-T, L);

    ll round = T / L, rest = T % L;
    ll idx = n;
    ll count = 0;

    REP (i, N) if (w != W[i]) {
        count += 2*round;
        ll dist = 0;
        if (w == 1) add(dist, X[i]-x, L);
        else add(dist, x-X[i], L);

        if (2 * rest >= dist + L) count += 2;
        else if (2 * rest >= dist) count++;
    }

    if (w == 1) add(idx, count, N);
    else add(idx, -count, N);

    return ii(idx, pos);
}

vi solve() {
    vi pos(N);
    REP (i, N) {
        if (W[i] == 1) pos[i] = (X[i] + T) % L;
        else pos[i] = (X[i] - T) % L;
        if (pos[i] < 0) pos[i] += L;
    }
    sort(ALL(pos));

    ii p0 = getPair(0), p1 = getPair(1);
    int idx = -1;
    REP (i, N) if (pos[(i+p0.first)%N] == p0.second && pos[(i+p1.first)%N] == p1.second) idx = i;
    vi ret(N);
    REP (i, N) ret[i] = pos[(idx+i)%N];
    return ret;
}

