    rep(i, N) cin >> X[i] >> W[i];

    ll collision_sum = 0;
    REP(i, 1, N) {
        if (W[0] == 1) {
            collision_sum += collision_count(0, i);
        } else {
            collision_sum -= collision_count(0, i);
        }
        collision_sum = (collision_sum + N) % N;
    }

    vector<ll> last_pos(N);
    rep(i, N) {
        if (W[i] == 1) {
            last_pos[i] = (X[i] + T) % L;
        } else {
