    vl x(n), w(n);
    for (int i = 0; i < n; ++i) {
        cin >> x[i] >> w[i];
    }
    deque<ll> pos;
    for (int i = 1; i < n; ++i) {
        if (w[i] != w[0]) {
            if (w[0] == 1)
                pos.push_back(x[i] - x[0]);
            else
                pos.push_front(l - (x[i] - x[0]));
        }
    }
    deque<ll> p = pos;
    for (auto &v : pos) {
        p.push_back(v + l);
    }
