	int ind = 0;
	for (int i = 0; i < n; i ++)
	{
		if (!w[i])
		{
			if (x[i] + t >= l)
				ind += (t + x[i] - l) / l + 1;
		}
		else
		{
			if (x[i] - t < 0)
				ind -= (t - x[i]) / l + 1;
		}
		ind = (ind % l + l) % l;

	}

	for (int i = 0; i < n; i ++)
		cout << ans[(ind + i) % n] << "\n";

	return 0;
}

