void move(int n){
    if(w[n]==1){
        if(x[n]==l-1)x[n]=0;
        else x[n]++;
    }else{
        if(x[n]==0)x[n]=l-1;
        else x[n]--;
    }
}
void swap(int a,int b){
    int c;
    c=a;
    a=b;
    b=a;
}

