    auto it = lower_bound(begin(pos), end(pos), p0);
    if (next(it) != end(pos) && *next(it) == p0 && !XW[0].second) it = next(it);

    ans[count] = p0;
    it++;
    for (int n = count+1; n % N != count; n++) {
        if (it == end(pos)) it = begin(pos);
        ans[n%N] = *it;
        it++;
    }
    for (int a : ans) cout<<a<<endl;

    return 0;
}

