    int n, l, t;
    cin >> n >> l >> t;
    for(int i = 0; i < n; i++) {
        scanf("%d%d", &a[i], &dir[i]);
        if(dir[i] == 1)
            b[i] = { (a[i] + t) % l, i };
        else
            b[i] = { ((a[i] - t) % l + l) % l, i };
    }
    sort(b, b + n);
    ll shift = 0;
    vector<pair<int, int> > test;
    for(int j = 0; j < min(n, 3); j++) {
        for (int i = 1; i < n; i++) {
            if (dir[i] != dir[j]) {
                ll len;
                if (dir[j] == 1)
                    len = a[i] - a[j];
                else
                    len = a[j] - a[i];
                if (len < 0)
                    len += l;
                ll calc = 0;
                if (2 * t < len)
                    calc = 0;
                else
                    calc = 1 + (2 * t - len) / l;
                if (dir[0] == 1)
                    shift = (shift + calc % n) % n;
                else
                    shift = ((shift - calc % n) % n + n) % n;
            }
        }
        int cur;
        if(dir[j] == 1)
            cur = (a[j] + t) % l;
        else
            cur = ((a[j] - t) % l + l) % l;
        test.push_back({ shift, cur });
    }
    for(int i = 0; i < n; i++) {
