ll calc_count(ll x, ll y, ll L, ll T){
  if(T*2 < abs(x-y)) return 0;
  ll remain = T*2 - abs(x-y);
  return 1+remain/L;
}

int main(){
  int N, L, T;
  cin >> N >> L >> T;
  vector<ll> X, W;
  vector<int> ans;

  rep(i,N){
    int x, w;
    cin >> x >> w;
    X.push_back(x);
    W.push_back(w);

    if(w == 1){
      ans.push_back((x+T)%L);
    }else{
      ans.push_back(((x-T)%L+L)%L);
    }
  }

  int base = ans[0];
  sort(ALLOF(ans));

  int SZ = ans.size();
  vector<int> ret(SZ);
  int cnt = 0;

  if(W[0] == 1){
    rep(i,X.size()){
      if(W[i] == 2){
        cnt += calc_count(X[0], X[i], L, T);
      }
    }

    int b = 0;
    rep(i,ans.size()){
      if(ans[i] == base){
        b = i;
      }
    }
    rep(j,ans.size()){
      ret[(cnt+j)%SZ] = ans[(b+j)%SZ];
    }    
  }else{
    rep(i,X.size()){
      if(W[i] == 1){
        cnt += calc_count(X[0]+L, X[i], L, T);
      }
    }

    int b = 0;
    rep(i,ans.size()){
      if(ans[i] == base){
        b = i;
        break;
      }
    }
    rep(j,ans.size()){
      ret[((-cnt+j)%SZ+SZ)%SZ] = ans[(b+j)%SZ];
    }
