const int N = 100005;

int n, L, T;
int x[N], w[N], a[N], p[N];

bool check(int l, int r, int x, int dir) {
	if (dir == 2) swap(l, r);
	if (l <= r && x >= l && x <= r) return 1;
	if (r < l && ((x >= l && x <= L - 1) || (x >= 0 && x <= r))) return 1;
	return 0;
}

int main() {
	ios_base::sync_with_stdio(false); cin.tie(0);
	cin >> n >> L >> T;

	int cnt = 0;
	int add = 2 * (T / L) % n;
	int v;
	for (int i = 0; i < n; ++i) {
		cin >> x[i] >> w[i];
		if (w[i] == 1) a[i] = (x[i] + T) % L; else a[i] = ((x[i] - T) % L + L) % L;
		//cerr << a[i] << endl;
		if (i == 0) {
			v = (w[i] == 1) ? +1 : -1;
		}
		else if (i != 0 && w[i] != w[0]) {
			cnt = (cnt + v * add) % n;
			int rx = check(x[0], a[0], x[i], w[0]);
			int ra = check(x[0], a[0], a[i], w[0]);
			cnt = (cnt + v * rx) % n; cnt = (cnt + v * ra) % n;
			if (x[0] == a[i]) cnt = (cnt - v) % n;
		}
	}
 	if (cnt < 0) cnt += n;

 	sort(a, a + n);

 	for (int i = cnt; i < n; ++i) printf("%d\n", a[i]);
 	for (int i = 0; i < cnt; ++i) printf("%d\n", a[i]);
}

