    len = L;

    for(int id = 0; id < N; id++){
        int this_pos, dir_id;
        bool this_dir = true;
        std::cin >> this_pos >> dir_id;
        if(dir_id == 2) this_dir = false;
        pos[id] = this_pos;
        dir[id] = this_dir;
    }
    // clock tick loop
    for(int clock = 0; clock < T; clock++){

        for(int id = 0; id < N; id++){
            bool collide_flag = false;
            for(int iid = id-1; iid <= id+1; iid++){
                iiid = iid;
                if(iid < 0) iiid = N + iid;
                else if (iid >= N) iiid = iid % N;
                if(id == iiid) continue;
                if(pos[iiid] == pos[id]) {
                    invert(id);
                }
                if(collide(dir[iiid], pos[iiid], id)){
                    collide_flag = true;
                    invert_stay(id);
                }
            }
            if(!collide_flag) {
                move(id);
            }
        }
        for(int id = 0; id < N; id++){
            update(id);
        }
    }
    for(int id = 0; id < N; id++){
        std::cout << pos[id] << std::endl;
    }
    return 0;
}

