            ll sumt;
            while(true){
                sumt = left[0].first + l - right[ri - 1].first;
                if(sumt > t){
                    ant = 0;
                    goto anspart;
                }
                sumt = sumt + l * (biserch / le) + l * (biserch / ri);
                sumt = sumt + left[biserch % le].first - left[0].first;
                sumt = sumt + (right[ri - 1].first + l - right[(ri - biserch % ri) - 1].first) % l;
                if(mid == 1 && sumt <= t) break;
                mid = (mid + 1) / 2;
                if(sumt > t) biserch -= mid;
                else biserch += mid;
            }
            if(sumt == t) rl = 0;
            ant = right[(ri - biserch % ri) - 1].second;
            if(sumt + (left[(biserch + 1) % le].first + l - left[biserch % le].first - 1) % l + 1 <= t){
                ant = left[(biserch + 1) % le].second;
            }
            if(sumt + (left[(biserch + 1) % le].first + l - left[biserch % le].first - 1) % l + 1 == t){
                rl = 1;
            }
        }
    }
anspart:
    ll pant = ans[ant];
    sort(ans, ans + n);
    ll want = lower_bound(ans, ans + n, pant) - ans;
    if(ans[want] == ans[(want + 1) % n]){
        if(rl == 0) want++;
    }
    for(ll i = 0; i < n; i++){
        cout << ans[(want + i) % n] << endl;
    }
}

