s64 N;
s64 L;
s64 T;

vector<s64> X;
vector<s64> W;

s64 calc_pos(s64 x, s64 w)
{
    s64 dir = w == 1 ? 1 : -1;
    return modulo(x + dir*T, L);
}

void solve()
{
    s64 cross0 = 0;
    FOR(i, 1, N) {
        if(W[0] == W[i]) continue;

        s64 d = W[0]==1 ? X[i]-X[0] : L-(X[i]-X[0]);

        s64 q = 2*T / L;
        s64 r = 2*T % L;

        cross0 += q;
        if(d < r)
            ++cross0;
    }
    cross0 %= N;

    s64 idx0 = modulo(W[0]==1 ? cross0 : N-cross0, N);
    s64 pos0 = calc_pos(X[0], W[0]);

    vector<s64> Y(N);
    REP(i, N) {
        Y[i] = calc_pos(X[i], W[i]);
    }
    ALL(sort, Y);

    auto p = ALL(equal_range, Y, pos0);
    auto it = p.first;
    if(distance(p.first, p.second) == 2 && W[0] == 2)
        ++it;
    s64 k = distance(begin(Y), it);
    REP(i, N) {
        s64 j = modulo(k-idx0+i, N);
        PRINTLN(Y[j]);
    }
}

