{
    RD(N);
    X.resize(N);
    W.resize(N);
    RD(L);
    RD(T);

    REP(i, N) {
        RD(X[i]);
        RD(W[i]);
    }

#ifdef DEBUG

#endif

    solve();

    EXIT();
}

