		long long top = X[0].first - X[n].first;
		if (X[0].second == 1)top += 2 * T;
		else bottom -= 2 * T;
		counter += floor((long double)top / L) - ceil((long double)bottom / L) + 1;
	}
	for (int n = ((expected - X[0].second * counter) % N + N)%N, c = 0; c < N; c++, n = (n+1)%N) {
