                rev_dist.push_back(mp(ants[0].first - ants[i].first + L, i));
            }
        }
    }

    int pos = 0;
    if(!rev_dist.empty()) {
        ll oT = T * 2;
        ll div = oT / L;
        ll off = div * L;
        oT -= off;

        if(ants[0].second == 1)
            pos += rev_dist.size() * div;
        else
            pos -= rev_dist.size() * div;
        pos %= N;

        tr(it, rev_dist) {
            if(oT < it->first)
                break;
            if(ants[0].second == 1)
                pos++;
            else
                pos--;
            pos %= N;
            pos += N;
            pos %= N;
        }
    }

    vll ans(N);
    rep(i, N) {
        if(ants[i].second == 1)
            ants[i].first += T;
        else
            ants[i].first -= T;

        ants[i].first %= L;
        ants[i].first += L;
        ants[i].first %= L;

        int pp = (i + pos + N) % N;
        ans[pp] = ants[i].first;
    }

    tr(it, ans)
        cout << *it << endl;

    return 0;
}

