// マイナスの割り算定義
int64_t my_div(int64_t a, int64_t b) {
  if (a>0){
  return a%b; 
  }
  else{
    a = -a;
    if( a % b==0){
      return 0;
    }
    else{
       return b*( a/b + 1) - a;        
     }
  }
}

