#include <bits/stdc++.h>

#define FOR(i,a,b) for (int i = (int)(a); i < (int)(b); ++i)
#define REP(i,n) FOR(i,0,n)
#define pb push_back
#define x first
#define y second

#define TRACE(x) cerr << #x << " = " << x << endl
#define _ << " _ " <<

using namespace std;

typedef long long ll;
typedef pair<ll, int> pii;

int n;
ll l, t;
pii x[100005];

ll f(ll a){
  a %= l;
  if (a < 0) return a+l;
  return a;
}

set<pii> Sn, Sp;

ll location(int dir, ll loc, ll tm){

  while (true){
    loc = f(loc);
    int nxt;
    if (dir == 1)
      nxt = Sn.lower_bound({f(loc+tm), 1e9})->y;
    else
      nxt = (--Sp.lower_bound({f(loc-tm), -1}))->y;
    ll loc2 = f(x[nxt].x + tm * x[nxt].y);

    if (dir == 1){
      if (loc2 <= loc) loc2 += l;
      loc2 = (loc+loc2) / 2;
    } else {
      if (loc2 >= loc) loc2 -= l;
      loc2 = (loc+loc2) / 2;
    }

    ll del = abs(loc-loc2);
    if (tm+del > t) break;
    tm += del;
    loc = loc2;
    dir = -dir;

  }

  return f(loc + (t-tm) * dir);

}

ll location(int id){
  return location(x[id].y, x[id].x, 0);
}

int main(){
  ios_base::sync_with_stdio(false);

  cin >> n >> l >> t;
  REP(i,n) cin >> x[i].x >> x[i].y, x[i].y = x[i].y == 1 ? 1 : -1;

  {
    bool check = true;
    REP(i,n) if (x[i].y != x[0].y) check = false;
    if (check){
      REP(i,n) cout << f(x[i].x + t * x[i].y) << endl;
      return 0;
    }
  }

  l *= 2;
  t *= 2;
  t %= 2*l;
  REP(i,n) x[i].x *= 2;

  REP(i,n){
    if (x[i].y == 1)
      Sp.insert({x[i].x, i}),
	Sp.insert({x[i].x+l, i}),
	Sp.insert({x[i].x-l, i});
    else
      Sn.insert({x[i].x, i}),
	Sn.insert({x[i].x+l, i}),
	Sn.insert({x[i].x-l, i});
  }

  ll a = location(0);
  ll b = location(1);

  vector<ll> all;
  REP(i,n) all.pb(f(x[i].x + x[i].y * t));
  sort(all.begin(), all.end());

  if (all.back() == a && all.front() == b)
    all.insert(all.begin(), a), all.pop_back();

  int id = -1;
  REP(i,n-1) if (all[i] == a && all[i+1] == b) id = i;
  assert(id != -1);

  FOR(i,id,n) cout << all[i]/2 << endl;
  FOR(i,0,id) cout << all[i]/2 << endl;

  return 0;
}

