ll N, L, T;
vector<ll> X, W;

ll collision_count(int a, int b)
{
    if (W[a] == 1 && W[b] == 2) {
        ll diff = (X[b] - X[a]);
        if (diff <= 2*T) {
            return 1 + (2*T - diff) / L;
        }
    } else if (W[a] == 2 && W[b] == 1) {
        ll diff = L - (X[b] - X[a]);
        if (diff <= 2*T) {
            return 1 + (2*T - diff) / L;
        }
    }

    return 0;
}

int main()
{
    ios::sync_with_stdio(false);

    cin >> N >> L >> T;
    X.resize(N), W.resize(N);
    rep(i, N) cin >> X[i] >> W[i];

    ll collision_sum = 0;
    REP(i, 1, N) collision_sum = (collision_sum + collision_count(0, i)) % N;

    ll last_num, last_dir;
    if (W[0] == 1) {
        last_num = collision_sum % N;
        last_dir = (collision_sum % 2 == 0 ? 1 : 2);
    } else {
        last_num = (N - collision_sum) % N;
        last_dir = (collision_sum % 2 == 0 ? 2 : 1);
    }

    assert(last_num >= 0LL);

    vector<ll> last_pos(N);
    rep(i, N) {
        if (W[i] == 1) {
            last_pos[i] = (X[i] + (T%L)) % L;
        } else {
            last_pos[i] = (X[i] - (T%L) + L) % L;
        }
        assert(last_pos[i] >= 0LL);
    }
    ll p = last_pos[0];
    sort(ALL(last_pos));

    int p_idx = -1;
    rep(i, N) {
        if (last_pos[i] == p) {
            p_idx = i;
            // break;
        }
    }

    vector<ll> ans(N);
    rep(i, N) ans[(last_num + i) % N] = last_pos[(p_idx + i) % N];
    rep(i, N) cout << ans[i] << endl;
}

