int main() {
    scanf("%d%lld%lld", &n, &L, &T);
    long long cnt = 0;
    for(int i = 0; i < n; i++) {
        scanf("%lld%lld", &a[i].x, &a[i].d);
        if(a[i].d == 1) cnt++;
        a[i].ed = a[i].x + T*(a[i].d == 1 ? 1LL : -1LL);
        a[i].ed = (a[i].ed%L + L)%L;
    }
    long long cross = 0;
    if(a[0].d == 1) {
        cross += T/L*(n-cnt)*2;
    }else {
        cross += T/L*cnt*2;
    }
