using namespace std;

using ll = long long;

int mod(int x, int m) {
    if (x > 0) {
        return x % m;
    } else {
        int r = (-x) % m;
        return r ? m - r : 0;
    }
}

int main() {
    cin.tie(0);
    ios::sync_with_stdio(false);

    int N, L, T;
    cin >> N >> L >> T;
    vector<int> X(N), W(N);
    REP(i, N) {
        cin >> X[i] >> W[i];
    }

    ll cnt = 0; // アリ 0 がすり抜ける回数。
    REP(i, N) {
        if (W[i] != W[0]) {
            int d;
            if (W[0] == 1 && W[1] == 2) {
                d = X[i] - X[0];
            } else if (W[0] == 2 && W[1] == 1) {
                d = L - (X[i] - X[0]);
            }
            if (2 * T >= d) {
                cnt += 1 + (2 * T - d) / L;
            }
        }
    }
    int k;
    if (W[0] == 1) {
        k = mod(cnt, N);
    } else if (W[0] == 2) {
        k = mod(-cnt, N);
    }

    vector<int> Y(N);
    REP(i, N) {
        int j = (i + k) % N;
        if (W[i] == 1) {
            Y[j] = mod(X[i] + T, L);
        } else if (W[i] == 2) {
            Y[j] = mod(X[i] - T, L);
        }
    }

    REP(i, N) {
        cout << Y[i] << '\n';
    }
    cout << flush;

    return 0;
}

