            LL len;
            if (it!=v[1].end()) len=*it-st;
            else len=l+v[1][0]-st;
            len/=2;
            if (len>=t)
            {
                st+=t;
                st%=l;
                break;
            }
            st+=len;
            st%=l;
            nf=!nf;
            for (int j=0;j<v[0].size();++j)
            {
                v[0][j]+=len;
                v[0][j]%=l;
            }
            for (int j=0;j<v[1].size();++j)
            {
                v[1][j]+=len;
