		return 0;
	}

	std::sort (fin, fin + N);
	long long currid = 0, curst;
	bool f = true;
	for (curst = 0; curst < st.size (); ++curst)
		if (X[st[curst]] > X[rid[currid]]) break;
	if (curst == st.size ()) curst = 0;
	long long curt = 0, curloc;
	while (true) {
		long long dist = ((X[st[curst]] - (f ? X[rid[currid]] : X[st[(curst + st.size () - 1) % st.size ()]])) % L + L) % L;
		if (dist == 0) dist = L;
		f = false;
		if (curt + dist >= T * 2) {
			curloc = (X[rid[currid]] + T) % L;
			break;
		}
		curt += dist;
		currid = (currid + rid.size () - 1) % rid.size ();
		dist = ((X[st[curst]] - X[rid[currid]]) % L + L) % L;
		long long k = (curt - dist + L - 1) / L;
		long long res = k * L + dist;
		if (res >= T * 2) {
			curloc = ((X[st[curst]] - T) % L + L) % L;
			break;
		}
		curt = res;
		curst = (curst + 1) % st.size ();
	}
	long long bep = -1;
	for (long long i = 0; i < N; ++i) {
		if (curloc == fin[i]) {
			bep = (i - rid[0] + N) % N;
			break;
		}
	}
	assert (bep != -1);
	for (long long i = 0; i < N; ++i)
		std::cout << fin[(i + bep) % N] << std::endl;
}

