ll n,l,t,x[100005],w[100005],p[100005],q[100005],ps,qs;
int main(void){
	cin.tie(0);
	ios::sync_with_stdio(0);
	cin>>n>>l>>t;
	rep(i,n){
		cin>>x[i]>>w[i];
	}
	if(w[0]==2){
		rep(i,n)if(w[i]==2)p[ps++]=i;
		rrep(i,n)if(w[i]==1)q[qs++]=i,x[i]-=l;
	}else{
		ps++;
		rng(i,1,n)if(w[i]==2)q[qs++]=i;
		rrng(i,1,n)if(w[i]==1)p[ps++]=i,x[i]-=l;
	}
	ll yes=0,no=10000000,yi=0;
	if(qs==0)no=1;
	while(no-yes>1LL){
		ll mid=(yes+no)/2LL;
		ll pr=mid/2LL,qr=(mid-1LL)/2LL;
		ll px=x[p[pr%ps]],qx=x[q[qr%qs]];
		if(w[0]==1){
			px-=(l*(pr/ps));
			qx+=(l*(qr/qs));
		}else{
			px+=(l*(pr/ps));
			qx-=(l*(qr/qs));
		}
		if(abs(px-qx)<=t*2LL){
			yes=mid;
			if(mid%2==0)yi=p[pr%ps];
			else yi=q[qr%qs];
		}else no=mid;
	}
	rep(i,n){
		ll z=(i+yi)%n;
		if(w[z]==1)x[z]+=t;
		else x[z]-=t;
		if(x[z]<0){
			x[z]=l-(-x[z])%l;
		}else x[z]%=l;
		print(x[z]);
	}
