std::int64_t count(std::int64_t x, std::int64_t y, std::int64_t T, std::int64_t L)
{
	x *= 2;
	y *= 2;
	T *= 2;
	L *= 2;
	auto m = ((L + y - x) % L) / 2;
	auto m2 = (m + L / 2) % L;
	auto v = T % L;
	if (v >= m2)
	{
		return 2 * (T / L) + 2;
	}
	else if (v >= m)
	{
		return 2 * (T / L) + 1;
	}
	else
	{
		return 2 * (T / L);
	}

}
std::int64_t rcount(std::int64_t x, std::int64_t y, std::int64_t T, std::int64_t L)
{
	return count(x, ((L + x - y) + x) % L, T, L);
}

void Main()
{
	int N, L, T, X, W;
	std::cin >> N >> L >> T >> X >> W;
	std::vector<std::int64_t> result;
	if (W == 1)
	{
		result.emplace_back((X + T) % L);
	}
	else
	{
		result.emplace_back((X - (T%L) + L) % L);
	}
	auto start = result.front();
	std::int64_t h{};
	for (int i = 1; i < N; ++i)
	{
		int x, w;
		std::cin >> x >> w;
		if (w == 1)
		{
			result.emplace_back((x + T) % L);
			if (W == 2)
			{
				h -= rcount(X, x, T, L);
			}
		}
		else
		{
			result.emplace_back((x - (T%L) + L) % L);
			if (W == 1)
			{
				h += count(X, x, T, L);
			}
		}
		h %= N;
		if (h < 0)
		{
			h = (N + h) % N;
		}
	}
	lib::sort(result);
	auto s = lib::lower_bound(result, start);
	for (int i{}; i < N; ++i)
	{
		std::cout << result[(N + i + s - h) % N] << std::endl;
	}
}

