					ccwitr = 0;
					rep(i, ccw.size()) {
						if ((ccw[ccwitr] - pos + l) % l > (ccw[i] - pos + l) % l) {
							ccwitr = i;
						}
					}
				}
				else	ccwitr = (ccwitr + 1) % ccw.size();
				ll opos = (ccw[ccwitr] - cur + l) % l;
				ll dist = (l + opos - pos) % l;
				if (dist > 0 && cur + (dist >> 1) <= t) {
					cur += dist >> 1;
					pos = (pos + (dist >> 1)) % l;
					dir = 2;
				}
				else {
					pos = (pos + t - cur) % l;
					cur = t;
				}
			}
		}
		else {
			if (cw.size() == 0) {
				pos = (pos + l - t + cur) % l;
				cur = t;
			}
			else {
				if (cwitr == -1) {
					cwitr = 0;
					rep(i, cw.size()) {
						if ((pos - cw[i] + l) % l < (pos - cw[cwitr] + l) % l) {
							cwitr = i;
						}
					}
				}
				else	cwitr = (cwitr + 1) % cw.size();
				ll opos = (-cw[cwitr] + cur + l) % l;
				ll dist = (pos - opos + l) % l;
				if (dist > 0 && cur + (dist >> 1) <= t) {
					cur += dist >> 1;
					pos = (pos - (dist >> 1) + l) % l;
					dir = 1;
				}
				else {
					pos = (pos - t + cur + l) % l;
					cur = t;
				}
			}
		}
	}
	vector<pair<ll, int>> after(n);
	rep(i, n)	after[i] = mp((dat[i].first + (dat[i].second == 1 ? 1 : -1) * t + l) % l, -dat[i].second);
	sort(all(after));
	int out = -1;
	rep(i, n) {
		if (after[i] == mp(pos, -dir)) {
			out = i;
			break;
		}
	}
	rep(i, n) {
		cout << (after[out].first >> 1) << endl;
		out = (out + 1) % n;
	}
	return 0;
}

