ll nrev = 0;

int main() {
    ll i, j, k;
    ll x, y, a, b;

    scanner >> n >> len >> te;

    repeat(n) {
        scanner >> xx[cnt] >> ww[cnt];
        nrev += ww[cnt] == 2;

        ww[cnt] = ww[cnt] == 1 ? 1 : -1;
    }

    // L秒後には元の位置に蟻がいる（同じアリとは限らない）．
    // しかし，1番目のありの位置がわかれば，その右は２番目，3番目…である．
    // 衝突回数をカウント出来れば，1番目の有りの位置がわかる

    ll crash = 0;

    // 1週で1番のありがぶつかる回数
    ll rotcrash = (ww[0] == 1 ? nrev : n - nrev) * 2;

    crash += rotcrash*(te / len);

    // せっぺん
    ll tick = te%len;;

    // シミュレート．
    repeat(n) {
        yy[cnt] = (xx[cnt] + tick*ww[cnt]);
    }

    if (ww[0] == -1)
        yy[0] += len;
    for (i = 1; i < n; ++i) {
        if (ww[i] != ww[0] && yy[i]*ww[0] <= yy[0]*ww[0]) ++crash;
    }
    // twice
    yy[0] -= len*ww[0];
    for (i = 1; i < n; ++i) {
        if (ww[i] != ww[0] && yy[i]*ww[0] <= yy[0]*ww[0]) ++crash;
    }

    repeat(n) {
        xx[cnt] = ((xx[cnt] + te*ww[cnt])%len+len)%len;
    }

    repeat(n) { ii[cnt] = cnt; }

    sort(ii, ii + n, [](int l,int r) {return xx[l] < xx[r]; });

    ll index = ii[0];

    index = (((index + crash*ww[0] ) % n) + n) % n;

    repeat(n) {
