long long floormod(long long a, long long mod) {
  if (a > 0) return (a % mod);
  else if (a % mod == 0 ) return 0;
  else return (a % mod) + mod;
}

int main() {
  int N;
  ll L, T;
  cin >> N >> L >> T;
  vector<ll> X(N);
  vector<int> W(N);
  rep(i, N) cin >> X[i] >> W[i];

  ll a = T / L, b = T % L;
  ll colnum = 0;
  rep(i, N) {
    if (W[i] == W[0]) continue;
    colnum += 2 * a;
    ll x = X[0], y = X[i];
    if (W[0] != 1) swap(x, y);
    if (x > y) y += L;
    if (y - x <= 2 * b) colnum++;
    if (y - x + L <= 2 * b) colnum++;
  }

  colnum %= N;

  vector<ll> Y(N);
  rep(i, N) {
    if (W[i] == 1) Y[i] = floormod(X[i] + T, L);
    else Y[i] = floormod(X[i] - T, L);
  }

  ll Z = Y[colnum];

  sort(all(Y));

  auto iter = lower_bound(all(Y), Z);
  int M = iter - Y.begin();

  rep(i, N) {
    cout << Y[floormod(M + i, N)] << endl;
  }

}

