void init(ll n){
  for(int i=0;i<n;i++){
    par[i]=i;
    len[i]=0;
    ele[i]=1;
  }
}
ll root(ll n){
  if(par[n]==n)return n;
  return par[n]=root(par[n]);
}
void unit(ll a,ll b){
  a=root(a);
  b=root(b);
  if(a==b)return;
  if(len[a]<len[b]){
    par[a]=b;
    ele[b]+=ele[a];
  }
  else{
    par[b]=a;
    ele[a]+=ele[b];
    if(len[a]==len[b])len[a]++;
  }
}
