const int N = 1e5 + 2;

int n, l, t, pos[N], dir[N];
vector<int>pos_set;

int cnt(int a, int b) {
	for (; a < 0; a += l);
	for (; b >= l; b -= l);
	if (a < b) {
		if (b - a > 2 * t)return 0;
		return 1 + (2 * t - b + a) / (2 * l);
	}
	int dist = (l - a + b) / 2;
	if (l - a + b > 2 * t)return 0;
	return 1 + (t - l + a - b) / l;

}

int32_t main() {
	//freopen("oj.in", "r", stdin);
	cin >> n >> l >> t;
	for (int i = 0; i < n; ++i) {
		cin >> pos[i] >> dir[i];
		if (dir[i] == 2)dir[i] = -1;
		pos_set.push_back((l + 1LL * pos[i] + (t % l) * dir[i]) % l);
	}
	if (dir[0] == 2) {
		assert(4 == 7);
	}
	int shift = 0;
	for (int i = 1; i < n; ++i) {
		int a = pos[0], b = pos[i];
		if (dir[0] == 1 && dir[i] == -1) {
			int currShift = cnt(a, b);
			shift = (shift + currShift) % n;
			if (currShift) {
				int delta = (b - a) / 2;
				int na = (delta + 1) % l;
				int nb = (delta - 1 + l) % l;
				if (max(na, nb) != max(a, b) or min(a, b) != min(na, nb))
					shift = (shift + cnt(na, nb)) % n;
			}
		}
	}
	for (int i = 0; i < n; ++i) {
		cout << pos_set[(shift + n + i) % n] << '\n';
	}
}

