int main() {
	cin.tie(0);
	ios::sync_with_stdio(false);
	int n, l, t;
	cin >> n >> l >> t;
	vector<int> x(n), w(n), pos(n);
	for (int i = 0; i < n; i++) {
		cin >> x[i] >> w[i];
		if (w[i] == 1) {
			pos[i] = (x[i] + t % l) % l;
		} else {
			pos[i] = (x[i] - t % l + l) % l;
		}
	}

	int sum = 0;
	for (int i = 1; i < n; i++) {
		if (w[i] == w[0]) continue;
		sum += 2 * t / l;
		if (w[0] == 1) {
			sum += ((x[i] + l - x[0]) % l < 2 * t % l);
		} else {
			sum += ((x[0] + l - x[i]) % l < 2 * t % l);
		}
	}

	sort(pos.begin(), pos.end());

	int tar;
	if (w[0] == 2) {
		tar = pos[sum % n];
	} else {
		tar = pos[n - 1 - sum % n];
	}

	int idx;
	for (int i = 0; i < n; i++) {
		if (pos[i] == tar) {
			idx = i;
			if (i + 1 < n && pos[i + 1] == tar && w[0] == 2) idx = i - 1;
			break;
		}
	}

	idx = (idx + n) % n;

	for (int i = 0; i < n; i++) {
		cout << pos[(i + idx) % n] << endl;
	}

	return 0;
}

