	w = W.at(0);
	rcnt = 0;
	lcnt = 0;
	if (w == 1) {
		rcnt = rcnt_end - 1;
	}

	int x_final;
	bool is_final = false;
	while (true) {
		int y;
		int dt, dx;
		if (w == 1) {
			if (lcnt_end > 0) {
				y = lX.at(lcnt) - t;
				y += L;
				y %= L;

				if (x <= y) {
					dt = (y - x + 1) / 2;
					dx = (y - x - 1) / 2;
				}
				else {
					dt = (y + L - x + 1) / 2;
					dx = (y + L - x - 1) / 2;
				}
			}
			else {
				dt = L;
				dx = 0;
			}
			if (!is_final && t + dt > r) {
				x_final = x + r - t;
				x_final %= L;
				is_final = true;
			}
			if (t + dt > L) {
				x += L - t;
				x %= L;
				break;
			}
			x += dx;
			x %= L;
			t += dt;
			rcnt++;
			rcnt %= rcnt_end;
			if (lcnt_end > 0)
