				x_final = x - (r - t);
				x_final %= L;
				x_final += L;
				x_final %= L;
				is_final = true;
			}
			if (t + dt > L) {
				x -= L - t;
				x %= L;
				x += L;
				x %= L;
				break;
			}
			x += dx;
			x %= L;
			x += L;
			x %= L;
			t += dt;
			lcnt++;
			lcnt %= lcnt_end;
			if (rcnt_end > 0)
				w = 1;
		}
	}

	int did;
