typedef long long lint;
const int N=1e5+5;
int n,len,q,pos[N];
int turn_0,turn_1,cnt_0,cnt_1,buk_0[N],buk_1[N];
bool stat[N];//0: clockwise, 1: counter

inline int nxi(){
	int x=0;
	char c;
	while((c=getchar())>'9'||c<'0');
	while(x=x*10-48+c,(c=getchar())>='0'&&c<='9');
	return x;
}

int main(){
	n=nxi(),len=nxi(),q=nxi();
	for(int i=1; i<=n; ++i){
		pos[i]=nxi(),stat[i]=nxi()-1;
	}
	int cyc=q/len,rest=q-cyc*len;
	lint dlt=0;
	for(int i=1; i<=n; ++i){
		if(stat[i]==0){
			dlt+=cyc;
			int tgt=pos[i]+rest;
			if(tgt>=len) ++dlt,tgt-=len;
			else turn_0=cnt_0+1;
			buk_0[++cnt_0]=tgt;
		}
		else{
			dlt-=cyc;
			int tgt=pos[i]-rest;
			if(tgt<0){
				--dlt,tgt+=len;
				turn_1=cnt_1;
			}
			buk_1[++cnt_1]=tgt;
		}
	}
	for(int c=1,i=1,j=turn_0+1,k=turn_1,l=cnt_1; c<=n; ++c){
		int type=0,nval=1e9;
		if(i<=turn_0&&buk_0[i]<nval)
			nval=buk_0[i],type=1;
		if(j<=cnt_0&&buk_0[j]<nval)
			nval=buk_0[j],type=2;
		if(k>0&&buk_1[k]<nval)
			nval=buk_1[k],type=3;
		if(l>turn_1&&buk_1[l]<nval)
			nval=buk_1[l],type=4;
		assert(type);
		pos[c]=nval;
		switch(type){
			case 1: ++i; break;
			case 2: ++j; break;
			case 3: --k; break;
			case 4: --l; break;
		}
	}
	dlt%=n;
	if(dlt<0) dlt+=n;
	for(int i=dlt+1; i<=n; ++i){
		printf("%d\n",pos[i]);
	}
	for(int i=1; i<=dlt; ++i){
		printf("%d\n",pos[i]);
	}
	return 0;
}

