                    cnt += cnts;
                    cnt %= n;
                }
            }
        } else {
            if (w[i] == 1) {
                long long len = (x[0] + l - x[i]) / 2;
                if (len < t) {
                    long long cnts = 1 + (2LL * (t - len) - 1) / l;
                    cnt += cnts;
                    cnt %= n;
                }
            }
        }
    }
    if (w[0] == 2) {
        cnt = (n - cnt) % n;
    }
    vector<long long> vv;
    for (int i = 0; i < n; i++) {
        if (w[i] == 1) {
            long long xx = x[i] + t;
