		if (W[i] == 1) Y[i] = ((X[i]+T)%L+L)%L; else Y[i] = ((X[i]-T)%L+L)%L;
	}
	long long sumc = 0;
	for(int i = 1 ; i <= N-1 ; i++) {
		if (W[0] != W[i]) {
			if (W[0] == 1 && X[i]-X[0] < T*2) {
