			}
			if (W[0] == 2 && L-(X[i]-X[0]) < T*2) {
				sumc += 1+(T*2 - (L-(X[i]-X[0]) - 1))/L;
			}
		}
	}
	long long z;
	// cout << sumc << "\n";
	if (W[0] == 1) {
		z = sumc%N;
	} else {
		z = (N-sumc%N)%N;
	}
	// cout << z << "\n";
	long long y = Y[0], n;
	sort(Y.begin(), Y.end());
	if (W[0] == 1) {
		n = distance(Y.begin(), lower_bound(Y.begin(), Y.end(), y));
