const int MAXN = 1e5 + 10;

int N;
ll L, T;
vector<ant> ants;

bool read() {
	if  (scanf("%d%lld%lld", &N, &L, &T) < 3) {
		return 0;
	}
	ants.resize(N);
	forn(i, N) {
		ants[i].read(i);
	} 
	return 1;
}

ll coord(ll x) {
	x %= L;
	if  (x < 0) {
		x += L;
	}
	return x;
}

ll final[MAXN];

void make_ans() {
	vi finals;
	forn(i, N) {
		ll pos = ants[i].x + (ants[i].w ? -1 : +1) * T;
		finals.pb(coord(pos));
	}

	sort(all(finals));
	int id0 = -1;
	forn(i, N) {
		if  (finals[i] == final[ants[0].id]) {
			id0 = i;
			break;
		}
	}
	assert(id0 != -1);
	for (int i = 1; i < N; ++i) {
		final[ants[i].id] = finals[(id0 + i) % N];
	}
}

void solve1() {
	vll opposite;
	vll my;
	for (int i = 1; i < N; ++i) {
		if  (ants[i].w == 1) {
			opposite.pb(ants[i].x);
		} else {
			my.pb(ants[i].x);
		}
	}

	// forn(i, N) {
	// 	printf("x=%d w=%d\n", ants[i].x, ants[i].w);
	// }

	if  (opposite.empty() || opposite.front() - ants[0].x >= 2 * T) {
		final[ants[0].id] = coord(ants[0].x + T);
		make_ans();
		return;
	}

	// printf("opposite:\n");
	// for (int x : opposite) {
	// 	printf("%d ", x);
	// }
	// puts("");
	// printf("my:\n");
	// for (int x : my) {
	// 	printf("%d ", x);
	// }
	// puts("");

	ll nT = 2 * T;
	ll dist = opposite.front() - ants[0].x;
	for (auto& x : opposite) {
		x -= dist;
		assert(x >= 0);
	}
	nT -= dist;

	// printf("nT=%d\n", nT);

	vll go;
	if  (!my.empty()) {
		ll prv = ants[0].x;
		ford(i, sz(my)) {
			ll dist = prv - my[i];
			if  (dist < 0) {
				dist += L;
			}
			go.pb(dist);
			prv = my[i];
		}
		go.pb(my.front() - ants[0].x);
	} else {
		go.pb(L);
	}

	vll stay;
	ll prv = opposite.front();
	for (int i = 1; i < sz(opposite); ++i) {
		ll dist = opposite[i] - prv;
		stay.pb(dist);
		prv = opposite[i];
	}
	stay.pb(ants[0].x - opposite.back() + L);

	vll pref_go(sz(go) + 1);
	forn(i, sz(go)) {
		pref_go[i + 1] = pref_go[i] + go[i];
	}

	vll pref_stay(sz(stay) + 1);
	forn(i, sz(stay)) {
		pref_stay[i + 1] = pref_stay[i] + stay[i];
	}

	// printf("go:\n");
	// for (int x : go) {
	// 	printf("%d ", x);
	// }
	// puts("");
	// printf("stay:\n");
	// for (int x : stay) {
	// 	printf("%d ", x);
	// }
	// puts("");

	ll Left = -1;
	ll Right = nT + 1;
	while (Left != Right - 1) {
		ll len = (Left + Right) / 2;

		ll cnt_go = (len + 1) / 2;
		ll cnt_stay = len - cnt_go;

		ll was_go = (cnt_go / sz(go)) * pref_go[sz(go)];
		was_go += pref_go[cnt_go % sz(go)];
		ll was_stay = (cnt_stay / sz(stay)) * pref_stay[sz(stay)];
		was_stay += pref_stay[cnt_stay % sz(stay)];

		if  (was_go + was_stay <= nT) {
			Left = len;
		} else {
			Right = len;
		}
	}

	{
		ll len = Left;
		assert(len >= 0);
		// printf("len=%lld\n", len);
		ll cnt_go = (len + 1) / 2;
		ll cnt_stay = len - cnt_go;

		ll was_go = (cnt_go / sz(go)) * pref_go[sz(go)];
		was_go += pref_go[cnt_go % sz(go)];
		ll was_stay = (cnt_stay / sz(stay)) * pref_stay[sz(stay)];
		was_stay += pref_stay[cnt_stay % sz(stay)];

		// printf("was=%lld\n", was);
		ll dist = was_go;
		if  (~len & 1) {
			dist += nT - was_go - was_stay;
		}
		// printf("dist=%lld\n", dist);
		ll pos = coord(ants[0].x - dist);
		// printf("x0=%d, pos=%lld\n", ants[0].x, pos);
		// printf("pos=%lld, T=%d, L=%d\n", pos, T, L);
		final[ants[0].id] = coord(pos + T);
		make_ans();
	}
}

void solve() {
	ll offset = 0;
	int id = -1;
	forn(i, N) {
		if  (ants[i].w == 0) {
			id = i;
			break;
		}
	}
	if  (id != -1) {
		// ants[id].x + off = 0
		offset = -ants[id].x;
		forn(i, N) {
			ants[i].x = coord(ants[i].x + offset);
		}
		vector<ant> nants;
		for (int i = id; i < N; ++i) {
			nants.pb(ants[i]);
		}
		forn(i, id) {
			nants.pb(ants[i]);
		}
		ants.swap(nants);
	}
	solve1();

	forn(i, N) {
		printf("%lld\n", coord(final[i] - offset));
	}
}

