using namespace output;

ll N, L, T;
vll solve(vll pos, vb dir) {
	ll s = 0;
	while (s < N && !dir[s]) ++s;

	if (s == N) {
		// all facing the same way case
		vll ans (N);
		F0R(i, N) {
			ans[i] = ((pos[i] - T) % L + L) % L;
		}
		return ans;
	}

	ll opp = 0;
	F0R(i, N) if (!dir[i]) ++opp;
	ll bumps = opp * ((2 * T) / L);

	F0R(i, N) if (!dir[i]) {
		ll dist = 0;
		if (pos[i] < pos[s]) 
			dist = L - pos[s] + pos[i];
		else
			dist = pos[i] - pos[s];
		if (dist < ((2 * T) % L)) bumps++;
	}

	vll ans (N);
	vll spots (N);
	F0R(i, N) {
		ll npos;
		if (dir[i])
			npos = (pos[i] + T) % L;
		else
			npos = (((pos[i] - T) % L) + L) % L;
		spots[i] = npos;
	}
	sort(spots.begin(), spots.end());
	int i = 0; 
	while (spots[i] != (pos[s] + T) % L) ++i;
	F0R(j, N) ans[(s + bumps + j) % N] = spots[(i + j) % N];
	return ans;
}

int main() {
    ios::sync_with_stdio(0), cin.tie(0), cout.tie(0);
	cin >> N >> L >> T;
	vll pos (N);
	vb dir (N); // is clockwise
	F0R(i, N) {
		ll x, d; cin >> x >> d;
		pos[i] = x;
		dir[i] = (d == 1);
	}

	vll ans = solve(pos, dir);

	for (ll x : ans) print(x);
}

