  for (int i: range(0, N)) {
    std::cin >> X[i] >> D[i];
    D[i] = (D[i] == 1 ? 1 : -1);
    after[i] = mod(X[i] + D[i] * T, L);
    if (D[i] == 1) {
      int val = T - (L - X[i]);
      if (val >= 0) {
        count += val / L + 1;
      }
    }
    else {
      int val = (T - 1) - X[i];
      if (val >= 0) {
        count -= val / L + 1;
      }
    }
  }
  std::sort(after.begin(), after.end());
  for (int i: range(0, N)) {
    std::cout << after[mod(count + i, N)] << '\n';
  }
  return 0;
}

