int main()
{
    int N, L, T;
    cin >> N >> L >> T;

    int X[N];
    int W[N];
    int Z[N];

    for (int i = 0; i < N; i++)
    {
        cin >> X[i] >> W[i];
        if (W[i] == 1)
        {
            Z[i] = X[i] + T;
            if (Z[i] >= L)
            {
                Z[i] = Z[i] % L;
            }
        }
        else
        {
            Z[i] = X[i] - T;
            if (Z[i] < 0)
            {
                Z[i] = Z[i] % L + L;
            }
        }
    }

    int first = Z[0];
    sort(Z, Z + N);
    auto iter = find(Z, Z + N, first);
    int index = distance(Z, iter);

    int zekken = 0;
    for(int i=1;i<N;i++) {
        if(W[i]!=W[0]) zekken++;
    }

    zekken = zekken * (T/L) * 2;
    T = T % L;

    for (int i = 1; i < N; i++)
    {
        if (W[0] == 1)
        {
            if (X[i] - X[0] > 2 * T)
            {
                break;
            }
            if (W[i] != W[0])
            {
                zekken++;
            }
        }
        else
        {
            if (X[0] + L - X[N - i] > 2 * T)
            {
                break;
            }
            if (W[N - i] != W[0])
            {
                zekken--;
            }
        }
    }

    zekken = (index - (zekken % N))%N;
    cout << zekken << endl;

    for (int i = zekken; i < N + zekken; i++)
    {
        if (i < 0)
            cout << Z[N + i] << endl;
        else if (i >= N)
            cout << Z[i - N] << endl;
        else
            cout << Z[i] << endl;
    }

    return 0;
}

