using namespace std;
const int N = 1e5 + 5;
int x[N], d[N], ans[N];
int main() {
	int n, l, t;
	scanf("%d%d%d", &n, &l, &t);
	/*int seed = time(0);
	cout << seed << endl;
	srand(seed);
	n = 50000, l = 500000, t = 1000000000;*/
	vector<int> L, R, X;
	/*for (int i = 0; i < l; ++ i) X.push_back(i); random_shuffle(X.begin(), X.end());
	X.resize(n); sort(X.begin(), X.end());*/
	for (int i = 0; i < n; ++ i) {
		scanf("%d%d", &x[i], &d[i]);
		//x[i] = X[i], d[i] = rand() % 2 + 1;
		(d[i] == 1 ? R : L).push_back(x[i]);
		(d[i] == 1 ? R : L).push_back(x[i] - l);
		(d[i] == 1 ? R : L).push_back(x[i] + l);
	}
	sort(L.begin(), L.end());
	sort(R.begin(), R.end());
	if (L.empty()) {
		for (int i = 0; i < n; ++ i) printf("%lld ", 1LL * (x[i] + t) % l); puts("");
		return 0;
	}
	if (R.empty()) {
		for (int i = 0; i < n; ++ i) printf("%lld ", (1LL * (x[i] - t) % l + l) % l); puts("");
		return 0;
	}
	int base = (2 * t) / l;
	for (int i = 0; i < n; ++ i) {
		if (d[i] == 1) {
			int rt = 2 * t - base * l;
			int cnt2 = upper_bound(L.begin(), L.end(), x[i] + rt) - lower_bound(L.begin(), L.end(), x[i]);
			int cnt = 0;
			for (int y : L) if (y >= 0 && y < l) if ((y - x[i] + l) % l <= rt) cnt ++;
			assert(cnt2 == cnt);
			cnt += 1LL * base * L.size(); // % n;
			ans[(i + cnt) % n] = (x[i] + t) % l;
		}
		else {
			int rt = 2 * t - base * l;
			int cnt2 = upper_bound(R.begin(), R.end(), x[i]) - lower_bound(R.begin(), R.end(), x[i] - rt);
			int cnt = 0;
			for (int y : R) if (y >= 0 && y < l) if ((x[i] - y + l) % l <= rt) cnt ++;
			assert(cnt2 == cnt);
			cnt += 1LL * base * R.size(); // % n;
			ans[((i - cnt) % n + n) % n] = ((x[i] - t) % l + l) % l;
		}
	}
	for (int i = 0; i < n; ++ i) printf("%d ", ans[i]); puts("");
}

