#include <iostream>
#include <map>
#include <vector>
#include <algorithm>

class Ant{
public:
    int order;
    int pos, next_pos;
    bool dir, next_dir; // true:clockwise
    int len;
    Ant() {};
    void move (){
        if(dir) next_pos = (pos + 1) % len;
        else if (pos > 0) next_pos = pos - 1;
        else next_pos = len - 1;
        next_dir = dir;
    }
    void invert (){
        if(dir) dir = false;
        else dir = true;
    }
    void invert_stay (){
        if(dir) next_dir = false;
        else next_dir = true;
        next_pos = pos;
    }
    bool collide (bool d, int p){
        if ((d == true && dir == false && dist(p) == 1) || (d == false && dir == true && dist(p) == len - 1)) return true;
        else return false;
    }
    int dist (int p){
        int ret = pos - p;
        if(ret < 0) ret = len + ret;
        return ret;
    }
    void update(){
        pos = next_pos;
        dir = next_dir;
    }
};

int main(int argc, const char * argv[]) {
    // insert code here...
    int N, L, T;
    std::map<int, Ant*> ants;
    std::cin >> N >> L >> T;

    for(int id = 0; id < N; id++){
        int this_pos, dir_id;
        bool this_dir = true;
        std::cin >> this_pos >> dir_id;
        if(dir_id == 2) this_dir = false;
        Ant* this_ant = new Ant();
        this_ant->order = id;
        this_ant->pos = this_pos;
        this_ant->dir = this_dir;
        this_ant->len = L;
        ants.insert(std::make_pair(id, this_ant));
    }
    // clock tick loop
    for(int clock = 0; clock < T; clock++){
        Ant* pre;
        Ant* me;

        for(int id = 0; id < N; id++){
            bool collide_flag = false;
            me = ants[id];
            for(int nid = 0; nid < N; nid++){
                if(nid == id) continue;
                pre = ants[nid];
                if(pre->pos == me->pos) {
                    me->invert();
                }
                if(me->collide(pre->dir, pre->pos)){
                    collide_flag = true;
                    me->invert_stay();
                }
            }
            if(!collide_flag) {
                me->move();
            }
        }
        for(int id = 0; id < N; id++){
            ants[id]->update();
        }
    }
    for(int id = 0; id < N; id++){
        std::cout << ants[id]->pos << std::endl;
    }
    return 0;
}

