ll ans[maxn];

int main(){
  int n; cin >> n;
  ll L; cin >> L;
  ll T; cin >> T;
  vector<ll> cw;
  vector<int> cw_ids;
  vector<ll> ccw;
  vector<int> ccw_ids;
  for(int i=0;i<n;i++){
    ll x; int w; cin >> x >> w;
    if(w == 1){
      cw.push_back(x); cw_ids.push_back(i);
    }
    else {ccw.push_back(x); ccw_ids.push_back(i);}
  }
  vector<ll> final_positions;
  for(ll e : ccw){
    ll eprime = (e - T) % L;
    eprime = (eprime + L) % L;
    final_positions.push_back(eprime);
    if(cw.size() == 0){
      cout << eprime << "\n";
    }
  }
  for(ll e : cw){
    ll eprime = (e + T) % L;
    final_positions.push_back(eprime);
    if(ccw.size() == 0){
      cout << eprime << "\n";
    }
  }
  if(ccw.size() == 0 || cw.size() == 0) {
    assert(false);
    return 0;
  }
  sort(final_positions.begin(), final_positions.end());
  //that was the easy part.
  int me = cw[0]; // every time I bump into someone, my label increases by 1.
  ll num_bumps = 0;
  for(ll x : ccw){
    int t2 = -1;
    if(x < cw[0]){
      t2 = L - (cw[0] - x);
    }
    else{
      t2 = x - cw[0];
    }
    num_bumps += 1 + (2 * T - t2) / L;
  }
  int my_label = (cw_ids[0] + num_bumps) % n;
  ll my_position = (cw[0] + T) % L;
  int ee = upper_bound(final_positions.begin(), final_positions.end(), my_position) - final_positions.begin() - 1;
  for(int l = my_label; ; l = (l + 1) % n, ee = (ee + 1) % n){
    ans[l] = final_positions[ee];
    if(l == my_label - 1) break;
  }
  for(int i=0;i<n;i++){
    cout << ans[i] << "\n";
  }
}

