typedef long long ll;
int N,L,T;
#define MAXN 100000
int X[MAXN],W[MAXN];
ll ans[MAXN];
void getans(){
    rep(i,N){
        if(W[i]==1)ans[i] = X[i] + T;
        else ans[i] = X[i]-T;
        if(ans[i]<0){
            ans[i] += ((ans[i]/L)+1)*L;
        }
        ans[i] %= L;
    }
    sort(ans,ans+N);
}

int main(){
    cin >> N >> L >> T;
    rep(i,N)cin >> X[i] >> W[i];
    int rout = W[0];
    ll cross = 0;
    for(int i=1;i<N;i++){
        if(W[i]==rout)continue;
        else{
            int tmp = X[i];
            double tmpt = T;
            tmpt -= double(tmp-W[0])/2;
            if(tmpt>=0){
                cross++;
                if(tmpt>=double(L/2)){
                    cross += (int)tmpt/(L/2);
                }
            }
        }
    }
    ll num ;
    if(W[0]==1){
        num =  1+cross;
    }else{
        num -= (cross-1);
        while(num < 0){
            num += L;
        }
    }
    num %= N;
    ll place;
    if(rout==1){
        place= X[0]+T;
    }else {
        place = X[0]-T;
        place += (1+(place/L))*L;
    }
    place %= L;
    num%=N;
    getans();
    int start;
    for(int i=0;i<N;i++){
        if(place==ans[i]){
            start = i;
            break;
        }
    }

    start -= num-1;
    if(start<0)start += L;
    for(int i = start;i<N;i++){
        cout << ans[i] << endl;
    }
    for(int i=0;i<start;i++){
        cout << ans[i] << endl;
    }
    return 0;
}

