    times(N, i) {
        scanf("%lld%lld",&X[i],&W[i]);
        if(W[i] == 1) {
            I1[N1] = i;
            X1[N1++] = X[i];
        } else {
            I2[N2] = i;
            X2[N2++] = X[i];
        }
    }
