        X1[0] += L;
        reverse(X1+1, X1+N1);
        reverse(I1+1, I1+N1);
    } else {
        reverse(X1, X1+N1);
        reverse(I1, I1+N1);
    }
    if(debug) {
        cout << "X1: "; times(N1, i) cout << X1[i] sp; cout ln;
        cout << "X2: "; times(N2, i) cout << X2[i] sp; cout ln;
    }

    int k;
    if(!N1 || !N2) {
        k = 0;
    } else {
        if(fmod(X2[0] - X1[0]) > T * 2) {
            k = 0;
        } else {
            int l = 0, r = T * 2;
            while(l < r) {
                int m = (l + r) / 2, m1 = (m + F1) / 2, m2 = (m + !F1) / 2;
                long x1 = L * (m1 / N1), x2 = L * (m2 / N2);
                upto(1, m1 % N1, i) x1 += X1[i-1] - X1[i];
                upto(1, m2 % N2, i) x2 += X2[i] - X2[i-1];
                if(debug) {
                    cout << "[m m1 m2]: " << m sp << m1 sp << m2 sp
                         << "[x1 x2 fmod(...)]: " << x1 sp << x2 sp << fmod(X2[0]-X1[0]) ln;
                }
                if(x1 + x2 + fmod(X2[0] - X1[0]) > T * 2) {
                    if(r == m) break;
                    r = m;
                } else {
                    if(l == m) break;
                    l = m;
                }
            }
            if(debug) cout << "l: " << l ln;
            k = l % 2 == F1 ? I1[(l+1) / 2 % N1] : I2[(l+1) / 2 % N2];
        }
    }

    if(debug) cout << "k: " << k ln;

    times(N, i) X[i] = fmod((W[i] == 1 ? X[i] + T : X[i] - T) % L);
    sort(X, X + N);
    times(N, i) printf("%d\n", X[(i - k + N) % N]);

    return 0;
}

