long long coor[MAXN], w[MAXN];

long long get(long long coor, long long w) {
	if (w == 1) {
		return (L - coor) % L;
	}
	return coor;
}

long long get_dir(long long coor, long long w) {
	if (w == 1) {
		return (coor + t / 2) % L;
	}
	long long ans = coor - t / 2;
	ans %= L;
	while (ans < 0) ans += L;
	return ans;
}

vector <long long> ans;
long long res[MAXN];

int main() {
	srand(time(0));
	ios::sync_with_stdio(0);
	//read(FILENAME);
	cin >> n >> L >> t;
	t *= 2;
	for (int i = 0; i < n; ++i) {
		cin >> coor[i] >> w[i];
		ans.pb(get_dir(coor[i], w[i]));
	}
	sort(ans.begin(), ans.end());
	int j = 0;
	long long d = coor[j], de = get_dir(coor[j], w[j]);
	for (int i = 0; i < n; ++i) {
		coor[i] = (coor[i] - d) % L;
		while (coor[i] < 0) coor[i] += L;
	}
	bool OK = false;
	for (int i = 0; i < n; ++i) {
		if (w[i] != w[j]) {
			long long mt = t;
			if (get(coor[i], w[i]) == t && w[i] == 1) {
				OK = true;
			}
			if (get(coor[i], w[i]) < t) {
				mt -= get(coor[i], w[i]);
				++cnt;
				cnt += (mt - 1) / L;
				if (mt % L == 0 && w[i] == 1)
					OK = true;
				cnt %= n;
			}
		}
	}
	long long q = -1;
	if (w[j] == 1) {
		q = (j + cnt) % n;
	} else {
		q = j - cnt;
		q %= n;
		while (q < 0)
			q += n;
	}
	long long L = 0;
	for (int i = 0; i < n; ++i) {
		if (ans[i] == de) {
			if (OK) {
				OK = false;
			} else {
				L = i;
				break;
			}
		}
	}
	for (int i = 0; i < n; ++i) {
		res[q] = ans[L];
		++q;
		q %= n;
		++L;
		L %= n;
	}
	for (int i = 0; i < n; ++i) {
		cout << res[i] << endl;
	}
}

