void solve(long long N, long long L, long long T, vector<long long> X, vector<long long> W){
	vector<long long> Y(N);
	for(int i = 0 ; i <= N-1 ; i++) {
		if (W[i] == 1) Y[i] = ((X[i]+T)%L+L)%L; else Y[i] = ((X[i]-T)%L+L)%L;
	}
	long long sumc = 0, suml = 0;
	for(int i = 1 ; i <= N-1 ; i++) {
		if (W[0] != W[i]) {
			suml++;
			if (abs(X[i]-X[0]) <= T%L*2) sumc++;
		}
	}
	sumc += (T/L)*suml;
	// cout << sumc << "\n";
	if (W[0] == 1) {
		for(int i = (N-sumc%N)%N ; i <= (N-sumc%N)%N+N-1 ; i++) {
			cout << Y[i%N] << "\n";
		}
	} else {
		for(int i = (sumc%N)%N ; i <= (sumc%N)%N+N-1 ; i++) {
			cout << Y[i%N] << "\n";
		}
	}

}

int main(){
	long long T;
	long long L;
	long long N;
	scanf("%lld",&N);
	vector<long long> X(N-1+1);
	vector<long long> W(N-1+1);
	scanf("%lld",&L);
	scanf("%lld",&T);
	for(int i = 0 ; i <= N-1 ; i++){
		scanf("%lld",&X[i]);
		scanf("%lld",&W[i]);
	}
	solve(N, L, T, X, W);
	return 0;
}

