    for(double i = 0; i < N; i++){
        if(W.at(0) != W.at(i)){

            ll sa;
            if(!W.at(0)){//時計回り
                if(X.at(0) >= X.at(i)){
                    sa = (L-X.at(0)) + X.at(i);
                }else{
                    sa =  X.at(i) - X.at(0);
                }
            }
            else{//反時計回り
                if(X.at(0) >= X.at(i)){
                    sa = X.at(0) - X.at(i);
                }else{
                    sa =  X.at(0) + (L - X.at(i));
                }
            }

            if(T >= sa / 2.0){
                through++;
                T -= sa / 2.0;
                through += double(T / (L / 2));
            }
        }
        T = T_copy;
    }

    ll position = 0;//蟻０の場所


    if(W.at(0)){//反時計回り
        position -= through;
    }else{//時計回り
        position += through;

    }

    position = ((position % N) + N) % N;


    ll P = afterX.at(0);


    sort(afterX.begin(), afterX.end());


    bool l = 0;
    ll I1,I2;
    int cnt = 0;
    for(int i = 0; i < N; i++){
        if(afterX.at(i) == P){
            cnt++;
            if(cnt == 1){
                I1 = i;
            }
            else if(cnt == 2){
                I2 = i;
                l = 1;
            }
        }

    }

    if(l){
        if( (W.at(0) + through) % 2 == 1){
            I1 = I2;
        }else{
            I1--;
        }
    }

    for(int i = 0; i < N; i++){
        cout << afterX.at((((I1 - position + i) % N) + N) % N) << endl;
    }

}

