					int mid=(ok+ng)/2, dis;
					dis=X[i]-X[cw[(t+cw.size()-mid)%cw.size()]];
					if(dis<0) dis += L;
					if(dis<=r*2) ok=mid;
					else ng=mid;
				}
				irek[(i+N-(q*cw.size()+ng)%N)%N]=i;
			}
		}
		for(int i=0; i<N; ++i){
			cout << ans[irek[i]] << endl;
		}
	}
	return 0;
}

