{
    ll res = 0, diff = -1;

    if (W[a] == 1 && W[b] == 2) {
        diff = (X[b] - X[a]);
    } else if (W[a] == 2 && W[b] == 1) {
        diff = L - (X[b] - X[a]);
    }

