		b >>= 1;
	}
	return ret;
}

int main() {
	int n, l, t;	cin >> n >> l >> t;
	t <<= 1;	l <<= 1;
	t %= l;
	vint cw, ccw;
	vector<pii> dat;
	rep(i, n) {
		int x, w;	cin >> x >> w;
		x <<= 1;
		if (w == 1)	cw.push_back(-x);
		else	ccw.push_back(x);
		dat.push_back(mp(x, w));
	}
	sort(all(cw));	sort(all(ccw));
	int dir = dat[0].second;
	int pos = dat[0].first;
	int cur = 0;
	while (cur < t) {
		if (dir == 1) {
			if (ccw.size() == 0) {
				pos = (pos + t - cur + l) % l;
				cur = t;
			}
			else {
				int coll = upper_bound(all(ccw), (pos + cur) % l) - ccw.begin();
				if (coll == ccw.size()) {
					coll = 0;
				}
				int opos = (ccw[coll] - cur + l) % l;
				int dist = (l + opos - pos) % l;
				if (dist > 0 && cur + (dist >> 1) <= t) {
					cur += dist >> 1;
					pos = (pos + (dist >> 1)) % l;
					dir = 2;
				}
				else {
					pos = (pos + t - cur) % l;
					cur = t;
				}
			}
		}
		else {
			if (cw.size() == 0) {
				pos = (pos + l - t) % l;
				cur = t;
			}
			else {
				int coll = upper_bound(all(cw), -((pos - cur + l) % l)) - cw.begin();
				if (coll == cw.size())	coll = 0;
				int opos = (-cw[coll] + cur + l) % l;
				int dist = (pos - opos + l) % l;
				if (dist > 0 && cur + (dist >> 1) <= t) {
					cur += dist >> 1;
					pos = (pos - (dist >> 1) + l) % l;
					dir = 1;
				}
				else {
					pos = (pos - t + cur + l) % l;
					cur = t;
				}
			}
		}
	}
	vector<pii> after(n);
	rep(i, n)	after[i] = mp((dat[i].first + (dat[i].second == 1 ? 1 : -1) * t + l) % l, -dat[i].second);
	sort(all(after));
	int out = -1;
	rep(i, n) {
		if (after[i] == mp(pos, -dir)) {
			out = i;
			break;
		}
	}
	if (out == -1) {
		// 強制デバッグ
		cout << 1 / 0 << endl;
	}
	else {
		rep(i, n) {
			cout << (after[out].first >> 1) << endl;
			out = (out + 1) % n;
		}
	}
	return 0;
}

