int main() {

    ll d, k;
    int slide, cnt;

    cin >> N >> L >> T;
    for (int i = 0; i < N; i++) {
        cin >> x[i] >> w[i];
        w[i] = (w[i] == 1 ? 1 : -1);
        xa[i] = ((x[i] + w[i] * T) % L + L) % L;
    }
    sort(xa, xa + N);

    k = 0;
    for (int i = 1; i < N; i++) {
        d = (x[i] + w[i] * T) - (x[0] + w[0] * T);
        // cout << "d : " << d << endl;
        k += (d > 0) ? (d / L) : (-d / L + 1);
        // cout << "k : " << k << endl;
    }
    k = (k * w[0] + N) % N;
    slide = lower_bound(xa, xa + N, ((x[0] + w[0] * T) % L + L) % L) - xa;
    // cout << "slide : " << slide << endl;
    cnt = upper_bound(xa, xa + N, ((x[0] + w[0] * T) % L + L) % L) - xa - slide;
    // cout << "cnt : " << cnt << endl;
    // if (cnt >= 2) {
    //     slide += (((x[0] + w[0] * T) % L + L) % L == ((x[1] + w[1] * T) % L + L) % L) ? 0 : 0;
    // }

    for (int i = 0; i < N; i++) {
        cout << xa[(N + slide - k + i) % N] << endl;
    }

    return 0;

}

