int N;
i64 L,T;
vector<i64> X;
vector<i64> W;
vector<i64> Xs[3];

int main(){
  cin >> N >> L >> T;
  X.resize(N);
  W.resize(N);
  rep(i,0,N - 1){
    cin >> X[i] >> W[i];
    Xs[W[i]].push_back(X[i] - 2 * L);
    Xs[W[i]].push_back(X[i] - L);
    Xs[W[i]].push_back(X[i]);
    Xs[W[i]].push_back(X[i] + L);
    Xs[W[i]].push_back(X[i] + 2 * L);
  }

  sort(begin(Xs[1]),end(Xs[1]));
  sort(begin(Xs[2]),end(Xs[2]));

  i64 cou = 0;

  rep(i,1,N - 1){
    if(W[i] != W[0]){
      cou++;
    }
  }

  i64 dif;
  if(W[0] == 1){
    dif = cou;
  }
  else{
    dif = N - cou;
  }

  vector<i64> ans(N,-1);

  rep(i,0,N - 1){
    i64 x = X[i];
    int num = (i + dif * (T / L)) % N;
    i64 re = T % L;
    if(W[i] == 1){
      int to = upper_bound(Xs[2].begin(),Xs[2].end(),x) - Xs[2].begin();
      int from = lower_bound(begin(Xs[2]),end(Xs[2]),x - 2 * re) - begin(Xs[2]);
      num = (num + to - from) % N;
      x += re;
      ans[num] = x % L;
    }
    else{
      int from = upper_bound(begin(Xs[1]),end(Xs[1]),x) - begin(Xs[1]);
      int to = upper_bound(begin(Xs[1]),end(Xs[1]),x + 2 * re) - begin(Xs[1]);
      num = (num + N - (to - from)) % N;
      x += L - re;
      ans[num] = x % L;
    }
  }

  for(auto i : ans){
    cout << i << endl;
  }
}

