    vector<int> w(n);
    rep(i,n) scanf(" %lld %d", &x[i], &w[i]);

    vector<ll> ant_pos(n);
    rep(i,n)
    {
        if(w[i]==1) ant_pos[i] = (x[i]+T)%L;
        else ant_pos[i] = (x[i]-T+L*1000000000)%L;
    }

    // rep(i,n) printf(" ant_pos[%d] = %lld\n", i,ant_pos[i]);

