        if(W[i]*W[0]<0)hit_one.push_back(i);
    }
    long long int list_ans[100002];
    rep(i,N){
        long long miniT=T%L;
        list_ans[i]=( ( (X[i]+W[i]*miniT)%L)+L)%L;
