        if(W[0]==1)kyori=abs(X[hit_one[i]]-X[0]);
        else kyori=X[0]+(L-X[hit_one[i]]);
        if(2*T>=kyori)zero_to_what+= ( ((2*T-kyori)/L)+1 );
    }
    zero_to_what=( (zero_to_what%N*W[0])+N)%N;
