if(zero_to_what_x<N-1&&list_ans[zero_to_what_x]==list_ans[zero_to_what_x+1]){
if(W[0])zero_to_what_x+=1;
}
    //つまりzero_to_what+iの座標はlist_ans[zero_to_what_x+i]
    rep(i,N){
        printf("%lld\n",list_ans[(zero_to_what_x+i-zero_to_what+N)%N]);
    }

}

