		read(x[i]); read(w[i]);
		if (w[i] == 1) f[i] = (x[i] + T) % L;
		else f[i] = (x[i] - T % L + L) % L;
	}
	f1 = f[1]; T <<= 1;
	sort(f + 1, f + n + 1);
