  vector<pair<int,int>> tmp;
  while(1){
    tmp.push_back({t,idx});
    if(w==1){
      ll tp=lf[0];
      ll td=(X[tp]+L-X[idx])%L/2;
      while(td<=t){td+=L/2;}
      if(td>rem){break;}
      t=td;
      idx=tp;
      lf.pop_front();
      lf.push_back(tp);
    }
    else{
      ll tp=rg[0];
      ll td=(X[idx]+L-X[tp])%L/2;
      while(td<=t){td+=L/2;}
      if(td>rem){break;}
      t=td;
      idx=tp;
      rg.pop_front();
      rg.push_back(tp);
    }
    w^=3;
  }
  int C=idx;
  vector<pair<int,int>> pts(N);
  for(int i=0;i<N;i++){
    pts[i]={point(i),W[i]};
  }
  sort(pts.begin(),pts.end());
  int base=-1;
  for(int i=0;i<N;i++){
    if(pts[i].F==point(C) && pts[i].S==W[0]){
      base=i;
    }
  }
  assert(base!=-1);
  for(int i=0;i<N;i++){
    assert(pts[(i+base+dif)%N].F>=0 && pts[(i+base+dif)%N].F<L);
    cout<<pts[(i+base+dif)%N].F<<endl;
  }


  return 0;
}

