    if(cur.second==1){
      if(a[r].second!=2){
        r++;
        continue;
      }
      cur=a[r];
      r++;
    }
    else{
      if(a[l].second!=1){
        l--;
        continue;
      }
      cur=a[l];
      l--;
    }
