typedef lib::modnum<1000000007> mod_t;

typedef lib::dmod<lib::int_tag<0>> N_t;
typedef lib::dmod<lib::int_tag<1>> L_t;
typedef lib::dmod<lib::int_tag<2>> L2_t;
N_t count(L_t x, L_t y, L_t T)
{
	auto d = T.val - (y.val - x.val) / 2.0;
	return d < 0 ? 0 : 2 * d >= x.mod ? 2 : 1;
}
N_t rcount(L_t x, L_t y, L_t T)
{
	return count(x, L_t(2)*x - y, T);
}

void Main()
{
	std::int64_t N, L, T, X, W;
	std::cin >> N >> L >> T >> X >> W;
	L_t::mod = L;
	N_t::mod = N;
	L2_t::mod = 2 * L;
	std::vector<std::int64_t> result;
	if (W == 1)
	{
		result.emplace_back((L_t(X) + L_t(T)).val);
	}
	else
	{
		result.emplace_back((L_t(X) - L_t(T)).val);
	}
	auto start = result.front();
	N_t h{};
	for (int i = 1; i < N; ++i)
	{
		L_t x;
		int w;
		std::cin >> x.val >> w;
		if (w == 1)
		{
			result.emplace_back((L_t(x) + L_t(T)).val);
			if (W == 2)
			{
				h -= rcount(X, x, T) + N_t(2 * (T / L));
			}
		}
		else
		{
			result.emplace_back((L_t(x) - L_t(T)).val);
			if (W == 1)
			{
				h += count(X, x, T) + N_t(2 * (T / L));
