typedef long long ll;

const int MAX_N = 100000 + 10;
int X[MAX_N];
int W[MAX_N];
int ans[MAX_N];
int pos[MAX_N];

int main2() {
  int N, L, T;
  scanf("%d%d%d", &N, &L, &T);
  REP(i, N) scanf("%d%d", &X[i], &W[i]);

  ll q = 0;
  for (int i = 1; i < N; i++) {
    if (W[0] == 1) {
      if (W[i] == 2) {
        int p = (X[i] - X[0]);
        if (p <= 2 * T) {
          q++;
          q += (2 * T - p) / L;
        }
      }
    } else {
      if (W[i] == 1) {
        int p = (L - X[i] + X[0]);
        if (p <= 2 * T) {
          q--;
          q -= (2 * T - p) / L;
        }
      }
    }
  }
  q = ((q % N) + N) % N;

  REP(i, N) {
    int x = 0;
    if (W[i] == 1) {
      x = (X[i] + T) % L;
    } else {
      x = ((X[i] - T) % L + L) % L;
    }
    pos[i] = x;
  }
  int pos0 = pos[0];
  sort(pos, pos + N);
  int s = 0;
