int part[100 * 1000 + 5][4];

int main() {
    //ifstream cin("C.in");
    int n, l, t; cin >> n >> l >> t;

    vector<int> x(n, 0), dir(n, 0);

    for(int i = 0; i < n; ++i) {
        cin >> x[i] >> dir[i];
        for(int j = 1; j <= 2; ++j) {
            if(i >= 1)
                part[i][j] += part[i - 1][j];
            if(dir[i] == j)
                part[i][j]++;
        }
    }

    vector<int> ans(n, 0);

    for(int i = 0; i < n; ++i) {
        int poz = x[i], who = -1;
        int poz2 = x[i];

        if(dir[i] == 1) {
            poz = (poz + t) % l;
            poz2 = (1LL * poz2 + 2 * t) % l;
        } else {
            poz = (poz - t) % l;
            while(poz < 0)
                poz += l;
            poz2 = (poz - 2 * t) % l;
            while(poz2 < 0)
                poz2 += l;
        }

        if(dir[i] == 1) {
            int sum = 0;
            auto it = upper_bound(x.begin(), x.end(), min(1LL * x[i] + 2 * t, 1LL * l)) - x.begin();
            --it;
            if(it >= 0 and it >= i)
                sum += part[it][2] - part[i][2];

            if(1LL * x[i] + 2 * t >= l) {
                it = upper_bound(x.begin(), x.end(), poz2) - x.begin();
                --it;
                if(it >= 0)
                    sum += part[it][2];
            }

            sum += ((2 * t) / l) * part[n - 1][2];
            who = (i + sum) % n;

            ans[who] = poz;
        } else {
            int sum = 0;
            auto it = lower_bound(x.begin(), x.end(), x[i] - 2 * t) - x.begin();

            if(it >= 1) {
                sum += part[i][1] - part[it - 1][1];
            } else {
                sum += part[i][1];
            }

            if(x[i] - 2 * t < 0) {
                it = lower_bound(x.begin(), x.end(), poz2) - x.begin();
                sum += part[n - 1][1];
                if(it >= 1)
                    sum -= part[it - 1][1];
            }

            sum += ((2 * t) / l) * part[n - 1][1];

            who = (i - sum) % n;
            while(who < 0)
                who += n;

            ans[who] = poz;
        }
    }

    for(int i = 0; i < n; ++i)
        cout << ans[i] << "\n";
}

