    if(W[0] == 2) {
        rep(i, N) {
            W[i] = W[i] == 1 ? 2 : 1;
            X[i] = L - X[i];
        }
    }
    ll roll = T / L, left = T % L, sum = 0;
    // 衝突回数計算
    repeat(i, 1, N) {
        if(W[i] != W[0]) {
