ll modn(ll x, ll n){
    ll r = x%n;
    while(r<0) r+=n;
    return r;
}

int main(){
    cin.tie(nullptr);
    ios::sync_with_stdio(false);
    cout.precision(12);
    cout.setf(ios_base::fixed, ios_base::floatfield);

    ll n, l, t;
    cin >> n >> l >> t;
    ll x[100000], w[100000];
    for(int i=0;i<n;i++) cin >> x[i] >> w[i];

    ll idx = 0;
    for(int i=1;i<n;i++){
        if(w[0] == w[i]) continue;
        int d;
        if(w[0] == 1) d = (l+x[i]-x[0]) % l;
        else d = (l+x[0]-x[i]) % l;
        if(t < d) continue;
        if(w[0] == 1) idx += (t-d)/l+1;
        else idx -= (t-d)/l+1;
        idx = modn(idx, n);
    }

    vector<ll> ants;
    for(int i=0;i<n;i++){
        if(w[i] == 1) ants.push_back(modn(x[i]+t, l));
        else ants.push_back(modn(x[i]-t, l));
    }
    sort(ants.begin(), ants.end());

    int cnt = 0;
    bool f = false;
    map<ll,ll> ans;
    for(int i=0;i<n;i++){
        if(f){
            ans[idx] = ants[i];
            cnt++;
            idx = modn(idx+1, n);
        }else if(ants[i]==modn(x[0]+t, l)){
            if(w[0]==1 || ants[(i+1)%n] != ants[i]){
                ans[idx] = ants[i];
                cnt++;
                idx = modn(idx+1, n);
                f = true;
            }
        }
    }
    for(int i=0;cnt<n;i++){
        ans[idx] = ants[i];
        cnt++;
        idx = modn(idx+1, n);
    }

    for(int i=0;i<n;i++) cout << ans[i] << endl;

    return 0;
}

