int main() {
	ll N,L,T,S = 0; cin >> N >> L >> T;
	V<ll> X(N), Y(N), W(N);
	for (int i = 0; i < N; ++i) cin >> X[i] >> W[i];
	for (int i = 0; i < N; ++i) Y[i] = X[i];
	for (int i = 0; i < N; ++i) if (W[i] == 1) (Y[i] += T%L) %= L;
	for (int i = 0; i < N; ++i) if (W[i] == 2) (Y[i] += L - T%L) %= L;
	for (int i = 0; i < N; ++i) X[i] -= X[0];
	for (int i = 0; i < N; ++i) if (W[i] != W[0]) (S += 2 * (T / L) % N) %= N;
	for (int i = 0; i < N; ++i) if (W[i] == 2) X[i] = L - X[i];
	for (int i = 0; i < N; ++i) if (W[i] != W[0]) {
		double h = X[i],t = T%L, l = L;
		if (t >= h/2.) S++;
		if (t - h/2. > l / 2) S++;
	}
	S %= N;
	if (W[0] == 1) for (int i = 0; i < N; ++i) cout << Y[(i + N - S) % N] << endl;
	else for (int i = 0; i < N; ++i) cout << Y[(i + S) % N] << endl;
	return 0;
}

