int main(){
	ll n, l, t;
	cin>>n>>l>>t;
	rep(i, n){
		cin>>x[i]>>w[i];
		w[i] = w[i]==1?1:-1;
		y[i] = (x[i]+w[i]*t)%l;
		if(y[i]<0) y[i] += l;
	}
	ll sw = 0, w0 = w[0];
	if(w[0]<0){
		rep(i, n) w[i] *= -1;
		rep(i, n) x[i] *= -1;
	}
	bool just = false;
	rep(i, n){
		if(w[i]>0) continue;
		ll a = x[0]-x[i], b = x[0]-x[i]+2*t;
		cerr<<i<<" "<<a<<" "<<b<<endl;
		if(a<0) sw++;
		sw += b/l;
		if(b%l==0) just = true;
	}
	ll left = 0;
	if(w0<0){
		rep(i, n) w[i] *= -1;
		rep(i, n) x[i] *= -1;
		sw *= -1;
		sw %= n;
		if(sw<0) sw += n;
		left = !left;
	}
	sort(y, y+n);
	int p = -1;
	for(int i = 0; i < n; i++){
		if((x[0]+t*w[0]-y[i])%l==0){
			p = i;
			if(just && !left) p++;
			break;
		}
	}
	//cerr<<just<<" "<<left<<endl;
	//cerr<<sw<<" "<<p<<endl;
	rep(i, n) r[(i+sw)%n] = y[(p+i)%n];
	rep(i, n) cout<<r[i]<<endl;
	return 0;
}

#include<bits/stdc++.h>
using namespace std;

int main(){
  int N, L, T;
  cin >> N >> L >> T;
  vector<int> x(N+1);
  vector<int> w(N+1);
  for(int i = 0; i < N; i++){
    cin >> x[i] >> w[i];
  }
  x[N] = x[0]; 
  w[N] = w[0];

  for(int t = 1; t <= T; t++){
    for(int i = 0; i < N; i++){
      if((x[i] == x[i+1]-1 || x[i] == x[i+1]+L-1) && w[i] == 1 && w[i+1] == 2){//差が１、向かい合うとき
        swap(w[i], w[i+1]);
        i = i + 1;
      }
      else if((x[i] == x[i+1]) && w[i] == 1 && w[i+1] == 2){//差が０、向かい合うとき
        x[i] = (x[i]-1)%L;
        x[i+1] =  (x[i]+1)%L;
        swap(w[i], w[i+1]);
        i = i + 1;
      }
      else{    
        if(w[i] == 1){
           x[i] = (x[i]+1) % L;
        }
        else{
           x[i] = (x[i]-1) % L;
        }
      }
    }
  }

  for(int i = 0; i < N; i++){//出力
    cout << x[i] << endl;
  }
}

