無 入力關數()
{
    入(匹) >> 長 >> 時;
    再(數, 0, 匹 - 1)
    {
        入(所[數]) >> 向[數];
    }
}

無 圓蟻()
{
    整 衝 代 0;
    再(數, 1, 匹 - 1)
    {
        如(向[0] 是 向[數])
        {
            次;
        }
        整 距;
        如(向[0] 是 1)
        {
            距 代 所[數] - 所[0];
        }
        他
        {
            距 代 所[0] + 長 - 所[數];
        }

        如(距 > 時 * 2)
        {
            次;
        }
        衝 代 衝 + 1 + (時 * 2 - 距) / 長;
    }

    衝 代 衝 % 匹;

    再(數, 0, 匹 - 1)
    {
        如(向[數] 是 1)
        {
            所[數] 代 所[數] + 時 % 長;
        }
        他
        {
            所[數] 代 所[數] + 長;
            所[數] 代 所[數] - 時 % 長;
        }
        所[數] 代 所[數] % 長;
    }

    如(匹 是 1)
    {
        出(所[0]) << 空行;
        返;
    }

    整 號;
    如(向[0] 是 1)
    {
        號 代 衝;
    }
    他
    {
        號 代 匹 - 衝;
    }

    整 基 代 所[0];
    逆理(始(所), 始(所) + 匹 - 1);
    整 初 代 0;
    再(數, 0, 匹 - 1)
    {
        如(所[數] 是 基)
        {
            初 代 數;
            如(向[0] 是 1 且 所[(數 + 1) % 長] 是 基)
            {
                初 代 初 + 1;
            }
            斷;
        }
    }

    再(數, 0, 匹 - 1)
    {
        出(所[(匹 + 初 - 號) % 匹]) << 空行;
        初 代 初 + 1;
        初 代 初 % 長;
    }

    返;
}

整數 心()
{
    入力關數();
    圓蟻();
    返 0;
}

