int main() {
	ios::sync_with_stdio(false);
	cin.tie(0);

	cin >> N >> M >> K;
	vector<long long int>place(N);
	vector<long long int>dir(N);
	vector<long long int>ans(N);
	long long int dif = 0;
	for (int i = 0; i < N; i++) {
		cin >> place[i] >> dir[i];
		place[i] += MOD*M;
		if (dir[i] == 1) {
			dif += (place[i] + K) / M - place[i] / M;
			ans[i] = place[i] + K;
			ans[i] %= M;
		}
		else {
			dif += (place[i] - K) / M - place[i] / M;
			ans[i] = place[i] - K;
			ans[i] %= M;
		}
	}
	sort(ans.begin(), ans.end());
	for (int i = 0; i < N; i++) {
		cout << ans[(i + dif) % N] << endl;
	}
	return 0;
}

