/*座標0を軸としてアリの順番が何匹ずれたかだけを記憶し、順番は考慮せずにアリが存在する位置を計算。
位置をソートしたのち、アリがずれた分だけ配列をずらして出力。*/
int main(void){
    int N, L, T, x, w, gap;
    cin >> N >> L >> T;
    vector<int> X;
    rep(i,N){
        cin >> x >> w;
        x += ((w+1) % 3 - 1) * T;
        if(x >= L)gap++;
        else if(x < 0)gap--;
        X.emplace_back((x+L) % L);
    }
    sort(X.begin(), X.end()); 
    rep(i,N)cout << X[(gap + i + N) % N] << endl;
