void Main()
{
    LL n,l,t;cin>>n>>l>>t;
    LL w;
    VVL a(n);
    REP(i,n){
        a[i].resize(3); // p, i, w;
        a[i][1] = i;
        cin>>a[i][0]>>a[i][2];
    }
    w = a[0][2];

    LL col = 0;
    FOR(i,1,n){
        if(w == a[i][2]){
            continue;
        }
        LL diff;
        if(w == 1){
            diff = a[i][0] - a[0][0];
        }
        else{
            diff = a[0][0] + l-a[i][0];
        }
        col += (t*2)/l;
        if(diff <= (t*2)%l){
            col++;
        }
        col%=n;
    }


    REP(i,n){
        if(a[i][2] == 1){
            a[i][0] += t;
        }
        else{
            a[i][0] -= t;
        }
        a[i][0] = ((a[i][0]%l)+l)%l;
    }

    SORT_ASC(a);

    LL point = 0;
    REP(i,n){
        if(a[i][1] == 0){
            if(w==1 && i!=n-1 && a[i][0] == a[i+1][0]){
                point = (i+1)%n;
            }
            else{
                point = i;
            }
            break;
        }
    }
    if(w == 1){
        point -= col;
    }
    else{
        point += col;
    }
    point = (point+n)%n;

    REP(i,n){
        cout<<a[(i+point)%n][0]<<endl;
    }





	return;
}

