    if(W[0] == 2) {
        rep(i, N) {
            W[i] = W[i] == 1 ? 2 : 1;
            X[i] = L - X[i];
        }
    }
    ll roll = T / L, left = T % L, sum = 0;
    // 衝突回数計算
    repeat(i, 1, N) {
        if(W[i] != W[0]) {
            sum += roll * 2;
            ll d = (X[i] - X[0] + L) % L;            
            if(left * 2 > d) sum += 1;
            if(left * 2 - d > L) sum += 1;
        }
        sum %= N;
    }
    // 蟻本方式に動いて移動先計算
    rep(i, N) {
        X[i] += (W[i] == 1 ? left : -left) + L;
        X[i] %= L;        
    }
