int main(){
	scanf("%d%d%d", &n, &l, &T);
	f(i, 0, n)scanf("%d%d", &a[i].first, &a[i].second);
	f(i, 0, n)if (a[i].second == 1)an[i] = (a[i].first + T) % l;
	else an[i] = (a[i].first - T % l + l) % l;
	sort(an, an + n);
	int z = T / l;
	int of = 0;
	f(i, 0, n)if (a[i].second == 1)++of; else --of;
	if (abs(of) == n)T = 0;
	if (of < 0)of += n;
	of = (ll)of * z % n;
	T %= l;
	int j = of, lc = a[of].first, dn = 0, zz = 0;
	while (T){
		if (a[of].second == 1) { ++j; if (j == n)j = 0; }
		else { --j; if (j == -1)j = n - 1; }
		if (a[of].second & a[j].second)continue;
		int nlc;
		if (a[of].second == 1) { nlc = a[j].first - dn; if (nlc < 0)nlc += l; }
		else { nlc = a[j].first + dn; if (nlc >= l)nlc -= l; }
		int cost;
		if (a[of].second == 1)cost = nlc - lc;
		else cost = lc - nlc;
		if (cost < 0)cost += l;
		else if (cost == 0)cost = l;
		int cost2 = cost + 1 >> 1;
		if (T < cost2)cost2 = T, --zz;
		T -= cost2;
		dn += cost2;
		++zz;
		if (a[of].second == 1) { lc += cost2; if (lc >= l)lc -= l; }
		else { lc -= cost2; if (lc < 0)lc += l; }
	}
	int i = 0;
	while (an[i] != lc)++i;
	if (a[of].second == 1) { if ((i -= zz) < 0)i += n; }
	else if ((i += zz) >= n)i -= n;
	f(j, 0, n){
		printf("%d\n", an[i]);
		if (++i == n)i = 0;
	}
}

