vector<int>pos_set;

int cnt(int a, int b) {
	for (; a < 0; a += l);
	for (; b >= l; b -= l);
	assert(a < b);
	if (b - a > 2 * t)return 0;
	return 1 + (2 * t - b + a) / (2 * l);
}

