        cur = pls(cur, mul((W[i] == 1 ? n - 1 : 1), tms, n), n);    
    }

    rep (i, 1, n) X[i] = pls(X[i], mul((W[i] == 1 ? 1 : L - 1), T, L), L);
    sort(X+1, X+n+1);

    rep (i, n - cur + 1, n) printf("%d\n", X[i]);
    rep (i, 1, n - cur) printf("%d\n", X[i]);

    return 0;
}

