using namespace std;


typedef long long ll;
typedef unsigned int ui;


#define N_MAX 100000

class ant_t
{
	public:
	int id, x, w;
	ant_t(int id, int x, int w):id(id),x(x),w(w){};
};


vector<ant_t> ant_cw, ant_ccw;


int laparound(ll x, int l)
{
	x%=l;
	if(x<0) x+=l;
	return x;
}


void solve(int n, int l, int t)
{
	ll loop;
	int i, j, d, cw_num, ccw_num, s, e, c;
	vector<int> work;

	loop=2*t/l;
	d=2*t-loop*l;
	cw_num=ant_cw.size();
	ccw_num=ant_ccw.size();

	work.clear();
	work.resize(ccw_num*2);
	work.push_back(2000000007);
	for(i=0;i<ccw_num;i++)
	{
		ant_t& ant=ant_ccw[ccw_num-1-i];

		work[i]=ant.x;
		work[i+ccw_num]=ant.x+l;
	}

	s=e=0;
	for(i=0;i<cw_num;i++)
	{
		ant_t& ant=ant_cw[i];
/*
		c=0;
		for(j=0;j<ccw_num*2;j++)
		{
			if(ant.x<work[j] && work[j]<ant.x+d) c++;
		}
*/
		for(;s<ccw_num*2;s++)
		{
			if(work[s]>ant.x) break;
		}
		for(;e<ccw_num*2;e++)
		{
			if(work[e]>ant.x+d) break;
		}
		c=e-s;

		ant.id=laparound(ant.id+c, n);
//		printf("cw : %d\n", c);
	}

	work.clear();
	work.resize(cw_num*2);
	work.push_back(-2000000007);
	for(i=0;i<cw_num;i++)
	{
		ant_t& ant=ant_cw[cw_num-1-i];

		work[i]=ant.x;
		work[i+cw_num]=ant.x-l;
	}

	s=e=0;
	for(i=0;i<ccw_num;i++)
	{
		ant_t& ant=ant_ccw[ccw_num-1-i];
/*
		c=0;
		for(j=0;j<cw_num*2;j++)
		{
			if(ant.x-d<work[j] && work[j]<ant.x) c++;
		}
*/
		for(;s<cw_num*2;s++)
		{
			if(work[s]<ant.x) break;
		}
		for(;e<cw_num*2;e++)
		{
			if(work[e]<ant.x-d) break;
		}
		c=e-s;

		ant.id=laparound(ant.id-c, n);
//		printf("ccw : %d\n", c);
	}

	for(auto ant: ant_cw)
	{
		ant.id=laparound(ant.id+loop*ccw_num, n);
	}
	for(auto ant: ant_ccw)
	{
		ant.id=laparound(ant.id-loop*cw_num, n);
	}
}


int main(void)
{
	int l, t;
	ui i, n;
	int x, w;
	vector<int> result;

	while(scanf("%d%d%d", &n, &l, &t)==3)
	{
		result.clear();
		ant_cw.clear();
		ant_ccw.clear();
		result.resize(n);
		ant_cw.reserve(n);
		ant_ccw.reserve(n);

		for(i=0;i<n;i++)
		{
			scanf("%d%d", &x, &w);
			if(w==1) ant_cw.push_back(ant_t(i,x,w));
			else ant_ccw.push_back(ant_t(i,x,w));
		}

		solve(n, l, t);

		for(auto ant: ant_cw)
		{
			ant.x=laparound(ant.x+t, l);
			result[ant.id]=ant.x;
		}
		for(auto ant: ant_ccw)
		{
			ant.x=laparound(ant.x-t, l);
			result[ant.id]=ant.x;
		}

		for(auto x: result)
		{
			printf("%d\n", x);
		}
	}

	return 0;
}

