ll collision_count(int a, int b)
{
    if (W[a] == 1 && W[b] == 2) {
        ll diff = (X[b] - X[a]);
        if (diff <= 2*T) {
            return 1 + (2*T - diff) / L;
        }
    } else if (W[a] == 2 && W[b] == 1) {
        ll diff = L - (X[b] - X[a]);
        if (diff <= 2*T) {
            return 1 + (2*T - diff) / L;
        }
    }

    return 0;
}

int main()
{
