				if (x[i] + L - 2 * T <= pos - L) ++d;
			}
			if (x[i] > pos) {
				if (x[i] - 2 * T <= pos) ++d;
				if (x[i] - 2 * T <= pos - L) ++d;
			}
		}
	}

	int tmp = y[index];
	sort(y + 1, y + n + 1);
	iter(i, n) {
		if (y[i] == tmp && y[N(i + 1)] != tmp) {
			iter(j, n) {
				ans[N((j-1) + index + d)] = y[N(i)];
				++i;
			}
			iter(j, n) printf("%d\n", ans[j]);
			break;
		}
	}
	return 0;
}

