ll norm(ll x){ return (x%L+L) % L; }
ll dist(ll x, ll y){
	if( x == y ) return L;
	return norm(y-x) % L;
}

int go(ll t){
	int ch = 0;
	for(int i = 0; i < N; i++){
		if( W[0] != W[i] ) ch = 1;
	}
	if( ch == 0 ) return (X[0] + t) % L;

	queue<ll> Q[3];
	ll cur = X[0], dir = W[0], tm = 0;
	for(int i = 1; i <= N-1; i++){
		if( W[i] == 2 ) Q[2].push(X[i]);
	}
	for(int i = N-1; i >= 1; i--){
		if( W[i] == 1 ) Q[1].push(X[i]);
	}
	while(t > tm){
		if( dir == 1 ){
			ll p = Q[2].front(); Q[2].pop();
			ll c = norm(p - tm), dt = dist(cur, c) / 2;
			tm += dt;
			p = norm(p - dt);
			cur = norm(cur + dt);

			Q[1].push(p - tm);
		}
		else{
			ll p = Q[1].front(); Q[1].pop();
			ll c = norm(p + tm), dt = dist(c, cur) / 2;
			tm += dt;
			p = norm(p + dt);
			cur = norm(cur - dt);

			Q[2].push(p + tm);
		}
		dir = 3-dir;
	}
	if( dir == 2 ) cur = norm(cur-tm+t);
	if( dir == 1 ) cur = norm(cur+tm-t);
	return cur;
}

