using namespace std;

struct AntPos {
	int64_t pos;
	int     dir;
};

// -1 : ない。(全部の蟻が同方向)
int seek_next(const vector<AntPos>& ants, int idx, int dir)
{
	int col_dir = (3 - dir);
	int add     = (dir == 1) ? 1 : -1;

	int next_idx = idx;
	int count    = 0;
	do {
		next_idx += add;
		if (next_idx     < 0)        next_idx += ants.size();
		if (ants.size() <= next_idx) next_idx -= ants.size();

		if (ants[next_idx].dir == col_dir) return next_idx;

		count++;
		if (count == ants.size()) return -1;
	} while(true);
}

int64_t add_pos(int64_t pos, int dir, int64_t val, int64_t l)
{
	int64_t next_pos = pos + ((dir == 1) ? val : -val);
	next_pos %= l;
	if (next_pos < 0) next_pos += l;

	return next_pos;
}

int main()
{
	// すべて 2 倍にしても正確性は失われない
	int64_t n, l, t; cin >> n >> l >> t;
	l *= 2;
	t *= 2;

	vector<AntPos> ants(n);
	for (auto & ant : ants) {
		cin >> ant.pos; ant.pos *= 2;
		cin >> ant.dir;
	}

	// まずは蟻の位置を気にせずに特定
	multiset<int64_t> reach_poss;
	FOR(i, ants.size()) {
		const auto& ant = ants[i];
		reach_poss.insert(add_pos(ant.pos, ant.dir, t, l));
	}

	// 蟻 0 のみ真面目に到達位置を計算する
	int64_t pos   = ants[0].pos;
	int     dir   = ants[0].dir;
	int     r_idx = 0;
	int     l_idx = 0;
	int64_t t_now = 0;

	while (true) {
		int idx      = (dir == 1) ? r_idx : l_idx;
		int next_idx = seek_next(ants, idx, dir);
		if (next_idx == -1) {
			pos = add_pos(pos, dir, t - t_now, l);
			break;
		}

		int64_t diff = -1;

		if (next_idx != idx) {
			diff = ants[next_idx].pos - ants[idx].pos;
			if (dir == 2) diff = - diff;
			if (diff < 0) diff += l;
		}
		else {
			diff = l;
		}

		if (t - t_now <= diff / 2) {
			pos   = add_pos(pos, dir, t - t_now, l);
			t_now = t;
			break;
		}

		pos    = add_pos(pos, dir, diff/2, l);
		dir    = (3 - dir);
		t_now += diff / 2;
	}

	// 蟻の位置関係は保存されているので蟻 0 の位置から出力する
	// ただし同じ位置に 2 個のアリがある場合に注意
	auto   it = reach_poss.lower_bound(pos);
	auto next = it;
	next++;
	if (next != reach_poss.end() && *(next) == *(it)) {
		// 右向きなら最初のアリ、左向きなら次のアリ
		if (dir == 2) it++;
	}

	for (int64_t i = 0; i < n; i++) {
		cout << (*it / 2) << endl;
		it++;
		if (it == reach_poss.end()) it = reach_poss.begin();
	}


	return 0;
}

