int n, m, lim;

void solve() {                   
	scanf("%d %d %d", &n, &m, &lim);
	lim <<= 1;
	m <<= 1;

    for (int i = 0; i < n; ++i) {
    	scanf("%d %d", &arr[i].fi, &arr[i].se);

    	if (arr[i].se == 2) {
    		arr[i].se = -1;
    	}

    	arr[i].fi <<= 1;
    }

    int curT = 0;

    while (1) {
    	int mx = -1;

    	for (int i = 0; i < n; ++i) {
    		coll[i] = 0;
    	}

    	for (int i = 0; i < n; ++i) {
    		int p = (i - 1 + n) % n;

    		if (arr[i].se == -1 && arr[p].se == 1) {
				int t = arr[i].fi - arr[p].fi;

				if (t < 0) {
					t += m;
				}

				if (t >= m) {
					t -= m;
				}

				t >>= 1;

				if (t <= lim - curT) {
					coll[i] = coll[p] = t;
					mx = max(mx, t);
				}
    		}
    	}

    	if (mx == -1) {
    		break;
    	}

		for (int i = 0; i < n; ++i) {
			if (coll[i] != 0) {						
				arr[i].fi += arr[i].se * coll[i];
				arr[i].fi = (arr[i].fi % m + m) % m;
				arr[i].se *= -1;
			}

			arr[i].fi += arr[i].se * (mx - coll[i]);
			arr[i].fi = (arr[i].fi % m + m) % m;
		} 

    	curT += mx;
    }

    for (int i = 0; i < n; ++i) {		
		arr[i].fi += arr[i].se * (lim - curT);
		arr[i].fi = (arr[i].fi % m + m) % m;
	}

	for (int i = 0; i < n; ++i) {
		printf("%d\n", arr[i].fi / 2);
	}
}

