using int64 = long long;

int main() {
    int64 N, L, T;
    cin >> N >> L >> T;

    vector<int64> X(N);
    vector<pair<int64, int>> Y(N);
    vector<int> W(N);
    for (int i = 0; i < N; i++) {
        cin >> X[i] >> W[i];
        // T秒後の位置
        // W[i]:=1 (if 時計回り)
        // W[i]:=2 (if 反時計回り)
        int dir = (W[i] == 1) ? 1 : (-1);
        Y[i] = make_pair(((X[i] + dir * T) % L + L) % L, W[i]);
    }
    int id = -1;
    for (int i = 0; i < N; i++) {
        if (W[i] == 1) id = i;
    }

    if (id == -1) {
        for (int i = 0; i < N; i++) {
            cout << Y[i].first << endl;
        }
        return 0;
    }
    // idの持っているゼッケン
    int diff = 0;
    for (int i = 0; i < N; i++) {
        if (i == id or W[i] == 1) continue;
        int64 p = X[i] + (X[id] > X[i] ? L : 0); 

        diff += 2 * T / L + (X[id] + 2 * T % L > p);
        diff %= N;
    }
    cerr << "id: " << id << endl;
    cerr << "diff: " << diff << endl;
    int nid = (id + diff) % N;

    vector<int> ans(N);
    int pos = Y[id].first,
        start = -1;
    sort(Y.begin(), Y.end());
    // Y[id].firstの位置に
    for (int i = 0; i < N; i++) {
        if (Y[i].first == pos and Y[i].second == 1) {
            start = i;
            break;
        }
    }
    for (int i = 0; i < N; i++) {
        ans[(nid + i) % N] = Y[(start + i) % N].first;
    }

    for (int i = 0; i < N; i++) {
        cout << ans[i] << endl;
    }

    return 0;
}

