    num += (2*t-fst)/l;
  }
  ll after = ((dat[0][1]==1?num:N-num))%n;
  vll ans(n);
  for(int i=0;i<n;i++){
    ans[after] = af[i];
    after = (after+1)%n;
  }
  for(int i=0;i<n;i++) std::cout << ans[i] << "\n";
  return 0;
}

