	{
		if (w[i] == 1)
			z[i] = (v[i] + T)%L;
		else
		{
			LL INF = 1e9;
			z[i] = ((v[i] - T) + INF * L) % L;
		}
	}
	int coll = 0;
	REP(i,N)
	{
		if (w[i] != w[0])
		{
			int dist = 0;
			if (w[0] == 1)
				dist = v[i] - v[0];
			else
				dist = v[0] - v[i] + L;
			int k = dist < 2*T ? max((2 * T - dist ) / L,1) : 0;
			coll += k;
		}
	}
	coll %= N;
	int ant0 = z[0];
	int k = -1;
	FOR(i, 1, N) if (z[i] == ant0)
	{
		k = i;
	}
	int coll2 = k;
	if (k != -1)
	{
		REP(i, N)
		{
			if (w[i] != w[k])
			{
