					if (w[k] == 1 && w[i] != w[k])
					{
						dist = v[k] - v[i];
					}
					else if (w[k] == 2 && w[i] != w[k])
					{
						dist = L - v[k] + v[i];
					}
				}

				int o = dist < 2 * T ? max((2 * T - dist) / L, 1) : 0;
				coll2 += o;
			}
		}
		coll2 %= N;
	}

