int main() {
    int N;
    long long L, T;
    cin >> N >> L >> T;
    long long X[N];
    int W[N];
    for (int i = 0; i < N; ++i) cin >> X[i] >> W[i];

    int counter = 0;
    for (int i = 1; i < N; ++i) {
        if (W[0] == 1 && W[i] == 2) {
            counter += (2 * T - (X[i] - X[0]) + 2 * L - 1) / (2 * L);
        }
        else if (W[0] == 2 && W[i] == 1) {
            counter += (2 * T - (L - (X[i] - X[0])) + 2 * L - 1) / (2 * L);
        }
    }
    for (int i = 0; i < N; ++i) {
        if (W[i] == 1) {
            X[i] += T;
            while (X[i] >= L) X[i] -= L;
        }
        else {
            X[i] -= T;
            while (X[i] < 0) X[i] += L;
        }
    }
    int x = X[0];
    sort(X, X + N);
    int d;
    for (int i = 0; i < N; ++i) {
        if (X[i] == x) d = i - counter;
    }
    int ans[N];
    for (int i = 0; i < N; ++i) {
        ans[i] = X[(i + d) % N];
    }

    for (int i = 0; i < N; ++i) cout << ans[i] << endl;

    return 0;
}

