template<class T>
T next(istream& in) {
    T ret;
    in >> ret;
    return ret;
}


int n;
int len;
int T;
vector<int> pos;
vector<int> dir;

int canMeet(int p1, int d1, int p2, int t) {
    if (p1 != 0) {
        p2 -= p1;
        if (p2 < 0) {
            p2 += len;
        }
    }

    if (d1 < 0) {
        p2 = len - p2;
    }

    // d1 > 0, d2 < 0
    int res = 0;
    if (p2 <= 2 * t) {
        ++res;
    } else {
        return 0;
    }
    if (len <= 2 * t - p2) {
        ++res;
    }
    return res;
}

void solve(istream& in, ostream& out) {
    n = next<int>(in);
    len = next<int>(in);
    T = next<int>(in);
    pos.clear();
    dir.clear();
    pos.resize(n);
    dir.resize(n);
    vector<int> new_pos(n);
    int t1 = T;
    T %= len;
    FOR(i, n) {
        pos[i] = next<int>(in);
        dir[i] = next<int>(in);
        if (dir[i] == 2) dir[i] = -1;

        new_pos[i] = pos[i] + dir[i] * T;
        if (new_pos[i] < 0) {
            new_pos[i] += len;
        }
        if (new_pos[i] >= len) {
            new_pos[i] -= len;
        }
    }

    int id1;
    int times = 0;
    T = t1;
    FOR(i, n) {
        if (i && dir[i] != dir[0]) {
            times += 2 * (T / len);
            times += canMeet(pos[0], dir[0], pos[i], T % len);
        }
    }

    id1 = times % n;
    if (dir[0] < 0) {
        id1 = n - id1;
    }
    vector<int> r(n);
    for (int i = id1, j = 0; j < n; ++j, i = (i + 1) % n) {
        r[i] = new_pos[j];
    }
    for (int x : r) {
        out << x << endl;
    }
}


