int cal() // Numbers of collisions between ant 0 and the others.
{
	int cnt = 0;
	for (int i = 1; i < n; i++)
		if (w[i] != w[0])
		{
			int d = 0;
			if (w[0] == 1 && w[i] == 2)
			{
				if (x[0] < x[i]) d = x[i] - x[0];
				else d = l - x[0] + x[i]; 	
			}
			else 
			{
				if (x[0] > x[i]) d = x[0] - x[i];
				else d = l - x[i] + x[0];
			}
			if (2 * t >= d)
				cnt += (1 + (t * 2 - d)/l);
		}
	return cnt;	
}

