typedef long long ll;

void solve(long long N, long long L, long long T, std::vector<long long> X, std::vector<long long> W){
    ll count = 0;    
    for (int i=1;i<N;i++){
        ll init_pos;
        if (W[0] ==1 &&  W[i] == 2){
            init_pos = X[i]-X[0];
            if (2*T >= init_pos){
                count += 1 + (2*T - init_pos)/L;
            }
        }else if (W[0] ==2 &&  W[i] == 1){
            init_pos = L - (X[i]-X[0]);
            if (2*T >= init_pos){
                count += 1 + (2*T - init_pos)/L;
            }
        }else{
                // pass
        } 
    }
    int number = (W[0]==1)? count%N : (N +(-count %N))%N;
    vector<ll> final_pos(N,0);
    for (int i=0;i<N;i++){
        ll increment = (W[i]==1)? T%L:-T%L + L;
        final_pos[i] = (X[i] + increment) %L;
    }
    ll pos_number = final_pos[0];
    sort(final_pos.begin(),final_pos.end());
    int p = lower_bound(final_pos.begin(),final_pos.end(),pos_number) -final_pos.begin();
    //　インデックス p がnumberと対応している
    for (int i=0;i<N;i++){
        printf("%lld\n",final_pos[(N+p-number+i)%N]);
    }

}

