        if(a[i].d == 1) cnt++;
        a[i].ed = a[i].x + T*(a[i].d == 1 ? 1LL : -1LL);
        a[i].ed = (a[i].ed%L + L)%L;
    }
    long long cross = 0;
    if(a[0].d == 1) {
        cross += T/L*(n-cnt);
        for(int i = 0; i < n; i++) {
            a[i].tmp = a[i].x + (a[i].d == 1 ? 1LL : -1LL) * (T%L);
        }
        for(int i = 1; i < n; i++) {
            if(a[i].d == 2 && a[i].tmp <= a[0].tmp) cross++;
        }
    }else {
        cross += T/L*cnt;
        for(int i = 0; i < n; i++) {
            a[i].tmp = a[i].x + (a[i].d == 1 ? 1 : -1) * (T%L);
