int getPos(int p, int T){
	int x, w; tie(x, w) = e[p];
	return (x + (w == 0 ? T : L - T % L)) % L;
}

int forward(int p, int T, int off = 0){
	int c = 0;
	while(1){
		int dir = e[p].second;
		if(d[!dir].empty()) return p;
		int x = getPos(p, off * 2);
//		cerr << p << ", " << T << ", " << off << ", " << x << endl;
		int nxtp, len;
		if(dir){ // ccw
			nxtp = (lower_bound(ALL(d[!dir]), pii(x, 0)) - d[!dir].begin() + d[!dir].size() - 1) % d[!dir].size();
			len = (L + x - d[!dir][nxtp].first) % L / 2;
			if(len == 0) len = L / 2;
		}else{	// cw
			nxtp = (upper_bound(ALL(d[!dir]), pii(x+1, -1)) - d[!dir].begin()) % d[!dir].size();
			len = (L + d[!dir][nxtp].first - x) % L / 2;
			if(len == 0) len = L / 2;
		}
		if(T <= len){
//			cerr << "! " << c << endl;
			return p;
		}
		p = d[!dir][nxtp].second;
		T -= len;
		off += len;
		c ++;
	}
}

