#define REP(i,a,b) for(int i=int(a);i<int(b);i++)

using namespace std;

typedef long long int lli;

struct data{
    int l, t, lp, rp;
    bool check;
    data(int l, int t, int lp, int rp, bool c) : l(l), t(t), lp(lp), rp(rp), check(c) {}
};

bool operator<(data d1, data d2) {
    if (d1.t != d2.t) return (d1.t > d2.t);
    else return d1.t > d2.t;
}

int main () {
    int N, L, T;
    cin >> N >> L >> T;
    T %= L;
    vector<lli> x(N);
    vector<int> w(N);
    REP (i, 0, N) {
        cin >> x[i] >> w[i];
        w[i]--;
    }
    vector<int> final(N);
    REP (i, 0, N) {
        if (w[i] == 0) {
            final[i] = (x[i] + T) % L;
        } else {
            final[i] = (x[i] - T + L) % L;
        }
    }
    vector<int> place(N);
    REP (i, 0, N) place[i] = i;
    priority_queue<data, vector<data>> pq;
    REP (i, 0, N) {
        if (w[i] == 0 && w[(i + 1) % N] == 1) {
            // 繰り上がり
            int tm = (1 + (x[(i + 1) % N] - x[i] + L) % L) / 2;
            pq.emplace(i, tm, (x[i] + tm) % L, (x[i + 1] - tm + L) % L, !(((x[(i + 1) % N] - x[i] + L) % L) % 2));
        }
    }
    vector<lli> befTime(N, 0);
    while (pq.size()) {
        data d = pq.top();
        pq.pop();
        if (d.t > T) break;
        w[d.l] = 1 - w[d.l];
        w[(d.l + 1) % N] = 1 - w[(d.l + 1) % N];
        befTime[d.l] = befTime[(d.l + 1) % N] = d.t;
        x[d.l] = d.lp;
        x[(d.l + 1) % N] = d.rp;
        swap(final[d.l], final[(d.l + 1) % N]);
        if (w[(d.l - 1 + N) % N] == 0 && w[d.l] == 1) {
            x[(d.l - 1 + N) % N] = (x[(d.l - 1 + N) % N] + d.t - befTime[(d.l - 1 + N) % N]) % L;
            befTime[(d.l - 1 + N) % N] = d.t;
            int tm = (1 + (d.lp - x[(d.l - 1 + N) % N] + L) % L) / 2;
            pq.emplace((d.l - 1 + N) % N, d.t + tm, (x[(d.l - 1 + N) % N] + tm) % L, (x[d.l] - tm + L) % L, !(((d.lp - x[(d.l - 1 + N) % N] + L) % L) % 2));
        }

        if (w[(d.l + 1) % N] == 0 && w[(d.l + 2) % N] == 1) {
            x[(d.l + 2) % N] = (x[(d.l + 2) % N] + d.t - befTime[(d.l + 2) % N]) % L;
            befTime[(d.l + 2) % N] = d.t;
            int tm = (1 + (x[(d.l + 2) % N] - x[(d.l + 1) % N] + L) % L) / 2;
            pq.emplace((d.l + 1) % N, d.t + tm, (x[(d.l + 1) % N] + tm) % L, (x[(d.l + 2) % N] - tm + L) % L, !(((x[(d.l + 2) % N] - x[(d.l + 1) % N] + L) % L) % 2));            
        }
    }
    REP (i, 0, N) {
        cout << final[i] << endl;
    }
    return 0;
}

#include <bits/stdc++.h>
using namespace std;
const int N=1e5+100;
int n,l,t,ans[N],wa,wb;
struct node
{
	int x,w,id;
}a[N];
node b[N],sh[N];
deque <int> s;
int main()
{
	scanf("%d%d%d",&n,&l,&t);
	for (int i=1;i<=n;i++)
	{
		int x,w;
		scanf("%d%d",&x,&w);
		sh[i].x=x,sh[i].w=w;
		if (w==1) a[++wa].x=x,a[wa].w=w,a[wa].id=i;
		else b[++wb].x=x,b[wb].w=w,b[wb].id=i;
	}
	for (int i=1;i<=wb;i++) s.push_back(b[i].x);
	for (int i=1;i<=wa;i++)
	{
		while (s.front()<a[i].x)
		{
			int x=s.front();
			s.pop_front();
			s.push_back(x+l);
		}
		int now=2*t,cnt=0;
		cnt=(now/l)*wb,now%=l;
		cnt+=upper_bound(s.begin(),s.end(),a[i].x+now)-s.begin();
		cnt%=n;
		if (a[i].id+cnt>n) sh[a[i].id].id=a[i].id+cnt-n;
		else sh[a[i].id].id=a[i].id+cnt;
	}
	s.clear();
	for (int i=1;i<=wa;i++) s.push_back(a[i].x);
	for (int i=wb;i>=1;i--)
	{
		while (s.back()>b[i].x)
		{
			int x=s.back();
			s.pop_back();
			s.push_front(x-l);
		}
		int now=2*t,cnt=0;
		cnt=(now/l)*wa,now%=l;
		cnt+=wa-(lower_bound(s.begin(),s.end(),b[i].x-now)-s.begin());
		cnt%=n;
		if (b[i].id-cnt<1) sh[b[i].id].id=n+b[i].id-cnt;
		else sh[b[i].id].id=b[i].id-cnt;
	}
	for (int i=1;i<=n;i++)
	{
		if (sh[i].w==2) ans[sh[i].id]=(sh[i].x-t+l)%l;
		else ans[sh[i].id]=(sh[i].x+t)%l;
	}
	for (int i=1;i<=n;i++) printf("%d\n",ans[i]);
}

