int main(){
	long long n, l, t; cin >> n >> l >> t;
	vector<long long> x(n), w(n);
	for(int i = 0; i < n; i++) cin >> x[i] >> w[i];
	dynamic_tree<long long, long long, 0, (long long)(1e9)> mv[2];
	for(int i = 0; i < n; i++){
		w[i]--;
		mv[w[i]].add_to_pos(x[i], 1);
	}
	vector<pair<int,long long> > who;
	for(int i = 0; i < n; i++){
		if(2 * t >= l){
			if(w[i] == 0){
				who.push_back({(i + mv[1].query(0, l)) % n, (x[i] + t) % l});
			} else {
				who.push_back({(i + n - mv[0].query(0, l)) % n, (x[i] - t + l) % l});
			}
		} else if(w[i] == 0){
			int from = x[i], to = (x[i] + 2 * t) % l;
			int stp = 0;
			if(from <= to) stp = mv[1].query(from, to);
			else stp = mv[1].query(0, to) + mv[1].query(from, l);
			who.push_back({(i + stp) % n, (x[i] + t) % l});	
		} else {
			int from = (x[i] - 2 * t + l) % l, to = x[i];
			int stp = 0;
			if(from <= to) stp = mv[0].query(from, to);
			else stp = mv[0].query(0, to) + mv[0].query(from, l);
			who.push_back({(i + n - stp) % n, (x[i] + l - t) % l});
		}
	}
	sort(who.begin(), who.end());
	for(auto e : who) cout << e.second << endl;
	return 0;
}

