  hm = ( migi / SZ(b) * l + ( l + b[migi%SZ(b)] - a.back() ) % l ) / 2;
  hh = ( hidari / SZ(a) * l + ( l + a.back() - a[(hidari+SZ(a)-1)%SZ(a)] ) % l ) / 2;
  return hm + hh;
}

int main(){

  n = in();
  l = in() * 2;
  t = in() * 2;
  REP( i , n ){
    x[i] = in() * 2;
    y[i] = in();
  }

  REP( i , n ){
    if( y[i] == 1 ){
      a.pb( x[i] );
    } else {
      b.pb( x[i] );
    }
  }


  if( SZ(a) == 0 ){
    REP( i , n ){
      printf( "%lld\n" , ( ( ( x[i] - t ) % l + l ) % l ) / 2 );
    }
    return 0;
  }

  if( SZ(b) == 0 ){
    REP( i , n ){
      printf( "%lld\n" , ( ( x[i] + t ) % l ) / 2 );
    }
    return 0;
  }

  ll st = -1;
  REP( i , n ){
    if( y[i] == 1 ){
      st = i;
      break;
    }
  }

  REVERSE( a );

  ll lb = 0, ub = INF * 4;
  while( ub - lb > 1 ){
    ll md = ( lb + ub ) / 2;
    if( check( md ) <= t ){
      lb = md;
    } else {
      ub = md;
    }
  }

  vl ans(0);
  REP( i , n ){
