	long long n, l, t; cin >> n >> l >> t;
	vector<long long> x(n), w(n);
	for(int i = 0; i < n; i++) cin >> x[i] >> w[i];
	dynamic_tree<long long, long long, 0, (long long)(1e9)> mv[2];
	for(int i = 0; i < n; i++){
		w[i]--;
		mv[w[i]].set_pos(x[i], 1);
	}
	vector<long long> ans(n);
	for(int i = 0; i < n; i++){
		int stp = 0;
		if(w[i] == 0){
			stp += mv[1].query(0, l) * (2 * t / l) % n;
			int from = x[i], to = (x[i] + (2 * t % l)) % l;
			if(from <= to) stp += mv[1].query(from, to);
			else stp += mv[1].query(0, to) + mv[1].query(from, l);
			ans[(i + stp) % n] = (x[i] + t) % l;
		} else {
			stp += mv[0].query(0, l) * (2 * t / l) % n;
