using ll = long long;
using namespace std;

template <typename UnaryPredicate>
ll binsearch(ll l, ll r, UnaryPredicate p) { // [l, r), p is monotone
    -- l;
    while (r - l > 1) {
        ll m = (l + r) / 2;
        (p(m) ? r : l) = m;
    }
    return r; // = min { x in [l, r) | p(x) }, or r
}

vector<int> solve(int n, int l, int t, vector<int> const & x, vector<int> const & w) {
    vector<int> cw, ccw;
    repeat (i, n) {
        (w[i] == 1 ? cw : ccw).push_back(x[i]);
    }
    int lshift = ((t / l) *(ll) (int(ccw.size()) - int(cw.size())) % n + n) % n;
    t %= l;
    function<int (vector<int> &, int, int)> cnt = [&](vector<int> & a, int l1, int r1) {
        if (l1 >= r1) {
            return cnt(a, 0, r1) + cnt(a, l1, l);
        } else {
            int l2 = binsearch(0,  a.size(), [&](int i) { return a[i] >= l1; });
            int r2 = binsearch(l2, a.size(), [&](int i) { return a[i] >= r1; });
            return r2 - l2;
        }
    };
    vector<int> y(n, -1);
    repeat (i, n) {
        int j;
        int y_j;
        if (w[i] == 1) {
            y_j = (x[i] + t) % l;
            j = cnt(ccw, x[i], (x[i] + 2ll * t + 1) % l);
        } else {
            y_j = (x[i] - t +(ll) l) % l;
            j = - cnt(cw, (x[i] - 2ll * t + 2ll * l) % l, (x[i] + 1) % l);
        }
        j = (i + j + n) % n;
        y[j] = y_j;
    }
    rotate(y.begin(), y.begin() + lshift, y.end());
    return y;
}

int main() {
    int n, l, t; scanf("%d%d%d", &n, &l, &t);
    vector<int> x(n), w(n); repeat (i, n) scanf("%d%d", &x[i], &w[i]);
    vector<int> y = solve(n, l, t, x, w);
    for (int y_i : y) {
        printf("%d\n", y_i);
    }
    return 0;
}

