int N, L, T;
int X[112345], W[112345];
int ans[112345];

int calc(int idx) {
	ll res = 0;

	REP(i, N) if (i != idx) {
		ll t = 1e11;

		if (W[idx] == 1 && W[i] == 2) t = (X[i] - X[idx] + L) % L;
		if (W[idx] == 2 && W[i] == 1) t = (X[idx] - X[i] + L) % L;

		if (2 * T >= t) res += (2 * T - t) / L + 1;
	}

	res %= N;
	if (W[idx] == 2) res = (idx - res + N) % N;
	else res = (idx + res) % N;

	return res;
}

int endP(int idx) {
	if (W[idx] == 1) return ((ll)X[idx] + T) % L;
	else return ( ( (ll)X[idx] - T ) % L + L) % L;
}

int main() {
	cin >> N >> L >> T;
	REP(i, N) scanf("%d %d", X + i, W + i);

	vector<int> e(N); // T秒後の各位置
	REP(i, N) e[i] = endP(i);
	sort(ALL(e));

	if (N == 1) {
		cout << e[0] << endl;
		return 0;
	}

	int idx1 = calc(0), p1 = endP(0);
	int idx2 = calc(1), p2 = endP(1);

	int st = -1;

	REP(i, N) {
		if (e[i] == p1 && e[(idx2 - idx1 + i + N) % N] == p2) {
			st = i;
			break;
		}
	}

	assert(st != -1);

	REP(i, N) ans[(idx1 + i) % N] = e[(i + st) % N];
	REP(i, N) printf("%d\n", ans[i]);

	return 0;
}

