template <typename T>
inline T mod(T a, T m) {
    T res = a % m;
    if (res < 0) res += m;
    return res;
}


class Solver {
    int N, L, T;
    vi x, w;

    vi cw, ccw, xt;
    int CW, CCW;
public:
    Solver() {
        scanf("%d%d%d", &N, &L, &T);
        x.resize(N); w.resize(N);
        rep(i,N) {
            scanf("%d%d", &x[i], &w[i]);
        }

        init();

        if (N == 1) {
            printf("%d\n", xt[0]);
            return;
        }

        pair<ll,bool> p0 = solve1(0);
        ll crossed = p0.first;
        bool just = p0.second;
        if (just) --crossed;
        int x0 = xt[0], dir0 = (w[0] == 1) ? 1 : -1;
        int from = dir0 * (crossed % 2 ? -1 : 1);

        int c0 = mod(0LL + dir0*crossed, (ll)N);

        sort(ALL(xt));

        int ix = lower_bound(ALL(xt), x0) - xt.begin();
        assert(xt[ix] == x0);

        int offset = 0;
        if (ix < N-1 && xt[ix+1] == x0) {
            if (from == 1) {
                offset = ix - c0;
            } else {
                offset = ix+1 - c0;
            }
        } else {
            offset = ix - c0;
        }

        rep(i,N){
            printf("%d\n", xt[mod(i+offset, N)]);
        }
    }
private:
    void init() {
        cw.clear(); ccw.clear();
        cw.reserve(N); ccw.reserve(N);
        xt.resize(N);
        rep(i,N){
            if (w[i] == 1) {
                cw.pb(x[i]);
                xt[i] = mod(x[i] + T, L);
            } else {
                ccw.pb(x[i]);
                xt[i] = mod(x[i] - T, L);
            }
        }
        CW = cw.size(); CCW = ccw.size();
    }
    pair<ll,bool> solve1(int i) {
        ll crossed = 0;
        bool just = false;
        if (w[i] == 1) {
            for (int y: ccw) {
                int d2 = y - x[i];
                if (d2 < 0) d2 += L;
                assert(IN(d2, 0, L-1));
                int q = 1+(T*2 - d2)/L;
                crossed += q;
                if (T*2 % L == d2) just = true;
            }
        } else {
            for (int y: cw) {
                int d2 = x[i] - y;
                if (d2 < 0) d2 += L;
                assert(IN(d2, 0, L-1));
                int q = 1+(T*2 - d2)/L;
                crossed += q;
                if (T*2 % L == d2) just = true;
            }
        }
        return make_pair(crossed, just);
    }
};

int main() {
    Solver *s = new Solver();
    delete s;
    return 0;
}

