ll N,M,K,A[NMAX],B,C,D,E;
// int dp[NMAX] = {};
int W[NMAX]={};
ll ans = 0;
ll pos[NMAX]={};
void solve(){
    // 解答アルゴリズム
    for (int i = 0; i < N; ++i)
    {
        if(W[i] % 2) {
            // forward
            pos[i] = (A[i] + K) % M;
        }
        else {
            // backward
            pos[i] = (A[i] - K) % M;
            if(pos[i] < 0) pos[i] += M;
        }
    }
    // calc offset
    int offset = 0;
    if (W[0] % 2)
    {
        for (int i = 1; i < N; ++i)
        {
            int cross = 2 * K - (A[i] - A[0]);
            if (W[i] != W[0] && cross >= 0)
            {
                offset = (offset + cross / M + 1) % N; 
            }
        }
    }else{
        for (int i = N - 1; i > 0; --i)
        {
            int cross = 2 * K - (A[0] + M - A[i]);
            if (W[i] != W[0] &&  cross >= 0)
            {
                offset = (offset - cross / M - 1) % N;
            }
        }
    }
    if(offset < 0) offset += N;

    // answer
    for (int i = 0; i < N; ++i)
    {
        printf("%lld\n", pos[(N - offset + i) % N]);
    }

}
