typedef pair<ll, ll> ii;
typedef tuple<ll, ll, ll> iii;
typedef vector<ll> vi;
typedef vector<ii> vii;
typedef vector<iii> viii;
typedef vector<vi> vvi;
typedef vector<vii> vvii;
#define REP(i,n) for (ll i = 0; i < n; ++i)
#define REPR(i,n) for (ll i = n-1; i >= 0; --i)
#define FOR(i,m,n) for (ll i = m; i < n; ++i)
#define FORR(i,m,n) for (ll i = n-1; i >= m; --i)
#define FORE(x,xs) for (const auto& x : xs)
#define FORI(i,v) for (auto i = v.begin(); i != v.end(); i++)
#define ALL(v) v.begin(), v.end()
#define CHMIN(x,y) x = min(x, y)
#define CHMAX(x,y) x = max(x, y)

const int MAX = 1e5+10;

ll N, L, T;
ll X[MAX], W[MAX];

void add(ll& n, ll m, ll mod) {
    n += m;
    n %= mod;
    if (n < 0) n += mod;
}

ii getPair(int n) {
    ll pos = 0;
    ll w = W[n], x = X[n];
    if (w == 1) add(pos, x+T, L);
    else add(pos, x-T, L);

    ll rest = T % L;
    ll idx = n;
    ll count = 0;

    REP (i, N) if (w != W[i]) {
        ll dist = 0;
        if (w == 1) add(dist, X[i]-x, L);
        else add(dist, x-X[i], L);

        count += 2 * (T / L);
        if (2 * rest >= dist + L) count += 2;
        else if (2 * rest >= dist) count++;
    }

    if (w == 1) add(idx, count, N);
    else add(idx, -count, N);

    return ii(idx, pos);
}

vi solve() {
    vi pos(N);
    REP (i, N) {
        if (W[i] == 1) add(pos[i], X[i]+T, L);
        else add(pos[i], X[i]-T, L);
    }
    sort(ALL(pos));

    ii p0 = getPair(0), p1 = getPair(1);
    int idx = -1;
    REP (i, N) if (pos[(i+p0.first)%N] == p0.second && pos[(i+p1.first)%N] == p1.second) {
        idx = i;
        break;
    }
    if (idx == -1) assert(false);
    vi ret(N);
    REP (i, N) ret[i] = pos[(idx+i)%N];
    return ret;
}

int main() {
    cin >> N >> L >> T;
    REP (i, N) cin >> X[i] >> W[i];
    FORE (x, solve()) cout << x << endl;
}

