int b[200000];
//答え
vector<int>lef, rig;
vector<H>lef2, rig2;
int solve(int i, int j) {
	//iとjの向きは必ず違う
	if (w[i] == 2) swap(i, j);
	ld k = (x[j] - x[i] + l) % l;
	k /= 2.0;
	ld r = l / 2.0;
	if (k > t) return 0;
	return 1 + (t - k) / r;
}
signed main() {
	cin >> n >> l >> t;
	for (int i = 0; i < n; i++) {
		cin >> x[i] >> w[i];
		if (w[i] == 1) {
			a[i] = (x[i] + t) % l;
			rig.push_back(x[i]);
			rig2.push_back(H{ x[i],i });
		}
		else {
			a[i] = ((x[i] - t) % l + l) % l;
			lef.push_back(x[i]);
			lef2.push_back(H{ x[i],i });
		}
	}
	sort(all(rig)); sort(all(lef));
	sort(all(rig2)); sort(all(lef2));
	if (lef.size() == 0 || rig.size() == 0) {
		for (int i = 0; i < n; i++) cout << a[i] << endl;
		return 0;
	}
	for (int i = 0; i < n; i++) {
		if (w[i] == 1) {
			int k = lower_bound(all(lef), x[i]) - lef.begin() - 1;
			if (k < 0) k = lef.size() - 1;
			//小さいほう
			int o = lower_bound(all(lef), x[i]) - lef.begin();
			if (o == lef.size()) o = 0;
			//大きいほう
			int l = solve(i, lef2[k].y), r = solve(i, lef2[o].y);
			if (l == r) {
				b[(i + l * lef.size()) % n] = a[i];
				continue;
			}
			int s = 0, e = lef.size(), t;
			while (e - s > 1) {
				t = (s + e) / 2;
				if (solve(i, lef2[(k + t) % lef.size()].y) == l) s = t;
				else e = t;
			}
			int sum = (s + 1)*l + (lef.size() - s - 1)*r;
			b[(i + sum) % n] = a[i];
		}
		else {
			int k = lower_bound(all(rig), x[i]) - rig.begin() - 1;
			if (k < 0) k = rig.size() - 1;
			//大きいほう
			int o = lower_bound(all(rig), x[i]) - rig.begin();
			if (o == rig.size()) o = 0;
			//小さいほう
			int l = solve(i, rig2[o].y), r = solve(i, rig2[k].y);
			if (l == r) {
				b[((i - l * rig.size()) % n + n) % n] = a[i];
				continue;
			}
			int s = 0, e = rig.size(), t;
			while (e - s > 1) {
				t = (s + e) / 2;
				if (solve(i, rig2[(o + t) % rig.size()].y) == l) s = t;
				else e = t;
			}
			int sum = (s + 1)*l + (rig.size() - s - 1)*r;
			b[((i - sum) % n + n) % n] = a[i];
		}
	}
	for (int i = 0; i < n; i++) {
		cout << b[i] << endl;
	}
}

