#include <bits/stdc++.h>
using namespace std;

class Ant {
private:
  int index; // 何番目のアリ
  long long x; // 座標
  long long L; // 周り
  bool is_clockwise; // 時計回りか
  Ant* nextAnt; // 前のアリ
  Ant* preAnt; // 次のアリ

public:
  Ant(int index, long long x, long long L, bool is_clockwise): index(index), x(x), L(L), is_clockwise(is_clockwise), nextAnt(NULL), preAnt(NULL) {}

  // コピーコンストラクタ
  Ant(const Ant& ant): index(ant.index), x(ant.x), L(ant.L), is_clockwise(ant.is_clockwise), nextAnt(ant.nextAnt), preAnt(ant.preAnt) {}

  int nextX(int _x) { return _x == L - 1 ? 0 : _x + 1; }
  int preX(int _x) { return _x == 0 ? L - 1 : _x - 1; }

  void setNextAnt(Ant* _nextAnt) { nextAnt = _nextAnt; }
  void setPreAnt(Ant* _preAnt) { preAnt = _preAnt; }
  long long getX() { return x; }
  void setX(long long _x) { x = _x; }
  int getIndex() { return index; }
  bool getIsClockwise() { return is_clockwise; }
  void setIsClockwise(bool _is_clockwise) { is_clockwise = _is_clockwise; }

  // 進行方向へ進む
  void go() {
    if (is_clockwise) {
      x = nextX(x);
    } else {
      x = preX(x);
    }
  }

  // 進行方向を逆にする
  void changeDirection() {
    is_clockwise = ! is_clockwise;
  }

  // 同じ座標に隣のアリがいるかチェックする
  void checkCoordinates() {
    if (x == nextAnt->getX()) {
      is_clockwise = ! is_clockwise;
    }
    if (x == nextX(nextAnt->getX())) {
      is_clockwise = ! is_clockwise;
      long long tmp_x = x;
      x = nextAnt->getX();
      nextAnt->setX(tmp_x);
      nextAnt->setIsClockwise(! is_clockwise);
    }
    if (x == preAnt->getX()) {
      is_clockwise = ! is_clockwise;
    }
    if (x == preX(preAnt->getX())) {
      is_clockwise = ! is_clockwise;
      long long tmp_x = x;
      x = preAnt->getX();
      preAnt->setX(tmp_x);
      preAnt->setIsClockwise(! is_clockwise);
    }
  }

  void showInfo() {
    printf("index: %d, x: %d, L: %d, is_clockwise: %d\n", index, x, L, is_clockwise);
  }

  void showNextAndPre() {
    printf("index: %d, nextAnt: %d, preAnt: %d\n", index, nextAnt->getIndex(), preAnt->getIndex());
  }
};

