ll n,l,t;
ll x[100001],w[100001],afx[100001],change[100001];

int main(void){
    scanf("%lld%lld%lld",&n,&l,&t);

    REP(i,n){
        scanf("%lld%lld",&x[i],&w[i]);
    }

    REP(i,n){
        ll a;
        if(w[i] == 1)
            a = 1;
        else
            a = -1;
        afx[i] = (x[i] + t * a) % l;
        if(afx[i] < 0)
            afx[i] += l;
    }

    FOR(i,1,n){
        if(w[0] == w[i]){
            change[i] = 0;
        }else{
            ll d = t * 2;

            ll b,c;

            if(w[0] == 1){
                b = x[0];c = x[i];
            }else{
                b = x[i];c = x[0];
            }
            change[i] = 0;
            if(c >= b){
                 d -= c - b;
            }else{
                d -= l - b +c;
            }
            if(d >= 0)
            change[i]++;
            else
                d = 0;
            change[i] += d / l;
        }
    }

    ll sum = 0;

    FOR(i,1,n){
        sum += change[i];
    }
    sum %= n;
    if(w[0] == 2)
        sum = (n - sum) % n;

    ll rem = afx[0];

    sort(afx,afx + n);

    ll start;
    afx[n] = -1000;
    REP(i,n){
        if(afx[i] == rem && afx[(i + 1) % n] != rem){
            start = i;
            break;
        }
        else if(afx[i] == rem && afx[(i + 1) % n] == rem){
            if(w[0] == 1)
                start = i  + 1;
            else
                start = i;
            break;
        }
    }

    start = (n + start - sum) % n;

    REP(i,n){
        printf("%lld\n",afx[start++]);
        if(start == n)
            start = 0;
    }

    return 0;
}

