ll n, l, t, x[100000], w[100000], now[100000], noww[100000], ans[200000];

int main() {
  scanf("%lld%lld%lld", &n, &l, &t);
  ll counter = 0;
  for (ll i = 0; i < n; i++) scanf("%lld%lld", &x[i], &w[i]), counter += w[i] - 1;
  counter *= t / l;
  t %= l;
  for (ll i = 0; i < n; i++) {
    now[i] = x[(i + counter) % n];
    noww[i] = w[(i + counter) % n];
    ans[i] = (x[i] + (w[i] == 1 ? t : -t)) % l;
    if (ans[i] < 0) ans[i] += l;
  }
  sort(ans, ans + n);
  for (ll i = 0; i < n; i++) ans[i+n] = ans[i];
  ll first = -1;
  for (ll i = 0; i < n; i++) if (noww[i] == 1) { first = i; break; }
  if (first == -1) {
    for (ll i = 0; i < n; i++) {
      x[i] = (x[i] - t) % l;
      if (x[i] < 0) x[i] += l;
      printf("%lld\n", x[i]);
    }
  }
  counter = 0;
  for (ll i = first + 1; i < first + n; i++) if (noww[i%n] == 2) {
    ll temp = now[i%n] - now[first];
    if (temp < 0) temp += l;
    if (temp <= 2 * t) counter++;
  }
  ll num;
  for (ll i = 0; i < n; i++) if ((now[first] + t) % l == ans[i]) num = i;
  num = (num + n - counter) % n;
  //printf("%lld, %lld, %lld\n", first, counter, num);
  ll diff = (num + n - first) % n;
  for (ll i = 0; i < n; i++) printf("%lld\n", ans[(diff + i) % n]);
}

