int X[100000 + 10];
int W[100000 + 10];

signed main() {
    vi last_pos;
    cin >> N >> L >> T;
    rep(i, N) {
        cin >> X[i] >> W[i];
        if (W[i] == 1) last_pos.pb((X[i] + T) % L);
        else last_pos.pb((X[i] + L * (int)1e10 - T) % L);
    }
    int last;
    if (W[0] == 1) { //時計回り
        int encount=0;
        Rep(i, 1, N) {
            if (W[1] == 2) {
                int a = dist(X[0], X[i]);
                if (T >= a/2.) { 
                    encount++;
                    double restT = T - a/2.;
                    encount += floor(restT / (L / (double)2));
                }
            }
        }
        // cout << encount << endl;
        last = encount % N;
    } else { //反時計回り
        int encount=0;
        Rep(i, 1, N) {
            if (W[1] == 1) {
                int a = dist(X[i], X[0]);
                // cout << "a:" << a << endl;
                if (T >= a/2.) { 
                    encount++;
                    double restT = T - a/2;
                    encount += floor(restT / (L / (double)2));
                }
            }
        }
        // cout << encount << endl;
        last = ((N * (int)1e10) - encount) % N;
    }

    rotate(last_pos.begin(), last_pos.begin()+N-last, last_pos.end());
    for(auto e:last_pos) {
        cout << e << endl;
    }

    return 0;
}

