        u[i] = ((a+(b == 1 ? t : -t) + l*MOD)%l);
        if(i == 0) k = u[i];
    }
    sort(u.begin(), u.end());
    int cur = static_cast<int>(lower_bound(u.begin(), u.end(), k) - u.begin());
    ll a = n*INF<int>;
    if(v[0].second == 1){
        for (int i = 1; i < n; ++i) {
            if(v[i].second == 1) continue;
            ll x = v[i].first - v[0].first;
            if(x >= t){
                a += (x-t)/l*2+1;
            }
        }
    }else {
        for (int i = 1; i < n; ++i) {
            if(v[i].second == 2) continue;
            ll x = l - v[i].first + v[0].first;
            if(x >= t){
                a -= (x-t)/l*2+1;
            }
        }
    }
    a %= n;
    for (int i = 0; i < n; ++i) {
        printf("%li\n", u[(cur-a+n+i)%n]);
    }
    return 0;
}

