std::pair<bool, int> x0_pos(int n, int l, int t, int *x, int *w) { // true if it's forwarding
	t *= 2;
	// assume w[0] = true
	// first collision of x[0] ahead
	int first_col;
	int first_col_dist = 1000000001;
	for (int i = 1; i < n; i++) {
		if (w[i]) continue;
		int dist = (x[i] - x[0] + l) % l;
		if (dist < first_col_dist) first_col_dist = dist, first_col = i;
	}
	std::cerr << "dist:" << first_col_dist << " i:" << first_col << std::endl;
	if (t <= first_col_dist) return {true, x[0]};
	t -= first_col_dist;
	std::vector<int> inv;
	std::vector<int> ahead;
	for (int i = 0; i < n; i++) if (!w[i]) inv.push_back(x[i]); else ahead.push_back(x[i]);
	std::sort(inv.begin(), inv.end()); //******************//
	std::sort(ahead.begin(), ahead.end()); // *************** //
	std::vector<int> interval_ahead;
	std::vector<int> interval_inv;
	if (ahead.size() > 1) {
		for (int i = ahead.size() - 1; i > 0; i--) {
			int x2 = ahead[(i + 1) % ahead.size()];
			int x1 = ahead[i];
			int dist = (x2 - x1 + l) % l;
			interval_ahead.push_back(dist);
		}
		interval_ahead.push_back((ahead[1] - ahead[0] + l) % l);
		assert(std::accumulate(interval_ahead.begin(), interval_ahead.end(), 0LL) == l);
	} else interval_ahead.push_back(l);
	if (inv.size() > 1) {
		for (int i = 0; i < (int) inv.size(); i++) {
			// first_col, first_col + 1
			int x2 = inv[(i + first_col + 1) % inv.size()];
			int x1 = inv[(i + first_col) % inv.size()];
			int dist = (x2 - x1 + l) % l;
			interval_inv.push_back(dist);
		}
	for (auto i : interval_inv) std::cerr << i << " ";
	std::cerr << std::endl;
		assert(std::accumulate(interval_inv.begin(), interval_inv.end(), 0LL) == l);
	} else interval_inv.push_back(l);
	int ll = -1;
	int rr = 1000000001;
	while (rr - ll > 1) {
		int m = ll + (rr - ll) / 2;
		// m times
		int64_t r0 = m / interval_ahead.size() * l;
		for (int i = 0; i < m % interval_ahead.size(); i++) r0 += interval_ahead[i];
		int64_t r1 = m / interval_inv.size() * l;
		for (int i = 0; i < m % interval_inv.size(); i++) r1 += interval_inv[i];
		if (r0 + r1 > t) rr = m;
		else ll = m;
	}
	std::cerr << "ll:" << ll << std::endl;
	int r0 = ll / interval_ahead.size() * l;
	for (int i = 0; i < ll % interval_ahead.size(); i++) r0 += interval_ahead[i];
	int r1 = ll / interval_inv.size() * l;
	for (int i = 0; i < ll % interval_inv.size(); i++) r1 += interval_inv[i];
	int64_t res = 0;
	res -= r1;
	// l ~ r
	std::cerr << "t-tt:" << t - (r0 + r1) << " int_ahead:" << interval_ahead[ll % ahead.size()] << std::endl;
	res -= std::min<int64_t>(t - (r0 + r1), interval_ahead[ll % ahead.size()]);
	bool dir;
	if (t == r0 + r1) dir = true;
	else if (t == r0 + r1 + interval_ahead[ll % ahead.size()]) dir = false;
	else dir = true; // nothing
	return {dir, (res % l + x[0] + l) % l};
}

int main() {
	int n = ri(), l = ri(), t = ri();
	int x[n], w[n];
	for (int i = 0; i < n; i++) x[i] = ri(), w[i] = !(ri() - 1); // 1 => +
