			std::cout << ((x[i] + t * (w[i] ? 1 : -1)) % l + l) % l  << std::endl;
		}
		return 0;
	}
	bool inversed = false;
	if (!w[0]) {
		for (int i = 0; i < n; i++) w[i] = !w[i], x[i] = (l - x[i]) % l;
		inversed = true;
	}
	auto res = x0_pos(n, l, t, x, w);
	int pos = res.second;
