ll N,L,T,X[100000],W[100000],ans[100000];
ll fin[100000];
bool hitb,hitf;

ll solvesingle(int i) {
	int b=i-1;
	if (b<0) b=N-1;
	while (W[b]!=0) {
		b--;
		if (b<0) b=N-1;
	}
	ll wait=(X[i]-X[b])%L;
	if (wait<=0) wait+=L;
	//cerr << "wai: " << wait << endl;

	ll stops=0;
	for (int i=0;i<N;i++) stops+=W[i];
	//cerr << "sto " << stops << endl;

	ll loopt=stops*wait+L;
	ll t=(2*T)%loopt;

	//cerr << loopt << ' ' << t << endl;

	int j=i;
	while (1) {
		while (W[j]==0) {
			j++;
			if (j==N) j=0;
		}

		ll tra=(X[j]-X[i])%L;
		if (tra<=0) tra+=L;
		if (tra==t) hitf=1;
		if (tra>=t) return (X[i]+t)%L;

		t-=tra;
		i=j++;
		if (j==N) j=0;

		if (wait==t) hitb=1;
		if (wait>=t) return X[i];
		t-=wait;

		//cerr << "cycle " << t << endl;
	}
}

