	if (ct==0 || ct==N) {
		for (int i=0;i<N;i++) cout << fin[i] << '\n';
		return 0;
	}

	for (int i=0;i<N;i++) if (W[i]==0) {
		ll p=solvesingle(i);
		p=(p-T)%L;
		//cerr << p << endl;
		if (p<0) p+=L;
		sort(fin,fin+N);
		for (int j=0;j<N;j++) if (fin[j]==p) {
			rotate(fin,fin+j,fin+N);
			break;
		}
		if (fin[N-1]==p) rotate(fin,fin+N-1,fin+N);

		int k=hitb;
		for (int ct=0;ct<N;ct++) {
			ans[i]=fin[k];
			i=(i+1)%N;
			k=(k+1)%N;
		}

		break;
	}

