typedef long long ll;

ll x[100003], a[100003];
int w[100003];

int main() {
	int n; ll L, T; cin >> n >> L >> T;
	for (int i = 0; i < n; ++i) {
		cin >> x[i] >> w[i];
		if (w[i] == 2) w[i] = -1;
		a[i] = (x[i] + w[i] * T % L + L) % L;
	}
	sort(a, a + n);
	ll pos = 0;
	for (int i = 1; i < n; ++i) {
		if (w[i] == w[0]) continue;
		if (w[0] == 1) {
			ll t = 2 * T;
			pos += x[i] - x[0] <= t ? 1 : 0;
			t = max(0LL, t - x[i] + x[0]);
			pos += t / L;
			pos %= n;
		}
		else {
			ll t = 2 * T;
			ll b = L - x[i] + x[0] <= t ? 1 : 0;
			t = max(0LL, t - L + x[i] - x[0]);
			b += t / L;
			pos += n - b%n;
			pos %= n;
		}
	}
	for (int i = 0; i < n; ++i) cout << a[(i + pos) % n] << endl;
	return 0;
}

