int main(){

    int N;
    ll L,T;cin>>N>>L>>T;
    vector<ll> X(N),Y(N);
    vector<pair<ll,int>> goal(N);
    ll c;
    for(int i=0;i<N;i++){
        cin>>X[i]>>Y[i];
        if(Y[i]==1) goal[i]={(X[i]+T)%L,i};
        else goal[i]={(L*T+X[i]-T)%L,i};
        if(i==0) c=goal[i].first;
    }

    sort(all(goal));

    ll cnt=0;

    ll a=X[0],b=Y[0];
    for(int i=1;i<N;i++){
        if(Y[i]==b) continue;
        ll left=-1,right=INF;
        while(right-left>1){
            ll mid=(left+right)/2;
            if(b==1){
                ll dis;
                if(X[i]<=a) dis=L-(a-X[i]);
                else dis=X[i]-a;
                if(dis+(mid-1)*L<=2*T) left=mid;
                else right=mid;
            }else{
                ll dis;
                if(X[i]>=a) dis=X[i]-a;
                else dis=L-(a-X[i]);
                if(dis+(mid-1)*L<=2*T) left=mid;
                else right=mid;
            }
        }
        left%=N;
        if(b==1) cnt+=left;
        else cnt+=(N-left);
        cnt%=N;
    }

    vector<ll> ans(N);

    ans[cnt]=c;
    int k;
    if(b==1){
        for(int i=0;i<N;i++){
            if(goal[i].first==c){
                k=i+1;
            }
        }
    }else{
        for(int i=N-1;i>=0;i--){
            if(goal[i].first==c){
                k=i+1;
            }
        }
    }

    for(int i=cnt+1;i<cnt+N;i++,k++){
        int j=i%N,l=k%N;
        ans[j]=goal[l].first;
    }

    for(int i=0;i<N;i++){
        cout<<ans[i]<<endl;
    }
}

