ll calc(ll x, ll y, ll L, ll T){
  if(T*2 < abs(x-y)){
    return 0;
  }
  ll remain = T*2 - abs(x-y);
  return 1+remain/L;
}

int main(){
  int N, L, T;
  cin >> N >> L >> T;
  vector<ll> X, W;
  vector<int> ans;

  rep(i,N){
    int x, w;
    cin >> x >> w;
    X.push_back(x);
    W.push_back(w);

    if(w == 1){
      ans.push_back((x+T)%L);
    }else{
      ans.push_back(((x-T)%L+L)%L);
    }
  }

  int SZ = ans.size();
  int cnt = 0;
  if(W[0] == 1){
    rep(i,X.size()){
      if(W[i] == 2){
        cnt += calc(X[0], X[i], L, T);
      }
    }
    vector<int> ret(SZ);
    rep(i,ans.size()){
      ret[(i+cnt)%SZ] = ans[i];
    }

    rep(i,ret.size()){
      cout << ret[i] << endl;
    }

  }else{
    rep(i,X.size()){
      if(W[i] == 1){
        cnt += calc(X[i], X[0], L, T);
      }
    }

    vector<int> ret(ans.size());
    rep(i,ans.size()){
      ret[((i-cnt)%SZ+SZ)%SZ] = ans[i];
    }

    rep(i,ret.size()){
      cout << ret[i] << endl;
    }

  }


  return 0;
}

