pair<int, int> y[N];

int main()
{
	cin >> n >> l >> t;
	for (int i = 1; i <= n; i++)
	{
		scanf("%d%d", &x[i], &w[i]);
		if (w[i] == 1)
		{
			y[i] = make_pair((x[i] + t) % l, i);
		}
		else
		{
			y[i] = make_pair(((x[i] - t) % l + l) % l, i);
		}
	}
	sort(y + 1, y + n + 1);
	int cnt = 0;

	for (int i = 2; i <= n; i++)
	{
		if (w[1] != w[i])
		{
			if (w[1] == 1 && w[i] == 2)
			{
				cnt += ((x[i] - x[1]) / 2 <= t) + (2 * t - (x[i] - x[1])) / l;
			}
			else
			{
				cnt += ((l - x[i] - x[1]) / 2 <= t) + (2 * t - (l - x[i] - x[1])) / l;
			}
		}
	}

	int pos;
	for(int i = 1; i <= n; i++) if(y[i].second == 1) pos = i;
	pos -= cnt;
	if(pos < 0) pos += n;

	for (int i = n - pos + 1; i <= n; i++)
	{
		printf("%d\n", y[i].first);
	}
	for (int i = 1; i <= n - pos; i++)
	{
		printf("%d\n", y[i].first);
	}
	return 0;
}

