#include <bits/stdc++.h>

using namespace std;

int main() {
	cin.tie(0);
	ios::sync_with_stdio(false);
	int n, l, t;
	cin >> n >> l >> t;
	vector<int> x(n), w(n), pos(n);
	for (int i = 0; i < n; i++) {
		cin >> x[i] >> w[i];
		//蟻同士が互いにすり抜けると仮定するとT秒後の蟻の位置がわかる
		if (w[i] == 1) {
			pos[i] = (x[i] + t % l) % l;
		} else {
			pos[i] = (x[i] - t % l + l) % l;
		}
	}

	//実際には蟻同士は衝突するので、蟻0-(n-1)(0-indexed)は時計回りに存在する
	//そこで、すり抜けた場合の蟻0の位置(tar=sort前のpos[0])==実際のT秒後の蟻iの位置とした時のiを求める
	//これにより、tar==sort後のpos[j]となるjと蟻iが対応していることがわかり、他の蟻の位置もわかる

	//以下、蟻iの候補を求める(iの初期値は0)
	//蟻0が時計回りに移動する場合、衝突の度にiが1増える
	//一方、蟻0が反時計回りに移動する場合、衝突の度にiが1減る
	//蟻0と進行方向が逆なものに対してそれぞれ衝突回数を求める
	int sum = 0; //衝突回数の合計
	for (int i = 1; i < n; i++) {
		if (w[i] == w[0]) continue;
		int tmp; //2匹の蟻の開始時点の距離
		if (w[0] == 1) tmp = (x[i] + l - x[0]) % l;
		else tmp = (x[0] + l - x[i]) % l;
		if (2 * t < tmp) continue; //衝突しない場合
		sum += (2 * t - tmp) / l + 1; //最初1回衝突すると次に会うのは2匹の進行距離の合計がLになる時
	}

	int tar = pos[0];
	int idx; //蟻i
	if (w[0] == 1) {
		idx = sum % n;
	} else {
		idx = (n - sum % n) % n;
	}

	sort(pos.begin(), pos.end());

	int sidx; //tar==sort後のpos[j]となるj
	for (int i = 0; i < n; i++) {
		if (pos[i] == tar) {
			sidx = i;
			//T秒後の位置が同じになる場合がある
			//しかし、同じ位置になるのは、最初の位置がすべて異なり、同じ速度で動いているため2匹しかありえない
			//先程の衝突回数の数え方だと、T秒後に位置が同じになる場合は衝突したとみなす
			//よって、進行方向においてより遠い方に蟻iはいると考えれば良い
			if (i + 1 < n && pos[i + 1] == tar && w[0] == 1) sidx = i + 1;
			break;
		}
	}

	vector<int> ans(n);
	for (int i = 0; i < n; i++) {
		ans[(idx + i) % n] = pos[(sidx + i) % n];
	}

	for (int x : ans) cout << x << endl;

	return 0;
}

