	for (ll i = 0; i < argT; ++i) {
	    for (ll j = 0; j < argN; ++j) {
			ll pos = j;
			ll next = j + 1;
			if (j == argN - 1) {
				next = 0;
			}

			if (argX.at(pos).first == argX.at(next).first) {
				ll pre = argX.at(pos).second;
				argX.at(pos).second = argX.at(next).second;
				argX.at(next).second = pre;
			}
		}

		for (ll j = 0; j < argN; ++j) {
			ll currentPos = argX.at(j).first;

			if (argX.at(j).second == 1) {
				ll targetPos = (currentPos + 1) % argL;
				ll nextPos = j + 1 < argN ? argX.at(j + 1).first : argX.at(0).first;
				ll nextDir = j + 1 < argN ? argX.at(j + 1).second : argX.at(0).second;
				if (nextPos == targetPos && nextDir == 2) {
					argX.at(j).second = 2;
					if (j + 1 < argN) {
