void solve(int ps, int pf){
    vector < pair < int, int > > res;
    pair < int, int > z;
    for (int i = 1; i <= n; i++){
        if (w[i] == 1) res.pb({(x[i] + tt) % l, 1}); else
        if (w[i] == 2) res.pb({(x[i] - tt % l + l) % l, 2});
        if (i == pf) z = res.back();
    }
    sort(res.begin(), res.end());
    int q = 0;
    while(res[q] != z){
        q++;
    }
    for (int i = 0; i < n; i++){
        ans[(ps + i - 1) % n] = res[(q + i) % n].F;
    }
    for (int i = 0; i < n; i++){
        cout << ans[i] << endl;
    }
}
