        } else {
            v.push_back(((x[i] - t) % l + l) % l);
        }
    }

    sort(v.begin(), v.end());

    xs = x[0];

    for (i = 1; i < n; i++) {
        if (w[i] == 2) {
            z1.push_back(x[i] - xs);
            c1 += z1.back();
            xs = x[i];
        }
    }

    xs = x[0];

    for (i = n - 1; i > 0; i--) {
        if (w[i] == 1) {
            z2.push_back((xs - x[i] + l) % l);
            c2 += z2.back();
            xs = x[i];
        }
    }

    if ((w[0] == 1 && z1.size() == 0) || (w[0] == 2 && z2.size() == 0)) {
        p = 0;
    } else {
        int f = 0;
        long long left = 0, right = 2e9, m = (left + right) / 2, z;

        if (w[0] == 1) {
            z1.push_back(l - (c1 - z1[0]));
            z2.push_back(l - c2);
        } else {
            z1.push_back(l - c1);
            z2.push_back(l - (c2 - z2[0]));
        }

        t *= 2;

        while (right - left > 1) {
            long long sum = 0, x, y;

            if (w[0] == 1) {
                x = (m + 1) / 2;

                sum += z1[0];
                x--;
                sum += x / (z1.size() - 1) * (l - z1[0]);
                x %= z1.size() - 1;
                for (i = 0; i < x; i++) sum += z1[i + 1];

                y = m / 2;

                sum += y / z2.size() * l;
                y %= z2.size();
                for (i = 0; i < y; i++) sum += z2[i];
            } else {
                x = m / 2;

                sum += x / z1.size() * l;
                x %= z1.size();
                for (i = 0; i < x; i++) sum += z1[i];

                y = (m + 1) / 2;

                sum += z2[0];
                y--;
                sum += y / (z2.size() - 1) * (l - z2[0]);
                y %= z2.size() - 1;
                for (i = 0; i < y; i++) sum += z2[i + 1];
            }

            if (sum <= t) {
                left = m;
                m = (left + right) / 2;
            } else {
                right = m;
                m = (left + right) / 2;
            }
        }

        z = x[0] * 2;

        if (w[0] == 1) {
            long long x, y;

            x = (left + 1) / 2;

            if (x > 0) {
                z += z1[0];
                t -= z1[0];
                x--;
                z += x / (z1.size() - 1) * (l - z1[0]);
                t -= x / (z1.size() - 1) * (l - z1[0]);
                x %= z1.size() - 1;
                for (i = 0; i < x; i++) {
                    z += z1[i + 1];
                    t -= z1[i + 1];
                }
            }

            y = left / 2;

            z -= y / z2.size() * l;
            t -= y / z2.size() * l;
            y %= z2.size();
            for (i = 0; i < y; i++) {
                z -= z2[i];
                t -= z2[i];
            }

            if (left % 2 == 0) {
                z += t;
                if (t == 0) f = 1;
            } else {
                z -= t;
            }
        } else {
            long long x, y;

            x = left / 2;

            z += x / z1.size() * l;
            t -= x / z1.size() * l;
            x %= z1.size();
            for (i = 0; i < x; i++) {
                z += z1[i];
                t -= z1[i];
            }

            y = (left + 1) / 2;

            if (y > 0) {
                z -= z2[0];
                t -= z2[0];
                y--;
                z -= y / (z2.size() - 1) * (l - z2[0]);
                t -= y / (z2.size() - 1) * (l - z2[0]);
                y %= z2.size() - 1;
                for (i = 0; i < y; i++) {
                    z -= z2[i + 1];
                    t -= z2[i + 1];
                }
            }

            if (left % 2 == 0) {
                z -= t;
            } else {
                z += t;
                if (t == 0) f = 1;
            }
        }

        z /= 2;
        z = (z % l + l) % l;

        for (i = 0; i < n; i++) {
            if (v[i] == z) {
                if (f == 1) {
                    f--;
                } else {
                    p = i;

                    break;
                }
            }
        }
    }

    for (i = p; i < n; i++) printf("%d\n", v[i]);
    for (i = 0; i < p; i++) printf("%d\n", v[i]);

    return 0;
}

