        gap += (pos > 0 ? pos / L : (pos - L + 1) / L);
        p.push_back(np);
    }
    //cout << gap << endl;
    sort(p.begin(), p.end());
    gap = ((gap%N)+N)%N;
    rep(i, N) {
        cout << p[(i + gap)%N] << endl;
    }
    return 0;
}

