ll getFin(int x){
    ll nr = 0;
    for (int i=1;i<=n;i++) if (d[i] != d[x]) nr++;
    val = nr * (t / l);
    t %= l;
    for (int i=1;i<=n;i++){
        if (i != x && d[i] != d[x]){
            if (abs(v[i] - v[x]) / 2 + 1 <= t) val++;
        }
    }
    if (d[x] == 2) val+=x;
    else val = -val+x;
    val %= n;
    if (val <= 0) val += n;
    return val;
}

ll nxt(int x){
    x++;
    if (x > n) x -= n;
    return x;
}

