int main() {
	int n, l, t;	cin >> n >> l >> t;
	t <<= 1;	l <<= 1;
	t %= l;
	vector<ll> cw, ccw;
	vector<pair<ll, int>> dat;
	rep(i, n) {
		int x, w;	cin >> x >> w;
		x <<= 1;
		if (w == 1)	cw.push_back(-x);
		else	ccw.push_back(x);
		dat.push_back(mp(x, w));
	}
	sort(all(cw));	sort(all(ccw));
	int dir = dat[0].second;
	ll pos = dat[0].first;
	ll cur = 0;
	int cwitr = -1, ccwitr = -1;
	while (cur < t) {
		if (dir == 1) {
			if (ccw.size() == 0) {
				pos = (pos + t - cur + l) % l;
				cur = t;
			}
			else {
				if (ccwitr == -1) {
					ccwitr = upper_bound(all(ccw), (pos + cur) % l) - ccw.begin();
					if (ccwitr == ccw.size())	ccwitr = 0;
				}
				else	ccwitr = (ccwitr + 1) % ccw.size();
				ll opos = (ccw[ccwitr] - cur + l) % l;
				ll dist = (l + opos - pos) % l;
				if (dist > 0 && cur + (dist >> 1) <= t) {
					cur += dist >> 1;
					pos = (pos + (dist >> 1)) % l;
					dir = 2;
				}
				else {
					pos = (pos + t - cur) % l;
					cur = t;
				}
			}
		}
		else {
			if (cw.size() == 0) {
				pos = (pos + l - t + cur) % l;
				cur = t;
			}
			else {
				if (cwitr == -1) {
					cwitr = upper_bound(all(cw), -((pos - cur + l) % l)) - cw.begin();
					if (cwitr == cw.size())	cwitr = 0;
				}
				else	cwitr = (cwitr + 1) % cw.size();
				ll opos = (-cw[cwitr] + cur + l) % l;
				ll dist = (pos - opos + l) % l;
				if (dist > 0 && cur + (dist >> 1) <= t) {
					cur += dist >> 1;
					pos = (pos - (dist >> 1) + l) % l;
					dir = 1;
				}
				else {
					pos = (pos - t + cur + l) % l;
					cur = t;
				}
			}
		}
	}
	vector<pair<ll, int>> after(n);
	rep(i, n)	after[i] = mp((dat[i].first + (dat[i].second == 1 ? 1 : -1) * t + l) % l, -dat[i].second);
