int main() {
    cin.tie(0);
    ios::sync_with_stdio(false);

    ll N, L, T; cin >> N >> L >> T;
    vector<ll> X(N), W(N);
    rep(i, N) cin >> X[i] >> W[i];
    ll w = W[0];
    if(W[0] == 2) {
        rep(i, N) {
            W[i] = W[i] == 1 ? 2 : 1;
            X[i] = L - X[i];
        }
    }
    ll roll = T / L, left = T % L, sum = 0;
    repeat(i, 1, N) {
        if(W[i] != W[0]) {
            sum += roll * 2;
            ll d = (X[i] - X[0] + L) % L;            
            if(left * 2 >= d) sum += 1;
            if(left * 2 - d >= L) sum += 1;
        }
        sum %= N;
    }
    rep(i, N) {
        X[i] += (W[i] == 1 ? left : -left) + L;
        X[i] %= L;        
    }
    if(w == 2) rep(i, N) X[i] = L - X[i];

    ll i = (w == 1 ? sum : N - sum + N) % N; // i番目の蟻が，0番目の蟻の移動先にいる   

    vector<pli> X2(N);
    rep(j, N) X2[j] = make_pair(X[j], j);
    sort(begin(X2), end(X2));

    ll ii = -1; 
    rep(j, N) if(X2[j].second == 0) ii = j;
    assert(ii >= 0);
    ll i2 = (ii - i + N) % N; // 0番目の蟻はi2番目の蟻の移動先にいる

    rep(j, N) {
        cout << X2[(i2 + j) % N].first << endl;
    }    

    return 0;
}

