ll check( ll s ){
  if( s == 0 ){
    hm = 0;
    hh = 0;
    return 0;
  }
  ll migi = ( s + 1 ) / 2 - 1;
  ll hidari = s / 2;
  hm = ( migi / SZ(b) * l + ( l + b[migi%SZ(b)] - a.back() ) % l ) / 2;
  hh = ( hidari / SZ(a) * l + ( l + a.back() - a[(hidari+SZ(a)-1)%SZ(a)] ) % l ) / 2;
  return hm + hh;
}

