  if( lb % 2 == 1 ){
    ll res = t - check( lb );
    assert( res >= 0 );
    ll cur = a.back() + hm - hh;
    cur -= res;
    cur = ( ( cur % l ) + l ) % l;
    pos = lower_bound( ALL(ans) , cur ) - ans.begin();
    assert( 0 <= pos and pos < SZ(ans) );
    assert( ans[pos] == cur );
  } else {
    ll res = t - check( lb );
    assert( res >= 0 );
    ll cur = a.back() + hm - hh;
    cur += res;
    cur = ( ( cur % l ) + l ) % l;
    pos = upper_bound( ALL(ans) , cur ) - ans.begin() - 1;
    assert( 0 <= pos and pos < SZ(ans) );
    assert( ans[pos] == cur );
  }

