        // 現在地がX[i] で T 秒間にどれだけ原点を通るかを出したい
        if(W[i]==1){
            cnt -= ( T - (L-X[i]) )/L;
        }else{
            cnt += (T+L-X[i]-1)/L;
        }
    }
    cnt = ((cnt%N)+N)%N;
    for(int i=0;i<N;i++)cout << tmp[(i+cnt)%N] << endl;
}

