		if (p[i].d == 1 && p[(i + 1) % N].d == 2) {
			Q.push({ (p[(i+1) % N].x - p[i].x + L)%L/2, i });
		}
	}

	ll now = 0;
	while (!Q.empty()) {
		Pll ti = Q.top(); Q.pop(); // time, id

		//cerr << ti << endl;
		if (ti.fs >= T) break;

		p[ti.sc].d = 2;
		p[(ti.sc+1)%N].d = 1;

		ll D = (p[(ti.sc + 1) % N].x - p[ti.sc].x + L)%L;


		//PrtExpN(D);
		p[(ti.sc + 1) % N].x = p[ti.sc].x = (p[ti.sc].x + D/2) % L;

		p[(ti.sc + 1) % N].t = p[ti.sc].t = ti.fs;


		ll pre = (ti.sc - 1 + N) % N;


		if (p[pre].d == 1) {

			p[pre].x += ti.fs - p[pre].t;
			p[pre].x %= L;
			p[pre].t = ti.fs;

			//cerr <<".  "<<pre <<  p[pre] << p[ti.sc].fs << endl;

			Q.push({ (p[ti.sc].fs - p[pre].fs + L) % L / 2 + ti.fs, pre });
		}


		ll nxt = (ti.sc + 1) % N;
		ll nxt2 = (ti.sc + 2) % N;
		if (p[nxt2].d == 2) {
			p[nxt2].x -= ti.fs - p[nxt2].t - L;
			p[nxt2].x %= L;
			p[nxt2].t = ti.fs;

			cerr << "+  " << nxt << p[nxt] << p[nxt2].fs << endl;

			Q.push({ (p[nxt2].fs - p[nxt].fs + L) % L / 2 + ti.fs, nxt });
		}

		//cerr << "------A------" << endl;
		//rep(i, N) cerr << p[i] << endl;
		//cerr << "------B------" << endl;

	}

	rep(i, N) {
		//cerr << p[i] << endl;
		if (p[i].d == 1) {
			p[i].x += T - p[i].t;
			p[i].x %= L;
		}
		if (p[i].d == 2) {
			p[i].x -= T - p[i].t - L;
			p[i].x %= L;
		}
		PINTN(p[i].x/2);
	}


}

