    as[i] = (get<0>(an[i]) + tim) % L;
    if (get<1>(an[i]) == 2) as[i] = (L - tim + get<0>(an[i])) % L;
  }
  sort(as.begin(), as.end());
  int al = 0;
  while (as[al] != ans[num]) al ++;
  for (int i = 1; i < N; i ++) {
    int j = i + al;
    j %= N;
    int k = i + num;
    k %= N;
    ans[k] = as[j];
  }
  for (int i = 0; i < N; i ++) {
    cout << ans[i] << endl;
  }
}

