using namespace std;

typedef long long int INT;

struct ant {
	int number;
	INT x;
	INT w;

	INT only_move(INT L)
	{
		INT tmp = (x + (w == 1 ? 1 : -1));
		if (tmp == -1) tmp = L - 1;
		if (tmp == L) tmp = 0;
		return tmp;
	}

	bool collision(INT L, ant a)
	{
		INT me = only_move(L);
		INT you = a.only_move(L);

		if (me == you) return true;
		else if (me == a.x && x == you) return true;

		return false;
	}

	INT move(INT L, ant a)
	{
		INT me = only_move(L);
		INT you = a.only_move(L);

		if (me == a.x && x == you) me = you;

		return me;
	}
};


int main()
{

	INT N, L, T;
	cin >> N >> L >> T;

	vector<ant> a(N);

	for (int i = 0; i < N; i++)
	{
		cin >> a[i].x >> a[i].w;
		a[i].number = i;
	}

	sort(a.begin(), a.end(), [](const ant &a, const ant &b) { return a.x < b.x; });



	for (int i = 0; i < T; i++) 
	{
		vector<ant> post_a(N);
		for (int j = 0; j < N; j++)
		{
			ant prev = a[j == 0 ? N - 1: (j - 1)];
			ant post = a[(j + 1) % N];
			post_a[j].w = a[j].w;

			INT pos = a[j].only_move(L);
			if (a[j].collision(L, prev))
			{
				pos = a[j].move(L, prev);
				post_a[j].w = (a[j].w == 1 ? 2 : 1);
			}
			else if(a[j].collision(L, post))
			{
				pos = a[j].move(L, post);
				post_a[j].w = (a[j].w == 1 ? 2 : 1);
			}
			post_a[j].x = pos;
		}

		for (int j = 0; j < N; j++)
		{
			a[j].x = post_a[j].x;
			a[j].w = post_a[j].w;
		}
	}

	sort(a.begin(), a.end(), [](const ant &a, const ant &b) { return a.number < b.number; });

	for (int i = 0; i < N; i++)
	{
		cout << a[i].x << endl;
	}

	return 0;
}

