  vector<int> cw_ids;
  vector<ll> ccw;
  vector<int> ccw_ids;
  for(int i=0;i<n;i++){
    ll x; int w; cin >> x >> w;
    if(w == 1){
      cw.push_back(x); cw_ids.push_back(i);
    }
    else {ccw.push_back(x); ccw_ids.push_back(i);}
  }
  vector<ll> final_positions;
  for(ll e : ccw){
    ll eprime = (e - T) % L;
    eprime = (eprime + L) % L;
    final_positions.push_back(eprime);
    if(cw.size() == 0){
      cout << eprime << "\n";
    }
  }
  for(ll e : cw){
    ll eprime = (e + T) % L;
    final_positions.push_back(eprime);
    if(ccw.size() == 0){
      cout << eprime << "\n";
    }
  }
  if(ccw.size() == 0 || cw.size() == 0) {
    //assert(false);
    return 0;
  }
  sort(final_positions.begin(), final_positions.end());
  //that was the easy part.
  int me = cw[0]; // every time I bump into someone, my label increases by 1.
  ll num_bumps = 0;
  for(ll x : ccw){
    int t2 = -1;
    if(x < cw[0]){
      t2 = L - (cw[0] - x);
    }
    else{
      t2 = x - cw[0];
    }
    if(t2 < 2 * T) continue;
    num_bumps += 1 + (2 * T - t2) / L;
  }
  int my_label = (cw_ids[0] + num_bumps) % n;
  ll my_position = (cw[0] + T) % L;
  int ee = upper_bound(final_positions.begin(), final_positions.end(), my_position) - final_positions.begin() - 1;
  assert(final_positions[ee] == my_position);
  for(int l = my_label; ; l = (l + 1) % n, ee = (ee + 1) % n){
    ans[l] = final_positions[ee];
    if((l - (my_label - 1)) % n == 0) break;
  }
  for(int i=0;i<n;i++){
    cout << ans[i] << "\n";
    assert(0 <= ans[i] && ans[i] < L);
  }
}

#include <stdint.h>
#include <stdio.h>
#include <vector>

unsigned readUnsigned() {
    int c;
    do { c = ::getchar_unlocked(); } while (c < '0');
    unsigned result = c - '0';
    while ((c = ::getchar_unlocked()) >= '0') {
        result *= 10;
        result += c - '0';
    }
    return result;
}

void writeUnsignedLn(unsigned x) {
    static const unsigned MAX_DIGITS = 10;
    static const unsigned BUF_SIZE = MAX_DIGITS + 1;
    static char buffer[BUF_SIZE] = {0};
    buffer[BUF_SIZE - 1] = '\n';
    unsigned i = BUF_SIZE - 1;
    do {
        buffer[--i] = x % 10 + '0';
        x /= 10;
    } while (x);
    ::fwrite_unlocked(buffer + i, 1, BUF_SIZE - i, stdout);
}

uint64_t N, L, T;
std::vector<uint64_t> xs, W;

std::vector<unsigned> solve() {
    std::vector<uint64_t> crossings(N);

    struct xid { uint64_t x, id; };
    std::vector<xid> left, right;
    for (unsigned n = 0; n <= 1; ++n) {
        for (unsigned i = 0; i < N; ++i) {
            if (W[i] == 1) {
                right.push_back({xs[i] + n*L, i});
            }
            else {
                left.push_back({xs[i] + n*L, i});
            }
        }
    }

    uint64_t numleft = left.size() / 2;
    uint64_t numright = right.size() / 2;

    for (unsigned i = 0, min = 0, max = 0; i < N; ++i) {
        if (W[i] != 1) {
            continue;
        }
        crossings[i] = (2 * T) / L * numleft;
        uint64_t lo = xs[i];
        uint64_t hi = xs[i] + 2 * T % L;
        for (; min < left.size() && left[min].x < lo; ++min);
        for (; max < left.size() && left[max].x < hi; ++max);
        crossings[i] += max - min;
    }

    for (unsigned i = 0, min = 0, max = 0; i < N; ++i) {
        if (W[i] != 2) {
            continue;
        }
        crossings[i] = (2 * T) / L * numright;
        uint64_t lo = xs[i] + L - 2 * T % L;
        uint64_t hi = xs[i] + L;
        for (; min < right.size() && right[min].x <= lo; ++min);
        for (; max < right.size() && right[max].x <= hi; ++max);
        crossings[i] += max - min;
    }

    std::vector<unsigned> result(N);
    for (unsigned i = 0; i < N; ++i) {
        if (W[i] == 1) {
            unsigned j = (i + crossings[i]) % N;
            unsigned t = (xs[i] + T) % L;
            result[j] = t;
        }
        else {
            unsigned j = (i - crossings[i] % N + N) % N;
            unsigned t = (xs[i] - T%L + L) % L;
            result[j] = t;
        }
    }
    return result;
}

int main() {
    N = readUnsigned();
    L = readUnsigned() * 2;
    T = readUnsigned() * 2;

    xs.resize(N);
    W.resize(N);
    for (unsigned i = 0; i < N; ++i) {
        xs[i] = readUnsigned() * 2;
        W[i] = readUnsigned();
    }

    std::vector<unsigned> result = solve();
    for (unsigned i = 0; i < N; ++i) {
        writeUnsignedLn(result[i] / 2);
    }
}

