i64 n,l,t;

i64 calc_count(i64 a,i64 b){
    i64 d;
    if(a<b) d=b-a;
    else d=l-a+b;
    if(2*t<d) return 0;
    return 1+(2*t-(d+d%2))/l;
}

void solve(){
    cin >> n >> l >> t;
    vector<i64> x(n),w(n);
    rep(i,0,n) cin >> x[i] >> w[i];
