        }
        else{
            ans[i] = (x[i] + l * t - t) % l;
            left[le] = P(x[i], i);
            le++;
        }
    }
    ll ant;
    ll rl;
    t *= 2;
    if(w[0] == 1){
        if(le == 0){
            ant = 0;
            rl = 1;
        }
        else{
            ll nowt = left[0].first - right[0].first + round(le, ri) * l + round(le, ri) * ri / le;
            ll nowl = 0;
            for(ll i = 0; i < round(le, ri) * ri % le; i++){
                nowt += (left[(nowl + 1) % le].first + l - left[nowl].first - 1) % l + 1;
                nowl = (nowl + 1) % le;
            }
            ll nowr = 0;
