#define int long long

int N;
i64 L,T;
vector<i64> X;
vector<i64> W;
vector<i64> Xs;

signed main(){
  cin >> N >> L >> T;
  X.resize(N);
  W.resize(N);
  rep(i,0,N - 1){
    cin >> X[i] >> W[i];
    if(W[i] == 1){
      Xs.push_back((X[i] + T) % L);
    }
    else{
      Xs.push_back((X[i] + L + (-T) % L ) % L);
    }
  }

  i64 zero = Xs.front();

  sort(begin(Xs),end(Xs));

  i64 cou = 0;

  rep(i,1,N - 1){
    if(W[0] != W[i]){
      i64 re = 0;
      if(W[0] == 1){
        re = X[i] - X[0];
      }
      else{
        re = (X[0] + L) - X[i];
      }
      if(re <= T * 2){
        i64 t = T * 2 - re;
        cou++;
        cou += t * 2 / (L);
      }
    }
  }


  if(W[0] == 2){
    cou = N - cou;
  }

  vector<int> ans(N);
  int from = lower_bound(begin(Xs),end(Xs),zero) - begin(Xs);

  rep(i,0,N - 1){
    int index = (from + i) % N;
    ans[(i + cou) % N] = Xs[index];
  }
  for(int an : ans){
    cout << an << endl;
  }
}

#include <cstdio>
#include <algorithm>

typedef long long LL;
const int MN = 100005;

int N, L, T, X[MN], W[MN], Y[MN], Id[MN];
int X1[MN], X2[MN], C1, C2;
int Ans[MN];

inline LL Q1(LL v) {
	LL w = (v % L + L) % L, k = (v - w) / L;
	return std::upper_bound(X1, X1 + C1, w) - X1 + k * C1;
}
inline LL Q2(LL v) {
	LL w = (v % L + L) % L, k = (v - w) / L;
	return std::upper_bound(X2, X2 + C2, w) - X2 + k * C2;
}

int main() {
	scanf("%d%d%d", &N, &L, &T);
	for (int i = 0; i < N; ++i) {
		scanf("%d%d", &X[i], &W[i]);
		if (W[i] == 1) X1[C1++] = X[i];
		if (W[i] == 2) X2[C2++] = X[i];
	}
	for (int i = 0; i < N; ++i) {
		Y[i] = X[i];
		if (W[i] == 1) {
			Y[i] = (Y[i] + T) % L;
			Id[i] = (i + Q2(X[i] + 2ll * T) - Q2(X[i])) % N;
		}
		if (W[i] == 2) {
			Y[i] = (Y[i] - T % L + L) % L;
			Id[i] = ((i - Q1(X[i] - 1) + Q1(X[i] - 2ll * T - 1)) % N + N) % N;
		}
		Ans[Id[i]] = Y[i];
	}
	for (int i = 0; i < N; ++i) printf("%d\n", Ans[i]);
	return 0;
}

#include <iostream>
using namespace std;
long long  L;

class Ant {
	public:
		double pos;
		int    dir;

		void init(double x, int w) {
			pos = x;
			if (w==1) dir = 1;
			else      dir = -1;
		}

		double move(double tt) {
			pos += tt * dir;
			if (pos>L)  pos -= L;
			if (pos<0)  pos += L;
			return pos;
		}

	private:

};


int main() {
	// your code goes here
	long long N, T;
	cin >> N >> L >> T;

	Ant ant[N];

	//蟻の初期化
	for(int i=0; i<N; i++) {
		int X,W;
		cin >> X >> W;
		ant[i].init(X,W);
	}

	//Main routine
	bool loop=true;
	double elapse=0.0;
	double t,tt;

	while(loop) {
		// collision check
		t =1000000;
		int cpos;
		for(int i=0; i<N; i++) {
			int j = (i+1) % N;
			if((ant[i].dir == 1) && (ant[j].dir==-1)) {
				if(ant[j].pos > ant[i].pos) {
					tt = (ant[j].pos - ant[i].pos)/2.0;
				} else {
					tt = (ant[j].pos + L - ant[i].pos)/2.0;
				}
				if (t>tt) {
					t = tt; cpos=i;
				}
			}
		}	
		// 蟻を進める
		if (elapse+t>T) {
			for(int i=0; i<N; i++) ant[i].move(T- elapse);
			loop = false;
		} else {
			elapse += t;
			for(int i=0; i<N; i++) ant[i].move(t);
			// 衝突していたら、進行方向を変える
			for(int i=0; i<N; i++) {
				int j = (i+1) % N;
				if (ant[i].pos == ant[j].pos) {
					ant[i].dir *= -1;
					ant[j].dir *= -1;
				}
			}
		}
	}
	//蟻の位置を出力する
	for(int i=0; i<N; i++) cout << ant[i].pos << endl;

	return 0;
}

