vector< vector<int> > Gra;
vector< bool> visit;
int must;
vector<int> ans;
bool dfs2(int S,int T){
	visit[S] = true;
	if( S==T ){
		return true;
	}
	int size = Gra[S].size();
	bool res = false;
	for(int i=0;i<size;++i){
		int to = Gra[S][i];
		if( visit[to] ) continue;
		res = dfs2(to,T);
		if( res ){
			ans.push_back(to);
			return res;//true
		}
	}
	visit[S] = false;
	return false;
}

bool dfs(int v){
	visit[v] = true;
	int size = Gra[v].size();
	bool res = false;
	int count = 0;
	for(int i=0;i<size;++i){//いける場所がある場合端点になれない
		int to = Gra[v][i];
		if( visit[to] ){
			++count;
			continue;
		}
		res = dfs(to);
		if( res ){
			ans.push_back(v);
			return res;
		}
	}

	if( count != Gra[v].size() ){
		visit[v] = false;
		return false;
	}

	size = Gra[must].size();
	for(int i=0;i<size;++i){
		if( visit[ Gra[must][i] ] == false ){
			visit[v] = false;
			return false;
		}
	}

	ans.push_back(v);
	return true;
}
void solve(){
	int N,M;
	cin >> N >> M;
	Gra = vector< vector<int> >(N);
	for(int i=0;i<M;++i){
		int a,b;
		cin >> a >> b;
		--a;--b;
		Gra[a].push_back(b);
		Gra[b].push_back(a);
	}
	vector<int> leaf;
	vector<pair<int,int> > dim(N);
	for(int i=0;i<N;++i){
		if( Gra[i].size() == 1 ){
			leaf.push_back(i);
		}
		dim[i].first = Gra[i].size();
		dim[i].second = i;
	}
	sort(dim.begin(), dim.end());//次数が小さい順
	if( leaf.size() >= 2 ){
		visit = vector< bool >(N,false);
		dfs2(leaf[0],leaf[1]);
		ans.push_back(leaf[0]);
		int size = ans.size();
		cout << size << endl;
		for(int i=size-1;i>=0;--i){
			cout << ans[i] + 1;
			if( i > 0 ){
				cout << " ";
			}else{
				cout << endl;
			}
		}
	}else{

		for(int i=0;i<N;++i){
			int start = dim[i].second;
			visit = vector< bool >(N,false);
			must = start;
			if( dfs(start) ){
				int size = ans.size();
				cout << size << endl;
				for(int j=0;j<size;++j){
					cout << ans[j]+1;
					if(j+1<size){
						cout << " ";
					}else{
						cout << endl;
					}
				}
				return;
			}
		}
	}
}

