typedef lib::modnum<1000000007> mod_t;

int count(int x, int y, int T, int L)
{
	x *= 2;
	y *= 2;
	auto m = (y - x) / 2;
	auto m2 = 2 * L - m;
	auto v = T / L;
	auto r = T%L;
	if (r > m2)
	{
		return 2 * v + 2;
	}
	else if (r > m)
	{
		return 2 * v + 1;
	}
	else
	{
		return 2 * v;
	}
}
int rcount(int x, int y, int T, int L)
{
	return count(L - y, L - x, T, L);
}

void Main()
{
	int N, L, T, X, W;
