	{
		result.emplace_back((X - (T%L) + L) % L);
	}
	auto start = result.front();
	int h{};
	for (int i = 1; i < N; ++i)
	{
		int x, w;
		std::cin >> x >> w;
		if (w == 1)
		{
			result.emplace_back((x + T) % L);
			if (W == 2)
			{
				h -= rcount(X, x, T, L);
			}
		}
		else
		{
			result.emplace_back((x - (T%L) + L) % L);
			if (W == 1)
			{
				h += count(X, x, T, L);
			}
		}
		h %= N;
		if (h < 0)
		{
			h = (N - h) % N;
		}
	}
	lib::sort(result);
	auto s = lib::lower_bound(result, start);
	for (int i{}; i < N; ++i)
	{
		std::cout << result[(N + i + s - h - 1) % N] << std::endl;
	}
