int main(){
	scanf("%d %d %d", &n, &l, &t);
	for(int i=0; i<n; ++i){
		int s, tmp;
		scanf("%d %d", &s, &tmp);
		x[tmp-1].push_back(P(s, i));
		if(tmp == 1){
			b.push_back(s + t);
		}else{
			b.push_back(s - t);
		}
	}

	for(int i=0; i<n; ++i)
