    if( check( md ) <= t ){
      lb = md;
    } else {
      ub = md;
    }
  }

  vl ans(0);
  REP( i , n ){
    if( y[i] == 1 ){
      ans.pb( ( x[i] + t ) % l );
    } else {
      ans.pb( ( ( x[i] - t ) % l + l ) % l );
    }
  }
  SORT( ans );

  ll pos;
  if( lb % 2 == 1 ){
    ll res = t - check( lb );
    ll cur = a.back() + hm - hh;
    cur -= res;
    cur = ( ( cur % l ) + l ) % l;
    pos = lower_bound( ALL(ans) , cur ) - ans.begin();
    assert( ans[pos] == cur );
  } else {
    ll res = t - check( lb );
    ll cur = a.back() + hm - hh;
    cur += res;
    pos = upper_bound( ALL(ans) , cur ) - ans.begin() - 1;
    assert( ans[pos] == cur );
