ll f(int rr, int ll) {
	if (rr >= ll)
		return rr - ll;
	else
		return rr - ll + l;
}

ll calc(int tektp, int idx, int cnt) {
	deepen(idx == 2);
	debug(mt(tektp, cnt));
	cnt--;
	if (cnt < 0) {
		return 0;
	}
	if (qt[tektp] == qh[tektp]) {
		return inf;
	}
	ll res = 1ll * l * (cnt / (qt[tektp] - qh[tektp]));
	int pos = x[q[tektp][qh[tektp] + cnt % (qt[tektp] - qh[tektp])]];
	if (tektp == 0) {
		res += f(x[idx], pos);
	} else {
		res += f(pos, x[idx]);
	}
	debug(res);
	return res;	
}

