const int N = 1e5 + 10;

int L, t;

int intersect(int x, int y) {
    return (y - x) / 2;
}

const int DIF = 100;

int get_dist(vi & ones, vi & zeros, int mone, int mzero, int mo, int mz) {
    int dist = zeros[(mzero + mz) % SZ(zeros)] + L * ((mzero + mz) / SZ(zeros));
    dist -= ones[(mone + mo) % SZ(ones)] - L * ((mone + mo) / SZ(ones));
    return dist;
}

void solve(vector<pii> pts, vi & ans) {

    vi ones, zeros;
    int n = SZ(pts);


    fori (i, n) {
        if (pts[i].second) {
            ones.push_back(pts[i].first);
        } else {
            zeros.push_back(pts[i].first);
        }
    }

    sort(RALL(ones));
    sort(ALL(zeros));

    if (min(SZ(ones), SZ(zeros)) == 0) {
        fori (i, n) {
            if (pts[i].second) {
                ans[i] = pts[i].first + t;
            }
        }
        return;
    }

    fori (i, n) {
