typedef long long ll;
int N, L, T;
vector<ll> X, W;
vector<int> b1, b2;
int f(int p) {
	int w = W[p];
	int p1, p2;
	if (w == 1) {
		p1 = 0;
		while (b1[p1] != p) ++ p1;
		p2 = -1;
		for (int i = 0; i < (int)b2.size(); ++ i) {
			if (b2[i] > p) {
				p2 = i;
				break;
			}
		}
		if (p2 < 0) p2 = 0;
	} else {
		p2 = 0;
		while (b2[p2] != p) ++ p2;
		p1 = -1;
		for (int i = b1.size()-1; i >= 0; -- i) {
			if (b1[i] < p) {
				p1 = i;
				break;
			}
		}
		if (p1 < 0) p1 = b1.size() - 1;
	}
	int t = 0;
	for (;;) {
		int tt = (X[b2[p2]] - X[b1[p1]] + L) % L;
		if (tt <= t) tt += ((t-tt)/L+1)*L;
		if (tt >= 2*T) break;
		t = tt;
		if (w == 1) {
			w = 2;
			p1 = (p1+b1.size()-1) % b1.size();
		} else {
			w = 1;
			p2 = (p2+1) % b2.size();
		}
	}
	if (w == 1) {
		return (X[b1[p1]] + T) % L;
	} else {
		return ((X[b2[p2]] - T) % L + L) % L;
	}
}
int main() {
	cin >> N >> L >> T;
	X.resize(N);
	W.resize(N);
	for (int i = 0; i < N; ++ i) {
