		(W[i] == 1 ? b1 : b2).push_back(i);
	}
	vector<ll> a(N);
	for (int i = 0; i < N; ++ i) {
		a[i] = X[i] + (W[i] == 1 ? T : -T);
		a[i] %= L;
		if (a[i] < 0) a[i] += L;
	}
	if (b1.size() && b2.size()) {
		sort(a.begin(), a.end());
		auto b = a;
		int x0 = f(0);
