#define FOR(i, start, end) for(int i = (start); i < (end); ++i)
#define REP(i, n) FOR(i, 0, n)
// }}}

// types {{{
using s64 = int64_t;
using u64 = uint64_t;
// }}}

s64 N;
s64 L;
s64 T;
vector<s64> X;
vector<s64> W;

void solve()
{
    vector<s64> ans(N);

    s64 q = 2*T / L;
    s64 r = 2*T % L;

    REP(i, N) {
        s64 pos = (X[i] + (W[i] == 1 ? T : L-T)) % L;

        s64 idx = i;
        idx += q * (N-1);
        idx %= N;
        if(W[i] == 1) {
            // ループを考慮
            if(X[i] + r <= L) {
                auto it = upper_bound(begin(X)+i, end(X), X[i]+r-1);
                idx += distance(begin(X)+i, it) - 1;
            }
            else {
                idx += N - i + 1;
                s64 r2 = (X[i] + r) % L;
                auto it = upper_bound(begin(X), end(X), X[i]+r2-1);
                idx += distance(begin(X), it) - 1;
            }
        }
        else {
            if(X[i] - r >= 0) {
                auto it = upper_bound(begin(X), begin(X)+i, X[i]-r);
                idx -= N - distance(it, begin(X)+i);
            }
            else {
                idx -= N - i;
                s64 r2 = (X[i] + L - r) % L;
                auto it = upper_bound(begin(X), end(X), X[i]-r2);
                idx -= N - distance(it, end(X));
            }
        }
        idx %= N;

        ans[idx] = pos;
    }

    for(s64 pos : ans) {
        cout << pos << "\n";
    }
}

int main()
{
    cin >> N >> L >> T;
    X.resize(N);
    W.resize(N);

    REP(i, N) {
        cin >> X[i] >> W[i];
    }

    solve();

    return 0;
}

