ll get_pos(ll T, ll id) {
    ll cnt = T / L;
    ll tm, delta, dd;
    int act_dir;
    delta = 0;

    id %= n;
    if (id == 0) id = n;

    /*cnt = T / L;
    T %= L;

    id += (n + sum[1] - sum[2]) * cnt;
    id %= n;
    if (id == 0) id = n;*/

    while (!ri.empty()) ri.pop_back();
    while (!le.empty()) le.pop_back();
    while (!rri.empty()) rri.pop_back();
    while (!lle.empty()) lle.pop_back();
    sumle = sumri = 0;

    aux.clear();
    for (i = id + 1; i <= n; i++) if (tp[i] == 2) aux.push_back(x[i] - x[id]);
    for (i = 1; i < id; i++) if (tp[i] == 2) aux.push_back(L - x[id] + x[i]);
    if (aux.size()) {
        ri.pb(aux[0]);
        rri.pb(aux[0]);
        for (i = 1; i < aux.size(); i++) ri.pb(aux[i] - aux[i - 1]), rri.pb(aux[i]);
        sumri = aux.back();
    }

    aux.clear();
    for (i = id - 1; i > 0; i--) if (tp[i] == 1) aux.push_back(x[id] - x[i]);
    for (i = n; i > id; i--) if (tp[i] == 1) aux.push_back(x[id] + L - x[i]);
    if (aux.size()) {
        le.pb(aux[0]);
        lle.pb(aux[0]);
        for (i = 1; i < aux.size(); i++) le.pb(aux[i] - aux[i - 1]), lle.pb(aux[i]);

        sumle = aux.back();
    }

    tm = 2 * T;
    act_dir = tp[id];
    while (tm > 0) {
        if (act_dir == 1) {
            dd = min(tm, ri.front());
            delta += dd;
            tm -= dd;
            ri.pop_front();
            rri.pop_front();
            sumri -= dd;

            if (le.empty())
                le.pb(L), lle.pb(L);
            else
                le.pb(L - sumle), lle.pb(L);

            sumle = L;
        } else {
            dd = min(tm, le.front());
            delta -= dd;
            tm -= dd;
            le.pop_front();
            lle.pop_front();
            sumle -= dd;

            if (ri.empty())
                ri.pb(L), rri.pb(L);
            else
                ri.pb(L - sumri), rri.pb(L);

            sumri = L;
        }

        act_dir ^= 3;
    }

    delta /= 2;
    ll ans = (10LL * L + x[id] + delta) % L;
    return ans;
}

