  for (int i: range(0, N)) {
    std::cin >> X[i] >> D[i];
    D[i] = (D[i] == 1 ? 1 : -1);
    after[i] = { mod(X[i] + D[i] * T, L), i };
  }
  std::sort(after.begin(), after.end());
  int64_t count = 0;
  if (D[0] == 1) {
    for (int i: range(1, N)) {
      if (D[i] == -1) {
        int64_t val = 2 * T - (X[i] - X[0]);
        if (val >= 0) {
          count += val / L + 1;
        }
      }
    }
  }
  else {
    for (int i: range(1, N)) {
      if (D[i] == 1) {
        int64_t val = 2 * T - (L - X[i] + X[0]);
        if (val >= 0) {
          count -= val / L + 1;
        }
      }
    }
  }
  count = mod(count, N);
  int pos = -1;
  for (int i: range(0, N)) {
    if (after[i].second == 0) {
      pos = i;
      break;
