			s%=N;
		}
	}
	else{
		for(auto i:is[0]){
			LL v=2*T-(L+X[0]-X[i]);
			if(v<=0)continue;
			//cerr << i << ": " << v << ", " << (v-1)/L << endl;
			s-=(v-1)/L+1;
			s%=N;
		}
	}
	if(s<0){
		s+=N;
	}
	for(int i=0;i<N;i++){
		if(W[i]==0){
			ps[i]=P((X[i]+T)%L,0);
		}
		else{
			LL v=(X[i]-T)%L;
			if(v<0){
				v+=L;
			}
			ps[i]=P(v,1);
		}
	}
	P t=ps[0];
	sort(ps,ps+N);
	int f=lower_bound(ps,ps+N,t)-ps;
	for(int i=0;i<N;i++){
		int j=(f-s+i+N)%N;
		//cerr << "j " << j << endl;
		cout << ps[j].first << endl;
	}

	return 0;
}

