struct Solver {
  long n, l, t;
  std::vector<std::array<long, 2>> xs;
  Solver() {
    S002 reader;
    reader >= n >= l >= t >n>= xs;
  }
  void solve() {
    std::vector<long> coords;
    for(long i = 0; i < n; ++i) {
      auto x = xs[i];
      long next = -1;
      if( x[1] == 1 ) {
        next = (x[0] + t) % l;
      }
      else if( x[1] == 2 ) {
        next = (x[0] - t + l * 1000000000) % l;
      }
      coords.push_back(next);
    }
    std::sort(coords.begin(), coords.end());
    long count = 0;
    for(long i = 0; i < n; ++i) {
      if( xs[i][0] == 1 ) count += 1;
      else count -= 1;
    }
    long diff = t / l * count;
    for(long i = 0; i < n; ++i) {
      // t % l sec
      long dt = t % l;
      if( xs[i][1] == 1 ) {
        if( (0     - xs[i][0] + 3 * l) % l <= dt and
            ((l-1) - xs[i][0] + 3 * l) % l <= dt     ) {
          diff += 1;
        }
      }
      if( xs[i][1] == 2 ) {
        if( (xs[i][0] - (l-1) + 3 * l) % l <= dt and
            (xs[i][0] - 0     + 3 * l) % l <= dt     ) {
          diff -= 1;
        }
      }
    }
    dumpl(diff);
    for(long i = 0; i < n; ++i) {
      printf("%ld\n", coords[(i+diff+3*l)%n]);
    }
  }    
  ~Solver() { fprintf(stderr, "--end--\n"); }
};


int main() {
  loop std::unique_ptr<Solver>(new Solver())->solve();
  return 0;
}

