    for(int i=0; i<N; i++)
        rmover.push_back(rmover[i]+L);
    for(int i=0; i<N; i++)
        lmover.push_back(lmover[i]+L);


    vector<long long> cross(N);
    for(int i=0; i<N; i++){
        if(XW[i].second == 1){
            long long X0 = XW[i].first;
            long long tmp1 = (2*T/L)*lmover.size();
            long long tmp2 = (2*T)%L;
            long long tmp3 = upper_bound(lmover.begin(), lmover.end(), tmp2+X0) - lower_bound(lmover.begin(), lmover.end(), X0);
            cross[i] = tmp1 + tmp3;
        }else{
            long long X0 = L-1-XW[i].first;
            long long tmp1 = (2*T/L)*rmover.size();
            long long tmp2 = (2*T)%L;
            long long tmp3 = upper_bound(rmover.begin(), rmover.end(), tmp2+X0) - lower_bound(rmover.begin(), rmover.end(), X0);
            cross[i] = tmp1 + tmp3;
        }
    }
    vector<long long> num(N);
    for(int i=0; i<N; i++){
        if(XW[i].second == 1)
            num[i] = (i + cross[i]) % N;
        else
            num[i] = (i - cross[i] + N * T) % N;
    }

    vector<long long> ans(N);
    for(int i=0; i<N; i++){
        if(XW[i].second == 1)
            ans[num[i]] = (XW[i].first + T) % L;
        else
            ans[num[i]] = (XW[i].first - T + L * T) % L;
    }
    for(int i=0; i<N; i++)
        cout << ans[i] << endl;

    return 0;
}

