//T秒後にそれぞれの蟻がいる位置を出力する。X[i] +- Tをソートすれば蟻の位置は確定する。
//すれ違った時、蟻の番号は+1or-1で変化する。
//蟻0が時計回りに進んでいるなら、X[i]-X[0]が基準の距離(d)。もし負になるならLを足す。
//T秒で2Tだけ距離を縮めることができるので、d+k*Lが2Tを超えないようなkが求める答えである。
//d+k*L<=2T , k <= (2T-d)/L

int main() {
    int N, L, T; cin >> N >> L >> T;
    VI X(N, 0), W(N, 0);
    REP(i, N) {
        cin >> X[i] >> W[i];
    }
    int num = 0;
    REP(i, N) {
        if (W[0] != W[i]){
            int d;
            if (W[0] == 1) {
                d = X[i] - X[0];
            } else {
                d = X[0] - X[i];
            }
            if (d < 0) d += L;
            int k = (2*T-d)/L + 1;
            num += k;
        }
    }
    if (W[0] == 1){
        num %= N;
    } else {
        num = (N-(num%N))%N;
    }
    VI Y(N, 0);
    REP(i, N) {
        if (W[i] == 1){
            Y[i] = X[i] + T;
        } else {
            Y[i] = X[i] - T;
        }
        if (Y[i] >= L){
            Y[i] %= L;
        } else if (Y[i] < 0) {
            //-1掛けてMOD取ってからLから引いてMODを取る。
            Y[i] = (L - (- Y[i]) % L) % L;
        }
    }
    sort(ALL(Y));
    //0がnumに居るので、numから順番に出力する。
    REP(i, N) {
        cout << Y[(i+num)%N] << endl;
    }
}

