		if (c[i] == 1) {
			sum += d * l2;
			sum += upper_bound(v2.begin(), v2.end(), a[i] + 2*r) - v2.begin();
			sum -= lower_bound(v2.begin(), v2.end(), a[i]) - v2.begin();
			loc = (a[i] + t) % l;
			id = (i + sum) % n;
		}
		else {
			sum += d * l1;
			sum += upper_bound(v1.begin(), v1.end(), a[i] + 2*r) - v1.begin();
			sum -= lower_bound(v1.begin(), v1.end(), a[i]) - v1.begin();
			loc = ((-a[i] - t) % l + l) % l;
			id = ((i - sum) % n + n) % n;
