}
void Read(LL &x) {
	x = 0; static char c;
	while (c > '9' || c < '0') c = get();
	while (c >= '0' && c <= '9') {
		x = x * 10 + c - '0';
		c = get();
	}
}
LL ep[V], ep1[V], a[V], d[V], N, L, T, S;
int main(void) {
	//freopen("in.txt", "r", stdin);
	Read(N); Read(L); Read(T);
	int i, j;
	for (i = 1; i <= N; i++) {
		Read(a[i]); Read(d[i]);
