using Int = long;

Int n,l,t;
const Int ARI_MAX = 100005;
Int x[ARI_MAX];
Int w[ARI_MAX];

void solve() {
    cin >> n >> l >> t;

    REP(i, n) {
        cin >>x[i] >> w[i];
        w[i] = (w[i] == 2) ? -1 : 1;
    }
    Int crossCnt = 0;
    FOR(i, 1, n){
        if (w[0] != w[i]){
            Int d = (-(x[0] * w[0]) -(x[i] * w[i]) + l) % l;
            if (d <= (2 * t)){
                crossCnt += (2 * t - d) / l + 1;
            }
        }
    }
    Int id = (((crossCnt * w[0]) % n ) + n) % n;
    REP(i, n){
        x[i] = (((x[i] + t * w[i]) % l) + l) % l;
    }
    Int idX = x[0];

    sort(x, x + n);
    Int idXrank;

    if (w[0] == -1) {
        for(idXrank = 0; idXrank < n; idXrank++){
            if (x[idXrank] == idX) break;
        }
    }
    else {
        for(idXrank = n-1; idXrank >= 0; idXrank--) {
            if (x[idXrank] == idX) break;
        }
    }
    REP(i, n){
        cout << x[(i - (id - idXrank) + n) % n] << endl;
    }

    return;
}

