ll n, v[Nmax], d[Nmax], l, t, nr, val, fin[Nmax], fin2[Nmax], fin3[Nmax];

ll getFin(int x){
    ll nr = 0;
    for (int i=1;i<=n;i++) if (d[i] != d[x]) nr++;
    val = nr * (t / l);
    t %= l;
    for (int i=1;i<=n;i++){
        if (i != x && d[i] != d[x]){
            if (abs(v[i] - v[x]) / 2 + 1 <= t) val++;
        }
    }
    if (d[x] == 2) val+=x;
    else val = -val+x;
    val %= n;
    if (val <= 0) val += n;
    return val;
}

int main()
{
    cin >> n >> l >> t;
    for (int i=1;i<=n;i++){
        cin >> v[i] >> d[i];
        d[i] = 3 - d[i];
        if (d[i] != d[1]) nr++;
        fin[i] = (v[i] + (d[i] == 1 ? -1 : 1) * t) % l;
        if (fin[i] < 0) fin[i] += l;
    }

    int p1 = fin[1];
    int p3 = fin[3];
    sort(fin+1,fin+n+1);
    int val = getFin(1);
    int val2 = getFin(3);
    int dif = val2 - val;
    for (int i=1;i<=n;i++){
        if (fin[i] == p1 && fin[(i + dif > n ? i+dif-n : i + dif)]==p3){
            for (int cnt=1,j=i;cnt<=n;cnt++,j = (j == n ? 1 : j+1)){
                fin2[cnt] = fin[j];
            }
            break;
        }
        assert(i!=n);
    }

    for (int cnt = 1,i=val;cnt<=n;cnt++,i = (i==n ? 1 : i+1)){
        fin3[i] = fin2[cnt];
    }
    for (int i=1;i<=n;i++){
        cout << fin3[i] << '\n';
    }

    return 0;
}

