	for(int i = 0; i < n; ++i) x[i] = read<int>(), w[i] = read<int>();
}

inline void solve()
{
	int pos[MAXN + 5];

	int p = 0;
	for(int i = 0; i < n; ++i)
		if(w[i] == 1)
		{
			p += t >= l - x[i];
			p += max(0, t - (l - x[i])) / l;
			pos[i] = (x[i] + t) % l;
		}
		else
		{
			p -= t >= x[i] + 1;
			p -= max(0, t - x[i] + 1) / l;
			pos[i] = ((x[i] - t) % l + l) % l;
		}

	(p += n) %= n;
	sort(pos, pos + n);
	for(int i = p; i < n; ++i) printf("%d\n", pos[i]);
	for(int i = 0; i < p; ++i) printf("%d\n", pos[i]);
	puts("");
}

