        sum[tp[i]]++;
    }

    if (sum[1] == 0 || sum[2] == 0)
        solve_simple();

    ll p1 = get_pos(T, 1);
    ll p2 = get_pos(T, 2);

    for (i = 1; i <= n; i++) {
        ll aux = x[i];
