int main(){
	LL n,m,t;
	int i,j,k;
	LL a,b,c,d;
	vector<P> vp;
	vector<LL> v[2];
	cin>>n>>m>>t;
	vector<LL> v1(n),v2(n),vs(n);
	for(i=0;i<n;i++){
		cin>>a>>b;
		b--;
		vp.push_back(make_pair(a,b));
		v[b].push_back(a);
	}
	int cnt=t/m;
	t%=m;
	for(i=0;i<n;i++){
		a=i;
		if(vp[i].second==0){
			a+=(LL)v[1].size()*cnt;
			a%=n;
		}else{
			a-=(LL)v[0].size()*cnt;
			if(a<0)a+=((-a)/n+1)*n;
			a%=n;
		}
		v1[i]=a;
	}
	for(i=0;i<n;i++){
		if(vp[i].second==0){
			a=vp[i].first+t*2;
			a%=m;
			auto itr=lower_bound(v[1].begin(),v[1].end(),a);
			b=distance(v[1].begin(),itr);
			itr=lower_bound(v[1].begin(),v[1].end(),vp[i].first);
			c=distance(v[1].begin(),itr);
			if(a<vp[i].first)b+=v[1].size();
			d=i+b-c;
		}else{
			a=vp[i].first-t*2;
			if(a<0)a+=((-a)/m+1)*m;
			a%=m;
			auto itr=upper_bound(v[0].begin(),v[0].end(),a);
			b=distance(v[0].begin(),itr);
			itr=lower_bound(v[0].begin(),v[0].end(),vp[i].first);
			c=distance(v[0].begin(),itr);
			if(a>vp[i].first)c+=v[0].size();
			d=i+b-c;
			if(d<0)d+=n;
		}
		d%=n;
		v2[i]=d;

		if(vp[i].second==0){
			a=vp[i].first+t;
			a%=m;
		}else{
			a=vp[i].first-t;
			if(a<0)a+=m;
		}
		vs[d]=a;
	}
	array_show(v2);
	for(i=0;i<n;i++){
		cout<<vs[i]<<endl;
	}
}

