using namespace std;
typedef long long int ll;
typedef pair <int,int> P;

ll X[SIZE];
int W[SIZE];

int main()
{
	int n;
	ll L,T;
	scanf("%d %lld %lld",&n,&L,&T);
	bool up=true;
	for(int i=0;i<n;i++)
	{
		scanf("%lld %d",&X[i],&W[i]);
		if(W[i]!=W[0]) up=false;
	}
	if(up)
	{
		if(W[0]==1)
		{
			for(int i=0;i<n;i++) printf("%lld\n",(X[i]+T)%L);
		}
		else
		{
			for(int i=0;i<n;i++) printf("%lld\n",(X[i]-T%L+L)%L);
		}
		return 0;
	}
	vector <ll> pos;
	for(int i=0;i<n;i++)
	{
		if(W[i]==2) pos.push_back((X[i]-T%L+L)%L);
		else pos.push_back((X[i]+T)%L);
	}
	sort(pos.begin(),pos.end());
	int nm=0;
	for(int i=0;i<n;i++) if(W[i]==1) nm++;
	vector <ll> ans;
	ans.resize(n);
	for(int i=0;i<n;i++)
	{
		if(W[i]==2)
		{
			ll cnt=0;
			for(int j=0;j<n;j++)
			{
				if(W[j]==1)
				{
					ll s=X[i]-2LL*T,t=X[i];
					//[s,t] の中にいくつ入っているか
					s-=X[j],t-=X[j];
					if(s<=0)
					{
						ll pl=(-s+L)/L;
						s+=pl*L,t+=pl*L;
					}
					//printf("* %lld %lld\n",s,t);
					cnt+=t/L-(s-1)/L;
				}
			}
			//printf("%lld\n",cnt);
			cnt%=n;
			int now=i;
			while(cnt>0)
			{
				now--;
				cnt--;
				if(now<0) now+=n;
			}
			//now <-> i
			int st=0;
			for(int j=0;j<pos.size();j++)
			{
				if(pos[j]==(X[i]-T%L+L)%L)
				{
					st=j;
					break;
				}
			}
			for(int j=0;j<n;j++)
			{
				ans[(now+j)%n]=pos[(st+j)%n];
			}
			break;
		}
	}
	for(int i=0;i<n;i++) printf("%lld\n",ans[i]);
	return 0;
}

