signed main() {
	INIT;
	VAR(int, n, l, t);
	VEC_ROW(int, n, x, w);
	std::vector<int> d(n);
	REP(i, n) {
		d[i] = x[i] + t*(w[i] == 1 ? 1 : -1);
		d[i] %= l;
		d[i] += l;
		d[i] %= l;
	}
	std::vector<int> v(d);
	std::sort(ALL(v));
	std::vector<int> ans(n);
	if (w[0] == 1) {
		int pos = 0;
		REP(i, n) {
			if (w[i] == 1) continue;
			if (x[i] - x[0] <= 2 * t) ++pos;
		}
		int tt = d[0];
		int dif;
		REP(i, n) {
			if (v[i] == tt) {
				dif = i;
				break;
			}
		}
		REP(i, n) {
			ans[(pos + i) % n] = v[(dif + i) % n];
		}
	}
	if (w[0] == 2) {
		int pos = 0;
		REP(i, n) {
			if (w[i] == 2) continue;
			if (l - x[i] + x[0] <= 2 * t) --pos;
		}
		pos += n;
		pos %= n;
		int tt = d[0];
		int dif;
		REP(i, n) {
			if (v[i] == tt) {
				dif = i;
				break;
			}
		}
		REP(i, n) {
			ans[(pos + i) % n] = v[(dif + i) % n];
		}
	}
	REP(i, n) {
		OUT(ans[i])BR;
	}
	return 0;
}

#include <bits/stdc++.h>
using i64 = long long;

struct S {
    int x, w, i;
    S(int x, int w, int i) : x(x), w(w), i(i) {}
};

int main() {
    i64 n, l, t;
    std::cin >> n >> l >> t;
    std::vector<S> vs;
    i64 cnt[] { 0, 0, 0 };
    for (int i = 0; i < n; i++) {
        int x, w;
        std::cin >> x >> w;
        vs.emplace_back(x, w, i);
        cnt[w]++;
    }

    const auto f = vs.front();
    i64 bump = t / l * 2 * (f.w == 1 ? cnt[2] : cnt[1]),
        rem = t % l;
    for (int i = 1; i < n; i++) {
        if (f.w == vs[i].w) continue;
        auto dist = f.w == 1 ? vs[i].x - f.x : f.x + l - vs[i].x;
        if (dist < rem * 2 || (f.w == 2 && dist == rem * 2)) bump++;
        if (dist + l < rem * 2 || (f.w == 2 && dist + l == rem * 2)) bump++;
    }

    auto s = f.w == 1 ? bump % n : (n - bump % n) % n;
    std::vector<int> pos;
    for (const auto &e : vs) {
        if (e.w == 1) pos.push_back((e.x + rem) % l);
        else pos.push_back((e.x - rem + l) % l);
    }
    int sp = pos.front();
    std::sort(pos.begin(), pos.end());

    auto m = std::lower_bound(pos.begin(), pos.end(), sp) - pos.begin();
    std::vector<int> ret(n);
    for (int j = 0; j < n; j++) {
        ret[vs[(j + s) % n].i] = pos[(j + m) % n];
    }

    for (auto e : ret) std::cout << e << std::endl;

    return 0;
}

#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
// 端点を間違えないように気をつけること!
#define FOR(i, m, n) for (ll i = (ll)(m); i <= (ll)(n); i++)
#define RFOR(i, m, n) for (ll i = (ll)(m); i >= (ll)(n); i--)
ll amari(ll a, ll b)
{
    if (a >= 0)
    {
        return a % b;
    }
    else
    {
        ll c = (-a) % b;
        return (b - c) % b;
    }
}

int main()
{
    ll N, L, T, t_1, t_2, kijun = 0;
    cin >> N >> L >> T;
    t_1 = (T / L) % N;
    t_2 = T % L;
    ll X[N], W[N];
    vector<ll> Y;
    FOR(i, 0, N - 1)
    {
        cin >> X[i] >> W[i];
        if (W[i] == 1)
        {
            Y.push_back(amari(X[i] + T, L));
            kijun -= t_1;
            if (X[i] + t_2 >= L)
            {
                kijun--;
            }
        }
        else
        {
            Y.push_back(amari(X[i] - T, L));
            kijun += t_1;
            if (X[i] - t_2 < 0)
            {
                kijun++;
            }
        }
    }
    kijun = amari(kijun, N);
    sort(Y.begin(), Y.end());
    FOR(i, 0, N - 1)
    {
        if (i < kijun)
        {
            cout << Y[i + N - kijun] << endl;
        }
        else
        {
            cout << Y[i - kijun] << endl;
        }
    }
}

#include <cstdio>
#include <algorithm>

int main() {
	int N, L, T, X[100000];
	bool W[100000];
	std::scanf("%d %d %d", &N, &L, &T);
	for (int i = 0; i < N; ++i) {
		int w;
		scanf("%d %d", X + i, &w);
		W[i] = w == 1;
	}
	int diff = W[0] ? 1 : L - 1;
	int pos = (X[0] + T * diff) % L;
	int number = 0;
	int n_diff = W[0] ? 1 : N - 1;
	for (int i = 1; i < N; ++i) {
		if (W[0] == W[i]) {
			continue;
		}
		int dist;
		if (W[0]) {
			if (X[0] <= X[i]) {
				dist = X[i] - X[0];
			} else {
				dist = X[i] + L - X[0];
			}
		} else {
			if (X[0] >= X[i]) {
				dist = X[i] - X[0];
			} else {
				dist = X[0] + L - X[i];
			}
		}
		int count = 0;
		count += 2 * T / L;
		count += (2 * T) % L >= dist ? 1 : 0;
		number += (count * n_diff) % N;
	}
	for (int i = 0; i < N; ++i) {
		int diff = W[i] ? 1 : L - 1;
		X[i] = (X[i] + diff * T) % L;
	}
	std::sort(X, X + N);
	int start_p;
	for (int i = 0; i < N; ++i) {
		 if (X[i] == pos) {
			 start_p = (i + L - number) % L;
			 break;
		 }
	}
	for (int i = 0; i < N; ++i) {
		std::printf("%d\n", X[(start_p + i) % N]);
	}
}

