                num += (2 * T - dif) / L + 1;
            }
        } else if (w == 2 && W[i] == 1) {
            ll dif = L - (X[i] - X[0]);
            if (2 * T >= dif) {
                num -= (2 * T - dif) / L + 1;
            }
        }
