//        cerr << ti << " " << net << "\n";
        if(net<L){
            exist ^= true;
            now = mp[list[exist][id[exist]]];
            if(exist) (id[0] += -1+si[0])%=si[0];
            else (id[1] += 1)%=si[1];;
        }else break;
        ti = net;
    }
    ll n = T/L;
    now = ((ll) now*n)%N;
    if(!W[now]){
        for(ll i=0;i<si[0];i++) if(mp[list[0][i]]==now){
            id[0] = i;
            break;
        }
        id[1] = 0;
        for(ll j=0;j<si[1];j++) if(X[now]<list[1][j]){
            id[1] = j;
            break;
        }
        exist = false;
    }else{
        for(ll i=0;i<si[1];i++) if(mp[list[1][i]]==now){
            id[1] = i;
            break;
        }
        id[0] = si[0]-1;
        for(ll j=0;j<si[0];j++){
            if(list[0][j]<X[now]){
                id[0] = j;
            }else break;
        }
        exist = true;
    }
    ti = 0;
    while(true){
        ll net = next_time(list[0][id[0]],list[1][id[1]],ti);
        if(net<(T%L)){
            exist ^= true;
            now = mp[list[exist][id[exist]]];
            if(exist) (id[0] += -1+si[0])%=si[0];
            else (id[1] += 1)%=si[1];;
        }else break;
        ti = net;
    }
    vec<ll> ans(N);
