        ll l = (X[i]+(W[i]? -1:1)*T+(ll) T*L)%L;
        v.push_back(l);
        if(i==now) start = l;
    }
    sort(v.begin(),v.end());
    ll sid = 0;
    for(ll i=0;i<N;i++) if(v[i]==start){
        sid = i;
        if(!W[now]) break;
    }
    for(ll i=0;i<N;i++) cout << v[(sid+i)%N]/2 << "\n";
}

