    if(w[i] == 1){
      temp += t;
      temp %= l;
    }else{
      temp -= t%l;
      if(temp < 0){
        temp += l;
      }
      temp %= l;
    }
    pos.push_back(temp);
  }

  bool clockwise = false;
  int pivot = 0;
  int cnt = 0;
  REP(i,n){
