      temp = 2*t-(l-(x[i]-x[0]));
      if(temp <= 0)continue;
      cnt += 1 + temp/l;
    }
    if(clockwise){
      pivot += cnt;
      pivot %= n;
    }else{
      pivot += n;
      pivot -= cnt%n;
      pivot %= n;
    }
  }

