/*
アリとラベルを別に考える。
アリ同士がぶつかる際に、すり抜けてラベルだけ交換するとしても同じ
アリ0がA回ぶつかったらラベルは
	アリ0が右回りなら：(0+A)%n
	アリ0が左回りなら：(0-A)%n
ラベルの順序は変わらないので、アリ0が何回ぶつかるかをカウントすれば全てのアリのラベルと位置が分かる

速度を半分にして時間を倍にすると端数が出なくて計算しやすい
*/

ll n,l,t,x[100010],w[100010],hit=0,zero_id,ans[100010];
mp pos_ans_beforeID[100010];

int main(void){
	cin>>n>>l>>t;
	rep(i,n)cin>>x[i]>>w[i];
	rep(i,n){
		//アリ0がアリiとぶつかる回数をカウント
		if(w[0]==1 && w[i]==2){//回転方向によってカウント方法が変わる
			if(2*t-(x[i]-x[0])>=0){
				hit++;
				hit+=(2*t-(x[i]-x[0]))/l;
			}
		}
		if(w[0]==2 && w[i]==1){
			if(2*t-(l-(x[i]-x[0]))>=0){
				hit++;
				hit+=(2*t-(l-(x[i]-x[0])))/l;
			}
		}
	}
	rep(i,n){
		if(w[i]==1){
			x[i]=(x[i]+t)%l;
		}else{
			x[i]=((x[i]-t)%l+l)%l;
		}
		pos_ans_beforeID[i]={x[i],i};//アリ0がどこに行ったか調べるため
	}
	sort(pos_ans_beforeID,pos_ans_beforeID+n);
	//アリ0がどこに行ったか調べる
	rep(i,n){
		if(pos_ans_beforeID[i].second==0){
			zero_id=pos_ans_beforeID[i].second;//ここがアリ0で、ラベルはhit%nになっている
			break;
		}
	}
	rep(i,n){
		int after_id;
		if(w[0]==1){//進む方向によってアリ0のラベルの値が変わるので
			after_id = ((pos_ans_beforeID[i].second-zero_id+hit)%n+n)%n;
		}else{
			after_id = ((pos_ans_beforeID[i].second-zero_id-hit)%n+n)%n;
		}
		ans[after_id] = pos_ans_beforeID[i].first;
	}
	rep(i,n)cout<<ans[i]<<endl;
	return 0;
}

