        ll col_n = 0;
        for (int i = 1; i < N; ++i) {
            if(W[0] != W[i]){
                ll tcol = -W[0] * V[0] - W[i] * V[i];
                tcol = (tcol + L) % L;
                if (tcol <= 2*T){
                    ll tm = 2*T - tcol;
                    tcol = 1 + tm / L;
                }
                else tcol = 0;
                col_n += tcol;
            }
        }
        ll num0 = (W[0] * col_n);
        num0 = (num0 + 1000000ll*N) % N;
        ll ls0 = (V[0] + W[0] * T + 1000000000*L) % L;
        vector<ll> last;
        last.push_back(ls0);
        for (int i = 1; i < V.size(); ++i) {
            last.push_back((V[i] + W[i] * T + 1000000000*L) % L);
//            cerr << "last[" << i << "] :" << last.back() << endl;
        }
        sort(last.begin(), last.end());
        vector<ll> ans(N);
        auto pos0l = lower_bound(last.begin(), last.end(), ls0);
//        auto pos0u = upper_bound(last.begin(), last.end(), ls0);
//        if(pos0u - pos0l == 2){
//            if(W[0] == -1){
//                num0++;
//            }
//        }
        for (int i = 0; i < N; ++i) {
            ans[(i+num0) % N] = *pos0l;
            pos0l++;
            if(pos0l == last.end()) pos0l = last.begin();
        }
        for (int i = 0; i < N; ++i) {
            cout << ans.at(i) << '\n';
        }
    }
}

