	return true;
}
int func(int x, int type) {
	if (type == 1) x += t;
	else x -= t;
	return (x % l + l) % l;
}
int main() {
	scanf("%d%d%d", &n, &l, &t);
	for (int i = 1; i <= n; i++)
		scanf("%d%d", &x[i], &type[i]);
	if (all_the_same()) {
		for (int i = 1; i <= n; i++)
			printf("%d\n", func(x[i], type[i]));
		return 0;
	}
	for (int i = 1; i <= n; i++)
		y[i] = func(x[i], type[i]);
	sort(y + 1, y + n + 1);
	if (type[1] == 1) {
		static int tmp[MAXN];
		int tot = 0, last = x[1], rec = 0;
		for (int i = 2; i <= n; i++)
			if (type[i] == 2) {
				tmp[++tot] = x[i] - last;
				rec += tmp[tot];
				last = x[i];
			}
		tmp[++tot] = l - rec;
		int T = t * 2;
		int ans = 1;
		ans += T / l * tot;
		rec = T % l;
		for (int i = 1; rec >= tmp[i]; i++) {
			rec -= tmp[i];
			ans++;
		}
		ans %= n;
		if (ans == 0) ans = n;
		int value = func(x[1], type[1]), start = 0;
		for (int i = 1; i <= n; i++)
			if (y[i] == value && (i == n || y[i + 1] != y[i])) {
				start = i;
				break;
			}
		for (int i = ans, j = 1; j <= n; i = i % n + 1, j++) {
			finalans[i] = y[start];
			start = start % n + 1;
		}
	} else {
		while (true) {
			n = n;
		}
	}
	for (int i = 1; i <= n; i++)
		printf("%d\n", finalans[i]);
}

