int n, l, t, pos[N], dir[N];
vector<int>pos_set;
int shift;
void intersect(int idx) {
	int diff, res;
	if (dir[0] == 1) {
		diff = pos[idx] - pos[0];
		if (dir[idx] == -1) {
			int val = 2 * t - diff;
			if (val >= 0) {
				shift += (1 + val) / l;
				shift %= n;
			}
		}
	}
	else {
		if (dir[idx] == 1) {
			diff = l - pos[idx] + pos[0];
			int val = 2 * t - diff;
			res = 1 + val / l;
			if (val >= 0) {
				res %= n;
				shift -= res;
				shift += n;
				shift %= n;
			}
		}
	}
}

