int positive_mod(int a, int b)
{
	if(a >= 0){
        return a%b;
    }
    else{
        return ((-a + b - 1)/b)*b + a;
    }
}

void change_direction(int* X, int* W, int length, int L){

    for(int i=0; i<length-1; i++){
        if(X[i] == X[positive_mod((i+W[i]), length)]){
            W[i] *= -1;
        }
    }

}

bool isNext(int x1, int x2, int L){

    if(abs(x1-x2) == 1 || abs(x1-x2) == L-1){
        return true;
    }
    else{
        return false;
    }

}

void increment(int* X, int* W, int length, int L){

    int preX[length];
    for(int i=0; i<length; i++){
        preX[i] = *(X+i);
    }

    for(int i=0; i<length; i++){
        if(isNext(X[i], preX[positive_mod((i+W[i]), length)], L)){
            W[i] *= -1;
        }
        else{
            X[i] = (X[i] + W[i])%L;
        }
    }

    change_direction(X, W, length, L);

}

