#define int long long

const int N = 1e5 + 100;

int n, l, T, shftsz;
int from[N], dir[N], to[N], ans[N];

void TZL()
{
	scf(n, l, T);
	forn(i, 1, n)
	{
		scf(from[i], dir[i]);
		if(dir[i] == 1)
		{
			to[i] = (from[i] + T) % l;
		}
		else
		{
			to[i] = (from[i] - T % l + l) % l;
		}
	}
	return;
}

deque<int> d1, d0;

int calc(int dst)
{
	dst = (dst % l + l) % l;
	int tbeg = dst;
	int ret = (2 * T - tbeg) / l;
	return ret + 1;
}

void SHIFT()
{
	static int foo[N], bar[N], buf[N];

	if(!dir[1])
		while(!dir[n - shftsz]) ++shftsz;
	else
	{
		shftsz = n;
		int i = 1;
		while(dir[i]) ++i, --shftsz;
	}

	forn(i, 1, n)
	{
		int j = (i + shftsz - 1) % n + 1;
		foo[j] = from[i];
		bar[j] = dir[i];
		buf[j] = to[i];
	}

	MCPY(from, foo); MCPY(dir, bar); MCPY(to, buf);
	nrof(i, n, 1) from[i] -= from[1];
	forn(i, 1, n) if(from[i] < 0) from[i] += l;
	return;
}

void BACK()
{
	if(shftsz) shftsz = (n - shftsz);
	static int foo[N];
	forn(i, 1, n)
	{
		int j = (i + shftsz - 1) % n + 1;
		foo[j] = ans[i];
	}
	MCPY(ans, foo);
	return;
}

void RANK1()
{
	int dlt = -1;
	forn(i, 1, n)
	{
		if(dir[i] == 1){ dlt = from[i]; break; }
	}

	if(!~dlt)
	{
		forn(i, 1, n) printf("%d\n", to[i]);
		return;
	}

	forn(i, 1, n)
	{
		dir[i]--;
	}

	int fst, lst;
	fst = lst = -1;

	forn(i, 1, n) if(dir[i])
	{
		if(!~fst) fst = i;
		lst = i;
	}

	if(!~lst)
	{
		forn(i, 1, n) printf("%d\n", to[i]);
		return;
	}

	SHIFT();

#ifdef DEBUG
	forn(i, 1, n) printf("%d %d\n", from[i], dir[i]);
#endif
	forn(i, 1, n) if(dir[i]) d1.pb(from[i]); else d0.pb(from[i]);

	forn(i, 1, n) if(!dir[i])
	{
#ifdef DEBUG
		printf("dir0\t%d\n", i);
		for(auto x: d1) printf("%d ", x); putchar('\n');
#endif
		while(d1.front() < from[i]) d1.pb(d1.front()), d1.pop_front();

		int foo = calc(d1[0] - from[i]);
		int lb = 0, rb = SZ(d1) - 1;
		while(lb <= rb)
		{
			int mid = lb + rb >> 1;
			if(calc(d1[mid] - from[i]) == foo) lb = mid + 1;
			else rb = mid - 1;
		}

		int jiao = foo * lb + (foo - 1) * (SZ(d1) - lb);
		int dest = (i - 1 + jiao) % n + 1;
		ans[dest] = to[i];
	}

	reverse(ALL(d0));

	nrof(i, n, 1) if(dir[i])
	{
		debug(i, '\n')
		while(d0[0] > from[i]) d0.pb(d0[0]), d0.pop_front();

		int foo = calc(from[i] - d0[0]);
		int lb = 0, rb = SZ(d0) - 1;
		while(lb <= rb)
		{
			int mid = lb + rb >> 1;
			if(calc(from[i] - d0[mid]) == foo) lb = mid + 1;
			else rb = mid - 1;
		}

		int jiao = foo * lb + (foo - 1) * (SZ(d0) - lb);
		int dest = (i - 1 - jiao % n + n) % n + 1;
		ans[dest] = to[i];
	}

	BACK();
	forn(i, 1, n) printf("%d\n", ans[i]);
	return;
}

