bool sum[5];
deque<ll> le, ri;
vector<ll> aux;

void solve_simple() {
    int i;
    ll aux;

    for (i = 1; i <= n; i++) {
        aux = x[i];
        if (tp[i] == 1) aux += T % L;
        else            aux += L - (T % L);

        printf("%lld\n", aux % L);
    }

    exit(0);
}

ll get_pos(ll id) {
    ll cnt = T / L;
    ll tm, delta, dd;
    int act_dir;

    T %= L;

    id += (n + sum[1] - sum[2]) * cnt;
    id %= n;
    if (id == 0) id = n;

    aux.clear();
    for (i = id + 1; i <= n; i++) aux.push_back(x[i] - x[id]);
    for (i = 1; i < id; i++) aux.push_back(L - x[id] + x[i]);
    if (aux.size()) {
        ri.pb(aux[0]);
        for (i = 1; i < aux.size(); i++) ri.pb(aux[i] - aux[i - 1]);
    }

    aux.clear();
    for (i = id - 1; i > 0; i--) aux.push_back(x[id] - x[i]);
    for (i = n; i > id; i--) aux.push_back(x[id] + L - x[i]);
    if (aux.size()) {
        le.pb(aux[0]);
        for (i = 1; i < aux.size(); i++) le.pb(aux[i] - aux[i - 1]);
    }

    le.pb(3LL * T);
    ri.pb(3LL * T);

    tm = 2 * T;
    act_dir = tp[id];
    while (tm > 0) {
        if (act_dir == 1) {
            dd = min(tm, ri.front());
            delta += dd;
            tm -= dd;
            ri.pop_front();
        } else {
            dd = min(tm, le.front());
            delta -= dd;
            tm -= dd;
            le.pop_front();
        }

        act_dir ^= 3;
    }

    delta /= 2;
    ll ans = (10LL * L + x[id] + delta) % L;
    return ans;
}

int main()
{
