    scanf("%lld%lld%lld", &n, &L, &T);
    for (i = 1; i <= n; i++) {
        scanf("%lld%d", &x[i], &tp[i]);
        sum[tp[i]]++;
    }

    if (sum[1] == 0 || sum[2] == 0)
        solve_simple();

    ll p1 = get_pos(1);
    ll p2 = get_pos(2);

    for (i = 1; i <= n; i++) {
        ll aux = x[i];
        if (tp[i] == 1) aux += T % L;
        else            aux += L - (T % L);

        aux %= L;
        x[i] = aux;
    }

    for (i = 1; i + 1 <= n; i++)
        if (x[i] == p1 && x[i + 1] == p2) break;

    for (j = i; j <= n; j++) printf("%lld\n", x[j]);
    for (j = 1; j < i; j++) printf("%lld\n", x[j]);


    return 0;
}

