        ans[i] = {ft, arr[i].se};
        if (i == 0) lol = ans[i];
    }
    int idx = 0;
    if (arr[0].se == 1)
    {
        FOR(j, 1, N)
        {
            if (arr[j].se == 1) continue;
            //count the # these guys intersect.
            int d = arr[j].fi - arr[0].fi;
            int k = max(0, (2 * T - d + L)) / L;
            idx += k;
            idx %= N;
            // cerr << 2 * T - d + L << '/' << L << endl;
            //d/2, (d+L)/2,....(d+(k-1)L)/2
            //(d + (k-1)L) / 2 <= T -> d+(k-1)L <= 2T => (2T - d + L)/L >= k
        }
        // cerr << idx << " intersectons\n";
        sort(ans, ans + N);
        FOR(i, 0, N) if (ans[i] == lol) idx = i - idx;
        if (idx < 0) idx += N;
        //the ith is ant #idx
