void solve(istream& cin) {
    ll N, L, T;
    while(cin >> N >> L >> T){
        vector<ll> V, W;
        for (int i = 0; i < N; ++i) {
            int tmp;
            cin >> tmp;
            V.push_back(tmp);
            cin >> tmp;
            W.push_back(tmp == 1 ? 1 : -1);
        }
        ll col_n = 0;
        for (int i = 1; i < N; ++i) {
            if(W[0] != W[i]){
                ll tcol = -W[0] * V[0] - W[i] * V[i];
                tcol = (tcol + L) % L;
                if (tcol <= 2*T){
                    ll tm = 2*T - tcol;
                    tcol = 1 + tm / L;
                }
                else tcol = 0;
                col_n += tcol;
            }
        }
        ll num0 = (W[0] * col_n);
        num0 = (num0 + 1000000ll*N) % N;
        ll ls0 = (V[0] + W[0] * T + 10000000*L) % L;
        vector<ll> last;
        last.push_back(ls0);
        for (int i = 1; i < V.size(); ++i) {
            last.push_back((V[i] + W[i] * T + 10000000*L) % L);
