        for (int i = 0; i < N; ++i) {
            ans[(i+num0) % N] = *pos0l;
            pos0l++;
            if(pos0l == last.end()) pos0l = last.begin();
        }
        for (int i = 0; i < N; ++i) {
            cout << ans.at(i) << '\n';
        }
    }
}

