inline void init(){
	n=read(); l=read(); t=read();
	for (int i=1;i<=n;i++){
		int x=read(),opt=read();
		if (opt==1){
			int temp=t;
			if (l-x<=temp){
				temp-=(l-x);
				++d; 
				x=0;
			}
			x+=temp; d+=temp/l; x%=l;
		}else{
			int temp=t;
			if (x+1<=temp){
				temp-=(x+1);
				--d; 
				x=l-1;
			}
			x-=temp; d-=temp/l; x%=l;
			if (x<0) x+=l;
		}
