#include <bits/stdc++.h>

using namespace std;

const int MAX_N = 100000, INDEX = 1;

int n;
long long l, t, x[MAX_N + INDEX], w[MAX_N + INDEX], lastChange[MAX_N + INDEX];

struct Bump {
    int ind, t;

    Bump() {
        ind = 0, t = 0;
    }

    Bump(int ind) {
        this->ind = ind;

        this->t = ((x[ind % n + 1] - x[ind] + l) % l - abs(lastChange[ind % n + 1] - lastChange[ind])) / 2 + max(lastChange[ind], lastChange[ind % n + 1]);

        x[ind] += w[ind] * (this->t - lastChange[ind]) % l;

        x[ind] += l;

        x[ind] %= l;

        lastChange[ind] = this->t;

        x[ind % n + 1] += w[ind % n + 1] * (this->t - lastChange[ind % n + 1]) % l;

        x[ind % n + 1] += l;

        x[ind % n + 1] %= l;

        lastChange[ind % n + 1] = this->t;
    }

    friend bool operator < (const Bump& a, const Bump& b) {
        if (a.t < b.t) {
            return true;
        }

        if (a.t > b.t) {
            return false;
        }

        if (a.ind < b.ind) {
            return true;
        }

        if (a.ind > b.ind) {
            return false;
        }

        return false;
    }
};

set<Bump> bumps;

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie();
    cout.tie();

    cin >> n >> l >> t;

    for (int i = 1; i <= n; i++) {
        cin >> x[i] >> w[i];
    }

    l *= 2;
    t *= 2;

    for (int i = 1; i <= n; i++) {
        x[i] *= 2;

        if (w[i] == 2) {
            w[i] = -1;
        }
    }

    for (int i = 1; i <= n; i++) {
        if (w[i] == 1 && w[i % n + 1] == -1) {
            bumps.insert(Bump(i));
        }
    }

//    for (auto b: bumps) {
//        cerr << b.ind << ' ' << b.t << '\n';
//    }

    while (bumps.size() > 0 && (*bumps.begin()).t <= t) {
        Bump b = *bumps.begin();
        bumps.erase(bumps.begin());

//        cerr << b.ind << ' ' << b.t << '\n';

        w[b.ind] *= -1;
        w[b.ind % n + 1] *= -1;

        if (n > 1) {
//            cerr << b.ind << ' ' << b.t << ' ' << w[b.ind] << ' ' << w[(b.ind + n - 2) % n + 1] << '\n';

            if (w[(b.ind + n - 2) % n + 1] == 1) {
                bumps.insert(Bump((b.ind + n - 2) % n + 1));

//                cerr << b.ind << ' ' << b.t << '\n';
            }
        }

        if (n > 2) {
            if (w[(b.ind + 1) % n + 1] == -1) {
                bumps.insert(Bump((b.ind + 1) % n + 1));

//                cerr << b.ind << ' ' << b.t << '\n';
            }
        }
    }

    for (int i = 1; i <= n; i++) {
        x[i] += w[i] * (t - lastChange[i]) % l;

        x[i] += l;

        x[i] %= l;
    }

    for (int i = 1; i <= n; i++) {
        cout << x[i] / 2;

        cout << '\n';
    }

    return 0;
}

