unsigned readUnsigned() {
    int c;
    do { c = ::getchar_unlocked(); } while (c < '0');
    unsigned result = c - '0';
    while ((c = ::getchar_unlocked()) >= '0') {
        result *= 10;
        result += c - '0';
    }
    return result;
}

void writeUnsignedLn(unsigned x) {
    static const unsigned MAX_DIGITS = 10;
    static const unsigned BUF_SIZE = MAX_DIGITS + 1;
    static char buffer[BUF_SIZE] = {0};
    buffer[BUF_SIZE - 1] = '\n';
    unsigned i = BUF_SIZE - 1;
    do {
        buffer[--i] = x % 10 + '0';
        x /= 10;
    } while (x);
    ::fwrite_unlocked(buffer + i, 1, BUF_SIZE - i, stdout);
}

uint64_t N, L, T;
std::vector<uint64_t> xs, W;

std::vector<uint64_t> solve() {
    std::vector<uint64_t> result(N);

    std::vector<uint64_t> left, right;
    for (unsigned i = 0; i < N; ++i) {
        if (W[i] == 1) {
            right.push_back(xs[i]);
        }
        else {
            left.push_back(xs[i]);
        }
    }

    uint64_t fixpoint = 0;
    uint64_t offset = 0;

    if (left.empty() || right.empty()) {
        if (W[fixpoint] == 1) {
            offset = (xs[fixpoint] + T) % L;
        }
        else {
            offset = (xs[fixpoint] + L - T%L) % L;
        }
        goto offset_found;
    }

    for (uint64_t t = 0, pos = xs[fixpoint], w = W[fixpoint];;) {
        if (t == T) {
            offset = pos;
            break;
        }
        ++t;
        if (w == 1) {
            pos = (pos + 1) % L;
        }
        else {
            pos = (pos - 1 + L) % L;
        }

        if (w == 1) {
            uint64_t i = 0;
            uint64_t X = (pos + t) % L;
            for (uint64_t n = left.size(); n; n /= 2) {
                while (i + n < left.size() && left[i + n] < X) i += n;
            }
            if (left[i] < X) {
                ++i;
                if (i >= left.size()) {
                    i = 0;
                }
            }
            uint64_t pos2 = (left[i] + L - t) % L;
            uint64_t dist = (pos2 - pos + L) % L;
            uint64_t t2 = t + dist / 2;
            if (t2 > T) {
                offset = (pos + T - t) % L;
                break;
            }
            t = t2;
            pos = (left[i] + L - t) % L;
            w = 2;
        }
        else {
            uint64_t i = 0;
            uint64_t X = (pos + L - t % L) % L;
            for (uint64_t n = right.size(); n; n /= 2) {
                while (i + n < right.size() && right[i + n] < X) i += n;
            }
            if (i == 0 && right[i] >= X) {
                i = right.size() - 1;
            }
            uint64_t pos2 = (right[i] + t) % L;
            uint64_t dist = (pos - pos2 + L) % L;
            uint64_t t2 = t + (dist + 1) / 2;
            if (t2 > T) {
                offset = (pos + L - (T%L - t)) % L;
                break;
            }
            t = t2;
            pos = (right[i] + t) % L;
            w = 1;
        }
    }

offset_found:

    for (unsigned i = 0; i < xs.size(); ++i) {
        uint64_t t = xs[i];
        if (W[i] == 1) {
            t += T;
        }
        else {
            t += L - T%L;
        }
        t %= L;
        result[i] = t;
    }

    std::sort(result.begin(), result.end(), [offset](uint64_t x, uint64_t y) {
        return x - offset < y - offset;
    });

    return result;
}

void doubleScale() {
    T *= 2;
    L *= 2;
    for (unsigned i = 0; i < N; ++i) {
        xs[i] *= 2;
    }
}

int main() {
    N = readUnsigned();
    L = readUnsigned();
    T = readUnsigned();

    xs.resize(N);
    W.resize(N);
    for (unsigned i = 0; i < N; ++i) {
        xs[i] = readUnsigned();
        W[i] = readUnsigned();
    }

    doubleScale();
    doubleScale();

    std::vector<uint64_t> result = solve();
    for (unsigned i = 0; i < N; ++i) {
        writeUnsignedLn(result[i] / 4);
    }
}

