const int maxn = 100010;
using namespace std;
int N, L, T, X[maxn];

int bSearch(int value, int low, int high, vector<int> b, int t)
{
	int mid, ret = 0;
	while (low <= high)
	{
		mid = (low + high);
		if ( (2 * T - (b[mid] - value)) / L + 1 == t)
		{
			low = mid + 1;
			ret = mid;
		}
		else
			high = mid - 1;
	}
	return ret;
}

vector <int> solve(vector<int> a, vector<int> b, int flag)
{
	int i, j;
	int n = a.size();
	int m = b.size();
	vector<int> ans;
	if (flag)
	{
		for (i = 0; i < n; i ++)
			a[i] = L - a[i];
		reverse(a.begin(), a.end());
		for (i = 0; i < m; i ++)
			b[i] = L - b[i];
		reverse(b.begin(), b.end());
	}
	for (int i = 0; i < m; i ++)
		b.push_back(b[i] + L);
	for (i = j = 0; i < n; i ++)
	{
		for( ; b[j] < a[i]; j ++);
		if (b[j] - a[i] > 2 * T)
		{
			ans.push_back(0);
			continue;
		}
		int t1, t2;
		t1 = (2 * T - (b[j] - a[i])) / L + 1;
		if (b[j + m - 1] - a[i] <= 2 * T)
			t2 = (2 * T - (b[j + m - 1] - a[i])) / L + 1;
		else
			t2 = 0;
		if (t1 == t2)
			ans.push_back((int)((1LL * t1 * m) % N));
		else
		{
			int pivot = bSearch(a[i], j, j + m - 1, b, t1);
			ans.push_back((int)((1LL * (pivot - j) * t1 + 1LL * (j + m - 1 - pivot) * t2) % N));
		}
	}
	return ans;
}
int ans[maxn];
int main()
{
	int i, j, k, n, m, w;
	vector<int> a, b, sa, sb;
	cin >> N >> L >> T;
	for (k = 0; k < N; k ++)
	{
		cin >> X[k] >> w;
		if (w == 1)
			a.push_back(X[k]);
		else
			b.push_back(X[k]);
	}
	sa = solve(a, b, 0);
	sb = solve(b, a, 1);
	n = a.size();
	m = b.size();
	for (k = i = j = 0; k < N; k ++)
		if (i < n && X[k] == a[i])
		{
			ans[(k + sa[i] + N) % N] = (X[k] + T) % L;
			i ++;
		}
		else if (j < m && X[k] == b[j])
		{
			ans[(k - sb[j] + N) % N] = ((X[k] - T) % L + L) % L;	
			j ++;
		}
	for (k = 0; k < N; k ++)
		cout << ans[k] << endl;
	return 0;
}

