typedef lib::modnum<1000000007> mod_t;

lib::dmod count(lib::dmod x, lib::dmod y, lib::dmod T)
{
	x.mod *= 2;
	auto mi = (y - x);
	auto m = mi.val;
	auto m2 = (mi + x.mod).val;
	x.mod /= 2;
	x *= 2;
	y *= 2;
	T *= 2;
	if (T.val >= m2)
	{
		return 2;
	}
	else if (T.val >= m)
	{
		return 1;
	}
	else
	{
		return 0;
	}

}
lib::dmod rcount(lib::dmod x, lib::dmod y, lib::dmod T)
{
	return count(x, 2 * x - y, T);
}

void Main()
{
	std::int64_t N, L, T, X, W;
	std::cin >> N >> L >> T >> X >> W;
	lib::dmod::mod = L;
	std::vector<std::int64_t> result;
	if (W == 1)
	{
		result.emplace_back((X + T) % L);
	}
	else
	{
		result.emplace_back((X - (T%L) + L) % L);
	}
	auto start = result.front();
	lib::dmod h{};
	for (int i = 1; i < N; ++i)
	{
		int x, w;
		std::cin >> x >> w;
		if (w == 1)
		{
			result.emplace_back((x + T) % L);
			if (W == 2)
			{
				h -= rcount(X, x, T) + 2*(T / L);
			}
		}
		else
		{
			result.emplace_back((x - (T%L) + L) % L);
			if (W == 1)
			{
				h += count(X, x, T) + 2 * (T / L);
			}
		}
	}
	lib::sort(result);
	std::int64_t s = lib::lower_bound(result, start);
	for (int i{}; i < N; ++i)
	{
		std::cout << result[(i + s - h).val] << std::endl;
	}
}

