li pos[100100];
li pos2[100100];
li dir[100100];
li n, l, t;

inline li dist(li x, li y) {
    if (dir[x] == 1) {
        if (pos[x] > pos[y]) {
            return l - pos[x] + pos[y];
        } else {
            return pos[y] - pos[x];
        }
    } else {
        if (pos[x] > pos[y]) {
            return pos[x] - pos[y];
        } else {
            return pos[x] + l - pos[y];
        }
    }
}

int main() {
    cin >> n >> l >> t;
    vector<PI> state(n);
    rin{
        cin >> pos[i] >> dir[i];
        if (dir[i] == 2)dir[i] = -1;
    }
    li offset = 0;
    repp(i, 1, n) {
        if (dir[i] != dir[0]) {
            li d = dist(0, i);
            if (d >= t * 2)continue;
            offset++;
            offset += (t * 2 - d - 1) / l;
        }
    }
    if (dir[0] != 1) {
        offset %= n;
    } else {
        // 前の人にゼッケン渡すので、そのぶん相対的に後退する
        offset = -offset + n * 100100;
        offset %= n;
    }

    rin{
        pos2[i] = (pos[i] + t * dir[i] + l * 100100) % l;
    }
    li start_pos = pos2[0];
    //dump(pos, n);
    //dump(pos2, n);
    sort(pos2, pos2 + n);
    li offset2 = n;
    rin{
        if (pos2[i] == start_pos) {
            offset2 = i;
            if (dir[0] < 0 && i < n - 1 && pos2[i + 1] == pos2[i]) {
                offset2 = i + 1;
            }
            break;
        }
    }
    //p2(offset, offset2);
    if (offset2 == n)throw;
    rin{
        cout << pos2[(i + offset + offset2) % n] << endl;
    }



    return 0;
}

