int n,m,t,x[N],w[N],res[N];
vi L,R,nl,nr;

int calc(int i){
	if(w[i]==2) return ((x[i]-t)%m+m)%m;
	return (x[i]+t)%m;
}

int solve(){
//	debuge;
	L.clear();R.clear();
	nl.clear();nr.clear();
	int l=0,r=1e9,k,ret,xl=x[1],xr=-1;
//	debuge;
	for(int i=2;i<=n;i++)
		if(w[i]==w[1]){
			L.pb(x[i]-xl);
			xl=x[i];nl.pb(i);
		}
		else{
			if(~xr) R.pb(x[i]-xr);
			xr=x[i];nr.pb(i);
		}
//	debuge;
	if(w[1]==1){
		k=x[nr[0]]-x[1];
		xl=m;for(auto i:L) xl-=i;
		L.pb(xl);reverse(L.begin(),L.end());
		nl.pb(1);reverse(nl.begin(),nl.end());
		xr=m;for(auto i:R) xr-=i;
		R.pb(xr);
	}
	else{
		k=(x[0]+m-xr);
		xl=m;for(auto i:L) xl-=i;
		L.pb(xl);reverse(nl.begin(),nl.end());
		nl.pb(1);reverse(nl.begin(),nl.end());
		xr=m;for(auto i:R) xr-=i;
		R.pb(xr);reverse(R.begin(),R.end());
		reverse(nr.begin(),nr.end());
	}
//	debuge;
	if(k>t*2) return calc(1);
//	for(auto i:L)printf("%d ",i);puts("");
//	for(auto i:R) printf("%d ",i);puts("");
	ret=nr[0];
	while(l<r){
		int mid=l+r>>1,sl=(mid+1)/2,sr=mid/2;
		ll len=k+m*(sl/L.size()+sr/R.size());
		for(int i=0;i<sl%L.size();i++) len+=L[i];
		for(int i=0;i<sr%R.size();i++) len+=R[i];
		if(len<=t*2){
			l=mid+1;
			if(sl>sr) ret=nl[sl%L.size()]; else ret=nr[sr%R.size()];
		}else r=mid;
	}
	return calc(ret);
}

int main(){
	scanf("%d%d%d",&n,&m,&t);
	for(int i=1;i<=n;i++) scanf("%d%d",&x[i],&w[i]);
	for(int i=1;i<=n;i++)
		res[i]=calc(i);
	sort(res+1,res+n+1);
	bool isok=0;
	for(int i=1;i<=n;i++) if(w[i]!=w[1]) isok=1;
	if(!isok){
		for(int i=1;i<=n;i++) printf("%d\n",res[i]);
		puts("");
		return 0;
	}
	int a1=solve();
//	debug(a1);
	int xx=x[1],ww=w[1];
	for(int i=1;i<n;i++)x[i]=x[i+1],w[i]=w[i+1];
	x[n]=xx;w[n]=ww;
	int p=x[1];
	for(int i=1;i<=n;i++) x[i]=(x[i]-p+m)%m;

	int a2=(solve()+p)%m;
//	debug(a2);
	for(int i=1;i<=n;i++)
		if(res[i]==a1&&res[i%n+1]==a2){
			for(int j=i;j<=n;j++) printf("%d\n",res[j]);
			for(int j=1;j<i;j++) printf("%d\n",res[j]);
			return 0;
		}
	return 0;
}

