int L, t;

int intersect(int x, int y) {
    return (y - x) / 2;
}

const int DIF = 100;

int get_dist(vi & ones, vi & zeros, int mone, int mzero, int mo, int mz) {
    int dist = zeros[(mzero + mz) % SZ(zeros)] + L * ((mzero + mz) / SZ(zeros));
    dist -= ones[(mone - mo % SZ(ones) + SZ(ones)) % SZ(ones)];
    int kek = mo - mone;
    inmax(kek, (int)0);
    kek = (kek + SZ(ones) - 1) / SZ(ones);
    dist += L * kek;
    return dist;
}

void solve(vector<pii> pts, vi & ans) {

    vi ones, zeros;
    int n = SZ(pts);


    fori (i, n) {
        if (pts[i].second) {
            ones.push_back(pts[i].first);
        } else {
            zeros.push_back(pts[i].first);
        }
    }

    sort(ALL(ones));
    sort(ALL(zeros));

    if (min(SZ(ones), SZ(zeros)) == 0) {
        fori (i, n) {
            if (pts[i].second) {
                ans[i] = pts[i].first + t;
            } else {
                ans[i] = pts[i].first - t;
            }
        }
        return;
    }

    fori (i, n) {
        if (pts[i].second) {
            int mone = lower_bound(ALL(ones), pts[i].first) - ones.begin();
            int mzero = lower_bound(ALL(zeros), pts[i].first) - zeros.begin();
            int l = -1, r = L + 10;
            while (r - l > 1) {
                int m = r + l >> 1;
                int dist = get_dist(ones, zeros, mone, mzero, m, m);
                if (dist / 2 <= t) {
                    l = m;
                } else {
                    r = m;
                }
            }
            if (l == -1) {
                ans[i] = pts[i].first + t;
            } else {
                int dist = get_dist(ones, zeros, mone, mzero, l + 1, l);
                if (dist / 2 <= t) {
                    ans[i] = ones[(mone - (l + 1) % SZ(ones)  + SZ(ones)) % SZ(ones)] + t;
                } else {
                    ans[i] = zeros[(mzero + l) % SZ(zeros)] - t;
                }
            }
        }
    }

}

