VI solve(int n, int m, int t)
{
	FOR (i, 0, n)
	{
		int d = t;
		if (D[i] == 1) d = -d;
		RES[i] = A[i] + d;
		RES[i] %= m;
		if (RES[i] < 0) RES[i] += m;
	}

	LL tot = 0;

	int x = A[0];
	FOR (i, 1, n)
	{
		if (D[i] == D[0]) continue;
		int y = A[i];

		int dst = 0;

		if (D[i] == 1) dst = y - x;
		else dst = m - (y - x);

		LL cur = 0;

		int v = 2 * t;

		v -= dst;

		if (v <= 0) continue;
		cur = 1;
		cur += v / m;
		if (v % m == 0) cur--;

		tot += cur;
	}

	tot %= n;

	if (D[0] == 1) tot = n - tot;
	tot %= n;

	int ind = tot;
	int val = RES[0];
	int dir = D[0];

//	cout<<ind<<' '<<val<<' '<<dir<<endl;

	sort(RES, RES + n);

	int wh = -1;

	FOR (i, 0, n)
	{
		if (RES[i] == val)
		{
			if (dir == 1 && i < n && RES[i+1] == val) i++;
			wh = i;
			break;
