  LL num=leftcount*(t/l)+distance(left.begin(),lower_bound(left.begin(),left.begin()+leftcount,t%l))-(rightcount*(t/l)+rightcount-distance(right.begin(),lower_bound(right.begin(),right.begin()+rightcount,l-t%l)));
