  // cout << num << endl;
  vector<LL> pos(n);
  for(int i=0;i<rightcount;i++){
    right[i]=(right[i]+t%l)%l;
    pos[i]=right[i];
  }
  for(int i=0;i<leftcount;i++){
    left[i]=((left[i]-t%l)%l+l)%l;
    pos[i+rightcount]=left[i];
  }
  sort(pos.begin(),pos.end());
  vector<LL> ans(n);
  for(int i=0;i<n;i++){
    ans[((num+i)%n+n)%n]=pos[i];
  }
  for(int i=0;i<n;i++) cout << ans[i] << endl;
  return 0;
}

