#include <iostream>
#include <map>
#include <vector>
#include <algorithm>

class Ant{
public:
    int order;
    int pos, next_pos;
    bool dir, next_dir; // true:clockwise
    int len;
    Ant() {};
    void move (){
        if(dir) next_pos = (pos + 1) % len;
        else if (pos > 0) next_pos = pos - 1;
        else next_pos = len - 1;
        next_dir = dir;
    }
    void invert (){
        if(dir) dir = false;
        else dir = true;
    }
    void invert_stay (){
        if(dir) next_dir = false;
        else next_dir = true;
        next_pos = pos;
    }
    bool collide (bool d, int p){
        if ((d == true && dir == false && dist(p) == 1) || (d == false && dir == true && dist(p) == len - 1)) return true;
        else return false;
    }
    int dist (int p){
        int ret = pos - p;
        if(ret < 0) ret = len + ret;
        return ret;
    }
    void update(){
        pos = next_pos;
        dir = next_dir;
    }
};

int main(int argc, const char * argv[]) {
    // insert code here...
    int N, L, T;
    std::map<int, Ant*> ants;
    std::map<int, Ant*>::iterator iterOut;
    std::map<int, Ant*>::iterator iterIn;
    std::cin >> N >> L >> T;

    for(int id = 0; id < N; id++){
        int this_pos, dir_id;
        bool this_dir = true;
        std::cin >> this_pos >> dir_id;
        if(dir_id == 2) this_dir = false;
        Ant* this_ant = new Ant();
        this_ant->order = id;
        this_ant->pos = this_pos;
        this_ant->dir = this_dir;
        this_ant->len = L;
        ants.insert(std::make_pair(id, this_ant));
    }
    // clock tick loop
    for(int clock = 0; clock < T; clock++){

        //for(int id = 0; id < N; id++){
        for(iterOut = ants.begin(); iterOut != ants.end(); iterOut++){
            bool collide_flag = false;
            for(iterIn = ants.begin(); iterIn != ants.end(); iterIn++){
                if(iterOut->first == iterIn->first) continue;
                if(iterIn->second->pos == iterOut->second->pos) {
                    iterOut->second->invert();
                }
                if(iterOut->second->collide(iterIn->second->dir, iterIn->second->pos)){
                    collide_flag = true;
                    iterOut->second->invert_stay();
                }
            }
            if(!collide_flag) {
                iterOut->second->move();
            }
        }
        for(iterOut = ants.begin(); iterOut != ants.end(); iterOut++){
            iterOut->second->update();
        }
    }
    for(iterOut = ants.begin(); iterOut != ants.end(); iterOut++){
        std::cout << iterOut->second->pos << std::endl;
    }
    return 0;
}

