#define REP(i,st,ed) for(int i=st,i##end=ed;i<=i##end;++i)
#define DREP(i,st,ed) for(int i=st,i##end=ed;i>=i##end;--i)
const int maxn=100005;
struct node{
	int x,dir;
	void input(){
		scanf("%d%d",&x,&dir);
	}
	bool operator < (const node &A) const {
		return x<A.x;
	}
}a[maxn];
long long tag=0;
int n,l,t;
int p[maxn];
int main(){
	scanf("%d%d%d",&n,&l,&t);
	REP(i,1,n)a[i].input();
	REP(i,1,n){
		if(a[i].dir==1){
			p[i]=a[i].x+t;
			tag+=p[i]/l;
			p[i]%=l;
		}else{
			p[i]=a[i].x-t;
			tag-=p[i]/l;
			p[i]%=l;
			if(p[i]<0)p[i]+=l,--tag;
		}
	}
	sort(p+1,p+1+n);
	tag%=n;
	if(tag<0)tag+=n;
	REP(i,1,n)
		printf("%d\n",p[(i+tag-1)%n+1]);
	return 0;
}

