int L, n, t;
long long cnt;
long long coor[MAXN], w[MAXN];

int get(int coor, int w) {
	if (w == 1) {
		return L - coor;
	}
	return coor;
}

int main() {
	ios::sync_with_stdio(0);
	//read(FILENAME);
	cin >> n >> L >> t;
	t *= 2;
	for (int i = 0; i < n; ++i) {
		cin >> coor[i] >> w[i];
	}
	long long d = coor[0];
	for (int i = 0; i < n; ++i) {
		coor[i] = (L + coor[i] - d) % L;
	}
	for (int i = 0; i < n; ++i) {
		if (w[i] != w[0]) {
			long long mt = t;
			if (get(coor[i], w[i]) <= t) {
				mt -= get(coor[i], w[i]);
				++cnt;
				cnt += mt / L;
			}
		}
	}
	cnt %= n;
	for (int i = 0; i < n; ++i) {
		int j = i - cnt;
		if (w[0] == 2) j += cnt * 2;
		j %= n;
		if (j < 0) j += n;
		if (w[j] == 1) {
			long long nc = d + coor[j] + t / 2;
			nc %= L;
			cout << nc << endl;
		} else {
			long long nc = d + coor[j] - t / 2;
			nc %= L;
			if (nc < 0) nc += L;
			cout << nc << endl;
		}
	}
}

