{
  ios_base::sync_with_stdio(false);
  cin.tie(0);
  cout << fixed << setprecision(20);
  INT(n); LL(l); LL(t); l *= 2, t *= 2;
  vector<pair<ll, int>> v(n); rep(i, n)cin >> v[i].FI >> v[i].SE, v[i].FI *= 2;
  vector<ll> ans(n); rep(i, n)ans[i] = v[i].FI + t * (v[i].SE == 1 ? 1: -1);
  rep(i, n)ans[i] = (ans[i] % l + l) % l;
  sort(all(ans));
  t %= l;
  int at = 0;
  if(v[0].SE == 1){
    for(int i = 1; i < n; i++){
      if(v[i].SE == 2){
        if(v[0].FI + t > v[i].FI - t){
          at = i;
        }
      }
    }
    for(int i = 0; i < n; i++){
      if(ans[i] == v[0].FI + t){
        int s = ((i - at) % n + n) % n;
        for(int j = s; j < n; j++)cout << ans[j] / 2 << endl;
        for(int j = 0; j < s; j++)cout << ans[j] / 2 << endl;
        return 0;
      }
    }
  }else{
    for(int i = n - 1; i > 0; i--){
      if(v[i].SE == 1){
        if((v[0].FI + l - v[i].FI) < 2 * t){
          at = i;
        }
      }
    }
    for(int i = n - 1; i >= 0; i--){
      if(ans[i] == ((v[0].FI - t) % l + l) % l){
        int s = ((n - at) + i) % n;
        for(int j = s; j < n; j++)cout << ans[j] / 2 << endl;
        for(int j = 0; j < s; j++)cout << ans[j] / 2 << endl;
        return 0;
      }
    }
  }
  return 0;
}

#include <cstdio>
#include <algorithm>
int N, L, T, p[100001], C = 1;
int main()
{
	scanf("%d%d%d", &N, &L, &T);
	for (int i = 1, x, w; i <= N; i++)
	{
		scanf("%d%d", &x, &w);
		if (w == 1)
		{
			int z = (T + x) / L;
			C = (C + z - 1) % N + 1;
			p[i] = (x + T) % L;
		}
		else
		{
			int z = (T - x - 1 + L) / L;
			C = ((C - z - 1) % N + N) % N + 1;
			p[i] = ((x - T) % L + L) % L;
		}
	}
	std::sort(p + 1, p + N + 1);
	for (int i = C; i <= N; i++)
		printf("%d\n", p[i]);
	for (int i = 1; i < C; i++)
		printf("%d\n", p[i]);
	return 0;
}

