		cin >> X[i] >> W[i];
		if(W[i] == 1){
			v1.push_back(X[i]);
			v1.push_back(X[i] - L);
			v1.push_back(X[i] - L * 2);
		}else{
			v2.push_back(X[i]);
			v2.push_back(X[i] + L);
			v2.push_back(X[i] + L * 2);
		}
