				id1--;
			}
			while(true){
				if(v1[id2] < X[i]){
					break;
				}
				id2--;
			}
			int col = id2 - id1;
			ans[(i - col + N * 2) % N] = (X[i] - T + L) % L;
			//cout << i << " " << col << endl;
		}
	}

	for(int i = 0; i < N; i++){
		cout << ans[i] << endl;
	}

	return 0;
}

