long long get(long long coor, long long w) {
	if (w == 1) {
		return L - coor;
	}
	return coor;
}

int main() {
	ios::sync_with_stdio(0);
	//read(FILENAME);
	cin >> n >> L >> t;
	t *= 2;
	for (int i = 0; i < n; ++i) {
		cin >> coor[i] >> w[i];
	}
	long long d = coor[0];
	for (int i = 0; i < n; ++i) {
		coor[i] = (coor[i] - d) % L;
		while (coor[i] < 0) coor[i] += L;
	}
	for (int i = 0; i < n; ++i) {
		if (w[i] != w[0]) {
			long long mt = t;
			if (get(coor[i], w[i]) <= t) {
				mt -= get(coor[i], w[i]);
				++cnt;
				cnt += mt / L;
				cnt %= n;
			}
		}
	}
	for (int i = 0; i < n; ++i) {
