int n;
ll length,timelimit,first_pos[100000],last_pos[100000];
int dir[100000];

int main() {
	cin.tie(0);
	ios::sync_with_stdio(false);

	cin>>n>>length>>timelimit;
	REP(i,n) cin>>first_pos[i]>>dir[i];

	REP(i,n) {
		if(dir[i]==1) last_pos[i]=(first_pos[i]+timelimit%length)%length;
		else last_pos[i]=(first_pos[i]-timelimit%length+length)%length;
	}

	int round_times=0,rest_times=0;
	FOR(i,1,n) {
		if(dir[0]!=dir[i]) {
			round_times+=2;
			if(dir[0]==1) {
				if(first_pos[i]-first_pos[0]<=timelimit%length*2) rest_times++;
				if(first_pos[i]-first_pos[0]+length<=timelimit%length*2) rest_times++;
			}
			else {
				if(length-first_pos[i]+first_pos[0]<=timelimit%length*2) rest_times++;
				if(length-first_pos[i]+first_pos[0]+length<=timelimit%length*2) rest_times++;
			}
		}
	}
	rest_times%=n;

	int	times=(round_times*(timelimit/length)+rest_times)%n;

	ll zero_pos=last_pos[0];
	sort(last_pos,last_pos+n);
	int idx=lower_bound(last_pos,last_pos+n,zero_pos)-last_pos;

	//cout<<"idx="<<idx<<",zero_pos="<<zero_pos<<endl;

	if(dir[0]==1) idx=(n-times+idx)%n;
	else idx=(n+times+idx)%n;

	//cout<<"idx="<<idx<<",times="<<times<<",round="<<round_times<<",rest="<<rest_times<<endl;

	REP(i,n) cout<<last_pos[(i+idx)%n]<<endl;

	return 0;
}

#include <bits/stdc++.h>
#define int long long
using namespace std;
const int N=1e5+100;
int n,l,t,ans[N],wa,wb;
struct node
{
	int x,w,id;
}a[N];
node b[N],sh[N];
deque <int> s;
signed main()
{
	scanf("%lld%lld%lld",&n,&l,&t);
	for (int i=1;i<=n;i++)
	{
		int x,w;
		scanf("%lld%lld",&x,&w);
		sh[i].x=x,sh[i].w=w;
		if (w==1) a[++wa].x=x,a[wa].w=w,a[wa].id=i;
		else b[++wb].x=x,b[wb].w=w,b[wb].id=i;
	}
	if (wa==0 || wb==0)
	{
		for (int i=1;i<=n;i++) sh[i].id=i;
		for (int i=1;i<=n;i++)
		{
			if (sh[i].w==2) ans[sh[i].id]=(sh[i].x-t+l)%l;
			else ans[sh[i].id]=(sh[i].x+t)%l;
		}
		for (int i=1;i<=n;i++) printf("%lld\n",ans[i]);
		return 0;
	}
	for (int i=1;i<=wb;i++) s.push_back(b[i].x);
	for (int i=1;i<=wa;i++)
	{
		while (s.front()<a[i].x)
		{
			int x=s.front();
			s.pop_front();
			s.push_back(x+l);
		}
		int now=2*t,cnt=0;
		cnt=(now/l)*wb,now%=l;
		cnt+=upper_bound(s.begin(),s.end(),a[i].x+now)-s.begin();
		cnt%=n;
		if (a[i].id+cnt>n) sh[a[i].id].id=a[i].id+cnt-n;
		else sh[a[i].id].id=a[i].id+cnt;
	}
	s.clear();
	for (int i=1;i<=wa;i++) s.push_back(a[i].x);
	for (int i=wb;i>=1;i--)
	{
		while (s.back()>b[i].x)
		{
			int x=s.back();
			s.pop_back();
			s.push_front(x-l);
		}
		int now=2*t,cnt=0;
		cnt=(now/l)*wa,now%=l;
		cnt+=wa-(lower_bound(s.begin(),s.end(),b[i].x-now)-s.begin());
		cnt%=n;
		if (b[i].id-cnt<1) sh[b[i].id].id=n+b[i].id-cnt;
		else sh[b[i].id].id=b[i].id-cnt;
	}
	for (int i=1;i<=n;i++)
	{
		if (sh[i].w==2) ans[sh[i].id]=(sh[i].x-t+l)%l;
		else ans[sh[i].id]=(sh[i].x+t)%l;
	}
	for (int i=1;i<=n;i++) printf("%lld\n",ans[i]);
}

