long long bumps(int i, int j) {
	if (w[i] == 2) {
		swap(i, j);
	}
	long long dst = (x[j] > x[i]) ? (x[j] - x[i]) : (l - x[i] + x[j]);
	long long my_time = l;
	long long result = (t / my_time) * 2;
	my_time = t % my_time;
	//cout << dst << ' ' << my_time << ' ' << x[i] << ' ' << x[j] << endl;
	if ((dst + 1) / 2 <= my_time) {
		my_time -= (dst + 1) / 2;
		++result;
		dst = l - dst % 2;
		if (my_time >= (dst + 1) / 2) {
			++result;
		}
	}
	return result;
}

int go(int pos, int val) {
	long long cnt = 0;
	REP(i, n) {
		if (w[i] != w[pos]) {
			cnt += bumps(pos, i);
			cnt %= n;
		}
	}
	if (w[pos] == 2) {
		return (pos - cnt + n) % n;
	}

	return (pos + cnt) % n;
}

