template<class T> struct edge { int to; T cost;};

bool collision(ll x1,ll w1,ll x2,ll w2,ll T, ll L){
  // 蟻1と2が衝突するか判定
  // 向きが同じなら衝突しない
  if (w1 == w2) return false;
  // 簡単のため、1が時計回り、2が反時計回りに移動するとする
  if (w1 == 2){ swap(x1, x2); swap(w1, w2);}
  // 2が1よりも座標が小さければ一周足しておく
  if (x1 > x2) x2 += L;
  // 移動して、両者が交差する、つまり座標の大小が変化しているなら衝突すると判定する
  x1 += L; x2 -= L;
  if (x1 >= x2) return true;
  else return false;
}

int main() {
  ll N; ll L,T; cin >>N >>L >>T;
  vector<ll> x(N),w(N); rep(i, N) cin >>x[i] >>w[i];
  // 座標自体は衝突を無視して計算すればいい
  // 各々がどの蟻かについては、x[0]の蟻についてT秒で衝突する蟻の個数を求める
  // それをそのまま足すか引くかすればその座標の蟻がどの蟻か決定する
  vector<ll> ant(N);
  // x[0]にいた蟻について調査
  for (ll i=1; i<N; i++){
    if (collision(x[0], w[0], x[i], w[i], T, L)){
      ant[0] += w[0] == 1 ? 1 : -1;
    }
  }
  // 座標を再計算
  for (ll i=0; i<N; i++){
    ll clockwise = w[i] == 1 ? 1 : -1;
    x[i] = (x[i] + T * clockwise + L * 100000000) % L;
  }
  // ant[0] : x[0]の蟻が実際にはどの蟻か
  // たとえば1であれば、蟻0から蟻N-1の座標は各々x[N-1], x[0], x[1], ..., x[N-2] となる
  for (ll i=0; i<N; i++){
    ll X = x[(i + N-ant[0])%N];
    cout <<X <<endl;
  }
}

