            pos[i] = (x - t) % l;
            tmp += (x - t) /l;
            if (pos[i] < 0){
                pos[i] += l;
                tmp--;
            }
        }
    }

    tmp = ((tmp % n) + n) % n;
    sort(pos, pos + n);

    for (int i = tmp; i < n; i++) cout << pos[i] << endl;
    for (int i = 0; i < tmp; i++) cout << pos[i] << endl;

    return 0;
}

