namespace gwlthll
{
	typedef std::pair<int,int> pii;
	const int N=101000,INF=1000000007;
	int sa[N],sb[N];
	pii s[N];
	int n,L,T,na,nb;

	bool cmp(pii A,pii B){return A.x==B.x?A.y<B.y:A.x<B.x;}

	void initialize()
	{
		scanf("%d%d%d",&n,&L,&T),na=nb=0;
		for(int i=1;i<=n;i++)
		{
			scanf("%d%d",&s[i].x,&s[i].y);s[i].y=3-s[i].y*2;
			if(s[i].y==1)sa[++na]=s[i].x;
			else sb[++nb]=s[i].x;
		}
	}
	pii GetTheFirstPosition()
	{
		int pos=s[1].x,k=s[1].y,rt=T;
		while(rt)
		{
//			printf("%d , %d , %d\n",pos,k,rt);
//			getchar();

			int pt=T-rt,dpos=(pos+pt*k%L+L)%L,dis;

//			printf("dpos = %d\n",dpos);

			if(k>0)
			{
				if(!nb)dis=INF;
				else if(dpos>sb[nb])dis=(sb[1]-dpos+L)%L;
				else dis=(*std::lower_bound(sb+1,sb+nb+1,dpos))-dpos;
			}
			else 
			{
				if(!na)dis=INF;
				else if(dpos<sa[1])dis=(dpos-sa[na]+L)%L;
				else dis=dpos-(*(std::upper_bound(sa+1,sa+na+1,dpos)-1));
			}

			int nt=(dis+1)/2,fk=dis/2;

//			printf("dis = %d\n",dis);

			if(rt>=nt)
			{
				pos=(pos+k*fk+L)%L;
				k*=-1;
				rt-=nt;
			}
			else 
			{
				pos=(pos+k*rt+L)%L;
				rt-=rt;
			}
		}
		return pii(pos,k);
	}
	void solve()
	{
		initialize();
		pii A=GetTheFirstPosition();

//		printf("%d %d\n",A.x,A.y);

		for(int i=1;i<=n;i++)
			s[i].x=((s[i].x+T*s[i].y)%L+L)%L;
		std::sort(s+1,s+n+1,cmp);

		int pos=0;
		for(int i=1;i<=n;i++)
			if(s[i]==A){pos=i;break;}

		for(int cnt=n;cnt--;)
		{
			printf("%d\n",s[pos].x);
			pos=pos%n+1;
		}
	}
}

