				if (x <= y) {
					dt = (y - x + 1) / 2;
					dx = (y - x - 1) / 2;
				}
				else {
					dt = (y + L - x + 1) / 2;
					dx = (y + L - x - 1) / 2;
				}
			}
			else {
				dt = L;
				dx = 0;
			}
			if (!is_final && t + dt > r) {
				x_final = x + r - t;
				x_final %= L;
				is_final = true;
			}
			if (t + dt > L) {
				x += L - t;
				x %= L;
				break;
			}
			x += dx;
			x %= L;
			t += dt;
			if (lcnt_end > 0) {
				rcnt++;
				rcnt %= rcnt_end;
				w = 2;
			}
		}
		else {
			if (rcnt_end > 0) {
				y = rX.at(rcnt) + t;
				y %= L;

				if (y <= x) {
					dt = (x - y + 1) / 2;
					dx = -(x - y - 1) / 2;
				}
				else {
					dt = (x + L - y + 1) / 2;
					dx = -(x + L - y - 1) / 2;
				}
			}
			else {
				dt = L;
				dx = 0;
			}
			if (!is_final && t + dt > r) {
				x_final = x - (r - t);
				x_final %= L;
				x_final += L;
				x_final %= L;
				is_final = true;
			}
			if (t + dt > L) {
				x -= L - t;
				x %= L;
				x += L;
				x %= L;
				break;
			}
			x += dx;
			x %= L;
			x += L;
			x %= L;
			t += dt;
			if (lcnt_end > 0) {
				lcnt++;
				lcnt %= lcnt_end;
				w = 1;
			}
		}
	}

	int did;
	for (int i = 0; i < N; i++)
	{
		if (x == X.at(i)) {
			did = i;
			break;
		}
	}

	vector<int> finalx;
	for (int i = 0; i < N; i++)
	{
		int tmpfinalx;
		if (W.at(i) == 1) {
			tmpfinalx = X.at(i) + r;
		}
		else {
			tmpfinalx = X.at(i) - r;
		}
		tmpfinalx %= L;
		tmpfinalx += L;
		tmpfinalx %= L;
		finalx.push_back(tmpfinalx);
	}
	sort(finalx.begin(), finalx.end());

	int did_final;
	for (int i = 0; i < N; i++)
	{
		if (finalx.at(i) == x_final) {
			did_final = i;
			break;
		}
	}
	const int id_final = (q*did + did_final) % N;
	for (int i = id_final; i < N; i++)
	{
		cout << finalx.at(i) << endl;
	}
	for (int i = 0; i < id_final; i++)
	{
		cout << finalx.at(i) << endl;
	}

	return 0;
}

