	vector<ll> las(N);

	cin >> X1 >> W1;
	if (W1 == 1)
		X3 = (X1 + a) % L;
	else
		X3 = (X1 - a + L) % L;
	las[0] = X3;

	for (ll i = 1;i < N;i++) {
		cin >> X >> W;
		//向かってくる奴との距離の差がa未満か否か
		if (W != W1) {
			if (W == 1) { //自分は反時計回り
				d = L - (X - X1);
				if (d <= c) V1++;
			}
			else {
				d = X - X1;
				if (d < c) V1++;
			}
		}
		if (W == 1) las[i] = (X + a) % L;
		else las[i] = (X + L - a) % L;
	}

