        int i, j;
        int n, l, t;
        cin >> n >> l >> t;
        vector<int> x(n), w(n);
        for (i = 0; i < n; i ++) cin >> x[i] >> w[i];
        int cnt = 0;
        for (i = 1; i < n; i ++) {
                if (w[0] + w[i] != 3) continue;
                int dis = (w[0] == 1 ? x[i] - x[0] : l - (x[i] - x[0]));
                int k = t;
                cnt += (int)(k / l) * 2;
                k %= l;
                if ((dis + 1) / 2 <= k) {
                        if (w[0] == 1) cnt = (cnt + 1) % n;
                        else cnt = ((cnt - 1) + n) % n;
                }
                if (dis + (l - dis + 1) / 2 <= k) {
                        if (w[0] == 1) cnt = (cnt + 1) % n;
                        else cnt = ((cnt - 1) + n) % n;
                }
        }
        //cerr << "cnt = " << cnt << endl;
        vector<pair<int, int>> y(n);
        for (i = 0; i < n; i ++) {
                if (w[i] == 1) {
                        y[i].first = (x[i] + t) % l;
                } else {
                        y[i].first = (x[i] - (t % l) + l) % l;
                }
                y[i].second = i;
        }
        //for (i = 0; i < n; i ++) cerr << y[i].first << ' ';
        //cout << endl;
        sort(y.begin(), y.end());
        int p;
        vector<int> ans(n);
        for (i = 0; i < n; i ++) {
                if (y[i].second == 0) {
                        ans[cnt] = y[i].first;
                        p = i;
                        break;
                }
        }
        for (i = 0; i < cnt; i ++) ans[i] = y[(p - cnt + i + n) % n].first;
        for (i = cnt + 1; i < n; i ++) ans[i] = y[(p + i - 1) % n].first;
        for (i = 0; i < n; i ++) cout << ans[i] << endl;
        return 0;
}

