        if (W[0] == 1 && W[i] == 2) {
            counter += (2 * T - (X[i] - X[0]) + 2 * L - 1) / (2 * L);
        }
        else if (W[0] == 2 && W[i] == 1) {
            counter += (2 * T - (L - (X[i] - X[0])) + 2 * L - 1) / (2 * L);
        }
    }
    for (int i = 0; i < N; ++i) {
        if (W[i] == 1) {
            X[i] += T;
            while (X[i] >= L) X[i] -= L;
        }
        else {
            X[i] -= T;
            while (X[i] < 0) X[i] += L;
        }
    }
    long long x = X[0];
    sort(X, X + N);
    long long d;
    for (int i = 0; i < N; ++i) {
        if (X[i] == x) d = i - counter;
    }
    long long ans[N];
    for (int i = 0; i < N; ++i) {
        ans[i] = X[(i + d) % N];
    }

    for (int i = 0; i < N; ++i) cout << ans[i] << endl;

    return 0;
}

