  }
  ll result[N] = {}; result[p0] = pos[0];
  sort(pos,pos+N);
  int p = lower_bound(pos,pos+N,result[p0]) - pos;
  rep(i,N) result[(p0+i)%N] = pos[(p+i)%N];

  rep(i,N) cout << result[i] << endl;
  return 0;
}

