ll compute(ll t, ll l, ll d) {
    ll ans = 2 * (t / l);
    t %= l;
    if (2*t < d) {
        return ans;
    } else if (2*t < d + l) {
        return ans + 1;
    } else {
        return ans + 2;
    }
}

int main() {
    setIO();

