    cin >> N >> L >> T;

    vll X(N);
    vi W(N);

    for (int i=0;i<N;i++) cin >> X[i] >> W[i];

    ll num_coll = 0;
    for (int i=1;i<N;i++) {
        if (W[0] != W[i]) {
            ll d = X[i] - X[0];
            if (W[i] == 2) d = L - d;
            num_coll += compute(T, L, d);
        }
    }

    vpll npos(N);
    for (int i=0;i<N;i++) {
        ll nx = 0;
        if (W[i] == 1) {
            nx = (X[i] + T) % L;
