	dir ^= 1;
	LL res = a[p];
	if (dir == 0) {
		res += t;
		res %= l;
		res -= dist[0];
		if (res < 0) {
			res += l;
		}
	}
	else {
		res += dist[1];
		res %= l;
		res -= t;
		if (res < 0) {
			res += l;
		}
	}
	return res;
}

int goClockWise(int p, int t) {
	return (p + t) % l;
}

int goCounterClockWise(int p, int t) {
	t %= l;
	p -= t;
	if (p < 0) {
		p += l;
	}
	return p;
}
