ll n, v[Nmax], d[Nmax], l, t, nr, val, fin[Nmax], fin2[Nmax], fin3[Nmax];

ll getFin(int x){
    ll nr = 0;
    for (int i=1;i<=n;i++) if (d[i] != d[x]) nr++;
    val = nr * (t / l);
    t %= l;
    for (int i=1;i<=n;i++){
        if (i != x && d[i] != d[x]){
            if (abs(v[i] - v[x]) / 2 + 1 <= t) val++;
        }
    }
    if (d[x] == 2) val+=x;
    else val = -val+x;
    val %= n;
    if (val <= 0) val += n;
    return val;
}

int main()
{
    cin >> n >> l >> t;
    for (int i=1;i<=n;i++){
        cin >> v[i] >> d[i];
        d[i] = 3 - d[i];
        if (d[i] != d[1]) nr++;
        fin[i] = (v[i] + (d[i] == 1 ? -1 : 1) * t) % l;
        if (fin[i] < 0) fin[i] += l;
    }

    int p1 = fin[1];
    int p3 = fin[2];
    // sort(fin+1,fin+n+1);
    int val = getFin(1);
    int val2 = getFin(2);
    int dif = val2 - val;
    for (int i=1;i<=n;i++){
        int nextI = (i + dif > n ? i+dif-n : i + dif); 
        if (fin[i] == p1 && fin[nextI] == p3){
            for (int cnt=1,j=i;cnt<=n;cnt++,j = (j == n ? 1 : j+1)){
                fin2[cnt] = fin[j];
            }
            break;
        }
        assert(i!=n);
    }

    for (int cnt = 1,i=val;cnt<=n;cnt++,i = (i==n ? 1 : i+1)){
        fin3[getFin(cnt)] = fin[cnt];
    }
    for (int i=1;i<=n;i++){
        cout << fin3[i] << '\n';
    }

    return 0;
}

object Main {
  def main(args: Array[String]): Unit = {
    import scala.io.StdIn.readLine
    val Array(n, l, t) = readLine().split(" ").map(_.toInt)
    val ants = (1 to n).map(i => {
      val Array(x, w) = readLine().split(" ").map(_.toInt)
      Ant(i, x * 2, if (w == 1) Positive else Negative)
    })
    f(l, t * 2, ants).foreach(ant => println(ant.x / 2))
  }

  // t, x は実際の２倍
  // ants は x でソート済み
  def f(l: Int, t: Int, ants: IndexedSeq[Ant]): Seq[Ant] = {
    val time = (ants.sliding(2) ++ Some(List(ants.last, ants.head.copy(x = ants.head.x + l * 2))))
      .filter { case Seq(a1, a2) => a1.d == Positive && a2.d == Negative }
      .map { case Seq(a1, a2) => a2.x - a1.x }
      .min

    if (time < t) {
      f(l, t - time, ants.map(_.after(time, l)).sorted)
    } else {
      ants.map(_.after(t, l)).sortBy(_.i)
    }
  }

}


sealed trait Direction

object Positive extends Direction

object Negative extends Direction

case class Ant(i: Int, x: Int, d: Direction) extends Ordered[Ant] {
  def after(t: Int, l: Int): Ant = {
    val nextX = this.x + t
    if (2 * l <= nextX) {
      this.copy(x = nextX - 2 * l)
    } else {
      this.copy(x = nextX)
    }
  }

  override def compare(that: Ant): Int = {
    if (this.x < that.x) {
      -1
    } else if (that.x < this.x) {
      1
    } else {
      if (this.d == that.d) {
        0
      } else if (this.d == Positive) {
        1
      } else {
        -1
      }
    }
  }
}

