const int MAXN = 1e5 + 5;

int N, L, T;
int X[MAXN], D[MAXN];

void input()
{
    read(N); read(L); read(T);
    for (int i = 0; i < N; ++i) {
        read(X[i]); read(D[i]);
    }
}

void solve()
{
    int left = 2 * T % L;
    int cntall = 0, cntlast = 0;
    for (int i = 1; i < N; ++i) {
        if (D[i] != D[0]) {
            cntall += 1;
            if (D[0] == 1)
                cntlast += (X[i] - X[0] < left);
            else
                cntlast += (X[0] + L - X[i] <= left);
        }
    }
    int d = ((LL)(2 * T / L) * cntall + cntlast) % N;
    int id = D[0] == 1 ? d : (N - d) % N;
    // printf("d=%d, id=%d\n", d, id);

    vector<Pii> pos;

    int T0 = T % L;
    for (int i = 0; i < N; ++i) {
        int p = (D[i] == 1 ? (X[i] + T0) % L : (X[i] - T0 + L) % L);
        pos.push_back(MP(p, i));
        // printf("pos(%d)=%d\n", i, pos[i].x);
    }
    std::sort(ALL(pos));
    int st = 20000723;
    for (int i = 0; i < N; ++i) {
        if (pos[i].y == 0)
            st = (id - i + N) % N;
    }

    static int ans[MAXN];

    for (int i = 0; i < N; ++i) {
        ans[(st + i) % N] = pos[i].x;
    }

    for (int i = 0; i < N; ++i) {
        printf("%d\n", ans[i]);
    }

    int ed = st = 20000723;     // forever
}

