#define FILE_NAME "a"

struct ant {
	int x, w;
	int id;

	void read(int ii) {
		id = ii;
		scanf("%d%d", &x, &w);
		--w;
	}

	bool operator < (const ant& other) const {
		return x < other.x;
	}
};

const int MAXN = 1e5 + 10;

int N, L, T;
vector<ant> ants;

bool read() {
	if  (scanf("%d%d%d", &N, &L, &T) < 3) {
		return 0;
	}
	ants.resize(N);
	forn(i, N) {
		ants[i].read(i);
	} 
	return 1;
}

int final[MAXN];

void make_ans() {
	vi finals;
	forn(i, N) {
		ll pos = ants[i].x + (ants[i].w ? -1 : +1) * 1ll * T;
		pos = (pos % L + L) % L;
		finals.pb(pos);
	}

	sort(all(finals));
	int id0 = -1;
	forn(i, N) {
		if  (finals[i] == final[ants[0].id]) {
			id0 = i;
			break;
		}
	}
	assert(id0 != -1);
	for (int i = 1; i < N; ++i) {
		final[ants[i].id] = finals[(id0 + i) % N];
	}
}

void solve1() {
	vi opposite;
	vi my;
	for (int i = 1; i < N; ++i) {
		if  (ants[i].w == 1) {
			opposite.pb(ants[i].x);
		} else {
			my.pb(ants[i].x);
		}
	}

	// forn(i, N) {
	// 	printf("x=%d w=%d\n", ants[i].x, ants[i].w);
	// }

	if  (opposite.empty() || opposite.front() - ants[0].x >= 2 * T) {
		final[ants[0].id] = (ants[0].x + T) % L;
		make_ans();
		return;
	}

	// printf("opposite:\n");
	// for (int x : opposite) {
	// 	printf("%d ", x);
	// }
	// puts("");
	// printf("my:\n");
	// for (int x : my) {
	// 	printf("%d ", x);
	// }
	// puts("");

	int nT = 2 * T;
	int dist = opposite.front() - ants[0].x;
	for (int& x : opposite) {
		x -= dist;
		assert(x >= 0);
	}
	nT -= dist;

	// printf("nT=%d\n", nT);

	vi go;
	if  (!my.empty()) {
		int prv = ants[0].x;
		ford(i, sz(my)) {
			int dist = prv - my[i];
			if  (dist < 0) {
				dist += L;
			}
			go.pb(dist);
			prv = my[i];
		}
		go.pb(my.front() - ants[0].x);
	} else {
		go.pb(L);
	}

	vi stay;
	int prv = opposite.front();
	for (int i = 1; i < sz(opposite); ++i) {
		int dist = opposite[i] - prv;
		stay.pb(dist);
		prv = opposite[i];
	}
	stay.pb(ants[0].x - opposite.back() + L);

	vll pref_go(sz(go) + 1);
	forn(i, sz(go)) {
		pref_go[i + 1] = pref_go[i] + go[i];
	}

	vll pref_stay(sz(stay) + 1);
	forn(i, sz(stay)) {
		pref_stay[i + 1] = pref_stay[i] + stay[i];
	}

	// printf("go:\n");
	// for (int x : go) {
	// 	printf("%d ", x);
	// }
	// puts("");
	// printf("stay:\n");
	// for (int x : stay) {
	// 	printf("%d ", x);
	// }
	// puts("");

	ll Left = -1;
	ll R = nT + 1;
	while (Left != R - 1) {
		ll len = (Left + R) / 2;

		ll cnt_go = (len + 1) / 2;
		ll cnt_stay = len - cnt_go;

		ll was = (cnt_go / sz(go)) * pref_go[sz(go)];
		was += (cnt_stay / sz(stay)) * pref_stay[sz(stay)];
		was += pref_go[cnt_go % sz(go)];
		was += pref_stay[cnt_stay % sz(stay)];

		if  (was <= nT) {
			Left = len;
		} else {
			R = len;
		}
	}

	{
		ll len = Left;
		assert(len >= 0);
		// printf("len=%lld\n", len);
		ll cnt_go = (len + 1) / 2;
		ll cnt_stay = len - cnt_go;

		ll was = (cnt_go / sz(go)) * pref_go[sz(go)];
		was += (cnt_stay / sz(stay)) * pref_stay[sz(stay)];
		was += pref_go[cnt_go % sz(go)];
		was += pref_stay[cnt_stay % sz(stay)];

		// printf("was=%lld\n", was);
		ll dist = (cnt_go / sz(go)) * pref_go[sz(go)] + pref_go[cnt_go % sz(go)];
		if  (~len & 1) {
			dist += nT - was;
		}
		// printf("dist=%lld\n", dist);
		ll pos = ants[0].x - dist;
		// printf("x0=%d, pos=%lld\n", ants[0].x, pos);
		pos = (pos % L + L) % L;
		// printf("pos=%lld, T=%d, L=%d\n", pos, T, L);
		final[ants[0].id] = (pos + T) % L;
		make_ans();
	}
}

void solve() {
	int offset = 0;
	int id = -1;
	forn(i, N) {
		if  (ants[i].w == 0) {
			id = i;
			break;
		}
	}
	if  (id != -1) {
		// ants[id].x + off = 0
		offset = -ants[id].x;
		forn(i, N) {
			ants[i].x += offset;
			ants[i].x = (ants[i].x % L + L) % L;
		}
		vector<ant> nants;
		for (int i = id; i < N; ++i) {
			nants.pb(ants[i]);
		}
		forn(i, id) {
			nants.pb(ants[i]);
		}
		ants.swap(nants);
	}
	solve1();


	forn(i, N) {
		printf("%d\n", (final[i] - offset % L + L) % L);
	}
}

int main() {
#ifdef LOCAL
	freopen(FILE_NAME ".in", "r", stdin);
	// freopen(FILE_NAME ".out", "w", stdout);
#endif

	while (read()) {
		solve();
	}

#ifdef LOCAL
	cerr.precision(5);
	cerr << "Time: " << fixed << (double) clock() / CLOCKS_PER_SEC << endl;
#endif
	return 0;
}

