void swap(int* a, int* b) { int t = *a; *a = *b; *b = t; }

int main() {
	int n, l, t, x[100000], w[100000];
	cin >> n >> l >> t;
	for (int i = 0; i < n; i++) {
		cin >> x[i] >> w[i];
		if (w[i] != 1) w[i] = -1;
	}
	int y[100000], k[100000];
	for (int i = 0; i < n; i++) {
		y[i] = (l + x[i] + t * w[i]) % l;
		k[i] = i;
	}
	vector<pair<int, pair<int, int>>> c;
	for (int i = 0; i < n; i++) {
		for (int j = 0; j < n; j++) {
			if (w[i] == 1 && w[j] == -1) {
				int d = (l + x[j] - x[i]) % l;
				for (; d <= 2 * t; d += l) {
					c.push_back(make_pair(d, make_pair(i, j)));
				}
			}
		}
	}
	sort(begin(c), end(c));
	for (int i = 0; i < c.size(); i++) {
		swap(y + k[c[i].second.first], y + k[c[i].second.second]);
		swap(k + c[i].second.first, k + c[i].second.second);
	}
	for (int i = 0; i < n; i++) {
		cout << y[i] << endl;
	}
	return 0;
}

