#include <bits/stdc++.h>
using namespace std;

typedef long long ll;
typedef long double ld;
typedef pair<ll, ll> ii;
typedef tuple<ll, ll, ll> iii;
typedef vector<ll> vi;
typedef vector<ii> vii;
typedef vector<iii> viii;
typedef vector<vi> vvi;
typedef vector<vii> vvii;
#define REP(i,n) for (ll i = 0; i < n; ++i)
#define REPR(i,n) for (ll i = n-1; i >= 0; --i)
#define FOR(i,m,n) for (ll i = m; i < n; ++i)
#define FORR(i,m,n) for (ll i = n-1; i >= m; --i)
#define FORE(x,xs) for (const auto& x : xs)
#define FORI(i,v) for (auto i = v.begin(); i != v.end(); i++)
#define ALL(v) v.begin(), v.end()
#define CHMIN(x,y) x = min(x, y)
#define CHMAX(x,y) x = max(x, y)

const int MAX = 1e5+10;

ll N, L, T;
ll X[MAX], W[MAX];

ii getPair(int n) {
    ll pos;
    int w = W[n];
    if (w == 1) pos = (X[n] + T) % L;
    else pos = (X[n] - T) % L;
    if (pos < 0) pos += L;

    ll round = T / L, rest = T % L;
    ll idx = n;

    ll countAntiWise = 0;
    REP (i, N) if (W[i] != w) countAntiWise++;
    if (w == 1) (idx += round * 2 * countAntiWise) %= N;
    else (idx -= round * 2 * countAntiWise) %= N;
    if (idx < 0) idx += N;

    REP (i, N) if (w != W[i]) {
        ll dist = 0;
        if (w == 1) dist = (W[i] - w) % N;
        else dist = (w - W[i]) % N;
        if (dist < 0) dist += N;

        if (2 * rest >= dist) {
            if (w == 1) idx++;
            else idx--;
        }
        if (rest >= dist + L) {
            if (w == 1) idx++;
            else idx--;
        }
    }

    idx %= N;
    if (idx < 0) idx += N;

    return ii(idx, pos);
}

vi solve() {
    vi pos(N);
    REP (i, N) {
        if (W[i] == 1) pos[i] = (X[i] + T) % L;
        else pos[i] = (X[i] - T) % L;
        if (pos[i] < 0) pos[i] += L;
    }
    sort(ALL(pos));

    ii p0 = getPair(1), p1 = getPair(2);
    int idx = -1;
    REP (i, N) if (pos[(i+p0.first)%N] == p0.second && pos[(i+p1.first)%N] == p1.second) idx = i;
    if (idx == -1) assert(false);
    vi ret(N);
    REP (i, N) ret[i] = pos[(idx+i)%N];
    return ret;
}

int main() {
    cin >> N >> L >> T;
    REP (i, N) cin >> X[i] >> W[i];
    FORE (x, solve()) cout << x << endl;
}

