const int MAXN = 100005;
const long double eps = 1e-8;

inline int read()
{
	int a = 0, c;
	do c = getchar(); while (!isdigit(c));
	while (isdigit(c)) {
		a = a*10+c-'0';
		c = getchar();
	}
	return a;
}

int n, mod, T;
int x[MAXN], w[MAXN];
int a[MAXN];
pair<int,int> p[MAXN];

int main()
{
	n = read(), mod = read(), T = read();
	int pox = -1, poy = -1, c = 0;
	for (int i = 0; i < n; i++) {
		x[i] = read(), w[i] = read();
		if (w[i] == 1) pox = i, c++;
		else poy = i;
	}
	if (pox == -1) {
		for (int i = 1; i <= n; i++)
			printf("%d\n", ((x[i]-T)%mod+mod)%mod);
	} else if (poy == -1) {
		for (int i = 1; i <= n; i++)
			printf("%d\n", ((x[i]+T)%mod+mod)%mod);
	} else {
		int cnt = pox;
		for (int i = 0; i < n; i++)
			if (w[i] == 2) {
				long double T_first = (i > pox ? (x[i]+x[pox])/2.0 : (1ll*x[i]+mod+x[pox])/2.0)-x[pox];
			        if (T_first > T) continue;
				cnt = (cnt+1+(long long)((T-T_first)/(mod/2.0)+eps))%n;
			}
		for (int i = 0; i < n; i++) {
			if (w[i] == 1)
				p[i] = make_pair((x[i]+T)%mod, i);
			else p[i] = make_pair(((x[i]-T)%mod+mod)%mod, i);
		}
		// cerr << pox << " " << cnt << endl;
		sort(p, p+n);
		int pp = 0;
		for (int i = 0; i < n; i++) {
			// cerr << p[i].first << " ";
			if (p[i].second == pox)
				pp = i;
		}
		// cerr << endl;
		for (int i = pp, c = cnt; i < pp+n; i++, c = (c+1)%n)
			a[c%n] = p[i%n].first;
		for (int i = 0; i < n; i++)
			printf("%d\n", a[i]);
	}
	return 0;
}

