		a[i+ta*2]=a[i]+L*2;
	}
	for (int i=1;i<=tb;i++){
		b[i+tb]=b[i]+L;
		b[i+tb*2]=b[i]+L*2;
	}
	ta*=3;tb*=3;
	for (int i=0,l=1,r=1;i<n;i++)
	if (w[i]==1){
		for (;l<=tb && b[l]<=x[i];l++);
		for (;r<=tb && b[r]<x[i]+q;r++);
		ans[(r-l+p*tb+i)%n]=(x[i]+T)%L;
	}
	for (int i=0,l=1,r=1;i<n;i++)
	if (w[i]==2){
		for (;l<=ta && a[l]<=x[i]-q;l++);
		for (;r<=ta && a[r]<x[i];r++);
		ans[((i-r+l-p*ta)%n+n)%n]=(x[i]-T%L+L)%L;
	}
	for (int i=0;i<n;i++) printf("%d\n",ans[i]);
}

