long X[100009], X1[100009], X2[100009], I1[100009], I2[100009], L;
int W[100009];

inline long fmod(long k) { return (k % L + L) % L; }

signed main() { // long: 64bit
    if(!debug) {
        cin.tie(0);
        ios::sync_with_stdio(0);
    }

    long N, T;
    scanf("%lld%lld%lld",&N,&L,&T);

    int N1 = 0, N2 = 0, F1;
    times(N, i) {
        scanf("%lld%lld",&X[i],&W[i]);
        if(W[i] == 1) {
            I1[N1] = i;
            X1[N1++] = X[i];
        } else {
            I2[N2] = i;
            X2[N2++] = X[i];
        }
    }
    F1 = W[0] == 1;
    if(F1) {
        X1[0] += L;
        reverse(X1+1, X1+N1);
        reverse(I1+1, I1+N1);
    } else {
        reverse(X1, X1+N1);
        reverse(I1, I1+N1);
    }
    if(debug) {
        cout << "X1: "; times(N1, i) cout << X1[i] sp; cout ln;
        cout << "X2: "; times(N2, i) cout << X2[i] sp; cout ln;
    }

    long k;
    if(!N1 || !N2) {
        k = 0;
    } else {
        if(fmod(X2[0] - X1[0]) > T * 2) {
            k = 0;
        } else {
            long l = 0, r = T * 2;
            while(l < r) {
                long m = (l + r) / 2, m1 = (m + F1) / 2, m2 = (m + !F1) / 2;
                long x1 = L * (m1 / N1), x2 = L * (m2 / N2);
                upto(1, m1 % N1, i) x1 += X1[i-1] - X1[i];
                upto(1, m2 % N2, i) x2 += X2[i] - X2[i-1];
                if(debug) {
                    cout << "[m m1 m2]: " << m sp << m1 sp << m2 sp
                         << "[x1 x2 fmod(...)]: " << x1 sp << x2 sp << fmod(X2[0]-X1[0]) ln;
                }
                if(x1 + x2 + fmod(X2[0] - X1[0]) > T * 2) {
                    if(r == m) break;
                    r = m;
                } else {
                    if(l == m) break;
                    l = m;
                }
            }
            if(debug) cout << "l: " << l ln;
            k = l % 2 == F1 ? I1[(l+1) / 2 % N1] : I2[(l+1) / 2 % N2];
        }
    }

    if(debug) cout << "k: " << k ln;

    times(N, i) X[i] = fmod(W[i] == 1 ? X[i] + T : X[i] - T);
    sort(X, X + N);
    times(N, i) printf("%d\n", X[(i - k + N) % N]);

    return 0;
}

