      ant[0].z -= T/L;
      if(L-abs(ant[0].x-a.x) <= 2*(T%L)) --ant[0].z;
      while(ant[0].z < 0) ant[0].z += N;
    }
  }

  for(auto& a: ant) {
    if(a.w==1) {
      a.x += T%L;
      a.x %= L;
    } else {
      a.x -= T%L;
      a.x += L;
      a.x %= L;
    }
  }

  sort(begin(ant), end(ant), [](auto l, auto r) {return l.x!=r.x ? l.x<r.x : l.w>r.w;});

  auto s=0;
  for(auto i=0; i<N; ++i) if(ant[i].z!=-1) s=i;
