void simple(const V<t2> &xwlist, ll n, ll length, ll tm)
{
    tm %= length;

    for (auto xw : xwlist) {
        ll x = get<0>(xw);
        ll w = get<1>(xw);
        if (w == 1) {
            x += tm;
            x %= length;
        }
        else {
            x -= tm;
            while (x < 0) x += length;
        }
        cout << x << endl;
    }
}

