        if(W[i]==1){
            X[i] += T;
        }else{
            X[i] -= T;
        }
    }

    REP(i,N){
        X[i] = (X[i] + L) % L;
    }

    ll undir = 0;
    REP(i,N){
        if(W[i] != W[0])undir++;
    }

