                ll spend = newX[idx] - newX[idx_init];
                if(spend > T * 2){
                    cnt--;
                    goto finish;
                }
            }else{
                ll spend = L - (newX[idx_init] - newX[idx]);
                if(spend > T * 2){
                    cnt--;
