using namespace std;
using ll = long long;

static ll simulate(const vector<ll>& x, const vector<ll>& d, ll len, ll t){
	const int n = x.size();
	queue<ll> q[3];
	for(int i = 0; i < n; ++i){
		if(d[i] == -1){ q[0].push(x[i]); }
	}
	for(int i = n - 1; i >= 0; --i){
		if(d[i] == 1){ q[2].push(x[i] - len); }
	}
	ll y = x[0], dir = -d[0], elapsed = 0;
	while(elapsed < t){
		const ll z = q[1 + dir].front() + elapsed * dir;
		q[1 + dir].push(q[1 + dir].front() + len * -dir);
		q[1 + dir].pop();
		if(z == y){ continue; }
		const ll w = min(t - elapsed, ((z - y) * -dir) / 2);
		y += w * -dir;
		elapsed += w;
		dir *= -1;
	}
	return y;
}

int main(){
	ios_base::sync_with_stdio(false);
	int n;
	ll l, t;
	cin >> n >> l >> t;
	l *= 4;
	t *= 4;
	t += 1;
	vector<ll> x(n), d(n), y(n);
	for(int i = 0; i < n; ++i){
		cin >> x[i] >> d[i];
		x[i] *= 4;
		if(d[i] == 2){ d[i] = -1; }
		y[i] = (x[i] + t * (d[i] + l)) % l;
	}
	sort(y.begin(), y.end());
	const ll cy = simulate(x, d, l, l);
	const ll ry = simulate(x, d, l, t % l);
	int coffset = 0, roffset = 0;
//while(x[coffset] != cy){ ++coffset; }
	coffset = (coffset * (t / l)) % n;
	while(y[roffset] != ry){ ++roffset; }
	for(int i = 0; i < n; ++i){
		cout << (y[(coffset + roffset + i) % n] + 1) / 4 << "\n";
	}
	return 0;
}

