using namespace std;

struct Ant {
  int pos;
  bool dir;
};

int bump_second(int L, const Ant& a, const Ant& b)
{
  int d = (L + b.pos - a.pos) % L;
  return (d + 1) / 2;
}

void move(int L, int time, const Ant& a, Ant& a_)
{
  a_.dir = a.dir;
  a_.pos = (L + a.pos + (a.dir ? time : -time)) % L;
}

void move(int L, int time, const Ant& a, Ant& a_, const Ant& b, Ant& b_)
{
  int d = (L + b.pos - a.pos) % L;
  a_.dir = !a.dir;
  b_.dir = !b.dir;
  if (d == time * 2) {
    a_.pos = b_.pos = (a.pos + time) % L;
  } else {
    a_.pos = (a.pos + time - 1) % L;
    b_.pos = (b.pos - time + 1) % L;
  }
}

int main()
{
  int N, L, T;
  cin >> N >> L >> T;
  vector<Ant> ants(N), tmp(N);

  for (int i = 0; i < N; ++i) {
    int d;
    cin >> ants[i].pos >> d;
    ants[i].dir = d == 1;
  }

  int time = 0;
  while (time < T) {
    int min_time = T - time;
    int min_now = -1;
    for (int now = 0; now < N; ++now) {
      int next = (now + 1) % N;
      if (ants[now].dir and !ants[next].dir) {
        int t = bump_second(L, ants[now], ants[next]);
        if (t <= min_time) {
          min_time = t;
          min_now = now;
        }
      }
    }

    for (int i = 0; i < N;) {
      int now = (min_now + i) % N;
      int next = (now + 1) % N;
      if (ants[now].dir and !ants[next].dir) {
        int t = bump_second(L, ants[now], ants[next]);
        if (t >= min_time) {
          move(L, min_time, ants[now], tmp[now], ants[next], tmp[next]);
          i += 2;
          continue;
        }
      }
      move(L, min_time, ants[now], tmp[now]);
      i += 1;
    }
    swap(ants, tmp);
    time += min_time;
  }
  for (int i = 0; i < ants.size(); ++i) cout << ants[i].pos << endl;
  return 0;
}

