ll n, l, t, x[100000], w[100000], ans[100000];

int main() {
  scanf("%lld%lld%lld", &n, &l, &t);
  for (ll i = 0; i < n; i++) scanf("%lld%lld", &x[i], &w[i]);
  for (ll i = 0; i < n; i++) {
    ans[i] = (x[i] + (w[i] == 1 ? t : -t)) % l;
    if (ans[i] < 0) ans[i] += l;
  }
  sort(ans, ans + n);
  ll first = -1;
  for (ll i = 0; i < n; i++) if (w[i] == 1) { first = i; break; }
  if (first == -1) {
    for (ll i = 0; i < n; i++) {
      x[i] = (x[i] - t) % l;
      if (x[i] < 0) x[i] += l;
      printf("%lld\n", x[i]);
    }
    return 0;
  }
  ll counter = 0;
  for (ll i = 0; i < n; i++) if (w[i] == 2) {
    ll temp = x[i] - x[first];
    if (temp < 0) temp += l;
    counter += 2*(t/l);
    if (temp <= 2 * (t%l)) counter++;
    if (temp + l <= 2 * (t%l)) counter++;
  }
  ll num;
  for (ll i = 0; i < n; i++) if ((x[first] + t) % l == ans[i]) num = i;
  ll diff = (num - first - counter) % n;
  if (diff < 0) diff += n;
  for (ll i = 0; i < n; i++) printf("%lld\n", ans[(diff + i) % n]);
}

