long long modulo(long long n, long long mod) {
	n %= mod;
	if (n < 0) {
		n += mod;
	}
	return n;
}

int main() {
	int n;
	long long L, T;
	cin >> n >> L >> T;
	L *= 2;
	T *= 2;

	vector<long long> x(n), w(n);
	vector<long long> left, right;
	vector<tuple<long long, int, int>> d(n);
	for (int i = 0; i < n; i++) {
		cin >> x[i] >> w[i];
		x[i] *= 2;
		if (w[i] == 1) {
			right.push_back(L - x[i]);
			right.push_back(L - x[i] + L);
			d[i] = make_tuple(modulo(x[i] + T, L), w[i], i);
		} else {
			left.push_back(x[i]);
			left.push_back(x[i] + L);
			d[i] = make_tuple(modulo(x[i] - T, L), w[i], i);
		}
	}

	sort(left.begin(), left.end());
	sort(right.begin(), right.end());
	sort(d.begin(), d.end());

	vector<int> p(n);
	for (int i = 0; i < n; i++) {
		p[get<2>(d[i])] = i;
	}

	for (int i = 0; i < n; i++) {
		if (w[i] == 1) {
			long long cnt = T / (L / 2) * left.size();
			cnt += lower_bound(left.begin(), left.end(), x[i] + T % (L / 2) * 2) - lower_bound(left.begin(), left.end(), x[i]);
			cout << get<0>(d[modulo(p[i] - cnt, n)]) / 2 << endl;
		} else {
			long long cnt = T / (L / 2) * right.size();
			cnt += lower_bound(right.begin(), right.end(), L - x[i] + T % (L / 2) * 2) - lower_bound(right.begin(), right.end(), L - x[i]);
			cout << get<0>(d[modulo(p[i] + cnt, n)]) / 2 << endl;
		}
	}
}

