		int tt = (X[b2[p2]] - X[b1[p1]] + L) % L;
		while (tt <= t) tt += L;
		if (tt >= 2*T) break;
		t = tt;
		if (w == 1) {
			w = 2;
			p1 = (p1+b1.size()-1) % b1.size();
		} else {
			w = 1;
			p2 = (p2+1) % b2.size();
		}
	}
	if (w == 1) {
		return (X[b1[p1]] + T) % L;
	} else {
		return ((X[b2[p2]] - T) % L + L) % L;
	}
}
