    if (x1.size() > 0 && x2.size() > 0) {
        int tcur = 0;
        int idx = 0;
        int i1 = 0, i2 = 0;
        while (tcur < 2 * t) {
            if (w[idx] == 1) {
                int xcur = (x[idx] + tcur % l) % l;
                while (i2 < x2.size() && x2[i2].first <= xcur)
                    i2++;
                int64_t tadd = 0;
                if (i2 == x2.size())
                    i2 = 0, tadd += l;
                tadd += x2[i2].first - xcur;
                if (tcur + tadd < 2 * t) {
                    tcur += tadd;
                    idx = x2[i2].second;
                }
                else {
                    tcur = 2 * t;
                }
            }
            else {
                int xcur = (x[idx] + l - tcur % l) % l;
                while (i1 >= 0 && x1[i1].first >= xcur)
                    i1--;
                int64_t tadd = 0;
                if (i1 == -1)
                    i1 = x1.size() - 1, tadd += l;
                tadd += xcur - x1[i1].first;
                if (tcur + tadd < 2 * t) {
