    auto iter = find(Z, Z + N, first);
    int index = distance(Z, iter);

    int zekken = 0;
    for (int i = 1; i < N; i++)
    {
        if (W[0] == 1)
            if (W[i] != W[0])
                zekken++;
        if (W[0] == 2)
            if (W[i] != W[0])
                zekken--;
    }

    zekken = zekken * (T / L) * 2;
    T = T % L;

    for (int i = 1; i < N; i++)
    {
        if (W[0] == 1  && W[i] != W[0])
        {
            if (X[i] - X[0] > 2 * T)
            {
                break;
            }
            else if (X[i] - X[0] <= 2 * T - L)
            {
                zekken += 2;
            }
            else
            {
                zekken++;
            }
        }
        else if (W[0] == 2 && W[i] != W[0])
        {
            if (X[0] + L - X[N - i] > 2 * T)
            {
                break;
            }
            else if (X[0] + L - X[N - i] <= 2 * T - L)
            {
                zekken -= 2;
            }
            else
            {
                zekken--;
            }
        }
    }

    zekken = zekken % N + N;
    int start = (index - zekken) % N;

    // cout << "zekken " << zekken << endl;
    // cout << "index " << index << endl;
    // cout << "start " << start << endl;

    for (int i = start; i < N + start; i++)
    {
        if (i < 0)
            cout << Z[N + i] << endl;
        else if (i >= N)
            cout << Z[i - N] << endl;
        else
            cout << Z[i] << endl;
    }

    return 0;
}

