    for(int i=0;i<n;i++){
        loc[i]=x[i]+(w[i]==1 ? t : -t);
        loc[i]=(loc[i]%l+l)%l;
    }
    sort(loc.begin(),loc.end());

    auto calc=[&](int id){
        ll cnt=0;
        for(int i=0;i<n;i++){
            if(w[id]!=w[i]){
                ll d;
                if(w[id]==1 && w[i]==2) d=(x[i]+l-w[id])%l;
                else d=(x[id]+l-w[i])%l;
                if(t*2>=d) cnt+=(t*2-d)/l+(ll)(d<=t*2);
            }
        }
        int exid=(w[id]==1 ? (id+cnt)%n : (id+n-cnt%n)%n);
        ll d=(x[id]+(w[id]==1 ? t : -t));
        d=(d%l+l)%l;
        return make_pair(exid,d);
    };
    auto pat0=calc(0);
    auto pat1=calc(1);
    auto pat2=calc(2);
