class Circle_Ant {

  private:
    struct Pair {
      long long x;
      long long w;
    };

    long long N_, L_, T_;
    std::vector<Pair> ant;
    std::vector<long long>  afterT;

    bool isCollision ( long long i, long long j ) {
      if ( i > j ) std::swap(i,j);
      if ( ant[i].w == 1 && ant[j].w == 2 ) {
        long long len = ant[j].x - ant[i].x;
        if ( len <= 2*T_ ) return true;
      }
      if ( ant[i].w == 2 && ant[j].w == 1 ) {
        long long len = L_ - (ant[j].x - ant[i].x);
        if ( len <= 2*T_ ) return true;
      }
      return false;
    }

    long long BuildZekken (long long i) {
      long long zekken = i;
      for(int j=0; j<N_; j++){
        if ( j == i ) continue;
        if ( ant[i].w == 1 && isCollision (i,j) ) {
          if ( zekken == N_-1 ) zekken = 0;
          else zekken += 1;
          continue;
        }
        if ( ant[i].w == 2 && isCollision (i,j) ) {
          if ( zekken == 0 ) zekken = N_-1;
          else zekken -= 1;
          continue;
        }
      }
      return zekken;
    }

    void BuildT () {
      for(long long i=0; i<N_; i++) {
        afterT[i] = ant[i].x + (ant[i].w == 1 ? T_ : -T_ );
        if ( afterT[i] < 0   ) afterT[i] += L_;
        if ( afterT[i] >= L_ ) afterT[i] -= L_;
      }
    }


  public:
    Circle_Ant( long long N, long long L, long long T) {
      N_ = N; L_ = L; T_ = T;
      afterT.resize(N_); for(long long i=0; i<N_; i++) afterT[i] = 0;
    }

    void Fill ( long long x, long long w ) {
      ant.push_back( {x, w} );
    }

    void Sol() {
      long long HeadAnt_Zekken = BuildZekken(0);
      BuildT();
      for(long long i=0; i<N_; i++){
        int ind = (i - HeadAnt_Zekken + N_) % N_;
        std::cout << afterT[ind] << std::endl;
      }
    }

};

int main (void){

  long long N, L, T;
  std::cin >> N >> L >> T;

  Circle_Ant ca(N, L, T);

  for(long long i=0; i<N; i++){
    long long x, w; std::cin >> x >> w;
    ca.Fill(x, w);
  }

  ca.Sol();
  return 0;
}

