      if (pos.at(i) < 0)
      {
        pos.at(i) += L;
      }
    }
    else
    {
      pos.at(i) = (X.at(i) - (T % L) + L) % L + 0.1;
      if (pos.at(i) > L)
      {
        pos.at(i) -= L;
      }
    }
  }
  double p0 = pos.at(0);
  sort(pos.begin(), pos.end());
  int start = lower_bound(pos.begin(), pos.end(), p0 - 0.1) - pos.begin();
