pair<int,int> a[200000];

int main() {
  int n,L,t,cnt=0;
  scanf("%d%d%d",&n,&L,&t);
  for(int i=0;i<n;i++){
    scanf("%d%d",&a[i].first,&a[i].second);
    if(a[i].second==1){
      a[i].first+=(t%L);
      a[i].first%=L;
    }
    else{
      cnt++;
      a[i].first-=(t%L);
      a[i].first+=L;
      a[i].first%=L;
    }
    //printf("=%d",a[i].first);
  }

  int cur=0+(((n-cnt)-cnt)%L)*(t/L);
  if(cur<0){
    cur+=(-1)*(cur+n-1)/n*n;
  }
  cur%=n;
  //printf("-----%d",cur);
  int isdb=0;
  if(t%L>(2*L)){
    isdb = 1;
  }
  for(int j=0;j<isdb+1;j++){
    int r=(cur+1)%n,l=(cur-1+n)%n;
    //printf("%d---",l);
    while(r<=l){
      cur%=n;
      if(a[cur].second==1){
        if(a[r].second!=2||a[l].first>a[cur].first){
          r++;
          r%=n;
          continue;
        }
        cur=r;
        r++;
        r%=n;
      }
      else{
        if(a[l].second!=1||a[l].first<a[cur].first){
          l--;
          continue;
        }
        cur=l;
        l+=n-1;
        l%=n;
      }
    }
  }
  cur+=n;
  cur%=n;
  for(int i=0;i<n;i++){
    if(a[i].first<0)
      a[i].first+=L;
    a[i].first=(a[i].first)%L;
  }
  int init = a[cur].first%L;
  sort(a,a+n);
  for(int i=0;i<n;i++){
    if(a[i].first==init){
      init=i;
      break;
    }
  }
  for(int i=0;i<n;i++){
    printf("%d\n",a[(init+i)%n].first);
  }
}

