    VEC Xs(N);
    vector<bool> Ws(N);

    FOR(i, N){
        INT x,y;
        cin >> x >> y;
        Xs[i] = x;
        if( y == 1 ){
            Ws[i] = true;
        } else {
            Ws[i] = false;
        }
    }

    INT id_diff = 0;
    FOR(i, N){
        if( Ws[i] ){
            Xs[i] += T;
            id_diff -= ( Xs[i] / L );
            Xs[i] = ( Xs[i] % L );
        } else {
            Xs[i] -= T;
            if( Xs[i] < 0 ){
                id_diff -= ( Xs[i] / L ) - 1; 
                Xs[i] = ( Xs[i] % L ) + L;
            }
        }
    }

    INT id_first = ( id_diff < 0 ) ? N+id_diff : id_diff;
    auto fst = std::min_element(RANGE(Xs));
    auto it = fst;

    VEC ans(N);
    while( it != Xs.end() ){
        ans[id_first++] = *it; it++;
        id_first %= N;
    }
    it = Xs.begin();
    while( it != fst ){
        ans[id_first++] = *it; it++;
        id_first %= N;
    }

    FOR(i, N) cout << ans[i] << endl;

