int model(int p, int t) {
	ti[0].clear();
	ti[1].clear();
	FOR(i, 0, n) {
		if (i == p) {
			continue;
		}
		if (w[i] == 1) {
			LL dist = a[p] - a[i];
			if (dist < 0) {
				dist += l;
			}
			ti[0].push_back(dist);
		}
		else {
			LL dist = a[i] - a[p];
			if (dist < 0) {
				dist += l;
			}
			ti[1].push_back(dist);
		}
	}
	sort(ti[0].begin(), ti[0].end());
	sort(ti[1].begin(), ti[1].end());
	int dir = w[p] - 1;
	int x = 0;
	int y = 0;
	LL dist[2] = { 0, 0 };
	int pos[2] = {0, 0};
	while (1) {
		dir ^= 1;
		if (ti[dir].size() == 0) {
			break;
		}
		if (ti[dir][pos[dir]] + dist[dir ^ 1] > t + t) {
			break;
		}
		dist[dir] = ti[dir][pos[dir]];
		ti[dir ^ 1].push_back(dist[dir ^ 1] + l);
		pos[dir]++;
	}
	dir ^= 1;
	LL res = a[p];
	if (dir == 0) {
		res += t;
		res %= l;
		res -= dist[0];
		if (res < 0) {
			res += l;
		}
	}
	else {
		res += dist[1];
		res %= l;
		res -= t;
		if (res < 0) {
			res += l;
		}
	}
	return res;
}

int goClockWise(int p, int t) {
	return (p + t) % l;
}

int goCounterClockWise(int p, int t) {
	t %= l;
	p -= t;
	if (p < 0) {
		p += l;
	}
	return p;
}
