bool cmp(int x, int y) { return p[x]<p[y]; }
ll s;
int main() {
	scanf("%d%d%I64d", &n, &m, &s);
	rep(i, 0, n - 1) {
		char ch[10]; scanf("%d %s", p + i, ch);
		p[i]; ra[i] = i;
