	int t = 0;
	rep(i, 0, n - 1) {
		if (dir[i] == 1) t += (p[i] + s) / m%n;
		else t += (p[i] - s - m + 1) / m%n;
		t = (t%n + n) % n;
		p[i] = p[i] + s%m*dir[i];
		p[i] = (p[i] % m + m) % m;
	}
	sort(p, p + n);
	rep(i, 0, n - 1) ans[ra[(i + n - t) % n]] = p[i];
	rep(i, 0, n - 1)
		printf("%d\n", ans[i]);
	return 0;
}

