int main(){
    std::cin.tie(nullptr);
    std::ios::sync_with_stdio(false);
    std::cout << std::setprecision(15) << std::fixed;

    usize n;
    i64 L, T;
    std::cin >> n >> L >> T;
    L *= 2;
    T *= 2;

    vec<std::pair<i64, usize>> xdir(n);
    vec<vec<i64>> pos(2);
    for (usize i=0; i<n; i++) {
        i64 x;
        usize dir;
        std::cin >> x >> dir;
        x *= 2;
        dir--;

        xdir.at(i) = {x, dir};
        pos.at(dir).push_back(x);
    }

    for (usize dir=0; dir<2; dir++) {
        auto&& v = pos.at(dir);
        if (dir==0) {
            for (i64& x: v) x -= 2*L;
        }
        usize sz = v.size();
        for (usize i=0; i<2*sz; i++) {
            v.push_back(v.at(i) + L);
        }
    }
    DEBUG(matrix_style<4>(pos));

    auto m1pow = [&](usize dir) {
        assert(dir==0 || dir==1);
        return dir==0 ? 1: -1;
    };

    auto normalized = [&](i64 x) {
        x %= L;
        return x<0 ? x+L : x;
    };

    auto simulate = [&](usize i, i64 tmax) -> i64 {
        DEBUG("simulate", i, tmax);
        i64 x;
        usize dir;
        std::tie(x, dir) = xdir.at(i);

        if (pos.at(!dir).empty()) {
            return normalized(x + m1pow(dir)*tmax);
        }

        i64 t = 0;
        while (true) {
            auto&& v = pos.at(!dir);
            DEBUG(x,t,dir,v);
            i64 dt = -1;
            if (dir==0) {
                auto ub = std::upper_bound(ALL(v), x+t);
                assert(ub!=v.end() && x+t<*ub && ((*ub-(x+t))%2==0));
                dt = (*ub-(x+t))/2;
            }
            if (dir==1) {
                auto lb = std::lower_bound(ALL(v), (x-t));
                assert(lb!=v.begin());
                --lb;
                assert(*lb<(x-t) && ((x-t)-*lb)%2==0);
                dt = ((x-t)-*lb)/2;
            }

            if (tmax <= t+dt) {
                return normalized(x + m1pow(dir) * (tmax-t));
            }
            x = normalized(x + m1pow(dir) * dt);
            t += dt;
            dir ^= 1;
        }
    };

    i64 next = simulate(0, L);
    {
        auto lb = std::lower_bound(ALL(xdir), std::make_pair(next, usize{0}));
        assert(lb!=xdir.end() && lb->first == next);
        next = lb - xdir.begin();
    }

    DEBUG("after one cycle idx", next);
    i64 q = T / L;
    i64 r = T % L;
    next = simulate((next*q)%n, r);

    vec<i64> config;
    for (auto&& e: xdir) {
        i64 x;
        usize dir;
        std::tie(x, dir) = e;
        config.push_back(normalized(x + m1pow(dir)*T));
    }
    std::sort(ALL(config));
    DEBUG(config);

    {
        auto lb = std::lower_bound(ALL(config), next);
        assert(lb!=config.end() && *lb == next);
        next = lb - config.begin();
    }
    DEBUG("final idx", next);

    for (usize i=0; i<n; i++) {
        std::cout << config.at((next+i)%n)/2 << '\n';
    }
}

