int main() {
	int n = ri();
	int64_t l = ri(), t = ri();
	int64_t t_bak = t;
	int64_t x[n], w[n];
	for (int i = 0; i < n; i++) x[i] = ri(), w[i] = !(ri() - 1); // 1 => +
	t *= 2;

	int64_t col = 0;
	for (int i = 1; i < n; i++) {
		if (w[i] != w[0]) {
			int dist = w[0] ? (x[i] - x[0] + l) % l : (x[0] - x[i] + l) % l;
			if (dist < t) {
				col++;
				col += (t - dist - 1) / l;
			}
		}
	}
	int label = w[0] ? col % n : (-col % n + n) % n;
	std::set<std::pair<int, bool> > st;
	std::pair<int, bool> zero;
	if (!w[0]) zero = {((x[0] - t_bak) % l + l) % l, true};
	else zero = {(x[0] + t_bak) % l, false};
	for (int i = 0; i < n; i++) {
		if (!w[i]) st.insert({((x[i] - t_bak) % l + l) % l, true});
		else st.insert({(x[i] + t_bak) % l, false});
	}
	assert(st.size() == n);
	auto itr = st.lower_bound(zero);
	assert(itr != st.end() && *itr == zero);
	int res[n];
	for (auto i = itr; i != st.end(); i++) res[label++ % n] = i->first;
	for (auto i = st.begin(); i != itr; i++) res[label++ % n] = i->first;
	for (int i = 0; i < n; i++) std::cout << res[i] << " ";
	return 0;
}

