const int mod = 1000000007;

long long pw(long long a, long long b) {
	long long res = 1;
	while (b) {
		if (b & 1ll) {
			res = res * a % mod;
		}
		b >>= 1;
		a = a * a % mod;
	}
	return res;
}

vector<int> solve(int n, int l, int t, vector<int> a, vector<int> w) {
	// int shift = accumulate(all(w), 0);
	// if (shift < 0) {
	// 	shift += n;
	// }

	// rotate(a.begin(), a.begin() + (1ll * (t / l) * shift) % n, a.end());
	// t %= l;

	vector<int> new_pos(n);
	for (int i = 0; i < n; ++i) {
		new_pos[i] = a[i] + t * w[i];
		new_pos[i] %= l;
		if (new_pos[i] < 0) {
			new_pos[i] += l;
		}
	}
	sort(all(new_pos));

	if (n == 1) {
		return new_pos;
	}

	long long sum = 1ll * accumulate(all(w), 0) * t;
	long long cur = accumulate(all(new_pos), 0ll) - accumulate(all(a), 0ll);
	// cerr << new_pos << " " << shift << " " << sum << " " << cur << "\n";

	long long diff = (sum - cur) / l;
	diff %= n;
	if (diff < 0) {
		diff += n;
	}
	rotate(new_pos.begin(), new_pos.begin() + diff, new_pos.end());

	return new_pos;
}

vector<int> stupid(int n, int l, int t, vector<int> a, vector<int> w) {
	for (int& x : a) {
		x *= 2;
	}
	t *= 2;
	l *= 2;
	while (t--) {
		for (int i = 0; i < n; ++i) {
			a[i] += w[i];
			if (a[i] == l) {
				a[i] = 0;
			}
			if (a[i] == -1) {
				a[i] = l - 1;
			}
		}
		for (int i = 0; i < n; ++i) {
			if (i == 1 && n == 2) {
				continue;
			}
			if (a[i] == a[(i + 1) % n]) {
				swap(w[i], w[(i + 1) % n]);
			}
		}
	}
	for (int& x : a) {
		x /= 2;
	}
	return a;
}

