using namespace std;
const int kMaxN = 1e5 + 10;
typedef long long int64;

int n;
int64 l, t;
int64 x[kMaxN], w[kMaxN];

int64 getPos(int i, int64 passed) {
	int64 pos =  (x[i] + w[i] * passed) % l;
	if (pos < 0)
		pos += l;
	return pos;
}

int64 timeToInter(int i, int j, int64 passed) {
	int64 posi = getPos(i, passed);
	int64 posj = getPos(j, passed);
	if (w[i] == -1)
		swap(posi, posj);
	// cout << i << " " << j << " ";
	// cout << posi << " " << posj << " ";
	int64 dif = (posj - posi + l)% l;
	if (dif&1)
		dif = (dif>>1) + 1;
	else dif = dif>>1;
	return dif;
}

int follow(int x, int64 start, int64 finish) {
	queue<int> Q[2];
	for (int i = x, cnt = 1; cnt <= n; ++cnt) {
		if (w[i] == 1)
			Q[0].push(i);
		else Q[1].push(i);

		if (w[x] == 1) {
			i = (i == n ? 1 : i+1);
		} else {
			i = (i == 1 ? n : i-1);
		}
	}

	int wh;
	if (w[x] == 1) {
		wh = 0;
	} else {
		wh = 1;
	}

	if (!Q[1-wh].empty()) {
		int64 passed = start;
		// cout << "Here\n";
		while (passed < finish) {
			// cout << passed << " ";
			int64 time = timeToInter(Q[wh].front(), Q[1-wh].front(), passed);
			// cout << time << "\n";
			if (passed + time <= finish) {
				passed += time;
				int y = Q[wh].front();
				Q[wh].pop();
				Q[wh].push(y);
				wh = 1 - wh;
			} else {
				passed = finish;
			}
		}
	}

	return Q[wh].front();
}

void solve() {
	cin >> n >> l >> t;

	for (int i =1 ; i <= n; ++i) {
		cin >> x[i] >> w[i];
		if (w[i] == 2)
			w[i] = -1;
	}

	int who = follow(1, 0, l);
	// cout << who << "\n";
	int64 quo = t / l;
	who = 1 + ((who - 1) * quo % n);
	// cout << who << "\n";
	int64 rem = t % l;
	int who2 = follow(who, l * quo, rem);
	// cout << who2 << "\n";

	for (int i = who2, cnt = 1; cnt <= n; ++cnt, i = (i == n ? 1 : i+1)) {
		cout << getPos(i, t) << "\n";
	}
}

