			int from = x[i], to = (x[i] + (t % l)) % l;
			stp += count(1, from, to);
			stp %= n;
			ans[stp] = (x[i] + (t/2)) % l;
		} else {
			stp += n - (pos[0].size() * (t / l) % n);
			int from = (x[i] - (t % l) + l) % l, to = x[i];
			stp += n - count(0, from, to);
			stp %= n;
			ans[stp] = (x[i] + l - ((t/2)%l)) % l;
		}
	}
	for(int i = 0; i < n; i++) cout << ans[i] << endl;
	return 0;
}

