void solve() {
  int n, l, t; cin >> n >> l >> t;
  vector<pii> arr, rev;
  rep(i,n) {
    int x, w; cin >> x >> w;
    if (w == 1) arr.emplace_back(x, i);
    else rev.emplace_back(x, i);
  }

  if (rev.empty()) {
    t %= l;
    rep(i,n) cout << (arr[i].first + t) % l << '\n';
    return;
  }

  if (arr.empty()) {
    t %= l;
    t = l - t;
    rep(i,n) cout << (rev[i].first + t) % l << '\n';
    return;
  }

  reverse(ALL(arr));

  int idx = arr.begin()->second;

  auto f = [&](int comp) -> ll {
    auto itr = arr.begin();
    auto ritr = upper_bound(ALL(rev), *itr);
    if (ritr == rev.end()) ritr = rev.begin();
    int ridx = ritr - rev.begin();
    ll sum = (ritr->first - itr->first + l) % l;
    int cnt = 0;

    while (sum <= comp) {
      if (++cnt & 1) {
        auto sitr = itr + 1;
        if (sitr == arr.end()) sitr = arr.begin();
        sum += (itr->first - sitr->first + l - 1) % l + 1;
        itr = sitr;
      } else {
        auto sitr = ritr + 1;
        if (sitr == rev.end()) sitr = rev.begin();
        sum += (sitr->first - ritr->first + l - 1) % l + 1;
        ritr = sitr;
      }
    }

    if (cnt & 1) {
      return (rev[(ridx + cnt / 2) % rev.size()].second - idx + n) % n;
    } else {
      return (arr[cnt / 2 % arr.size()].second - idx + n) % n;
    }
  };

  int add = 0;

  if (l <= t) {
    add = t / l * f(2 * l) % n;
    t %= l;
  }

  int dummy = (idx + f(2 * t)) % n;

  vector<pii> pos; pos.reserve(n);
  for (auto &p : arr) pos.emplace_back((p.first + t) % l, p.second + (1<<20));
  for (auto &p : rev) pos.emplace_back((p.first + l - t) % l, p.second);

  sort(ALL(pos));

  int v = 0;
  int mask = (1<<20) - 1;
  while ((pos[v].second & mask) != dummy) ++v;

  (v -= idx - add) %= n;
  if (v < 0) v += n;

  REP(i,v,n-1) cout << pos[i].first << '\n';
  rep(i,v) cout << pos[i].first << '\n';
}
