    			col[0] -= ((2 * lim - t) / m + 1);
    		}                        
    	}
    }

    for (int i = 1; i < n; ++i) {
    	col[i] = col[i - 1] + 1;
    }    

    for (int i = 0; i < n; ++i) {
    	col[i] = (col[i] % n + n) % n;
    }                 

    for (int i = 0; i < n; ++i) {
    	ll p = (arr[i].se ? arr[i].fi - lim : arr[i].fi + lim);
    	ans[col[i]] = (p % m + m) % m;
    }

    for (int i = 0; i < n; ++i) {
    	printf("%d\n", ans[i]);
    }
}

