	}

    for (int i = 0; i < n; ++i) {
		scanf("%lld %d", &arr[i].fi, &arr[i].se);
        --arr[i].se;
    }

    assert(n <= 7000);

    vector<ll> tmp[2];

    for (int i = 0; i < n; ++i) {    	    
    	if (arr[i].se == 0) {
    		for (ll x : tmp[1]) {
    			if (x <= 2 * lim - m + arr[i].fi) {
    				++col[i];
    			}
    		}                            	
    	}
    	else {
    		for (ll x : tmp[0]) {
    			if (arr[i].fi - 2 * lim <= x) {
    				--col[i];
    			}
    		}
        }

    	tmp[arr[i].se].pb(arr[i].fi);
    }

    for (int i = 0; i < 2; ++i) {
    	tmp[i].clear();
    }

    for (int i = n - 1; i >= 0; --i) {    	
    	if (arr[i].se == 0) {
			for (ll x : tmp[1]) {
				if (x <= 2 * lim + arr[i].fi) {
					++col[i];
				}
			}
  		}
    	else {
    		for (ll x : tmp[0]) {
    			if (arr[i].fi - 2 * lim + m <= x) {
    				--col[i];
    			}
    		}                    	
    	}    	

    	tmp[arr[i].se].pb(arr[i].fi);
    }

    for (int i = 0; i < n; ++i) {
    	col[i] = (col[i] % n + n) % n;
    }

    for (int i = 0; i < n; ++i) {
    	ll p = (arr[i].se ? arr[i].fi - lim : arr[i].fi + lim);
    	ans[col[i]] = (p % m + m) % m;
    }

    for (int i = 0; i < n; ++i) {
    	printf("%d\n", ans[i]);
    }
}

