        if(pos < 0) pos = L - (-pos % L);
        if(L <= pos) pos %= L;
        po[i].x = pos;
        po[i].i = (N + (i + start)) % N;
    }
    sort(po, po + N, [](Ant a, Ant b){return a.i < b.i;});
