#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
int N;
ll L, T;
vector<ll> X, W;
vector<int> b1, b2;
int f(int p) {
	ll w = W[p];
	int p1, p2;
	if (w == 1) {
		p1 = 0;
		while (b1[p1] != p) ++ p1;
		p2 = -1;
		for (int i = 0; i < (int)b2.size(); ++ i) {
			if (b2[i] > p) {
				p2 = i;
				break;
			}
		}
		if (p2 < 0) p2 = 0;
	} else {
		p2 = 0;
		while (b2[p2] != p) ++ p2;
		p1 = -1;
		for (int i = b1.size()-1; i >= 0; -- i) {
			if (b1[i] < p) {
				p1 = i;
				break;
			}
		}
		if (p1 < 0) p1 = b1.size() - 1;
	}
	ll t = 0;
	int state = 0, w0, p10, p20;
	ll t0;
	for (;;) {
		ll tt = (X[b2[p2]] - X[b1[p1]] + L) % L;
		if (tt <= t) tt += ((t-tt)/L+1)*L;
		if (tt >= 2*T) break;
		t = tt;
		if (w == 1) {
			w = 2;
			p1 = (p1+b1.size()-1) % b1.size();
		} else {
			w = 1;
			p2 = (p2+1) % b2.size();
		}
		if (state == 0) {
			state = 1;
			w0 = w;
			p10 = p1;
			p20 = p2;
			t0 = t;
		} else if (state == 1 && w == w0 && p1 == p10 && p2 == p20) {
			state = 2;
			ll s = t - t0;
			ll n = (2*T - t - 1) / s;
			if (n > 0) t += s*n;
		}
	}
	if (w == 1) {
		return (X[b1[p1]] + T) % L;
	} else {
		return ((X[b2[p2]] - T) % L + L) % L;
	}
}
