const int N = 1e+5+3;

struct ant{
	int x,fx;
}a[N],b[N];
int id[N];
int n;
int w1[N],w2[N],k1,k2;
int l,t;
int k;
int ans[N];
int qt;

bool cmp(ant a,ant b){
	return a.x<b.x;
}

void putans(int w){
	t=qt;
	fo(i,1,n){
		if (a[i].fx==1)a[i].x=(a[i].x+t)%l;
		else a[i].x=(a[i].x+l-t)%l;
	}
	sort(a+1,a+1+n,cmp);
	fo(i,1,n)
	if (a[i].x==w){
		for(int cas=k,now=i;cas;cas--,now=(now+n-2)%n+1)id[now]=cas;
		for(int cas=k,now=i;cas<=n;cas++,now=now%n+1)id[now]=cas;
		id[i]=k;
		break;
	}
	fo(i,1,n)ans[id[i]]=a[i].x;
	fo(i,1,n)printf("%d\n",ans[i]);
}

int main(){
	n=get();l=get();t=get();
	fo(i,1,n){a[i].x=get();a[i].fx=get();}
	bool bz=1;
	fo(i,2,n)bz&=(a[i].fx==a[1].fx);
	if (bz){
		if (a[1].fx==1)fo(i,1,n)printf("%d\n",(a[i].x+t)%l);
		else fo(i,1,n)printf("%d\n",(a[i].x+l-t)%l);
		return 0;
	}
	k=0;
	fo(i,1,n)if (a[i].fx==1){k=i;break;}
	fo(i,1,n)b[i]=a[i];
	fo(i,k,n)a[i-k+1]=b[i];
	fo(i,1,k-1)a[n-k+1+i]=b[i];
	qt=t;
	t<<=1;
	t%=(l*2);
	fo(i,1,n)
	if (a[i].fx==1)w1[++k1]=a[i].x;else w2[++k2]=a[i].x;
	int w=w1[1];
	if (t<=(w2[1]+l-w1[1])%l)putans((w+t+l-qt%l)%l);
	else{
		w=(w+(w2[1]+l-w1[1])%l)%l;
		t-=(w2[1]+l-w1[1])%l;
		int now=2;
		int h1=1,h2=1;
		while(t){
			if (now==2){
				int tmp=(w1[h1%k1+1]+l-w1[h1])%l;
				w=(w+min(t,tmp))%l;
				t-=min(t,tmp);
				now=1;h1=h1%k1+1;
			}
			else{
				int tmp=(w2[h2%k2+1]+l-w2[h2])%l;
				w=(w+min(t,tmp))%l;
				t-=min(t,tmp);
				now=2;h2=h2%k2+1;
			}
		}
		putans((w+l-qt%l)%l);
	}
	return 0;
}

