int get1(int x, int y, int t)
{
	int d;
	if (x <= y)
		d = y - x;
	else
		d = y - x + l;

	return max(0, (2 * t - d) / l + 1);
}

int get2(int x, int y, int t)
{
	int d;
	if (x >= y)
		d = x - y;
	else
		d = x - y + l;

	return max(0, (2 * t - d) / l + 1);
}

