	for (int i = 0; i < N; i++)
	{
		int tmpX;
		int tmpW;
		cin >> tmpX >> tmpW;
		X.push_back(tmpX);
		W.push_back(tmpW);
	}

	vector<int> Xd;
	for (int i = 1; i < N; i++)
	{
		if (W.at(i) != W.at(0)) {
			Xd.push_back(X.at(i) * 2);
		}
	}

	int cnt = 0;
	const int Ld = L * 2;
	const int Td = T * 2;
