			td += (Xd.at(i) - X0d) / 2;
		}
		else {
			td += (L + X0d - Xd.at(i)) / 2;
		}
		if (td < Td) {
			cnt++;
		}
		else {
			continue;
		}
		cnt += ((Td - td - 1) / (Ld / 2)) % N;
		cnt %= N;
	}
	vector<int> Xfinal;
	int X0final;
	for (int i = 0; i < N; i++)
	{
