	bool isok=0;
	for(int i=1;i<=n;i++) if(w[i]!=w[1]) isok=1;
	if(!isok){
		for(int i=1;i<=n;i++) printf("%d\n",res[i]);
		puts("");
		return 0;
	}
	int a1=solve();
//	debug(a1);
	int xx=x[1],ww=w[1];
	for(int i=1;i<n;i++)x[i]=x[i+1],w[i]=w[i+1];
	x[n]=xx;w[n]=ww;
	int p=x[1];
	for(int i=1;i<=n;i++) x[i]=(x[i]-p+m)%m;

	int a2=(solve()+p)%m;
//	debug(a2);
	for(int i=1;i<=n;i++)
		if(res[i]==a1&&res[i%n+1]==a2){
			for(int j=i;j<=n;j++) printf("%d\n",res[j]);
			for(int j=1;j<i;j++) printf("%d\n",res[j]);
			return 0;
		}
	return 0;
}

