#define MAXN 1000010
#define LL long long

int n;
LL L,T;
LL pos[MAXN],dir[MAXN];
LL d1[MAXN],d2[MAXN];
LL sd1[MAXN],sd2[MAXN];
LL p1[MAXN],p2[MAXN];
int id1[MAXN],id2[MAXN];
int target1[MAXN],target2[MAXN],target[MAXN];
int n1,n2;

LL getD1(int x,int l){
	if(l<=x) return sd1[x]-sd1[x-l];
	LL res=sd1[x];
	l-=x;
	res+=sd1[n1]*(l/n1);
	res+=sd1[n1]-sd1[n1-l%n1];
	return res;
}

LL getD2(int x,int l){
	if(l<=n2-x+1) return sd2[x+l-1]-sd2[x-1];
	LL res=sd2[n2]-sd2[x-1];
	l-=n2-x+1;
	res+=sd2[n2]*(l/n2);
	res+=sd2[l%n2];
	return res;
}

int find1(int x1,int x2,LL t){
	int l=0,r=t;
	while(l<r){
		int mid=(l+r+1)>>1;
		if(getD1(x1,mid)+getD2(x2,mid)<=t) l=mid;
		else r=mid-1;
	}
	t-=getD1(x1,l)+getD2(x2,l);
	x1=((x1-l-1)%n1+n1)%n1+1;
	x2=(x2+l-1)%n2+1;
	if(t<d1[x1]) return id2[x2];
	else return id1[(x1-2+n1)%n1+1];
}

int find2(int x1,int x2,LL t){
	int l=0,r=t;
	while(l<r){
		int mid=(l+r+1)>>1;
		if(getD1(x1,mid)+getD2(x2,mid)<=t) l=mid;
		else r=mid-1;
	}
	t-=getD1(x1,l)+getD2(x2,l);
	x1=((x1-l-1)%n1+n1)%n1+1;
	x2=(x2+l-1)%n2+1;
	if(t<d2[x2]) return id1[x1];
	else return id2[x2%n2+1];
}

int main(){
#ifdef DEBUG
	freopen("C.in","r",stdin);
#endif
	scanf("%d%lld%lld",&n,&L,&T);
	for(int i=1;i<=n;i++){
		scanf("%lld%lld",pos+i,dir+i);
		if(dir[i]==1){
			p1[++n1]=pos[i];
			id1[n1]=i;
		}else{
			p2[++n2]=pos[i];
			id2[n2]=i;
		}
	}
	for(int i=1;i<=n1;i++){
		d1[i]=(p1[i]-p1[(i-2+n1)%n1+1]+L)%L;
		if(!d1[i]) d1[i]=L;
		sd1[i]=sd1[i-1]+d1[i];
	}
	for(int i=1;i<=n2;i++){
		d2[i]=(p2[i%n2+1]-p2[i]+L)%L;
		if(!d2[i]) d2[i]=L;
		sd2[i]=sd2[i-1]+d2[i];
	}
	T*=2;
	int now=1;
	for(int i=1;i<=n1;i++){
		if(!n2){
			target[i]=i;
			continue;
		}
		while(now<=n2 && p1[i]>p2[now]) now++;
		int x=(now-1)%n2+1;
		LL delta=(p2[now]-p1[i]+L)%L;
		if(delta>T) target1[i]=id1[i];
		else target1[i]=find1(i,now,T-delta);
		target[id1[i]]=target1[i];
	}
	for(int i=n2;i>=1;i--){
		if(!n1){
			target[i]=i;
			continue;
		}
		while(now && p2[i]<p1[now]) now--;
		int x=(now-1+n1)%n1+1;
		LL delta=(p2[i]-p1[now]+L)%L;
		if(delta>T) target2[i]=id2[i];
		else target2[i]=find2(now,i,T-delta);
		target[id2[i]]=target2[i];
	}
	T/=2;
	for(int i=1;i<=n;i++){
		int x=target[i];
		if(dir[x]==1) printf("%lld\n",(pos[x]+T)%L);
		else printf("%lld\n",((pos[x]-T)%L+L)%L);
	}
	return 0;
}

