ll coord(ll x) {
	x %= L;
	if  (x < 0) {
		x += L;
	}
	return x;
}

const ll INF = 1e16;

ll mult(ll x, ll y) {
	if  (!y) {
		return 0;
	}
	if  (x >= INF / y) {
		return INF;
	}
	return min(INF, x * y);
}

ll final[MAXN];

void make_ans(bool is_left = true) {
	vll finals;
	forn(i, N) {
		ll pos = ants[i].x + (ants[i].w ? -1 : +1) * T;
		finals.pb(coord(pos));
	}

	sort(all(finals));
	int id0 = -1;
	srand(3);
	forn(i, N) {
		if  (finals[i] == final[ants[0].id]) {
			id0 = i;
			if  (!is_left) {
				assert((i + 1 < N && finals[i + 1] == final[ants[0].id]));
				++id0;
			}
			break;
		}
	}
	assert(id0 != -1);
	for (int i = 1; i < N; ++i) {
		final[ants[i].id] = finals[(id0 + i) % N];
	}
}

void solve1() {
	if  (ants[0].w == 1) {
		final[ants[0].id] = coord(ants[0].x - T);
		make_ans();
		return;
	}

	assert(!ants[0].x);

	vll opposite;
	vll my;
	for (int i = 1; i < N; ++i) {
		if  (ants[i].w == 1) {
			opposite.pb(ants[i].x);
		} else {
			my.pb(ants[i].x);
		}
	}

	// forn(i, N) {
	// 	printf("x=%lld w=%d\n", ants[i].x, ants[i].w);
	// }

	if  (opposite.empty() || opposite.front() - ants[0].x >= 2 * T) {
		final[ants[0].id] = coord(ants[0].x + T);
		make_ans();
		return;
	}

	// printf("opposite:\n");
