	ll nT = 2 * T;
	ll dist = opposite.front() - ants[0].x;
	for (auto& x : opposite) {
		x -= dist;
		assert(x >= 0);
	}
	nT -= dist;

	// printf("nT=%d\n", nT);

	vll go;
	if  (!my.empty()) {
		ll prv = ants[0].x;
		ford(i, sz(my)) {
			ll dist = prv - my[i];
			if  (dist < 0) {
				dist += L;
			}
			go.pb(dist);
			prv = my[i];
		}
		go.pb(my.front() - ants[0].x);
	} else {
		go.pb(L);
	}

	for (auto d : go) {
		assert(d > 0);
	}

	vll stay;
	ll prv = opposite.front();
	for (int i = 1; i < sz(opposite); ++i) {
		ll dist = opposite[i] - prv;
		stay.pb(dist);
		prv = opposite[i];
	}
	stay.pb(ants[0].x - opposite.back() + L);

	for (auto d : stay) {
		assert(d > 0);
	}

	vll pref_go(sz(go) + 1);
	forn(i, sz(go)) {
		pref_go[i + 1] = pref_go[i] + go[i];
	}

	vll pref_stay(sz(stay) + 1);
	forn(i, sz(stay)) {
		pref_stay[i + 1] = pref_stay[i] + stay[i];
