                    s.insert(make_pair(l - x[i] + x[0], i));
                } else {
                    s.insert(make_pair(x[i + 1] - x[i], i));
                }
            } 
        }
    }
    double curadd = 0;
    while (t > 0) {
        if (s.empty()) {
            curadd += t;
            break;
        }
        pair<double, int> a = *s.begin();
        s.erase(a);
        w[a.second] = 2;
        w[(a.second + 1) % n] = 1;
        x[a.second] += curadd - last[a.second];
        x[(a.second + 1) % n] -= curadd - last[(a.second + 1) % n];
