class Circle_Ant {

  private:
    struct Pair {
      long long x;
      long long w;
    };

    long long N_, L_, T_;
    std::vector<Pair> ant;
    std::vector<long long>  y;

    int isCollision ( long long i, long long j ) {
      if ( i > j ) std::swap(i,j);
      if ( ant[i].w == 1 && ant[j].w == 2 ) {
        long long len = ant[j].x - ant[i].x;
        if ( len <= 2*T_ ) return (2*T_ - len) / L_ + 1;
      }
      if ( ant[i].w == 2 && ant[j].w == 1 ) {
        long long len = L_ - (ant[j].x - ant[i].x);
        if ( len <= 2*T_ ) return (2*T_ - len) / L_ + 1;
      }
      return 0;
    }

    long long BuildZekken (long long i) {
      long long zekken = i;
      for(int j=0; j<N_; j++){
        if ( j == i ) continue;
        if ( ant[i].w == 1 && isCollision (i,j) ) zekken = (zekken + isCollision (i,j)) % N_;
        if ( ant[i].w == 2 && isCollision (i,j) ) zekken = (zekken - isCollision (i,j) + N_) % N_;
      }
      return zekken;
    }

    void BuildT () {
      for(long long i=0; i<N_; i++) {
        if ( ant[i].w == 1 ) y[i] = (ant[i].x + T_) % L_;
        if ( ant[i].w == 2 ) y[i] = (ant[i].x - T_ + L_) % L_;
      }
    }


  public:
    Circle_Ant( long long N, long long L, long long T) {
      N_ = N; L_ = L; T_ = T;
      y.resize(N_); for(long long i=0; i<N_; i++) y[i] = 0;
    }

    void Fill ( long long x, long long w ) {
      ant.push_back( {x, w} );
    }

    void Sol() {
      long long HeadAnt_Zekken = BuildZekken(0);
      BuildT();
      for(long long i=0; i<N_; i++){
        int ind = (N_ - HeadAnt_Zekken + i) % N_;
        std::cout << y[ind] << std::endl;
      }
    }

};

int main (void){

  long long N, L, T;
  std::cin >> N >> L >> T;

  Circle_Ant ca(N, L, T);

  for(long long i=0; i<N; i++){
    long long x, w; std::cin >> x >> w;
    ca.Fill(x, w);
  }

  ca.Sol();
  return 0;
}

