struct ant{
    long long dir;
    long long num;
    long long pos;
};

bool cmp(ant a, ant b){
    return (a.pos<b.pos)+(a.pos==b.pos)*(a.dir<b.dir);
}

ant a[200000];

long long getidx(long long cpos,long long cnum,long long n){
    sort(a,a+n,cmp);
    for(int i=0;i<n;i++){
        if(a[i].pos==cpos&&a[i].num==cnum){
            return i;
        }
    }
}

