#include <bits/stdc++.h>
using namespace std;

long long int N, L, T;
int X[100010], W[100010], Y[100010], Z[100010],S[100010], U[100010];
int A[100010], B[100010];
int a=0, b=0;
int pmod(long long int x, long long int a){
	if (x%a<0) return x%a+a;
  	else return x%a;
}
int modL(long long int x){
	if(x%L==0) return L;
  	else return pmod(x,L);
}
int locate_0(int t){
	if (W[0]==1){
		int i=0, d=0;
      	while(d<=2*t){
        	if (i%2==0){
            	if (i==0) {
                  d+=modL(B[0]-A[0]);
                }
              	else {
                	d+=modL(B[pmod(i/2,b)]-B[pmod(i/2-1,b)]);
                }
            }
          	else{
            	d+=modL(A[pmod((i-1)/2,a)]-A[pmod((i+1)/2,a)]);
            }
          i++;
        }
      	if (i%2==1) return pmod(A[pmod((i-1)/2,a)]+t,L);
      	else return pmod(B[pmod((i-2)/2,b)]-t,L);
    }
  if (W[0]==2){
		int i=0, d=0;
      	while(d<=2*t){
        	if (i%2==0){
            	if (i==0) {
                  d+=modL(B[0]-A[0]);
                }
              	else {
                	d+=modL(A[pmod((i-2)/2,a)]-A[pmod(i/2,a)]);
                }
            }
          	else{
            	d+=modL(B[pmod((i+1)/2,b)]-B[pmod((i-1)/2,b)]);
            	}	
          i++;
        }
      	if (i%2==0) return pmod(A[pmod((i-2)/2,a)]+t,L);
      	else return pmod(B[pmod((i-1)/2,b)]-t,L);
    }
}
int f(int x){
	for (int i=0; i<N; i++){
    	if (x==X[i]) return Y[i];
    }
}
int main() {
  cin >> N >> L >>T;
  for (int i=0; i<N; i++){
  	cin >>X[i] >> W[i];
  }
  for (int i=0; i<N; i++){
    if(W[i]==2){
      	B[b]=X[i];
        b++;
    }
  }
  for (int i=N; i>=1; i--){
    	if (W[i%N]==1){
      	A[a]=X[i%N];
        a++;
        }
    }


  int s=0;
  	while(X[s]!=locate_0(L)){
  		s++;
  	}

  for (int i=0; i<N;i++){
  	Y[i]=X[(i+s)%N];
  }

  int c=1, d=X[0];
  Z[0]=X[0];
  while(f(d)!=X[0]){
  	d=f(d);
    Z[c]=d;
    c++;
  }

  int u=(s*((c-(T/L)%c)%c))%N;

  for (int i=0; i<N; i++){
  	if (W[i]==1) S[i]=(X[i]+T)%L;
    else S[i]=pmod((X[i]-T),L);
  }
  sort(S, S+N);

  int v=0;
  while(S[v]!=locate_0(T%L)) v++;

  for (int i=0; i<N; i++){
  	U[i]=S[pmod(v-u+i,N)];
    cout << U[i] <<endl;
  }
}

