typedef long long ll;
ll n, l, t;
vector<ll> w, x, a, b[2];

int main(){
//	cin.tie(0);
//	ios::sync_with_stdio(false);
	cin >> n >> l >> t;
	x.resize(n);
	w.resize(n);
	for(int i=0; i<n; ++i){
		cin >> x[i] >> w[i];
		a.push_back((x[i] + (3-2*w[i]) * t + l)%l);
	}
	if(n == 1){
		cout << (x[0] + (3 - 2 * w[0]) * t) % l << "\n";
		return 0;
	}
	sort(a.begin(), a.end());
	for(int i=1; i<=n; ++i)
		if(w[i%n] == 2)
			b[0].push_back(x[i%n]);
	for(int i=n-1; i>=0; --i)
		if(w[i] == 1)
			b[1].push_back(x[i]);
	ll p[2] = {}, q = x[0], r = 0;
	for(int i=w[0]-1;; i=1-i){
//		cout << "q = " << q << " r = " << r << "\n";
		ll s = (b[i][p[i]] + (2*i-1)*r + l) % l;
//		cout << "s = " << s << "\n";
		if(i == 0){
			ll d = (s - q + l)%l;
//			cout << d << "\n";
			if(d%2 == 0){
				if(r + d/2 < t){
					q += d/2;
					r += d/2;
					q %= l;
				}else{
					q += t - r;
					r = t;
					q %= l;
				}
			}else{
				if(r + d/2 + 1 < t){
					q += d/2;
					r += d/2 + 1;
					q %= l;
				}else{
					q += t - r;
					r = t;
					q %= l;
				}
			}
		}else{
			ll d = (q - s + l)%l;
//			cout << d << "\n";
			if(d%2 == 0){
				if(r + d/2 < t){
					q += l - d/2;
					r += d/2;
					q %= l;
				}else{
					q += l - r - d/2 + t;
					r = t;
					q %= l;
				}
			}else{
				if(r + d/2 + 1 < t){
					q += l - d/2;
					r += d/2 + 1;
					q %= l;
				}else{
					q += l - r - d/2 - 1 + t;
					r = t;
					q %= l;
				}
			}
		}
		p[i] = (p[i]+1) % b[i].size();
		if(r == t) break;
	}
	cout << q << " " << r << "\n";
	for(int i=0; i<a.size(); ++i)
		if(a[i] == q)
			for(int j=0; j<a.size(); ++j)
				cout << a[(i+j)%n] << "\n";
}

