int main(){
  cin >> n >> l >> t;
  for(lli i = 0;i < n;i++) cin >> x[i] >> w[i];
  for(lli i = 0;i < n;i++){
    if(w[i] != w[0]){
      reverse_ants++;
      if(w[0] == 1){
        if((x[i]-x[0]+l)%l-t%l <= (t%l)) cross_ants++;
      }else{
        if((x[0]-x[i]+l)%l-t%l <= (t%l)) cross_ants++;
      }
    }
    cross_ants += reverse_ants*(t/l);
  }
  for(lli i = 0;i < n;i++){
    if(w[i] == 1) x[i] = (x[i]+t)%l;
    else{
      x[i] -= t;
