			if (w1.empty())
			{
				x = (x - t2 + t1 + L) % L;
				break;
			}
			int y = (w1.front() + t1) % L;
			int t3 = (x - y + 1) / 2;
			if (y > x)
				t3 = (L - y + x + 1) / 2;
			if (t2 - t1 < t3)
			{
				x = (x - t2 + t1 + L) % L;
				break;
			}
			w2.push(w2.front());
			w2.pop();
			w1.push(w1.front());
			w1.pop();	
			x = (y + t3) % L;
			t1 += t3;
			d = 1;
		}	
	}
	return x;
}

