	int N;
	int L;
	int T;
	cin >> N >> L >> T;
	multiset<int> goal;
	goal.clear();

	int X1;
	int w;
	int W1;
	cin >> X1 >> w;
	W1 = -2 * w + 3;

	int x1Goal = (X1 + W1 * T) % L;
	if (x1Goal < 0) {
		x1Goal += L;
	}
	goal.insert(x1Goal);

	vector<int> traitor(N - 1);
	traitor.clear();
	FOR(i, N - 1) {
		int X;
		int w;
