		W = -2 * w + 3;

		int xGoal = (X + W * T) % L;
		if (xGoal < 0) {
			xGoal += L;
		}
		goal.insert(xGoal);

		if (W != W1) {
			if (W1 == 1) {
				traitor.push_back(X - X1);
			}
			else {
				traitor.push_back(L - X + X1);
			}
		}
	}

	int rap = 2 * T / L;
	int rem = 2 * T % L;
	int conflictNum = rap * traitor.size() + distance(traitor.begin(), lower_bound(traitor.begin(), traitor.end(), rem));

	multiset<int>::iterator it = goal.find(x1Goal);
	if (W1 == 1) {
		FOR(i, conflictNum) {
			if (it == goal.begin()) {
				it = goal.end();
			}
			it--;
		}
	}
	else {
		FOR(i, conflictNum) {
			it++;
			if (it == goal.end()) {
				it = goal.begin();
			}
		}
	}

	FOR(i, N) {
		cout << *it << ENDL;
		it++;
		if (it == goal.end()) {
			it = goal.begin();
		}
	}

	return 0;
}

