	cin >> N >> L >> T;
	rep(i, 0, N) {
		cin >> A[i] >> W[i]; W[i]--;
	}
	ll cnt = 0;
	rep(i, 1, N) {
		if(W[i] != W[0]) {
			ll b; 
			if(W[0] == 0) b = A[i] - A[0];
			else b = L - (A[i] - A[0]);
			if(T < b) continue;
			if(T == b) cnt++;
			else {
				cnt += 1 + 2 * (T - b) / L;
			}
		}
	}
	cnt %= N;
	rep(i, 0, N) {
		ans[i] = W[i] == 0 ? (T + A[i]) % L : (L - (T - A[i] + L) % L) % L;
	}
	// debug(vl(ans, ans + N));
	rep(i, 0, N) {
		cout << ans[(i - cnt + N) % N] << "\n";
	}
}

