#define fst first
#define snd second
const ll UNDEF = -1;
const ll INF=1e18;
template<typename T> inline bool chkmax(T &aa, T bb) { return aa < bb ? aa = bb, true : false; }
template<typename T> inline bool chkmin(T &aa, T bb) { return aa > bb ? aa = bb, true : false; }
typedef pair<ll,ll> pll;
typedef vector<ll> vll;
void solve(long long N, long long L, long long T, vector<long long> X, vector<long long> W){
	vector<pll> v;
	ll sumtimes=0;
	assert(W[0]==1);
	for (ll i=1;i<N;i++) {
		if (W[i]!=W[0]) {
			ll diff;
			if (W[0]==1) {diff=(X[i]-X[0]+L)%L;}
			else {diff=(X[0]-X[i]+L)%L;}
			if (diff<0) diff+=L;
			ll times=((2*T+L-diff)/L)%N;
			if (W[0]!=1) times=N-times;
			assert(times>=0);
			sumtimes+=times;
			sumtimes%=N;
		}
	}
	for (ll i=0;i<N;i++) {
		ll dir=W[i]==1?1:-1;
		v.PB(MP(((X[i]+dir*T)%L+L)%L,i));
	}
	sort(v.begin(),v.end());
	ll newZeroIdx=-1;
	for (ll i=0;i<N;i++) {
		if (v[i].snd==0) {newZeroIdx=i; break;}
	}
	if (W[0]==2) {
		if (newZeroIdx!=N&&v[newZeroIdx]==v[(newZeroIdx+1)]) {
			newZeroIdx=(newZeroIdx+1);
		}
	}
	vector<ll> vans;
	vans.resize(N);
	for (ll i=0;i<N;i++) {
		vans[(i+sumtimes)%N]=v[(newZeroIdx+i)%N].fst;
	}
	for (ll i=0;i<N;i++) {
		printf("%lld\n",vans[i]);
	}
}

