int main() {
    ll i, t, kl, kr, km, x1, x2;
    scanf("%lld%lld%lld", &n, &l, &t);
    for(i=0; i<n; i++) {
        scanf("%lld%lld", &x[i], &w[i]);
        if(w[i]==2) w[i]=l-1;
        xe[i]=(x[i]+w[i]*t)%l;
    }
    sort(xe, xe+n);
    for(i=0; i<n; i++) if(w[i]==l-1)
        ip[np]=i, yyp[np]=x[i], np++;
    if(w[0]==1)
        in[nn]=0, yyn[nn]=x[0], nn++;
    for(i=n-1; i>0; i--) if(w[i]==1)
        in[nn]=i, yyn[nn]=-l+x[i], nn++;
    if(np==0 || nn==0) {
        outp((x[0]+w[0]*t)%l, 0);
        return 0;
    }
    kl=0; kr=2*t+1;
    while(kl<kr) {
        km=(kl+kr)/2;
        x1=getx(km);
        x2=getx(km+1);
        if(abs(x1-x2)>2*t) kr=km;
        else kl=km+1;
    }
    x1=getx(kl);
    if((w[0]==1 && kl%2==0) || (w[0]==l-1 && kl%2==1)) x2=1;
    else x2=l-1;
    outp((x1+x2*t)%l, (x2==1));
    return 0;
}

