// マイナスの割り算定義
int my_div(int a, int b) {
  if (a>0){
  return a%b; 
  }
  else{
    a = -a;
    if( a % b==0){
      return 0;
    }
    else{
       return b*( a/b + 1) - a;        
     }
  }
}

