        if(c == '1'){
            Dir[i] = true;
            destination[i] = (X[i] + T) % L;
        }
        else{
            Dir[i] = false;
            destination[i] = (X[i] - T) % L;
            if(destination[i] < 0) destination[i] = L + destination[i];
        }
    }
    long long int pos = 0;
    if(Dir[0]){
        for(int i = 1; i < n; ++i) if(not Dir[i]){
            long long int dist = X[i] - X[0]; if(dist <= 0) dist += L;
            // (dist + Lk) ≤ 2Tなる最大の k : k = (2T - dist) / L
            const long long int d = 2 * T - dist;
            if(d >= 0) pos += (d / L) + 1;
        }
        pos %= n;
    }
    else{
        for(int i = 1; i < n; ++i) if(Dir[i]){
            long long int dist = X[0] - X[i]; if(dist <= 0) dist += L;
            const long long int d = 2 * T - dist;
            if(d >= 0) pos -= (d / L) + 1;
        }
        pos %= n; if(pos < 0) pos += n;
    }

    const int zero_pos = destination[0];
    std::sort(destination.begin(), destination.end());
    int idx1 = std::lower_bound(destination.cbegin(), destination.cend(), zero_pos) - destination.cbegin();
