  // 座標自体は衝突を無視して計算すればいい
  // 各々がどの蟻かについては、x[0]の蟻についてT秒で衝突する蟻の個数を求める
  // それをそのまま足すか引くかすればその座標の蟻がどの蟻か決定する
  ll ant0 = 0;
  // x[0]にいた蟻について調査
  for (int i=1; i<N; i++){
    ant0 += w[0] * collision(x[0], w[0], x[i], w[i], T, L);
  }
  if (ant0 >= 0) ant0 %= N;
  else{ ant0 *= -1; ant0 %= N; ant0 = (N-ant0) % N; }

  // 座標を再計算
  for (int i=0; i<N; i++){
    x[i] = (x[i] + T * w[i] + L * 1000000000) % L;
  }
  // ant0 : x[0]の蟻が実際にはどの蟻か
  int index = ant0;
  int indexco = x[0];
  // 現在、蟻index は indexco にいる
  sort(all(x));
  // 各々の蟻は座標順に存在すると考えられる
  // ただし、同じ座標の蟻が存在しうる。この場合、w[0] = 1なら若い方、w[0] = -1なら若くない方。
  vector<int> res(N);
  res[index] = indexco;
  for (int j=0; j<N; j++){
    if (x[j] == indexco){
      if (x[(j-1+N)%N] == indexco) if (w[0] == 1) j = (j-1+N)%N;
      else if (x[(j+1)%N] == indexco) if (w[0] == -1) j = (j+1+N)%N;
      for (int i=0; i<N; i++){
        res[(i+index)%N] = x[(j+i)%N];
      }
      break;
    }
  }

  // たとえば1であれば、蟻0から蟻N-1の座標は各々x[N-1], x[0], x[1], ..., x[N-2] となる
  for (int i=0; i<N; i++){
    cout <<res[i] <<endl;
  }
}

