        if(b[i])
            v.pb((c[i]+t)%m),k+=(c[i]+t)/m;
        else
            v.pb(((c[i]-t)%m+m)%m),k+=(c[i]>t?(c[i]-t)/m:(c[i]-t-m+1)/m);
    sort(v.begin(),v.end());
    k=(k%n+n)%n;
    for(ll i=0;i<n;i++)
        ans[a[i].Y]=v[(i+k)%n]+1;
    for(ll i=0;i<n;i++)
        cout<<ans[i]-1<<'\n';
    return 0;
}

