int cnt(int a, int b) {
	for (; a < 0; a += l);
	for (; b >= l; b -= l);
	if (a < b) {
		if (b - a > 2 * t)return 0;
		return 1 + (2 * t - b + a) / (2 * l);
	}
	int dist = (l - a + b) / 2;
	if (l - a + b > 2 * t)return 0;
	return 1+(2*t-l+a-b)/2*l; 

}

