using namespace std;

typedef long long ll;
typedef pair<ll, int> pii;

int n;
ll l, t;
pii x[100005];

set<pii> Sp, Sn;

int query(int dir, ll loc){
  loc %= l;
  if (loc < 0) loc += l;
  if (dir == -1) return Sn.lower_bound({loc, 1e9})->y;
  else return (--Sp.lower_bound({loc, -1}))->y;
}

ll location(ll loc, int dir){

  ll tm = 0;

  while (true){
    loc %= l;
    if (loc < 0) loc += l;
    int nxt = query(-dir, loc + tm * dir);
    ll loc2 = x[nxt].x - dir * tm;
    loc2 %= l;
    if (loc2 < 0) loc2 += l;

    // TRACE(loc _ dir _ tm _ nxt _ loc2);

    if (dir == 1){
      if (loc2 <= loc) loc2 += l;
      loc2 = (loc+loc2) / 2;
      ll del = loc2-loc;
      if (tm+del > t) break;
      loc = loc2;
      tm += del;
      dir = -dir;
    } else {
      if (loc2 >= loc) loc2 -= l;
      loc2 = (loc+loc2) / 2;
      ll del = loc-loc2;
      if (tm+del > t) break;
      loc = loc2;
      tm += del;
      dir = -dir;
    }
  }

  loc += dir * (t-tm);
  loc %= l;
  if (loc < 0) loc += l;

  return loc;

}

ll red(ll a){
  a %= l;
  if (a < 0) return a+l;
  return a;
}

