#include<bits/stdc++.h>
using namespace std;

struct Ant {int x, w, z=-1;};

int main() {
  int N, L, T;
  cin >> N >> L >> T;
  vector<Ant> ant(N);
  for(auto& a: ant) cin >> a.x >> a.w;

  ant[0].z = 0;
  for(auto a: ant) if(ant[0].w!=a.w) {
    if(ant[0].w==1) {
      auto d = a.x-ant[0].x;
      if(d <= 2*T) ant[0].z += (2*T - d)%L + 1;
      ant[0].z %= N;
    } else {
      auto d = L-a.x+ant[0].x;
      if(d <= 2*T) ant[0].z -= (2*T - d)%L + 1;
      ant[0].z %= N;
      if(ant[0].z < 0) ant[0].z += N;
    }
  }

  for(auto& a: ant) {
    if(a.w==1) {
      a.x += T%L;
      a.x %= L;
    } else {
      a.x -= T%L;
      a.x %= L;
      if(a.x < 0) a.x += L;
    }
  }

  sort(begin(ant), end(ant), [](auto l, auto r) {return l.x!=r.x ? l.x<r.x : l.w<r.w;});

  auto s=0;
  for(auto i=0; i<N; ++i) if(ant[i].z!=-1) {
    s=i;
    if(ant[(i-1+N)%N].x == ant[i].x) {
      s=(i-1+N)%N;
      ant[s].z = ant[i].z;
    }
    if(ant[(i+1)%N].x == ant[i].x) {
      s=i;
      ant[s].z -= 1;
      if(ant[s].z < 0) ant[s].z += N;
    }
  }
  for(auto i=1; i<N; ++i) {
    auto& a = ant[(s+i)%N];
    auto& p = ant[(s+i-1)%N];
    a.z = (p.z+1)%N;
  }

  sort(begin(ant), end(ant), [](auto l, auto r) {return l.z < r.z;});

  for(auto a: ant) cout << a.x << endl;
}

#include <bits/stdc++.h>

using namespace std;
typedef long long LL;

const int N=2e5+10;

int n,L,T,pos[N],w[N],ans[N];

void Init()
{
	scanf("%d%d%d",&n,&L,&T);
	for (int i=0;i<n;++i) 
	{
		scanf("%d%d",&pos[i],&w[i]);
		if (w[i]==2) w[i]=-1;
	}
}
void Solve()
{
	LL cg=0;
	for (int i=0;i<n;++i)
	{
		LL epos=pos[i]+1ll*w[i]*T;
		if (epos<0) cg-=-epos/L+1;
		else cg+=epos/L;
		ans[i]=(epos%L+L)%L;
		cg%=n;
	}
	sort(ans,ans+n);
	for (int i=0;i<n;++i) printf("%d\n",ans[(i+cg+n)%n]);
}

int main()
{
	Init();
	Solve();
	return 0;
}

