        long long cnt = c;
        for (int i = 0; i < n; i++) {
            if (w[i] == w[c]) continue;
            if (w[c] == 1) {
                long long d = (x[i] - x[c] + l) % l;
                if (t * 2 < d) continue;
                long long remain = t * 2 - d; cnt++;
                cnt += remain / l;
            } else {
                long long d = (l + x[i] - x[i]) % l;
                if (t * 2 < d) continue;
                long long remain = t * 2 - d; cnt--;
                cnt -= remain / l;
            }
        }
        return (cnt % n + n) % n;
    };
    int idx0 = calc(0), idx1 = calc(1);
    vector<long long> ans(n, -1);
    int prev = -n;
    for (int i = 0; i < n; i++) {
        int t = calc(place[i].second);
        ans[t] = place[i].first;
        if (prev + 1 == t) {
            for (int j = i+1; j < n; j++) {
                ans[(t-i+j) % n] = place[j].first;
            }
            break;
        }
        prev = t;
    }
    for (auto &c: ans) cout << c << "\n";
    return 0;
}

