const int N = 1e5 + 10;

int L, t;


int get_dist(vi & ones, vi & zeros, int mone, int mzero, int mo, int mz) {
    int dist = zeros[(mzero + mz) % SZ(zeros)] + L * ((mzero + mz) / SZ(zeros));
    dist -= ones[(mone + mo) % SZ(ones)] - L * ((mone + mo) / SZ(ones));
    return dist;
}

void solve(vector<pii> pts, vi & ans) {

    vi ones, zeros;
    int n = SZ(pts);


    fori (i, n) {
        if (pts[i].second) {
            ones.push_back(pts[i].first);
        } else {
            zeros.push_back(pts[i].first);
        }
    }

    sort(RALL(ones));
    sort(ALL(zeros));

    if (min(SZ(ones), SZ(zeros)) == 0) {
        fori (i, n) {
            if (pts[i].second) {
                ans[i] = pts[i].first + t;
            }
        }
        return;
    }

    fori (i, n) {
        if (pts[i].second) {
            int mone = lower_bound(ALL(ones), pts[i].first, [&](int i, int j) -> bool {
                return i > j;
            }) - ones.begin();
            int mzero = lower_bound(ALL(zeros), pts[i].first) - zeros.begin();
            int l = -1, r = 2e9;
            while (r - l > 1) {
                int m = r + l >> 1;
                int dist = get_dist(ones, zeros, mone, mzero, m, m);
                if (dist <= t * 2) {
                    l = m;
                } else {
                    r = m;
                }
            }
            if (l == -1) {
                ans[i] = pts[i].first + t;
            } else {
                int dist = get_dist(ones, zeros, mone, mzero, l + 1, l);
                if (dist <= t * 2) {
                    ans[i] = ones[(mone + l + 1) % SZ(ones)] + t;
                } else {
                    ans[i] = zeros[(mzero + l) % SZ(zeros)] - t;
                }
            }
        }
    }

}

void smain() {

    int n;
    cin >> n >> L >> t;
    vector<pii> pts(n);
    fori (i, n) {
        cin >> pts[i].first >> pts[i].second;
        pts[i].second &= 1;
    }


    vi ans(n, -1);

//    t %= L;

    solve(pts, ans);

    reverse(ALL(pts));
    reverse(ALL(ans));
    for (auto & x : pts) {
        x.second ^= 1;
        x.first = L - x.first - 1;
    }

    solve(pts, ans);
    reverse(ALL(ans));
    reverse(ALL(pts));

    fori (i, n) {
        if (pts[i].second) {
            ans[i] = L - ans[i] - 1;
        }
        ans[i] = (L + ans[i] % L) % L;
        cout << ans[i] << ' ';
    }



}

