    }
    t[i]=f(t[i]);
  }

  for(int i=0;i<n;i++){
    x[i+n]=x[i]+l;
    w[i+n]=w[i];
    t[i+n]=t[i];
  }
  for(int i=1;i<=n*2;i++){
    sum[i]=sum[i-1];
    if(w[i-1]==1)sum[i]++;
  }
  solve();
 for(int i=0;i<n;i++)
    cout<<ans[i]<<endl;
  return 0;
}

