void move(vector<pair<int, int>> &ants, int n, int l, int time) {
    for (int i = 0; i < n; i++) {
        int *p;
        p = &ants[i].first;
        if (ants[i].second == 1) {
            if (*p + time < l) *p += time;
            else *p = time - (l - *p);
        }
        else {
            if (*p - time >= 0) *p -= time;
            else *p = l - (time - *p);
        }
    }
}

bool bump(vector<pair<int, int>> &ants, int n, int l, int &t) {
    int ret = l * 10;
    pair<int, int> bumpants;
    for (int i = 0; i < n; i++) {
        int distance = 0;
        if (ants[i].second == 1) {
            if (i < n - 1) {
                if (ants[i + 1].second == 2) {
                    distance = ants[i + 1].first - ants[i].first;
                    if (distance < ret && distance) {
                        ret = distance;
                        bumpants = make_pair(i, i + 1);
                    }
                }
            }
            else {
                if (ants[0].second == 2) {
                    distance = l - ants[i].first + ants[0].first;
                    if (distance < ret) {
                        ret = distance;
                        bumpants = make_pair(i, 0);
                    }
                }
            }
        }
    }

    bool flag = false;
    if (t >= ret) {
        move(ants, n, l, ret / 2);
        t -= ret / 2;
        flag = true;
    }
    else {
        move(ants, n, l, t);
    }

    if (flag) {
        ants[bumpants.first].second = 2;
        ants[bumpants.second].second = 1;
    }

    return flag;
}

