		now_position += input[i].second * t;
		now_position %= l;
		now_position += l * (abs(now_position) / l + 1);
		now_position %= l;
		positions.push_back(now_position);
	}
	int starter = positions[0];
	sort(positions.begin(), positions.end());
	int now_cnt = 0;
	for (int i = 1; i < n; ++i) {
		if (input[i].second != input[0].second) {
			if (input[0].second == 1) {
				int first_step = input[i].first - input[0].first;
				int now_ans = 2*t;
				if (first_step < now_ans) {
					now_ans -= first_step;
					now_cnt += 1 + (now_ans - 1) / l;
					now_cnt %= n;
				}
			}
			else {
				int first_step = (l - input[i].first) + input[0].first;
				int now_ans = 2 * t;
				if (first_step < now_ans) {
					now_ans -= first_step;
					now_cnt += 1 + (now_ans-1) / l;
					now_cnt %= n;
				}
			}
		}
	}
	int now_itr = 0;
	if (input[0].second == 1) {
		for (int i = 0; i < positions.size(); ++i) {
			if (positions[i] == starter) {
				now_itr = i;
				break;
			}
		}
	}
	else {
		for (int i = positions.size() - 1; i >= 0; --i) {
			if (positions[i] == starter) {
				now_itr = i;
				break;
			}
		}
	}
	for (int i = 0; i < n; ++i) {
		ans[now_cnt] = positions[(now_itr+i)%n];
		now_cnt++;
		now_cnt %= n;
	}
	REP(i, n) {
		cout << ans[i] << endl;
	}
	return 0;
}

