			l = X[0],r = X[i];
		}
		else{
			l = X[i],r = X[0] + L;
		}
		if(T*2 < r-l) continue;
		ll S = 2*T - (r-l);
		cnt += (N + (W[0]==1?1:-1)*(1 + S/L)%N )%N;
		cnt %= N;
	}
	ll C = T%L;
	for(int i = 0; i < N; ++i) {
		if(W[i] == 1) (X[i] += T) %= L;
		else (X[i] += L - C) %= L;
	}
	sort(ALL(X));
	for(int i = 0; i < N; ++i) Y[i] = X[(i+cnt)%N];
	for(int i = 0; i < N; ++i) cout << Y[i] << endl;


    return 0;
}

