	if ((dst + 1) / 2 <= my_time) {
		my_time -= (dst + 1) / 2;
		++result;
		dst = l - dst % 2;
		if (my_time >= (dst + 1) / 2) {
			++result;
		}
	}
	return result;
}

int go(int pos, int val) {
	long long cnt = 0;
	REP(i, n) {
		if (w[i] != w[pos]) {
			cnt += bumps(pos, i);
			cnt %= n;
		}
	}
	if (w[pos] == 2) {
		return (pos - cnt + n) % n;
	}

	return (pos + cnt) % n;
}

