	int result = 0;
	REP(i, n) {
		if (b[i] == val) {
			if (i + 1 < n && b[i + 1] == val) {
				if (w[rnd] == 1) {
					result = i;
				} else {
					result = i + 1;
				}
			} else {
				result = i;
			}
			result = i;
