void solve()
{
    int left = 2 * T % L;
    int cntall = 0, cntlast = 0;
    for (int i = 1; i < N; ++i) {
        if (D[i] != D[0]) {
            cntall += 1;
            cntlast += (X[i] - X[0] <= left);
        }
    }
    int d = ((LL)(2 * T / L) * cntall + cntlast) % N;
    int id = D[0] == 1 ? d : (N - d) % N;

    static int pos[MAXN];

    int T0 = T % L;
    for (int i = 0; i < N; ++i) {
        if (D[i] == 1)
            pos[(i + id) % N] = (X[i] + T0) % L;
        else
            pos[(i + id) % N] = (X[i] - T0 + L) % L;
    }

    for (int i = 0; i < N; ++i) {
        printf("%d\n", pos[i]);
    }
}

