      i64 d = (x2 != x) ? modL(x2 - x) : L;
      DEBUG(t, x, x2, lp, d);
      if (t + d / 2 >= T) {
        return {modL(x + T - t), 1};
      }
      t += (d + 1) / 2;
      x = modL(x2 - (d + 1) / 2);
      auto [x3, i3] = rx[rp];
      x3 = modL(x3 + t);
      rp = (rp + rsize - 1) % rsize;
      d = (x3 != x) ? modL(x - x3) : L;
      DEBUG(t, x, x3, rp, d);
      if (t + d / 2 >= T) {
        return {modL(x - (T - t)), 2};
      }
      t += (d + 1) / 2;
      x = modL(x3 + (d + 1) / 2);
    }
    return {-1, -1};
  };
