		}
	}
	sort(at, at + n);
	v1 = model(shift, t % l);
	v2 = model((shift + 1) % n, t % l);
	FOR(i, 0, n) {
		int ne = i + 1;
		if (ne == n) {
			ne = 0;
		}
		if ((v1 == at[i]) && (v2 == at[ne])) {
			shift = i;
			break;
		}
	}
