typedef long long ll;
ll get(ll d, vector<ll>v1, vector<ll>v2, ll t)
{
	ll now = 0, na = 0, nb = 0;
	int pa = v1.size() - 1, pb = 0;
	//for (int i = 0; i < v1.size(); i++)printf("%lld ", v1[i]); printf("\n");
	//for (int i = 0; i < v2.size(); i++)printf("%lld ", v2[i]); printf("\n");
	for (;;)
	{
		if (d == 1)
		{
			ll x = v2[pb] - nb;
			if (x > t)
			{
				now += t;
				break;
			}
			pb++;
			nb += x;
			now += x;
			d = 2;
			t -= x;
		}
		else
		{
			ll x = na - v1[pa];
			if (x > t)
			{
				now -= t;
				break;
			}
			pa--;
			na -= x;
			now -= x;
			d = 1;
			t -= x;
		}
		//printf("---%lld\n", now);
	}
	return now;
}
