const int N=100007;
int n,l,t;
struct pos{
	int x,v;
	bool operator!=(const pos&w)const{return x!=w.x||v!=w.v;}
	bool operator<(const pos&w)const{return x!=w.x?x<w.x:v<w.v;}
	void mov(int d){
		x=((x+d*v)%l+l)%l;
	}
}ps[N];
int min(int a,int b){return a<b?a:b;}
int as[N],ap=0,bs[N],bp=0;
int main(){
	scanf("%d%d%d",&n,&l,&t);
	for(int i=0,x,v;i<n;++i){
		scanf("%d%d",&x,&v);
		ps[i]=(pos){x,v==2?-1:1};
		if(i){
			if(v==2)as[ap++]=x;
			else bs[bp++]=x;
		}
	}
	pos p0=ps[0];
	int now=0;
	std::sort(as,as+ap);as[ap]=as[0]+l;
	std::sort(bs,bs+bp,std::greater<int>());bs[bp]=bs[0]-l;
	int t0=t;
	t%=l*2;
	while(now<t){
		if(p0.v==1){
			if(ap){
				int xd=(p0.x+now)%l;
				xd=*std::lower_bound(as,as+ap,xd)-xd;
				if(xd&1){
					int z=min(t-now,xd/2+1);
					now+=z;
					p0.mov(min(z,xd/2));
					if(z==xd/2+1)p0.v*=-1;
				}else{
					int z=min(t-now,xd/2);
					now+=z;
					p0.mov(z);
					if(z==xd/2)p0.v*=-1;
				}
			}else{
				p0.mov(t-now);
				now=t;
			}
		}else if(bp){
			int xd=((p0.x-now)%l+l)%l;
			xd-=*std::lower_bound(bs,bs+bp,xd,std::greater<int>());
			if(xd&1){
				int z=min(t-now,xd/2+1);
				now+=z;
				p0.mov(min(z,xd/2));
				if(z==xd/2+1)p0.v*=-1;
			}else{
				int z=min(t-now,xd/2);
				now+=z;
				p0.mov(z);
				if(z==xd/2)p0.v*=-1;
			}
		}else{
			p0.mov(t-now);
			now=t;
		}
	}
	for(int i=0;i<n;++i)ps[i].mov(t0);
	std::sort(ps,ps+n);
	int w=0;
	while(ps[w]!=p0)++w;
	for(int i=0;i<n;++i)printf("%d\n",ps[(w+i)%n].x);
	return 0;
}

