	int mid=a[(l+r)/2];
	while (i<j){
		while (a[i]<mid) i++;
		while (a[j]>mid) j--;
		if (i<=j){
			int p;
			p=a[i]; a[i]=a[j]; a[j]=p;
			p=w[i]; w[i]=w[j]; w[j]=p;
			p=b[i]; b[i]=b[j]; b[j]=p;
			i++;
			j--;
		}
	}
	if (l<j) qsort(l,j);
	if (i<r) qsort(i,r);
} 
