			sum+=(ll)m*(mid/(2*l1))+(ll)m*((mid+1)/(2*l2));
			x1=(mid/2)%l1; x2=((mid+1)/2)%l2;
			R1=(now-1)%l1+1; L1=(R1-x1+l1-1)%l1+1;
			L2=i; R2=(i+x2-1)%l2+1;
