			sum+=L2<=R2?b[R2]-b[L2]:m+b[R2]-b[L2];
			if(sum<=x)L=mid; else R=mid-1;
		}
		if(L&1)ans[pos2[i]]=p2[(i+((L+1)/2)%l2-1)%l2+1];
		else ans[pos2[i]]=p1[((now-1)%l1+1-(L/2)%l1+l1-1)%l1+1];
	}
	for(int i=1; i<=n; i++)printf("%d\n", ans[i]);
	return 0;
}

