void input ()
{
	// input method

	scanf ( "%d%d%d", &n, &l, &t );
	lpi ( i, 1, n ) scanf ( "%d%d", &x[i], &d[i] );
}

void work ()
{
	// main work

	lpi ( i, 1, n ){
		if ( d[i] == 1 ) ans[i] = ( x[i] + t ) % l;
		else ans[i] = ( ( x[i] - t ) % l + l ) % l;
	}

	int tp1 = ans[1];
	sort ( ans+1, ans+1+n );
	int p1 = -1;
	lpi ( i, 1, n ) if ( ans[i] == tp1 ) { p1 = i; break; }

	LL cc = 0;
	if ( d[1] == 1 ){
		lpi ( i, 1, n ){
			if ( d[i] == 2 ) cc += divi ( ( t - ( ( x[i] - x[1] ) / 2 + 1 ) ), l ) + 1;
		}
	} else if ( d[1] == 2 ){
		lpi ( i, 1, n ){
			if ( d[i] == 1 ) cc -= divi ( ( t - ( ( x[1] + l - x[i] + 1 ) / 2 ) ), l ) + 1;
		}
	}

	cc %= n;
	( cc += n ) %= n;

	p1 -= cc;
	if ( p1 <= 0 ) p1 += n;
	lp ( i, 0, n ) printf ( "%d\n", ans[( p1+i-1 )%n+1] );
}

