    while ((ch<'0') || (ch>'9')) {if (ch=='-') f=-1;ch=getchar();}
    while ((ch>='0') && (ch<='9')) {x=x*10+(ch-'0');ch=getchar();}
    return x*f;
}

int main()
{
    n=read();l=read();t=read();int i;
    for (i=1;i<=n;i++)
    {
        int now=read(),face=read();
        if (face==1)
        {
            pos[i]=(now+t)%l;
            rk+=((now+t)/l);
        }
        else if (face==2)
        {
            pos[i]=(now-t)%l;
            if (pos[i]<0) {pos[i]+=l;rk--;}
