pair<int,int> a[200000];

int main() {
  int n,L,t;
  scanf("%d%d%d",&n,&L,&t);
  for(int i=0;i<n;i++){
    scanf("%d%d",&a[i].first,&a[i].second);
    if(a[i].second==1){
      a[i].first+=t-L;
    }
    else{
      a[i].first-=t;
    }
  }
  pair<int,int> cur=a[0];
  int r=1,l=n-1;
  while(r<=l){
    if(cur.second==1){
      if(a[r].second!=2 || a[r].first>cur.first){
        r++;
        continue;
      }
      cur=a[r];
      r++;
    }
    else{
      if(a[l].second!=1 || a[l].first<cur.first){
        l--;
        continue;
      }
      cur=a[l];
      l--;
    }
  }
  int init = cur.first%L;
  for(int i=0;i<n;i++){
    if(a[i].first<0)
      a[i].first+=L;
    a[i].first=(a[i].first)%L;
  }
  sort(a,a+n);
  for(int i=0;i<n;i++){
    if(a[i].first==init){
      init=i;
      break;
    }
  }
  for(int i=0;i<n;i++){
    printf("%d\n",a[(init+i)%n].first);
  }
}

#include<cstdio>
