using namespace std;

int main() {
    int N, L, T;
    int antX[100000];
    int antW[100000];
    cin >> N >> L >> T;
    for (int i = 0; i < N; ++i) {
        cin >> antX[i] >> antW[i];
    }

    int newAntX[100000];
    int zekken[100000];
    int suretigai[100000];
    for (int i = 0; i < N; ++i) {
        if (antW[i] == 1) {
            newAntX[i] = antX[i] + T;
        } else{
            newAntX[i] = antX[i] - T;
        }
        if (newAntX[i] >= L) {
            newAntX[i] -= L;
        } else if (newAntX[i] < 0) {
            newAntX[i] += L;
        }
        for (int j = 0; j < N; ++j) {
            if (i == j) {
                continue;
            }
            if (antW[i] != antW[j]) {
                double firstTime;
                double diff = antX[i] - antX[j];
                if (diff < 0) {
                    diff += L;
                }
                firstTime = diff / 2.0;
                if (firstTime > 0) {
                    suretigai[i] += 1;
                }
                suretigai[i] += (int) (2 * (T - firstTime)) / L;
            }
        }
        if (antW[i] == 1) {
            zekken[i] = i + suretigai[i];
        } else{
            zekken[i] = i - suretigai[i];
            while (zekken[i] < 0) {
                zekken[i] += N;
            }
        }
        zekken[i] = zekken[i] % N;
    }

    for (int i = 0; i < N - 1; ++i) {
        for (int j = i + 1; j < N; ++j) {
            if (zekken[j] < zekken[i]) {
                int tmpZekken = zekken[i];
                zekken[i] = zekken[j];
                zekken[j] = tmpZekken;
                int tmpX = newAntX[i];
                newAntX[i] = newAntX[j];
                newAntX[j] = tmpX;
            }
        }
    }
    for (int i = 0; i < N; ++i) {
        cout << newAntX[zekken[i]] << endl;
    }
    return 0;
}

