int main()
{
    i64 n , L , T ;

    scanf("%lld %lld %lld",&n,&L,&T) ;

    i64 cl = 0 , anticl = 0 ;

    for(int i=1 ; i<=n ; i++)
    {
        scanf("%lld %lld",&pos[i],&type[i]) ;
        if(type[i]==1) cl++ ;
        else anticl++ ;

        if( type[i] == 1 ) nextPos[i] = (pos[i]+T)%L ;
        else nextPos[i] = ((pos[i]-T)%L + L)%L ;
    }

    sort( nextPos+1 , nextPos+n+1 ) ;

    if( type[1] == 1 )
    {
        i64 collision = 0 ;
        collision = 2LL*(T/L)*anticl ;

        i64 p = (T+pos[1])%L ;

        for(int i=2 ; i<=n ; i++)
        {
            if(type[i]==1) continue ;

            if( ( pos[i]-pos[1] ) <= 2*(T%L) )
            {
                collision++ ;
                if( pos[1]+L-pos[i] <= (2*(T%L) - ( pos[i]-pos[1] )) ) collision++ ;
            }
        }

        collision %= n ;
        int idx = collision+1 ;

        int start = 1 ;

        for(int i=1 ; i<=n ; i++)
        {
            if( nextPos[i] == p  ) start = i ;
        }
        for(int i=start , j=1 ; j<=n ;  j++ )
        {
            ans[idx] = nextPos[i] ;

            idx++ ; if(idx>n) idx -= n ;
            i++ ; if(i>n) i -= n ;
        }
   //     return 0 ;
    }
    else{
        i64 collision = 0 ;
        collision = 2LL*(T/L)*cl ;

        i64 p = ( (pos[1]-T)%L + L )%L ;

