            if( (pos[1] + L-pos[i] ) <= 2*(T%L) )
            {
                collision++ ;
                if( (pos[i]-pos[1]) <= (2*(T%L) - (pos[1] + L-pos[i] )) ) collision++ ;
            }
        }
        collision %= n ;

        int idx = 1 ;

        if(collision > 0) idx = n-collision+1 ;

        int start ;

        for(int i=n ; i>=1 ; i--)
        {
            if( nextPos[i] == p ) start = i ;
        }

        for(int j=1 , i= start ; j<=n ; j++)
        {
            ans[idx] = nextPos[i] ;
            i++ ; idx++ ;
            if(i > n) i -= n ;
            if(idx > n) idx -= n ;
        }
