    REP(i, n) cin >> X[i] >> W[i];
    vector<ll> Y(n);
    REP(i, n) {
        Y[i] = ((X[i] + (W[i] == 1 ? 1 : -1) * T) % L + L) % L;
    }
    vector<ll> Y0 = Y;
    sort(ALL(Y));
    ll hit = 0;
    REP(i, n) {
        if (W[i] == W[0]) continue;
        ll len = W[0] == 1 ? X[i]-X[0] : X[0]-X[i];
        if (len < 0) len += L;
        // cout << i << " " << len << endl;
        if (len < T*2) {
            hit += (T*2 - len - 1)/(L*2)+1;
        }
    }
    // cout << hit << endl;
    ll idx = hit * (W[0] == 1 ? 1 : -1);
    REP(i, Y.size()) {
        if (Y[i] == Y0[0]) {
            idx -= i;
            if (i+1 < Y.size() && Y[i+1] == Y[i] && W[0] == 2) {
                --idx;
            }
            break;
        }
    }
    idx = (idx % n + n) % n;
    vector<ll> ans(n, -1);
    REP(i, Y.size()) {
        ans[(idx+i)%n] = Y[i];
    }
    REP(i, n) cout << ans[i] << endl;
}

#include <bits/stdc++.h>

using namespace std;

const int N = 100 * 1000 + 17;
const int MOD = 1000 * 1000 * 1000 + 7;

int n, L, t;
int a[N], w[N];

bool read() {
    if (!(cin >> n >> L >> t))
        return false;

    for (int i = 0; i < n; ++i)
        cin >> a[i] >> w[i];

    return true;
}

void solve() {
    vector< pair<int, int> > b;

    for (int i = 0; i < n; ++i)
        b.emplace_back((L + (a[i] + t * (w[i] == 1 ? 1 : -1)) % L) % L, i);

    sort(b.begin(), b.end());
    auto kek = 0;

    for (int i = 0; i < n; ++i)
        if (w[i] != w[0])
            ++kek;

    auto cnt = (w[0] == 0 ? 1ll : -1ll) * kek * ((2 * t) / L);
    t = (2 * t) % L;

    for (int i = 0; i < n; ++i)
        if (w[i] != w[0])
            if (w[0] == 1 && (a[i] - a[0] + L) % L <= t)
                ++cnt;
            else if (w[0] == 2 && (a[0] - a[i] + L) % L <= t)
                --cnt;

    cnt = (cnt % n + n) % n;
    vector<int> ans(n);

    for (int i = 0; i < n; ++i)
        ans[(i + n - cnt) % n] = b[i].first;

    for (auto i : ans)
        cout << i << endl;
}

int32_t main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    while (read())
        solve();

    return 0;
}

