  for(long long int i=0;i<N;i++){
    cin>>X.at(i)>>W.at(i);
    H.at(i)=X.at(i);
  }
  for(long long int i=0;i<N;i++){
    if(W.at(i)==1)X.at(i)=(X.at(i)+T)%L;
    else X.at(i)=(X.at(i)-T+L)%L;
