using namespace std;
using namespace __gnu_pbds;
typedef long long ll;
const int MAX = (1e5)+1;

ll n, l, t, m, x[MAX], w[MAX], cnt[2], f[MAX], res[MAX];
tree<ll, null_type, less_equal<ll>, rb_tree_tag, tree_order_statistics_node_update> lls, lms;
tree<ll, null_type, greater_equal<ll>, rb_tree_tag, tree_order_statistics_node_update> gls, gms;
int main() {
	ios::sync_with_stdio(false);
	cin.tie(0);
	cin >> n >> l >> t;
	m = t%l;
	for(int i = 0; i < n; i++) {
		cin >> x[i] >> w[i];
		cnt[--w[i]]++;
	}
	for(int i = 0; i < n; i++) if(!w[i]) gms.insert(x[i]);
	for(int i = 0; i < n; i++) {
		if(w[i]) {
			ll fl = gls.order_of_key(x[i]-2*m) + gls.order_of_key(x[i]-2*(m-l));
			ll fm = gms.order_of_key(x[i]+l-2*m) + gms.order_of_key(x[i]+l-2*(m-l));
			res[(n+i-(fl+fm)%n)%n] = (x[i]-m+l)%l;
		} else {
			gls.insert(*gms.begin());
			gms.erase(gms.begin());
		}
	}
	for(int i = 0; i < n; i++) if(w[i]) lms.insert(x[i]);
	for(int i = 0; i < n; i++) {
		if(!w[i]) {
			ll fl = lls.order_of_key(x[i]-l+2*m) + lls.order_of_key(x[i]-l+2*(m-l));
			ll fm = lms.order_of_key(x[i]+2*m) + lms.order_of_key(x[i]+2*(m-l));
			res[(i+fl+fm)%n] = (x[i]+m)%l;
		} else {
			lls.insert(*lms.begin());
			lms.erase(lms.begin());
		}
	}
	for(int i = 0; i < n; i++) cout << res[i] << endl;
}

