int main(void)
{
	int N, L, T;
	cin >> N >> L >> T;
	vector<pair<int, int>> ant(N);
	for (auto &i : ant)
	{
		cin >> i.first >> i.second;
		i.second = 3 - i.second * 2;
	}
	bool is_same_W = true;
	for (auto &i : ant) if (ant[0].second != i.second) { is_same_W = false; break; }
	if (is_same_W)
	{
		auto W = ant[0].second;
		auto d = (T % L) * W + L;
		for (auto &i : ant)
		{
			i.first += d;
			i.first %= L;
		}
	}
	else
	{
		L *= 2;
		T *= 2;
		for (auto &i : ant) i.first *= 2;
		int W;
		int first = 0, next;
		int d, t;
		while (T)
		{
			W = ant[first].second;
			for (next = (first + N + W) % N; ant[next].second == W; next = (next + N + W) % N);
			t = ant[next].first - ant[first].first;
			d = ((t * W > 0) ? abs(t) : L - abs(t)) / 2;
			t = min(d, T);

			T -= t;
			for (auto &i : ant)
			{
				i.first += (L + t * i.second);
				i.first %= L;
			}
			auto pos = ant[first].first;
			sort(ant.begin(), ant.end());
			auto res = find(ant.begin(), ant.end(), make_pair(pos, ((t < d) ? W : -W)));
			first = res - ant.begin();
		}
		for (auto &i : ant) i.first /= 2;
		rotate(ant.begin(), ant.begin() + first, ant.end());
	}
	for (auto &i : ant) cout << i.first << endl;
	return 0;
}

