  {
    if (W.at(i) == 1)
    {
      pos.at(i) = (X.at(i) + T) % L - 0.1;
      if (pos.at(i) < 0)
      {
        pos.at(i) += L;
      }
    }
    else
    {
      pos.at(i) = (X.at(i) - (T % L) + L) % L + 0.1;
    }
  }
  double p0 = pos.at(0);
  sort(pos.begin(), pos.end());
  int start = lower_bound(pos.begin(), pos.end(), p0) - pos.begin();
  int n = 0, x = X.at(0), w = W.at(0);
  for (int i = 1; i < N; i++)
  {
    if (W.at(i) == w)
    {
      continue;
    }
    int d = X.at(i) - x;
    if (w == 2)
    {
      d = L - d;
    }
    if (d < 2 * (T - 0.1))
    {
      if (w == 1)
      {
        n++;
        continue;
      }
      n = (n + N - 1) % N;
    }
  }
  vector<double> ans(N);
  for (int i = start; i < start + N; i++)
  {
    ans.at(n % N) = round(pos.at(i % N));
    if (ans.at(n % N) > L - 0.1)
    {
      ans.at(n % N) -= L;
