        }
        if(W[0] != W[i]){
            // 2*T >= (n - 1)*L + dist
            long long n = 0;
            if(2*T >= dist){
                n = (2*T - dist) / L + 1;
            }
            meet_count += n;
        }
    }
    //cout << meet_count << endl;
    int start;
    for(int i = 0; i < N; i++){
        if(X_after[i].second == (meet_count) % N){
            start = i;
        }
