  cin>>n>>l>>t;
  int x[n],w[n];
  REP(i,n){
    cin>>x[i]>>w[i];
  }
  vector<int> pos;
  REP(i,n){
    int temp = x[i];
    if(w[i] == 1){
      temp += t;
      temp %= l;
    }else{
      temp -= t%l;
      if(temp < 0){
        temp += l;
      }
      temp %= l;
    }
    pos.push_back(temp);
  }

  bool clockwise = false;
  int pivot = 0;
  int cnt = 0;
  REP(i,n){
    if(i == 0){
      if(w[i] == 1){
        clockwise = true;
      }
      continue;
    }
    int temp;
    if(w[i] == 1){
      if(clockwise)continue;
      temp = 2*t-(x[i]-x[0]);
      if(temp <= 0)continue;
      cnt += 1 + (temp-1)/l;
    }else{
      if(!clockwise)continue;
      temp = 2*t-(l-(x[i]-x[0]));
      if(temp <= 0)continue;
      cnt += 1 + (temp-1)/l;
    }
    if(clockwise){
      pivot += cnt;
      pivot %= n;
    }else{
      pivot = n;
      pivot -= cnt%n;
    }
  }

  int ans[n];
  int pos0 = pos[0];
  sort(ALL(pos));
  int index = lower_bound(ALL(pos), pos0) - pos.begin();
  REP(i,n){
    ans[(pivot + i)%n] = pos[(index + i)%n];
  }
  REP(i,n){
    cout<<ans[i]<<endl;
  }
  return 0; 
}

