#include <bits/stdc++.h>

using namespace std;

typedef long long ll;
typedef long double ld;

#define mp make_pair
#define ff first
#define ss second
#define pb push_back
#define pf push_front
#define popb pop_back
#define popf pop_front
#define all(v) v.begin(),v.end()

const int maxn = 1e5 + 100;
const ll inf = 2e18, mod = 1e9 + 7;

int n, w[maxn], ans;
ll l, t, x[maxn], y[maxn];
vector<pair<ll, int> > ants[3];

void solve() {
	ll currentTime = 0;
	int now = 0;
	while (currentTime < t) {
		if (w[now] == 1) {
			ll key = (x[now] + 2 * currentTime) % l;
			int ind = lower_bound(all(ants[2]), mp(key, -1)) - ants[2].begin();
			if (ind == ants[2].size()) {
				ind = lower_bound(all(ants[2]), mp(key - l, -1)) - ants[2].begin();
			}
			ind = ants[2][ind].ss;
			ll dist = ((x[ind] - currentTime + l) % l - (x[now] + currentTime) % l + l) % l;
			if ((dist + 1) / 2 > t - currentTime) {
				currentTime = t;
			}
			else {
				currentTime += (dist + 1) / 2;
				now = ind;
			}
		}
		else {
			ll key = (x[now] - 2 * currentTime) % l;
			int ind = upper_bound(all(ants[1]), mp(key, -1)) - ants[1].begin();
			ind--;
			if (ind < 0) {
				ind = upper_bound(all(ants[1]), mp(key + l, -1)) - ants[1].begin();
				ind--;
			}
			ind = ants[1][ind].ss;
			ll dist = ((x[now] - currentTime + l) % l - (x[ind] + currentTime) % l + l) % l;
			if ((dist + 1) / 2 > t - currentTime) {
				currentTime = t;
			}
			else {
				currentTime += (dist + 1) / 2;
				now = ind;
			}
		}
	}
	ans = now;
}

