	t %= l;
	for (int i = 0; i < n; i++) {
		cin >> x[i] >> w[i];
		ants[w[i]].pb(mp(x[i], i));
	}
	solve();

	for (int i = 0; i < n; i++) {
		y[i] = (x[i] + t * (w[i] == 1 ? 1 : -1) % l + l) % l;
	}
	sort(y, y + n);
	int pos = lower_bound(y, y + n, (x[ans] + t * (w[ans] == 1 ? 1 : -1) % l + l) % l) - y;
	for (int i = 0; i < n; i++) {
		cout << y[pos] << endl;
		pos = (pos + 1) % n;
	}
}

