typedef long long ll;

const int N_MAX = 100002;

int n;
ll L, t;

ll x[N_MAX];

int w[N_MAX];

vector <int> v1, v2;

int ans[N_MAX];

int last1 (int pos)
{
    int l = 0, r = (int)v1.size() - 1;
    while(l < r)
    {
        int mid = ((l + r + 1) >> 1);
        if(x[v1[mid]] > pos)
            r = mid - 1;
        else
            l = mid;
    }
    return l;
}

int last2 (int pos)
{
    int l = 0, r = (int)v2.size() - 1;
    while(l < r)
    {
        int mid = ((l + r + 1) >> 1);
        if(x[v2[mid]] > pos)
            r = mid - 1;
        else
            l = mid;
    }
    return l;
}

int cnt1 (int l, int r)
{
    l = (l % L + L) % L;
    r = (r % L + L) % L;
    if(l <= r)
        return last1(r) - last1(l - 1);
    else if(l - r > 1)
        return (int)v1.size() - 1 - cnt1(r + 1, l - 1);
    return 0;
}

int cnt2 (int l, int r)
{
    l = (l % L + L) % L;
    r = (r % L + L) % L;
    if(l <= r)
        return last2(r) - last2(l - 1);
    else if(l - r > 1)
        return (int)v2.size() - 1 - cnt2(r + 1, l - 1);
    return 0;
}

