        if(w[i] == 1)
        {
            int pos = (x[i] + 2LL * t) % L;
            int c = (cnt2(x[i], pos) + (2LL * t / L) * ((int)v2.size() - 1) % n) % n;
            int j = ((i - 1 + c) % n + n) % n + 1;
            ans[j] = ((pos - t) % L + L) % L;
        }
        else
        {
            int pos = ((x[i] - 2LL * t) % L + L) % L;
            int c = (cnt1(pos, x[i]) % n + (2LL * t / L) * ((int)v1.size() - 1) % n) % n;
            int j = ((i - 1 - c) % n + n) % n + 1;
            ans[j] = (pos + t) % L;
        }
    for(int i = 1; i <= n; i++)
        cout << ans[i] << "\n";
    return 0;
}

