bool intersects(ll a, ll b, ll c, ll d) {
	bool res = false;
	for (int i = -3; i < 4; i++) {
		for (int j = -3; j < 4; j++) {
			ll A = a + i * l;
			ll B = b + i * l;
			ll C = c + j * l;
			ll D = d + j * l;
			res |= (max(A, C) < min(B, D));
		}
	}
	return res;
}

void calcPos() {
	if (w[0] == 1) {
		for (int i = 1; i < n; i++) {
			if (w[i] == 2 && intersects(x[0], y[0], y[i], x[i])) {
				pos++;
			}
		}
	}
	else {
		for (int i = n - 1; i > 0; i--) {
			if (w[i] == 1 && intersects(y[0], x[0], x[i], y[i])) {
				pos--;
			}
		}
	}
	pos = (pos + n) % n;
}

