		int pos;

		if(k>0)pos=sa[ia];
		else pos=sb[ib];
		pos=adj(pos+k*T);

		return pii(pos,k);
	}
	void solve()
	{
		initialize();
		pii A=GetTheFirstPosition();

		for(int i=1;i<=n;i++)
			s[i].x=((s[i].x+T*s[i].y)%L+L)%L;
