                    }
                }else{
                    ll spend = L - abs(newX[idx_init] - newX[idx]);
                    //cout<<i<<" "<<cnt<<" ? "<<spend<<endl;
                    if(spend > T*2){
                        cnt--;
                        goto finish;
                    }
                }
            }
        }
    }

finish:;

    N /= 2;
    L /= 2;
    //T /= 2;

    //cout<<N<<" "<<cnt<<endl;

    REP(i,N){
        if(W[i]==1){
