using namespace std;

int N, L, T;
int X[100001];
int W[100001];

int mod(int a, int b)
{
    while (a%b<0) {
        a += b;
    }
    return a%b;
}

int main()
{
    scanf("%d %d %d", &N, &L, &T);
    REP(i, N)
        scanf("%d %d", &X[i], &W[i]);

    int collision[100001];
    int num_col = 0;
    REP(i, N) {
        if(W[0]==W[i])
            collision[i] = 0;
        else {
            if (X[i]-X[0]>2*T) {
                collision[i] = 0;
            } else {
                collision[i] = int((double(T)-double(X[i]-X[0])/2.0)*2.0/double(L)) + 1;
            }
        }
        num_col += collision[i];
    }

    int lastof0;
    if(W[0]==1)
        lastof0 = num_col % N;
    else
        lastof0 = mod(-num_col,N);


    int pos[100001];
    REP(i, N) {
        if(W[i]==1)
            pos[i] = mod(X[i]+T, L);
        else
            pos[i] = mod(X[i]-T, L);
    }
    int pos0 = pos[0];
    sort(pos, pos+N);

    int offset;
    REP(i, N) {
        if(pos[i]==pos0) {
            offset = i-lastof0;
            break;
        }
    }
    REP(i, N) {
        cout << pos[mod(i+offset,N)] << endl;
    }

    return 0;
}

