#include<bits/stdc++.h>

using namespace std;
typedef long long ll;

const int N=100005;

int n,m,Q;
int a[N],na,b[N],nb;
int w[N],pnext[N],pnow[N];

int chk1(int p){
	int l=0,r=Q*2,mid=l+(r-l+1)/2;
	int x=pnow[p],y=pnext[p];
	if((b[y%nb]-a[x%na]+m)%m>=Q*2)
		return (a[x%na]+Q)%m;
	while(l<r){
		int cx=x-(mid+1)/2,cy=y+mid/2;
		ll dis=0;
		dis+=(ll)m*(cy/nb+(-cx)/na);
		cx%=na,cy%=nb;
		if(cx<0)cx+=na,dis+=m;
		dis+=b[cy]-a[cx];
		if(dis>=Q*2)
			r=mid-1;
		else
			l=mid;
		mid=l+(r-l+1)/2;
	}
	if(mid&1)return (a[((x-(mid+1)/2)%na+na)%na]+Q)%m;
	return ((b[(y+mid/2)%nb]-Q)%m+m)%m;
}

int chk2(int p){
	int l=0,r=Q*2,mid=l+(r-l+1)/2;
	int x=pnext[p]-1,y=pnow[p];
	if((b[y%nb]-a[(x%na+na)%na]+m)%m>=Q*2)
		return ((b[y%nb]-Q)%m+m)%m;
	while(l<r){
		int cx=x-mid/2,cy=y+(mid+1)/2;
		ll dis=0;
		dis+=(ll)m*(cy/nb+(-cx)/na);
		cx%=na,cy%=nb;
		if(cx<0)cx+=na,dis+=m;
		dis+=b[cy]-a[cx];
		if(dis>=Q*2)
			r=mid-1;
		else
			l=mid;
		mid=l+(r-l+1)/2;
	}
	if(mid&1)return ((b[(y+(mid+1)/2)%nb]-Q)%m+m)%m;
	return (a[((x-mid/2)%na+na)%na]+Q)%m;
}

int main(){
	scanf("%d%d%d",&n,&m,&Q);
	for(int i=1,x;i<=n;i++){
		scanf("%d%d",&x,&w[i]);
		if(w[i]==1)
			a[pnow[i]=na++]=x,pnext[i]=nb;
		else
			b[pnow[i]=nb++]=x,pnext[i]=na;
	}
	if(!na||!nb){
		for(int i=1;i<=n;i++)
			if(w[i]==1)
				printf("%d\n",(a[pnow[i]]+Q)%m);
			else
				printf("%d\n",((b[pnow[i]]-Q)%m+m)%m);
	}else{
		for(int i=1;i<=n;i++)
			if(w[i]==1)
				printf("%d\n",chk1(i));
			else
				printf("%d\n",chk2(i));
	}
	return 0;
}

