int main() {
  ios::sync_with_stdio(false);
  cin.tie(nullptr);
  i64 N, L, T;
  cin >> N >> L >> T;
  vector<i64> X(N);
  vector<short> W(N);
  vector<pair<i64, int>> rx, lx1, lx2;
  rx.reserve(N);
  lx1.reserve(N);
  lx2.reserve(N);
  int target = -1;
  REP(i, N) {
    cin >> X[i] >> W[i];
    if (W[i] == 1) {
      rx.emplace_back(X[i], i);
      if (target == -1) target = i;
    } else {
      assert(W[i] == 2);
      if (target == -1) {
        lx1.emplace_back(X[i], i);
      } else {
        lx2.emplace_back(X[i], i);
      }
    }
  }
  REP(i, lx1.size()) { lx2.push_back(lx1[i]); }

  auto modL = [&](i64 x) -> i64 {
    if (x >= 0) return x % L;
    i64 k = (-x + L - 1) / L;
    return (x + k * L) % L;
  };

  DEBUG(target);
  if (target == -1) {
    REP(i, N) { cout << modL(X[i] - T) << '\n'; }
    return 0;
  }

  auto track_target = [&]() -> pair<i64, int> {
    i64 t = 0;
    i64 x = X[target];
    const int rsize = rx.size();
    const int lsize = lx2.size();
    int rp = (target + rsize - 1) % rsize;
    int lp = 0;
    DEBUG(rp, lp);
    cerr << "R:";
    REP(i, rsize) { cerr << rx[(rp + i) % rsize].first << ' '; }
    cerr << endl;
    cerr << "L:";
    REP(i, lsize) { cerr << lx2[(lp + i) % lsize].first << ' '; }
    cerr << endl;
    while (true) {
      auto [x2, i2] = lx2[lp];
      x2 = modL(x2 - t);
      lp = (lp + 1) % lsize;
      i64 d = (x2 != x) ? modL(x2 - x) : L;
      DEBUG(t, x, x2, lp, d);
      if (t + d / 2 >= T) {
        return {modL(x + T - t), 1};
      }
      t += (d + 1) / 2;
      x = modL(x2 - (d + 1) / 2);
      auto [x3, i3] = rx[rp];
      x3 = modL(x3 + t);
      rp = (rp + rsize - 1) % rsize;
      d = (x3 != x) ? modL(x - x3) : L;
      DEBUG(t, x, x3, rp, d);
      if (t + d / 2 >= T) {
        return {modL(x - (T - t)), 2};
      }
      t += (d + 1) / 2;
      x = modL(x3 + (d + 1) / 2);
    }
    return {-1, -1};
  };
  auto [target_pos, target_dir] = track_target();
  DEBUG(target_pos, target_dir);

  vector<int> pos;
  pos.reserve(N);
  REP(i, N) { pos.push_back(modL(X[i] + T * (W[i] == 1 ? 1 : -1))); }
  sort(pos.begin(), pos.end());
  REP(i, N) { DEBUG(i, pos[i]); }
  i64 offset = -1;
  REP(i, N) {
    if ((target_dir == 1 && pos[i] == target_pos &&
         (i == 0 || pos[i - 1] != target_pos)) ||
        (target_dir == 2 && pos[i] == target_pos &&
         (i == N - 1 || pos[i + 1] != target_pos))) {
      offset = i - target;
      if (offset < 0) offset += N;
      break;
    }
  }
  DEBUG(offset);
  assert(offset >= 0);
  REP(i, N) {
    int j = (offset + i) % N;
    cout << pos[j] << '\n';
  }
}

