      // get target ant
      int f = j - 1;
      int b = j + 1;
      if (j == 0) { f = n - 1; }

      if (ig[j] == 1) {
        ig[j] = 0;
        continue;
      }
      if (w[j] == 2) {
        // anticlockwise
        // change way.
        if (w[f] == 1 && (x[j] == x[f] + 1 || (x[j] == 0 && x[f] == len - 1))) { 
          w[j] = 1;
          w[f] = 2;
          ig[f] = 1;
        } else {
          if (x[j] == 0) { x[j] = len - 1; }
          else { x[j] -= 1; }
        }
      }else if (w[j] == 1) {
        // clockwise
        // change way.
        if (w[b] == 2 && (x[j] == x[b] - 1 || (x[j] == len - 1 && x[b] == 0))) { 
          w[j] = 2;
          w[b] = 1;
          ig[b] = 1;
        } else {
          //cout << "in:" << j << endl;
