//    }


    // T秒後の蟻の位置を算出
    ant ants[100000];
    for (int i = 0; i < N; ++i) {
        if (antW[i] == 1) {
            ants[i].x = antX[i] + T;
        } else {
            ants[i].x = antX[i] - T;
        }
        if (ants[i].x >= L) {
            ants[i].x = ants[i].x % L;
        } else if (ants[i].x < 0) {
            ants[i].x = (L + ants[i].x) % L;
        }
        ants[i].index = i;
//        cout << "ant" << i << ", x" << ants[i].x << endl;
    }
    // 蟻の位置の配列を昇順でソート
    // ゼッケンの番号と対応させる
    sort(ants, ants + N, [](const ant &x, const ant &y) { return x.x < y.x; });
//    cout << endl;
//    for (int i = 0; i < N; ++i) {
//        cout << "ant" << ants[i].index << ", x" << ants[i].x << endl;
//    }
    // ゼッケン1の蟻が他の蟻とすれ違う回数を算出
    int suretigai = 0;
    for (int j = 1; j < N; ++j) {
        if (antW[0] != antW[j]) {
            double firstTime;
            double diff = antX[0] - antX[j];
            if (diff < 0) {
                diff += L;
            }
            if (antW[0] == 2) {
                diff = L - diff;
            }
            firstTime = diff / 2.0;
            if (T - firstTime >= 0) {
                if (firstTime > 0) {
                    suretigai += 1;
                }
                suretigai += (int) (2 * (T - firstTime)) / L;
            }
        }
    }
//    cout << "suretigai" << suretigai << endl;
    // ゼッケン1の蟻がT秒後に持っているゼッケンの番号を算出
    int zekken = 0;
    if (antW[0] == 1) {
        zekken = suretigai;
    } else {
        zekken = N - suretigai;
        if (zekken == N) {
            zekken = 0;
        }
        if (zekken < 0) {
            zekken = (N + zekken) % N;
        }
    }
    zekken = zekken % N;
//    cout << "zekken : " << zekken << endl;
    // T秒後にどの番号のゼッケンがどの座標にあるかを算出
    int zekkenX[100000];
    int index = 0;
    for (int i = 0; i < N; ++i) {
        if (ants[i].index == 0) {
            index = i;
            break;
        }
    }
    for (int i = 0; i < N; ++i) {
        // ゼッケン番号を計算
        int z = zekken + i;
        if (z >= N) {
            z -= N;
        }
        //
        int ind = index + i;
        if (ind >= N) {
            ind -= N;
        }
//        cout << z << " " << ind << endl;
        zekkenX[z] = ants[ind].x;
    }


    for (int i = 0; i < N; ++i) {
        cout << zekkenX[i] << endl;
    }
    return 0;
}

