	INIT;
	VAR(int, n, l, t);
	VEC_ROW(int, n, x, w);
	std::vector<int> d(n);
	REP(i, n) {
		int sign = w[i] == 1 ? 1 : -1;
		d[i] = x[i] + t * sign;
		d[i] %= l;
		if (d[i] < 0) d[i] += l;
	}
	int p0 = d[0];
