    vector<int> x(n), w(n);
    rep(i, n) cin >> x[i] >> w[i];

    int cnt = 0;
    for(int i = 1; i < n; i++){
        if(w[0] == w[i]){
            continue;
        }
        int diff;
        if(w[0] == 1){
            diff = (x[i] - x[0]);
        }else{
            diff = (x[0] + l - x[i]);
        }

        if(diff > t * 2){
            continue;
