        x[i] %= l;
    }

    if(n == 1){
        cout << x[0] << endl;
        return 0;
    }

    int id;
    if(w[0] == 1){
        id = cnt;
    }else{
        id = (n - cnt) % n;
    }
    int base = x[0];

    sort(ALL(x));
    int start = 0;
    rep(i, n){
        if(x[i] == base){
            start = i;
            if(w[0] == 1 && x[(i+1)%n] == base){
                start++;
            }
