const int N=2e5+10;

int n,L,T,pos[N],w[N],ans[N];

void Init()
{
	scanf("%d%d%d",&n,&L,&T);
	for (int i=0;i<n;++i) 
	{
		scanf("%d%d",&pos[i],&w[i]);
		if (w[i]==2) w[i]=-1;
	}
}
void Solve()
{
	int cg=0;
	for (int i=0;i<n;++i)
	{
		int epos=pos[i]+w[i]*T;
		if (epos<0) cg-=epos/L+1;
		else cg+=epos/L;
		ans[i]=(epos%L+L)%L;
		cg%=n;
	}
	sort(ans,ans+n);
	for (int i=0;i<n;++i) printf("%d\n",ans[(i+cg+n)%n]);
}

int main()
{
	Init();
	Solve();
	return 0;
}

