using namespace std;

struct AntPos {
	int64_t pos;
	int     dir;
};


int main()
{
	int n; cin >> n;
	int64_t l, t; cin >> l >> t;

	vector<AntPos> ants(n);
	int cw_count = 0;
	int ucw_count = 0;
	for (auto & ant : ants) {
		cin >> ant.pos;
		cin >> ant.dir;

		if (ant.dir == 1) {
			cw_count++;
		}
		else {
			ucw_count++;
		}
	}


	// まずは蟻の個体を気にせず位置
	vector<int64_t> anspos(n);
	FOR_LT(i, 0, n) {
		anspos[i] = ants[i].pos + ((ants[i].dir == 1) ? t : -t);
		anspos[i] %= l;
		if (anspos[i] < 0) anspos[i] += l;
	}
	sort(anspos.begin(), anspos.end());

	// 0 番のアリの延長線上が何番かを特定
	int ti = 0;

	auto head = ants[0];
	if (head.dir == 1) {
		int64_t ccount = 0;
		// 1 周ごとに 2 回ずつあたる
		ccount = (t / l) * 2 * ucw_count;

		// 残りの衝突は 0, 1, 2
		int64_t rem = t % l;
		for (auto& ant : ants) {
			if (ant.dir == 1) continue;

			if (ant.pos - head.pos <= 2 * rem) ccount++;
			if (ant.pos - head.pos + l <= 2 * rem) ccount++;
		}

		ti += ccount % n;
	}
	else {
		int64_t ccount = 0;
		// 1 周ごとに 2 回ずつあたる
		ccount = (t / l) * 2 * cw_count;

		// 残りの衝突は 0, 1, 2
		int64_t rem = t % l;
		for (auto& ant : ants) {
			if (ant.dir == 2) continue;

			if (ant.pos + l - head.pos <= 2 * rem) ccount++;
			if (ant.pos + l - head.pos + l <= 2 * rem) ccount++;
		}

		ti += (n - ccount % n);
	}

	int64_t headpos = head.pos + ((head.dir == 1) ? t : -t);
	headpos %= l;
	if (headpos < 0) headpos += l;

	auto it = find(anspos.begin(), anspos.end(), headpos);
	assert(it != anspos.end());
	if (it + 1 != anspos.end() && *(it + 1) == headpos && head.dir == 1) {
		// 右回りで丁度衝突した場合
		it++;
	}

	vector<int64_t> ansantpos(n);

	FOR_LT(i, 0, n) {
		ansantpos[(ti + i) % n] = *it;
		it++;
		if (it == anspos.end()) it = anspos.begin();
	}

	for (auto& elem : ansantpos) {
		cout << elem << endl;
	}

	return 0;
}

