#define MINUS(a) memset(a,0xff,sizeof(a))
//-------------------------------------------------------

int N,L,T;
int X[101010],W[101010];
ll ret[101010];

void solve() {
	int i,j,k,l,r,x,y; string s;

	cin>>N>>L>>T;
	int id=-1;
	L*=2;
	T*=2;
	FOR(i,N) {
		cin>>X[i]>>W[i];
		X[i]*=2;
		if(W[i]==1 && id==-1) id=i;
	}
	if(id==-1) {
		FOR(i,N) {
			X[i]=((X[i]-T)%L+L)%L;
			_P("%d\n",X[i]/2);
		}
		return;
	}
	ll hit=0;
	vector<ll> V;
	FOR(i,N) {
		if(W[i]==1) V.push_back((X[i]+T)%L);
		else V.push_back(((X[i]-T)%L+L)%L);
	}
	sort(ALL(V));

	FOR(i,N) if(W[i]==2) {
		ll dif=(i>id)?(X[i]-X[id]):(L+X[i]-X[id]);
		ll TT=T;
		if(dif/2<=TT) {
			hit++;
			TT-=dif/2;
		}
		hit+=TT/(L/2);
	}
	ll tid=(id+hit)%N;
	ll TX=(X[id]+T)%L;

	FOR(i,N) if(V[i]==TX) {
		FOR(j,N) {
			ret[(tid+j)%N]=V[(i+j)%N]/2;
		}
		break;
	}

	FOR(i,N) _P("%lld\n",ret[i]);


}


