int main() {
	int N;
	long long L, T, X[100000];
	bool W[100000];
	std::scanf("%d %lld %lld", &N, &L, &T);
	for (int i = 0; i < N; ++i) {
		int w;
		scanf("%lld %d", X + i, &w);
		W[i] = w == 1;
	}
	long long diff = W[0] ? 1 : L - 1;
	long long pos = (X[0] + T * diff) % L;
	int number = 0;
	int n_diff = W[0] ? 1 : N - 1;
	for (int i = 1; i < N; ++i) {
		if (W[0] == W[i]) {
			continue;
		}
		int dist;
		if (W[0]) {
			if (X[0] <= X[i]) {
				dist = X[i] - X[0];
			} else {
				dist = X[i] + L - X[0];
			}
		} else {
			if (X[0] >= X[i]) {
				dist = X[i] - X[0];
			} else {
				dist = X[0] + L - X[i];
			}
		}
		int count = 0;
		count += T / L;
		count += T % L >= std::ceil(dist / 2.0) ? 1 : 0;
		number += (count * n_diff) % N;
		number = number % N;
	}
	for (int i = 0; i < N; ++i) {
		int diff = W[i] ? 1 : L - 1;
		X[i] = (X[i] + diff * T) % L;
	}
	std::sort(X, X + N);
	int start_p;
	for (int i = 0; i < N; ++i) {
		 if (X[i] == pos) {
			 if (X[(i + 1) % N] == pos) {
				 if (W[i]) {
			 		start_p = (i + N - number) % N;
				 } else {
			 		start_p = ((i + 1) % N + N - number) % N;
				 }
			 } else if (X[(i + N - 1) % N] == pos) {
				 if (W[i]) {
			 		start_p = ((i + N - 1) % N + N - number) % N;
				 } else {
			 		start_p = (i + N - number) % N;
				 }
			 } else {
			 	start_p = (i + N - number) % N;
			 }
			 break;
		 }
	}
	for (int i = 0; i < N; ++i) {
		std::printf("%lld\n", X[(start_p + i) % N]);
	}
}

