    rep(i, 0, ss.size() - 1) {
        ds.emplace_back((l + x[ss[i]] - x[ss[i + 1]]) % l);
    }
    ds.emplace_back(l - accumulate(ds.begin(), ds.end(), 0ll));
    rep(i, 0, tt.size() - 1) {
        dt.emplace_back((l + x[tt[i]] - x[tt[i + 1]]) % l);
    }
    dt.emplace_back(l - accumulate(dt.begin(), dt.end(), 0ll));
    rep(i, 1, ds.size()) ds[i] += ds[i - 1];
    rep(i, 1, dt.size()) dt[i] += dt[i - 1];
    debug(ds, dt);
    ll lx = 0, rx = 1.1e9;
    while (rx - lx > 1) {
        ll mid = (rx + lx) / 2, sum = d0;
        ll sc = (mid + 1) / 2, tc = mid / 2;
        sum += (sc / ss.size()) * l;
        sc -= sc / ss.size() * ss.size();
        sum += (tc / tt.size()) * l;
        tc -= tc / tt.size() * tt.size();
        if (sc) sum += ds[sc - 1];
        if (tc) sum += dt[tc - 1];
        if (sum < t * 2)
            lx = mid;
        else
            rx = mid;
    }
    debug(lx, rx);
    int res = 0;
    lx = rx;
    if (lx % 2 == 0) {
        lx /= 2;
        lx %= ss.size();
        res = ss[lx];
    } else {
        lx /= 2;
        lx %= tt.size();
        res = tt[lx];
    }
    debug(res);
    rep(i, 0, n) {
        cout << z[(i + res) % n] << endl;
    }
    return 0;
}

