unsigned readUnsigned() {
    int c;
    do { c = ::getchar_unlocked(); } while (c < '0');
    unsigned result = c - '0';
    while ((c = ::getchar_unlocked()) >= '0') {
        result *= 10;
        result += c - '0';
    }
    return result;
}

void writeUnsignedLn(unsigned x) {
    static const unsigned MAX_DIGITS = 10;
    static const unsigned BUF_SIZE = MAX_DIGITS + 1;
    static char buffer[BUF_SIZE] = {0};
    buffer[BUF_SIZE - 1] = '\n';
    unsigned i = BUF_SIZE - 1;
    do {
        buffer[--i] = x % 10 + '0';
        x /= 10;
    } while (x);
    ::fwrite_unlocked(buffer + i, 1, BUF_SIZE - i, stdout);
}

unsigned N, L, T;
std::vector<unsigned> xs, W;

std::vector<unsigned> simulate() {
    std::vector<unsigned> result(N);

    std::vector<unsigned> left, right;
    for (unsigned i = 0; i < N; ++i) {
        if (W[i] == 1) {
            right.push_back(xs[i]);
        }
        else {
            left.push_back(xs[i]);
        }
    }

    /*
     * We will calculate the final position of an arbitrary ant, xs[fixpoint].
     *
     * It will be offset.
     *
     */
    unsigned fixpoint = 0;
    unsigned offset = 0;

    if (left.empty() || right.empty()) {
        /* All ants are going in the same direction, no mystery here. */
        if (W[fixpoint] == 1) {
            offset = (xs[fixpoint] + T) % L;
        }
        else {
            offset = (xs[fixpoint] + L - T) % L;
        }
        goto offset_found;
    }

    for (unsigned t = 0, pos = xs[fixpoint], w = W[fixpoint];;) {
        assert(t <= T);

        /* Find the next collision for fixpoint. */
        if (w == 1) {
            unsigned i = 0;
            /*
             * An ant starting at X and going left will collide with our
             * fixpoint ant at time t.
             */
            unsigned X = (pos + t) % L;
            for (unsigned n = left.size(); n; n /= 2) {
                while (i + n < left.size() && left[i + n] < X) i += n;
            }
            ++i;
            if (i >= left.size()) {
                i = 0;
            }
            unsigned pos2 = (left[i] + L - t) % L;
            unsigned dist = (pos2 - pos + L) % L;
            unsigned t2 = t + (dist + 1) / 2;
            if (t2 > T) {
                offset = (pos + T - t) % L;
                break;
            }
            t = t2;
            pos = (left[i] + L - t) % L;
            w = 2;
        }
        else {
            unsigned i = 0;
            unsigned X = (pos + L - t) % L;
            for (unsigned n = right.size(); n; n /= 2) {
                while (i + n < right.size() && right[i + n] <= X) i += n;
            }
            if (i == 0 && right[i] > X) {
                i = right.size() - 1;
            }
            unsigned pos2 = (right[i] + t) % L;
            unsigned dist = (pos - pos2 + L) % L;
            unsigned t2 = t + (dist + 1) / 2;
            if (t2 > T) {
                offset = (pos + L - (T - t)) % L;
                break;
            }
            t = t2;
            pos = (right[i] + t) % L;
            w = 1;
        }
    }

offset_found:

    for (unsigned i = 0; i < xs.size(); ++i) {
        unsigned t = xs[i];
        if (W[i] == 1) {
            t += T;
        }
        else {
            t += L - T;
        }
        t %= L;
        result[i] = t;
    }

    std::sort(result.begin(), result.end(), [offset](unsigned x, unsigned y) {
        return x - offset < y - offset;
    });

    return result;
}

int main() {
    N = readUnsigned();
    L = readUnsigned();
    T = readUnsigned() % L;

    xs.resize(N);
    W.resize(N);
    for (unsigned i = 0; i < N; ++i) {
        xs[i] = readUnsigned();
        W[i] = readUnsigned();
    }

    std::vector<unsigned> result = simulate();
    for (unsigned i = 0; i < N; ++i) {
        writeUnsignedLn(result[i]);
    }
}

