            dist = (x[0] + l - x[i]) % l;
        } else {    // Clockwise
            dist = (x[i] + l - x[0]) % l;
        }
        if (t % l * 2 > dist) id0++;
        if (t % l * 2 > dist + l) id0++;
        //printf("Ant #0 - #%d: Cyc = %d Dist = %d Hold = %d\n", i, cycles, dist, (int)id0);
