int dist(int i) {
    return x[(i - 1) % n + 1] + l * ((i - 1) / n);
}
int summa(int i, int T) {
    return pref[(i - 1) % n + 1][T] + ((i - 1) / n) * pref[n][T];
}

signed main() {
    ios_base::sync_with_stdio(false);
    cin.tie(0);
    cin >> n >> l >> t;
    for (int i = 1; i <= n; ++i) {
        cin >> x[i] >> w[i];
        if (w[i] == 1) {
            fx[i] = (x[i] + t) % l;
        } else {
            fx[i] = ((x[i] - t) % l + l) % l;
        }
    }
    for (int i = 1; i <= n; ++i) {
        for (int j = 1; j <= 2; ++j) {
            pref[i][j] = pref[i - 1][j] + (w[i] == j);
        }
    }
    for (int i = 1; i <= n; ++i) {
        if (w[i] == 1) {
            int l = i, r = INF;
            while (r - l > 1) {
                int m = (l + r) >> 1;
                if (dist(m) - dist(i) < t * 2) l = m;
                else r = m;
            }
            meet[i] = summa(l, 2) - summa(i, 2);
            ans[(i - 1 + meet[i]) % n + 1] = fx[i];
        } else {
            int l = 1, r = i + n * INF;
            while (r - l > 1) {
                int m = (l + r) >> 1;
                if (dist(i + n * INF) - dist(m) < t * 2) r = m;
                else l = m;
            }
            meet[i] = summa(i + n * INF, 1) - summa(r - 1, 1);
            ans[((i - 1 - meet[i]) % n + n) % n + 1] = fx[i];
        }
    }
    for (int i = 1; i <= n; ++i) {
        cout << ans[i] << '\n';
    }
    return 0;
}

