    for(long i = 0; i < n; ++i) {
      dumpll(i, coords[i]);
    }
    long count = 0;
    for(long i = 0; i < n; ++i) {
      if( xs[i][0] == 1 ) count += 1;
      else count -= 1;
    }
    long diff = t / l * count;
    for(long i = 0; i < n; ++i) {
      // t % l sec
      long dt = t % l;
      if( xs[i][1] == 1 ) {
        long t1 = ((l-1) - xs[i][0] + 3 * l) % l;
        long t2 = (0     - xs[i][0] + 3 * l) % l;
        if( t1 <= dt and
            t2 <= dt and
            t1 < t2 ) {
          diff += 1;
        }
      }
      if( xs[i][1] == 2 ) {
        long t1 = (xs[i][0] - 0     + 3 * l) % l;
        long t2 = (xs[i][0] - (l-1) + 3 * l) % l;
        if( t1 <= dt and
            t2 <= dt and
            t1 < t2      ) {
          diff -= 1;
        }
      }
    }
    dumpl(diff);
    for(long i = 0; i < n; ++i) {
      assert( (i+diff+1100100100*n) >= 0 );
      printf("%ld\n", coords.at((i+diff+1100100100*n)%n));
    }
  }    
  ~Solver() { fprintf(stderr, "--end--\n"); }
};


