int intersects(ll a, ll b, ll c, ll d) {
	int res = 0;
	for (int i = -3; i < 4; i++) {
		ll A = a + i * l;
		ll B = b + i * l;
		ll C = c;
		ll D = d;
		res += (max(A, C) <= min(B, D));
	}
	return res;
}

void calcPos() {
	if (w[0] == 1) {
		for (int i = 1; i < n; i++) {
			if (w[i] == 2) {
				pos += intersects(x[0], y[0], y[i], x[i]);
			}
		}
	}
	else {
		for (int i = n - 1; i > 0; i--) {
			if (w[i] == 1) {
				pos -= intersects(y[0], x[0], x[i], y[i]);
			}
		}
	}
	pos = (pos + n) % n;
}

