			}
			cou %= n;
		}
	}

	vector<pair<ll,ll>> ans;
	REP(i,n){
		if(aft[i].SE == 0){
			REP(j,n){
				ans.PB(MP((cou+j)%n,aft[(i+j)%n].FI));
			}
			break;
		}
	}

	sort(ALL(ans));

	REP(i,n){
		cout << ans[i].SE << endl;
	}


	return 0;
}

