int di(int a, int b, int c, int s)
{
    int A = 2*f[a][0];
    int B = 2*f[b][0];
    int C = 2*f[c][0];
    if(!s)
    {
        while(B <= A) B += 2*l;
        while(C <= B) C += 2*l;
    }
    else
    {
        while(B <= C) B += 2*l;
        while(A <= B) A += 2*l;
        A = -A;
        B = -B;
        C = -C;
    }
    int eps = (B - A) / 2;
    return (C - A) / 2 - eps;
}

pair<pair<int, int>, pair<int, int> > dyn(int pos, int der, int d, int sens)
{
    //PR(pos, der, d);
    if(d < 0) return {{pos, der}, {sens, d}};
    int sui = h[der][!sens];
    return dyn(sui, pos, d - di(pos, der, sui, sens), 1 - sens);
}

