int N, L, T;

int next(int a) {
    if (a == N-1) return 0;
    else return a+1;
}

int prev(int a) {
    if (a == 0) return N-1;
    else return a-1;
}

int dist(int a, int b) { //座標aから座標bへ時計回りにみた距離
    if (a <= b) return b-a;
    else return L-(a-b);
}

int meet_time(int dist) {
    if (T < dist/2.) return 0;
    else {
        int cnt=1;
        double first_meet = dist/2.;
        double remain = T - first_meet;
        cnt += floor(remain / (L/2.));
        return cnt;
    }
}

