            int first = (abs(ant[i][0] - ant[0][0]) / 2 <= t) ? 1 : 0;
            count = 2 * (max(t - abs(ant[i][0] - ant[0][0]) / 2,(int)0)) / l + first;
        } else {
            int first =  (abs(l - ant[i][0] + ant[0][0]) / 2 <= t) ? 1 : 0;
            count = 2 * (max(t - abs(l - ant[i][0] + ant[0][0]) / 2,(int)0)) / l + first;
        }
        if(ant[0][1] == 2){
            sum -= count;
        } else {
            sum += count;
        }
    }
}
sum = ((sum % n) + n) % n;
for(int i = 0; i < n; i++){
    std::cout << outx[(sum + i) % n] << " ";
}
std::cout << std::endl;
return 0;
}

