using namespace std;

const int N = 100010;

int pos[N], dir[N], x[N], ans[N];
int n, m, T;

int main(){
	scanf("%d%d%d", &n, &m, &T);
	For(i, 1, n){
		scanf("%d%d", &x[i], &dir[i]);
		pos[i] = dir[i] == 1 ? (x[i] + T) % m : ((x[i] - T) % m + m) % m;
	}
	long long ret = 0;
	For(i, 2, n) if(dir[i] ^ dir[1]){
		int delt = 0;
		if(dir[1] == 1) delt = x[i] - x[1];
		else delt = (x[1] + m - x[i]) % m;
		ret += (2 * T - delt) / m + 1;
	}
	ret %= n;
	if(dir[1] == 2) ret = (n - ret) % n;

	int p = pos[1];

	sort(pos + 1, pos + n + 1);
	if(dir[1] == 2) p = int(lower_bound(pos + 1, pos + n + 1, p) - pos);
	else p = int(upper_bound(pos + 1, pos + n + 1, p) - pos) - 1;

	--p;
	For(i, 0, n - 1) ans[(ret + i) % n] = pos[(p + i) % n + 1];
	For(i, 0, n - 1) printf("%d\n", ans[i]);
	return 0;
}

