#define REP(i,n) FOR(i,0,n)  
#define FORE(i,a,b) for(int i=(a);i<=(b);++i)  
#define REPE(i,n) FORE(i,0,n)  
#define FORSZ(i,a,v) FOR(i,a,SZ(v))  
#define REPSZ(i,v) REP(i,SZ(v))  
typedef long long ll;
typedef unsigned long long ull;
ll gcd(ll a,ll b) { return b==0?a:gcd(b,a%b); }

const int MAXN=100000;

int n; ll L,T;
ll x[MAXN]; int dir[MAXN];
pair<ll,ll> tmp[MAXN];
ll ret[MAXN];

int simulate(int at,ll CT) {
	ll t=0;
	int nxt=at;
	//puts("");
	while(true) {
		nxt=(nxt+1)%n; while(dir[nxt]==+1) nxt=(nxt+1)%n;
		ll nt=(x[nxt]-x[at])/2; while(nt<=t) nt+=L/2;
		//printf("%lld = %d\n",nt,nxt);
		if(nt>CT) return at;
		at=(at+n-1)%n; while(dir[at]==-1) at=(at+n-1)%n;
		ll nnt=(x[nxt]-x[at])/2; while(nnt<=nt) nnt+=L/2;
		//printf("%lld = %d\n",nnt,at);
		if(nnt>CT) return nxt;
		t=nnt;
	}
}

void solve() {
	int pos=-1; REP(i,n) if(dir[i]>0) { pos=i; break; }
	if(pos==-1) { REP(i,n) ret[i]=((x[i]-T)%L+L)%L; return; }
	int neg=-1; REP(i,n) if(dir[i]<0) { neg=i; break; }
	if(neg==-1) { REP(i,n) ret[i]=(x[i]+T)%L; return; }

	int fullperiod=(simulate(pos,L)+n-pos)%n;
	ll fulltimes=T/L;
	int diff=fulltimes*fullperiod%n;
	int topos=(pos+n-diff)%n;

	int remperiod=T%L==0?0:(simulate(pos,T%L-1)+n-pos)%n;
	//printf("fullperiod=%d fulltimes=%lld remperiod=%d -> delta=%d\n",fullperiod,fulltimes,remperiod,delta);

	REP(i,n) tmp[i]=MP(((x[i]+dir[i]*(T-1))%L+L)%L,((x[i]+dir[i]*T)%L+L)%L);
	int npos=(pos+remperiod)%n; ll nposx=tmp[npos].first;
	sort(tmp,tmp+n);
	int off=0; REP(i,n) if(tmp[i].first==nposx) off=i-topos;
	REP(i,n) { int j=(i+n+off)%n; ret[i]=tmp[j].second; }
}

void run() {
	scanf("%d%lld%lld",&n,&L,&T); L*=4; T*=4;
	REP(i,n) scanf("%lld%d",&x[i],&dir[i]),x[i]*=4,dir[i]=dir[i]==1?+1:-1;
	solve();
	REP(i,n) printf("%lld\n",ret[i]<0?ret[i]:ret[i]/4);
}

int main() {
	run();
	return 0;
}

