class Ants {
	int n, l, t;
	int *x, *w;
public:
	Ants();
	void xTimes();
	void manage();
	void show();
};

Ants::Ants() {
	std::cin >> n >> l >> t;
	x = new int[n];
	w = new int[n];

	for (int i = 0; i < n; i++) {
		std::cin >> x[i] >> w[i];
	}
 }

void Ants::manage() {
	int *tempX = new int[2 * n];
	for (int i = 0; i < n; i++) {
		tempX[i] = 2 * x[i];
	}

	for (int i = 0; i < 2; i++) {
		for (int j = 0; j < n; j++) {
			if (w[j] == 1)tempX[j]++;
			else tempX[j]--;
			if (tempX[j] == -1)tempX[j] = 2 * l - 1;
			else if (tempX[j] == 2 * l)tempX[j] = 0;
		}

		for (int j = 0; j < n - 1; j++) {
			for (int k = j + 1; k < n; k++) {
				if (tempX[j] == tempX[k] && w[j] != w[k]) {
					if (w[j] == 1)w[j] = 2, w[k] = 1;
					else w[j] = 1, w[k] = 2;
				}
			}
		}

	}
	for (int i = 0; i < n; i++) {
		x[i] = tempX[i] / 2;
	}
}

void Ants::show() {
	for (int i = 0; i < n; i++){
		printf("%d\n", x[i]);
	}
}

void Ants::xTimes() {
	for (int i = 0; i < t; i++) {
		manage();
	}
}


