      }
      else
      {
        if (2 * t - l + (x[i] - x[0] + 1) < 0)
          continue;
        else
          count += 1 + (2 * t - l + (x[i] - x[0] + 1)) / l;
      }
    }
  }
  count = count % n;
  if (w[0] == 2)
  {
    count = (n - count) % n;
  }

  i64 ans_f = ans[0];
  sort(ans, ans + n);
