        if( (0     - xs[i][0] + 3 * l) % l <= dt and
            ((l-1) - xs[i][0] + 3 * l) % l <= dt     ) {
          diff += 1;
        }
      }
      if( xs[i][1] == 2 ) {
        if( (xs[i][0] - (l-1) + 3 * l) % l <= dt and
            (xs[i][0] - 0     + 3 * l) % l <= dt     ) {
          diff -= 1;
        }
      }
    }
