typedef pair<DWORD, DWORD> PAIR;

DWORD N,T,L;
vector<PAIR> vAnts;
DWORD hit = 0;

static DWORD RevisePos(DWORD pos)
{
	if (pos < 0) return L + pos;
	else if (pos >= L) return pos - L;
	else	return pos;
}

static void HitCntOfZeroAnt()
{
	PAIR zero_ant = vAnts[0];

	for (int i = 1; i < N; i++) {
		DWORD dist = vAnts[i].first - zero_ant.first;

		if (zero_ant.second == 1 && vAnts[i].second == -1) { //0番目のアリが右周りの時
			if (((2 * T) - dist) > 0) {
				hit ++;	//0週目で衝突する回数

				hit += ((2 * T) - dist) / L;  //1週以上して衝突する回数
				if (((2 * T) - dist) % L == 0)  hit--; //最後の位置が同じ場合は衝突としてカウントしない
			} 

		} else if (zero_ant.second == -1 && vAnts[i].second == 1) { //0番目のアリが左回り
			dist = L - dist;
			if (((2 * T) - dist) > 0) {
				hit ++;
				hit += ((2 * T) - dist) / L;
				if (((2 * T) - dist) % L == 0)  hit--;
			}
		}

	}
}

