ll N, L, T;
vector<ll> X, W;

ll collision_count(int a, int b)
{
    ll res = 0, diff = -1;

    if (W[a] == 1 && W[b] == 2) {
        diff = (X[b] - X[a]);
    } else if (W[a] == 2 && W[b] == 1) {
        diff = L - (X[b] - X[a]);
    }

    // DUMP(diff);
    if (diff >= 0) res = (T + L - 1) / L + (diff % L <= T / 2);
    // cerr << "collision_count(" << a << ", " << b << ") = " << res << endl;
    return res;
}

int main()
{
    ios::sync_with_stdio(false);

    cin >> N >> L >> T;
    X.resize(N), W.resize(N);
    rep(i, N) cin >> X[i] >> W[i];

    ll collision_sum = 0;
    REP(i, 1, N) {
        if (W[0] == 1) {
            collision_sum += collision_count(0, i);
        } else {
            collision_sum -= collision_count(0, i);
        }
    }
    collision_sum = (collision_sum + N*T) % N;
    assert(collision_sum >= 0LL);

    vector<ll> last_pos(N);
    rep(i, N) {
        if (W[i] == 1) {
            last_pos[i] = (X[i] + T) % L;
        } else {
            last_pos[i] = (X[i] - T + L*T) % L;
        }
        assert(last_pos[i] >= 0LL);
    }

    vector<ll> ans(N);
    rep(i, N) {
        ans[(collision_sum + i) % N] = last_pos[i];
    }
    rep(i, N) cout << ans[i] << endl;

    // DUMP(collision_sum);
}

