int K(int x, int y) {//時計回り　反時計回り 何回ぶつかるか
	if (x > y)y += c;
	double e = d;
	e -= (y-x)/2;
	if (e < 0)return 0;
	e = max(d, 0ll);
	return 2 * d / c+1;
}
