		if(dir[i]==1){
			p1[++n1]=pos[i];
			id1[n1]=i;
		}else{
			p2[++n2]=pos[i];
			id2[n2]=i;
		}
	}
	for(int i=1;i<=n1;i++){
		d1[i]=(p1[i]-p1[(i-2+n1)%n1+1]+L)%L;
		if(!d1[i]) d1[i]=L;
		sd1[i]=sd1[i-1]+d1[i];
	}
	for(int i=1;i<=n2;i++){
		d2[i]=(p2[i%n2+1]-p2[i]+L)%L;
		if(!d2[i]) d2[i]=L;
		sd2[i]=sd2[i-1]+d2[i];
	}
	T*=2;
	int now=1;
	for(int i=1;i<=n1;i++){
		if(!n2){
			target[i]=i;
