template <typename T>
inline T mod(T a, T m) {
    T res = a % m;
    if (res < 0) res += m;
    return res;
}


class Solver {
    int N, L, T;
    vi x, w;

    vi cw, ccw, xt;
    int CW, CCW;
public:
    Solver() {
        scanf("%d%d%d", &N, &L, &T);
        x.resize(N); w.resize(N);
        rep(i,N) {
            scanf("%d%d", &x[i], &w[i]);
        }

        init();

        if (N == 1) {
            printf("%d\n", xt[0]);
            return;
        }

        int dir0 = (w[0] == 1) ? 1 : -1;
        ll crossed = 0;
        bool just = false;
        if (dir0 == 1) {
            for (int y: ccw) {
                ll d2 = y - x[0];
                if (d2 < 0) d2 += L;
                assert(IN(d2, 0, L-1));
                ll q = 1+(T*2 - d2)/L;
                crossed += q;
                if (T*2 % L == d2) just = true;
            }
        } else {
            for (int y: cw) {
                ll d2 = x[0] - y;
                if (d2 < 0) d2 += L;
                assert(IN(d2, 0, L-1));
                ll q = 1+(T*2 - d2)/L;
                crossed -= q;
                if (T*2 % L == d2) just = true;
            }
        }

        int x0 = xt[0];
        int c0 = mod(0+crossed, (ll)N);


        sort(ALL(xt));

        int ix = lower_bound(ALL(xt), x0) - xt.begin();
        assert(xt[ix] == x0);

        int offset = 0;
        if (ix < N-1 && xt[ix+1] == x0) {
            if (dir0 == 1) {
                offset = ix+1 - c0;
            } else {
                offset = ix - c0;
            }
        } else {
            offset = ix - c0;
        }

        rep(i,N){
            printf("%d\n", xt[mod(i+offset, N)]);
        }
    }
private:
    void init() {
        cw.clear(); ccw.clear();
        cw.reserve(N); ccw.reserve(N);
        xt.resize(N);
        rep(i,N){
            if (w[i] == 1) {
                cw.pb(x[i]);
                xt[i] = mod(x[i] + T, L);
            } else {
                ccw.pb(x[i]);
                xt[i] = mod(x[i] - T, L);
            }
        }
        CW = cw.size(); CCW = ccw.size();
    }
};

int main() {
    Solver *s = new Solver();
    delete s;
    return 0;
}

