        fin[i] = (v[i] + (d[i] == 1 ? -1 : 1) * t) % l;
        if (fin[i] < 0) fin[i] += l;
    }

    int p1 = fin[1];
    int p3 = fin[3];
    sort(fin+1,fin+n+1);
    int val = getFin(1);
    int val2 = getFin(3);
    int dif = val2 - val;
    for (int i=1;i<=n;i++){
        if (fin[i] == p1 && fin[(i + dif > n ? i+dif-n : i + dif)]==p3){
