            while(fx > sx) {
                sx+=L;
            }
            if ((sx-fx-1) % 2) {
                if((sx-fx-1)/2.0 <= t) {
                    cnt++;
                    t-=(sx-fx-1)/2.0;
                }
            } else {
                if((sx-fx-1)/2.0 + 1 <= t) {
                    cnt++;
                    t-=(sx-fx-1)/2.0 + 1;
                }
            }
            cnt += (ll)(t*2 / L);
        }
    }
    if (W[0]==2) {
        lastf = INF * L;
        lastf -= cnt;

    } else {
        lastf += cnt;
    }
    lastf %= L;

    // 反時計の蟻はINF×N周足しておく
    REP(i,N) {
        if (W[i]==2) {
            X[i]+=INF*L;
        }
    }

    // T秒後の座標を求める
    vector<ll> ans;
    REP(i,N) {
        if(W[i]==2) {
            X[i]-=T;
        } else {
            X[i]+=T;
        }
        X[i]%=L;
        ans.pb(X[i]);
        ans.pb(X[i]+L);
        ans.pb(X[i]+L+L);
    }
    sort(ans.begin(), ans.end());
    ll zekken = lastf;
    int cntst = 0;

    for(auto x: ans) {
        if (cntst) {
            ansc[zekken%N] = x%L;
            zekken++;
        } else if(X[0]==x) {
            ansc[zekken%N] = x%L;
            cntst = 1;
            zekken++;
        }
    }

    REP(i, N) {
        cout << ansc[i] << endl;
    }

    return 0;
}

