    for(int i=0;i<N;i++){
        cin >> X[i] >> W[i];
        W[i]--;
        mp[X[i]] = i;
        list[W[i]].emplace_back(X[i]);
    }
    if(list[1].empty()){
        for(int i=0;i<N;i++) cout << (X[i]+T)%L << "\n";
        return 0;
    }
