        return 0;
    }
    for(int k=0;k<2;k++) sort(list[k].begin(),list[k].end());

    auto dist = [&](int clock,int counter){
        if(clock<counter) return counter-clock;
        else return L-(clock-counter);
    };

    auto next_time = [&](int clock,int counter,int ti){
        int p0 = (clock+ti)%L,p1 = (counter-ti+L)%L;
        int d = dist(p0,p1);
        return ti+(d+1)/2;
    };

    vec<int> id(2);
    int ti = 0,now = 0;
    bool exist = mp[list[0][1]]==1;
