using s64 = int64_t;
using u64 = uint64_t;
// }}}

s64 N;
s64 L;
s64 T;
vector<s64> X;
vector<s64> W;

s64 getpos(s64 x, s64 w)
{
    if(w == 1)
        return (x + T) % L;
    else
        return (x + L - T%L) % L;
}

void solve()
{
    // アリ0がT秒間に他のアリとすれ違う回数を求める
    // 他方のアリを固定し、アリ0が 2*T 進むと考える
    s64 cross = 0;
    FOR(i, 1, N) {
        if(W[0] == W[i]) continue;

        s64 d;
        if(W[0] == 1 && W[i] == 2) {
            d = X[i] - X[0];
        }
        else {
            d = L - (X[i] - X[0]);
        }

        s64 q = 2*T / L;
        s64 r = 2*T % L;
        cross += q;
        if(d < r)
            ++cross;
    }

    // すれ違った回数だけアリ0のインデックスが増減
    s64 idx0 = W[0] == 1 ? cross%N : (N-cross%N)%N;
    s64 pos0 = getpos(X[0], W[0]);

    // T 秒後の座標リスト
    vector<s64> pos(N);
    REP(i, N) {
        pos[i] = getpos(X[i], W[i]);
    }
    sort(begin(pos), end(pos));
#ifdef DEBUG
    fmt::print("idx0: {}\n", idx0);
    fmt::print("pos0: {}\n", pos0);
    PRINT_RANGE(begin(pos), end(pos));
#endif

    // アリ0がどこに行ったか調べてry
    // 同座標に2匹いることがあるが、その場合は
    // W[0] == 1 なら前、W[0] == 2 なら後ろ
    auto p = equal_range(begin(pos), end(pos), pos0);
    auto it = p.first;
    if(distance(p.first, p.second) == 2 && W[0] == 2) {
        ++it;
    }
    int k = distance(begin(pos), it);
    k += N - idx0;
    k %= N;
    REP(_, N) {
        cout << pos[k] << "\n";
        ++k;
        k %= N;
    }
}

int main()
{
    cin >> N >> L >> T;
    X.resize(N);
    W.resize(N);

    REP(i, N) {
        cin >> X[i] >> W[i];
    }

    solve();

    return 0;
}

