void solve(){
	int N,L,T;
	cin >> N >> L >> T;
	vector<LL> X(N),W(N);
	vector<LL> pos(N);
	for(int i=0;i<N;++i){
		cin >> X[i] >> W[i];
		if( W[i] == 2 ){
			W[i] = -1;
		}
		pos[i] = X[i] + T*W[i];
	}
	int count = 0;
	for(int i=1;i<N;++i){
		if( W[0] > 0 && pos[0] > pos[i]){
			++count;
		}else if(W[0]<0 && pos[0] < pos[i]){
			--count;
		}
	}
	for(int i=0;i<N;++i){
		pos[i] = (pos[i]%L+L)%L;
	}
	sort(pos.begin(), pos.end());
	for(int i=0;i<N;++i){
		cout << pos[(i+count%N+N)%N] << endl;
	}
}

