int main(){
//	cin.tie(0);
//	ios::sync_with_stdio(false);
	cin >> n >> l >> t;
	x.resize(n);
	w.resize(n);
	for(int i=0; i<n; ++i){
		cin >> x[i] >> w[i];
		ll tmp = x[i] + (3-2*w[i]) * t;
		tmp %= l;
		if(tmp < 0) tmp += l;
		a.push_back(tmp);
	}
	if(n == 1){
		cout << a[0] << "\n";
		return 0;
	}
	sort(a.begin(), a.end());
	for(int i=1; i<n; ++i)
		if(w[i] != w[0])
			b.push_back(x[i]);
	ll c = 0;
	for(int i=0; i<b.size(); ++i){
		ll dis = w[0] == 1 ? b[i] - x[0] : x[0] - b[i];
		dis = (dis + 2*l) % l;
//		cout << "d = " << dis << "\n";
		// max x s.t. 2 * t >= x * l + dis
		if(2*t >= dis){
			ll p = 0, q = 1e10;
			while(p+1 < q){
				ll m = (p + q) / 2;
//				cout << m << "\n";
				if(2*t >= m*l + dis) p = m;
				else q = m;
//				cout << p << " " << q << "\n";
			}
//			cout << "p = " << p << "\n";
			c += p + 1;
			c %= n;
//			cout << c << "\n";
		}
	}
//	cout << c << "\n";
	if(w[0] == 2) c = (n - c) % n;
	u = x[0] + (3-2*w[0]) * t;
	u %= l;
	if(u < 0) u += l;
	for(int i=0; i<n; ++i)
		if(a[i] == u){
			for(int j=0; j<n; ++j)
				cout << a[(i-c+j+n)%n] << "\n";
			return 0;
		}
}

#include<cstdio>
#include<cstring>
