void _main()
{
    ll n; llin(n);
    ll mod; llin(mod);
    ll t; llin(t);
    V<t2> xwlist; llinl2(xwlist, n);

    ll sidx = -1;
    rep (i, n) {
        ll w = get<1>(xwlist[i]);
        if (w == 1) {
            sidx = i;
            break;
        }
    }

    if (sidx < 0) {
        t %= mod;
        for (auto xw : xwlist) {
            ll x = get<0>(xw);
            x -= t;
            if (x < 0) x += mod;
            cout << x << endl;
        }
        return;
    }

    debug_printf("--- sidx=%lld\n", sidx);

    ll revidxs = 0;
    rep (i, n) {
        ll w = get<0>(xwlist[i]);
        if (w == 2) revidxs++;
    }

    ll proceeds = revidxs * (t / mod) * 2LL;
    ll sx = get<0>(xwlist[sidx]);

    debug_printf("---- proceeds(1)=%lld\n", proceeds);

    rep (i, n) {
        ll x = get<0>(xwlist[i]);
        ll w = get<1>(xwlist[i]);
        if (w == 1) continue;
        while (x < sx) x += mod;
        if (x - sx < (t % mod) * 2LL) proceeds++;
        if (x - sx + mod < (t % mod) * 2LL) proceeds++;
    }

    debug_printf("---- proceeds(2)=%lld\n", proceeds);

    V<ll> poslist;

    ll sxx = get<0>(xwlist[sidx]);
    sxx += t % mod;
    sxx %= mod;

    rep (i, n) {
        ll x = get<0>(xwlist[i]);
        ll w = get<1>(xwlist[i]);
        if (w == 1) x += t % mod;
        else x -= t % mod;
        while (x < 0) x += mod;
        x %= mod;
        while (x < sxx) x += mod;
        poslist.pb(x);
    }
    sort(poslist);

    debug_printf("---- poslist\n");
    debug_print(poslist);

    ll idx = proceeds + sidx;
    ll anslist[100005];
    rep (i, n) {
        anslist[idx%n] = poslist[i] % mod;
        idx++;
    }

    debug_printf("---- ans\n");
    rep (i, n) cout << anslist[i] << endl;
}

