      int kyori = (x + L - X[0])%L;
      if (kyori <= 2 * nokori) {
        branch++;
      }
      if (kyori + L <= 2 * nokori) {
        branch++;
      }
    }
    branch %= N;
  } else {
    int counter = V[0].size();
    branch += N - ((T/L) * 2 * counter)%N;
    branch %= N;
    int nokori = T%L;
    for (auto x : V[0]) {
      int kyori = (X[0] + L - x)%L;
      if (kyori <= 2 * nokori) {
        branch += (N-1);
      }
      if (kyori + L <= 2 * nokori) {
        branch += (N-1);
      }
    }
    branch %= N;
  }
  cerr << "branch = " << branch << endl;
  int memo = ans[0];
  cerr << "memo = " << memo << endl;
  sort(ans, ans+N);
  int zahyo = 0;
  if (W[0] == 0) {
    for (auto i = N-1; i >= 0; --i) {
      if (memo == ans[i]) {
        zahyo = (i + N - branch)%N;
        break;
      }
    }    
  } else {
    for (auto i = 0; i < N; ++i) {
      if (memo == ans[i]) {
        zahyo = (i + N - branch)%N;
        break;
      }
    }    
  }
  cerr << "zahyo = " << zahyo << endl;
  for (auto i = 0; i < N; ++i) {
    cout << ans[(zahyo + i)%N] << endl;
  }
}

