  REP(i,n){
    x[i] = getInt();
    w[i] = getInt();
  }

  int k = 0;
  while(k != n && w[k] != 1) k++;

  if(k == n){
    REP(i,n){
      int p = (x[i] - t) % l;
      if(p < 0) p += l;
      printf("%d\n", p);
    }
    return 0;
