    if(xx < x[k]) xx += l;

    int diff = xx - x[k];
    int dt = diff / 2 + diff % 2;

    if(dt < t) {
      cnt++;

      int rest = t - dt;
      cnt += (rest - 1) / l;

      const int r = rest % l;
      if(diff % 2 == 0){
        if(r + r > l) cnt++;
      }else{
        if(r + r >= l) cnt++;
