        rep(i, 0, N) {
            if(w[0] != w[i]) {
                ini += calc(x[0], x[i]);
                ini %= N;
            }
        }
    } else {
        rep(i, 0, N) {
            if(w[0] != w[i]) {
                ini -= calc(x[i], x[0]);
                ini += N;
                ini %= N;
            }
        }
    }
    sort(all(y));
    rep(i,0,N){
        z[i] = y[(i + ini + N) % N];
    }
