			if (W[0] != W[i]) {
				ll dis = X[i] - X[0];
				if (dis < 0) {
					dis += L;
				}

				count[i] = (2 * T - dis-1) / L + int(dis <= 2 * T);

			}
		}
		else {

			if (W[0] != W[i]) {
				ll dis = X[0]-X[i];
				if (dis < 0) {
					dis += L;
				}

				count[i] = (2 * T - dis-1) / L + int(dis <= 2 * T);

			}

		}
	}

	if (W[0] == 1) {
		for (int i = 0; i < N; i++) {
			sum += count[i];
		}
	}
	else {

		for (int i = 0; i < N; i++) {
			sum -= count[i];
		}
	}

	sum %= N; // ゼッケンの番号
	if (sum < 0) {
		sum += N;
	}

	int x;// ゼッケンがsumの蟻の座標
	if (W[0] == 1) {
		x = (X[0] + T) % L; 
	}
	else {
		x = (X[0] - T) % L;
		if (x < 0) {
			x += L;
		}
	}


	// すべての蟻の座標
	vll new_X(N);
	for (int i = 0; i < N; i++) {
		if (W[i] == 1) {
			new_X[i] = (X[i] + T) % L;
		}
		else {
			new_X[i] = (X[i] - T) % L;
			if (new_X[i] < 0) {
				new_X[i] += L;
			}
		}
	}

	sort(new_X.begin(), new_X.end());

	// 
	auto Iter1 = lower_bound(new_X.begin(), new_X.end(), x);
	ll sum_idx = Iter1 - new_X.begin();

	vll ans(N);
	for (int i = 0; i < N; i++) {
		ans[(i+sum)%N] = new_X[(sum_idx + i)%N];
	}

	for (int i = 0; i < N; i++) {
		cout << ans[i] << endl;
	}


}

