void solve() {
    ll n, l, t;
    cin >> n >> l >> t;
    rep(i,0,n) {
        cin >> x[i] >> w[i];
        if (w[i] == 2) w[i] = -1;
    }

    vector<ll> resX;
    rep(i,0,n) {
        resX.push_back((x[i]+w[i]*t+l*t)%l);
    }
    ll cntX = 0;
    rep(i,1,n) {
        if (w[i] != w[0]) {
            ll dist = (x[i]-x[0]+l)%l;
            if (w[0] == -1)
                dist = (x[0]-x[i]+l)%l;
            if (2*t < dist) continue;
            cntX += 1+(2*t - dist)/l;
        }
    }
    if (w[0] == -1)
        cntX *= -1;
    cntX = (cntX+n*t)%n;
    // ant at x[0]+w[0]*t is ant #cntX
    sort(resX.begin(), resX.end());
    ll tar = (x[0]+w[0]*t+l*t)%l;
    ll ans[N];
    rep(i,0,n) {
        if (resX[i] == tar) {
            ans[cntX] = resX[i];
            cntX = (cntX+1)%n;
            ll j = (i+1)%n;
            while (j != i) {
                ans[cntX] = resX[j];
                cntX = (cntX+1)%n;
                j = (j+1)%n;
            }
            break;
        }
    }

    rep(i,0,n)
        cout << ans[i] << endl;

}


