// [l, r) from l to r
struct range {
  struct itr {
    int i;
    constexpr itr(int i_): i(i_) { }
    constexpr void operator ++ () { ++i; }
    constexpr int operator * () const { return i; }
    constexpr bool operator != (itr x) const { return i != x.i; }
  };
  const itr l, r;
  constexpr range(int l_, int r_): l(l_), r(std::max(l_, r_)) { }
  constexpr itr begin() const { return l; }
  constexpr itr end() const { return r; }
};

// [l, r) from r to l
struct revrange {
  struct itr {
    int i;
    constexpr itr(int i_): i(i_) { }
    constexpr void operator ++ () { --i; }
    constexpr int operator * () const { return i; }
    constexpr bool operator != (itr x) const { return i != x.i; }
  };
  const itr l, r;
  constexpr revrange(int l_, int r_): l(l_ - 1), r(std::max(l_, r_) - 1) { }
  constexpr itr begin() const { return r; }
  constexpr itr end() const { return l; }
};

int64_t mod(int64_t x, int64_t md) {
  x %= md;
  if (x < 0) {
    x += md;
  }
  return x;
}

int main() {
  int64_t N, L, T;
  std::cin >> N >> L >> T;
  std::vector<int64_t> X(N), D(N);
  std::vector<std::pair<int64_t, int>> after(N);
  for (int i: range(0, N)) {
    std::cin >> X[i] >> D[i];
    D[i] = (D[i] == 1 ? 1 : -1);
    after[i] = { mod(X[i] + D[i] * T, L), i };
  }
  std::sort(after.begin(), after.end());
  int64_t count = 0;
  if (D[0] == 1) {
    for (int i: range(1, N)) {
      if (D[i] == -1) {
        int64_t val = 2 * T - (X[i] - X[0]);
        if (val >= 0) {
          count += val / L + 1;
        }
      }
    }
  }
  else {
    for (int i: range(1, N)) {
      if (D[i] == 1) {
        int64_t val = 2 * T - (L - X[i] + X[0]);
        if (val >= 0) {
          count -= val / L + 1;
        }
      }
    }
  }
  count = mod(count, N);
  int pos = -1;
  for (int i: range(0, N)) {
    if (after[i].second == 0) {
      pos = i;
      break;
    }
  }
  std::vector<int64_t> ans(N);
  for (int i: range(0, N)) {
    ans[mod(count + i, N)] = after[mod(pos + i, N)].first;
  }
  for (int x: ans) {
    std::cout << x << '\n';
  }
  return 0;
}

