int n, w[maxn], pos;
ll l, t, x[maxn], y[maxn], ans[maxn];

bool intersects(ll a, ll b, ll c, ll d) {
	if (b > l) {
		a -= l;
		b -= l;
	}
	if (d > l) {
		c -= l;
		d -= l;
	}

	bool res = false;
	res |= (max(a, c) <= min(b, d));

	if (a < 0 && c > 0) {
		c -= l;
		d -= l;
	}
	else if (a > 0 && c < 0) {
		a -= l;
		b -= l;
	}
	res |= (max(a, c) <= min(b, d));
	return res;
}

void calcPos() {
	if (w[0] == 1) {
		for (int i = 1; i < n; i++) {
			if (w[i] == 2 && intersects(x[0], y[0], y[i], x[i])) {
				pos++;
			}
		}
	}
	else {
		for (int i = n - 1; i >= 0; i--) {
			if (w[i] == 1 && intersects(y[0], x[0], x[i], y[i])) {
				pos--;
			}
		}
	}
	pos = (pos + n) % n;
}

