inline void norm(double &xx) {
    long long f = max(0LL, (long long)ceil(-xx / l + 1e-9));
    xx += f * l;
    f = max(0LL, (long long)floor(xx / l + 1e-9));
    xx -= f * l;
}


int main() {    
    int tt;
    n = readInt(), l = readInt(), tt = readInt();
    //t = tt % l;
    t = tt;
    for (int i = 0; i < n; i++) {
        x[i] = readInt(), w[i] = readInt();
    }
    set<pair<double, int> > s;
    for (int i = 0; i < n; i++) {
        if (w[i] == 1) {
            if (w[(i + 1) % n] == 2) {
                if (i == n - 1) {
                    s.insert(make_pair(l - x[i] + x[0], i));
                } else {
                    s.insert(make_pair(x[i + 1] - x[i], i));
                }
            } 
        }
    }
    double curadd = 0;
    while (t > 0) {
        if (s.empty()) {
            curadd += t;
            break;
        }
        pair<double, int> a = *s.begin();
        s.erase(a);
        x[a.second] += curadd - last[a.second];
        x[(a.second + 1) % n] -= curadd - last[(a.second + 1) % n];
        norm(x[a.second]);
        norm(x[(a.second + 1) % n]);
        a.first = (x[a.second] <= x[(a.second + 1) % n] + 1e-9 ? x[(a.second + 1) % n] - x[a.second]: l - x[a.second] + x[(a.second + 1) % n]);
        if (a.first / 2.0 > t) {
            last[a.second] = curadd; 
            last[(a.second + 1) % n] = curadd; 
            curadd += t;
            break;
        }
        w[a.second] = 2;
        w[(a.second + 1) % n] = 1;
        x[a.second] += a.first / 2.0;
        x[(a.second + 1) % n] -= a.first / 2.0; 
        norm(x[a.second]);
        norm(x[(a.second + 1) % n]);
        curadd += a.first / 2.0;
        last[a.second] = curadd; 
        last[(a.second + 1) % n] = curadd; 
        if (w[(a.second + 2) % n] == 2) {
            double pos = x[(a.second + 2) % n] - (curadd - last[(a.second + 2) % n]);
            norm(pos);
            double time = (x[(a.second + 1) % n] <= pos ? (pos - x[(a.second + 1) % n]): (l - x[(a.second + 1) % n] + pos));
            s.insert(make_pair(time, (a.second + 1) % n));
        }
        if (w[(a.second - 1 + n) % n] == 1) {
            double pos = x[(a.second - 1 + n) % n] + (curadd - last[(a.second - 1 + n) % n]);
            norm(pos);
            double time = (pos <= x[a.second] ? (x[a.second] - pos): (l - pos + x[a.second]));
            s.insert(make_pair(time, (a.second - 1 + n) % n));
        }
        t -= a.first / 2.0;
    }
    for (int i = 0; i < n; i++) {
        if (w[i] == 1) {
            x[i] += curadd - last[i];
        } else {
            x[i] -= curadd - last[i];
        }
        norm(x[i]);
        writeInt(((int)round(x[i]) + l) % l, '\n');
    }
    return 0;
}

