const int N = 100500;

int n, w[N];
ll L, T, xa[N];

ll sred(ll x, ll y){
	if(x <= y)
		return (x + y) / 2;
	y += L;
	return ((x + y) / 2) % L;
}

ll dist(ll x, ll y, int W){
	if(W == 2)
		swap(x, y);
	if(x <= y)
		return y - x;
	return L - (x - y);
}

ll get(int num, ll t2){
	ll t1 = 0;
	queue <int> q1, q2;
	for(int i = 1; i < n; ++i)
		if(w[(num - i + n) % n] == 1)
			q1.push(xa[(num - i + n) % n]);
	for(int i = 1; i < n; ++i)
		if(w[(num + i) % n] == 2)
			q2.push(xa[(num + i) % n]);
	ll x = xa[num], W = w[num];
	while(t1 < t2){
		if(W == 1){
			if(q2.empty()){
				x += (t2 - t1);
				x %= L;
				break;
			}
			ll y = q2.front();
			q2.pop();
			y -= t1;
			y %= L;
			y += L;
			y %= L;
			ll z = sred(x, y);
			ll ti = dist(x, z, 1);    
			if(t1 + ti >= t2){
				x += (t2 - t1);
				x %= L;
				break;
			}
			t1 += ti;
			q1.push((((z - t1) % L) + L) % L);
			t1++;
			x = z;
			x = ((x - 1) + L) % L;
		}else{
		    if(q1.empty()){
		    	x -= (t2 - t1);
		    	x %= L;
		    	x += L;
		    	x %= L;
		    	break;
		    }
		    ll y = q1.front();
		    q1.pop();
		    y += t1;
		    y %= L;
		    ll z = sred(y, x);
		    ll ti = dist(x, z, 2);

		    if(t1 + ti >= t2){
		    	x -= (t2 - t1);
		    	x %= L;
		    	x += L;
		    	x %= L;
		    	break;
		    }
		    t1 += ti;
			q2.push((z + t1) % L);
			x = z;
			x = (x + 1) % L;
			t1++;
		}
		W = 3 - W;
	}
	return x;
}

