#include<bits/stdc++.h>
#include<queue>
#define N 100001
using namespace std;
int n,L,t;
int ans[N];
struct Node
{
	int x;
	int w;
	int id;
	double tim;
}ant[N];
struct Edge
{
	int u,v;
	double tim;
};
bool operator <(const Edge &a,const Edge &b)
{ 
	return a.tim<b.tim; 
}
bool compare(Edge a,Edge b)
{
	return a.tim<b.tim;
}
priority_queue<Edge> que;
bool cmp(Node a,Node b)
{
	return a.tim<b.tim;
}
double dis(int u,int v)
{
	if(ant[u].w==ant[v].w)
	{
		if(ant[u].x==ant[v].x)return 0;
	}
	else
	{
		if(ant[u].w==1&&ant[v].w==2)return abs(ant[u].x-ant[v].x)/2.0;
		if(ant[u].w==2&&ant[v].w==1)return (L-abs(ant[u].x-ant[v].x))/2.0;
	}
}
double inter(int u,int v)
{
	if(ant[u].w==1&&ant[u].w==2)
	{
		return ant[u].x+dis(u,v)/2>L?ant[u].x+dis(u,v)/2-L:ant[u].x+dis(u,v)/2;
	}
	else
	{
		return (ant[v].x+(L-abs(ant[u].x-ant[v].x))/2+L)%L;
	}
}
int main()
{
	scanf("%d%d%d",&n,&L,&t);
	for(int i=1;i<=n;i++)
	{
		scanf("%d%d",&ant[i].x,&ant[i].w);
		if(ant[i].w==1)
		{
			ant[i].x=(ant[i].x+t)%L;
		}
		else
		{
			ant[i].x=ant[i].x-t;
			while(ant[i].x<0)ant[i].x+=L;
		}
		ant[i].id=i;
	}
	ant[0].x=ant[n].x;ant[0].w=ant[n].w;
	for(int i=1;i<=n;i++)
	{
		que.push((Edge){i,(i+1)%n,dis(i,(i+1)%n)});
	}
	double sum=0;
	while(sum<t)
	{
		int u=que.top().u;
		int v=que.top().v;
		que.pop();
		sum+=dis(u,v);
		if(sum>t)break;
		swap(ant[u],ant[v]);
		que.push((Edge){u-1,v,dis(u-1,v)-sum});
		que.push((Edge){u,v+1,dis(u,v+1)-sum});
	}
	for(int i=1;i<=n;i++)
	{
		ans[ant[i].id]=ant[i].x;
	}
	printf("%d\n",ans[n]);
	for(int i=1;i<n;i++)
	{
		printf("%d\n",ans[i]);
	}
}

