typedef long long ll;

int main()
{
	ll N, L, T; cin >> N >> L >> T;
	vector<ll>X(N), W(N);
	for (int i = 0; i < N; i++) {
		cin >> X[i] >> W[i];
	}

	vector<pair<double,int>>Y(N);
	for (int i = 0; i < N; i++) {
		ll y = X[i];
		if (W[i] == 1) {
			y += T;
			y %= L;
		}
		else {
			y -= T%L;
			y = (y + L) % L;
		}
		Y[i].first = y + 0.1*(3-W[i]);
		Y[i].second = i;
	}
	sort(Y.begin(), Y.end());

	int cnt = 0;
	for (int i = 1; i < N; i++) {
		if (W[0] != W[i]) {
			cnt += 2 * (T/L);

			int D;
			if (W[0] == 1) {
				if (X[0] > X[i])D = X[i] + L - X[0];
				else D = X[i] - X[0];
			}
			else {
				if (X[0] < X[i])D = X[0] + L - X[i];
				else D = X[0] - X[i];
			}

			int tmpT = T%L;
			if (D <= 2 * tmpT)cnt++;
			tmpT -= ceil(D / 2.);
			D = L - D % 2;
			if (D <= 2 * tmpT)cnt++;
		}
	}

	cnt %= N;
	for (int i = 0; i < N; i++) {
		if (Y[i].second == 0) {
			cnt = (N + i + (W[0] == 1 ? -cnt : cnt)) % N;
			break;
		}
	}

	for (int i = cnt; i < N; i++) {
		cout << (int)Y[i].first << endl;
	}
	for (int i = 0; i < cnt; i++) {
		cout << (int)Y[i].first << endl;
	}

    return 0;
}

