signed main() {
	INIT;
	VAR(int, n, l, t);
	VEC_ROW(int, n, x, w);
	std::vector<PAIR> d(n);
	REP(i, n) {
		d[i].first = (x[i] + t * ((w[i] == 1) ? 1 : -1)) % l;
		if (d[i].first < 0) d[i].first += l;
		d[i].second = i;
	}
	int cnt = 0;
	REP(i, n) {
		if (w[i] == w[0]) continue;
		int di = x[i] - x[0];
		int tmp = (di + 1) / 2;
		if (l % 2 == 0) {
			if (tmp <= t) {
				cnt += 1 + (t - tmp) / (l / 2);
			}
		}
		else {
			if (tmp <= t) {
				int y = (t - tmp) / l;
				cnt += 1 + y * 2;
				if (di % 2 == 0) {
					if (t - tmp - y*l >= (l + 1) / 2) ++cnt;
				}
				else {
					if (t - tmp - y*l >= l / 2) ++cnt;
				}
			}
		}
	}
	cnt %= n;
	if (w[0] == 2) cnt = (n - cnt) % n;
	std::vector<int> ans(n);
