		if (d[i].second == 0) {
			REP(ii, n) {
				ans[(ii + cnt) % n] = d[(ii + i) % n].first;
			}
			break;
		}
	}
	REP(i, n) {
		OUT(ans[i])BR;
	}
	return 0;
}

