using namespace std;

const int N=100010;

int n,l,t;
int a[N],b[N],c[N],nxt[N];

inline int dist(int x,int y){
	return (a[x]+l-a[y])%l;
}

int main(){
	scanf("%d%d%d",&n,&l,&t);
	for(int i=1;i<=n;i++)
		scanf("%d%d",&a[i],&b[i]),c[i]=(a[i]+(b[i]==1?1:-1)*t%l+l)%l;
	sort(c+1,c+1+n);
	int p=-1,dis;
	for(int i=n;i;i--)
		if(b[i]!=b[1]) p=i,dis=(a[i]+l-a[1])%l;
	int pos=(a[1]+(b[1]==1?1:-1)*t%l+l)%l;
	t*=2;
	if(p!=-1 && dis<t*2){
		int lst=1;
		for(int i=n;i;i--)
			if(b[i]==b[1]) nxt[i]=lst,lst=i;
		lst=p;
		for(int i=1;i<=n;i++)
			if(b[i]!=b[1]) nxt[i]=lst,lst=i;
		t-=dis; t%=2*l;
		int j=1;
		for(int i=2;i<=n;i++)
			if(b[i]==b[1]){
				j=i; break;
			}
		int i=p,cb=1;
		while(1){
			if(cb==1){
				if(dist(j,nxt[j])>t){
					pos=c[i]; break;
				}
				t-=dist(j,nxt[j]);
				cb=2; j=nxt[j];
			}
			else{
				if(dist(i,nxt[i])>t){
					pos=(a[i]+(b[i]==1?1:-1)*t/2%l+l)%l;
					break;
				}
				t-=dist(i,nxt[i]); cb=1; i=nxt[i];
			}
		}
	}
	int bg=lower_bound(c+1,c+1+n,pos)-c;
	for(int i=1;i<=n;i++) printf("%d\n",c[(i+bg-2)%n+1]);
	return 0;
}

