typedef long long ll;

void solve(long long N, long long L, long long T, std::vector<long long> X, std::vector<long long> W){
    ll count = 0;    
    for (int i=1;i<N;i++){
        ll init_pos;
        if (W[0] ==1 &&  W[i] == 2){
            init_pos = X[i]-X[0];
            if (2*T >= init_pos){
                count += 1 + (2*T - init_pos)/L;
            }
        }else if (W[0] ==2 &&  W[i] == 1){
            init_pos = L - (X[i]-X[0]);
            if (2*T >= init_pos){
                count += 1 + (2*T - init_pos)/L;
            }
        }else{
                // pass
        } 
    }
    int number = (W[0]==1)? count%N : (N +(-count %N))%N;
    vector<ll> final_pos(N,0);
