void solve() {                   
	scanf("%d %d %d", &n, &m, &lim);

	for (int i = 0; i < n; ++i) {
		scanf("%d %d", &arr[i].fi, &arr[i].se);

		if (arr[i].se == 2) {
			arr[i].se = -1;
		}
	}

	for (int i = 0; i < n; ++i) {
		pt[i] = mp(arr[i].fi + arr[i].se * lim, i);
		pt[i].fi = (pt[i].fi % m + m) % m;
	}

	sort(pt, pt + n);
	int one = 0, p = 0;

	for (int i = 1; i < n; ++i) {
		if (arr[i].se == arr[0].se) {
			continue;
		}

		if (arr[0].se == 1) {
		    int t = arr[i].fi - arr[0].fi;

		    if (0 <= t && t <= lim * 2) {
		    	int add = ((2ll * lim - t) / m + 1ll) % n;
		    	one += add;
				one %= n;

				if (one < 0) {
					one += n;
				}		    	
		    }

		}
		else {
			int t = arr[0].fi - arr[i].fi + m;

			if (0 <= t && t <= lim * 2) {
				int add = ((2ll * lim - t) / m + 1ll) % n;
				one -= add;
				one %= n;

				if (one < 0) {
					one += n;
				}
			}
		}
	}

