    	col[(p + i) % n] = (one + i) % n;
    }

    for (int i = 0; i < n; ++i) {
    	ans[col[i]] = pt[i].fi;
    }

    for (int i = 0; i < n; ++i) {
    	printf("%d\n", ans[i]);
    }
}

