const int maxn = (int) 1e5 + 5;
int n;
long long l, t;
long long x[maxn];
int dir[maxn];

int read() {
  if (scanf("%d%lld%lld", &n, &l, &t) < 3) {
    return false;
  }
  l *= 2;
  t *= 2;
  for (int i = 0; i < n; i++) {
    scanf("%lld%d", &x[i], &dir[i]);
    x[i] *= 2;
    dir[i] %= 2;
  }
  return true;
}

long long nx[maxn];
long long res[maxn];

void solve() {
  int id = 0;
  for (int i = 1; i < n; i++) {
    if (dir[i] == dir[0]) {
      continue;
    }
    long long t0;
    if (dir[0]) {
      t0 = ((x[i] - x[0] + l) % l) / 2;
    } else {
      t0 = ((x[0] - x[i] + l) % l) / 2;
    }
    if (t0 > t) {
      continue;
    }
    int cnt = (1 + (t - t0) / (l / 2)) % n;
    if (!dir[0]) {
      cnt = (n - cnt) % n;
    }
    id = (id + cnt) % n;
  }
  for (int i = 0; i < n; i++) {
    nx[i] = ((x[i] + t * (2 * dir[i] - 1)) % l + l) % l;
  }
  long long x0 = nx[0];
  sort(nx, nx + n);
  int pos = (dir[0] ? -inf : inf);
  for (int i = 0; i < n; i++) {
    if (nx[i] == x0) {
      if (dir[0]) {
        pos = max(pos, i);
      } else {
        pos = min(pos, i);
      }
    }
  }
  for (int it = 0; it < n; it++) {
    res[id] = nx[pos];
    pos = (pos + 1) % n;
    id = (id + 1) % n;
  }
  for (int i = 0; i < n; i++) {
    printf("%lld\n", res[i] / 2);
  }
}

