int main(){
    ll N,L,T;
    cin>>N>>L>>T;
    vector<ll> X(N),W(N);
    REP(i,N){
        cin>>X[i];
        cin>>W[i];
    }
    //inputend
    ll meet;
    REPi(i,1,N){
        if(W[0]!=W[i]){
            ll dist=0;
            if((X[i]-X[0]>=0&&W[0]==1)||(X[i]-X[0]<=0&&W[0]==2)){
                dist=abs(X[i]-X[0]);
            }else{
                dist=L-abs(X[i]-X[0]);
            }
            if(dist>2*T){
                meet+=0;
            }else{
                meet+=(2*T-dist)/L+1;
            }
            meet%=N;
            }
        }
    if(W[0]==1){
        //最初に入力された蟻がそのまま進んでmeet番目のゼッケンをつけている
    }else{
        meet=N-meet;
        //最初に入力された蟻はそのまま進んでmeet番目のゼッケンをつけている．
    }
    vector<ll> Xp(N);
    ll first_ant;
    REP(i,N){
        if(W[i]==1){
        Xp[i]=(X[i]+T)%L;
        }else{
        Xp[i]=(X[i]-T)%L;
        }
        if(Xp[i]<0){
            Xp[i]+=L;
        }
    }
    first_ant=Xp[0];
    sort(ALL(Xp));
    auto iter=lower_bound(ALL(Xp),first_ant);
    ll ant_number=distance(Xp.begin(),iter);
    //meet番目のゼッケンをつけた蟻の位置はベクトル中でant_number番目
    //0番目のゼッケンをつけた蟻の位置は(ant_number-meet)%N番目
    //i番目のゼッケンをつけた蟻の位置は(ant_number-meet+i)%N番目

    REP(i,N){
        cout<<Xp[(ant_number-meet+i)%N]<<endl;
    }
}

