using namespace std;

const int N = 1e5 + 5;
const double eps = 1e-4;

int n, l, t, x[N], w[N];
int a[N], X, W, ans;
int np, nq, p[N], q[N], pp, pt, qq, qt;

double f(double x) {
	if (x < 0) return x + l;
	if (x > l) return x - l;
	return x;
}

int solve() {
	int np = 0, nq = 0;

	for (int i = 1; i <= n; i++)
		if (w[i] == -1) p[++np] = x[i];
	pp = p[1] - x[1];
	pt = p[1] + l - p[np];
	for (int i = np; i >= 2; i--)
		p[i] = p[i] - p[i - 1];
	p[1] = pt;

	for (int i = n + 1; i >= 1; i--)
		if (w[i] == 1) q[++nq] = x[i];
	qq = x[1] + l - q[1];
	qt = q[nq] + l - q[1];
	for (int i = nq; i >= 2; i--)
		q[i] = q[i - 1] - q[i];
	q[1] = qt;

	double xx = x[1], tt = t;
	W = w[1];
	if (W == 1) {
		tt -= pp / 2.0;
		xx += W * pp / 2.0;
		xx = f(xx);
		if (tt < eps) return f(xx + tt * W);
		W *= -1;
		pp = 1; qq = 0;
	} else {
		tt -= qq / 2.0;
		xx += W * qq / 2.0;
		xx = f(xx);
		if (tt < eps) return f(xx + tt * W);
		W *= -1;
		qq = 1; pp = 0;
	}
	while (tt > eps) {
	//printf("%.2f\n", xx);
		if (W == 1) {
			pp = pp % np + 1;
			tt -= p[pp] / 2.0;
			xx += W * p[pp] / 2.0;
			xx = f(xx);
			if (tt < eps) return f(xx + tt * W);
			W *= -1;
		} else {
			qq = qq % nq + 1;
			tt -= q[qq] / 2.0;
			xx += W * q[qq] / 2.0;
			xx = f(xx);
			if (tt < eps) return f(xx + tt * W);
			W *= -1;
		}
	}
}

int main() {
	scanf("%d%d%d", &n, &l, &t);
	for (int i = 1; i <= n; i++) {
		scanf("%d%d", &x[i], &w[i]);
		if (w[i] == 2) w[i] = -1;
		a[i] = ((x[i] + w[i] * t) % l + l) % l;
	}
	sort(a + 1, a + n + 1);
	X = 0;
	if (n != 1) X = (solve() % l + l) % l; //printf("%d\n", X);
	ans = 1;
	for (int i = 1; i <= n; i++) {
		if (a[i] == X) {
			ans = i;
			break;
		}
	}
	if (ans < n && a[ans] == a[ans + 1] && W == -1) ans++;
	for (int i = 1; i <= n; i++) {
		printf("%d\n", a[ans]);
		ans = ans % n + 1;
	}
	return 0;
}

