using namespace std;

typedef pair<int, int> pii;

int N, L, T;

vector<pii> A;
vector<int> B, C, P;

int f(int x, vector<int> &a) {
    int s = 0, e = a.size() - 1;
    int ret = -1;
    while(s <= e) {
        int m = (s + e)>>1;
        if(a[m] <= x) {
            ret = m;
            s = m + 1;
        }
        else e = m - 1;
    }
    return ret + 1;
}

int main() {
    scanf("%d %d %d", &N, &L, &T);

    A.resize(N);

    for(int i = 0; i < N; i++) {
        scanf("%d %d", &A[i].first, &A[i].second);
        if(A[i].second == 1) B.push_back(A[i].first);
        else C.push_back(A[i].first);
    }

    P.resize(N);

    for(int i = 0; i < N; i++) {
        long long q = 2*T / L;
        long long r = 2*T % L;
        int s, e;
        long long cnt;

        if(A[i].second == 1) {
            s = A[i].first;
            e = (A[i].first + r) % L;
        }
        else {
            s = (A[i].first + L - r) % L;
            e = A[i].first;
        }
        cnt = q * (long long)(A[i].second == 1? C.size() : B.size());

        if(s <= e) cnt += f(e, A[i].second == 1? C : B) - f(s - 1, A[i].second == 1? C : B);
        else {
            cnt += f(L - 1, (A[i].second == 1? C : B)) - f(s - 1, (A[i].second == 1? C : B));
            cnt += f(e, (A[i].second == 1? C : B));
        }
        P[ ((long long)i + (A[i].second == 1? cnt : (long long)N - cnt % N)) % N ] = (A[i].first + (A[i].second == 1? T : L - T % L)) % L;
    }

    for(int i = 0; i < N; i++) {
        printf("%d\n", P[i]);
    }
}

