         mjk.push_back((x[fi] + dis/2 + l/2));
      }
   }
   if (!mjk.size()){
      for(int i=0;i<n;i++) printf("%lld\n", ((x[i] + t + l) % l) / 2);
      return 0;
   }

   sort(mjk.begin(),mjk.end());
   mjk.resize(distance(mjk.begin(),unique(mjk.begin(),mjk.end())));

   int pos = lower_bound(mjk.begin(),mjk.end(),x[fi]) - mjk.begin();
   if (mjk[pos] < x[fi]) pos = 0;

   ll old = fi;
   ll zz = x[fi];
   ll cnt = t / l;
   fi = (fi + cnt * mjk.size()) % n;
   ll rt = t;
   t -= cnt * l;

   for(int i=pos;;i=(i+1)%mjk.size()){
      if (mjk[i] - zz > t) break;
      t -=  mjk[i] - zz;
      fi = (fi + 1) % n;
      zz = zz + mjk[i] - zz;
   }

   ll dem = 0;
   for(int i=fi;;i=(i+1)%n){
      if (dem && i == fi) break;
      dem++;
      if (w[old] == 1) ans[i] = (x[old] + rt + l) % l / 2;
      else ans[i] = (x[old] - rt + l) % l / 2;
      old = (old + 1) % n;
   }

   for(int i=0;i<n;i++) printf("%lld\n",ans[i]);
}

