			else C[i] = pii(L, 1);
		} else {
			ll x = ll(A[i]) - T;
			x %= L;
			x = (x + L) % L;
			C[i] = pii(x, 2);
		}
	}
	sort(C+1, C+N+1);

	//for(int i = 1; i <= N; i++)
    //  printf("%d : %d %d : %d %d\n", i, A[i], B[i], C[i].first, C[i].second);

	{
		ll sum = 0;
		for(int i = 2; i <= N; i++) {
			if(1 == B[i] || 2*T <= A[i]) continue;
			sum += (2*T - A[i]) / L + 1;
		}
		sum %= N;

		int idx = (1+sum) % N;
		if(!idx) idx = N;

		if(F && 1 != idx) {
            idx = N+2-idx;
		}

		//printf("sum=%lld, idx=%d\n", sum, idx);

		pii p = pii((A[1]+T)%L, 1);
		int i = 1;
		for(; C[i] != p; i++);

		for(int j = 0; j < N; j++) {
			int x = (!F) ? ((idx+j) % N) : ((idx-j+N) % N);
			if(!x) x = N;

			int y = (i+j) % N;
			if(!y) y = N;

			//printf("x=%d, y=%d\n", x, y);

			Ans[x] = C[y].first;
		}
	}

	if(F) {
		for(int i = 1; i <= N; i++)
			Ans[i] = (L-Ans[i]) % L;
	}
	for(int i = 1; i <= N; i++)
		Ans[i] = (Ans[i] + X) % L;

	for(int i = 1; i <= N; i++)
		printf("%d\n", Ans[i]);
	return 0;
}

