class modint;
modint pow(modint, size_t);
ll MOD = ll(1e9)+7;

class modint {
public:
  ll value;

  modint(int x): modint((ll)x) { }
  modint(ll x = 0): value(x) {
    value %= MOD;
    if (value < 0) value += MOD;
  }
  bool operator==(const modint& rhs) {
    return value == rhs.value;
  }
  bool operator!=(const modint& rhs) {
    return value != rhs.value;
  }
  modint operator+(const modint& rhs) const {
    return modint(*this) += rhs;
  }
  modint operator-(const modint& rhs) const {
    return modint(*this) -= rhs;
  }
  modint operator*(const modint& rhs) const {
    return modint(*this) *= rhs;
  }
  modint operator/(const modint& rhs) const {
    return modint(*this) /= rhs;
  }
  modint &operator+=(const modint& rhs) {
    value += rhs.value;
    if (value >= MOD) value -= MOD;
    return *this;
  }
  modint &operator-=(const modint& rhs) {
    if (value < rhs.value) value += MOD;
    value -= rhs.value;
    return *this;
  }
  modint &operator*=(const modint& rhs) {
    value = value * rhs.value % MOD;
    return *this;
  }
  modint &operator/=(const modint& rhs) {
    return *this *= pow(rhs, MOD - 2);
  }
  modint &operator++() {
    return *this += 1;
  }
  modint operator++(int) {
    modint tmp(*this);
    ++(*this);
    return tmp;
  }
  modint &operator--() {
    return *this -= 1;
  }
  modint operator--(int) {
    modint tmp(*this);
    --(*this);
    return tmp;
  }
  operator int() const {
    return (int)value;
  }
  operator ll() const {
    return value;
  }
  bool operator<(const modint& rhs) const {
    return value < rhs.value;
  }
};


