        if (w[(a.second + 2) % n] == 2) {
            double pos = x[(a.second + 2) % n] - (curadd - last[(a.second + 2) % n]);
            f = max(0LL, (long long)ceil(-pos / l + 1e-9));
            pos += f * l;
            f = floor(pos / l + 1e-9);
