#include <iostream>
#include <vector>
#include <algorithm>

struct ant {
    int index;
    int position;
    int delta;
};


int main() {
    int n, l, t;
    std::cin >> n >> l >> t;
    std::vector<ant> v;
    v.reserve(n);

    auto cross = [&](ant const& lhs, ant const& rhs) {
        if (lhs.position == 0 && rhs.position == l - 1 &&
            lhs.delta == 1 && rhs.delta == -1) {
            return true;
        }
        if (lhs.position == l - 1 && rhs.position == 0 &&
            lhs.delta == -1 && rhs.delta == 1) {
            return true;
        }
        if (rhs.position - lhs.position == 1 &&
            rhs.delta == 1 && lhs.delta == -1) {
            return true;
        }
        if (lhs.position - rhs.position == 1 &&
            lhs.delta == 1 && rhs.delta == -1) {
            return true;
        }
        return false;
    };

    for (int i = 0; i != n; ++i) {
        int pos, dir;
        std::cin >> pos >> dir;
        v.push_back({ i, pos, dir == 1 ? 1 : -1});
    }
    for (int i = 0; i != t; ++i) {

        for (auto& a : v) {
            a.position += a.delta;
            if (a.position == -1) a.position = l-1;
            else if (a.position == l) a.position = 0;
        }
        std::vector<ant> v2 = v;


        auto update = [&](std::size_t i, std::size_t j) {
            if (cross(v[i], v[j])) {
                std::swap(v2[i].index, v2[j].index);
            }
        };

        for (int i = 1; i != n; ++i) {
            update(i-1, i);
        }
        update(n-1, 0);
        v = v2;
        std::sort(v.begin(), v.end(), [](ant const& lhs, ant const& rhs){ return lhs.index < rhs.index; });
    }
    for (auto const& a : v) {
        auto pos = a.position % l;
        std::cout << pos << std::endl;
    }
}

