				ll t = arr[i].fi - arr[p].fi;

				if (t < 0) {
					t += m;
				}

				if (t >= m) {
					t -= m;
				}

				t >>= 1;

				if (t <= lim - curT) {
					coll[i] = coll[p] = t;
					mx = max(mx, t);
				}
    		}
    	}

