typedef lib::modnum<1000000007> mod_t;

typedef lib::dmod<lib::int_tag<0>> N_t;
typedef lib::dmod<lib::int_tag<1>> L_t;
typedef lib::dmod<lib::int_tag<2>> L2_t;
N_t count(L_t x, L_t y, L_t T)
{
	L2_t X = x.val;
	L2_t Y = y.val;
	L2_t t = 2 * T.val;
	auto m = Y - X;
	auto m2 = m + L2_t(x.mod);
	if (t.val >= m2.val)
	{
		return 2;
	}
	else if (t.val >= m.val)
	{
		return 1;
	}
	else
	{
		return 0;
	}
}
N_t rcount(L_t x, L_t y, L_t T)
{
	return count(x, L_t(2)*x - y, T);
}

void Main()
{
	std::int64_t N, L, T, X, W;
	std::cin >> N >> L >> T >> X >> W;
	L_t::mod = L;
	N_t::mod = N;
	L2_t::mod = 2 * L;
	std::vector<std::int64_t> result;
	if (W == 1)
	{
		result.emplace_back((L_t(X) + L_t(T)).val);
	}
	else
	{
		result.emplace_back((L_t(X) - L_t(T)).val);
	}
	auto start = result.front();
	N_t h{};
	for (int i = 1; i < N; ++i)
	{
		L_t x;
		int w;
		std::cin >> x.val >> w;
		if (w == 1)
		{
			result.emplace_back((L_t(x) + L_t(T)).val);
			if (W == 2)
			{
				h -= rcount(X, x, T) - N_t(2 * (T / L));
			}
		}
		else
		{
			result.emplace_back((L_t(x) - L_t(T)).val);
			if (W == 1)
			{
				h += count(X, x, T) + N_t(2 * (T / L));
			}
		}
	}
	lib::sort(result);
	std::int64_t s = lib::lower_bound(result, start);
	for (int i{}; i < N; ++i)
	{
		std::cout << result[(N_t(s) - h + N_t(i)).val] << std::endl;
	}
	std::cout << start << " " << h.val << " " << s << std::endl;
}

