   for(int i=0;i<n;i++) if (w[i] == 1) fi = i;
   if (w[fi] != 1){
      for(int i=0;i<n;i++) printf("%lld\n", ((x[i] - t + l) % l) / 2);
      return 0;
   }
   for(int i=(fi+1)%n;;i=(i+1)%n){
      if (i == fi) break;
      if (w[i] == 2){
         ll dis = x[i] - x[fi];
         if (dis < 0) dis += l;
         dis %= l;
         mjk.push_back((x[fi] + dis/2) % l);
         mjk.push_back((x[fi] + dis/2 + l/2) % l);
      }
   }
   if (!mjk.size()){
      for(int i=0;i<n;i++) printf("%lld\n", ((x[i] + t + l) % l) / 2);
      return 0;
   }

