      t -=  (mjk[i] - zz + l)%l;
      fi = (fi + 1) % n;
      zz = (zz + (mjk[i] - zz + l)%l) % l;
   }

   ll dem = 0;
   for(int i=fi;;i=(i+1)%n){
      if (dem && i == fi) break;
      dem++;
      if (w[old] == 1) ans[i] = (x[old] + rt + l) % l / 2;
