    rep (i, n) {
        ll x = get<0>(xwlist[i]);
        ll w = get<1>(xwlist[i]);
        if (w == 1) {
            base_idx = i;
            x += tmrem;
            x %= length;
            base_vpos = x;
            break;
        }
    }
    debug_printf("base_idx=%lld base_vpos=%lld\n", base_idx, base_vpos);

    ll colcnt = 0LL;

    ll cnt2 = 0LL;
    for (auto xw : xwlist) {
        ll x = get<0>(xw);
