        if (len < tmrem * 2LL) colcnt++;
    }
    colcnt %= n;
    debug_printf("x2 colcnt=%lld\n", colcnt);

    ll base_nidx = -1LL;
    rep (i, n) {
        if (base_vpos == poslist[i]) {
