    for (int i = 0; i < N; i++) {
        cin >> X[i] >> W[i];
    }
    for (int i = 0; i < N; i++) {
        if (W[i] == 1) A[i] = (X[i] + T % L) % L;
        else A[i] = (X[i] + L - T % L) % L;
    }
    sort(A, A + N);
    int key = (X[0] + T % L) % L;
    if (W[0] == 2) key = (X[0] + L - T % L) % L;

    int idx1;
    if (W[0] == 1) {
        for (int i = 0; i < N; i++) {
            if (A[i] == key) {
                idx1 = i;
                break;
