        if(L <= pos) pos %= L;
        po[i].x = pos;
        po[i].i = (N + (i - start) + 2) % N;
    }
    sort(po, po + N, [](Ant a, Ant b){return a.i < b.i;});
    for(ll i = 0; i < N; i++) cout << po[i].x << endl;
    return 0;
}

