	for(int i=0;i<n;i++)
	{
		V[w[i]].pb(x[i]-L); V[w[i]].pb(x[i]); V[w[i]].pb(x[i]+L);
	}
	sort(V[0].begin(),V[0].end()); sort(V[1].begin(),V[1].end());
	for(int i=0;i<n;i++)
	{
		int ty=w[i];
		int shift = V[ty^1].size()/3;
		if(ty) shift*=-1;
		shift+=i;
		shift%=n;
		if(shift<0) shift+=n;
		st[0][i]=shift;
	}
	for(int i=1;i<LG;i++)
	{
		for(int j=0;j<n;j++)
		{
			st[i][j]=st[i-1][st[i-1][j]];
		}
	}
	ll shiftcnt = ((2LL*t)/L);
	for(int i=0;i<n;i++)
	{
		circles[i] = getnxt(i,shiftcnt);
		//cerr<<circles[i]<<' '; 
	}
