			int lb = lower_bound(V[ty^1].begin(),V[ty^1].end(),x[i]-rem)-V[ty^1].begin();
			int rb = upper_bound(V[ty^1].begin(),V[ty^1].end(),x[i])-V[ty^1].begin();
