#define rrep1(i,x) for(ll i=x;i>0;i--)

ll N,L,T;
ll x[100000],w[100000];
ll ans[100000];
vector<ll> l,r;

ll solve(ll id){
	ll pos=x[id];
	ll cnt=0;
	ll t=T;
	ll cnl,cnr;
	l.clear();
	r.clear();
	rep(i,N){
		if(i==id){
			if(w[i]==1) l.pb(L);
			else r.pb(L);
		}
		else if(w[i]==1){
			l.pb( (pos-x[i]+L)%L );
		}
		else{
			r.pb( (x[i]-pos+L)%L );
		}
	}

	if(l.size()){
		l.pb(l[0]+L);
		sort(l.begin(),l.end());
	}
	if(r.size()){
		r.pb(r[0]+L);
		sort(r.begin(),r.end());
	}
	rrep1(i,l.size()-1){
		l[i]=l[i]-l[i-1];
	}
	rrep1(i,r.size()-1){
		r[i]=r[i]-r[i-1];
	}

	if(w[id]==2) cnt=1;//はん時計
	cnl=0;
	cnr=0;
	while(1){
		cnt++;
		if(cnt%2==0){//とけい
			if(r.size()==0){
				return (pos+t)%L;
			}
			cnr%=r.size();
			if(r[cnr]/2>=t){
				return (pos+t)%L;
			}
			pos+=r[cnr]/2;
			t-=r[cnr]/2;
			cnr++;
		}
		else{
			if(l.size()==0){
				return ((pos-t)%L+L)%L;
			}
			cnl%=l.size();
			if(l[cnl]/2>=t){
				return ((pos-t)%L+L)%L;
			}
			pos-=l[cnl]/2;
			t-=l[cnl]/2;
			cnr++;
		}
	}
}

