		}
	}
	sort(ans,ans+N);
	ll m=solve(0);
	ll n=solve(1);
	ll ori;
	if(m==n){
		ori=lower_bound(ans,ans+N,m)-ans;
	}
	else{
		ori=upper_bound(ans,ans+N,m)-ans-1;
	}
	rep(i,N){
		cout<<ans[(i+ori)%N]/2<<endl;
	}
}

