bool inRange(int x, int lo, int hi)
{
  debug("%d %d %d\n",x,lo,hi);
  if (lo > hi) swap(lo,hi);
  if (hi - lo >= l - 1) return 1;
  x %= l;
  lo %= l;
  hi %= l;
  if (x < 0) x += l;
  if (lo < 0) lo += l;
  if (hi < 0) hi += l;
  if (lo > hi) 
  {
    return x <= lo || x >= hi;
  }
  // debug("%d %d %d %d\n",x,lo,hi,lo <= x && x <= hi);
  return lo <= x && x <= hi;
}

