				ll dist = (pos - opos + l) % l;
				if (dist > 0 && cur + (dist >> 1) <= t) {
					cur += dist >> 1;
					pos = (pos - (dist >> 1) + l) % l;
					dir = 1;
				}
				else {
					pos = (pos - t + cur + l) % l;
					cur = t;
				}
			}
		}
