        px[i] = p;
        place.emplace_back(p, i);
    }
    if (n == 1) {
        cout << px[0] << "\n";
        return 0;
    }
    sort(place.begin(), place.end());
    for (auto &c: place) cout << c.first << " ";
    cout << "\n";
    long long cnt = 0;
    auto calc = [&](int c) {
        long long cnt = c;
        for (int i = 0; i < n; i++) {
            if (w[i] == w[c]) continue;
            if (w[c] == 1) {
                long long d = (x[i] - x[c] + l) % l;
                if (t * 2 < d) continue;
                long long remain = t * 2 - d; cnt++;
                cnt += remain / l;
            } else {
                long long d = (l + x[i] - x[i]) % l;
                if (t * 2 < d) continue;
                long long remain = t * 2 - d; cnt--;
                cnt -= remain / l;
            }
        }
        return (cnt % n + n) % n;
    };
    int idx0 = calc(0), idx1 = calc(1);
    cout << idx0 << " " << idx1 << "\n";
    vector<long long> ans(n, -1);
    int prev = -n;
    for (int i = 0; i < n; i++) {
        int t = calc(place[i].second);
        ans[t] = place[i].first;
        if (prev + 1 == t) {
            for (int j = i+1; j < n; j++) {
