                }
            } else {
                if((L-X[i] + X[0])/2 <= T) {
                    tmp++;
                    double t = (double)T - (double)(L-X[i] + X[0])/2;
                    tmp += t/(double)(L/2);
                }
            }
        }
    }

    int num = 0;
    if(W[0] == 1) {
        num = tmp % N;
    } else {
        num = (N - tmp%N) % N;
    }

    vector<int> v;
    int t = T%L;
    int sx;
    REP(i, N) {
        int x = X[i];
        if(W[i] == 1) {
            x = (x + t) % L;
        } else {
            x = (x + L - t) % L;
        }
        v.PB(x);
        if(i==0) {
            sx = x;
        }
    }

    sort(ALL(v));

    int n = lower_bound(ALL(v), sx) - v.begin();
    // if(W[0] == 2) {
    //     n = upper_bound(ALL(v), sx) - v.begin();
    //     n--;
    // }

    // cerr << num << " " << n << endl;

    n = (n-num+N) % N;

    REP(i,N) {
        cout << v[n++] << endl;
        n %= N;
    }

    return 0;
}

