using i64=int64_t;

i64 n,l,t;

i64 calc_count(i64 a,i64 b){
    i64 d;
    if(a<b) d=b-a;
    else d=l-a+b;
    if(2*t<d) return 0;
    return 1+(2*t-(d+d%2))/l;
}

void solve(){
    cin >> n >> l >> t;
    vector<i64> x(n),w(n);
    rep(i,0,n) cin >> x[i] >> w[i];
    i64 num=0;
    rep(i,1,n){
        if(w[i]==w[0]) continue;
        i64 a=x[0],b=x[i];
        if(w[i]==1) swap(a,b);
        num+=calc_count(a,b)*(w[0]==1?1:-1);
    }
    num=(num%n+n)%n;
    vector<i64> y(n);
    rep(i,0,n) y[i]=((x[i]+t*(w[i]==1?1:-1))%l+l)%l;
    i64 tmp=y[0];
    sort(y.begin(),y.end());
    vector<i64> ans(n);
    int j;
    rep(i,0,n) if(y[i]==tmp){
        j=i;
        break;
    }
    rep(i,0,n) ans[(num+i)%n]=y[(i+j)%n];
    rep(i,0,n) cout << ans[i] << endl;
}

