    else
    {
        idl=0;
        idr=ri.size()-1;
        rs=1;
    }
    dr=idr;
    dl=idl;
    idr=(idr==ri.size()-1?idr:idr+1);
    idl=(idl==0?0:idl-1);

    while(1)
    {
        LL dis=le[dl]+ls*l-(ri[dr]-rs*l);
        if(dis/2>=t)
        {
            break;
        }

        if(iw==1)
        {
            dr--;
            if(dr<0)
                dr=ri.size()-1;
            iw=-1;
            if(dr==idr)
                rs++;
        }
        else
        {
            dl++;
            if(dl>=le.size())
                dl=0;
            iw=1;
            if(dl==idl)
                ls++;
        }
    }

    LL zi;
    if(iw==1)
    {
        LL pos=mod(ri[dr]-rs*l+t,l);
        zi=lower_bound(ALL(xx),pos)-xx.begin();
    }
    else
    {
        LL pos=mod(le[dl]+ls*l-t,l);
        zi=lower_bound(ALL(xx),pos)-xx.begin();
        if(xx[zi]+1==pos)
            zi++;

    }

    REP(i,n)
    {
        cout<<xx[(zi+i)%n]<<endl;
    }
}

