void Solve() {
    read(N);read(L);read(T);
    for(int i = 0 ; i < N ; ++i) {
	read(x[i]);read(w[i]);
	if(w[i] == 1) to[i] = (x[i] + T) % L;
	else to[i] = ((x[i] - T) % L + L) % L;
	id[i] = i;
    }
    sort(id,id + N,[](int a,int b){return to[a] < to[b] || (to[a] == to[b] && w[a] < w[b]);});
    int pos = 0;
    for(int i = 1 ; i < N ; ++i) {
	if(w[i] ^ w[0]) {
	    pos += (T / L) * 2 % N;
	    int64 rem = T % L;
	    int64 dis = x[i] - x[0];
	    if(w[0] == 2) dis = L - dis;
	    if(dis + L < 2 * rem) pos += 2;
	    else if(dis < 2 * rem) pos += 1;
	    pos %= N;
