const int N=1e5+10;
const int MOD=1e9+7,BASE=43;
const int inf=1e9+10;



int n,len,need;
int a[N],dir[N];
vector <int> v[2];

int dis(int x,int y){
    if (x-y<0) return x-y+len;
    return x-y;
}
int mov(int x,int dir,int time){
    if (dir==0) return (x+time)%len;
    return (x-time%len+len)%len;
}
void solve(){
    for(int i=1;i<=n;i++) v[dir[i]].push_back(a[i]);
    if (v[0].empty()||v[1].empty()){
        for(int i=1;i<=n;i++) cout<<mov(a[i],dir[i],need)<<'\n';
        return;
    }
    int cdir=dir[1],cpos=a[1],ctime=0;
    while (ctime<need){
        if (cdir==1){
            auto idx=upper_bound(v[0].begin(),v[0].end(),cpos);
            if (idx==v[0].begin()) idx=v[0].end();
            idx--;
            int use=dis(cpos,*idx)/2;
            if (ctime+use>=need) break;
            ctime+=use;
            cpos=*idx;
            cdir=0;
        }
        if (cdir==0){
            auto idx=lower_bound(v[1].begin(),v[1].end(),cpos);
            if (idx==v[1].end()) idx=v[1].begin();
            int use=dis(cpos,*idx)/2;
            if (ctime+use>=need) break;
            ctime+=use;
            cpos=*idx;
            cdir=1;
        }
    }
    int finpos=mov(cpos,cdir,ctime);
    for(int i=1;i<=n;i++) a[i]=mov(a[i],dir[i],need);
    sort(a+1,a+n+1);
    int idx=lower_bound(a+1,a+n+1,finpos)-a;
    for(int i=idx;i<=n;i++) cout<<a[i]<<'\n';
    for(int i=1;i<idx;i++) cout<<a[i]<<'\n';
}
int main(){
    scanf("%d%d%d",&n,&len,&need);
    for(int i=1;i<=n;i++) scanf("%d%d",a+i,dir+i),dir[i]--;
    solve();
}

