void Main() {
  int n = ri();
  int l = ri();
  int t = ri();

  int tl = t % l;

  vi X(n), W(n);
  rep(i, n) {
    X[i] = ri();
    W[i] = ri() - 1;
  }

  vi Y(n);

  rep(i, n) {
    if (W[i] == 0) {
      Y[i] = (X[i] + tl) % l;
    }
    else {
      Y[i] = (X[i] - tl + l) % l;
    }
  }
  int x0 = Y[0];

  auto ccol = [&](int idx) {
    ll ret = 0;
    rep(i, n) if (W[i] != W[idx]) {
      int d;
      if (W[idx] == 0) {
        d = (X[i] - X[idx] + l) % l;
      }
      else {
        d = (X[idx] - X[i] + l) % l;
      }
      if (d <= 2 * t) {
        int c = 1 + (2 * t - d) / l;
        ret += c;
      }
    }
    return ret;
  };

  ll ncol = ccol(0);

  // x0 にいるやつ
  int p0;
  if (W[0] == 0) {
    p0 = ncol % n;
  }
  else {
    p0 = n - (ncol % n);
  }
  out(ncol, x0, p0);

  int d0;
  {
    ll pcol = ccol(p0);
    out(p0, pcol);
    d0 = (W[p0] + (pcol % 2)) % 2;
  }
  out(d0);

  sort(all(Y));

  vi A;
  rep(i, n) {
    if (Y[i] == x0) A.emplace_back(i);
  }

  out(A);
  int chg;
  if (sz(A) == 1) {
    chg = A[0];
  }
  else {
    if (d0 == 1) chg = A[0];
    else chg = A[1];
  }

  // Y[chg] が 元の p0
  // Y[i+diff] が元の i
  int diff = (chg - p0 + n) % n;

  vi ans(n);
  rep(i, n) {
    cout << Y[(i+diff)%n] << endl;
  }
}
