ll norm(ll x) {
    x %= l;
    if (x < 0)
        x += l;
    return x;
}

void read() {
    cin >> n >> l >> t;
    for (int i = 0; i < n; ++i) {
        cin >> x[i] >> w[i];
        if (w[i] == 2)
            w[i] = -1;
    }
}

void kill() {
    for (int i = 0; i < n; ++i) {
        p[i] = norm(x[i] + w[i] * t);
    }

    ll step = 0;
    int at = 0;
    for (int i = 0; i < n; ++i)
        if (w[i] == 1) {
            at = i;
            for (int j = 0; j < n; ++j)
                if (w[j] == -1) {
                    ll d = norm(x[j] - x[i]);
                    ll len = 2 * t - d;
                    if (len < 0)
                        continue;
                    step += (len + l - 1) / l;
                }
            break;
        }

    ll x = p[at];
    sort(p, p + n);
    int i = find(p, p + n, x) - p;
    int id = (at + step) % n;
    for (int j = 0; j < n; ++j) {
        ans[i] = id;
        id = (id + 1) % n;
        i = (i + 1) % n;
    }

    for (int i = 0; i < n; ++i)
        if (ans[i] == 0) {
            for (int j = 0; j < n; ++j)
                cout << p[(i + j) % n] << "\n";
            break;
        }
}

