    for(int i=0; i<N; i++){
        if(XW[i].second == 1)
            num[i] = (i + cross[i]) % N;
        else
            num[i] = (i - cross[i] + 2 * N * T) % N;
    }

    vector<long long> ans(N);
    for(int i=0; i<N; i++){
        int n = num[i];
        if(XW[i].second == 1)
            ans[n] = (XW[i].first + T) % L;
        else
            ans[n] = (XW[i].first - T + L * T) % L;
    }
    for(int i=0; i<N; i++)
        cout << ans[i] << endl;

    return 0;
}

