			w1.push(w1.front());
			w1.pop();	
			if (t3 > 0)
			{
				w2.push(w2.front());
				w2.pop();
				x = (y + t3) % L;
				t1 += t3;
			}
			d = 1;
		}	
	}
	return x;
}

