void solve(){
    // 解答アルゴリズム
    for (int i = 0; i < N; ++i)
    {
        if(W[i] % 2) {
            // forward
            pos[i] = (A[i] + K) % M;
        }
        else {
            // backward
            pos[i] = (A[i] - K) % M;
            if(pos[i] < 0) pos[i] += M;
        }
    }
    // calc offset
    int offset = 0;
    if (W[0] % 2)
    {
        for (int i = 1; i < N; ++i)
        {
            if(W[i] == W[0]) continue;
            ll cross = 2 * K - (A[i] - A[0]);
            if (cross >= 0)
            {
                offset = (offset + cross / M + 1) % N; 
                debug("offset+ : %d\n", offset);
            }
        }
    }else{
        for (int i = N - 1; i > 0; --i)
        {
            if(W[i] == W[0]) continue;
            ll cross = 2 * K - (A[0] + M - A[i]);
            if (cross >= 0)
            {
                offset = (offset - cross / M - 1) % N;
                debug("offset- : %d\n", offset);
            }
        }
    }
    if(offset < 0) offset += N;

    #ifdef DEBUG
        cout << "pos_before: ";
        for (int i = 0; i < N; ++i)
        {
            cout << pos[i] << " ";
        }
        cout << endl;
    #endif

    // answer
    ll pos0 = pos[0];
    debug("pos0: %lld\n", pos0);
    sort(pos, pos+N);
    int index = distance(pos, find(pos, pos+N, pos0));
    if (count(pos, pos+N, pos0) == 2
        && W[0] == 1 ) ++index;
    debug("index: %d\n", index);
    for (int i = 0; i < N; ++i)
    {
        printf("%lld\n", pos[(index - offset + i) % N]);
    }

}
