int main(){
  const int n = getInt();
  const int l = getInt();
  const int t = getInt();

  vector<int> x(n);
  vector<int> w(n);

  REP(i,n){
    x[i] = getInt();
    w[i] = getInt();
  }

  int k = 0;
  while(k != n && w[k] != 1) k++;

  if(k == n){
    REP(i,n){
      int p = (x[i] - t) % l;
      if(p < 0) p += l;
      printf("%d\n", p);
    }
    return 0;
  }

  int cnt = 0;
  queue<int> q;
  REP(i,n) if(w[(k + i) % n] == 2){
    q.push(x[(k + i) % n]);
  }

  if(q.size() == 0){
    REP(i,n) printf("%d\n", (x[i] + t) % l);
    return 0;
  }

  int tt = 0;
  int pos = x[k];

  while(true){
    int next = (q.front() - tt) % l; q.pop();
    if(next < 0) next += l;
    if(next < pos) next += l;
    const int diff = next - pos;

    const int d2 = diff / 2 + diff % 2;
    if(tt + d2 < t){
      tt += d2;
      cnt++;
      pos = (pos + d2) % l;
      const int pp = (pos + l - diff % 2) % l;
      q.push((pp + tt) % l);
    }else{
      break;
    }
  }

  // printf("%d %d\n", k, cnt);
  vector<int> ans(n);
  int kp = 0;
  REP(i,n){
    const int idx = (k + i) % n;
    int xx = (x[idx] + (w[idx] == 2 ? -t : t)) % l;
    if(xx < 0) xx += l;
    ans[i] = xx;
    if(i == 0) kp = xx;
  }

  sort(ans.begin(), ans.end());
  int idx = 0; while(ans[idx] != kp) idx++;
  int zidx = (idx - k - cnt) % n;
  if(zidx < 0) zidx += n;
  // printf("%d %d %d %d\n", k, cnt, kp, idx);

  REP(i,n) printf("%d\n", ans[(zidx + i) % n]);

  return 0;
}

