			num = ((num - collision) % n + n) % n;
		}
	}
	vector<ll> after(n);
	rep(i, n)	after[i] = ((dat[i].first + (dat[i].second == 1 ? 1 : -1)*t) % l + l) % l;
	sort(all(after));
	int pos = 0;
	if (dat[0].second == 1) {
		ll afterpos = (dat[0].first + t) % l;
		rrep(i, after.size()) {
			if (after[i] == afterpos) {
				pos = i;
				break;
			}
		}
	}
	else {
		ll afterpos = ((dat[0].first - t) % l + l) % l;
		rep(i, after.size()) {
			if (after[i] == afterpos) {
				pos = i;
				break;
			}
		}
	}
	vector<ll> ret(n);
	rep(i, n) {
		ret[num] = after[pos];
		num = (num + 1) % n;
		pos = (pos + 1) % n;
	}
	rep(i, n)	cout << (ret[i] >> 1) << endl;
	return 0;
}

