modint pow(modint base, size_t exp) {
  modint res = 1;
  while (exp) {
    if (exp % 2) res *= base;
    base *= base;
    exp /= 2;
  }
  return res;
}

modint powm(ll base, size_t exp) {
  return pow((modint)base, exp);
}

// O(r + log MOD)
modint choose(int n, int r) {
  chmin(r, n-r);
  if (r < 0) return modint(0);
  modint nu = 1, de = 1;
  rep(i, r) nu *= n-i, de *= i+1;
  return nu / de;
}

int main() {
  ll n = IN, l = IN, t = IN; MOD = l;
  VLL x(n), w(n);
  rep(i, n) IN >> x[i] >> w[i];
  ll zero = x[0];
  minheap<pair<ll, int>> clock, counter;
  rep(i, 1, n) {
    if (w[i] == 1) {
      clock.emplace(modint(zero-x[i]).value, i);
    } else {
      counter.emplace(modint(x[i]-zero).value, i);
    }
  }
  int cnt = 0;
  rep(i, 1, n) if (w[i] != w[0]) {
    ll d0 = w[0] == 1 ? abs(x[i]-zero+l)%l : abs(zero-x[i]+l)%l;
    if (d0 > t*2) continue;
    cnt++;
