#define CHMAX(x,y) x = max(x, y)

const int MAX = 1e5+10;

ll N, L, T;
ll X[MAX], W[MAX];

ii getPair(int n) {
    ll pos;
    if (W[n] == 1) pos = (X[n] + T) % L;
    else pos = (X[n] - T) % L;
    if (pos < 0) pos += L;

    ll round = T / L, rest = T % L;
    ll idx = n;

    ll countAntiWise = 0;
    REP (i, N) if (W[i] != W[n]) countAntiWise++;
    if (W[n] == 1) {
        (idx += round * 2 * countAntiWise) %= N;
    } else {
        (idx -= round * 2 * countAntiWise) %= N;
        if (idx < 0) idx += N;
    }

    REP (i, N) if (W[n] != W[i]) {
        ll dist = 0;
        if (W[n] == 1) dist = (W[i] - W[n]) % N;
        else dist = (W[n] - W[i]) % N;
        if (dist < 0) dist += N;

        if (2 * rest >= dist) {
            if (W[n] == 1) idx++;
            else idx--;
        }
        if (rest >= dist + L) {
            if (W[n] == 1) idx++;
            else idx--;
        }
    }

    idx %= N;
    if (idx < 0) idx += N;

    return ii(idx, pos);
}

vi solve() {
    vi pos(N);
    REP (i, N) {
        if (W[i] == 1) pos[i] = (X[i] + T) % L;
        else pos[i] = (X[i] - T) % L;
        if (pos[i] < 0) pos[i] += L;
    }
    sort(ALL(pos));

    ii p0 = getPair(0), p1 = getPair(1);
    int idx = 0;
    REP (i, N) if (pos[(i+p0.first)%N] == p0.second && pos[(i+p1.first)%N] == p1.second) idx = i;
    vi ret(N);
    REP (i, N) ret[i] = pos[(idx+i)%N];
    return ret;
}

int main() {
    cin >> N >> L >> T;
    REP (i, N) cin >> X[i] >> W[i];
    FORE (x, solve()) cout << x << endl;
}

