typedef long long int int64;
#define N 100000
int64 x[N];
int64 clen;
int cw[N];
int bcnt;
struct heap {
    int n;
    struct postime {
        int64 time;
        int who;
    } ent[N/2];
} h;

struct postime *
poph(struct heap *h)
{
    if (!h->n)
        return 0;
    struct postime tmp = h->ent[--(h->n)];
    h->ent[h->n] = h->ent[0];
    int this, left;

    for (this = 0; (left = this * 2 + 1) < h->n; this = left) {
        int right = left+1;
        if (right < h->n && h->ent[right].time < h->ent[left].time)
            left = right;

        if (tmp.time <= h->ent[left].time)
            break;
        h->ent[this] = h->ent[left];
    }
    h->ent[this] = tmp;
    return &h->ent[h->n];
}

void
puth(struct heap *h, struct postime *ent)
{
    if (h->n >= N/2)
        assert(0);
    int cur = h->n++;
    while (cur) {
        int up = (cur-1) >> 1;
        if (h->ent[up].time <= ent->time)
            break;
        h->ent[cur] = h->ent[up];
        cur = up;
    }
    h->ent[cur] = *ent;
}
void
chk_heap(struct heap *h)
{
    int i;
    for (i = 1; i < h->n; ++i) {
        int up = (i - 1) >> 1;
        if (h->ent[up].time <= h->ent[i].time)
            continue;
        printf("%d(%lld) !< %d(%lld)\n", up, h->ent[up].time, i, h->ent[i].time);
    }
}

static inline int64
adv_cw(int pos, int64 time)
{
    return (pos + time) % clen;
}
static inline int
adv_ccw(int pos, int64 time)
{
    return clen - 1 - (time - pos + clen - 1) % clen;
}

int
pos(int who, int64 time)
{
    if (cw[who])
        return adv_cw(x[who], time);
    else
        return adv_ccw(x[who], time);
}

void
putcollide(int no, int64 time)
{
    int nxt = (no + 1) % bcnt;
    int dif = (pos(nxt, time) - pos(no, time) + clen) % clen;
    struct postime evt = {time + dif/2, no};
    puth(&h, &evt);
}

int
calcorig(int64 pos, int64 time, int dir)
{
    if (dir)
        return adv_ccw(pos, time);
    else
        return adv_cw(pos, time);
}

int
main(void)
{
    int64 maxt;
    scanf("%d%lld%lld", &bcnt, &clen, &maxt);

    clen *= 2;
    maxt *= 2;

    int i;
    for (i = 0; i < bcnt; ++i) {
        scanf("%lld%d", &x[i], &cw[i]);
        if (cw[i] != 1)
            cw[i] = 0;
        x[i] *= 2;
    }

    for (i = 0; i < bcnt; ++i) {
        int nxt = (i + 1) % bcnt;
        if (cw[i] && !cw[nxt])
            putcollide(i, 0);
    }

    for (;;) {
        struct postime *evtp = poph(&h);
        if (!evtp)
            break;
        int64 time = evtp->time;
        if (time >= maxt)
            break;
        int this = evtp->who;
        int nxt = (this + 1) % bcnt;

        int curpos = pos(this, time);
        if (curpos != pos(nxt, time))
            assert(0);
        cw[this] = 0;
        cw[nxt] = 1;

        x[this] = calcorig(curpos, time, 0);
        x[nxt] = calcorig(curpos, time, 1);;

        int prv = (this - 1 + bcnt) % bcnt;

        if (cw[prv])
            putcollide(prv, time);
    }
    for (i = 0; i < bcnt; ++i)
        printf("%d\n", pos(i, maxt)/2);
    return 0;
}

#include<stdio.h>
long long int mod=1000000007;
long long int solve(int N,int M){
	static long long int dp[3001][3001]={0};
	long long int i,j,ans=0;
	if(N==0){return 0;}
	for(i=0;i<=N;i++){
		dp[0][i]=1;
	}
	for(j=1;j<=M;j++){
		i=0;
		dp[j][i]=dp[j-1][i]+dp[j-1][i+1];dp[j][i]%=mod;
		for(i=1;i<N;i++){
			dp[j][i]=dp[j-1][i-1]+dp[j-1][i]*2+dp[j-1][i+1];dp[j][i]%=mod;
		}
		dp[j][i]=dp[j-1][i-1]+dp[j-1][i];dp[j][i]%=mod;
	}
	for(i=0;i<=N;i++){
		ans+=dp[M][i];ans%=mod;
	}
	return ans;
}
int main(void){
	int N,M,it;
	scanf("%d %d",&N,&M);
	it=solve(N,M)-solve(N-1,M);
	if(it<0){it+=mod;}
	printf("%d\n",it);
	return 0;
}

