//最も衝突が早い組を探索
void search(void)
{
	int i, j;

	for(i=0; i<n; i++){
		if(ant[i].w!=1 || i==res.n1)
			continue;
		for(j=0; j<n; j++){
			double ct = d_abs( ant[i].x - ant[j].x );	//二匹の小さい方の間

			if(ant[j].w!=2 || i==res.n2)
				continue;
			else if(res.t > ( (ant[i].x<ant[j].x)?ct/2.0:(cc-ct)/2.0 ) ){
				res.t = (ant[i].x<ant[j].x)?ct/2.0:(cc-ct)/2.0;
				res.n1 = i;
				res.n2 = j;
			}
		}
	}
}
