/*
ゼッケンと座標の組が1つ求まれば良いのだった
解説では「最初に1番のゼッケンをつけていた蟻」の座標とゼッケンを求めていた
実は「一番小さい座標にいる蟻」の座標とゼッケンはもっと簡単に求めることができる

時間経過によって「一番小さい座標にいる蟻」のゼッケンの番号は
蟻が時計回りに座標0を超えて来た時に1減り、反時計回りに座標0を超えたとき1増える
よって、すべての蟻がT秒間に座標0を通過する回数の合計がわかれば求めることができる
*/

#include <stdio.h>
#include <stdlib.h>
#define ll long long
#define rep(i,l,r)for(ll i=(l);i<(r);i++)
int upll(const void*a, const void*b){return*(ll*)a<*(ll*)b?-1:*(ll*)a>*(ll*)b?1:0;}
void sortup(ll*a,int n){qsort(a,n,sizeof(ll),upll);}

ll n,L,T;
ll ans[100010];
int main(){
	scanf("%lld%lld%lld",&n,&L,&T);
	ll cnt=0;
	rep(i,0,n){
		ll x,w;
		scanf("%lld%lld",&x,&w);
		if(w==1)x+=T;
		else x-=T;
		//座標0の点を何度通過したかを数える
		cnt-=x/L;
		x%=L;
		if(x<0){
			x+=L;
			cnt++;
		}
		ans[i]=x;
		cnt%=n;
	}
	sortup(ans,n);

	//一番小さい座標ans[0]にいる蟻はcnt番のゼッケンをつけている
	//0番のゼッケンをつけているのはans[-cnt]の蟻
	rep(i,0,n)printf("%lld\n",ans[(i-cnt+n)%n]);
}

