#include <stdio.h>
#include <math.h>

long long int nn, ll, tt;

typedef struct ant
{
  long long int xx;
  long long int ww;
  long long int lap;
} _ant;

long long int changeww(_ant tmp)
{
  return (tmp.ww == 1) ? 2 : 1;
}

long long int dd(_ant tmp)
{
  return (tmp.xx + tmp.lap * ll);
}

_ant walk(_ant tmp)
{
  if(tmp.ww == 1)
  {
    tmp.xx++;
    if(tmp.xx == ll)
    {
      tmp.xx = 0;
      tmp.lap++;
    }
  }
  else
  {
    tmp.xx--;
    if(tmp.xx == -1)
    {
      tmp.xx = ll - 1;
      tmp.lap--;
    }
  }
  return tmp;
}

int main()
{
  scanf("%lld %lld %lld", &nn, &ll, &tt);
  _ant table[nn];
  for(long long int ii = 0;ii < nn;ii++)
  {
    scanf("%lld %lld", &table[ii].xx, &table[ii].ww);
    table[ii].lap = 0;
  }

  for(long long int ii = 0;ii < tt;ii++)
  {
    for(long long int jj = 0;jj < nn;jj++)
    {
      table[jj] = walk(table[jj]);
    }
    for(long long int jj = 0;jj < nn - 1;jj++)
    {
      if(dd(table[jj]) > dd(table[jj + 1]))
      {
        table[jj].ww = changeww(table[jj]);
        table[jj + 1].ww = changeww(table[jj + 1]);
        table[jj] = walk(table[jj]);
        table[jj + 1] = walk(table[jj + 1]);
        jj++;
      }
      if(table[nn - 1].xx == table[0].xx + 1 || (table[nn - 1].xx == 0 && table[0].xx == ll - 1))
      {
        table[nn - 1].ww = changeww(table[nn - 1]);
        table[0].ww = changeww(table[0]);
        table[nn - 1] = walk(table[nn - 1]);
        table[0] = walk(table[0]);
      }
      if(dd(table[jj]) == dd(table[jj + 1]))
      {
        table[nn - 1].ww = changeww(table[nn - 1]);
        table[0].ww = changeww(table[0]);
      }
      if(table[nn - 1].xx == table[0].xx)
      {
        table[nn - 1].ww = changeww(table[nn - 1]);
        table[0].ww = changeww(table[0]);
      }
    }
  }

  for(int ii = 0;ii < nn;ii++)
  {
    printf("%lld\n", table[ii].xx);
  }

  return 0;
}

