typedef long long ll;


#define N_MAX 100000

typedef struct tag_ant_t
{
	ll x;
	int w;
	int id;
}ant_t;


int n, l, t;
ant_t ant[N_MAX];


ll laparound(ll x, ll w)
{
	x%=w;
	if(x<0) x+=w;
	return x;
}


void solve(int cw_num)
{
	ll loop;
	int i, j, x, ccw_num;

	ccw_num=n-cw_num;
	loop=(2*t/l);
	x=2*t-loop*l;

	for(i=0;i<cw_num;i++)
	{
		for(j=cw_num;j<n;j++)
		{
			if(laparound(ant[j].x-ant[i].x, l)<x)
			{
				ant[i].id=laparound(ant[i].id+1, n);
				ant[j].id=laparound(ant[j].id-1, n);
			}
		}
	}

	for(i=0;i<cw_num;i++)
	{
		ant[i].x=laparound(ant[i].x+t, l);
	}
	for(;i<n;i++)
	{
		ant[i].x=laparound(ant[i].x-t, l);
	}

	for(i=0;i<cw_num;i++)
	{
		ant[i].id=laparound(ant[i].id+ccw_num*loop, n);
	}
	for(;i<n;i++)
	{
		ant[i].id=laparound(ant[i].id-cw_num*loop, n);
	}
}


int cmpant(const void *pa, const void *pb)
{
	const ant_t *a, *b;
	a=pa;
	b=pb;
	if(a->id<b->id) return -1;
	return a->id>b->id;
}

