	while(scanf("%d%d%d", &n, &l, &t)==3)
	{
		cw_num=ccw_num=0;
		for(i=0;i<n;i++)
		{
			scanf("%d%d", &x, &w);
			if(w==1) d=&ant[cw_num++];
			else d=&ant[n-++ccw_num];

			d->x=x;
			d->w=w;
			d->id=i;
		}
		solve(cw_num);
		qsort(ant, n, sizeof(ant[0]), cmpant);
		for(i=0;i<n;i++)
		{
			printf("%lld\n", ant[i].x);
		}
	}

	return 0;
}

