	int *X = (int *)malloc(sizeof(int) * N);
	int *W = (int *)malloc(sizeof(int) * N);
	int fW1 = -1, W2num = 0;
	for(i = 0; i < N; i++){
		scanf("%d%d", &X[i], &W[i]);
		if(fW1 == -1 && W[i] == 1){
			fW1 = i;
		}
		if(W[i] == 2){
			W2num++;
		}
	}
	if(fW1 == -1){
		for(i = 0; i < N; i++){
			printf("%d\n", MOD(X[i] - T, L));
		}
		return 0;
	}
	int gap = X[fW1];
	int *X2 = (int *)malloc(sizeof(int) * N);
	int *W2 = (int *)malloc(sizeof(int) * N);
	for(i = 0; i < N; i++){
		X2[i] = MOD(X[MOD(i + fW1, N)] - gap, L);
		W2[i] = W[MOD(i + fW1, N)];
	}
	int *X3 = (int *)malloc(sizeof(int) * N);
	for(i = 0; i < N; i++){
		X3[i] = MOD(X2[i] + (W2[i] == 1 ? T : -T), L);
	}
	sort(X3, N);
	int encountcount = ((2 * T) / L) * W2num;
	for(i = 0; i < N; i++){
		if(W2[i] == 2 && X2[i] < MOD(2 * T, L)){
			encountcount++;
		}
	}
	int fW1will;
	for(i = 0; i < N; i++){
		if(X3[i] == MOD(T, L)){
			fW1will = i;
			break;
		}
	}
	int *ans = (int *)malloc(sizeof(int) * N);
	for(i = 0; i < N; i++){
		ans[MOD(i + fW1, N)] = MOD(X3[MOD(fW1will + i - encountcount, N)] + gap, L);
	}
	for(i = 0; i < N; i++){
		printf("%d\n", ans[i]);
	}
	return 0;
}

#include <stdio.h>
#include <stdlib.h>

int main(void)
{
  int n, l, t, i, j;
  int *x, *w;

  /*初期値入力*/
  scanf("%d %d %d", &n, &l, &t);
  /*動的配列を作成*/
  x = malloc(sizeof(int) * n);
  w = malloc(sizeof(int) * n);
  /*蟻の座標と進む向きを入力*/
  for (i=0;i<n;i++) {
    scanf("%d %d", &x[i], &w[i]);
    if (w[i] == 2) {
      w[i] = -1;
    }
  }

  /*処理*/
  /*時間のループ*/
  for (i=0;i<t;i++) {
    /*すべての蟻のループ　初めの向き＆移動編*/
    for (j=0;j<n;j++) {
      if (x[j] == x[(j + 1) % n]) {
        w[j] = w[j] * -1;
        w[(j + 1) % n] = w[(j + 1) % n] * -1;
      }
    }
    /*すべての蟻のループ　とりあえず衝突無視して移動編*/
    for (j=0;j<n;j++) {
      x[j] = (x[j] + w[j]) % l;
      if (x[j] == -1) {
        x[j] = l - 1;
      }
    }
    /*すべての蟻のループ　衝突の効果を考慮する編*/
    for (j=0;j<n;j++) {
      if ((x[j] - x[(j + 1) % n] == 1 && w[j] == 1 && w[(j + 1) % n] == -1) || (x[j] - x[(j + 1) % n] == -1 && w[j] == -1 && w[(j + 1) % n] == 1)) {
        w[j] = w[j] * -1;
        w[(j + 1) % n] = w[(j + 1) % n] * -1;
        x[j] = x[j] + w[j];
        x[(j + 1) % n] = x[(j + 1) % n] + w[(j + 1) % n];
      } else if (x[j] - x[(j + 1) % n] == l - 1 && w[j] == -1 && w[(j + 1) % n] == 1) {
        w[j] = w[j] * -1;
        w[(j + 1) % n] = w[(j + 1) % n] * -1;
        x[j] = 0;
        x[(j + 1) % n] = l - 1;
      } else if (x[j] - x[(j + 1) % n] == -(l - 1) && w[j] == 1 && w[(j + 1) % n] == -1) {
        w[j] = w[j] * -1;
        w[(j + 1) % n] = w[(j + 1) % n] * -1;
        x[j] = l - 1;
        x[(j + 1) % n] = 0;
      }
    }
  }

  /*出力*/
  for (i=0;i<n;i++) {
    printf("%d\n", x[i]);
  }
  free(x);
  free(w);
  return 0;
}

