						counter+=(t*2-(x[i]-x[0]))/l+1;
					}
				}
			}
			counter = (counter+1)%n;
			if(counter ==0)counter =n;

		}else {
			for(int i = n-1;i>0;i--) {
				if(w[i]==1) {
					if(t*2-(x[0]+l-x[i])<0) {

					}else {
						counter+=(t*2-(x[0]+l-x[i]))/l+1;
					}
				}
			}
			counter = (1-counter);

			counter = counter%n;
			if(counter<=0)counter+=n;
		}


		int offset = list.indexOf(firstIndex)-counter;
		for(int i =1;i<n+1;i++) {
			int listindex = offset+i;
