				if(w[i]==2){
					if(((x[i]-x[0])%2==1&&(x[i]-x[0])/2<t) || ((x[i]-x[0])%2==0&&(x[i]-x[0])/2<=t))count++;
				}
			}else{
				if(w[i]==1){
					if(((l-x[i]+x[0])%2==1&&(l-x[i]+x[0])/2<t) || ((l-x[i]+x[0])%2==0&&(l-x[i]+x[0])/2<=t))count--;
				}
			}
		}
		if(w[0]==1){
			while(count>=n)count -= n;
		}else{
			while(count<0)count += n;
		}
		long[] dist = new long[n];
