import java.io.StringReader;
import java.util.Arrays;
import java.util.StringTokenizer;

public class Main  implements Runnable {
    public static void main(String[] args) {
        new Thread(null, new Main(), "", 64 * 1024 * 1024).start();
    }
    public void run() {
    	FastScanner sc = new FastScanner(System.in);
    	int n = Integer.parseInt(sc.next());
    	int l = Integer.parseInt(sc.next());
    	int t = Integer.parseInt(sc.next());
		PrintWriter out = new PrintWriter(System.out);
		int[] x = new int[n];
		int[] w = new int[n];
		for(int i = 0; i < n; i++)
		{
			x[i] = Integer.parseInt(sc.next());
			w[i] = Integer.parseInt(sc.next());
		}
		int tmp = t % l;
		int[] a = new int[n];
		for(int i = 0; i < n; i++)
		{
			int ans = x[i];
			if(w[i] == 1)
			{
				ans += tmp;
				ans %= l;
			}
			else
			{
				ans -= tmp;
				if(ans < 0)
				{
					ans += l;
				}
			}
			a[i] = ans;
		}

		int count = 0;
		for(int i = 1; i < n; i++)
		{
			if(w[0] != w[i])
			{
				count += (t*2)/l;
				count %= n;
				if(w[0] ==1)
				{
					int tx = x[i]-x[0];
					if(tx < 0)
					{
						tx = tx + l;
					}
					if((t%l*2) >= (tx))
					{
						count++;
					}
					if((t%l)*2 >= (tx)+(l+1)/2)
					{
						count++;
					}
				}
				else
				{
					int tx = x[0]-x[i];
					if(tx < 0)
					{
						tx = tx + l;
					}
					if((t%l)*2 >= (tx))
					{
						count++;
					}
					if((t%l)*2 >= (tx)+(l+1)/2)
					{
						count++;
					}
				}
			}
		}
		if(w[0] == 2)
		{
			count = n - count;
		}
		count %= n;
		int pos0 = a[0];
		Arrays.parallelSort(a);
		int p=0;
		int ant0pos = -1;
		while(ant0pos == -1)
		{
			if(a[p] == pos0)
			{
				if(w[0] == 1 && a[(p+1)%n] == a[p])
				{
					ant0pos=p+1;
				}
				else
				{
					ant0pos = p;
				}
			}
			p++;
		}
		for(int i = 0; i < n; i++)
		{
			int ap = (i+ant0pos-count)%n;
			if(ap < 0) {
				ap += n;
			}
			out.printf("%d\n", a[ap]);
		}
		out.flush();
    }

    static class FastScanner {
        private BufferedReader reader = null;
        private StringTokenizer tokenizer = null;
        public FastScanner(String in) {
        	StringReader sr = new StringReader(in);
            reader = new BufferedReader(new BufferedReader(sr));
            tokenizer = null;
        }
        public FastScanner(InputStream in) {
            reader = new BufferedReader(new InputStreamReader(in));
            tokenizer = null;
        }
        public String next() {
            if (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    tokenizer = new StringTokenizer(reader.readLine());
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }
    }
}

import java.io.IOException;
import java.io.InputStream;
import java.io.OutputStream;
import java.lang.reflect.Field;
import java.util.Arrays;
import java.util.NoSuchElementException;
import java.util.function.IntUnaryOperator;
import java.util.function.LongUnaryOperator;



public class Main {
    public static void main(String[] args) throws Exception {
        Field f = System.out.getClass().getDeclaredField("autoFlush");
        f.setAccessible(true);
        f.set(System.out, false);
        execute(System.in, System.out);
    }

    public static void execute(InputStream in, OutputStream out) {
        ExtendedScanner s = new ExtendedScanner(in);
        Out o = new Out(out);
        solve(s, o);
        o.flush();
        o.close();
    }

    public static void solve(ExtendedScanner sc, Out out) {
        int n = sc.nextInt();
        int l = sc.nextInt();
        int t = sc.nextInt();
        int[] x = new int[n];
        boolean[] clk = new boolean[n];
        int m = 0;
        int v = -1;
        for (int i = 0; i < n; i++) {
            x[i] = sc.nextInt();
            clk[i] = sc.nextInt() == 1;
            if (!clk[i]) m++;
            else v = i;
        }
        int col = 0;
        if (0 < m && m < n) {
            int[] rvs = new int[m];
            for (int i = 0, idx = 0; i < n; i++) {
                if (!clk[i]) {
                    rvs[idx++] = v > i ? x[i] - x[v] + l : x[i] - x[v];
                }
            }
            Arrays.sort(rvs);
            for (int j = 0; j < m; j++) {
                long ll = -1, rr = 2 * t + 1;
                while (rr - ll > 1) {
                    long mm = (ll + rr) >> 1;
                    if (2 * t > rvs[j] + mm * l) ll = mm;
                    else rr = mm;
                }
                col += rr % n;
                if (col >= n) col -= n;
            }
        }
        int[] dst = new int[n];
        for (int i = 0; i < n; i++) {
            if (clk[i]) {
                dst[i] = (x[i] + t) % l;
            } else {
                dst[i] = (x[i] - t) % l;
                if (dst[i] < 0) dst[i] += l;
            }
        }
        int dv = (x[v] + t) % l;
        Arrays.sort(dst);
        for (int i = 0; i < n; i++) {
            if (dst[i] == dv) {
                int k = (i - (v + col)) % n;
                if (k < 0) k += n;
                for (int j = 0; j < n; j++) {
                    out.writeln(dst[(k + j) % n]);
                }
                return;
            }
        }
    }
}


/**
