import java.util.*;
public class Main{
	public static void main(String[] args){
		Scanner sc = new Scanner(System.in);
		int n = sc.nextInt();
		int l = sc.nextInt();
		int t = sc.nextInt();
		int[] x = new int[n];
		int[] w = new int[n];
		for(int i=0; i<n; i++){
			x[i] = sc.nextInt();
			w[i] = sc.nextInt();
		}
		int count = 0;
		for(int i=1; i<n; i++){
			if(w[0]==1){
				if(w[i]==2){
					if((x[i]-x[0])/2<t)count++;
					else break;
					if((2*t-x[i]+x[0])%l==0)count = count + (2*t-x[i]+x[0]-l)/l;
					else count = count + (2*t-x[i]+x[0])/l;
				}
			}else{
				if(w[i]==1){
					if((l-x[i]+x[0])/2<t)count--;
					else break;
					if((2*t+x[i]-x[0])%l==0)count = count - (2*t+x[i]-x[0])/l;
					else count = count - (2*t-l+x[i]-x[0])/l;
				}
			}
		}
		if(w[0]==1){
			count %= n;
		}else{
			count = (count%n + n)%n;
		}
		int[] dist = new int[n];
		for(int i=0; i<n; i++){
			if(w[i]==1){
				dist[i] = (x[i] + t)%l;
			}else{
				dist[i] = ((x[i] - t)%l+l)%l;
			}
		}
		int dist0 = dist[0];
		Arrays.sort(dist);
		int index0 = 0;
		if(w[0]==1){
			for(int i=0; i<n; i++){
				if(dist[i]==dist0){
					index0 = i;
					break;
				}
			}
		}else{
			for(int i=n-1; i>=0; i--){
				if(dist[i]==dist0){
					index0 = i;
					break;
				}
			}
		}
		int[] ans = new int[n];
		if(index0>=count){
			for(int i=0; i<n-index0+count; i++){
				ans[i] = dist[i+index0-count];
			}
			for(int i=0; i<index0-count; i++){
				ans[n-index0+count+i] = dist[i];
			}
		}else{
			for(int i=0; i<n-count+index0; i++){
				dist[i] = ans[i+count-index0];
			}
			for(int i=0; i<count-index0; i++){
				dist[n-count+index0+i] = ans[i];
			}
		}
		for(int i=0; i<n; i++){
			System.out.println(ans[i]);
		}
	}
}

import java.util.Scanner;

public class Main {

	public static void main(String[] args) {
		Scanner sc = new Scanner(System.in);
		int N = Integer.parseInt(sc.next());
		int L = Integer.parseInt(sc.next());
		int T = Integer.parseInt(sc.next());
		int[] X = new int[N];
		int[] W = new int[N];
		for(int i = 0; i < N ; i++) {
			X[i] = Integer.parseInt(sc.next());
			W[i] = Integer.parseInt(sc.next());
		}

		for(int i = 1; i <= T; i++) {
			for(int j = 0; j < N; j++) {
				if(j == N-1) {
					if(collision(X[j], X[0], W[j], W[0])) {
						j++;
					}
					else {
						X[j] = moveAnt(X[j], W[j], L);
						X[0] = moveAnt(X[0], W[0], L);
					}
				}else {
					if(collision(X[j], X[j+1], W[j], W[j+1])) {
						W[j] = 2;
						W[j+1] = 1;
						j++;
					}
					else {
						if(j == 0) continue;
						else X[j] = moveAnt(X[j], W[j], L);
					}
				}
			}
		}

		for(int i = 0; i < N; i++) {
			System.out.println(X[i]);
		}
	}

	public static boolean collision(int pa, int pb, int da, int db) {
		if(pa+1 == pb && da == 1 && db == 2) {
			return true;
		}else return false;
	}

	public static int moveAnt(int pa, int da, int length) {
		if(da == 1) {
			if(pa == length-1) return 0;
			else return pa+1;
		}else if(da == 2) {
			if(pa == 0) return length-1;
			else return pa-1;
		}
		else return pa;
	}

}

