public class Main {
  public static void main(String[] args) {
    FastScanner sc = new FastScanner();
    int N = sc.nextInt();
    long L = sc.nextLong();
    long T = sc.nextLong();

    long[][] ari = sc.nextLongTable(N, 2);
    long d = ari[0][1];

    long[] finalPos = new long[N];

    int ptr = 0;
    long[] c = new long[N];
    for (int i = 0; i < N; i ++) {

      if (ari[i][1] != d) {
        c[ptr ++] = ari[i][0];
      }

      finalPos[i] = (ari[i][0] + (ari[i][1] == 1 ? T : (L - T))) % L; 
    }
    c = Arrays.copyOf(c, ptr);

    long count = T / L * c.length;
    T = T % L;


    long now = finalPos[0];

    for (int i = 0; i < c.length; i ++) {
      if (d == 1) {
        c[i] = c[i] - T; 
        if (c[i] < now) {
          count ++;
        }
      } else {
        c[i] = c[i] + T;
        if (c[i] >= now) {
          count ++;
        }
      }
    }

    int start = 0;
    count %= N;
    if (d == 1) {
      start = (int)((N - count) % N);
    } else {
      start = (int)((N + count) % N);
    }
    StringBuilder sb = new StringBuilder();
    for (int i = 0; i < N; i ++) {
      sb.append(finalPos[(i + start) % N]);
      sb.append("\n");
    }
    System.out.println(sb);

  }
