		long l = sc.nextLong();
		long t = sc.nextLong();
		long p[] = new long[n];
		long cw[] = new long[n];
		long end[] = new long[n];
		for (int i = 0 ; i < n ; ++i) {
			p[i] = sc.nextInt(); int c = sc.nextInt() - 1;
			cw[i] = c;
			int sign = (c == 0) ? 1 : -1;
			end[i] = (p[i] + t*sign ) % l;
			while (end[i] < 0) end[i] += l;
			end[i] %= l;
		}
		long col = 0;
		if (cw[0] == 0) {
			for (int i = 1 ; i < n ; ++i) {
				if (cw[i] == cw[0]) {
					continue;
				}
				long has = 2 * t;
				long d = p[i] - p[0];
				if (has >= d) {
					++col;
					has -= d;
					col += has / l;
					col %=n;
				}
			}
		} else {
