import java.io.IOException;
import java.io.InputStream;
import java.util.Arrays;
import java.util.NoSuchElementException;

public class Main {
  public static void main(String[] args) {
    FastScanner sc = new FastScanner();
    int N = sc.nextInt();
    int L = sc.nextInt();
    long T = sc.nextLong();

    long[][] ari = sc.nextLongTable(N, 2);

    long[] cl = new long[N];
    long[] ccl = new long[N];

    int p = 0, q = 0;
    for (int i = 0; i < N; i ++) {
      if (ari[i][1] == 1) {
        cl[p ++] = L - ari[i][0];
      } else {
        ccl[q ++] = ari[i][0];
      }
    }
    cl = Arrays.copyOf(cl, p);
    ccl = Arrays.copyOf(ccl, q);
    Arrays.sort(cl);

    long[] rets = new long[N];
    for (int i = 0; i < N ;i ++) {
      if (ari[i][1] == 1) {
        int count = (int)(count(ccl, ari[i][0], ari[i][0] + 2L * T, L) % N);
        rets[(i + count) % N] = (ari[i][0] + T) % L;
      } else {
        int count = (int)(count(cl, L - ari[i][0], L - ari[i][0] + 2L * T, L) % N);
        rets[(i + N - count) % N] = (ari[i][0] + L - T % L) % L;
      }
    }

    for (int i = 0; i < N; i ++) {
      System.out.println(rets[i]);
    }
  }

  private static long count(long[] xs, long f, long t, int L) {
    long ret = 0;
    int n = xs.length;
    {
      ret += t / L * n;
      int ind = Arrays.binarySearch(xs, (int)(t % L));
      if (ind < 0)  ind = -ind - 2;
      ind ++;
      ret += ind;
    }
    {
      ret -= f / L * n;
      int ind = Arrays.binarySearch(xs, (int)(f % L));
      if (ind < 0)  ind = -ind - 2;
      ind ++;
      ret -= ind;
    }
    return ret;
  }
}




class FastScanner {
	public static String debug = null;

	private final InputStream in = System.in;
	private int ptr = 0;
	private int buflen = 0;
	private byte[] buffer = new byte[1024];
	private boolean eos = false;

	private boolean hasNextByte() {
		if (ptr < buflen) {
			return true;
		} else {
			ptr = 0;
			try {
				if (debug != null) {
					buflen = debug.length();
					buffer = debug.getBytes();
					debug = "";
					eos = true;
				} else {
					buflen = in.read(buffer);
				}
			} catch (IOException e) {
				e.printStackTrace();
			}
			if (buflen < 0) {
				eos = true;
				return false;
			} else if (buflen == 0) {
				return false;
			}
		}
		return true;
	}

	private int readByte() {
		if (hasNextByte())
			return buffer[ptr++];
		else
			return -1;
	}

	private static boolean isPrintableChar(int c) {
		return 33 <= c && c <= 126;
	}

	private void skipUnprintable() {
		while (hasNextByte() && !isPrintableChar(buffer[ptr]))
			ptr++;
	}

	public boolean isEOS() {
		return this.eos;
	}

	public boolean hasNext() {
		skipUnprintable();
		return hasNextByte();
	}

	public String next() {
		if (!hasNext())
			throw new NoSuchElementException();
		StringBuilder sb = new StringBuilder();
		int b = readByte();
		while (isPrintableChar(b)) {
			sb.appendCodePoint(b);
			b = readByte();
		}
		return sb.toString();
	}

	public long nextLong() {
		if (!hasNext())
			throw new NoSuchElementException();
		long n = 0;
		boolean minus = false;
		int b = readByte();
		if (b == '-') {
			minus = true;
			b = readByte();
		}
		if (b < '0' || '9' < b) {
			throw new NumberFormatException();
		}
		while (true) {
			if ('0' <= b && b <= '9') {
				n *= 10;
				n += b - '0';
			} else if (b == -1 || !isPrintableChar(b)) {
				return minus ? -n : n;
			} else {
				throw new NumberFormatException();
			}
			b = readByte();
		}
	}

	public int nextInt() {
		return (int) nextLong();
	}

	public long[] nextLongList(int n) {
		return nextLongTable(1, n)[0];
	}

	public int[] nextIntList(int n) {
		return nextIntTable(1, n)[0];
	}

	public long[][] nextLongTable(int n, int m) {
		long[][] ret = new long[n][m];
		for (int i = 0; i < n; i ++) {
			for (int j = 0; j < m; j ++) {
				ret[i][j] = nextLong();
			}
		}
		return ret;
	}

	public int[][] nextIntTable(int n, int m) {
		int[][] ret = new int[n][m];
		for (int i = 0; i < n; i ++) {
			for (int j = 0; j < m; j ++) {
				ret[i][j] = nextInt();
			}
		}
		return ret;
	}
}

import java.io.PrintWriter;
import java.util.*;

public class Main {
	public static void main(String[] args) {
		Scanner sc = new Scanner(System.in);
		PrintWriter pw = new PrintWriter(System.out);

		int N = sc.nextInt();
		long L = sc.nextLong();
		long T = sc.nextLong();
		int[] x = new int[N];
		boolean[] w = new boolean[N];
		ArrayList<Integer> cw = new ArrayList<>();
		ArrayList<Integer> ccw = new ArrayList<>();
		for(int i=0; i<N; i++) {
			x[i] = sc.nextInt();
			w[i] = sc.nextInt()==1;
			if(w[i])
				cw.add(x[i]);
			else
				ccw.add(x[i]);
		}
		Collections.reverse(cw);

		if(cw.size()==0 || ccw.size()==0) {
			for(int i=0; i<N; i++) {
				pw.println((x[i]+(w[i]? T%L : L-(T%L)))%L);
			}
		} else {
			long t=0;
			boolean dirCW = true;
			int cwIdx=0;
			int ccwIdx=0;
			int lane1 = -1, lane2 = -1;
			boolean dir1=false;
			while(t<2*L) {
				if(cwIdx==0 && ccwIdx==0) {
					t += (ccw.get(0)-cw.get(0)+L) % L;
					cwIdx++;
					ccwIdx++;
				} else if(dirCW) {
					int next = ccw.get(ccwIdx%ccw.size()) - ccw.get((ccwIdx-1)%ccw.size());
					if(next<=0)
						next += L;
					t += next;
					ccwIdx++;
				} else {
					int next = cw.get((cwIdx-1)%cw.size()) - cw.get(cwIdx%cw.size());
					if(next<=0)
						next += L;
					t += next;
					cwIdx++;
				}
				if(lane1==-1 && t>=2*(T%L)) {
					lane1 = dirCW ? cw.get((cwIdx-1)%cw.size()) : ccw.get((ccwIdx-1)%ccw.size());
					dir1 = dirCW;
				}
				if(lane2==-1 && t>=2*L) {
					lane2 = dirCW ? cw.get((cwIdx-1)%cw.size()) : ccw.get((ccwIdx-1)%ccw.size());
				}
				dirCW ^= true;
			}
			int gap2 = Arrays.binarySearch(x, lane2) - Arrays.binarySearch(x, cw.get(0));

			int[] pos = new int[N];
			for(int i=0; i<N; i++)
				pos[i] = (int)((x[i]+(w[i]? T%L : L-(T%L)))%L);
			Arrays.sort(pos);

			lane1 = (int)((lane1 + (dir1 ? T : L-(T%L)))%L);
			int idx = Arrays.binarySearch(pos, lane1);
			if(idx<N-1 && pos[idx]==pos[idx+1] && !dir1)
				idx++;
			idx = (idx - Arrays.binarySearch(x, cw.get(0)) + N)%N;
			idx = (int)((idx + (long)gap2*(T/L))%N);

			for(int i=0; i<N; i++)
				pw.println(pos[(idx+i)%N]);
		}

		sc.close();
		pw.close();
	}
}

import java.io.IOException;
import java.io.InputStream;
import java.io.OutputStream;
import java.lang.reflect.Field;
import java.util.Arrays;
import java.util.HashSet;
import java.util.NoSuchElementException;
import java.util.function.IntUnaryOperator;
import java.util.function.LongUnaryOperator;


public class Main {
    public static void main(String[] args) throws Exception {
        Field f = System.out.getClass().getDeclaredField("autoFlush");
        f.setAccessible(true);
        f.set(System.out, false);
        execute(System.in, System.out);
    }

    public static void execute(InputStream in, OutputStream out) {
        ExtendedScanner s = new ExtendedScanner(in);
        Out o = new Out(out);
        solve(s, o);
        o.flush();
        o.close();
    }

    public static void solve(ExtendedScanner sc, Out out) {
        int n = sc.nextInt();
        int l = sc.nextInt();
        int t = sc.nextInt();
        int[] x = new int[n];
        boolean[] clk = new boolean[n];
        HashSet<Integer> set = new HashSet<>();
        int v = -1;
        boolean vClk = false;
        for (int i = 0; i < n; i++) {
            x[i] = sc.nextInt();
            clk[i] = sc.nextInt() == 1;
            if (clk[i]) {
                int dst = (x[i] + t) % l;
                if (!set.contains(dst)) {
                    v = i;
                    set.add(dst);
                    vClk = true;
                }
            } else {
                int dst = (x[i] - t) % l;
                if (dst < 0) dst += l;
                if (!set.contains(dst)) {
                    v = i;
                    set.add(dst);
                    vClk = false;
                }
            }
        }
        int m = 0;
        for (int i = 0; i < n; i++) {
            if (clk[i] ^ vClk) m++;
        }
        if (vClk) {
            int col = 0;
            if (0 < m && m < n) {
                int[] rvs = new int[m];
                for (int i = 0, idx = 0; i < n; i++) {
                    if (!clk[i]) {
                        rvs[idx++] = v > i ? x[i] - x[v] + l : x[i] - x[v];
                    }
                }
                Arrays.sort(rvs);
                for (int j = 0; j < m; j++) {
                    long ll = -1, rr = 2 * t + 1;
                    while (rr - ll > 1) {
                        long mm = (ll + rr) >> 1;
                        if (2 * t > rvs[j] + mm * l) ll = mm;
                        else rr = mm;
                    }
                    col += rr % n;
                    if (col >= n) col -= n;
                }
            }
            int dv = (x[(v - col + n) % n] + t) % l;
            int[] dst = new int[n];
            for (int i = 0; i < n; i++) {
                if (clk[i]) {
                    dst[i] = (x[i] + t) % l;
                } else {
                    dst[i] = (x[i] - t) % l;
                    if (dst[i] < 0) dst[i] += l;
                }
                dst[i] -= dv;
                if (dst[i] < 0) dst[i] += l;
            }
            Arrays.sort(dst);
            for (int i = 0; i < n; i++) {
                out.writeln((dst[(i + n - v) % n] + dv) % l);
            }
        } else {
            int col = 0;
            if (0 < m && m < n) {
                int[] rvs = new int[m];
                for (int i = 0, idx = 0; i < n; i++) {
                    if (clk[i]) {
                        rvs[idx++] = v > i ? x[v] - x[i] : x[v] - x[i] + l;
                    }
                }
                Arrays.sort(rvs);
                for (int j = 0; j < m; j++) {
                    long ll = -1, rr = 2 * t + 1;
                    while (rr - ll > 1) {
                        long mm = (ll + rr) >> 1;
                        if (2 * t > rvs[j] + mm * l) ll = mm;
                        else rr = mm;
                    }
                    col += rr % n;
                    if (col >= n) col -= n;
                }
            }
            int dv = (x[(v + col) % n] - t) % l;
            if (dv < 0) dv += l;
            int[] dst = new int[n];
            for (int i = 0; i < n; i++) {
                if (clk[i]) {
                    dst[i] = (x[i] + t) % l;
                } else {
                    dst[i] = (x[i] - t) % l;
                    if (dst[i] < 0) dst[i] += l;
                }
                dst[i] -= dv;
                if (dst[i] < 0) dst[i] += l;
            }
            Arrays.sort(dst);
            for (int i = 0; i < n; i++) {
                out.writeln((dst[(i + n - v) % n] + dv) % l);
            }
        }
    }
}


