public class Main {






	public static void main(String[]args) throws Throwable {
		Scanner sc = new Scanner(System.in);
		PrintWriter out = new PrintWriter(System.out);
		int n = sc.nextInt(), l = sc.nextInt(), t = sc.nextInt();
		int p[] = new int[n];
		int cw[] = new int[n];
		int end[] = new int[n];
		for (int i = 0 ; i < n ; ++i) {
			p[i] = sc.nextInt(); int c = sc.nextInt() - 1;
			cw[i] = c;
			int sign = (c == 0) ? 1 : -1;
			end[i] = (p[i] + t*sign ) % l;
			while (end[i] < 0) end[i] += l;
			end[i] %= l;
		}
		int col = 0;
		if (cw[0] == 0) {
			for (int i = 1 ; i < n ; ++i) {
				if (cw[i] == cw[0]) {
					continue;
				}
				int has = 2 * t;
				int d = p[i] - p[0];
				if (has >= d) {
					++col;
					has -= d;
					col += has / l;
					col %=n;
				}
			}
		} else {
			for (int i = 1 ; i < n ; ++i) {
				if (cw[i] == cw[0]) {
					continue;
				}
				int has = 2 * t;
				int d = l - p[i] + p[0];
				if (has >= d) {
					++col;
					has -= d;
					col += has / l;
					col %= n;
				}

			}
		}
		Arrays.sort(end);
		if (cw[0] == 0) {
			int pos = col%n;
			for (int i = pos ; i < n ; ++i) out.print(end[i]+"\n");
			for (int i = 0 ; i < pos ; ++i) out.print(end[i]+"\n");
		} else {
			int pos = (-col + n) % n;
			for (int i = pos ; i < n ; ++i) out.print(end[i]+"\n");
			for (int i = 0 ; i < pos ; ++i) out.print(end[i]+"\n");
		}
		out.flush();
		out.close();
	}
	static class Scanner {
