            int n = in.nextInt();
            long l = in.nextLong();
            long t = in.nextLong();

            ArrayList<Pair> list1 = new ArrayList<>();
            ArrayList<Pair> list2 = new ArrayList<>();
            for (int i = 0; i < n; i++) {
                int x = in.nextInt();
                int w = in.nextInt();

                if (w == 1) {
                    list1.add(new Pair(x, i));
                } else {
                    list2.add(new Pair(x, i));
                }
            }

            long m = 2 * t / l;
            long p = 2 * t % l;

            int[] cnt = new int[n];
            int n1 = list1.size();
            int n2 = list2.size();
            for (int i = 0; i < n1; i++) {
                long x = list1.get(i).x;
                int id = list1.get(i).y;
                cnt[id] += m * n2;

                if (x + p + 1 >= l) {
                    cnt[id] += n2 - lowerBound(list2, x);
                    cnt[id] += lowerBound(list2, (x + p + 1) % l);
                } else {
                    cnt[id] += lowerBound(list2, x + p + 1) - lowerBound(list2, x);
                }
            }
            for (int i = 0; i < n2; i++) {
                long x = list2.get(i).x;
                int id = list2.get(i).y;
                cnt[id] += m * n1;

                if (x - p <= 0) {
                    cnt[id] += n1 - lowerBound(list1, (x - p + l) % l);
                    cnt[id] += lowerBound(list1, x);
                } else {
                    cnt[id] += lowerBound(list1, x) - lowerBound(list2, x - p);
                }
            }

            long[] ans = new long[n];
            for (int i = 0; i < n1; i++) {
                int id = (list1.get(i).y + cnt[list1.get(i).y]) % n;
                ans[id] = (list1.get(i).x + t) % l;
            }
            for (int i = 0; i < n2; i++) {
                int id = (list2.get(i).y - cnt[list2.get(i).y] % n + n) % n;
                ans[id] = (list2.get(i).x - t % l + l) % l;
            }

            for (int i = 0; i < n; i++) {
                out.println(ans[i]);
            }
        }

        int lowerBound(ArrayList<Pair> a, long x) {
            int high = a.size();
            int low = 0;
            while (high > low) {
                int mid = (high + low) / 2;
                if (a.get(mid).x < x) {
                    low = mid + 1;
                } else {
                    high = mid;
                }
            }
            return low;
        }

        public class Pair {
            long x;
            int y;

            Pair(long x, int y) {
                this.x = x;
                this.y = y;
            }

        }

    }

    static class InputReader {
        BufferedReader in;
        StringTokenizer tok;

        public String nextString() {
            while (!tok.hasMoreTokens()) {
                try {
                    tok = new StringTokenizer(in.readLine(), " ");
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
            }
            return tok.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(nextString());
        }

        public long nextLong() {
            return Long.parseLong(nextString());
        }

        public InputReader(InputStream inputStream) {
            in = new BufferedReader(new InputStreamReader(inputStream));
            tok = new StringTokenizer("");
        }

    }
}

import java.io.IOException;
import java.io.InputStream;
import java.util.Arrays;
import java.util.NoSuchElementException;

public class Main {
  public static void main(String[] args) {
    FastScanner sc = new FastScanner();
    int N = sc.nextInt();
    long L = sc.nextLong();
    long T = sc.nextLong();

    long[][] ari = sc.nextLongTable(N, 2);
    long d = ari[0][1];

    long[] finalPos = new long[N];

    int ptr = 0;
    long[] c = new long[N];
    for (int i = 0; i < N; i ++) {

      if (ari[i][1] != d) {
        c[ptr ++] = ari[i][0];
      }

      finalPos[i] = (ari[i][0] + (ari[i][1] == 1 ? T : (L - T))) % L; 
    }
    c = Arrays.copyOf(c, ptr);

    long count = T / L * c.length;
    T = T % L;


    long now = finalPos[0];

    for (int i = 0; i < c.length; i ++) {
      if (d == 1) {
        c[i] = c[i] - T; 
        if (c[i] <= now) {
          count ++;
        }
      } else {
        c[i] = c[i] + T;
        if (c[i] >= now) {
          count ++;
        }
      }
    }

    int start = 0;
    count %= N;
    if (d == 1) {
      start = (int)((N - count) % N);
    } else {
      start = (int)((N + count) % N);
    }
    StringBuilder sb = new StringBuilder();
    for (int i = 0; i < N; i ++) {
      sb.append(finalPos[(i + start) % N]);
      sb.append("\n");
    }
    System.out.println(sb);

  }
}




class FastScanner {
	public static String debug = null;

	private final InputStream in = System.in;
	private int ptr = 0;
	private int buflen = 0;
	private byte[] buffer = new byte[1024];
	private boolean eos = false;

	private boolean hasNextByte() {
		if (ptr < buflen) {
			return true;
		} else {
			ptr = 0;
			try {
				if (debug != null) {
					buflen = debug.length();
					buffer = debug.getBytes();
					debug = "";
					eos = true;
				} else {
					buflen = in.read(buffer);
				}
			} catch (IOException e) {
				e.printStackTrace();
			}
			if (buflen < 0) {
				eos = true;
				return false;
			} else if (buflen == 0) {
				return false;
			}
		}
		return true;
	}

	private int readByte() {
		if (hasNextByte())
			return buffer[ptr++];
		else
			return -1;
	}

	private static boolean isPrintableChar(int c) {
		return 33 <= c && c <= 126;
	}

	private void skipUnprintable() {
		while (hasNextByte() && !isPrintableChar(buffer[ptr]))
			ptr++;
	}

	public boolean isEOS() {
		return this.eos;
	}

	public boolean hasNext() {
		skipUnprintable();
		return hasNextByte();
	}

	public String next() {
		if (!hasNext())
			throw new NoSuchElementException();
		StringBuilder sb = new StringBuilder();
		int b = readByte();
		while (isPrintableChar(b)) {
			sb.appendCodePoint(b);
			b = readByte();
		}
		return sb.toString();
	}

	public long nextLong() {
		if (!hasNext())
			throw new NoSuchElementException();
		long n = 0;
		boolean minus = false;
		int b = readByte();
		if (b == '-') {
			minus = true;
			b = readByte();
		}
		if (b < '0' || '9' < b) {
			throw new NumberFormatException();
		}
		while (true) {
			if ('0' <= b && b <= '9') {
				n *= 10;
				n += b - '0';
			} else if (b == -1 || !isPrintableChar(b)) {
				return minus ? -n : n;
			} else {
				throw new NumberFormatException();
			}
			b = readByte();
		}
	}

	public int nextInt() {
		return (int) nextLong();
	}

	public long[] nextLongList(int n) {
		return nextLongTable(1, n)[0];
	}

	public int[] nextIntList(int n) {
		return nextIntTable(1, n)[0];
	}

	public long[][] nextLongTable(int n, int m) {
		long[][] ret = new long[n][m];
		for (int i = 0; i < n; i ++) {
			for (int j = 0; j < m; j ++) {
				ret[i][j] = nextLong();
			}
		}
		return ret;
	}

	public int[][] nextIntTable(int n, int m) {
		int[][] ret = new int[n][m];
		for (int i = 0; i < n; i ++) {
			for (int j = 0; j < m; j ++) {
				ret[i][j] = nextInt();
			}
		}
		return ret;
	}
}

import java.util.ArrayList;
import java.util.Iterator;
import java.util.List;
import java.util.Scanner;

public class Main {

	public static int pair1=0;
	public static int pair2=0;
	public static double length=0;
	public static int l = 0;
	public static float h_l = 0;

	public static void main(String[] args) {
		Scanner scan = new Scanner(System.in);
		int n = Integer.parseInt(scan.next());
		l = Integer.parseInt(scan.next());
		h_l = l/2;
		Double t = Double.parseDouble(scan.next());
		List<Double> x = new ArrayList<Double>();
		List<Double> w = new ArrayList<Double>();
		for(int i=0; i<n; ++i) {
			x.add(Double.parseDouble(scan.next()));
			w.add(Double.parseDouble(scan.next()));
		}


		while(true) {
			length=l+1;
			double pairLength = length;
			// 向かい合う方向を向いていて一番近い物を探す
			for(int i=0; i<n; ++i) {
				//最初の場合は最後と比較
				if(i==n-1) {
					if(Math.abs(w.get(0) - w.get(n-1)) == 1) {
						//２点間の距離を求める
						double tempLength =0;
						if(w.get(i) == 1) tempLength = l - (x.get(n-1) - x.get(0));
						if(w.get(i) == 2) tempLength = x.get(n-1) - x.get(0);

						if(pairLength > tempLength && tempLength != 0) {
							pair1 = 0;
							pair2 = n-1;
							pairLength = tempLength;
						}
					}
				} else {
					if(Math.abs(w.get(i) - w.get(i+1)) == 1) {
						double tempLength =0;
						if(w.get(i) == 1) {
							double tempI_1 = x.get(i+1) - x.get(i);
							// ..0...<-X2....X1->..
							if(tempI_1 < 0) {
								tempLength = l + tempI_1;
							}
							// ..<-X2...0....X1->...
							else {
								tempLength = x.get(i+1) - x.get(i);
							}
						}
						if(w.get(i) == 2) tempLength = l - (x.get(i+1) - x.get(i));

						if(pairLength > tempLength && tempLength != 0) {
							pair1 = i;
							pair2 = i+1;
							pairLength = tempLength;
						}
					}
				}
			}

			System.out.println(pair1 + ":" + pair2);

			// みんな同じ方向を向いていたら、時間がくるまで進める
			if(pair1 ==0 && pair2 ==0) {
				update(x, w, t);
				break;
			}

			// 衝突する場合は、何秒後か求め衝突させ、向きを反転
			else {
				Double tempT = pairLength / 2;

				// 残り時間で衝突できない場合は最後まで更新
				if(tempT > t) {
					update(x, w, t);
					break;
				} else {
					update(x,w,tempT);
					t = t - tempT;

					if(w.get(pair1) == 1.0) {
						w.set(pair1, 2.0);
					} else {
						w.set(pair1, 1.0);
					}

					if(w.get(pair2) == 1.0) {
						w.set(pair2, 2.0);
					} else {
						w.set(pair2, 1.0);
					}
				}
			}

			length=l+1;
		}

		Iterator<Double> itr = x.iterator();
		while(itr.hasNext()) {
			System.out.println(itr.next());
		}

	}

	public static void update(List<Double> x, List<Double> w, Double t) {
		for(int i = 0; i< x.size(); ++i) {
			t = t % l;
			if(w.get(i) == 1) {
				Double tempX = x.get(i) + t;
				if(tempX < l) { x.set(i, tempX);}
				else { x.set(i, tempX -l);}
			} else {
				Double tempX = x.get(i) - t;
				if(tempX >= 0) {x.set(i, tempX);}
				else {x.set(i, l + tempX);}//0を超えたぶん
			}
		}
	}
}

