import java.io.PrintWriter;
import java.util.Arrays;
import java.io.BufferedWriter;
import java.io.Writer;
import java.io.OutputStreamWriter;
import java.util.InputMismatchException;
import java.io.IOException;
import java.io.InputStream;

/**
 * Built using CHelper plug-in
 * Actual solution is at the top
 *
 * @author ilyakor
 */
public class Main {

  public static void main(String[] args) {
    InputStream inputStream = System.in;
    OutputStream outputStream = System.out;
    InputReader in = new InputReader(inputStream);
    OutputWriter out = new OutputWriter(outputStream);
    TaskC solver = new TaskC();
    solver.solve(1, in, out);
    out.close();
  }

  static class TaskC {

    int l;

    public void solve(int testNumber, InputReader in, OutputWriter out) {
      int n = in.nextInt();
      l = in.nextInt();
      int t = in.nextInt();
      int[] a = new int[n];
      int[] dir = new int[n];
      for (int i = 0; i < n; ++i) {
        a[i] = in.nextInt();
        dir[i] = in.nextInt();
        if (dir[i] == 2) {
          dir[i] = -1;
        }
      }
      int[] b = a.clone();
      int shift = 0;
      for (int i = 0; i < n; ++i) {
        int pos = a[i] + dir[i] * t;
        if (dir[i] == 1) {
          shift += calc(a[i], t);
        } else {
          shift -= calc((l - 1 - a[i]) % l, t);
        }
        b[i] = (pos % l + l) % l;
      }
      Arrays.sort(b);
      for (int i = 0; i < n; ++i) {
        int j = ((i + shift) % n + n) % n;
        out.printLine(b[j]);
      }
    }

    private int calc(int x, int t) {
      t -= l - x;
      if (t < 0) {
        return 0;
      }
      return 1 + t / l;
    }

  }

  static class InputReader {

    private InputStream stream;
    private byte[] buffer = new byte[10000];
    private int cur;
    private int count;

    public InputReader(InputStream stream) {
      this.stream = stream;
    }

    public static boolean isSpace(int c) {
      return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
    }

    public int read() {
      if (count == -1) {
        throw new InputMismatchException();
      }
      try {
        if (cur >= count) {
          cur = 0;
          count = stream.read(buffer);
          if (count <= 0) {
            return -1;
          }
        }
      } catch (IOException e) {
        throw new InputMismatchException();
      }
      return buffer[cur++];
    }

    public int readSkipSpace() {
      int c;
      do {
        c = read();
      } while (isSpace(c));
      return c;
    }

    public int nextInt() {
      int sgn = 1;
      int c = readSkipSpace();
      if (c == '-') {
        sgn = -1;
        c = read();
      }
      int res = 0;
      do {
        if (c < '0' || c > '9') {
          throw new InputMismatchException();
        }
        res = res * 10 + c - '0';
        c = read();
      } while (!isSpace(c));
      res *= sgn;
      return res;
    }

  }

  static class OutputWriter {

    private final PrintWriter writer;

    public OutputWriter(OutputStream outputStream) {
      writer = new PrintWriter(new BufferedWriter(new OutputStreamWriter(outputStream)));
    }

    public OutputWriter(Writer writer) {
      this.writer = new PrintWriter(writer);
    }

    public void print(Object... objects) {
      for (int i = 0; i < objects.length; i++) {
        if (i != 0) {
          writer.print(' ');
        }
        writer.print(objects[i]);
      }
    }

    public void printLine(Object... objects) {
      print(objects);
      writer.println();
    }

    public void close() {
      writer.close();
    }

  }
}

import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Scanner;
import java.util.Set;
public class Main {
	public static void main(String[] args){
		Main main = new Main();
		main.solveC();
	}

	private void solveC() {
		Scanner sc = new Scanner(System.in);
		int N = sc.nextInt();
		int L = sc.nextInt();
		int T = sc.nextInt();
		int[] array = new int[N];
		Set<Integer> set = new HashSet<Integer>();
		for (int i = 0; i < N; i++) {
			array[i] = sc.nextInt() + T * (3 - sc.nextInt() * 2);
			set.add(i);
		}
		while (!set.isEmpty()) {
			Set<Integer> nextSet = new HashSet<Integer>();
			for (int i : set) {
				if (checkAndSwap(array, i, (i + 1) % N, N, L)) {
					nextSet.add((i - 1 + N) % N);
					nextSet.add((i + 1) % N);
				}
			}
			set = nextSet;
		}
		for (int x : array) {
			System.out.println((x + L) % L);
		}
	}

	private boolean checkAndSwap(int[] array, int a, int b, int N, int L) {
		int offset = 0;
		if (a == N - 1 && b == 0) {
			offset = L;
		}
		if (array[a] - offset > array[b]) {
			int swap = array[b];
			array[b] = array[a] - offset;
			array[a] = swap + offset;
			return true;
		}
		return false;
	}
}

import java.io.OutputStream;
