import java.io.*;
import java.math.*;
import java.util.*;

public class Main {
    private static boolean debug = false;
    private static boolean elapsed = false;

    private static PrintWriter _out = new PrintWriter(System.out);
    private static PrintWriter _err = new PrintWriter(System.err);

    private void solve(Scanner sc) {
        int N = sc.nextInt();
        int L = sc.nextInt();
        int T = sc.nextInt();
        int[] X = new int[N];
        int[] W = new int[N];
        for (int i = 0; i < N; ++i) {
            X[i] = sc.nextInt();
            W[i] = sc.nextInt();
        }

        int[] p = new int[N];
        int x0 = 0;
        for (int i = 0; i < N; ++i) {
            if (W[i] == 1) {
                p[i] = (X[i] + T) % L;
                x0 += (X[i] + T) / L;
            } else {
                p[i] = (X[i] - T) % L;
                x0 += (X[i] - T) / L;
                if (p[i] < 0) {
                    p[i] += L;
                    --x0;
                }
            }
        }
        Arrays.sort(p);
        for (int i = 0; i < N; ++i) {
            _out.println(p[(i + x0) % N]);
        }
    }
    private static BigInteger C(long n, long r) {
        BigInteger res = BigInteger.ONE;
        for (long i = n; i > n - r; --i) {
            res = res.multiply(BigInteger.valueOf(i));
        }
        for (long i = r; i > 1; --i) {
            res = res.divide(BigInteger.valueOf(i));
        }
        return res;
    }
    private static BigInteger P(long n, long r) {
        BigInteger res = BigInteger.ONE;
        for (long i = n; i > n - r; --i) {
            res = res.multiply(BigInteger.valueOf(i));
        }
        return res;
    }
    /*
     * 10^10 > Integer.MAX_VALUE = 2147483647 > 10^9
     * 10^19 > Long.MAX_VALUE = 9223372036854775807L > 10^18
     */
    public static void main(String[] args) {
        long S = System.currentTimeMillis();

        Scanner sc = new Scanner(System.in);
        new Main().solve(sc);
        _out.flush();

        long G = System.currentTimeMillis();
        if (elapsed) {
            _err.println((G - S) + "ms");
        }
        _err.flush();
    }
}

import java.util.*;
public class Main{
	public static void main(String[] args){
		Scanner sc = new Scanner(System.in);
		int n = sc.nextInt();
		float l = sc.nextFloat();
		float t = sc.nextFloat();
		float[] x = new float[n];
		int[] w = new int[n];
		for(int i=0; i<n; i++){
			x[i] = sc.nextFloat();
			w[i] = sc.nextInt();
		}
		int count = 0;
		for(int i=1; i<n; i++){
			if(w[0]==1){
				if(w[i]==2){
					if((x[i]-x[0])/2<t)count++;
					else break;
					if((t-(x[i]-x[0])/2)%(l/2)==0)count += (t-(x[i]-x[0])/2) / (l/2) - 1;
					else count += (t-(x[i]-x[0])/2) / (l/2);
				}
			}else{
				if(w[i]==1){
					if((l-x[i]+x[0])/2<t)count--;
					else break;
					if((t-(l-x[i]+x[0])/2)%(l/2)==0)count -= (t-(l-x[i]+x[0])/2) / (l/2) +1;
					else count -= (t-(l-x[i]+x[0])/2) / (l/2);
				}
			}
		}
		if(w[0]==1){
			count %= n;
		}else{
			count = (count%n + n)%n;
		}
		float[] dist = new float[n];
		for(int i=0; i<n; i++){
			if(w[i]==1){
				dist[i] = (x[i] + t)%l;
			}else{
				dist[i] = ((x[i] - t)%l+l)%l;
			}
		}
		float dist0 = dist[0];
		Arrays.sort(dist);
		int index0 = 0;
		if(w[0]==1){
			for(int i=0; i<n; i++){
				if(dist[i]==dist0){
					index0 = i;
					break;
				}
			}
		}else{
			for(int i=n-1; i>=0; i--){
				if(dist[i]==dist0){
					index0 = i;
					break;
				}
			}
		}
		int[] ans = new int[n];
		if(index0>=count){
			for(int i=0; i<n-index0+count; i++){
				ans[i] = (int)dist[i+index0-count];
			}
			for(int i=0; i<index0-count; i++){
				ans[n-index0+count+i] = (int)dist[i];
			}
		}else{
			for(int i=0; i<n-count+index0; i++){
				ans[i+count-index0] = (int)dist[i];
			}
			for(int i=0; i<count-index0; i++){
				ans[i] = (int)dist[n-count+index0+i];
			}
		}
		for(int i=0; i<n; i++){
			System.out.println(ans[i]);
		}
	}
}

