using System;
using System.Collections.Generic;

class Program
{
    static IO io = new IO();

    static void Main(string[] args)
    {
        //入力
        io.ReadSplit();
        int N = io.Int();
        int L = io.Int();
        int T = io.Int();
        int[] X = new int[N];
        int[] W = new int[N];
        for (int i = 0; i < N; ++i)
        {
            io.ReadSplit();
            X[i] = 2 * io.Int();
            W[i] = 3 - 2 * io.Int();
        }

        //計算
        int LL = 2 * L;
        for (int t = 0; t < 2 * T; ++t)
        {
            for (int i = 0; i < N; ++i)
            {
                X[i] += W[i];
                if (X[i] >= LL)
                {
                    X[i] -= LL;
                }
                if (X[i] < 0)
                {
                    X[i] += LL;
                }
            }
            for (int i = 0; i < N - 1; ++i)
            {
                if (X[i] == X[i + 1])
                {
                    W[i] *= -1;
                    W[i + 1] *= -1;
                }
            }
            if (X[N - 1] == X[0])
            {
                W[N - 1] *= -1;
                W[0] *= -1;
            }
        }

        //出力
        for (int i = 0; i < N; ++i)
        {
            io.Write((X[i] / 2).ToString());
        }
    }
}

