static class Program{
	const int mod=1000000007;
	static void Main(){
		Sc sc=new Sc();
		int[] s=sc.Ia;
		s[2]%=s[1];
		int[][] a=new int[s[0]][];
		long[] ans=new long[s[0]+1];
		for(int i = 0;i<s[0];i++) {
			a[i]=sc.Ia;
			ans[i]=(a[i][0]+(a[i][1]==1?s[2]:-s[2])+s[1])%s[1];
		}
		ans[s[0]]=long.MaxValue;
		Array.Sort(ans);
		bool b=true;
		int c=0,d=1,e=s[0]-1;
		long t=s[2];
		while(b){
			if(a[c][1]==1){
				for(int i = d;;i++) {
					if(i%s[1]==c){b=false;break;}
					else if(a[i%s[0]][1]==2){
						if((s[1]+a[i%s[0]][0]-a[c][0])%s[1]>=t*2){b=false;}
						else{c=i%s[1];d=(i+1)%s[1];}
						break;
					}
				}
			}
			else{
				for(int i = e;;i--) {
					if(i%s[1]==c){b=false;break;}
					else if(a[i%s[0]][1]==1){
						if((s[1]+a[c][0]-a[i%s[0]][0])%s[1]>=t*2){b=false;}
						else{c=i%s[1];e=(i-1)%s[1];}
						break;
					}
				}
			}
		}
		long g=g=(a[c][0]+(a[c][1]==1?s[2]:-s[2])+s[1])%s[1];
		for(int i = 0;i<s[0];i++) {
			if(ans[i]==g){g=i;break;}
		}
		if(ans[g]==ans[g+1]&&a[c][1]==2){g++;}
		StringBuilder sb=new StringBuilder();
		for(int i = 0;i<s[0];i++) {sb.Append(ans[(i+g)%s[0]]+"\n");}
		Console.Write(sb);
	}
}

