namespace AtCoder
{
	public class ProblemA
	{
		public static void Main(string[] args)
		{
			string[] line = Console.ReadLine().Split(' ');
			int n = int.Parse(line[0]);
			int l = int.Parse(line[1]);
			int t = int.Parse(line[2]);


			line = Console.ReadLine().Split(' ');
			var first = new Ant(l)
			{
				Position = int.Parse(line[0]),
				ToClockwise = line[1] == "1",
			};

			Ant prev = first;

			for (int i = 1; i < n; i++)
			{
				line = Console.ReadLine().Split(' ');
				var newAnt = new Ant(l)
				{
					Position = int.Parse(line[0]),
					ToClockwise = line[1] == "1",
					Prev = prev,
				};

				prev.Next = newAnt;
				prev = newAnt;
			}
			first.Prev = prev;
			prev.Next = first;

			Ant cur = first;

			while (cur.Seconds < t)
			{
				int pos = cur.Position;
				Ant tonari = null;
				if (cur.ToClockwise)
				{
					tonari = cur.Next;
					if (tonari.Seconds == cur.Seconds && tonari.Position == cur.GetRelativePosition(1) && !tonari.ToClockwise)
					{
						cur.Seconds++;
						cur.Reverse();
						tonari.Seconds++;
						tonari.Reverse();
						cur = tonari.Next;
					}
					else if (tonari.Seconds == cur.Seconds && tonari.Position == cur.GetRelativePosition(2) && !tonari.ToClockwise)
					{
						cur.Seconds++;
						cur.Move();
						cur.Reverse();
						tonari.Seconds++;
						tonari.Move();
						tonari.Reverse();
						cur = tonari.Next;
					}
					else
					{
						cur.Seconds++;
						cur.Move();
						cur = cur.Next;
					}
				}
				else
				{
					tonari = cur.Prev;
					if (tonari.Seconds == cur.Seconds && tonari.Position == cur.GetRelativePosition(-1) && tonari.ToClockwise)
					{
						cur.Seconds++;
						cur.Reverse();
						tonari.Seconds++;
						tonari.Reverse();
						cur = cur.Next;
					}
					else if (tonari.Seconds == cur.Seconds && tonari.Position == cur.GetRelativePosition(-2) && tonari.ToClockwise)
					{
						cur.Seconds++;
						cur.Move();
						cur.Reverse();
						tonari.Seconds++;
						tonari.Move();
						tonari.Reverse();
						cur = cur.Next;
					}
					else
					{
						cur.Seconds++;
						cur.Move();
						cur = cur.Next;
					}
				}
			}

			Ant target = first;
			var sb = new StringBuilder();
			for (int i = 0; i < n; i++, target = target.Next)
			{
				sb.AppendLine(target.Position.ToString());
			}

			Console.Write(sb.ToString());
		}
	}

	public class Ant
	{
		public Ant(int l)
		{
			this.l = l;
		}

		private int l;

		public int Seconds
		{
			get; set;
		}

		public int Position
		{
			get; set;
		}

		public bool ToClockwise
		{
			get; set;
		}

		public Ant Prev
		{
			get; set;
		}

		public Ant Next
		{
			get; set;
		}

		public void Move()
		{
			if (this.ToClockwise)
			{
				this.Position++;
				this.Position %= this.l;
			}
			else
			{
				this.Position--;
				if (this.Position < 0)
				{
					this.Position += this.l;
				}
			}
		}

		public void Reverse()
		{
			this.ToClockwise = !this.ToClockwise;
		}

		public int GetRelativePosition(int delta)
		{
			if (delta > 0)
			{
				return (this.Position + delta) % this.l;
			}
			else if (delta < 0)
			{
				int tmp = this.Position - 1;
				if (tmp < 0)
					tmp += this.l;

				return tmp;
			}

			return this.Position;
		}
	}
}

