using System;
using System.Linq;
using System.Collections.Generic;

public class Program
{
    public static void Main()
    {
        var nlt = Console.ReadLine().Split()
            .Select(x => int.Parse(x))
            .ToArray();
        var n = nlt[0];
        var l = nlt[1];
        var t = nlt[2];
        var antsQuery =
            from i in Enumerable.Range(0, n)
            let ant = Console.ReadLine().Split()
                .Select(x => int.Parse(x))
                .ToArray()
            select new { pos = ant[0], dir = ant[1] };
        var ants = antsQuery.ToArray();

        var xs = ants.Select(x => x.pos).ToArray();
        var ws = ants.Select(x => x.dir).ToArray();

        var splitQuery =
            from i in Enumerable.Range(0, n)
            group xs[i] by ws[i] into g
            select g;
        var split = Enumerable.Range(0, 3)
            .GroupJoin(splitQuery, w => w, g => g.Key, (w, gg) => new { w, g = gg.DefaultIfEmpty()?.First()?.ToArray() ?? new int[0] })
            .OrderBy(x => (3 - x.w) % 3)
            .Select(x => x.g)
            .ToArray();
        var encount = split.Select(x => x.Length).ToArray();
        var sign = ws.Select(w => w * 2 - 3).ToArray();

        var dl = l * 2;
        var turn = t / l;
        var last = t * 2 - dl * turn;
        var lastHalf = last / l * l;
        var lastWalk = last - lastHalf;
        var swapping = new int[n];
        var jl = Enumerable.Repeat(0, 3).ToArray();
        var jr = Enumerable.Repeat(1, 3).ToArray();
        if (encount.Skip(1).All(x => x > 0))
        for (int i = 0; i < n; ++i)
        {
            Func<int, bool> reachable = 
                k => PositiveMod((xs[i] * 2 - lastHalf - split[ws[i]][k] * 2) * sign[i], dl) <= lastWalk * 2;

            if (encount[ws[i]] == 1)
            {
                swapping[i] += reachable(0) ? 1 : 0;
                continue;
            }

            while (jr[ws[i]] != jl[ws[i]] && !reachable(jr[ws[i]]))
            {
                ++jr[ws[i]];
                jr[ws[i]] %= encount[ws[i]];
            }
            while (jl[ws[i]] != jr[ws[i]] & reachable(jl[ws[i]]))
            {
                ++jl[ws[i]];
                jl[ws[i]] %= encount[ws[i]];
            }
            while (jr[ws[i]] != jl[ws[i]] && reachable(jr[ws[i]]))
            {
                ++jr[ws[i]];
                jr[ws[i]] %= encount[ws[i]];
            }
            var spanning = jr[ws[i]] == jl[ws[i]];
            while (jl[ws[i]] != jr[ws[i]] && !reachable(jl[ws[i]]))
            {
                ++jl[ws[i]];
                jl[ws[i]] %= encount[ws[i]];
            }
            while (jr[ws[i]] != jl[ws[i]])
            {
                var j = PositiveMod(jr[ws[i]] - 1, encount[ws[i]]);
                if (reachable(j))
                {
                    break;
                }
                jr[ws[i]] = j;
            }
            while (jl[ws[i]] != jr[ws[i]])
            {
                var j = PositiveMod(--jl[ws[i]], encount[ws[i]]);
                if (!reachable(j))
                {
                    break;
                }
                jl[ws[i]] = j;
            }

            swapping[i] += spanning ? encount[ws[i]] : PositiveMod(jr[ws[i]] - jl[ws[i]], encount[ws[i]]);
        }

        last /= 2;
        var finalIndices = new int[n];
        for (int i = 0; i < n; ++i)
        {
            xs[i] = PositiveMod(xs[i] - last * sign[i], l);
            finalIndices[PositiveMod(i - swapping[i] * sign[i], n)] = i;
        }
        Console.WriteLine(string.Join("\n", finalIndices.Select(i => xs[i])));
    }

    static int PositiveMod(int n, int mod)
        => n >= 0 ? n % mod : n % mod + mod;
}

