			int t = int.Parse(line[2]);

			bool firstClockwise = false;
			int firstPosition = 0;
			Ant[] ants = new Ant[n];

			int count = 0;

			for (int i = 0; i < n; i++)
			{
				line = Console.ReadLine().Split(' ');
				int pos = int.Parse(line[0]);
				bool toClockwise = line[1] == "1";

				var a = new Ant() { Position = pos, ToClockwise = toClockwise };

				ants[i] = a;

				if (i == 0)
				{
					firstClockwise = toClockwise;
					firstPosition = pos;
				}
				else if (firstClockwise != toClockwise)
				{
					if (firstClockwise)
					{
						count += ((firstPosition - pos) + 2 * t) % l;
					}
					else
					{
						count += ((pos - firstPosition - l) + 2 * t) % l;
					}
				}

				if (a.ToClockwise)
					a.Position = (a.Position + t) % l;
				else
					a.Position = ((a.Position - t) % l + l) % l;
			}

			Ant first = ants[0];

			Array.Sort(ants, new Comparer());
			int p = Array.IndexOf(ants, first);

			count = count % n;
			if (!firstClockwise)
				count = n - count;

			var sb = new StringBuilder();
			for (int i = 0; i < n; i++)
			{
				int idx = (i + count + p - 1) % n;
				sb.AppendLine(ants[idx].Position.ToString());
			}

			Console.Write(sb.ToString());
		}

		private class Comparer : IComparer<Ant>
		{
			public int Compare([AllowNull] Ant x, [AllowNull] Ant y)
			{
				return x.Position - y.Position;
			}
		}
	}

