class Program
{
	static void Main()
	{
	string[] input = Console.ReadLine().Split(' ');//Splitで区切り文字を指定して複数個受け取る。
	int n = int.Parse(input[0]);
	long l = int.Parse(input[1]);
  long t = int.Parse(input[2]);
  long[] answers = new long[n];

  long[,] vertexes = new long[n,2];//ここに受け取る
    for(int i = 0; i < n; i++)
    {
    long[] nums = Array.ConvertAll(Console.ReadLine().Split(' '),long.Parse);//１行ごとに受け取る
    vertexes[i,0] = nums[0];
    vertexes[i,1] = nums[1];
    }

    long antNum = 0;//すれ違う回数
    long distance;//すれ違うまでの距離
    for(int i = 1; i < n; i++)
    {
      if(vertexes[i,1] == vertexes[0,1])//回転方向が異なるとき
      {
        distance = (vertexes[i,0] - vertexes[0,0] + l)%l;
        if(vertexes[0,1] == 2) distance = l - distance;
        if((l-distance)/2 >= t) antNum++;
        antNum += 2 * (t-((l-distance)/2)) / l;
        antNum %= n;
      }
    }

    long antNumPos = 0;//antNumの座標
    for(int i = 0; i < n; i++)//座標を求める
    {
      if(vertexes[i,1] == 1) answers[i] = (vertexes[i,0] + t) % l;
      else
      {
      answers[i] = (vertexes[i,0] - t) % l;
      if(answers[i] < 0) answers[i] += l;
      }
      if(i == antNum) antNumPos = answers[i];
    }
    Array.Sort(answers);

    int antCheck;
    for(int i = 0; i < n; i++)
    {
      if(antNumPos == answers[i]) antCheck = i;
    }

    for(int i = 0; i < n; i++)
    {
      int k = antCheck - antNum + i;
      if(k<0) k += n;
      Console.WriteLine(answers[k]);
    }


	}
}

