        var swapping = Enumerable.Range(0, n)
            .Where(i => ws[i] != ws[0])
            .Count(i => PositiveMod((xs[0] - xs[i]) * signs[0], l) <= 2 * t);

        for (int i = 0; i < n; ++i)
        {
