using System;
using System.Linq;
using System.Collections.Generic;

public class Program
{
    public static void Main()
    {
        var nlt = Console.ReadLine().Split()
            .Select(x => int.Parse(x))
            .ToArray();
        var n = nlt[0];
        var l = nlt[1];
        var t = nlt[2];
        var antsQuery =
            from i in Enumerable.Range(0, n)
            let ant = Console.ReadLine().Split()
                .Select(x => int.Parse(x))
                .ToArray()
            select new { pos = ant[0], dir = ant[1] };
        var ants = antsQuery.ToArray();
        var xs = ants.Select(x => x.pos).ToArray();
        var ws = ants.Select(x => x.dir).ToArray();

        var encount = new int[3];
        for (int i = 0; i < n; ++i)
        {
            ++encount[ws[i]];
        }

        var turn = t / l;
        var swapping = new int[n];
        for (int i = 0; i < n; ++i)
        {
            swapping[i] += encount[ws[i]] * turn * 2;
        }
        var remain = t % l;
        if (remain > l / 2)
        for (int i = 0; i < n; ++i)
        {
            switch (ws[i])
            {
                case 1:
                    xs[i] = (xs[i] + l / 2) % l;
                    break;
                case 2:
                    xs[i] = (xs[i] - l / 2 + l) % l;
                    break;
            }
            swapping[i] += encount[ws[i]];
        }
        var lastWalk = Math.Max(remain, remain - l / 2);
        for (int i = 0; i < n; ++i)
        {
            switch (ws[i])
            {
                case 1:
                    swapping[i] += Enumerable.Range(0, n)
                        .Count(j => ws[j] != ws[i] && (xs[j] - xs[i] + l) % l <= lastWalk);
                    break;
                case 2:
                    swapping[i] += Enumerable.Range(0, n)
                        .Count(j => ws[j] != ws[i] && (xs[i] - xs[j] + l) % l <= lastWalk);
                    break;
            }
        }

        var finalIndices = new int[n + 1];
        for (int i = 0; i < n; ++i)
        {
            switch (ws[i])
            {
                case 1:
                    xs[i] = (xs[i] + lastWalk) % l;
                    finalIndices[i] = (i + swapping[i]) % n;
                    break;
                case 2:
                    xs[i] = (xs[i] - lastWalk + l) % l;
                    finalIndices[i] = ((i - swapping[i]) % n + n) % n;
                    break;
            }
        }
        finalIndices[n] = finalIndices[0];
        Console.WriteLine(string.Join("\n", finalIndices.Skip(1).OrderBy(x => x).Select(x => xs[x])));
    }
}

