func main() {
  input := Input{bufio.NewReaderSize(os.Stdin,100)}
  n,l,t := input.Next3Ints()
  a := make([]Ant,n)
  w1 := 2*n
  for i:=0;i<n;i++ {
    x,w := input.Next2Ints()
    a[i] = Ant{i,x,w}
    w1 -= w
  }
  w2 := n-w1
  x1 := []int{}
  x2 := []int{}
  r := t/l
  for i:=0;i<n;i++ {
    if a[i].w == 1 {
      t := (int64(a[i].i)+int64(2*w2)*int64(r))%int64(n)
      a[i].i = int(t)
      x1 = append(x1,a[i].x)
    } else {
      t := (int64(a[i].i)-int64(2*w1)*int64(r))%int64(n)
      if t < 0 { t += int64(n) }
      a[i].i = int(t)
      x2 = append(x2,a[i].x)
    }
  }
  r = t%l
  for i:=0;i<n;i++ {
    if a[i].w == 1 {
      c := count(x2,a[i].x,a[i].x+2*r,l)
      a[i].i = (a[i].i+c)%n
      a[i].x = (a[i].x+r)%l
    } else {
      c := count(x1,a[i].x-2*r,a[i].x,l)
      a[i].i = (a[i].i-c)%n
      if a[i].i < 0 { a[i].i += n }
      a[i].x = (a[i].x-r)%l
      if a[i].x < 0 { a[i].x += l }
    }
  }
  ans := make([]int,n)
  for i:=0;i<n;i++ { ans[a[i].i] = a[i].x }
  for i:=0;i<n;i++ { fmt.Println(ans[i]) }
}
func count(x []int,fm,to,ln int) int {
  n := len(x)
  ret := 0
  if fm < 0 {
    d := -fm
    if d >= ln {
      d -= ln
      ret += n
    }
    ret += search(x,ln-d,ln)
    fm = 0
  }
  if to >= ln {
    d := to-ln
    if d >= ln {
      d -= ln
      ret += n
    }
    ret += search(x,0,d)
    to = ln-1
  }
  return ret+search(x,fm,to)
}
func search(x []int,fm,to int) int {
  lb := lowerBound(x,fm)
  ub := upperBound(x,to)
  return ub-lb
}
func lowerBound(x []int,d int) int {
  l := 0
  r := len(x)
  for l < r {
    m := (l+r)/2
    if x[m] < d {
      l = m+1
    } else {
      r = m
    }
  }
  return l
}
func upperBound(x []int,d int) int {
  l := 0
  r := len(x)
  for l < r {
    m := (l+r)/2
    if x[m] > d {
      r = m
    } else {
      l = m+1
    }
  }
  return l
}

