		next := ants[i].position + float64((ants[i].direction * t))
		if next < 0 {
			next = float64(l) + next
			negative++
		}
		if next > float64(l) {
			next = next - float64(l)
			positive++
		}

		ants[i] = Ant{
			direction: ants[i].direction,
			position:  next,
		}
	}

	sortedAnts := make(Ants, n)
	diff := positive - negative

	for i := 0; i < len(ants); i++ {
		var index int = i + diff

		if index >= len(ants) {
			sortedAnts[index-len(ants)] = ants[i]
			continue
		}
		if index < 0 {
			sortedAnts[len(ants)-index] = ants[i]
			continue
		}
		sortedAnts[index] = ants[i]
	}

	for i := 0; i < len(sortedAnts); i++ {
		fmt.Println(sortedAnts[i].position)
	}
