  for i:=0;i<n;i++ {
    x[i],w = input.Next2Ints()
    r[w-1] = append(r[w-1],i)
  }
  if len(r[0]) == 0 {
    for i:=0;i<n;i++ {
      x[i] = (x[i]-t)%l
      if x[i] < 0 { x[i] += l }
      fmt.Println(x[i])
    }
