    for i:=0;i<n;i++ { fmt.Println((x[i]+t)%l) }
    return
  }
  event := []float64{0,0.5*float64(l)}
  for i:=0;i<len(r[0]);i++ {
    cw := x[r[0][i]]
    if cw > x[r[1][0]] { cw -= l }
    event = append(event,0.5*float64(x[r[1][0]]-cw))
  }
  sort.Float64s(event)
  coll := int(float64(t)/(0.5*float64(l)))*len(r[0])
  rsdl := float64(t)-float64(coll)*(0.5*float64(l))
  k := sort.Search(len(event),func(k int) bool { return rsdl < event[k] })
  coll += k-1
  ccwx := x[r[1][0]]
  for i:=0;i<len(r[0]);i++ {
    x[r[0][i]] = (x[r[0][i]]+(2*t)%l)%l
  }
  sort.Ints(x)
  j := -1
  for i:=0;i<n;i++ {
    if x[i] == ccwx { j = i;break }
  }
  y := make([]int,n)
  for i:=j;i<n;i++ {
    m := (r[1][0]-coll+i-j)%n
    if m < 0 { m += n }
    y[m] = (x[i]-t)%l
    if y[m] < 0 { y[m] += l }
  }
  for i:=0;i<j;i++ {
    m := (r[1][0]-coll+n+i-j)%n
    if m < 0 { m += n }
    y[m] = (x[i]-t)%l
    if y[m] < 0 { y[m] += l }
  }
