int main() {
    auto sc = new Scanner(stdin);
    int n; long l, t;
    sc.read(n, l, t);
    long[] x = new long[n];
    int[] w = new int[n];
    foreach (i; 0..n) {
        sc.read(x[i], w[i]);
    }

    int cnt = 0;
    foreach (i; 1..n) {
        if (w[0] == w[i]) continue;
        long dist = x[i]-x[0];
        if (w[0] == 2) dist = l-dist;
        long tt = 2*t;
        if (tt < dist) continue;
        tt -= dist; cnt++;
        cnt += tt/l;
        cnt %= n;
    }
    if (w[0] == 2) cnt = (n-cnt)%n;
    long[2][] x2 = new long[2][n];
    foreach (i; 0..n) {
        long nx;
        if (w[i] == 1) nx = (x[i]+t)%l;
        else nx = ((x[i]-t)%l+l)%l;
        x2[i] = [nx, -i];
        if (w[0] == 2) x2[i][1] *= -1;
    }
    x2.sort!"a<b";
//    writeln(x2);
    int st = -1;
    foreach (i; 0..n) {
        if (x2[i][1] == 0) st = i;
    }
    foreach (i; 0..n) {
        writeln(x2[(st+i-cnt+n)%n][0]);
    }
    return 0;
}
