import sys 
def turn(wise):
    if wise ==1 :
        return 2
    else:
        return 1
def calculate_index(n, N): 
    if n < 0:
        return n+N 
    if n > N:
        return n-N 
    return n
def min_step(Ants,N,L):
    ret = sys.maxint
    for i in xrange(N):
        j = (i+N-1) % N 
        if Ants[j][1] == 1 and Ants[i][1] == 2:
            ret = min( calculate_index(Ants[i][0] - Ants[j][0],L)/2 , ret) 
    return ret 
def runAnts(Ants,t,N,L):
    for a in Ants:
        if a[1] == 1:
            a[0] = calculate_index(a[0] + t, L)
        else:
            a[0] = calculate_index(a[0] - t, L)  
    for i in xrange(N):
        j = (i+N-1) % N 
        k = (i+1) % N 
        if Ants[i][0] == Ants[k][0] or Ants[i][0] == Ants[j][0]:
            Ants[i][1] = turn(Ants[i][1])
    return Ants

