def normalize(x):
    return (x + L) % L


def prepare():
    cw_list = []
    ccw_list = []
    ants_map = {}
    for no in range(1, N + 1):
        (x, w) = list(map(int, input().split()))
        if w == 1:
            cw_list.append(no)
        else:
            ccw_list.append(no)
            w = -1
        move = []
        for t in range(T + 1):
            move.append(normalize(x + w * t))
        ants_map[no] = move
    return cw_list, ccw_list, ants_map


def get_combi_list(cw_list, ccw_list):
    combi = []
    for cw in cw_list:
        for ccw in ccw_list:
            combi.append((cw, ccw))
    return combi

def get_cross_point():
    cross_point_list = []
    for t in range(1, T + 1):
        between_points = []
        points = []
        for a, b in combi_list:
            prev_a = ants_map[a][t - 1]
            curr_a = ants_map[a][t]
            prev_b = ants_map[b][t - 1]
            curr_b = ants_map[b][t]
            if prev_a == curr_b and prev_b == curr_a:
                between_points.append((t - 0.5, a, b))
            if curr_a == curr_b:
                points.append((t, a, b))
        if len(between_points) > 0:
            cross_point_list.append(between_points)
        if len(points) > 0:
            cross_point_list.append(points)            

    return cross_point_list


def get_dst_list(ants_map):
    dst = []
    for no in sorted(ants_map.keys()):
        dst.append(ants_map[no][-1])
    return dst


def exchange(dst_list, ia, ib):
    prev_a = dst_list[ia]
    prev_b = dst_list[ib]
    dst_list[ia] = prev_b
    dst_list[ib] = prev_a


