def solve(N: int, L: int, T: int, X: "List[int]", W: "List[int]"):

    # 蟻の最終位置
    last_X = [0]*N
    for i in range(N):
        last_X[i] = (X[i]+T) % L if W[i] == 1 else (X[i]-T) % L

    # print(last_X)

    # 蟻0の他の蟻とすれ違う回数
    switch_counter = 0
    for i in range(1, N):
        if W[i] == W[0]:
            continue
        if W[0] == 1:
            if 2*T < ((X[i]-X[0]) % L):
                switch_counter += 0
            else:
                switch_counter += 1+int((2*T - ((X[i]-X[0]) % L))/L)
        elif W[0] == 2:
            if 2*T < ((X[0]-X[i]) % L):
                switch_counter += 0
            else:
                switch_counter += 1+int((2*T - ((X[0]-X[i]) % L))/L)
    # 蟻0の最終のゼッケン番号は
    if W[0] == 1:
        zekken = switch_counter
    else:
        zekken = (-switch_counter) % N
    for i in range(N):
        print(last_X[(N-zekken+i) % N])
    return


