import sys


def solve(N: int, L: int, T: int, X: "List[int]", W: "List[int]"):
    r=0
    x=0#基準座標
    w=0#基準index
    ans=[]
    f=True
    for i in range(N):
        if(W[i]==1):
            w=i
            x=X[i]
            f=False
            break
    if f :#全員逆向き
        for i in range(N):
            X[i]-=T%L
            if X[i]<0:
                X[i]+=L
        ans=X
        print("\n".join(map(str,ans)))
        return

    #基準より前にいるやつで逆のやつがいたら遠さからrをカウント
    for i in range(N):
        if W[(i+w)%N]==2:
            tmp=X[(i+w)%N]
            diff=max(tmp,x)-max(tmp,x)
            if(diff)/2<T:
                r+=1+(T-(diff)/2)//(L/2)
                if (T-(diff)/2)%(L/2)==0:
                    r-=1

    for i in range(N):
            if(W[i]==1):
                X[i]+=T%L
            else:
                X[i]-=T%L
            if(X[i]>L):X[i]-=L
            if(X[i]<0):X[i]+=L

    r%=N
    r=int(r)
    ans=X
    ans=ans[N-r:N]+ans[0:N-r]
    print("\n".join(map(str,ans)))
    return






