class Ant:
    def __init__(self, index, pos, direction):
        self.index = index
        self.pos = pos
        self.direction = direction

    def move(self):
        if self.direction == 1:
            self.pos += 1
        else:
            self.pos -= 1

        if self.pos >= L:
            self.pos = self.pos - L
        if self.pos < 0:
            self.pos += L + self.pos

    def change_direction(self):
        if self.direction == 1:
            self.direction = 2
        else:
            self.direction = 1

def get_colide_ant_list(ant_list):
    colide_ant_list = []
    ant_list = sorted(ant_list, key=lambda ant: ant.pos)
    len_ant_list = len(ant_list)
    for i in range(len_ant_list-1):
        if ant_list[i].pos == ant_list[i+1].pos:
            colide_ant_list.append((ant_list[i], ant_list[i+1]))
        elif (ant_list[i+1].index - ant_list[i].index != 1) and \
             (ant_list[i].direction == 2 and ant_list[i+1].direction == 1):
            colide_ant_list.append((ant_list[i], ant_list[i+1]))
    if ant_list[0].index > ant_list[-1].index and (ant_list[0].direction == 1 and ant_list[-1].direction == 2):
        colide_ant_list.append((ant_list[0], ant_list[-1]))

    return colide_ant_list


