def new_place(ant, l, t):
    x = ant[0]
    w = ant[1]
    a = t%l
    if w == 1:
        new = x + a
        if new >= l:
            new -= l
    else:
        new = x - a
        if new < 0:
            new += l
    return new

def num_cross(ant1, ant2, l, t):
    if ant1[1] == ant2[1]:
        return 0
    if (ant2[0] - ant1[0])%2 == 0:
        if ant1[1] == 1:
            if t <= (ant2[0] - ant1[0])/2:
                return 0
            else:
                return 2*(t - 1 - (ant2[0] - ant1[0])/2)//l + 1
        else:
            if t - (ant1[0] + l -ant2[0])/2 <= 0:
                return 0
            else:
                return 2*(t - 1 - (ant1[0] + l -ant2[0])/2)//l + 1
    else:
        if ant1[1] == 1:
            if t <= (ant2[0] - ant1[0])/2:
