        'x': x,
        'w': 1 if w == 1 else -1
    })


def normalize(x):
    return (x + L) % L


def find_neighbor(ant):
    x = ant['x']
    for neighbor in snapshot:
        if ant['no'] == neighbor['no']:
            continue
        _x = neighbor['x']
        if _x == normalize(x - 1) and (ant['w'] == -1 and neighbor['w'] == 1):
            return neighbor
        if _x == normalize(x + 1) and (ant['w'] == 1 and neighbor['w'] == -1):
            return neighbor
        if _x == x:
            return neighbor
    return None


def move():
    results = {}
    for ant in copy.deepcopy(snapshot):
        x = ant['x']        
        no = ant['no']
        if no in results:
            continue
        neighbor = find_neighbor(ant)
        if neighbor is None:
            ant['x'] = normalize(ant['x'] + ant['w'])
            results[ant['no']] = ant
            continue
        if x == neighbor['x']:
            ant['w'] *= -1
            ant['x'] = normalize(ant['x'] + ant['w'])
            if neighbor['no'] not in results:            
                neighbor['w'] *= -1
                neighbor['x'] = normalize(neighbor['x'] + neighbor['w'])
                results[neighbor['no']] = neighbor
        else:
            ant['w'] *= -1
            results[ant['no']] = ant
            if neighbor['no'] not in results:
                neighbor['w'] *= -1
                results[neighbor['no']] = neighbor
    ret = []
    for k in sorted(results.keys()):
        ret.append(results[k])
    return ret


