            let m = (2 * t + v[0].0 + l - v[i].0) / l;
            id = (id + m) % n;
        } else {
            let m = (2 * t + v[i].0 - v[0].0) / l;
            id = (id + n - m % n) % n;
        }
    }
    let mut ps = vec![0; n];
    for i in 0..n {
        if v[i].1 == 1 {
            ps[i] = (v[i].0 + t) % l;
        } else {
            ps[i] = (v[i].0 + l - t % l) % l;
        }
    }
    let mut j = 0;
    let p0 = if v[0].1 == 1 {
        (v[0].0 + t) % l
    } else {
        (v[0].0 + l - t % l) % l
    };
    ps.sort();
    while ps[j] != p0 {
        j += 1;
    }
    let mut ans = vec![0; n];
    for i in 0..n {
        ans[(i + id) % n] = ps[(j + i) % n];
    }
    for &a in &ans {
        println!("{}", a);
    }
}

fn main() {
    let s = std::io::stdin();
    let mut sc = Scanner { stdin: s.lock() };
    let n: usize = sc.read();
    let l: usize = sc.read();
    let t: usize = sc.read();
    let xw: Vec<(usize, usize)> = (0..n).map(|_| (sc.read(), sc.read())).collect();

    let mut clockwise = 0;
    let mut counter_clock_wise = 0;
    for (i, (x, w)) in xw.iter().cloned().enumerate() {
        if w == 1 {
            clockwise += (x + t - 1) / l;
        } else if t > x {
            counter_clock_wise += ((l - x) + t - 1) / l;
        }
    }

    eprintln!("{} {}", clockwise, counter_clock_wise);
    if clockwise == counter_clock_wise {
        let mut next_x = xw
            .iter()
            .cloned()
            .map(|(x, w)| {
                if w == 1 {
                    (x + t) % l
                } else {
                    (l - ((l - x) + t) % l) % l
                }
            })
            .collect::<Vec<_>>();
        next_x.sort();
        for i in 0..n {
            println!("{}", next_x[i]);
        }
    } else if clockwise > counter_clock_wise {
        let mut next_x = xw
            .iter()
            .cloned()
            .map(|(x, w)| {
                if w == 1 {
                    (x + t) % l
                } else {
                    (l - ((l - x) + t) % l) % l
                }
            })
            .collect::<Vec<_>>();
        next_x.sort();
        let over = clockwise - counter_clock_wise;
        for i in 0..n {
            println!("{}", next_x[(over + i) % n]);
        }
    } else {
        let mut next_x = xw
            .iter()
            .cloned()
            .map(|(x, w)| {
                if w == 1 {
                    (x + t) % l
                } else {
                    l - ((l - x) + t) % l
                }
            })
            .collect::<Vec<_>>();
        next_x.sort();

        let over = counter_clock_wise - clockwise;
        for i in 0..n {
            println!("{}", next_x[(n - over + i) % n]);
        }
    }
}

pub struct Scanner<R> {
    stdin: R,
}

impl<R: std::io::Read> Scanner<R> {
    pub fn read<T: std::str::FromStr>(&mut self) -> T {
        use std::io::Read;
        let buf = self
            .stdin
            .by_ref()
            .bytes()
            .map(|b| b.unwrap())
            .skip_while(|&b| b == b' ' || b == b'\n' || b == b'\r')
            .take_while(|&b| b != b' ' && b != b'\n' && b != b'\r')
            .collect::<Vec<_>>();
        unsafe { std::str::from_utf8_unchecked(&buf) }
            .parse()
            .ok()
            .expect("Parse error.")
    }
    pub fn vec<T: std::str::FromStr>(&mut self, n: usize) -> Vec<T> {
        (0..n).map(|_| self.read()).collect()
    }
    pub fn chars(&mut self) -> Vec<char> {
        self.read::<String>().chars().collect()
    }
}

