	let mut scan = InputScanner::new(stdin.lock(),256);

	let n:usize = scan.next();
	let l:usize = scan.next();
	let t:usize = scan.next();

	let mut xw:Vec<(usize,usize,bool)> = Vec::with_capacity(n);
	let mut lx:Vec<(usize,usize)> = Vec::with_capacity(n);
	let mut rx:Vec<(usize,usize)> = Vec::with_capacity(n);

	for i in 0..n {
		let x:usize = scan.next();
		let w:char = scan.next::<String>().chars().collect::<Vec<char>>()[0];

		if w == '1' {
			rx.push((i,x));
			xw.push((i,x,true));
		} else {
			lx.push((i,x));
			xw.push((i,x,false));
		}
	}

	let mut i:usize = 0;

	let mut d:usize = 0;
	let mut count:usize = 0;
	let mut rc = 0;

	if rx[0].0 == xw[i].0 {
		i += 1;
	}

	if lx.len() > 0 && rx.len() > 0 {
		while d < (t * 2) % l {
			let offset = ((xw[i].1 + 2*l) - (rx[0].1) - d) % l;

			if xw[i].2 {
				rc += 1;
			} else {
				rc = 0;
			}

			if offset == 0 || (d + offset > (t * 2) % l) {
				break;
			}

			d += offset;

			count += 1;
			i += 1;
			i = i % xw.len();
		}
	}

	let offset:usize = count - rc as usize;

	let mut all = rx.into_iter().map(|(i,x)| ((i+offset)%n,(x+(t%l))%l)).collect::<Vec<(usize,usize)>>();
	all.append(&mut lx.into_iter().map(|(i,x)| ((i+offset)%n,(l+x-(t%l))%l)).collect::<Vec<(usize,usize)>>());

	all.sort_by(|a,b| a.0.cmp(&b.0));

	println!("{}",all.into_iter().map(|(_,x)| format!("{}",x)).collect::<Vec<String>>().join("\n"));
}
struct InputScanner<R: BufRead> {
	reader: R,
	buf: Vec<u8>, // Should never be empty
	pos: usize,   // Should never be out of bounds as long as the input ends with '\n'
}
impl<R: BufRead> InputScanner<R> {
	fn new(reader: R, capacity: usize) -> Self {
		InputScanner {
			reader: reader,
			buf: Vec::with_capacity(capacity),
			pos: 0,
		}
	}

	#[inline]
	fn next<T: FromStr>(&mut self) -> T
	where
		T::Err: fmt::Debug,
	{
		if self.buf.is_empty() {
			self._read_next_line();
		}
		let mut start = None;
		loop {
			match (self.buf[self.pos], start.is_some()) {
				(b' ', true) | (b'\n', true) | (b'\r', true) => break,
				(_, true) | (b' ', false) => self.pos += 1,
				(b'\n', false) | (b'\r', false) => self._read_next_line(),
				(_, false) => start = Some(self.pos),
			}
		}
		let target = &self.buf[start.unwrap()..self.pos];
		unsafe { str::from_utf8_unchecked(target) }.parse().unwrap()
	}

	#[inline]
	fn _read_next_line(&mut self) {
		self.pos = 0;
		self.buf.clear();
		if self.reader.read_until(b'\n', &mut self.buf).unwrap() == 0 {
			panic!("Reached EOF");
		}
	}
}

