    let (n, l, t) = (v[0] as usize, v[1], v[2]);
    let mut xs = vec![];
    let mut ws = vec![];
    for _ in 0..n {
        let v = read_vec::<i64>();
        xs.push(v[0]);
        ws.push(if v[1] == 2 { -1 } else { 1 });
    }
    let reversed = ws[0] == -1;
    if reversed {
        for i in 0..n {
            xs[i] = (l - xs[i]) % l;
            ws[i] = -ws[i];
        }
    }

    let mut poses = vec![];
    for (&x, &w) in xs.iter().zip(ws.iter()) {
        if w == 1 {
            poses.push((((x + t) % l), w));
        } else {
            poses.push((((l + (x - t) % l) % l), w));
        }
    }

    poses.sort();

    let mut count = 0;
    for i in 1..n {
        if ws[i] == -1 {
            count += 2 * t / l;
            if (2 * t) % l >= (xs[i] - xs[0] + l) % l {
                count += 1;
            }
        }
    }
    let count = count as usize % n;

    let zero_pos = ((xs[0] + t) % l, 1);
    let mut zero_idx = 0;
    for i in 0..n {
        if poses[i] == zero_pos {
            zero_idx = i;
        }
    }
    let mut answers = vec![0; n];

    for i in 0..n {
        if reversed {
            answers[i] = poses[(2 * n - i + zero_idx - count) % n].0;
        } else {
            answers[i] = poses[(i + zero_idx + n - count) % n].0;
        }
    }
    debug!(count, zero_idx);

    if reversed {
        for i in 0..n {
            answers[i] = (l - answers[i]) % l;
        }
    }
    for ans in answers {
        println!("{}", ans);
    }
}

