use std::mem::drop;

fn main() {
    read!(n = usize, len = i32, dur = i32);
    let dur = (dur % len) * 2;
    let len = len*2;
    dbg!((dur, len));
    let mut ls: Vec<(usize, i32)> = Vec::new();
    let mut rs: Vec<(usize, i32)> = Vec::new();
    let mut xs: Vec<(u8, i32)> = Vec::new();
    let mut i = 0;
    readx_loop!(|x = i32, w = u8| {
        xs.push((w, 2*x));
        if w == 1 {
            ls.push((i, 2*x - len));
            ls.push((i, 2*x - 2*len));
        } else {
            rs.push((i, 2*x));
            rs.push((i, 2*x + len));
        }
        i += 1;
    });
    drop(i);
    ls.sort_by_key(|&(_, x)| x);
    rs.sort_desc_by_key(|&(_, x)| x);
    dbg!(&xs);
    dbg!((&ls, &rs));
    let origin: (usize, i32) = ls.last().map_or_else(|| *rs.last().unwrap(), |llast| *llast);

    let mut is_l = true;
    let to_i = if ls.is_empty() || rs.is_empty() { origin.0 } else {
        let mut l = ls.pop().unwrap();
        let mut r = rs.pop().unwrap();
        loop {
            let next_t = (r.1 - l.1) / 2;
            if next_t >= dur {
                break;
            }
            if is_l {
                is_l = false;
                match ls.pop() {
                    None => break,
                    Some(new_l) => l = new_l
                }
            } else {
                is_l = true;
                match rs.pop() {
                    None => break,
                    Some(new_r) => r = new_r
                }
            }
        }
        if is_l { l.0 } else { r.0 }
    };
    dbg!((origin, to_i));
    let to_x = if xs[to_i].0 == 1 { (xs[to_i].1 + dur) % len } else { (xs[to_i].1 + len - dur) % len };
    let mut moved_xs: Vec<i32> = xs.iter().map(|&(w, x)| {
        if w == 1 { (x + dur) % len } else { (x + len - dur) % len }
    }).collect();
    moved_xs.sort();
    dbg!(&moved_xs);
    let moved_to_i = if is_l {
        moved_xs.iter().enumerate().find(|&(_, &x)| x == to_x).unwrap().0
    } else {
        moved_xs.iter().enumerate().rev().find(|&(_, &x)| x == to_x).unwrap().0
    };

    let mut ans = vec![0; n];
    for i in 0..n {
        ans[(origin.0 + i) % n] = moved_xs[(moved_to_i + i) % n];
    }
    for x in ans {
        println!("{}", x/2);
    }
}

fn main() {
    let mut sc = Scanner::new();
    let n = sc.usize_read();
    let l = sc.usize_read();
    let t = sc.usize_read();
    let xw: Vec<(usize, bool)> = (0..n).map(|_| (sc.read(), sc.usize_read() == 1)).collect();

    let (first_pos, first_clock) = xw[0];
    let mut conflict_first = 0;
    for i in 1..n {
        let (x, w) = xw[i];
        if w == first_clock {
            continue;
        }
        let interval = if first_clock {
            x - first_pos
        } else {
            l + first_pos - x
        };

        if interval > t * 2 {
            continue;
        }
        conflict_first += (2 * t - interval + 2 * l - 1) / (2 * l);
    }

    let mut moved = vec![];
    for &(x, w) in &xw {
        if w {
            let x = (x + t) % l;
            moved.push(x);
        } else {
            let x = (l + x - t % l) % l;
            moved.push(x);
        }
    }
    moved.sort();
    let moved_first = if first_clock {
        (first_pos + t) % l
    } else {
        (l + first_pos - t % l) % l
    };

    let mut moved_first_i = 0;
    for i in 0..n {
        if moved_first == moved[i] {
            moved_first_i = i;
        }
    }
    let cur_id = if first_clock {
        conflict_first % n
    } else {
        (n - conflict_first % n) % n
    };

    let mut ans = vec![0; n];
    for i in 0..n {
        ans[(cur_id + i) % n] = moved[(moved_first_i + i) % n];
    }

    for &ans in &ans {
        println!("{}", ans);
    }
}

struct Scanner {
    ptr: usize,
    length: usize,
    buf: Vec<u8>,
    small_cache: Vec<u8>,
}

#[allow(dead_code)]
impl Scanner {
    fn new() -> Scanner {
        Scanner {
            ptr: 0,
            length: 0,
            buf: vec![0; 1024],
            small_cache: vec![0; 1024],
        }
    }

    fn load(&mut self) {
        use std::io::Read;
        let mut s = std::io::stdin();
        self.length = s.read(&mut self.buf).unwrap();
    }

    fn byte(&mut self) -> u8 {
        if self.ptr >= self.length {
            self.ptr = 0;
            self.load();
            if self.length == 0 {
                self.buf[0] = b'\n';
                self.length = 1;
            }
        }

        self.ptr += 1;
        return self.buf[self.ptr - 1];
    }

    fn is_space(b: u8) -> bool {
        b == b'\n' || b == b'\r' || b == b'\t' || b == b' '
    }

    fn read_vec<T>(&mut self, n: usize) -> Vec<T>
    where
        T: std::str::FromStr,
        T::Err: std::fmt::Debug,
    {
        (0..n).map(|_| self.read()).collect()
    }

    fn usize_read(&mut self) -> usize {
        self.read()
    }

    fn read<T>(&mut self) -> T
    where
        T: std::str::FromStr,
        T::Err: std::fmt::Debug,
    {
        let mut b = self.byte();
        while Scanner::is_space(b) {
            b = self.byte();
        }

        for pos in 0..self.small_cache.len() {
            self.small_cache[pos] = b;
            b = self.byte();
            if Scanner::is_space(b) {
                return String::from_utf8_lossy(&self.small_cache[0..(pos + 1)])
                    .parse()
                    .unwrap();
            }
        }

        let mut v = self.small_cache.clone();
        while !Scanner::is_space(b) {
            v.push(b);
            b = self.byte();
        }
        return String::from_utf8_lossy(&v).parse().unwrap();
    }
}

use std::fmt;
use std::io::stdin;
use std::io::BufRead;
use std::str;
use std::str::FromStr;

fn main() {
	let stdin = stdin();
	let mut scan = InputScanner::new(stdin.lock(),256);

	let n:usize = scan.next();
	let l:i64 = scan.next();
	let t:i64 = scan.next();

	let mut xw:Vec<(usize,usize,bool)> = Vec::with_capacity(n);
	let mut lx:Vec<(usize,usize)> = Vec::with_capacity(n);
	let mut rx:Vec<(usize,usize)> = Vec::with_capacity(n);

	for i in 0..n {
		let x:usize = scan.next();
		let w:char = scan.next::<String>().chars().collect::<Vec<char>>()[0];

		if w == '1' {
			rx.push((i,x));
			xw.push((i,x,true));
		} else {
			lx.push((i,x));
			xw.push((i,x,false));
		}
	}

	xw.sort_by(|a,b| a.1.cmp(&b.1));

	let mut count:i64 = 0;

	for &x in &xw {
		if x.2 {
			count -= (t + x.1 as i64) / l;
		} else {
			count += (t - (x.1 as i64 + 1) + l) / l;
		}
	}

	let offset = (count % n as i64 + n as i64) as usize;

	let n = n as usize;
	let l = l as usize;
	let t = t as usize;
	let mut all = rx.into_iter().map(|(i,x)|(i,(x+(t%l))%l)).collect::<Vec<(usize,usize)>>();
	all.append(&mut lx.into_iter().map(|(i,x)|(i,(l+x-(t%l))%l)).collect::<Vec<(usize,usize)>>());

	all.sort_by(|a,b| a.1.cmp(&b.1));

	let mut r = (0..n).map(|_| 0).collect::<Vec<usize>>();

	for i in 0..n {
		r[(i+offset)%n] = all[i].1;
	}

	println!("{}",r.into_iter().map(|x| format!("{}",x)).collect::<Vec<String>>().join("\n"));
}
struct InputScanner<R: BufRead> {
	reader: R,
	buf: Vec<u8>, // Should never be empty
	pos: usize,   // Should never be out of bounds as long as the input ends with '\n'
}
impl<R: BufRead> InputScanner<R> {
	fn new(reader: R, capacity: usize) -> Self {
		InputScanner {
			reader: reader,
			buf: Vec::with_capacity(capacity),
			pos: 0,
		}
	}

	#[inline]
	fn next<T: FromStr>(&mut self) -> T
	where
		T::Err: fmt::Debug,
	{
		if self.buf.is_empty() {
			self._read_next_line();
		}
		let mut start = None;
		loop {
			match (self.buf[self.pos], start.is_some()) {
				(b' ', true) | (b'\n', true) | (b'\r', true) => break,
				(_, true) | (b' ', false) => self.pos += 1,
				(b'\n', false) | (b'\r', false) => self._read_next_line(),
				(_, false) => start = Some(self.pos),
			}
		}
		let target = &self.buf[start.unwrap()..self.pos];
		unsafe { str::from_utf8_unchecked(target) }.parse().unwrap()
	}

	#[inline]
	fn _read_next_line(&mut self) {
		self.pos = 0;
		self.buf.clear();
		if self.reader.read_until(b'\n', &mut self.buf).unwrap() == 0 {
			panic!("Reached EOF");
		}
	}
}

