	let mut lx:Vec<(usize,usize)> = Vec::with_capacity(n);
	let mut rx:Vec<(usize,usize)> = Vec::with_capacity(n);

	for i in 0..n {
		let x:usize = scan.next();
		let w:char = scan.next::<String>().chars().collect::<Vec<char>>()[0];

		if w == '1' {
			rx.push((i,x));
		} else {
			lx.push((i,x));
		}
	}

	let mut li:usize = 0;

	let mut d:usize = 0;
	let mut count:usize = 0;

	if lx.len() > 0 && rx.len() > 0 {
		while d <= (t * 2) % l {
			d += if ((lx[li].1 + l) - d) % l == 0 {
				l
			} else {
				((lx[li].1 + l) - d) % l
			};

			if d > (t *2) %l {
				break;
			}

			count += 1;
			li += 1;
			li = li % lx.len();
		}
	}

	let offset:usize = count;

	let mut all = rx.into_iter().map(|(i,x)| ((i+offset)%n,(x+(t%l))%l)).collect::<Vec<(usize,usize)>>();
	all.append(&mut lx.into_iter().map(|(i,x)| ((i+offset)%n,(l+x-(t%l))%l)).collect::<Vec<(usize,usize)>>());

	all.sort_by(|a,b| a.0.cmp(&b.0));

	println!("{}",all.into_iter().map(|(_,x)| format!("{}",x)).collect::<Vec<String>>().join("\n"));
}
struct InputScanner<R: BufRead> {
	reader: R,
	buf: Vec<u8>, // Should never be empty
	pos: usize,   // Should never be out of bounds as long as the input ends with '\n'
}
impl<R: BufRead> InputScanner<R> {
	fn new(reader: R, capacity: usize) -> Self {
		InputScanner {
			reader: reader,
			buf: Vec::with_capacity(capacity),
			pos: 0,
		}
	}

	#[inline]
	fn next<T: FromStr>(&mut self) -> T
	where
		T::Err: fmt::Debug,
	{
		if self.buf.is_empty() {
			self._read_next_line();
		}
		let mut start = None;
		loop {
			match (self.buf[self.pos], start.is_some()) {
				(b' ', true) | (b'\n', true) | (b'\r', true) => break,
				(_, true) | (b' ', false) => self.pos += 1,
				(b'\n', false) | (b'\r', false) => self._read_next_line(),
				(_, false) => start = Some(self.pos),
			}
		}
		let target = &self.buf[start.unwrap()..self.pos];
		unsafe { str::from_utf8_unchecked(target) }.parse().unwrap()
	}

	#[inline]
	fn _read_next_line(&mut self) {
		self.pos = 0;
		self.buf.clear();
		if self.reader.read_until(b'\n', &mut self.buf).unwrap() == 0 {
			panic!("Reached EOF");
		}
	}
}

fn main() {
    let mut sc = Scanner::new();
    let n = sc.usize_read();
    let length: usize = sc.read();
    let time: usize = sc.read();
    let xw: Vec<(usize, bool)> = (0..n).map(|_| (sc.read(), sc.read::<i32>() == 1)).collect();

    let (first_pos, first_clock) = xw[0];
    let cross_count: usize = xw[1..n]
        .iter()
        .filter(|&&(_, clock)| clock != first_clock)
        .map(|&(pos, _)| {
            if first_clock {
                pos - first_pos
            } else {
                length + first_pos - pos
            }
        })
        .filter(|&distance| time * 2 >= distance)
        .map(|distance| (time * 2 - distance + length - 1) / length)
        .sum();

    let final_num = if first_clock {
        cross_count % n
    } else {
        (n - cross_count % n) % n
    };

    let final_pos = if first_clock {
        (first_pos + time) % length
    } else {
        (first_pos + length - time % length) % length
    };

    let mut final_states = xw.iter()
        .map(|&(pos, clock)| {
            if clock {
                (pos + time) % length
            } else {
                (pos + length - time % length) % length
            }
        })
        .collect::<Vec<_>>();
    final_states.sort();

    let mut final_i = final_states
        .iter()
        .enumerate()
        .filter(|&(_, &pos)| pos == final_pos)
        .map(|(i, &_)| i);
    let final_i = if first_clock {
        final_i.next().unwrap()
    } else {
        final_i.last().unwrap()
    };

    let mut ans = vec![0; n];
    for i in 0..n {
        ans[(final_num + i) % n] = final_states[(final_i + i) % n];
    }

    for &a in &ans {
        println!("{}", a);
    }
}

struct Scanner {
    ptr: usize,
    length: usize,
    buf: Vec<u8>,
    small_cache: Vec<u8>,
}

#[allow(dead_code)]
impl Scanner {
    fn new() -> Scanner {
        Scanner {
            ptr: 0,
            length: 0,
            buf: vec![0; 1024],
            small_cache: vec![0; 1024],
        }
    }

    fn load(&mut self) {
        use std::io::Read;
        let mut s = std::io::stdin();
        self.length = s.read(&mut self.buf).unwrap();
    }

    fn byte(&mut self) -> u8 {
        if self.ptr >= self.length {
            self.ptr = 0;
            self.load();
            if self.length == 0 {
                self.buf[0] = b'\n';
                self.length = 1;
            }
        }

        self.ptr += 1;
        return self.buf[self.ptr - 1];
    }

    fn is_space(b: u8) -> bool {
        b == b'\n' || b == b'\r' || b == b'\t' || b == b' '
    }

    fn read_vec<T>(&mut self, n: usize) -> Vec<T>
    where
        T: std::str::FromStr,
        T::Err: std::fmt::Debug,
    {
        (0..n).map(|_| self.read()).collect()
    }

    fn usize_read(&mut self) -> usize {
        self.read()
    }

    fn read<T>(&mut self) -> T
    where
        T: std::str::FromStr,
        T::Err: std::fmt::Debug,
    {
        let mut b = self.byte();
        while Scanner::is_space(b) {
            b = self.byte();
        }

        for pos in 0..self.small_cache.len() {
            self.small_cache[pos] = b;
            b = self.byte();
            if Scanner::is_space(b) {
                return String::from_utf8_lossy(&self.small_cache[0..(pos + 1)])
                    .parse()
                    .unwrap();
            }
        }

        let mut v = self.small_cache.clone();
        while !Scanner::is_space(b) {
            v.push(b);
            b = self.byte();
        }
        return String::from_utf8_lossy(&v).parse().unwrap();
    }
}

#[allow(unused_macros)]
macro_rules! input {
    (source = $s:expr, $($r:tt)*) => {
        let mut iter = $s.split_whitespace();
        let mut next = || { iter.next().unwrap() };
        input_inner!{next, $($r)*}
    };
    ($($r:tt)*) => {
        let stdin = std::io::stdin();
        let mut bytes = std::io::Read::bytes(std::io::BufReader::new(stdin.lock()));
        let mut next = move || -> String{
            bytes
                .by_ref()
                .map(|r|r.unwrap() as char)
                .skip_while(|c|c.is_whitespace())
                .take_while(|c|!c.is_whitespace())
                .collect()
        };
        input_inner!{next, $($r)*}
    };
}

#[allow(unused_macros)]
macro_rules! input_inner {
    ($next:expr) => {};
    ($next:expr, ) => {};

    ($next:expr, $var:ident : $t:tt $($r:tt)*) => {
        let $var = read_value!($next, $t);
        input_inner!{$next $($r)*}
    };
}

#[allow(unused_macros)]
macro_rules! read_value {
    ($next:expr, ( $($t:tt),* )) => {
        ( $(read_value!($next, $t)),* )
    };

    ($next:expr, [ $t:tt ; $len:expr ]) => {
        (0..$len).map(|_| read_value!($next, $t)).collect::<Vec<_>>()
    };

    ($next:expr, chars) => {
        read_value!($next, String).chars().collect::<Vec<char>>()
    };

    ($next:expr, bytes) => {
        read_value!($next, String).into_bytes()
    };

    ($next:expr, usize1) => {
        read_value!($next, usize) - 1
    };

    ($next:expr, $t:ty) => {
        $next().parse::<$t>().expect("Parse error")
    };
}

