use std::mem::drop;

fn main() {
    read!(n = usize, len = i64, dur = i64);
    let dur = (dur % len) * 2;
    let len = len*2;
    dbg!((dur, len));
    let mut ls: Vec<(usize, i64)> = Vec::new();
    let mut rs: Vec<(usize, i64)> = Vec::new();
    let mut xs: Vec<(u8, i64)> = Vec::new();
    let mut i = 0;
    readx_loop!(|x = i64, w = u8| {
        xs.push((w, 2*x));
        if w == 1 {
            ls.push((i, 2*x - len));
            ls.push((i, 2*x - 2*len));
        } else {
            rs.push((i, 2*x));
            rs.push((i, 2*x + len));
        }
        i += 1;
    });
    drop(i);
    ls.sort_by_key(|&(_, x)| x);
    rs.sort_desc_by_key(|&(_, x)| x);
    dbg!(&xs);
    dbg!((&ls, &rs));
    let origin: (usize, i64) = ls.last().map_or_else(|| *rs.last().unwrap(), |llast| *llast);

    let mut is_l = true;
    let to_i = if ls.is_empty() || rs.is_empty() { origin.0 } else {
        let mut l = ls.pop().unwrap();
        let mut r = rs.pop().unwrap();
        loop {
            let next_t = (r.1 - l.1) / 2;
            if next_t >= dur {
                break;
            }
            if is_l {
                is_l = false;
                match ls.pop() {
                    None => break,
                    Some(new_l) => l = new_l
                }
            } else {
                is_l = true;
                match rs.pop() {
                    None => break,
                    Some(new_r) => r = new_r
                }
            }
        }
        if is_l { l.0 } else { r.0 }
    };
    dbg!((origin, to_i));
    let to_x = if xs[to_i].0 == 1 { (xs[to_i].1 + dur) % len } else { (xs[to_i].1 + len - dur) % len };
    let mut moved_xs: Vec<i64> = xs.iter().map(|&(w, x)| {
        if w == 1 { (x + dur) % len } else { (x + len - dur) % len }
    }).collect();
    moved_xs.sort();
    dbg!(&moved_xs);
    let moved_to_i = if is_l {
        moved_xs.iter().enumerate().find(|&(_, &x)| x == to_x).unwrap().0
    } else {
        moved_xs.iter().enumerate().rev().find(|&(_, &x)| x == to_x).unwrap().0
    };

    let mut ans = vec![0; n];
    for i in 0..n {
        ans[(origin.0 + i) % n] = moved_xs[(moved_to_i + i) % n];
    }
    for x in ans {
        println!("{}", x/2);
    }
}

use std::io::{stdin, Read};

macro_rules! parse {
    ($iter: ident) => {
        $iter.next().unwrap().parse().unwrap()
    };
    ($iter: ident,2) => {
        (parse!($iter), parse!($iter))
    };
    ($iter: ident,3) => {
        (parse!($iter), parse!($iter), parse!($iter))
    };
    ($iter: ident,4) => {
        (parse!($iter), parse!($iter), parse!($iter), parse!($iter))
    };
    ($iter: ident, $n: ident) => {
        $iter.take($n).map(|e| e.parse().unwrap()).collect();
    };
}

fn main() {
    let mut s = String::new();
    stdin().read_to_string(&mut s).unwrap();
    let mut iter = s.split_whitespace();
    let (n, l, t): (usize, isize, isize) = parse!(iter, 3);
    let mut xs = vec![0; n];
    let mut ys = vec![(0, 0); n];
    for i in 0..n {
        let (x, w): (isize, isize) = parse!(iter, 2);
        let w = 3 - 2 * w;
        ys[i] = (x, w);
        let x = (x + t * w) % l;
        let x = if x >= 0 { x } else { x + l };
        xs[i] = x;
    }
    let (x, w) = ys[0];
    let mut num = 0;
    for i in 1..n {
        let (y, v) = ys[i];
        if v == w {
            continue;
        }
        let d = y - x;
        if w > 0 {
            let d = if d >= 0 { d } else { d + l };
            let mut c = 2 * t / l;
            if (2 * t) % l >= d {
                c += 1;
            }
            num += c;
        } else {
            let d = -d;
            let d = if d >= 0 { d } else { d + l };
            let mut c = -(2 * t / l);
            if (2 * t) % l >= d {
                c -= 1;
            }
            num += c;
        }
    }
    num %= n as isize;
    if num < 0 {
        num += n as isize;
    }
    xs.sort();
    for i in (num as usize)..n {
        println!("{}", xs[i]);
    }
    for i in 0..(num as usize) {
        println!("{}", xs[i]);
    }
}

use std::fmt::Debug;
use std::io;
use std::io::{Read, Stdin};
use std::str;
use std::str::FromStr;
use std::usize;
use std::cmp;
use std::collections::vec_deque::VecDeque;
use std::i64::MAX;

fn main() {
    let mut sc = Scanner::new();
    let n = sc.parse::<usize>();
    let l = sc.parse::<i64>();
    let t = sc.parse::<i64>();

    let mut x: Vec<i64> = vec![0; n];
    let mut w: Vec<usize> = vec![0; n];

    for i in 0..n {
        x[i] = sc.parse::<i64>();
        w[i] = sc.parse::<usize>();
    }

    let cross_count = (0..n)
        .map(|i| {
            let w0 = w[0];
            let wi = w[i];
            if w0 == wi {
                return 0;
            }

            let interval;
            if w0 == 1 {
                interval = x[i] - x[0];
            } else {
                interval = x[0] + l - x[i];
            }

            if interval > t * 2 {
                return 0;
            }

            let time = t * 2 - interval;
            let count;
            if time % l == 0 && w[0] == 1 {
                count = time / l;
            } else {
                count = time / l + 1;
            }
            return count;
        })
        .collect::<Vec<i64>>();

    let count_sum: i64 = cross_count.iter().sum::<i64>() % (n as i64);
    let position;
    let num;
    if w[0] == 1 {
        position = (x[0] + t) % l;
        num = count_sum;

    } else {
        position = (x[0] - (t % l) + l) % l;
        num = (n as i64) - count_sum;
    }

    let mut positions: Vec<i64> = (0..n)
        .map(|i| {
            let p;
            if w[i] == 1 {
                p = (x[i] + t) % l;
            } else {
                p = (x[i] - (t % l) + l) % l;
            }
            return p;
        })
        .collect::<Vec<i64>>();
    positions.sort();

    let a = positions.binary_search(&position).unwrap();

    let ans = (0..n)
        .map(|idx| {
                 let i = (idx + n - ((num as usize) % n)) % n;
                 let p = (a + i as usize) % n;
                 return positions[p];
             })
        .collect::<Vec<i64>>();

    for a in &ans {
        println!("{}", a);
    }

}

struct Scanner {
    stdin: Stdin,
    buf: Vec<u8>,
}

impl Scanner {
    fn new() -> Scanner {
        Scanner {
            stdin: io::stdin(),
            buf: Vec::with_capacity(256),
        }
    }

    fn parse<T: FromStr>(&mut self) -> T
        where <T as FromStr>::Err: Debug
    {
        self.buf.clear();
        let mut it = self.stdin.lock().bytes();
        let mut c = it.next().unwrap().unwrap();
        while c == ' ' as u8 || c == '\n' as u8 {
            c = it.next().unwrap().unwrap();
        }
        while !(c == ' ' as u8 || c == '\n' as u8) {
            self.buf.push(c);
            c = it.next().unwrap().unwrap();
        }
        str::from_utf8(&self.buf).unwrap().parse::<T>().unwrap()
    }
}

use std::fmt;
use std::io::stdin;
use std::io::BufRead;
use std::str;
use std::str::FromStr;

fn main() {
	let stdin = stdin();
	let mut scan = InputScanner::new(stdin.lock(),256);

	let n:usize = scan.next();
	let l:i64 = scan.next();
	let t:i64 = scan.next();

	let mut xw:Vec<(usize,usize,bool)> = Vec::with_capacity(n);
	let mut lx:Vec<(usize,usize)> = Vec::with_capacity(n);
	let mut rx:Vec<(usize,usize)> = Vec::with_capacity(n);

	for i in 0..n {
		let x:usize = scan.next();
		let w:char = scan.next::<String>().chars().collect::<Vec<char>>()[0];

		if w == '1' {
			rx.push((i,x));
			xw.push((i,x,true));
		} else {
			lx.push((i,x));
			xw.push((i,x,false));
		}
	}

	xw.sort_by(|a,b| a.1.cmp(&b.1));

	let mut count:i64 = 0;

	for &x in xw.iter().skip(1) {
		if x.2 {
			count -= (t + x.1 as i64) / l;
		} else {
			count += (t - x.1 as i64 + l) / l;
		}
	}

	let offset = (count % n as i64 + n as i64) as usize;

	let n = n as usize;
	let l = l as usize;
	let t = t as usize;
	let mut all = rx.into_iter().map(|(i,x)|(i,(x+(t%l))%l)).collect::<Vec<(usize,usize)>>();
	all.append(&mut lx.into_iter().map(|(i,x)|(i,(l+x-(t%l))%l)).collect::<Vec<(usize,usize)>>());

	all.sort_by(|a,b| a.1.cmp(&b.1));

	let mut r = (0..n).map(|_| 0).collect::<Vec<usize>>();

	for i in 0..n {
		r[(i+offset)%n] = all[i].1;
	}

	println!("{}",r.into_iter().map(|x| format!("{}",x)).collect::<Vec<String>>().join("\n"));
}
struct InputScanner<R: BufRead> {
	reader: R,
	buf: Vec<u8>, // Should never be empty
	pos: usize,   // Should never be out of bounds as long as the input ends with '\n'
}
impl<R: BufRead> InputScanner<R> {
	fn new(reader: R, capacity: usize) -> Self {
		InputScanner {
			reader: reader,
			buf: Vec::with_capacity(capacity),
			pos: 0,
		}
	}

	#[inline]
	fn next<T: FromStr>(&mut self) -> T
	where
		T::Err: fmt::Debug,
	{
		if self.buf.is_empty() {
			self._read_next_line();
		}
		let mut start = None;
		loop {
			match (self.buf[self.pos], start.is_some()) {
				(b' ', true) | (b'\n', true) | (b'\r', true) => break,
				(_, true) | (b' ', false) => self.pos += 1,
				(b'\n', false) | (b'\r', false) => self._read_next_line(),
				(_, false) => start = Some(self.pos),
			}
		}
		let target = &self.buf[start.unwrap()..self.pos];
		unsafe { str::from_utf8_unchecked(target) }.parse().unwrap()
	}

	#[inline]
	fn _read_next_line(&mut self) {
		self.pos = 0;
		self.buf.clear();
		if self.reader.read_until(b'\n', &mut self.buf).unwrap() == 0 {
			panic!("Reached EOF");
		}
	}
}

use std::io::{stdin, Read};

macro_rules! parse {
    ($iter: ident) => {
        $iter.next().unwrap().parse().unwrap()
    };
    ($iter: ident,2) => {
        (parse!($iter), parse!($iter))
    };
    ($iter: ident,3) => {
        (parse!($iter), parse!($iter), parse!($iter))
    };
    ($iter: ident,4) => {
        (parse!($iter), parse!($iter), parse!($iter), parse!($iter))
    };
    ($iter: ident, $n: ident) => {
        $iter.take($n).map(|e| e.parse().unwrap()).collect();
    };
}

fn main() {
    let mut s = String::new();
    stdin().read_to_string(&mut s).unwrap();
    let mut iter = s.split_whitespace();
    let (n, l, t): (usize, isize, isize) = parse!(iter, 3);
    let mut xs = vec![0; n];
    let mut ys = vec![(0, 0); n];
    for i in 0..n {
        let (x, w): (isize, isize) = parse!(iter, 2);
        let w = 3 - 2 * w;
        ys[i] = (x, w);
        let x = (x + t * w) % l;
        let x = if x >= 0 { x } else { x + l };
        xs[i] = x;
    }
    let (x, w) = ys[0];
    let mut num = 0;
    for i in 1..n {
        let (y, v) = ys[i];
        if v == w {
            continue;
        }
        let d = y - x;
        let d = if d >= 0 { d } else { d + l };
        if w > 0 {
            let c = (2 * t - d) / l + 1;
            num += c;
        } else {
            let c = (2 * t + d) / l;
            num -= c;
        }
    }
    num %= n as isize;
    if num < 0 {
        num += n as isize;
    }
    xs.sort();
    for i in (num as usize)..n {
        println!("{}", xs[i]);
    }
    for i in 0..(num as usize) {
        println!("{}", xs[i]);
    }
}

