fn main() {
    input!{
        n: usize,
        l: usize,
        t: usize,
        v: [(usize, usize); n]
    }
    let mut id = 0;
    for i in 1..n {
        if v[0].1 == v[i].1 {
            continue;
        }
        if v[0].1 == 1 {
            let m = (2 * t + v[0].0 + l - v[i].0 - 1) / l;
            id = (id + m) % n;
        } else {
            let m = (2 * t + v[i].0 - v[0].0) / l;
            id = (id + n - m % n) % n;
        }
    }
    let mut ps = vec![0; n];
    for i in 0..n {
        if v[i].1 == 1 {
            ps[i] = (v[i].0 + t) % l;
        } else {
            ps[i] = (v[i].0 + l - t % l) % l;
        }
    }
    ps.sort();
    let mut j = 0;
    let p0 = if v[0].1 == 1 {
        (v[0].0 + t) % l
    } else {
        (v[0].0 + l - t % l) % l
    };
    while ps[j] != p0 {
        j += 1;
    }
    let mut ans = vec![0; n];
    for i in 0..n {
        ans[(i + id) % n] = ps[(j + i) % n];
    }
    for &a in &ans {
        println!("{}", a);
    }
}

use std::cmp::Ordering;
use std::fmt::Debug;
#[allow(unused_imports)]
use std::fs::File;
#[allow(unused_imports)]
use std::io::{stdin, stdout, BufReader, BufWriter, Read, Write};
use std::str::FromStr;

pub fn start<R: Read, W: Write>(input: R, output: &mut W) {
    let mut scanner = Scanner::new(input.bytes().map(Result::unwrap));
    let n = scanner.next_value::<isize>();
    let l = scanner.next_value::<isize>(); // 長さ l <= 10^9
    let t = scanner.next_value::<isize>(); // 時間 t <= 10^9
    let xw = scanner.next_2darray::<isize>(2, n as usize); // x = position,  w == 1 増, w == 2 減

    let mut results = Vec::new(); // 現在位置のリストを作成
    let mut shift = 0; // ゼロ点を通過した蟻の数
    for x in xw {
        if x[1] == 1 {
            let mut r = x[0] + t;
            while r >= l {
                r -= l;
                shift -= 1;
            }
            results.push(r);
        } else {
            let mut r = x[0] - t;
            while r < 0 {
                r += l;
                shift += 1;
            }
            results.push(r);
        }
    }
    while shift < 0 {
        shift += n;
    }
    while shift >= n {
        shift -= n;
    }
    for i in shift..n {
        write!(output, "{}\n", results[i as usize]).unwrap();
    }
    for i in 0..(shift as usize) {
        write!(output, "{}\n", results[i]).unwrap();
    }
}

