fn main() {
    input!{
        n: usize,
        l: usize,
        t: usize,
        v: [(usize, usize); n]
    }
    let mut id = 0;
    for i in 1..n {
        if v[0].1 == v[i].1 {
            continue;
        }
        if v[0].1 == 1 {
            let m = (2 * t + v[0].0 + l - v[i].0) / l;
            id = (id + m) % n;
        } else {
            let m = (2 * t + v[i].0 - v[0].0) / l;
            id = (id + (n - 1) * m) % n;
        }
    }
    let mut ans = vec![0; n];
    for i in 0..n {
        if v[i].1 == 1 {
            ans[(i + id) % n] = (v[i].0 + t) % l;
        } else {
            ans[(i + id) % n] = (v[i].0 + l - t % l) % l;
        }
    }
    for &a in &ans {
        println!("{}", a);
    }
}

