		d += if (lx[li].1 + l) % l - d == 0 {
			l
		} else {
			(lx[li].1 + l) % l - d
		};

		if d > t % l {
			break;
		}

		count += 1;
		li += 1;
		li = li % lx.len();
	}

	let offset = count;

