use std::mem::drop;

fn main() {
    read!(n = usize, len = i32, dur = i32);
    let dur = (dur % len) * 2;
    let len = len*2;
    dbg!((dur, len));
    let mut ls: Vec<(usize, i32)> = Vec::new();
    let mut rs: Vec<(usize, i32)> = Vec::new();
    let mut xs: Vec<(u8, i32)> = Vec::new();
    let mut i = 0;
    readx_loop!(|x = i32, w = u8| {
        xs.push((w, 2*x));
        if w == 1 {
            ls.push((i, 2*x - len));
        } else {
            rs.push((i, 2*x));
        }
        i += 1;
    });
    drop(i);
    ls.sort_by_key(|&(_, x)| x);
    rs.sort_desc_by_key(|&(_, x)| x);
    dbg!(&xs);
    dbg!((&ls, &rs));
    let origin: (usize, i32) = ls.last().map_or(*rs.last().unwrap(), |llast| *llast);

    let mut is_l = true;
    let to_i = if ls.is_empty() || rs.is_empty() { origin.0 } else {
        let mut l = ls.pop().unwrap();
        let mut r = rs.pop().unwrap();
        loop {
            let next_t = (r.1 - l.1) / 2;
            if next_t >= dur {
                break;
            }
            if is_l {
                is_l = false;
                match ls.pop() {
                    None => break,
                    Some(new_l) => l = new_l
                }
            } else {
                is_l = true;
                match rs.pop() {
                    None => break,
                    Some(new_r) => r = new_r
                }
            }
        }
        if is_l { l.0 } else { r.0 }
    };
    dbg!((origin, to_i));
    let to_x = if xs[to_i].0 == 1 { (xs[to_i].1 + dur) % len } else { (xs[to_i].1 + len - dur) % len };
    let mut moved_xs: Vec<i32> = xs.iter().map(|&(w, x)| {
        if w == 1 { (x + dur) % len } else { (x + len - dur) % len }
    }).collect();
    moved_xs.sort();
    dbg!(&moved_xs);
    let to_i = if is_l {
        moved_xs.iter().enumerate().find(|&(_, &x)| x == to_x).unwrap().0
    } else {
        moved_xs.iter().enumerate().rev().find(|&(_, &x)| x == to_x).unwrap().0
    };

    let mut ans = vec![0; n];
    for i in 0..n {
        ans[(origin.0 + i) % n] = moved_xs[(to_i + i) % n];
    }
    for x in ans {
        println!("{}", x/2);
    }
}

