	let l:usize = scan.next();
	let t:usize = scan.next();

	let mut lx = Vec::with_capacity(n);
	let mut rx = Vec::with_capacity(n);

	for i in 0..n {
		let x:usize = scan.next();
		let w:char = scan.next::<String>().chars().collect::<Vec<char>>()[0];

		if w == '1' {
			rx.push((i,x));
		} else {
			lx.push((i,x));
		}
	}

	rx.sort();
	lx.sort();

	let mut d:Vec<(usize,usize,usize)> = Vec::new();

	{
		let ll = lx.len();
		let rl = rx.len();

		let mut li = 0;
		let mut ri = 0;

		while li < ll && ri < rl  {
			while li < ll && rx[ri] >= lx[li] {
				li += 1;
			}

			if li == ll {
				break;
			}

			while ri < rl && rx[ri] < lx[li] {
				d.push((li,lx[li].1-rx[ri].1,ri));
				ri += 1;
			}
		}

		ri = rl-1;
		li = ll-1;

		loop {
			while li > 0 && rx[ri] <= lx[li] {
				li -= 1;
			}

			while rx[ri] > lx[li] {
				d.push((li,l-(rx[ri].1-lx[li].1),ri));
				if ri == 0 {
					break;
				} else {
					ri -= 1;
				}
			}

			if li == 0 && ri == 0 {
				break;
			}
		}
	}

	d.sort_by(|a,b| a.1.cmp(&b.1));

	for _ in 0..(t / l) {
		for d in &d {
			mem::swap(&mut lx[d.0].0,&mut rx[d.2].0);
		}
	}

	{
		let t = t % l;
		let mut dx = 0;

		for d in d {
			if dx > t * 2 {
				break;
			} else {
				mem::swap(&mut lx[d.0].0,&mut rx[d.2].0);
				dx += d.1;
			}
		}
	}

	let mut all = {
		let t = t % l;
		let mut rx = rx.iter().map(|&(i,x):&(usize,usize)| (i,(x+t)%l)).collect::<Vec<(usize,usize)>>();
		println!("{:?}",rx);
		let mut lx = lx.iter().map(|&(i,x):&(usize,usize)| (i,(x+(l-t))%l)).collect::<Vec<(usize,usize)>>();
		println!("{:?}",lx);
		rx.append(&mut lx);
		rx
	};

	all.sort_by(|a,b| a.0.cmp(&b.0));

	println!("{}",all.iter().map(|&(_,x)| format!("{}",x)).collect::<Vec<String>>().join("\n"));
}
struct InputScanner<R: BufRead> {
	reader: R,
	buf: Vec<u8>, // Should never be empty
	pos: usize,   // Should never be out of bounds as long as the input ends with '\n'
}
impl<R: BufRead> InputScanner<R> {
	fn new(reader: R, capacity: usize) -> Self {
		InputScanner {
			reader: reader,
			buf: Vec::with_capacity(capacity),
			pos: 0,
		}
	}

	#[inline]
	fn next<T: FromStr>(&mut self) -> T
	where
		T::Err: fmt::Debug,
	{
		if self.buf.is_empty() {
			self._read_next_line();
		}
		let mut start = None;
		loop {
			match (self.buf[self.pos], start.is_some()) {
				(b' ', true) | (b'\n', true) | (b'\r', true) => break,
				(_, true) | (b' ', false) => self.pos += 1,
				(b'\n', false) | (b'\r', false) => self._read_next_line(),
				(_, false) => start = Some(self.pos),
			}
		}
		let target = &self.buf[start.unwrap()..self.pos];
		unsafe { str::from_utf8_unchecked(target) }.parse().unwrap()
	}

	#[inline]
	fn _read_next_line(&mut self) {
		self.pos = 0;
		self.buf.clear();
		if self.reader.read_until(b'\n', &mut self.buf).unwrap() == 0 {
			panic!("Reached EOF");
		}
	}
}

#[allow(unused_macros)]
macro_rules! input {
    (source = $s:expr, $($r:tt)*) => {
        let mut iter = $s.split_whitespace();
        let mut next = || { iter.next().unwrap() };
        input_inner!{next, $($r)*}
    };
    ($($r:tt)*) => {
        let stdin = std::io::stdin();
        let mut bytes = std::io::Read::bytes(std::io::BufReader::new(stdin.lock()));
        let mut next = move || -> String{
            bytes
                .by_ref()
                .map(|r|r.unwrap() as char)
                .skip_while(|c|c.is_whitespace())
                .take_while(|c|!c.is_whitespace())
                .collect()
        };
        input_inner!{next, $($r)*}
    };
}

#[allow(unused_macros)]
macro_rules! input_inner {
    ($next:expr) => {};
    ($next:expr, ) => {};

    ($next:expr, $var:ident : $t:tt $($r:tt)*) => {
        let $var = read_value!($next, $t);
        input_inner!{$next $($r)*}
    };
}

#[allow(unused_macros)]
macro_rules! read_value {
    ($next:expr, ( $($t:tt),* )) => {
        ( $(read_value!($next, $t)),* )
    };

    ($next:expr, [ $t:tt ; $len:expr ]) => {
        (0..$len).map(|_| read_value!($next, $t)).collect::<Vec<_>>()
    };

    ($next:expr, chars) => {
        read_value!($next, String).chars().collect::<Vec<char>>()
    };

    ($next:expr, bytes) => {
        read_value!($next, String).into_bytes()
    };

    ($next:expr, usize1) => {
        read_value!($next, usize) - 1
    };

    ($next:expr, $t:ty) => {
        $next().parse::<$t>().expect("Parse error")
    };
}

