use std::io::*;
use std::str::FromStr;

fn main() {
    let (n, l, t): (usize, i64, i64) = (read(), read(), read());
    let xw: Vec<(i64, i64)> = (0..n).map(|_| (read::<i64>(), read::<i64>())).collect();
    let mut count: i64 = 0;
    let (x0, w0) = xw[0];
    for i in 1..n {
        let (x, w) = xw[i];
        if w0 != w {
            if w0 == 1 && 2 * t >= x - x0 {
                count += (2 * t - (x - x0)) / l + 1;
            } else if w0 == 2 && 2 * t >= l - (x - x0) {
                count += (2 * t - (l - (x - x0))) / l + 1;
            }
        }
    }

    let mut ans: Vec<i64> = vec![0; n];
    let mut cvalue: i64 = 0;
    for i in 0..n {
        let (x, w) = xw[i];
        ans[i] = (x + (t % l) * (if w == 1 { 1 } else { -1 }) + l) % l;
        if i == 0 {
            cvalue = ans[i];
        }
    }
    ans.sort();
    let mut start: usize = 0;
    for i in 0..n {
        if ans[i] == cvalue {
            if w0 == 1 {
                start = (i + n - count as usize % n) % n;
            } else {
                start = (i + count as usize % n) % n;
                break;
            }
        }
    }
    for i in 0..n {
        println!("{}", ans[(i + start) % n]);
    }
}

fn read<T: FromStr>() -> T {
    let stdin = stdin();
    let stdin = stdin.lock();
    let token: String = stdin
        .bytes()
        .map(|c| c.expect("failed to read char") as char)
        .skip_while(|c| c.is_whitespace())
        .take_while(|c| !c.is_whitespace())
        .collect();
    token.parse().ok().expect("failed to parse token")
}

#[allow(unused_macros)]
macro_rules! input {
    (source = $s:expr, $($r:tt)*) => {
        let mut iter = $s.split_whitespace();
        let mut next = || { iter.next().unwrap() };
        input_inner!{next, $($r)*}
    };
    ($($r:tt)*) => {
        let stdin = std::io::stdin();
        let mut bytes = std::io::Read::bytes(std::io::BufReader::new(stdin.lock()));
        let mut next = move || -> String{
            bytes
                .by_ref()
                .map(|r|r.unwrap() as char)
                .skip_while(|c|c.is_whitespace())
                .take_while(|c|!c.is_whitespace())
                .collect()
        };
        input_inner!{next, $($r)*}
    };
}

#[allow(unused_macros)]
macro_rules! input_inner {
    ($next:expr) => {};
    ($next:expr, ) => {};

    ($next:expr, $var:ident : $t:tt $($r:tt)*) => {
        let $var = read_value!($next, $t);
        input_inner!{$next $($r)*}
    };
}

#[allow(unused_macros)]
macro_rules! read_value {
    ($next:expr, ( $($t:tt),* )) => {
        ( $(read_value!($next, $t)),* )
    };

    ($next:expr, [ $t:tt ; $len:expr ]) => {
        (0..$len).map(|_| read_value!($next, $t)).collect::<Vec<_>>()
    };

    ($next:expr, chars) => {
        read_value!($next, String).chars().collect::<Vec<char>>()
    };

    ($next:expr, bytes) => {
        read_value!($next, String).into_bytes()
    };

    ($next:expr, usize1) => {
        read_value!($next, usize) - 1
    };

    ($next:expr, $t:ty) => {
        $next().parse::<$t>().expect("Parse error")
    };
}

