fn main() {
    let v = read_vec::<i64>();
    let (n, l, t) = (v[0] as usize, v[1], v[2] % v[1]);
    let mut xs = vec![];
    let mut ws = vec![];
    for _ in 0..n {
        let v = read_vec::<i64>();
        xs.push(v[0]);
        ws.push(v[1]);
    }
    let reversed = ws[0] == 2;
    if reversed {
        for i in 0..n {
            xs[i] = (l - xs[i]) % l;
            ws[i] = 3 - ws[i];
        }
    }

    let mut poses = vec![];
    for (&x, &w) in xs.iter().zip(ws.iter()) {
        if w == 1 {
            poses.push((x + t) % l);
        } else {
            poses.push((l + (x - t) % l) % l);
        }
    }
    poses.sort();

    let mut count = 0;
    for i in 1..n {
        let (x, w) = (xs[i], ws[i]);
        if w == 2 {
            count += (2 * t - (x - xs[0])) / l + 1;
        }
    }
    let count = count as usize % n;

    let zero_pos = (xs[0] + t) % l;
    let mut zero_idx = 0;
    for i in 0..n {
        if poses[i] == zero_pos {
            zero_idx = i;
            // break;
        }
    }
    let mut answers = vec![0; n];

    for i in 0..n {
        answers[i] = poses[(i + zero_idx + n - count) % n];
    }
    debug!(count, zero_idx);

    if reversed {
        for i in 0..n {
            answers[i] = (l - answers[i]) % l;
        }
        answers.reverse();
    }

    for ans in answers {
        println!("{}", ans);
    }
}

fn read<T: std::str::FromStr>() -> T {
    let mut s = String::new();
    std::io::stdin().read_line(&mut s).ok();
    s.trim().parse().ok().unwrap()
}

fn read_vec<T: std::str::FromStr>() -> Vec<T> {
    read::<String>()
        .split_whitespace()
        .map(|e| e.parse().ok().unwrap())
        .collect()
}

fn main() {
    let mut sc = Scanner::new();
    let n = sc.usize_read();
    let length: usize = sc.read();
    let time: usize = sc.read();
    let xw: Vec<(usize, bool)> = (0..n).map(|_| (sc.read(), sc.read::<i32>() == 1)).collect();

    let (first_pos, first_clock) = xw[0];
    let mut cross_count = 0;
    for &(pos, clock) in &xw[1..n] {
        if clock == first_clock {
            continue;
        }
        let initial_distance = if first_clock {
            pos - first_pos
        } else {
            length + first_pos - pos
        };
        if time * 2 < initial_distance {
            continue;
        }

        cross_count += (time * 2 - initial_distance + length - 1) / length;
    }

    let final_num = if first_clock {
        cross_count % n
    } else {
        (n - cross_count % n) % n
    };

    let final_pos = if first_clock {
        (first_pos + time) % length
    } else {
        (first_pos + length - time % length) % length
    };

    let mut final_states = xw.iter()
        .map(|&(pos, clock)| {
            if clock {
                (pos + time) % length
            } else {
                (pos + length - time % length) % length
            }
        })
        .collect::<Vec<_>>();
    final_states.sort();

    let mut final_i = 0;
    for i in 0..n {
        if final_states[i] == final_pos {
            if first_clock || final_states[i] != final_states[(i + 1) % n] {
                final_i = i;
            } else {
                final_i = i + 1;
            }
            break;
        }
    }

    let mut ans = vec![0; n];
    for i in 0..n {
        ans[(final_num + i) % n] = final_states[(final_i + i) % n];
    }

    for &a in &ans {
        println!("{}", a);
    }
}

struct Scanner {
    ptr: usize,
    length: usize,
    buf: Vec<u8>,
    small_cache: Vec<u8>,
}

#[allow(dead_code)]
impl Scanner {
    fn new() -> Scanner {
        Scanner {
            ptr: 0,
            length: 0,
            buf: vec![0; 1024],
            small_cache: vec![0; 1024],
        }
    }

    fn load(&mut self) {
        use std::io::Read;
        let mut s = std::io::stdin();
        self.length = s.read(&mut self.buf).unwrap();
    }

    fn byte(&mut self) -> u8 {
        if self.ptr >= self.length {
            self.ptr = 0;
            self.load();
            if self.length == 0 {
                self.buf[0] = b'\n';
                self.length = 1;
            }
        }

        self.ptr += 1;
        return self.buf[self.ptr - 1];
    }

    fn is_space(b: u8) -> bool {
        b == b'\n' || b == b'\r' || b == b'\t' || b == b' '
    }

    fn read_vec<T>(&mut self, n: usize) -> Vec<T>
    where
        T: std::str::FromStr,
        T::Err: std::fmt::Debug,
    {
        (0..n).map(|_| self.read()).collect()
    }

    fn usize_read(&mut self) -> usize {
        self.read()
    }

    fn read<T>(&mut self) -> T
    where
        T: std::str::FromStr,
        T::Err: std::fmt::Debug,
    {
        let mut b = self.byte();
        while Scanner::is_space(b) {
            b = self.byte();
        }

        for pos in 0..self.small_cache.len() {
            self.small_cache[pos] = b;
            b = self.byte();
            if Scanner::is_space(b) {
                return String::from_utf8_lossy(&self.small_cache[0..(pos + 1)])
                    .parse()
                    .unwrap();
            }
        }

        let mut v = self.small_cache.clone();
        while !Scanner::is_space(b) {
            v.push(b);
            b = self.byte();
        }
        return String::from_utf8_lossy(&v).parse().unwrap();
    }
}

