		let x:usize = scan.next();
		let w:char = scan.next::<String>().chars().collect::<Vec<char>>()[0];

		if w == '1' {
			rx.push((i,x));
			xw.push((i,x,true));
		} else {
			lx.push((i,x));
			xw.push((i,x,false));
		}
	}

	xw.sort_by(|a,b| a.1.cmp(&b.1));

	let mut count:i64 = 0;

	for &x in &xw {
		if x.2 {
			count -= (t + x.1 as i64) / l;
		} else {
			count += (t - (x.1 as i64 + 1) + l) / l;
		}
	}

	let offset = (count % n as i64 + n as i64) as usize;

	let n = n as usize;
	let l = l as usize;
	let t = t as usize;
	let mut all = rx.into_iter().map(|(i,x)|(i,(x+t)%l)).collect::<Vec<(usize,usize)>>();
	all.append(&mut lx.into_iter().map(|(i,x)|(i,(l as i64 +x as i64-t as i64) as usize %l)).collect::<Vec<(usize,usize)>>());

	all.sort_by(|a,b| a.0.cmp(&b.0));

	let mut r = (0..n).map(|_| 0).collect::<Vec<usize>>();

