use std::cmp::Ordering;
use std::fmt::Debug;
#[allow(unused_imports)]
use std::fs::File;
#[allow(unused_imports)]
use std::io::{stdin, stdout, BufReader, BufWriter, Read, Write};
use std::str::FromStr;

pub fn start<R: Read, W: Write>(input: R, output: &mut W) {
    let mut scanner = Scanner::new(input.bytes().map(Result::unwrap));
    let n = scanner.next_value::<isize>();
    let l = scanner.next_value::<isize>(); // 長さ l <= 10^9
    let t = scanner.next_value::<isize>(); // 時間 t <= 10^9
    let xw = scanner.next_2darray::<isize>(2, n as usize); // x = position,  w == 1 増, w == 2 減

    let mut seq = (0..n as usize).into_iter().collect::<Vec<_>>();
    seq.sort_by_key(|&x| xw[x][0] << 1 | xw[x][1] & 1);

    let mut results = Vec::new(); // 現在位置のリストを作成
    let mut shift = 0; // ゼロ点を通過した蟻の数
    for x in xw {
        if x[1] == 1 {
            let mut r = x[0] + t;
            while r >= l {
                r -= l;
                shift += 1;
            }
            results.push(r);
        } else {
            let mut r = x[0] - t;
            while r < 0 {
                r += l;
                shift -= 1;
            }
            results.push(r);
        }
    }
    results.sort();
    while shift < 0 {
        shift += n;
    }
    while shift >= n {
        shift -= n;
    }
    for i in shift..n {
        write!(output, "{}\n", results[seq[i as usize]]).unwrap();
    }
    for i in 0..(shift as usize) {
        write!(output, "{}\n", results[seq[i]]).unwrap();
    }
}

