fn main() {
    let v = read_vec::<i64>();
    let (n, l, t) = (v[0] as usize, v[1], v[2]);
    let mut xs = vec![];
    let mut ws = vec![];
    for _ in 0..n {
        let v = read_vec::<i64>();
        xs.push(v[0]);
        ws.push(v[1]);
    }
    let reversed = ws[0] == 2;
    if reversed {
        for i in 0..n {
            xs[i] = (l - xs[i]) % l;
            ws[i] = 3 - ws[i];
        }
    }

    let mut poses = vec![];
    for (&x, &w) in xs.iter().zip(ws.iter()) {
        if w == 1 {
            poses.push((x + t) % l);
        } else {
            poses.push((l + (x - t) % l) % l);
        }
    }
    poses.sort();
    // debug!(poses);

    let t = t % l;
    let mut count = 0;

    for i in 0..n {
        if ws[i] == 1 {
            continue;
        }
        if xs[0] + 2 * t > xs[i] {
            count += 1;
        }
    }
    for i in 0..n {
        if ws[i] == 1 {
            continue;
        }
        if xs[0] + 2 * t > xs[i] + l {
            count += 1;
        }
    }

    let zero_pos = (xs[0] + t) % l;
    let mut zero_idx = 0;
    for i in 0..n {
        if poses[i] == zero_pos {
            zero_idx = i;
            break;
        }
    }
    let mut answers = vec![0; n];

    for i in 0..n {
        answers[(i + count) % n] = poses[(i + zero_idx) % n];
    }

    if reversed {
        for i in 0..n {
            answers[i] = l - answers[i];
        }
        answers.reverse();
    }

    for ans in answers {
        println!("{}", ans);
    }
}

