fn main() {
    let nlt = readn::<usize>(" ");
    let n = nlt[0];
    let l = nlt[1];
    let t = nlt[2];
    let mut x = Vec::with_capacity(n);
    let mut w = Vec::with_capacity(n);
    let mut pos = Vec::with_capacity(n);

    for _ in 0..n {
        let xw = readn::<usize>(" ");
        x.push(xw[0]);
