    let mut xs = vec![0; n];
    let mut ys = vec![(0, 0); n];
    for i in 0..n {
        let (x, w): (isize, isize) = parse!(iter, 2);
        let w = 3 - 2 * w;
        ys[i] = (x, w);
        let x = (x + t * w) % l;
        let x = if x >= 0 { x } else { x + l };
