    let mut num = 0;
    for i in 1..n {
        let (y, v) = ys[i];
        if w == v {
            continue;
        }
        let d = y - x;
        let d = if d >= 0 { d } else { d + l };
        num += (2 * t * w) / l;
        let r = (2 * t * w) % l;
        let r = if r >= 0 { r } else { r + l };
        if w > 0 && r >= d || w < 0 && r <= d {
            num += w;
        }
    }
    num %= n as isize;
    if num < 0 {
        num += n as isize;
    }
    xs.sort();
    for i in (num as usize)..n {
        println!("{}", xs[i]);
    }
    for i in 0..(num as usize) {
        println!("{}", xs[i]);
    }
}

