    let T: i64 = T;
    let mut aa: Vec<(i64, i64)> = aa;

    let mut bb: Vec<i64> = vec![];
    let mut p = 0;

    for (x, w) in aa {
        let xt = if w == 1 {
            x + T
        } else {
            x - T
        };
        p += xt / L;
        bb.push(xt % L);
    }
    debug!(p, bb);

    bb.sort();
    p %= N as i64;

    for i in 0..N {
        let x = bb[(i + p as usize) % N];
        println!("{}", (L + x) % L);
    }
}
